        PreviewOnly,
        NonPreviewOnly
    }

    private enum PipeAreaFluidResolution
    {
        NoFluidConstraint,
        Resolved,
        UnresolvedFluidEndpoint
    }

    private struct RectGridPlacementCell
    {
        public InputOutputModule.RectGridBlockPlacement placement;
        public InputOutputModule.RectGridBlockType blockType;
        public Vector2Int localOffset;
        public Vector2Int rotatedOffset;
        public Vector2Int coordinate;

        public RectGridPlacementCell(
            InputOutputModule.RectGridBlockPlacement placement,
            InputOutputModule.RectGridBlockType blockType,
            Vector2Int localOffset,
            Vector2Int rotatedOffset,
            Vector2Int coordinate)
        {
            this.placement = placement;
            this.blockType = blockType;
            this.localOffset = localOffset;
            this.rotatedOffset = rotatedOffset;
            this.coordinate = coordinate;
        }
    }

    private void Awake()
    {
        ResolveInstallButtons();
        BindInstallButtons();
        SetInstallButtonVisible(false);
        RefreshMapEditButtonState();
    }

    private void OnEnable()
    {
        ResolveInstallButtons();
        BindInstallButtons();
        RefreshInstallButton();
        RefreshMapEditButtonState();
    }

    private void Update()
    {
        bool profileRuntime = MapObjectTickProfiler.IsEnabled;
        long startTimestamp = profileRuntime ? MapObjectTickProfiler.BeginSample() : 0L;
        try
        {
            ResolveInstallButtons();
            RefreshInstallButton();
            RefreshMapEditButtonState();
            if (TryHandleModeCancelInput())
            {
                return;
            }

            if (!IsInstallationModeActive())
            {
                if (mapEditModeActive)
                {
                    UpdateMapEditSelectionInput();
                }

                UpdateInstallGrid();
                return;
            }

            if (waitForPointerReleaseAfterPreviewSpawn)
            {
                if (IsPrimaryPointerHeld())
                {
                    UpdateInstallGrid();
                    return;
                }

                waitForPointerReleaseAfterPreviewSpawn = false;
            }

            if (IsRailloadInstallationModeActive())
            {
                if (railloadInstallationController.Tick())
                {
                    ClearInstallPreview();
                }

                UpdateInstallGrid();
                return;
            }

            UpdateUndergroundPipeCandidatePreview();
            UpdateInstallPreviewPointerInput();
            UpdateInstallGrid();
        }
        finally
        {
            if (profileRuntime)
            {
                MapObjectTickProfiler.EndNamedSample(
                    "Runtime",
                    "InstallationPlacementController",
                    "Installation Placement Update",
                    startTimestamp);
            }
        }
    }

    private void LateUpdate()
    {
        bool profileRuntime = MapObjectTickProfiler.IsEnabled;
        long startTimestamp = profileRuntime ? MapObjectTickProfiler.BeginSample() : 0L;
        try
        {
            RefreshInstallPreviewVisualsAfterLateTransformChanges();
            if ((installGridDirty || installGridPreviewDirty) && ShouldUpdateInstallGridLate())
            {
                UpdateInstallGrid();
            }
        }
        finally
        {
            if (profileRuntime)
            {
                MapObjectTickProfiler.EndNamedSample(
                    "Runtime",
                    "InstallationPlacementController",
                    "Installation Placement LateUpdate",
                    startTimestamp);
            }
        }
    }

    private bool ShouldUpdateInstallGridLate()
    {
        return IsInstallGridModeActive()
               || (GameManager.Instance != null && GameManager.Instance.DebugConveyorInstallGridEnds);
    }

    private void RefreshInstallPreviewVisualsAfterLateTransformChanges()
    {
        MapObject preview = activeInstallPreview;
        if (preview == null || (!IsInstallationModeActive() && !mapEditModeActive))
        {
            ResetInstallPreviewVisualSyncState();
            return;
        }

        RefreshHandcartInstallPreviewConnectionPoses();
        bool hasAnchor = TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate);
        int quarterTurns = GetPreviewAreaQuarterTurns(preview);
        if (IsInstallPreviewVisualSyncCurrent(preview, hasAnchor, anchorCoordinate, quarterTurns))
        {
            return;
        }

        if (hasAnchor)
        {
            RefreshInstallPreviewAreaMarkers(preview);
            RefreshPreviewRangeVisualsIfNeeded(preview);
            RefreshUtilityPolePreviewWire(preview);
        }
        else
        {
            ClearInputOutputMarkers(preview);
            UnregisterUtilityPolePreviewWire(preview);
            RememberInstallPreviewVisualSyncState(preview, false, Vector2Int.zero, quarterTurns);
        }

        InvalidateInstallGridPreview();
    }

    private bool IsInstallPreviewVisualSyncCurrent(
        MapObject preview,
        bool hasAnchor,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        if (preview == null
            || installPreviewVisualSyncPreview != preview
            || installPreviewVisualSyncHasAnchor != hasAnchor
            || installPreviewVisualSyncQuarterTurns != quarterTurns)
        {
            return false;
        }

        if (hasAnchor && installPreviewVisualSyncAnchorCoordinate != anchorCoordinate)
        {
            return false;
        }

        Transform previewTransform = preview.transform;
        return (previewTransform.position - installPreviewVisualSyncPosition).sqrMagnitude <= InstallPreviewVisualSyncPositionEpsilonSqr
               && Mathf.Abs(Quaternion.Dot(previewTransform.rotation, installPreviewVisualSyncRotation)) >= PlacementRotationExactDotThreshold;
    }

    private void RememberInstallPreviewVisualSyncState(
        MapObject preview,
        bool hasAnchor,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        if (preview == null || preview != activeInstallPreview)
        {
            return;
        }

        installPreviewVisualSyncPreview = preview;
        installPreviewVisualSyncHasAnchor = hasAnchor;
        installPreviewVisualSyncAnchorCoordinate = anchorCoordinate;
        installPreviewVisualSyncQuarterTurns = quarterTurns;
        installPreviewVisualSyncPosition = preview.transform.position;
        installPreviewVisualSyncRotation = preview.transform.rotation;
    }

    private void ResetInstallPreviewVisualSyncState()
    {
        installPreviewVisualSyncPreview = null;
        installPreviewVisualSyncHasAnchor = false;
        installPreviewVisualSyncAnchorCoordinate = Vector2Int.zero;
        installPreviewVisualSyncQuarterTurns = 0;
        installPreviewVisualSyncPosition = Vector3.zero;
        installPreviewVisualSyncRotation = Quaternion.identity;
    }

    private bool TryHandleModeCancelInput()
    {
        if (GameManager.TextInputFocused || !Input.GetKeyDown(KeyCode.Escape))
        {
            return false;
        }

        if (!IsEditingInstallation() && !IsInstallationModeActive() && !mapEditModeActive)
        {
            return false;
        }

        HandleInstallCancelClicked();
        return true;
    }

    private void OnDisable()
    {
        WorkableObject.SetInstallOrEditWorkableSelectionRangeVisualsRequested(false);
        UtilityPole.SetInstallOrEditUtilityPoleSelectionRangeVisualsRequested(false);
        UtilityPole.ClearBlueprintPreviews();
        ClearEditableInstallationSelection();
        mapEditModeActive = false;
        GameManager.Instance?.SetMapEditActive(false);
        FinalizePackedInstallationHistory();
        if (IsEditingInstallation())
        {
            CancelInstallationEdit();
        }
        else
        {
            ClearInstallPreview();
        }
        SetInstallButtonVisible(false);
        RefreshMapEditButtonState();
        ReleaseInstallGridResources();
    }

    private void OnDestroy()
    {
        WorkableObject.SetInstallOrEditWorkableSelectionRangeVisualsRequested(false);
        UtilityPole.SetInstallOrEditUtilityPoleSelectionRangeVisualsRequested(false);
        UtilityPole.ClearBlueprintPreviews();
        UnbindInstallButtons();
        mapEditModeActive = false;
        GameManager.Instance?.SetMapEditActive(false);
        FinalizePackedInstallationHistory();
        if (IsEditingInstallation())
        {
            CancelInstallationEdit();
        }
        else
        {
            ClearInstallPreview();
        }
        ReleaseInstallGridResources();
    }

    public void SetInstallButtons(Button button, Button cancelButton, Button rotationButton, Button completeButton)
    {
        bool isSameBinding = installButton == button
                             && installCancelButton == cancelButton
                             && installRotationButton == rotationButton
                             && installCompleteButton == completeButton
                             && installButton != null;
        if (isSameBinding)
        {
            BindInstallButtons();
            RefreshInstallButton();
            return;
        }

        UnbindInstallButtons();
        installButton = button;
        installCancelButton = cancelButton;
        installRotationButton = rotationButton;
        installCompleteButton = completeButton;
        installButtonHierarchySearchComplete = false;
        ResolveInstallButtons();
        BindInstallButtons();
        RefreshInstallButton();
    }

    public void SetInstallButton(Button button)
    {
        SetInstallButtons(button, installCancelButton, installRotationButton, installCompleteButton);
    }

    public void SetMapEditButtons(Button button, Button cancelButton, Button rotationButton, Button completeButton, Button packButton, Button undoButton)
    {
        bool isSameBinding = mapEditButton == button
                             && mapEditCancelButton == cancelButton
                             && mapEditRotationButton == rotationButton
                             && mapEditCompleteButton == completeButton
                             && mapEditPackButton == packButton
                             && mapEditUndoButton == undoButton
                             && mapEditButton != null;
        if (isSameBinding)
        {
            BindButton(mapEditButton, HandleMapEditButtonClicked);
            BindButton(mapEditCancelButton, HandleInstallCancelClicked);
            BindButton(mapEditRotationButton, HandleInstallRotationClicked);
            UnbindButton(mapEditCompleteButton, HandleInstallCompleteClicked);
            BindButton(mapEditCompleteButton, HandleMapEditCompleteClicked);
            BindButton(mapEditPackButton, HandleMapEditPackClicked);
            BindButton(mapEditUndoButton, HandleMapEditUndoClicked);
            RefreshMapEditButtonState();
            return;
        }

        UnbindButton(mapEditButton, HandleMapEditButtonClicked);
        UnbindButton(mapEditCancelButton, HandleInstallCancelClicked);
        UnbindButton(mapEditRotationButton, HandleInstallRotationClicked);
        UnbindButton(mapEditCompleteButton, HandleMapEditCompleteClicked);
        UnbindButton(mapEditCompleteButton, HandleInstallCompleteClicked);
        UnbindButton(mapEditPackButton, HandleMapEditPackClicked);
        UnbindButton(mapEditUndoButton, HandleMapEditUndoClicked);
        mapEditButton = button;
        mapEditCancelButton = cancelButton;
        mapEditRotationButton = rotationButton;
        mapEditCompleteButton = completeButton;
        mapEditPackButton = packButton;
        mapEditUndoButton = undoButton;
        installButtonHierarchySearchComplete = false;
        ResolveInstallButtons();
        BindButton(mapEditButton, HandleMapEditButtonClicked);
        BindButton(mapEditCancelButton, HandleInstallCancelClicked);
        BindButton(mapEditRotationButton, HandleInstallRotationClicked);
        UnbindButton(mapEditCompleteButton, HandleInstallCompleteClicked);
        BindButton(mapEditCompleteButton, HandleMapEditCompleteClicked);
        BindButton(mapEditPackButton, HandleMapEditPackClicked);
        BindButton(mapEditUndoButton, HandleMapEditUndoClicked);
        RefreshMapEditButtonState();
    }

    private void ResolveInstallButtons()
    {
        PlayerHUD playerHud = GetComponent<PlayerHUD>();
        if (installButton == null && playerHud != null && playerHud.InstallButton != null)
        {
            installButton = playerHud.InstallButton;
        }

        if (playerHud != null)
        {
            if (installCancelButton == null)
            {
                installCancelButton = playerHud.InstallCancelButton;
            }

            if (installRotationButton == null)
            {
                installRotationButton = playerHud.InstallRotationButton;
            }

            if (installCompleteButton == null)
            {
                installCompleteButton = playerHud.InstallCompleteButton;
            }

            if (mapEditButton == null)
            {
                mapEditButton = playerHud.MapEditButton;
            }

            if (mapEditCancelButton == null)
            {
                mapEditCancelButton = playerHud.MapEditCancelButton;
            }

            if (mapEditRotationButton == null)
            {
                mapEditRotationButton = playerHud.MapEditRotationButton;
            }

            if (mapEditCompleteButton == null)
            {
                mapEditCompleteButton = playerHud.MapEditCompleteButton;
            }
        }

        if (installButtonHierarchySearchComplete)
        {
            return;
        }

        Button[] buttons = GetComponentsInChildren<Button>(true);
        for (int i = 0; i < buttons.Length; i++)
        {
            Button candidate = buttons[i];
            if (candidate == null)
            {
                continue;
            }

            if (installButton == null && candidate.name == "InstallButton")
            {
                installButton = candidate;
                continue;
            }

            if (installCancelButton == null)
            {
                if ((playerHud != null && playerHud.InstallCancelButton == candidate) || candidate.name == "InstallCancelButton")
                {
                    installCancelButton = candidate;
                    continue;
                }
            }

            if (installRotationButton == null)
            {
                if ((playerHud != null && playerHud.InstallRotationButton == candidate)
                    || candidate.name == "RotateButton"
                    || candidate.name == "RotationButton"
                    || candidate.name == "InstallRotationButton")
                {
                    installRotationButton = candidate;
                    continue;
                }
            }

            if (installCompleteButton == null)
            {
                if ((playerHud != null && playerHud.InstallCompleteButton == candidate)
                    || candidate.name == "CompleteButton"
                    || candidate.name == "InstallCompleteButton")
                {
                    installCompleteButton = candidate;
                    continue;
                }
            }

            if (mapEditButton == null)
            {
                if ((playerHud != null && playerHud.MapEditButton == candidate) || candidate.name == "MapEditButton")
                {
                    mapEditButton = candidate;
                }
            }

            if (mapEditPackButton == null && (candidate.name == "PackButton" || candidate.name == "Pack"))
            {
                mapEditPackButton = candidate;
            }

            if (mapEditUndoButton == null && (candidate.name == "UnDoButton" || candidate.name == "UndoButton"))
            {
                mapEditUndoButton = candidate;
            }
        }

        installButtonHierarchySearchComplete = true;
    }

    private void UpdateInstallButtonVisibility(PlayerBag handBag)
    {
        if (mapEditModeActive)
        {
            SetInstallButtonVisible(false);
            return;
        }

        if (IsEditingInstallation())
        {
            SetInstallButtonVisible(false);
            return;
        }

        int handItemId = handBag != null ? handBag.GetSlotItemId(0) : -1;
        bool hasHandItem = handBag != null && handBag.GetSlotCount(0) > 0;
        SetInstallButtonVisible(
            hasHandItem && TryGetInventoryInstallationDefinition(handItemId, out _));
    }

    private void RefreshInstallButton()
    {
        PlayerBag handBag = GetPlayerHandBag();
        UpdateInstallButtonVisibility(handBag);

        if (!IsInstallationModeActive())
        {
            activeInstallDefinition = null;
            activeInstallPreview = null;
            return;
        }

        if (IsEditingInstallation())
        {
            if (activeInstallPreview == null || installPreviewInstances.Count <= 0)
            {
                CleanupInstallPreviewReferences();
            }

            EnsureValidActiveInstallPreview();
            return;
        }

        int handItemId = handBag != null ? handBag.GetSlotItemId(0) : -1;
        int handItemCount = handBag != null ? handBag.GetSlotCount(0) : 0;
        if (handItemId >= 0
            && handItemCount > 0
            && !TryGetInventoryInstallationDefinition(handItemId, out _))
        {
            ClearInstallPreview();
            return;
        }

        if (activeInstallPreview == null || installPreviewInstances.Count <= 0)
        {
            CleanupInstallPreviewReferences();
        }

        EnsureValidActiveInstallPreview();
    }

    private bool IsEditingInstallation()
    {
        return activeInstallationEditSession != null;
    }

    private bool TryGetHandInstallationDefinition(out ItemDefinition definition)
    {
        definition = null;

        PlayerBag handBag = GetPlayerHandBag();
        if (handBag == null || handBag.GetSlotCount(0) <= 0)
        {
            return false;
        }

        int handItemId = handBag.GetSlotItemId(0);
        return TryGetInventoryInstallationDefinition(handItemId, out definition);
    }

    private bool TryGetInventoryInstallationDefinition(int itemId, out ItemDefinition definition)
    {
        definition = null;

        if (itemId < 0 || GameManager.Instance == null || GameManager.Instance.ItemManger == null)
        {
            return false;
        }

        List<ItemDefinition> definitions = GameManager.Instance.ItemManger.ItemDefinitions;
        definition = ItemDefinitionLookup.ResolveExactById(definitions, itemId);
        if (!ItemDefinitionLookup.IsInstallationDefinition(definition))
        {
            definition = null;
            return false;
        }

        return true;
    }

    private bool TryGetInstallationDefinition(int itemId, out ItemDefinition definition)
    {
        definition = null;

        if (itemId < 0 || GameManager.Instance == null || GameManager.Instance.ItemManger == null)
        {
            return false;
        }

        List<ItemDefinition> definitions = GameManager.Instance.ItemManger.ItemDefinitions;
        if (definitions == null)
        {
            return false;
        }

        definition = ItemDefinitionLookup.ResolveInstallationById(definitions, itemId);
        return definition != null;
    }

    private bool TryGetInstallationDefinition(
        BlockStateStore.InstallationSaveState savedState,
        out ItemDefinition definition)
    {
        definition = null;
        if (savedState == null)
        {
            return false;
        }

        TryGetInstallationDefinition(savedState.itemId, out definition);
        if (ItemDefinitionLookup.LooksLikeLegacyConveyorBelt2FState(
                savedState.itemId,
                definition,
                savedState.occupiedCoordinates))
        {
            ItemDefinition belt2FDefinition =
                ItemDefinitionLookup.ResolveConveyorBelt2F(GameManager.Instance?.ItemManger?.ItemDefinitions);
            if (belt2FDefinition != null)
            {
                definition = belt2FDefinition;
            }
        }

        return definition != null;
    }

    private bool TryGetInstallationDefinitionForEditableObject(InstallationObject installationObject, out ItemDefinition definition)
    {
        definition = null;
        if (installationObject == null)
        {
            return false;
        }

        if (TryGetInstallationDefinition(installationObject.ResolveItemId(), out definition)
            && definition != null)
        {
            return true;
        }

        if (installationObject is Wall)
        {
            return TryGetFenceInstallationDefinition(out definition);
        }

        if (IsBelt2F(installationObject))
        {
            return TryGetBelt2FInstallationDefinition(out definition);
        }

        return false;
    }

    private bool TryGetBelt2FInstallationDefinition(out ItemDefinition definition)
    {
        definition = null;
        if (GameManager.Instance == null || GameManager.Instance.ItemManger == null)
        {
            return false;
        }

        List<ItemDefinition> definitions = GameManager.Instance.ItemManger.ItemDefinitions;
        if (definitions == null)
        {
            return false;
        }

        for (int i = 0; i < definitions.Count; i++)
        {
            ItemDefinition candidate = definitions[i];
            if (candidate == null || !IsBelt2F(candidate.mapObject))
            {
                continue;
            }

            definition = candidate;
            return true;
        }

        return false;
    }

    private bool TryGetFenceInstallationDefinition(out ItemDefinition definition)
    {
        definition = null;
        if (GameManager.Instance == null || GameManager.Instance.ItemManger == null)
        {
            return false;
        }

        List<ItemDefinition> definitions = GameManager.Instance.ItemManger.ItemDefinitions;
        if (definitions == null)
        {
            return false;
        }

        for (int i = 0; i < definitions.Count; i++)
        {
            ItemDefinition candidate = definitions[i];
            if (candidate == null || !(candidate.mapObject is Wall))
            {
                continue;
            }

            definition = candidate;
            return true;
        }

        return false;
    }

    private static bool TryResolveInstallationObject(MapObject mapObject, out InstallationObject installationObject)
    {
        installationObject = null;
        if (mapObject == null)
        {
            return false;
        }

        if (mapObject.GetComponent<Resource>() != null || mapObject.GetComponentInChildren<Resource>(true) != null)
        {
            return false;
        }

        installationObject = mapObject as InstallationObject;
        if (installationObject != null)
        {
            return true;
        }

        installationObject = mapObject.GetComponent<InstallationObject>();
        if (installationObject == null)
        {
            installationObject = mapObject.GetComponentInChildren<InstallationObject>(true);
        }

        return installationObject != null;
    }

    private PlayerBag GetPlayerHandBag()
    {
        if (GameManager.Instance == null || GameManager.Instance.Player == null)
        {
            return null;
        }

        return GameManager.Instance.Player.GetHandBag();
    }

    private PlayerBag GetPlayerInventoryBag()
    {
        if (GameManager.Instance == null || GameManager.Instance.Player == null)
        {
            return null;
        }

        return GameManager.Instance.Player.GetBag();
    }

    private bool TryReserveInstallPreviewItem(ItemDefinition definition, out InstallPreviewItemReservation reservation)
    {
        reservation = null;
        int itemId = definition != null ? definition.id : -1;
        if (itemId < 0)
        {
            return false;
        }

        Player player = GameManager.Instance != null ? GameManager.Instance.Player : null;
        PlayerBag handBag = player != null ? player.GetHandBag() : GetPlayerHandBag();
        if (TryReserveInstallPreviewItemFromHand(player, handBag, itemId, out reservation))
        {
            return true;
        }

        PlayerBag inventoryBag = player != null ? player.GetBag() : GetPlayerInventoryBag();
        return TryReserveInstallPreviewItemFromInventory(inventoryBag, handBag, itemId, out reservation);
    }

    private bool TryReserveInstallPreviewItemFromHand(
        Player player,
        PlayerBag handBag,
        int itemId,
        out InstallPreviewItemReservation reservation)
    {
        reservation = null;
        if (handBag == null)
        {
            return false;
        }

        PortableObject sourcePortableObject = GetFirstPlayerHandPortableSource(itemId);
        if (!TryReserveInstallPreviewItemFromBagSlot(
                handBag,
                itemId,
                0,
                true,
                sourcePortableObject,
                out reservation))
        {
            return false;
        }

        RefreshHandAfterInstallPreviewReservationChange(player, handBag);
        return true;
    }

    private bool TryReserveInstallPreviewItemFromInventory(
        PlayerBag inventoryBag,
        PlayerBag handBag,
        int itemId,
        out InstallPreviewItemReservation reservation)
    {
        reservation = null;
        if (inventoryBag == null || inventoryBag == handBag)
        {
            return false;
        }

        for (int i = 0; i < inventoryBag.SlotCount; i++)
        {
            if (TryReserveInstallPreviewItemFromBagSlot(
                    inventoryBag,
                    itemId,
                    i,
                    false,
                    null,
                    out reservation))
            {
                return true;
            }
        }

        return false;
    }

    private bool TryReserveInstallPreviewItemFromBagSlot(
        PlayerBag bag,
        int itemId,
        int slotIndex,
        bool fromHand,
        PortableObject sourcePortableObject,
        out InstallPreviewItemReservation reservation)
    {
        reservation = null;
        if (bag == null
            || itemId < 0
            || slotIndex < 0
            || bag.GetSlotItemId(slotIndex) != itemId
            || bag.GetSlotCount(slotIndex) <= 0)
        {
            return false;
        }

        if (!bag.TryRemoveItemsAtSlot(
                slotIndex,
                1,
                out int removedItemId,
                out int removedCount,
                out _,
                false,
                true)
            || removedItemId != itemId
            || removedCount <= 0)
        {
            return false;
        }

        reservation = new InstallPreviewItemReservation
        {
            itemId = itemId,
            fromHand = fromHand,
            sourceSlotIndex = slotIndex,
            sourcePortableObject = sourcePortableObject
        };
        return true;
    }

    private PortableObject GetFirstPlayerHandPortableSource(int itemId)
    {
        List<PortableObject> handSources = GetPlayerHandPortableSources(itemId, 1);
        return handSources.Count > 0 ? handSources[0] : null;
    }

    private static int GetReservationSourceSlotIndex(InstallPreviewItemReservation reservation)
    {
        if (reservation == null)
        {
            return -1;
        }

        return reservation.sourceSlotIndex >= 0 ? reservation.sourceSlotIndex : (reservation.fromHand ? 0 : -1);
    }

    private void RefreshHandAfterInstallPreviewReservationChange(Player player, PlayerBag handBag)
    {
        handBag?.RefreshExternalStackCounts(false);
        player?.UpdateCarryState();
    }

    private void RefundInstallPreviewReservation(MapObject preview)
    {
        if (preview == null)
        {
            return;
        }

        if (!installPreviewItemReservationsByPreview.TryGetValue(preview, out InstallPreviewItemReservation reservation))
        {
            return;
        }

        installPreviewItemReservationsByPreview.Remove(preview);
        RefundInstallPreviewReservation(reservation);
    }

    private bool TryConsumeInstallPreviewReservation(MapObject preview, out PortableObject sourcePortableObject)
    {
        sourcePortableObject = null;
        if (preview == null
            || !installPreviewItemReservationsByPreview.TryGetValue(preview, out InstallPreviewItemReservation reservation))
        {
            return false;
        }

        installPreviewItemReservationsByPreview.Remove(preview);
        if (reservation == null)
        {
            return false;
        }

        sourcePortableObject = reservation.sourcePortableObject;
        Player player = GameManager.Instance != null ? GameManager.Instance.Player : null;
        PlayerBag handBag = player != null ? player.GetHandBag() : GetPlayerHandBag();
        PlayerBag inventoryBag = player != null ? player.GetBag() : GetPlayerInventoryBag();
        PlayerBag sourceBag = reservation.fromHand ? handBag : inventoryBag;
        int sourceSlotIndex = GetReservationSourceSlotIndex(reservation);

        if (sourceBag != null
            && sourceSlotIndex >= 0
            && sourceBag.CommitVisualPreservedObjectRemoval(
                sourceSlotIndex,
                reservation.itemId,
                out PortableObject removedPortableObject)
            && sourcePortableObject == null)
        {
            sourcePortableObject = removedPortableObject;
        }

        if (reservation.fromHand)
        {
            RefreshHandAfterInstallPreviewReservationChange(player, handBag);
        }

        return true;
    }

    private int GetReservedInstallPreviewItemCount(int itemId)
    {
        if (itemId < 0 || installPreviewItemReservationsByPreview.Count <= 0)
        {
            return 0;
        }

        int count = 0;
        foreach (InstallPreviewItemReservation reservation in installPreviewItemReservationsByPreview.Values)
        {
            if (reservation != null && reservation.itemId == itemId)
            {
                count++;
            }
        }

        return count;
    }

    private void RefundAllInstallPreviewReservations()
    {
        List<InstallPreviewItemReservation> reservations = new List<InstallPreviewItemReservation>(
            installPreviewItemReservationsByPreview.Values);
        installPreviewItemReservationsByPreview.Clear();
        for (int i = 0; i < reservations.Count; i++)
        {
            RefundInstallPreviewReservation(reservations[i]);
        }
    }

    private void RefundInstallPreviewReservation(InstallPreviewItemReservation reservation)
    {
        if (reservation == null || reservation.itemId < 0)
        {
            return;
        }

        Player player = GameManager.Instance != null ? GameManager.Instance.Player : null;
        PlayerBag handBag = player != null ? player.GetHandBag() : GetPlayerHandBag();
        PlayerBag inventoryBag = player != null ? player.GetBag() : GetPlayerInventoryBag();
        if (reservation.fromHand)
        {
            if (TryRestoreInstallPreviewReservationToSourceSlot(handBag, reservation))
            {
                RefreshHandAfterInstallPreviewReservationChange(player, handBag);
                return;
            }

            if (player != null && player.TryAddToHand(reservation.itemId, out _))
            {
                RefreshHandAfterInstallPreviewReservationChange(player, handBag);
                return;
            }
        }
        else if (inventoryBag != null)
        {
            if (TryRestoreInstallPreviewReservationToSourceSlot(inventoryBag, reservation)
                || inventoryBag.TryAddObjectToSlotOnly(
                    GetReservationSourceSlotIndex(reservation),
                    reservation.itemId,
                    out _))
            {
                return;
            }

            if (player != null && player.TryAddToBag(reservation.itemId, out _))
            {
                return;
            }
        }

        player?.UpdateCarryState();
    }

    private bool TryRestoreInstallPreviewReservationToSourceSlot(
        PlayerBag bag,
        InstallPreviewItemReservation reservation)
    {
        int sourceSlotIndex = GetReservationSourceSlotIndex(reservation);
        return bag != null
               && reservation != null
               && sourceSlotIndex >= 0
               && bag.TryRestoreVisualPreservedObjectToSlotOnly(
                   sourceSlotIndex,
                   reservation.itemId,
                   out _);
    }

    private List<PortableObject> GetPlayerHandPortableSources(int itemId, int requestedCount)
    {
        List<PortableObject> results = new List<PortableObject>();
        if (requestedCount <= 0 || itemId < 0)
        {
            return results;
        }

        PlayerBag handBag = GetPlayerHandBag();
        if (handBag == null)
        {
            return results;
        }

        List<PortableObject> occupiedObjects = new List<PortableObject>();
        if (!handBag.TryGetOccupiedSlotObjects(0, occupiedObjects))
        {
            return results;
        }

        for (int i = occupiedObjects.Count - 1; i >= 0 && results.Count < requestedCount; i--)
        {
            PortableObject portableObject = occupiedObjects[i];
            if (portableObject == null || portableObject.ItemId != itemId)
            {
                continue;
            }

            results.Add(portableObject);
        }

        return results;
    }

    private void BindInstallButtons()
    {
        BindButton(installButton, HandleInstallButtonClicked);
        BindButton(installCancelButton, HandleInstallCancelClicked);
        BindButton(installRotationButton, HandleInstallRotationClicked);
        BindButton(installCompleteButton, HandleInstallCompleteClicked);
        BindButton(mapEditButton, HandleMapEditButtonClicked);
        BindButton(mapEditCancelButton, HandleInstallCancelClicked);
        BindButton(mapEditRotationButton, HandleInstallRotationClicked);
        UnbindButton(mapEditCompleteButton, HandleInstallCompleteClicked);
        BindButton(mapEditCompleteButton, HandleMapEditCompleteClicked);
        BindButton(mapEditPackButton, HandleMapEditPackClicked);
        BindButton(mapEditUndoButton, HandleMapEditUndoClicked);
    }

    private void UnbindInstallButtons()
    {
        UnbindButton(installButton, HandleInstallButtonClicked);
        UnbindButton(installCancelButton, HandleInstallCancelClicked);
        UnbindButton(installRotationButton, HandleInstallRotationClicked);
        UnbindButton(installCompleteButton, HandleInstallCompleteClicked);
        UnbindButton(mapEditButton, HandleMapEditButtonClicked);
        UnbindButton(mapEditCancelButton, HandleInstallCancelClicked);
        UnbindButton(mapEditRotationButton, HandleInstallRotationClicked);
        UnbindButton(mapEditCompleteButton, HandleMapEditCompleteClicked);
        UnbindButton(mapEditCompleteButton, HandleInstallCompleteClicked);
        UnbindButton(mapEditPackButton, HandleMapEditPackClicked);
        UnbindButton(mapEditUndoButton, HandleMapEditUndoClicked);
    }

    private static void BindButton(Button button, UnityEngine.Events.UnityAction action)
    {
        if (button == null || action == null)
        {
            return;
        }

        button.onClick.RemoveListener(action);
        button.onClick.AddListener(action);
    }

    private static void UnbindButton(Button button, UnityEngine.Events.UnityAction action)
    {
        if (button == null || action == null)
        {
            return;
        }

        button.onClick.RemoveListener(action);
    }

    private void RefreshMapEditButtonState()
    {
        CleanupSelectedEditableInstallation();
        if (mapEditButton != null)
        {
            mapEditButton.interactable = !IsInstallationModeActive();
        }

        bool canPack = mapEditModeActive && CanPackSelectedInstallation();
        if (mapEditPackButton != null)
        {
            mapEditPackButton.interactable = canPack;
        }

        if (mapEditRotationButton != null)
        {
            mapEditRotationButton.interactable = CanUseMapEditRotationButton();
        }

        if (mapEditCompleteButton != null)
        {
            mapEditCompleteButton.interactable = mapEditModeActive;
        }

        bool canUndo = mapEditModeActive && !IsEditingInstallation() && packedInstallationHistory.Count > 0;
        if (mapEditUndoButton != null)
        {
            mapEditUndoButton.interactable = canUndo;
        }
    }

    private bool CanPackSelectedInstallation()
    {
        if (!mapEditModeActive)
        {
            return false;
        }

        if (IsEditingInstallation())
        {
            CleanupInstallPreviewReferences();
            return activeInstallationEditSession != null
                   && activeInstallPreview != null
                   && TryGetPreviewAnchorCoordinate(activeInstallPreview, out _);
        }

        CleanupSelectedEditableInstallation();
        return selectedEditableInstallation != null
               && selectedEditableInstallation.TryGetPlacementRuntime(out _, out _)
               && CanPackEditableInstallation(selectedEditableInstallation);
    }

    private bool IsSelectedEditableSelectionOnly()
    {
        return ShouldSelectOnlyInMapEdit(selectedEditableInstallation);
    }

    private bool CanUseMapEditRotationButton()
    {
        if (!mapEditModeActive)
        {
            return false;
        }

        if (!IsEditingInstallation() && CanRotateSelectedSteamTrain())
        {
            return true;
        }

        return !IsSelectedEditableSelectionOnly();
    }

    private bool CanRotateSelectedSteamTrain()
    {
        if (!(selectedEditableInstallation is SteamTrain steamTrain)
            || !steamTrain.gameObject.activeInHierarchy)
        {
            return false;
        }

        return steamTrain.TryGetCurrentRailPose(out _, out _, out _, out Vector2 tangent)
               && tangent.sqrMagnitude > 0.0001f;
    }

    private bool CanPackEditableInstallation(InstallationObject installationObject)
    {
        return installationObject != null
               && (!(installationObject is Railload rail) || !IsRailOccupiedByTrain(rail));
    }

    private bool IsRailOccupiedByTrain(Railload rail)
    {
        if (rail == null)
        {
            return false;
        }

        mapEditRailOccupancyTrainScratch.Clear();
        Train.CollectActiveRuntimeTrains(mapEditRailOccupancyTrainScratch);
        for (int i = 0; i < mapEditRailOccupancyTrainScratch.Count; i++)
        {
            Train train = mapEditRailOccupancyTrainScratch[i];
            if (train == null)
            {
                continue;
            }

            if (train.TryGetCurrentRailPose(out Railload trainRail, out _, out _, out _)
                && trainRail == rail)
            {
                mapEditRailOccupancyTrainScratch.Clear();
                return true;
            }

            if (train.TryGetPlacementRuntime(out Vector2Int trainCoordinate, out _)
                && CoordinateListContains(rail.RuntimeOccupiedCoordinates, trainCoordinate))
            {
                mapEditRailOccupancyTrainScratch.Clear();
                return true;
            }
        }

        mapEditRailOccupancyTrainScratch.Clear();
        return false;
    }

    private void UpdateMapEditSelectionInput()
    {
        if (Input.touchCount > 0)
        {
            Touch touch = Input.GetTouch(0);
            switch (touch.phase)
            {
                case TouchPhase.Began:
                    BeginMapEditSelectionPointerTracking(touch.position, IsPointerOverBlockingUi(touch.position));
                    break;
                case TouchPhase.Moved:
                case TouchPhase.Stationary:
                    ContinueMapEditSelectionPointerTracking(touch.position);
                    break;
                case TouchPhase.Ended:
                    EndMapEditSelectionPointerTracking();
                    break;
                case TouchPhase.Canceled:
                    EndMapEditSelectionPointerTracking();
                    break;
            }

            return;
        }

        if (Input.GetMouseButtonDown(0))
        {
            BeginMapEditSelectionPointerTracking(Input.mousePosition, IsPointerOverBlockingUi(Input.mousePosition));
        }

        if (Input.GetMouseButton(0))
        {
            ContinueMapEditSelectionPointerTracking(Input.mousePosition);
        }

        if (Input.GetMouseButtonUp(0))
        {
            EndMapEditSelectionPointerTracking();
        }
    }

    private void BeginMapEditSelectionPointerTracking(Vector2 pointerPosition, bool startedOverUi)
    {
        ResetMapEditTrainDragTracking();
        if (startedOverUi)
        {
            return;
        }

        if (TryGetEditableInstallationAtPointer(pointerPosition, out InstallationObject installationObject, out Vector2Int anchorCoordinate))
        {
            if (!IsInstallationModeActive())
            {
                if (ShouldSelectOnlyInMapEdit(installationObject))
                {
                    SelectEditableInstallation(installationObject, anchorCoordinate);
                    BeginMapEditTrainDragTracking(installationObject as Train, pointerPosition);
                    return;
                }

                if (!BeginInstallationEdit(installationObject, anchorCoordinate))
                {
                    SelectEditableInstallation(installationObject, anchorCoordinate);
                }
                return;
            }

            SelectEditableInstallation(installationObject, anchorCoordinate);
            return;
        }

        ClearEditableInstallationSelection();
    }

    private void BeginMapEditTrainDragTracking(Train train, Vector2 pointerPosition)
    {
        if (train == null
            || !train.gameObject.activeInHierarchy
            || !train.TryGetCurrentRailPose(out _, out _, out _, out _))
        {
            return;
        }

        isMapEditTrainDragTracking = true;
        mapEditTrainDragMoved = false;
        mapEditTrainDragStartPosition = pointerPosition;
        mapEditTrainDragTrain = train;
    }

    private void ContinueMapEditSelectionPointerTracking(Vector2 pointerPosition)
    {
        if (!isMapEditTrainDragTracking
            || mapEditTrainDragTrain == null
            || !mapEditTrainDragTrain.gameObject.activeInHierarchy)
        {
            ResetMapEditTrainDragTracking();
            return;
        }

        if (!mapEditTrainDragMoved)
        {
            float threshold = Mathf.Max(1f, installRotateTapThreshold);
            if (Vector2.Distance(mapEditTrainDragStartPosition, pointerPosition) < threshold)
            {
                return;
            }

            mapEditTrainDragMoved = true;
        }

        TryMoveSelectedTrainAlongRail(pointerPosition, mapEditTrainDragTrain);
    }

    private void EndMapEditSelectionPointerTracking()
    {
        ResetMapEditTrainDragTracking();
    }

    private void ResetMapEditTrainDragTracking()
    {
        isMapEditTrainDragTracking = false;
        mapEditTrainDragMoved = false;
        mapEditTrainDragStartPosition = Vector2.zero;
        mapEditTrainDragTrain = null;
    }

    private bool TryMoveSelectedTrainAlongRail(Vector2 pointerPosition, Train train)
    {
        if (train == null
            || train != selectedEditableInstallation
            || !train.gameObject.activeInHierarchy
            || !train.TryGetPlacementRuntime(out _, out _)
            || !TryGetTrainDragRailSample(pointerPosition, out TrainPlacementRailSample railSample))
        {
            return false;
        }

        float maxRailDistance = RailAlignedPlacementMaxDistance;
        if (railSample.SqrDistance > maxRailDistance * maxRailDistance)
        {
            return false;
        }

        Vector2 referenceFacing = new Vector2(train.transform.forward.x, train.transform.forward.z);
        if (train.TryGetCurrentRailPose(out _, out _, out _, out Vector2 currentRailTangent)
            && currentRailTangent.sqrMagnitude > 0.0001f)
        {
            referenceFacing = currentRailTangent;
        }

        Vector2 facing = ResolveTrainPlacementFacingTangent(railSample.Tangent, referenceFacing);
        if (facing.sqrMagnitude <= 0.0001f)
        {
            return false;
        }

        Vector3 targetPosition = train.transform.position;
        targetPosition.x = railSample.Point.x;
        targetPosition.z = railSample.Point.y;
        Quaternion targetRotation = Quaternion.LookRotation(
            new Vector3(facing.x, 0f, facing.y),
            Vector3.up);
        if (!CanPlaceTrainAtPose(train, targetPosition, targetRotation, train)
            || !train.TryApplyRailPose(
                railSample.Rail,
                railSample.DistanceAlongPath,
                railSample.Point,
                facing))
        {
            return false;
        }

        Physics.SyncTransforms();
        train.ClearTrainConnections();
        ConnectTrainToNearbyTrains(train);
        if (train.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out _))
        {
            selectedEditableAnchorCoordinate = anchorCoordinate;
        }

        RefreshMapEditButtonState();
        return true;
    }

    private bool TryGetTrainDragRailSample(Vector2 pointerPosition, out TrainPlacementRailSample railSample)
    {
        railSample = default;
        Camera targetCamera = ResolveInstallPreviewCamera();
        if (targetCamera == null
            || !TryGetGroundPlanePoint(targetCamera.ScreenPointToRay(pointerPosition), out Vector3 worldPoint))
        {
            return false;
        }

        Vector2 referencePoint = new Vector2(worldPoint.x, worldPoint.z);
        Vector2Int centerCoordinate = new Vector2Int(
            Mathf.RoundToInt(referencePoint.x),
            Mathf.RoundToInt(referencePoint.y));
        int searchCells = Mathf.CeilToInt(Mathf.Max(1f, TrainPlacementRailSearchRadius));
        return TryFindNearestTrainPlacementRailSampleAroundCoordinate(
            centerCoordinate,
            referencePoint,
            searchCells,
            out railSample);
    }

    private static bool ShouldSelectOnlyInMapEdit(InstallationObject installationObject)
    {
        return installationObject is Railload || installationObject is Train;
    }

    private bool TryGetEditableInstallationAtPointer(Vector2 pointerPosition, out InstallationObject installationObject, out Vector2Int anchorCoordinate)
    {
        installationObject = null;
        anchorCoordinate = Vector2Int.zero;

        Camera targetCamera = ResolveInstallPreviewCamera();
        if (targetCamera == null)
        {
            return false;
        }

        Ray ray = targetCamera.ScreenPointToRay(pointerPosition);
        float maxDistance = targetCamera.farClipPlane > 0f ? targetCamera.farClipPlane : 512f;
        if (TryGetBlockFromGroundPlane(ray, out Block clickedBlock)
            && clickedBlock != null)
        {
            if (TryGetEditableBelt2FAtPointerBlock(ray, maxDistance, clickedBlock, out installationObject, out anchorCoordinate))
            {
                return true;
            }

            if (TryGetEditableTrainAtRailPointer(ray, maxDistance, clickedBlock, out installationObject, out anchorCoordinate))
            {
                return true;
            }

            if (TryGetEditableInstallationAtBlock(clickedBlock, out installationObject, out anchorCoordinate))
            {
                return true;
            }
        }

        return TryGetEditableInstallationFromRaycast(ray, maxDistance, out installationObject, out anchorCoordinate);
    }

    private bool TryGetEditableTrainAtRailPointer(
        Ray ray,
        float maxDistance,
        Block clickedBlock,
        out InstallationObject installationObject,
        out Vector2Int anchorCoordinate)
    {
        installationObject = null;
        anchorCoordinate = Vector2Int.zero;
        if (clickedBlock == null || !(clickedBlock.MapObject is Railload))
        {
            return false;
        }

        if (TryGetEditableTrainFromRaycast(ray, maxDistance, out Train raycastTrain, out Vector2Int raycastTrainAnchorCoordinate))
        {
            installationObject = raycastTrain;
            anchorCoordinate = raycastTrainAnchorCoordinate;
            return true;
        }

        return TryGetEditableTrainAtCoordinate(clickedBlock.Coordinate, out installationObject, out anchorCoordinate);
    }

    private bool TryGetEditableTrainFromRaycast(
        Ray ray,
        float maxDistance,
        out Train train,
        out Vector2Int anchorCoordinate)
    {
        train = null;
        anchorCoordinate = Vector2Int.zero;

        int hitCount = Physics.RaycastNonAlloc(
            ray,
            pointerRaycastHits,
            Mathf.Max(0f, maxDistance),
            Physics.DefaultRaycastLayers,
            QueryTriggerInteraction.Ignore);
        if (hitCount <= 0)
        {
            return false;
        }

        Train bestTrain = null;
        Vector2Int bestAnchorCoordinate = Vector2Int.zero;
        float bestDistance = float.PositiveInfinity;
        for (int i = 0; i < hitCount; i++)
        {
            RaycastHit hit = pointerRaycastHits[i];
            Collider hitCollider = hit.collider;
            if (hitCollider == null || hit.distance >= bestDistance)
            {
                continue;
            }

            Train candidate = hitCollider.GetComponentInParent<Train>();
            if (candidate == null
                || !candidate.gameObject.activeInHierarchy
                || !candidate.TryGetPlacementRuntime(out Vector2Int candidateAnchorCoordinate, out _))
            {
                continue;
            }

            bestTrain = candidate;
            bestAnchorCoordinate = candidateAnchorCoordinate;
            bestDistance = hit.distance;
        }

        if (bestTrain == null)
        {
            return false;
        }

        train = bestTrain;
        anchorCoordinate = bestAnchorCoordinate;
        return true;
    }

    private bool TryGetEditableTrainAtCoordinate(
        Vector2Int coordinate,
        out InstallationObject installationObject,
        out Vector2Int anchorCoordinate)
    {
        installationObject = null;
        anchorCoordinate = Vector2Int.zero;

        mapEditRailOccupancyTrainScratch.Clear();
        Train.CollectActiveRuntimeTrains(mapEditRailOccupancyTrainScratch);
        for (int i = 0; i < mapEditRailOccupancyTrainScratch.Count; i++)
        {
            Train train = mapEditRailOccupancyTrainScratch[i];
            if (train == null
                || !train.TryGetPlacementRuntime(out Vector2Int trainAnchorCoordinate, out _)
                || !CoordinateListContains(train.RuntimeOccupiedCoordinates, coordinate))
            {
                continue;
            }

            installationObject = train;
            anchorCoordinate = trainAnchorCoordinate;
            mapEditRailOccupancyTrainScratch.Clear();
            return true;
        }

        mapEditRailOccupancyTrainScratch.Clear();
        return false;
    }

    private bool TryGetEditableBelt2FAtPointerBlock(
        Ray ray,
        float maxDistance,
        Block clickedBlock,
        out InstallationObject installationObject,
        out Vector2Int anchorCoordinate)
    {
        installationObject = null;
        anchorCoordinate = Vector2Int.zero;
        if (clickedBlock == null)
        {
            return false;
        }

        if (TryGetEditableBelt2FFromRaycast(ray, maxDistance, clickedBlock, out installationObject, out anchorCoordinate))
        {
            return true;
        }

        return TryFindEditableBelt2FCoveringBlock(clickedBlock, out installationObject, out anchorCoordinate);
    }

    private bool TryGetEditableInstallationAtBlock(
        Block block,
        out InstallationObject installationObject,
        out Vector2Int anchorCoordinate)
    {
        installationObject = null;
        anchorCoordinate = Vector2Int.zero;
        if (block == null)
        {
            return false;
        }

        installationObject = block.MapObject as InstallationObject;
        if (installationObject == null || !installationObject.TryGetPlacementRuntime(out anchorCoordinate, out _))
        {
            installationObject = null;
            return false;
        }

        if (installationObject is UndergroundPipe undergroundPipe
            && undergroundPipe.ContainsEndpoint(block.Coordinate))
        {
            anchorCoordinate = block.Coordinate;
        }

        return true;
    }

    private bool TryGetEditableBelt2FFromRaycast(
        Ray ray,
        float maxDistance,
        Block clickedBlock,
        out InstallationObject installationObject,
        out Vector2Int anchorCoordinate)
    {
        installationObject = null;
        anchorCoordinate = Vector2Int.zero;
        if (clickedBlock == null)
        {
            return false;
        }

        int hitCount = Physics.RaycastNonAlloc(
            ray,
            pointerRaycastHits,
            Mathf.Max(0f, maxDistance),
            Physics.DefaultRaycastLayers,
            QueryTriggerInteraction.Ignore);
        if (hitCount <= 0)
        {
            return false;
        }

        InstallationObject bestInstallationObject = null;
        Vector2Int bestAnchorCoordinate = Vector2Int.zero;
        float bestDistance = float.PositiveInfinity;
        for (int i = 0; i < hitCount; i++)
        {
            RaycastHit hit = pointerRaycastHits[i];
            Collider hitCollider = hit.collider;
            if (hitCollider == null)
            {
                continue;
            }

            InstallationObject candidate = hitCollider.GetComponentInParent<InstallationObject>();
            if (hit.distance < bestDistance
                && TryResolveEditableBelt2FAtCoordinate(candidate, clickedBlock, out InstallationObject resolvedInstallation, out Vector2Int resolvedAnchorCoordinate))
            {
                bestInstallationObject = resolvedInstallation;
                bestAnchorCoordinate = resolvedAnchorCoordinate;
                bestDistance = hit.distance;
            }
        }

        if (bestInstallationObject == null)
        {
            return false;
        }

        installationObject = bestInstallationObject;
        anchorCoordinate = bestAnchorCoordinate;
        return true;
    }

    private bool TryFindEditableBelt2FCoveringBlock(
        Block clickedBlock,
        out InstallationObject installationObject,
        out Vector2Int anchorCoordinate)
    {
        installationObject = null;
        anchorCoordinate = Vector2Int.zero;
        if (clickedBlock == null)
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        editableInstallationScratch.Clear();
        int searchRadius = Mathf.Max(Belt2FDefaultFootprintWidth, Belt2FDefaultFootprintLength) + 2;
        for (int offsetY = -searchRadius; offsetY <= searchRadius; offsetY++)
        {
            for (int offsetX = -searchRadius; offsetX <= searchRadius; offsetX++)
            {
                Vector2Int candidateCoordinate = clickedBlock.Coordinate + new Vector2Int(offsetX, offsetY);
                if (!terrain.TryGetLoadedBlock(candidateCoordinate, out Block candidateBlock)
                    || candidateBlock == null
                    || !(candidateBlock.MapObject is InstallationObject candidate)
                    || !editableInstallationScratch.Add(candidate))
                {
                    continue;
                }

                if (TryResolveEditableBelt2FAtCoordinate(candidate, clickedBlock, out installationObject, out anchorCoordinate))
                {
                    editableInstallationScratch.Clear();
                    return true;
                }
            }
        }

        editableInstallationScratch.Clear();

        ConvayorBelt2F[] activeBelts = FindObjectsOfType<ConvayorBelt2F>(false);
        for (int i = 0; i < activeBelts.Length; i++)
        {
            if (TryResolveEditableBelt2FAtCoordinate(activeBelts[i], clickedBlock, out installationObject, out anchorCoordinate))
            {
                return true;
            }
        }

        return false;
    }

    private bool TryResolveEditableBelt2FAtCoordinate(
        InstallationObject candidate,
        Block clickedBlock,
        out InstallationObject installationObject,
        out Vector2Int anchorCoordinate)
    {
        installationObject = null;
        anchorCoordinate = Vector2Int.zero;
        if (candidate == null
            || clickedBlock == null
            || !IsBelt2F(candidate)
            || !candidate.gameObject.activeInHierarchy
            || !candidate.TryGetPlacementRuntime(out Vector2Int candidateAnchorCoordinate, out int candidateQuarterTurns))
        {
            return false;
        }

        Vector2Int bridgeCenterCoordinate = GetBelt2FBridgeCenterCoordinate(
            candidateAnchorCoordinate,
            candidate,
            candidateQuarterTurns);
        if (clickedBlock.Coordinate == bridgeCenterCoordinate
            && IsBaseConveyorBelt(GetBlockingMapObject(clickedBlock)))
        {
            return false;
        }

        List<Vector2Int> footprintCoordinates = GetFootprintCoordinates(
            candidateAnchorCoordinate,
            candidate,
            candidateQuarterTurns);
        if (!footprintCoordinates.Contains(clickedBlock.Coordinate))
        {
            return false;
        }

        installationObject = candidate;
        anchorCoordinate = candidateAnchorCoordinate;
        return true;
    }

    private void SelectEditableInstallation(InstallationObject installationObject, Vector2Int anchorCoordinate)
    {
        if (selectedEditableInstallation != installationObject)
        {
            SetWorkableRangeVisualRequested(selectedEditableInstallation, false);
            SetUtilityPoleRangeVisualRequested(selectedEditableInstallation, false);
            ClearSelectedEditableTint();
        }

        selectedEditableInstallation = installationObject;
        selectedEditableAnchorCoordinate = anchorCoordinate;
        ApplySelectedEditableTint(selectedEditableInstallation);
        SetWorkableRangeVisualRequested(selectedEditableInstallation, true);
        SetUtilityPoleRangeVisualRequested(selectedEditableInstallation, true);
        RefreshInstallOrEditWorkableRangeVisualRequest();
        RefreshMapEditButtonState();
    }

    private void ClearEditableInstallationSelection()
    {
        ResetMapEditTrainDragTracking();
        SetWorkableRangeVisualRequested(selectedEditableInstallation, false);
        SetUtilityPoleRangeVisualRequested(selectedEditableInstallation, false);
        ClearSelectedEditableTint();
        selectedEditableInstallation = null;
        selectedEditableAnchorCoordinate = Vector2Int.zero;
        RefreshInstallOrEditWorkableRangeVisualRequest();
        RefreshMapEditButtonState();
    }

    private void CleanupSelectedEditableInstallation()
    {
        if (selectedEditableInstallation == null)
        {
            return;
        }

        if (!selectedEditableInstallation.gameObject.activeInHierarchy
            || !selectedEditableInstallation.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out _))
        {
            SetWorkableRangeVisualRequested(selectedEditableInstallation, false);
            SetUtilityPoleRangeVisualRequested(selectedEditableInstallation, false);
            ClearSelectedEditableTint();
            selectedEditableInstallation = null;
            selectedEditableAnchorCoordinate = Vector2Int.zero;
            ResetMapEditTrainDragTracking();
            RefreshInstallOrEditWorkableRangeVisualRequest();
            return;
        }

        selectedEditableAnchorCoordinate = anchorCoordinate;
    }

    private void ApplySelectedEditableTint(MapObject mapObject)
    {
        ClearSelectedEditableTint();
        if (mapObject == null)
        {
            return;
        }

        Renderer[] renderers = mapObject.GetComponentsInChildren<Renderer>(true);
        for (int i = 0; i < renderers.Length; i++)
        {
            Renderer renderer = renderers[i];
            if (renderer == null
                || renderer.GetComponentInParent<WorkableObjectRangeVisual>() != null
                || renderer.sharedMaterial == null)
            {
                continue;
            }

            MaterialPropertyBlock originalPropertyBlock = new MaterialPropertyBlock();
            renderer.GetPropertyBlock(originalPropertyBlock);
            selectedEditableTintStates.Add(new RendererPropertyBlockState
            {
                renderer = renderer,
                propertyBlock = originalPropertyBlock
            });
        }

        ApplyInstallPreviewTint(mapObject, true, installPreviewTint);
    }

    private void ClearSelectedEditableTint()
    {
        if (selectedEditableTintStates.Count <= 0)
        {
            return;
        }

        for (int i = 0; i < selectedEditableTintStates.Count; i++)
        {
            RendererPropertyBlockState rendererState = selectedEditableTintStates[i];
            if (rendererState == null || rendererState.renderer == null)
            {
                continue;
            }

            rendererState.renderer.SetPropertyBlock(rendererState.propertyBlock);
        }

        selectedEditableTintStates.Clear();
    }

    private static void SetWorkableRangeVisualRequested(MapObject mapObject, bool requested)
    {
        WorkableObject workableObject = ResolveWorkableObject(mapObject);
        if (workableObject != null)
        {
            workableObject.SetSelectedRangeVisualRequested(requested);
        }
    }

    private static void SetUtilityPoleRangeVisualRequested(
        MapObject mapObject,
        bool requested,
        bool connectionRangeRequested = true)
    {
        UtilityPole utilityPole = ResolveUtilityPole(mapObject);
        if (utilityPole != null)
        {
            utilityPole.SetSelectedSupplyRangeVisualRequested(requested, connectionRangeRequested);
        }
    }

    private static void SetWorkableRangeVisualGlobalSuppressed(MapObject mapObject, bool suppressed)
    {
        WorkableObject workableObject = ResolveWorkableObject(mapObject);
        if (workableObject != null)
        {
            workableObject.SetGlobalRangeVisualSuppressed(suppressed);
        }
    }

    private static WorkableObject ResolveWorkableObject(MapObject mapObject)
    {
        if (mapObject == null)
        {
            return null;
        }

        if (mapObject is WorkableObject workableObject)
        {
            return workableObject;
        }

        return mapObject.GetComponentInChildren<WorkableObject>(true);
    }

    private static UtilityPole ResolveUtilityPole(MapObject mapObject)
    {
        if (mapObject == null)
        {
            return null;
        }

        if (mapObject is UtilityPole utilityPole)
        {
            return utilityPole;
        }

        return mapObject.GetComponentInChildren<UtilityPole>(true);
    }

    private static InstallationObject ResolveInstallationObject(MapObject mapObject)
    {
        if (mapObject == null)
        {
            return null;
        }

        if (mapObject is InstallationObject installationObject)
        {
            return installationObject;
        }

        return mapObject.GetComponentInChildren<InstallationObject>(true);
    }

    private void RefreshUtilityPolePreviewWire(MapObject preview)
    {
        UtilityPole utilityPole = ResolveUtilityPole(preview);
        InstallationObject installationObject = ResolveInstallationObject(preview);
        if (utilityPole != null)
        {
            if (TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate))
            {
                UtilityPole.RegisterBlueprintPreview(
                    utilityPole,
                    anchorCoordinate,
                    GetPreviewQuarterTurns(preview),
                    IsEditingInstallation()
                    && preview == activeInstallPreview
                    && activeInstallationEditSession?.originalInstallation is UtilityPole);
            }
            else
            {
                UtilityPole.UnregisterBlueprintPreview(utilityPole);
            }

            UtilityPole.UnregisterConsumerBlueprintPreview(installationObject);
            return;
        }

        if (installationObject != null && TryGetPreviewAnchorCoordinate(preview, out Vector2Int consumerAnchorCoordinate))
        {
            UtilityPole.RegisterConsumerBlueprintPreview(
                installationObject,
                consumerAnchorCoordinate,
                GetPreviewQuarterTurns(preview));
            return;
        }

        UtilityPole.UnregisterConsumerBlueprintPreview(installationObject);
    }

    private void RefreshUtilityPolePreviewWires()
    {
        CleanupInstallPreviewReferences();
        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            RefreshUtilityPolePreviewWire(installPreviewInstances[i]);
        }
    }

    private static void UnregisterUtilityPolePreviewWire(MapObject preview)
    {
        UtilityPole utilityPole = ResolveUtilityPole(preview);
        if (utilityPole != null)
        {
            UtilityPole.UnregisterBlueprintPreview(utilityPole);
        }

        InstallationObject installationObject = ResolveInstallationObject(preview);
        if (installationObject != null)
        {
            UtilityPole.UnregisterConsumerBlueprintPreview(installationObject);
        }
    }

    private bool ShouldRequestInstallOrEditWorkableRangeVisuals()
    {
        GameManager gameManager = GameManager.Instance;
        bool installationModeActive = gameManager != null && gameManager.InstallationPlacementActive;
        if (installationModeActive && activeInstallDefinition != null && ResolveWorkableObject(activeInstallDefinition.mapObject) != null)
        {
            return true;
        }

        if ((installationModeActive || mapEditModeActive) && ResolveWorkableObject(activeInstallPreview) != null)
        {
            return true;
        }

        return mapEditModeActive && ResolveWorkableObject(selectedEditableInstallation) != null;
    }

    private bool ShouldRequestInstallOrEditUtilityPoleRangeVisuals()
    {
        GameManager gameManager = GameManager.Instance;
        bool installationModeActive = gameManager != null && gameManager.InstallationPlacementActive;
        if (installationModeActive && activeInstallDefinition != null && ResolveUtilityPole(activeInstallDefinition.mapObject) != null)
        {
            return true;
        }

        if ((installationModeActive || mapEditModeActive) && ResolveUtilityPole(activeInstallPreview) != null)
        {
            return true;
        }

        return mapEditModeActive && ResolveUtilityPole(selectedEditableInstallation) != null;
    }

    private void RefreshInstallOrEditWorkableRangeVisualRequest()
    {
        WorkableObject.SetInstallOrEditWorkableSelectionRangeVisualsRequested(
            ShouldRequestInstallOrEditWorkableRangeVisuals());
        UtilityPole.SetInstallOrEditUtilityPoleSelectionRangeVisualsRequested(
            ShouldRequestInstallOrEditUtilityPoleRangeVisuals());
    }

    private void RefreshPreviewRangeVisualsIfNeeded(MapObject preview)
    {
        if (ResolveWorkableObject(preview) != null)
        {
            WorkableObject.RefreshAllRangeVisuals();
        }

        if (ResolveUtilityPole(preview) != null)
        {
            UtilityPole.RefreshAllRangeVisuals();
        }
    }

    private void SetInstallPreviewSelectionVisual(
        MapObject preview,
        bool selected,
        bool forceWorkableRangeVisible = false,
        bool forceUtilityPoleRangeVisible = false)
    {
        SetWorkableRangeVisualGlobalSuppressed(preview, true);
        ApplyInstallPreviewTint(preview, selected);
        SetWorkableRangeVisualRequested(preview, selected || (forceWorkableRangeVisible && ResolveWorkableObject(preview) != null));
        UtilityPole previewPole = ResolveUtilityPole(preview);
        bool utilityPoleRangeRequested = selected || (forceUtilityPoleRangeVisible && previewPole != null);
        bool connectionRangeRequested = !(selected && previewPole != null && IsInstallationModeActive());
        SetUtilityPoleRangeVisualRequested(preview, utilityPoleRangeRequested, connectionRangeRequested);
        RefreshInstallOrEditWorkableRangeVisualRequest();
        if (!selected)
        {
            ClearInputOutputMarkers(preview);
        }
    }

    private void RefreshInstallPreviewSelectionVisuals()
    {
        CleanupInstallPreviewReferences();
        bool forceWorkablePreviewRangesVisible = ShouldRequestInstallOrEditWorkableRangeVisuals();
        bool forceUtilityPolePreviewRangesVisible = ShouldRequestInstallOrEditUtilityPoleRangeVisuals();
        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            MapObject preview = installPreviewInstances[i];
            if (preview == null)
            {
                continue;
            }

            SetInstallPreviewSelectionVisual(
                preview,
                preview == activeInstallPreview,
                forceWorkablePreviewRangesVisible,
                forceUtilityPolePreviewRangesVisible);
        }

        RefreshInstallOrEditWorkableRangeVisualRequest();
        UtilityPole.RefreshAllRangeVisuals();
    }

    private void ApplyInstallPreviewTint(MapObject preview, bool selected)
    {
        ApplyInstallPreviewTint(preview, selected, ResolveInstallPreviewTint(preview));
    }

    private void ApplyInstallPreviewTint(MapObject preview, bool selected, Color tint)
    {
        if (preview == null)
        {
            return;
        }

        if (installPreviewPropertyBlock == null)
        {
            installPreviewPropertyBlock = new MaterialPropertyBlock();
        }

        if (preview is UndergroundPipe undergroundPipePreview)
        {
            // The route is created after the endpoint renderers. Bind its preview
            // material before collecting renderers so it receives the same property block.
            undergroundPipePreview.SetPreviewRouteColor(tint);
        }

        Renderer[] renderers = preview.GetComponentsInChildren<Renderer>(true);
        for (int i = 0; i < renderers.Length; i++)
        {
            Renderer renderer = renderers[i];
            if (renderer == null || renderer.GetComponentInParent<WorkableObjectRangeVisual>() != null)
            {
                continue;
            }

            Material sharedMaterial = renderer.sharedMaterial;
            if (sharedMaterial == null)
            {
                continue;
            }

            installPreviewPropertyBlock.Clear();
            renderer.GetPropertyBlock(installPreviewPropertyBlock);
            bool hasColorProperty = false;
            if (TryApplyBlueprintPreviewProperties(sharedMaterial, installPreviewPropertyBlock, tint))
            {
                hasColorProperty = true;
            }
            else if (sharedMaterial.HasProperty(BaseColorPropertyId))
            {
                installPreviewPropertyBlock.SetColor(BaseColorPropertyId, tint);
                hasColorProperty = true;
            }
            else if (sharedMaterial.HasProperty(ColorPropertyId))
            {
                installPreviewPropertyBlock.SetColor(ColorPropertyId, tint);
                hasColorProperty = true;
            }

            if (sharedMaterial.HasProperty(EmissionColorPropertyId))
            {
                installPreviewPropertyBlock.SetColor(EmissionColorPropertyId, tint * 0.35f);
                hasColorProperty = true;
            }

            if (hasColorProperty)
            {
                renderer.SetPropertyBlock(installPreviewPropertyBlock);
            }
        }

        RefreshInstallPreviewConveyorShaderProperties(preview);
    }

    private static bool ConfigurePreviewOnlyRuntimeRendering(MapObject preview)
    {
        if (preview == null)
        {
            return false;
        }

        RobotArm[] robotArms = preview.GetComponentsInChildren<RobotArm>(true);
        for (int i = 0; i < robotArms.Length; i++)
        {
            RobotArm robotArm = robotArms[i];
            if (robotArm == null)
            {
                continue;
            }

            robotArm.SetPreviewRenderingMode(true);
            DisablePreviewAnimators(robotArm);
        }

        return robotArms.Length > 0;
    }

    private static void NormalizeInstallPreviewNativeRendering(MapObject preview)
    {
        if (preview == null)
        {
            return;
        }

        if (preview is ConveyorBelt conveyorBelt)
        {
            conveyorBelt.SetVirtualRenderingSuppressed(false);
        }

        Renderer[] renderers = preview.GetComponentsInChildren<Renderer>(true);
        for (int i = 0; i < renderers.Length; i++)
        {
            Renderer renderer = renderers[i];
            if (!ShouldRestoreInstallPreviewRenderer(renderer))
            {
                continue;
            }

            renderer.forceRenderingOff = false;
            renderer.enabled = true;
        }
    }

    private static bool ShouldRestoreInstallPreviewRenderer(Renderer renderer)
    {
        return renderer != null
               && renderer.gameObject.activeInHierarchy
               && !(renderer is ParticleSystemRenderer)
               && !(renderer is LineRenderer)
               && !(renderer is SpriteRenderer)
               && renderer.GetComponentInParent<WorkableObjectRangeVisual>() == null
               && !IsPipeFluidDisplayRenderer(renderer)
               && RendererHasAnyMaterial(renderer);
    }

    private static bool IsPipeFluidDisplayRenderer(Renderer renderer)
    {
        if (renderer == null)
        {
            return false;
        }

        if (renderer.name == "Fluid DP")
        {
            return true;
        }

        Material sharedMaterial = renderer.sharedMaterial;
        return sharedMaterial != null
               && sharedMaterial.name != null
               && sharedMaterial.name.StartsWith("M_Fluid", System.StringComparison.Ordinal);
    }

    private static void DisablePreviewAnimators(Component previewRoot)
    {
        if (previewRoot == null)
        {
            return;
        }

        Animator[] animators = previewRoot.GetComponentsInChildren<Animator>(true);
        for (int i = 0; i < animators.Length; i++)
        {
            if (animators[i] != null)
            {
                animators[i].enabled = false;
            }
        }
    }

    private static bool IsRobotArmPreviewRenderer(Renderer renderer)
    {
        return renderer != null
               && renderer.GetComponentInParent<RobotArm>(true) != null
               && renderer.GetComponentInParent<PortableObject>(true) == null;
    }

    private Color ResolveInstallPreviewTint(MapObject preview)
    {
        if (preview != null && trainConnectionPreviewTints.TryGetValue(preview, out Color connectionTint))
        {
            return connectionTint;
        }

        return installPreviewTint;
    }

    private void RefreshTrainInstallPreviewTints()
    {
        ClearInstalledTrainConnectionTints();
        trainConnectionPreviewTints.Clear();
        trainConnectionPreviewObjectsByTrain.Clear();
        trainConnectionPreviewScratch.Clear();
        trainConnectionInstalledScratch.Clear();
        trainConnectionNodeScratch.Clear();
        trainConnectionNodeSet.Clear();
        trainConnectionVisited.Clear();
        trainConnectionQueue.Clear();

        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            MapObject preview = installPreviewInstances[i];
            if (preview == null)
            {
                continue;
            }

            MapObject source = ResolveInstallPreviewPlacementSource(preview);
            if ((ResolveTrainSource(source) ?? ResolveTrainSource(preview)) == null)
            {
                continue;
            }

            Train previewTrain = ResolveTrainSource(preview);
            if (previewTrain == null)
            {
                continue;
            }

            trainConnectionPreviewScratch.Add(previewTrain);
            trainConnectionPreviewObjectsByTrain[previewTrain] = preview;
            AddTrainConnectionNode(previewTrain);
        }

        if (trainConnectionPreviewScratch.Count > 0)
        {
            Train.CollectActiveRuntimeTrains(trainConnectionInstalledScratch);
            for (int i = 0; i < trainConnectionInstalledScratch.Count; i++)
            {
                Train installedTrain = trainConnectionInstalledScratch[i];
                if (installedTrain == null || trainConnectionPreviewObjectsByTrain.ContainsKey(installedTrain))
                {
                    continue;
                }

                AddTrainConnectionNode(installedTrain);
            }
        }

        int groupTintIndex = 0;
        for (int i = 0; i < trainConnectionNodeScratch.Count; i++)
        {
            Train startTrain = trainConnectionNodeScratch[i];
            if (startTrain == null || trainConnectionVisited.Contains(startTrain))
            {
                continue;
            }

            CollectTrainConnectionComponent(startTrain);
            if (trainConnectionComponentScratch.Count <= 1)
            {
                continue;
            }

            Color groupTint = ResolveTrainConnectionGroupTint(groupTintIndex++);
            for (int componentIndex = 0; componentIndex < trainConnectionComponentScratch.Count; componentIndex++)
            {
                Train train = trainConnectionComponentScratch[componentIndex];
                if (train == null)
                {
                    continue;
                }

                if (trainConnectionPreviewObjectsByTrain.TryGetValue(train, out MapObject preview))
                {
                    trainConnectionPreviewTints[preview] = groupTint;
                    continue;
                }

                ApplyInstalledTrainConnectionTint(train, groupTint);
            }
        }

        for (int i = 0; i < trainConnectionPreviewScratch.Count; i++)
        {
            Train previewTrain = trainConnectionPreviewScratch[i];
            if (previewTrain == null
                || !trainConnectionPreviewObjectsByTrain.TryGetValue(previewTrain, out MapObject preview)
                || preview == null)
            {
                continue;
            }

            ApplyInstallPreviewTint(
                preview,
                preview == activeInstallPreview,
                ResolveInstallPreviewTint(preview));
        }

        trainConnectionPreviewScratch.Clear();
        trainConnectionInstalledScratch.Clear();
        trainConnectionNodeScratch.Clear();
        trainConnectionNodeSet.Clear();
        trainConnectionComponentScratch.Clear();
        trainConnectionVisited.Clear();
        trainConnectionQueue.Clear();
        trainConnectionPreviewObjectsByTrain.Clear();
    }

    private void AddTrainConnectionNode(Train train)
    {
        if (train == null || !trainConnectionNodeSet.Add(train))
        {
            return;
        }

        trainConnectionNodeScratch.Add(train);
    }

    private void CollectTrainConnectionComponent(Train startTrain)
    {
        trainConnectionComponentScratch.Clear();
        if (startTrain == null)
        {
            return;
        }

        trainConnectionQueue.Enqueue(startTrain);
        trainConnectionVisited.Add(startTrain);
        while (trainConnectionQueue.Count > 0)
        {
            Train currentTrain = trainConnectionQueue.Dequeue();
            if (currentTrain == null)
            {
                continue;
            }

            trainConnectionComponentScratch.Add(currentTrain);
            foreach (Train connectedTrain in currentTrain.ConnectedTrains)
            {
                if (connectedTrain == null
                    || !trainConnectionNodeSet.Contains(connectedTrain)
                    || !trainConnectionVisited.Add(connectedTrain))
                {
                    continue;
                }

                trainConnectionQueue.Enqueue(connectedTrain);
            }

            for (int i = 0; i < trainConnectionNodeScratch.Count; i++)
            {
                Train candidate = trainConnectionNodeScratch[i];
                if (candidate == null
                    || candidate == currentTrain
                    || trainConnectionVisited.Contains(candidate)
                    || !Train.CanConnectByPose(currentTrain, candidate))
                {
                    continue;
                }

                trainConnectionVisited.Add(candidate);
                trainConnectionQueue.Enqueue(candidate);
            }
        }
    }

    private static Color ResolveTrainConnectionGroupTint(int groupIndex)
    {
        if (TrainConnectionGroupTints.Length <= 0)
        {
            return Color.white;
        }

        int index = ((groupIndex % TrainConnectionGroupTints.Length) + TrainConnectionGroupTints.Length)
                    % TrainConnectionGroupTints.Length;
        return TrainConnectionGroupTints[index];
    }

    private void ApplyInstalledTrainConnectionTint(Train train, Color tint)
    {
        if (train == null)
        {
            return;
        }

        if (!installedTrainConnectionTintStates.TryGetValue(train, out List<RendererPropertyBlockState> rendererStates))
        {
            rendererStates = new List<RendererPropertyBlockState>();
            Renderer[] renderers = train.GetComponentsInChildren<Renderer>(true);
            for (int i = 0; i < renderers.Length; i++)
            {
                Renderer renderer = renderers[i];
                if (renderer == null
                    || renderer.GetComponentInParent<WorkableObjectRangeVisual>() != null
                    || renderer.sharedMaterial == null)
                {
                    continue;
                }

                MaterialPropertyBlock originalPropertyBlock = new MaterialPropertyBlock();
                renderer.GetPropertyBlock(originalPropertyBlock);
                rendererStates.Add(new RendererPropertyBlockState
                {
                    renderer = renderer,
                    propertyBlock = originalPropertyBlock
                });
            }

            installedTrainConnectionTintStates[train] = rendererStates;
        }

        for (int i = 0; i < rendererStates.Count; i++)
        {
            RendererPropertyBlockState rendererState = rendererStates[i];
            Renderer renderer = rendererState?.renderer;
            if (renderer == null)
            {
                continue;
            }

            Material sharedMaterial = renderer.sharedMaterial;
            if (sharedMaterial == null)
            {
                continue;
            }

            if (installPreviewPropertyBlock == null)
            {
                installPreviewPropertyBlock = new MaterialPropertyBlock();
            }

            installPreviewPropertyBlock.Clear();
            renderer.GetPropertyBlock(installPreviewPropertyBlock);
            bool hasColorProperty = false;
            if (TryApplyBlueprintPreviewProperties(sharedMaterial, installPreviewPropertyBlock, tint))
            {
                hasColorProperty = true;
            }
            else if (sharedMaterial.HasProperty(BaseColorPropertyId))
            {
                installPreviewPropertyBlock.SetColor(BaseColorPropertyId, tint);
                hasColorProperty = true;
            }
            else if (sharedMaterial.HasProperty(ColorPropertyId))
            {
                installPreviewPropertyBlock.SetColor(ColorPropertyId, tint);
                hasColorProperty = true;
            }

            if (sharedMaterial.HasProperty(EmissionColorPropertyId))
            {
                installPreviewPropertyBlock.SetColor(EmissionColorPropertyId, tint * 0.35f);
                hasColorProperty = true;
            }

            if (hasColorProperty)
            {
                renderer.SetPropertyBlock(installPreviewPropertyBlock);
            }
        }
    }

    private void ClearInstalledTrainConnectionTints()
    {
        if (installedTrainConnectionTintStates.Count <= 0)
        {
            return;
        }

        foreach (KeyValuePair<Train, List<RendererPropertyBlockState>> entry in installedTrainConnectionTintStates)
        {
            List<RendererPropertyBlockState> rendererStates = entry.Value;
            if (rendererStates == null)
            {
                continue;
            }

            for (int i = 0; i < rendererStates.Count; i++)
            {
                RendererPropertyBlockState rendererState = rendererStates[i];
                if (rendererState == null || rendererState.renderer == null)
                {
                    continue;
                }

                rendererState.renderer.SetPropertyBlock(rendererState.propertyBlock);
            }
        }

        installedTrainConnectionTintStates.Clear();
    }

    private static void RefreshInstallPreviewConveyorShaderProperties(MapObject preview)
    {
        if (preview == null)
        {
            return;
        }

        ConveyorBelt[] conveyorBelts = preview.GetComponentsInChildren<ConveyorBelt>(true);
        for (int i = 0; i < conveyorBelts.Length; i++)
        {
            ConveyorBelt conveyorBelt = conveyorBelts[i];
            if (conveyorBelt == null)
            {
                continue;
            }

            conveyorBelt.RefreshBeltTopShaderProperties();
        }
    }

    private void HandleMapEditButtonClicked()
    {
        if (IsInstallationModeActive())
        {
            RefreshMapEditButtonState();
            return;
        }

        SetMapEditModeActive(!mapEditModeActive);
    }

    private void HandleMapEditPackClicked()
    {
        TryPackSelectedInstallation();
        RefreshMapEditButtonState();
    }

    private void HandleMapEditUndoClicked()
    {
        TryUndoPackedInstallation();
        RefreshMapEditButtonState();
    }

    private void HandleMapEditCompleteClicked()
    {
        if (!mapEditModeActive)
        {
            if (IsEditingInstallation())
            {
                CompleteInstallationEdit();
            }

            return;
        }

        if (IsEditingInstallation())
        {
            bool hasPackedInstallationsToFinalize = packedInstallationHistory.Count > 0;
            if (TryCompleteInstallationEdit() || !hasPackedInstallationsToFinalize)
            {
                return;
            }

            if (IsEditingInstallation())
            {
                CancelInstallationEdit();
            }
        }

        SetMapEditModeActive(false);
    }

    private bool TryPackSelectedInstallation()
    {
        if (!mapEditModeActive)
        {
            return false;
        }

        bool wasEditingInstallation = IsEditingInstallation();
        InstallationEditSession editSession;
        Vector2Int targetAnchorCoordinate;
        int targetQuarterTurns;

        if (wasEditingInstallation)
        {
            CleanupInstallPreviewReferences();
            if (activeInstallationEditSession == null
                || activeInstallPreview == null
                || !TryGetPreviewAnchorCoordinate(activeInstallPreview, out targetAnchorCoordinate))
            {
                return false;
            }

            editSession = activeInstallationEditSession;
            if (!CanPackEditableInstallation(editSession.originalInstallation))
            {
                return false;
            }

            targetQuarterTurns = GetPreviewQuarterTurns(activeInstallPreview);
            activeInstallationEditSession = null;
            PreserveAttachedAreaBoxesForPacking(editSession);
        }
        else
        {
            CleanupSelectedEditableInstallation();
            if (selectedEditableInstallation == null
                || !selectedEditableInstallation.TryGetPlacementRuntime(out targetAnchorCoordinate, out targetQuarterTurns)
                || !CanPackEditableInstallation(selectedEditableInstallation)
                || !TryCreateInstallationEditSession(selectedEditableInstallation, out editSession))
            {
                return false;
            }

            PreserveAttachedAreaBoxesForPacking(editSession);
            DetachInstallationForEditing(editSession);
        }

        int itemId = ResolvePackedInstallationItemId(editSession);
        int packedConveyorVariantKind = wasEditingInstallation && activeInstallPreview != null
            ? GetInstallationVariantKind(activeInstallPreview)
            : editSession.originalConveyorVariantKind;
        if (itemId < 0)
        {
            RestoreEditedInstallation(editSession, targetAnchorCoordinate, targetQuarterTurns);
            ClearInstallPreview();
            return false;
        }

        int itemCount = ResolvePackedInstallationItemCount(editSession);
        PackedInstallationSession packedSession = new PackedInstallationSession
        {
            editSession = editSession,
            anchorCoordinate = targetAnchorCoordinate,
            quarterTurns = ((targetQuarterTurns % 4) + 4) % 4,
            conveyorVariantKind = packedConveyorVariantKind,
            itemId = itemId,
            itemCount = itemCount,
            dropCoordinate = targetAnchorCoordinate,
            pendingDroppedBlockStatesByCanonicalOffset = BuildPackedInstallationDroppedBlockStates(editSession)
        };
        packedInstallationHistory.Push(packedSession);

        ClearEditableInstallationSelection();
        ClearInstallPreview();
        RefreshInstalledConnectorVariantsAfterRemoval(editSession, targetAnchorCoordinate, targetQuarterTurns);
        return true;
    }

    private static int ResolvePackedInstallationItemCount(InstallationEditSession editSession)
    {
        if (editSession?.originalInstallation is Railload
            || editSession?.definition?.mapObject is Railload)
        {
            return Mathf.Max(1, editSession.originalRailRequiredItemCount);
        }

        return 1;
    }

    private static int ResolvePackedInstallationItemId(InstallationEditSession editSession)
    {
        if (editSession?.originalInstallation is Railload
            || editSession?.definition?.mapObject is Railload)
        {
            IReadOnlyList<ItemDefinition> definitions = GameManager.Instance?.ItemManger?.ItemDefinitions;
            ItemDefinition railDefinition =
                ItemDefinitionLookup.ResolveInstallationByStableName(definitions, "Railload");
            if (railDefinition != null && railDefinition.id >= 0)
            {
                return railDefinition.id;
            }
        }

        return editSession?.definition != null
            ? editSession.definition.id
            : editSession?.originalInstallation != null
                ? editSession.originalInstallation.ResolveItemId()
                : -1;
    }

    private bool TryUndoPackedInstallation()
    {
        if (!mapEditModeActive || IsEditingInstallation() || packedInstallationHistory.Count <= 0)
        {
            return false;
        }

        PackedInstallationSession packedSession = packedInstallationHistory.Peek();
        if (packedSession == null || packedSession.editSession == null)
        {
            packedInstallationHistory.Pop();
            return false;
        }

        if (!TryRemovePackedSessionItem(packedSession))
        {
            return false;
        }

        packedInstallationHistory.Pop();
        RestoreEditedInstallation(
            packedSession.editSession,
            packedSession.anchorCoordinate,
            packedSession.quarterTurns);
        return true;
    }

    private bool TryDropPackedPortable(int itemId, Vector2Int preferredCoordinate, out PortableObject portableObject, out Vector2Int dropCoordinate)
    {
        portableObject = null;
        dropCoordinate = preferredCoordinate;

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null || itemId < 0)
        {
            return false;
        }

        const int maxSearchRadius = 2;
        for (int radius = 0; radius <= maxSearchRadius; radius++)
        {
            for (int offsetY = -radius; offsetY <= radius; offsetY++)
            {
                for (int offsetX = -radius; offsetX <= radius; offsetX++)
                {
                    if (radius > 0 && Mathf.Abs(offsetX) != radius && Mathf.Abs(offsetY) != radius)
                    {
                        continue;
                    }

                    Vector2Int coordinate = preferredCoordinate + new Vector2Int(offsetX, offsetY);
                    if (!terrain.TryGetLoadedBlock(coordinate, out Block block) || block == null || block.Type != Block.BlockType.Ground)
                    {
                        continue;
                    }

                    if (!block.TryAddFloorObject(itemId, out portableObject))
                    {
                        continue;
                    }

                    dropCoordinate = coordinate;
                    return true;
                }
            }
        }

        return false;
    }

    private bool TryRemovePackedPortable(PackedPortableDrop packedPortableDrop)
    {
        if (packedPortableDrop == null || packedPortableDrop.portableObject == null)
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        if (terrain.TryGetLoadedBlock(packedPortableDrop.coordinate, out Block dropBlock)
            && dropBlock != null
            && dropBlock.TryRemoveFloorObject(packedPortableDrop.portableObject))
        {
            return true;
        }

        return false;
    }

    private bool TryRemovePackedPortables(PackedInstallationSession packedSession)
    {
        if (packedSession?.portableDrops == null || packedSession.portableDrops.Count <= 0)
        {
            return true;
        }

        for (int i = packedSession.portableDrops.Count - 1; i >= 0; i--)
        {
            if (!TryRemovePackedPortable(packedSession.portableDrops[i]))
            {
                return false;
            }

            packedSession.portableDrops.RemoveAt(i);
        }

        return true;
    }

    private bool TryRemovePackedSessionItem(PackedInstallationSession packedSession)
    {
        if (packedSession == null)
        {
            return true;
        }

        if (packedSession.packedItemStoredInHandCount > 0 && !TryRemovePackedHandItem(packedSession))
        {
            return false;
        }

        if (packedSession.packedItemStoredInInventoryCount > 0 && !TryRemovePackedInventoryItem(packedSession))
        {
            return false;
        }

        return TryRemovePackedPortables(packedSession);
    }

    private bool TryRemovePackedHandItem(PackedInstallationSession packedSession)
    {
        if (packedSession == null || packedSession.packedItemStoredInHandCount <= 0)
        {
            return true;
        }

        Player player = GameManager.Instance != null ? GameManager.Instance.Player : null;
        PlayerBag handBag = player != null ? player.GetHandBag() : GetPlayerHandBag();
        if (handBag == null
            || handBag.GetTotalItemCount(packedSession.itemId) < packedSession.packedItemStoredInHandCount
            || handBag.RemoveItems(packedSession.itemId, packedSession.packedItemStoredInHandCount)
               < packedSession.packedItemStoredInHandCount)
        {
            return false;
        }

        handBag.RefreshExternalStackCounts(false);
        player?.UpdateCarryState();
        packedSession.packedItemStoredInHandCount = 0;
        return true;
    }

    private bool TryRemovePackedInventoryItem(PackedInstallationSession packedSession)
    {
        if (packedSession == null || packedSession.packedItemStoredInInventoryCount <= 0)
        {
            return true;
        }

        PlayerBag inventoryBag = GetPlayerInventoryBag();
        if (inventoryBag == null
            || inventoryBag.GetTotalItemCount(packedSession.itemId) < packedSession.packedItemStoredInInventoryCount
            || inventoryBag.RemoveItems(packedSession.itemId, packedSession.packedItemStoredInInventoryCount)
               < packedSession.packedItemStoredInInventoryCount)
        {
            return false;
        }

        packedSession.packedItemStoredInInventoryCount = 0;
        return true;
    }

    private static int GetPackedInstallationAccountedItemCount(PackedInstallationSession packedSession)
    {
        if (packedSession == null)
        {
            return 0;
        }

        int portableDropCount = packedSession.portableDrops != null ? packedSession.portableDrops.Count : 0;
        return Mathf.Max(0, packedSession.packedItemStoredInInventoryCount)
               + Mathf.Max(0, packedSession.packedItemStoredInHandCount)
               + Mathf.Max(0, portableDropCount);
    }

    private static int GetPackedInstallationRemainingItemCount(PackedInstallationSession packedSession)
    {
        if (packedSession == null)
        {
            return 0;
        }

        return Mathf.Max(0, packedSession.itemCount - GetPackedInstallationAccountedItemCount(packedSession));
    }

    private void FinalizePackedInstallationHistory()
    {
        int packedPortableMoveIndex = 0;
        while (packedInstallationHistory.Count > 0)
        {
            PackedInstallationSession packedSession = packedInstallationHistory.Pop();
            TryStorePackedItemInPlayerStorage(packedSession, ref packedPortableMoveIndex);
            TransferPackedContentsToPlayerStorage(packedSession, ref packedPortableMoveIndex);
            ApplyPackedInstallationDroppedBlockStates(packedSession);
            int remainingPackedItemCount = GetPackedInstallationRemainingItemCount(packedSession);
            for (int i = 0; i < remainingPackedItemCount && packedSession.itemId >= 0; i++)
            {
                if (!TryDropPackedPortable(
                        packedSession.itemId,
                        packedSession.dropCoordinate,
                        out PortableObject packedPortableObject,
                        out Vector2Int packedDropCoordinate))
                {
                    break;
                }

                packedSession.portableDrops.Add(new PackedPortableDrop
                {
                    portableObject = packedPortableObject,
                    coordinate = packedDropCoordinate
                });
            }

            InstallationObject originalInstallation = packedSession?.editSession?.originalInstallation;
            if (originalInstallation == null)
            {
                continue;
            }

            TerrainGenerator terrain = ResolveInstallPreviewTerrain();
            ReleaseInstalledObjectInstance(
                originalInstallation,
                ResolveInstallationSourcePrefab(
                    packedSession.editSession.definition,
                    packedSession.editSession.originalConveyorVariantKind),
                terrain);
        }
    }

    private void TransferPackedContentsToPlayerStorage(PackedInstallationSession packedSession, ref int moveIndex)
    {
        TransferPackedBlockItemsToPlayerStorage(packedSession, ref moveIndex);
        TransferPackedRobotArmHeldItemToPlayerStorage(packedSession, ref moveIndex);
        TransferPackedStoredInstallationItemsToPlayerStorage(packedSession, ref moveIndex);
    }

    private bool TryStorePackedItemInPlayerStorage(PackedInstallationSession packedSession, ref int moveIndex)
    {
        if (packedSession == null || packedSession.itemId < 0)
        {
            return false;
        }

        int remainingItemCount = GetPackedInstallationRemainingItemCount(packedSession);
        if (remainingItemCount <= 0)
        {
            return false;
        }

        bool storedAnyItem = false;
        Vector3 startPosition = ResolvePackedItemMoveStartPosition(packedSession);
        for (int i = 0; i < remainingItemCount; i++)
        {
            if (!TryAddPackedItemToPlayerStorage(
                    packedSession.itemId,
                    startPosition,
                    ref moveIndex,
                    out PackedItemStorageTarget storageTarget))
            {
                break;
            }

            if (storageTarget == PackedItemStorageTarget.Inventory)
            {
                packedSession.packedItemStoredInInventoryCount++;
            }
            else if (storageTarget == PackedItemStorageTarget.Hand)
            {
                packedSession.packedItemStoredInHandCount++;
            }

            storedAnyItem = true;
        }

        return storedAnyItem;
    }

    private void TransferPackedBlockItemsToPlayerStorage(PackedInstallationSession packedSession, ref int moveIndex)
    {
        if (packedSession?.pendingDroppedBlockStatesByCanonicalOffset == null
            || packedSession.pendingDroppedBlockStatesByCanonicalOffset.Count <= 0)
        {
            return;
        }

        List<Vector2Int> keys = new List<Vector2Int>(packedSession.pendingDroppedBlockStatesByCanonicalOffset.Keys);
        for (int keyIndex = 0; keyIndex < keys.Count; keyIndex++)
        {
            Vector2Int key = keys[keyIndex];
            if (!packedSession.pendingDroppedBlockStatesByCanonicalOffset.TryGetValue(key, out List<int> itemIds)
                || itemIds == null
                || itemIds.Count <= 0)
            {
                continue;
            }

            Vector3 startPosition = ResolvePackedItemMoveStartPosition(packedSession, packedSession.dropCoordinate);
            for (int itemIndex = itemIds.Count - 1; itemIndex >= 0; itemIndex--)
            {
                int itemId = itemIds[itemIndex];
                if (itemId < 0 || TryAddPackedItemToPlayerStorage(itemId, startPosition, ref moveIndex))
                {
                    itemIds.RemoveAt(itemIndex);
                }
            }

            if (itemIds.Count <= 0)
            {
                packedSession.pendingDroppedBlockStatesByCanonicalOffset.Remove(key);
            }
        }
    }

    private void TransferPackedRobotArmHeldItemToPlayerStorage(PackedInstallationSession packedSession, ref int moveIndex)
    {
        RobotArm robotArm = packedSession?.editSession?.originalInstallation as RobotArm;
        if (robotArm == null || !robotArm.HasHeldItem)
        {
            return;
        }

        int itemId = robotArm.HeldItemId;
        if (itemId < 0)
        {
            return;
        }

        bool storedItem = TryAddPackedItemToPlayerStorage(itemId, robotArm.HeldItemWorldPosition, ref moveIndex)
                          || TryDropPackedFloorObject(itemId, packedSession.dropCoordinate, out _, out _);
        if (storedItem)
        {
            robotArm.TryClearHeldItemForPacking(itemId);
        }
    }

    private void TransferPackedStoredInstallationItemsToPlayerStorage(
        PackedInstallationSession packedSession,
        ref int moveIndex)
    {
        InstallationObject installation = packedSession?.editSession?.originalInstallation;
        if (installation is IPersistentInstallationItemCollectionStorage collectionStorage)
        {
            List<int> itemIds = new List<int>();
            collectionStorage.CapturePersistentStoredItemIds(itemIds);
            Vector3 collectionStartPosition = ResolvePackedItemMoveStartPosition(packedSession);
            for (int i = itemIds.Count - 1; i >= 0; i--)
            {
                int collectionItemId = itemIds[i];
                bool movedItem = collectionItemId < 0
                                 || TryAddPackedItemToPlayerStorage(
                                     collectionItemId,
                                     collectionStartPosition,
                                     ref moveIndex)
                                 || TryDropPackedFloorObject(
                                     collectionItemId,
                                     packedSession.dropCoordinate,
                                     out _,
                                     out _);
                if (movedItem)
                {
                    itemIds.RemoveAt(i);
                }
            }

            collectionStorage.ApplyPersistentStoredItemIds(itemIds);
        }

        IPersistentInstallationItemStorage itemStorage =
            installation as IPersistentInstallationItemStorage;
        int itemId = itemStorage != null ? itemStorage.PersistentStoredItemId : -1;
        if (itemId < 0)
        {
            return;
        }

        Vector3 startPosition = ResolvePackedItemMoveStartPosition(packedSession);
        bool storedItem = TryAddPackedItemToPlayerStorage(itemId, startPosition, ref moveIndex)
                          || TryDropPackedFloorObject(itemId, packedSession.dropCoordinate, out _, out _);
        if (storedItem)
        {
            itemStorage.ApplyPersistentStoredItemId(-1);
        }
    }

    private bool TryAddPackedItemToPlayerStorage(int itemId, Vector3 startPosition, ref int moveIndex)
    {
        return TryAddPackedItemToPlayerStorage(
            itemId,
            startPosition,
            ref moveIndex,
            out _);
    }

    private bool TryAddPackedItemToPlayerStorage(
        int itemId,
        Vector3 startPosition,
        ref int moveIndex,
        out PackedItemStorageTarget storageTarget)
    {
        storageTarget = PackedItemStorageTarget.None;
        if (itemId < 0)
        {
            return false;
        }

        Player player = GameManager.Instance != null ? GameManager.Instance.Player : null;
        PlayerBag inventoryBag = GetPlayerInventoryBag();
        PortableObject targetPortableObject = null;
        bool addedToInventory = player != null
            ? player.TryAddToBag(itemId, out targetPortableObject)
            : inventoryBag != null && inventoryBag.TryAddObject(itemId, out targetPortableObject);
        if (addedToInventory)
        {
            PlayPackedPortableMoveToPlayerStorage(
                itemId,
                targetPortableObject,
                startPosition,
                moveIndex * PackedPortableMoveInterval);
            moveIndex++;
            storageTarget = PackedItemStorageTarget.Inventory;
            return true;
        }

        if (player == null || !player.TryAddToHand(itemId, out targetPortableObject))
        {
            return false;
        }

        player.UpdateCarryState();
        PlayPackedPortableMoveToPlayerStorage(
            itemId,
            targetPortableObject,
            startPosition,
            moveIndex * PackedPortableMoveInterval);
        moveIndex++;
        storageTarget = PackedItemStorageTarget.Hand;
        return true;
    }

    private void PlayPackedPortableMoveToPlayerStorage(
        int itemId,
        PortableObject targetPortableObject,
        Vector3 startPosition,
        float delay)
    {
        if (targetPortableObject == null || itemId < 0)
        {
            return;
        }

        PortableObject movingPortableObject = Instantiate(
            targetPortableObject,
            startPosition,
            targetPortableObject.transform.rotation);
        if (movingPortableObject == null)
        {
            return;
        }

        movingPortableObject.name = $"{targetPortableObject.name}_PackedMove";
        movingPortableObject.transform.SetParent(null, true);
        movingPortableObject.transform.position = startPosition;
        movingPortableObject.transform.localScale = targetPortableObject.transform.lossyScale;
        if (!movingPortableObject.gameObject.activeSelf)
        {
            movingPortableObject.gameObject.SetActive(true);
        }

        if (!movingPortableObject.SetItem(itemId))
        {
            Destroy(movingPortableObject.gameObject);
            return;
        }

        Vector3 targetPosition = targetPortableObject.transform.position;
        movingPortableObject.MoveTo(
            () => targetPortableObject != null ? targetPortableObject.transform.position : targetPosition,
            Mathf.Max(0f, delay),
            () => startPosition,
            () =>
            {
                if (movingPortableObject != null)
                {
                    Destroy(movingPortableObject.gameObject);
                }
            },
            false);
    }

    private Vector3 ResolvePackedItemMoveStartPosition(PackedInstallationSession packedSession)
    {
        if (packedSession?.editSession?.originalInstallation != null)
        {
            return packedSession.editSession.originalInstallation.transform.position;
        }

        return packedSession != null
            ? ResolvePackedItemMoveStartPosition(packedSession, packedSession.dropCoordinate)
            : Vector3.zero;
    }

    private Vector3 ResolvePackedItemMoveStartPosition(PackedInstallationSession packedSession, Vector2Int coordinate)
    {
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain != null && terrain.TryGetLoadedBlock(coordinate, out Block block) && block != null)
        {
            return block.transform.position + Vector3.up * 0.35f;
        }

        if (packedSession?.editSession?.originalInstallation != null)
        {
            return packedSession.editSession.originalInstallation.transform.position;
        }

        return Vector3.zero;
    }

    private void ApplyPackedInstallationDroppedBlockStates(PackedInstallationSession packedSession)
    {
        if (packedSession?.editSession == null
            || packedSession.pendingDroppedBlockStatesByCanonicalOffset == null
            || packedSession.pendingDroppedBlockStatesByCanonicalOffset.Count <= 0)
        {
            return;
        }

        List<Vector2Int> keys = new List<Vector2Int>(packedSession.pendingDroppedBlockStatesByCanonicalOffset.Keys);
        for (int keyIndex = 0; keyIndex < keys.Count; keyIndex++)
        {
            Vector2Int key = keys[keyIndex];
            if (!packedSession.pendingDroppedBlockStatesByCanonicalOffset.TryGetValue(key, out List<int> droppedItemIds)
                || droppedItemIds == null
                || droppedItemIds.Count <= 0)
            {
                continue;
            }

            for (int itemIndex = 0; itemIndex < droppedItemIds.Count; itemIndex++)
            {
                int itemId = droppedItemIds[itemIndex];
                if (itemId < 0)
                {
                    continue;
                }

                TryDropPackedFloorObject(itemId, packedSession.dropCoordinate, out _, out _);
            }

            droppedItemIds.Clear();
            packedSession.pendingDroppedBlockStatesByCanonicalOffset.Remove(key);
        }
    }

    private bool TryDropPackedFloorObject(int itemId, Vector2Int preferredCoordinate, out PortableObject portableObject, out Vector2Int dropCoordinate)
    {
        portableObject = null;
        dropCoordinate = preferredCoordinate;

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null || itemId < 0)
        {
            return false;
        }

        const int maxSearchRadius = 2;
        for (int radius = 0; radius <= maxSearchRadius; radius++)
        {
            for (int offsetY = -radius; offsetY <= radius; offsetY++)
            {
                for (int offsetX = -radius; offsetX <= radius; offsetX++)
                {
                    if (radius > 0 && Mathf.Abs(offsetX) != radius && Mathf.Abs(offsetY) != radius)
                    {
                        continue;
                    }

                    Vector2Int coordinate = preferredCoordinate + new Vector2Int(offsetX, offsetY);
                    if (!terrain.TryGetLoadedBlock(coordinate, out Block block) || block == null || block.Type != Block.BlockType.Ground)
                    {
                        continue;
                    }

                    if (!block.TryAddFloorObject(itemId, out portableObject))
                    {
                        continue;
                    }

                    dropCoordinate = coordinate;
                    return true;
                }
            }
        }

        return false;
    }

    private void RestorePackedInstallationHistory()
    {
        while (packedInstallationHistory.Count > 0)
        {
            PackedInstallationSession packedSession = packedInstallationHistory.Pop();
            if (packedSession?.editSession == null)
            {
                continue;
            }

            TryRemovePackedSessionItem(packedSession);
            RestoreEditedInstallation(
                packedSession.editSession,
                packedSession.anchorCoordinate,
                packedSession.quarterTurns);
        }
    }

    private void HandleInstallButtonClicked()
    {
        SetMapEditModeActive(false);

        if (!TryGetHandInstallationDefinition(out ItemDefinition definition) || definition == null || definition.mapObject == null)
        {
            ClearInstallPreview();
            return;
        }

        if (IsInstallationModeActive() && activeInstallDefinition == definition)
        {
            ClearInstallPreview();
            return;
        }

        if (definition.mapObject is Railload)
        {
            BeginRailloadInstallPreview(definition);
            return;
        }

        BeginInstallPreview(definition);
    }

    private void HandleInstallCancelClicked()
    {
        if (IsEditingInstallation())
        {
            CancelInstallationEdit();
            RestorePackedInstallationHistory();
            SetMapEditModeActive(false);
            return;
        }

        if (mapEditModeActive)
        {
            RestorePackedInstallationHistory();
            SetMapEditModeActive(false);
            return;
        }

        ClearInstallPreview();
    }

    private bool BeginInstallationEdit(
        InstallationObject installationObject,
        Vector2Int? selectedCoordinate = null)
    {
        if (installationObject == null
            || ShouldSelectOnlyInMapEdit(installationObject)
            || !TryCreateInstallationEditSession(
                installationObject,
                out InstallationEditSession editSession,
                selectedCoordinate))
        {
            return false;
        }

        if (HasInstallPreviewState())
        {
            ClearInstallPreview();
        }

        activeInstallationEditSession = editSession;
        ClearEditableInstallationSelection();
        DetachInstallationForEditing(editSession);
        BeginInstallationEditPreview(editSession);
        return activeInstallPreview != null;
    }

    private bool HasInstallPreviewState()
    {
        return activeInstallDefinition != null
               || activeInstallPreview != null
               || installPreviewInstances.Count > 0
               || installPreviewItemReservationsByPreview.Count > 0
               || installedFenceVariantPreviews.Count > 0
               || installedPipeVariantPreviews.Count > 0;
    }

    private bool TryCreateInstallationEditSession(
        InstallationObject installationObject,
        out InstallationEditSession editSession,
        Vector2Int? selectedCoordinate = null)
    {
        editSession = null;
        if (installationObject == null || !installationObject.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out int runtimeQuarterTurns))
        {
            return false;
        }

        if (!TryGetInstallationDefinitionForEditableObject(installationObject, out ItemDefinition definition)
            || definition == null
            || definition.mapObject == null)
        {
            return false;
        }

        int resolvedQuarterTurns = ResolveInstallationEditQuarterTurns(
            installationObject,
            definition,
            anchorCoordinate,
            runtimeQuarterTurns);

        editSession = new InstallationEditSession
        {
            originalInstallation = installationObject,
            definition = definition,
            originalAnchorCoordinate = anchorCoordinate,
            originalQuarterTurns = resolvedQuarterTurns,
            originalRotation = installationObject.transform.rotation,
            originalConveyorVariantKind = GetInstallationVariantKind(installationObject),
            originalRailRequiredItemCount = installationObject is Railload railload
                ? railload.RequiredItemCount
                : 0,
            originalOccupiedCoordinates = new List<Vector2Int>(installationObject.RuntimeOccupiedCoordinates)
        };
        if (installationObject is UndergroundPipe undergroundPipe
            && undergroundPipe.TryGetPairCoordinates(
                out Vector2Int firstEndpoint,
                out Vector2Int secondEndpoint))
        {
            Vector2Int movingEndpoint = selectedCoordinate.HasValue
                                        && selectedCoordinate.Value == secondEndpoint
                ? secondEndpoint
                : firstEndpoint;
            editSession.editsUndergroundPipeEndpoint = true;
            editSession.originalMovingEndpointCoordinate = movingEndpoint;
            editSession.fixedUndergroundEndpointCoordinate = movingEndpoint == firstEndpoint
                ? secondEndpoint
                : firstEndpoint;
        }
        editSession.originalStateCoordinates = GetInstallationEditStateCoordinates(
            editSession,
            editSession.originalAnchorCoordinate,
            editSession.originalQuarterTurns);

        if (installationObject is InputOutputModule inputOutputModule)
        {
            editSession.inputOutputState = inputOutputModule.CapturePersistentState();
        }

        if (installationObject is BoxObject boxObject)
        {
            editSession.boxIsOpen = boxObject.IsOpen;
        }

        editSession.itemFilterMaskInitialized = installationObject.IsItemFilterMaskInitialized;
        editSession.itemFilterMaskWords = installationObject.CaptureItemFilterMaskWords();
        editSession.storedFluidLiters = installationObject.StoredFluidLiters;
        editSession.storedFluidItemId = installationObject.StoredFluidItemId;
        editSession.storedFluidTemperatureCelsius =
            installationObject.GetStoredFluidTemperatureCelsius(editSession.storedFluidItemId);
        if (installationObject is IPersistentInstallationItemStorage itemStorage)
        {
            editSession.storedInstallationItemId = itemStorage.PersistentStoredItemId;
        }
        if (installationObject is IPersistentInstallationItemCollectionStorage collectionStorage)
        {
            collectionStorage.CapturePersistentStoredItemIds(editSession.storedInstallationItemIds);
        }

        CaptureAttachedAreaBoxes(editSession);
        CaptureInstallationBlockStates(editSession);
        return true;
    }

    private List<Vector2Int> GetInstallationEditStateCoordinates(
        InstallationEditSession editSession,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        if (editSession == null)
        {
            return new List<Vector2Int>();
        }

        if (editSession.editsUndergroundPipeEndpoint)
        {
            return new List<Vector2Int>(editSession.originalOccupiedCoordinates);
        }

        MapObject footprintSource = editSession.definition != null && editSession.definition.mapObject != null
            ? editSession.definition.mapObject
            : editSession.originalInstallation;
        List<Vector2Int> coordinates = GetFootprintCoordinates(anchorCoordinate, footprintSource, quarterTurns);
        if (ShouldSkipBelt2FBridgeCenterBinding(anchorCoordinate, footprintSource, quarterTurns, out Vector2Int bridgeCenterCoordinate))
        {
            coordinates.Remove(bridgeCenterCoordinate);
        }

        return coordinates;
    }

    private void CaptureAttachedAreaBoxes(InstallationEditSession editSession)
    {
        if (editSession == null)
        {
            return;
        }

        editSession.attachedAreaBoxes.Clear();
    }

    private bool TryCaptureAttachedAreaBox(
        InstallationEditSession editSession,
        BoxObject boxObject,
        out AreaAttachedBoxState boxState)
    {
        boxState = null;
        if (editSession == null
            || boxObject == null
            || boxObject == editSession.originalInstallation
            || !boxObject.TryGetPlacementRuntime(out Vector2Int boxAnchorCoordinate, out int boxRuntimeQuarterTurns))
        {
            return false;
        }

        ItemDefinition boxDefinition = null;
        int boxItemId = boxObject.ResolveItemId();
        TryGetInstallationDefinition(boxItemId, out boxDefinition);
        int boxQuarterTurns = boxDefinition != null
            ? ResolveInstallationEditQuarterTurns(boxObject, boxDefinition, boxAnchorCoordinate, boxRuntimeQuarterTurns)
            : NormalizePlacementQuarterTurns(boxRuntimeQuarterTurns);

        Vector2Int worldOffset = boxAnchorCoordinate - editSession.originalAnchorCoordinate;
        boxState = new AreaAttachedBoxState
        {
            boxObject = boxObject,
            definition = boxDefinition,
            originalAnchorCoordinate = boxAnchorCoordinate,
            originalQuarterTurns = boxQuarterTurns,
            originalRotation = boxObject.transform.rotation,
            canonicalAnchorOffset = RotateFootprintOffset(worldOffset, -editSession.originalQuarterTurns),
            boxIsOpen = boxObject.IsOpen,
            itemFilterMaskInitialized = boxObject.IsItemFilterMaskInitialized,
            itemFilterMaskWords = boxObject.CaptureItemFilterMaskWords()
        };
        return true;
    }

    private void CaptureInstallationBlockStates(InstallationEditSession editSession)
    {
        editSession.blockStatesByCanonicalOffset.Clear();

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null || editSession.originalStateCoordinates == null)
        {
            return;
        }

        for (int i = 0; i < editSession.originalStateCoordinates.Count; i++)
        {
            Vector2Int stateCoordinate = editSession.originalStateCoordinates[i];
            if (!terrain.TryGetLoadedBlock(stateCoordinate, out Block block) || block == null)
            {
                continue;
            }

            List<int> blockState = block.CaptureFloorObjectState();
            if (!CoordinateListContains(editSession.originalOccupiedCoordinates, stateCoordinate))
            {
                if (block.MapObject is BoxObject)
                {
                    continue;
                }

                blockState = FilterInternalObjectState(blockState);
            }

            if (blockState == null || blockState.Count <= 0)
            {
                continue;
            }

            Vector2Int worldOffset = stateCoordinate - editSession.originalAnchorCoordinate;
            Vector2Int canonicalOffset = RotateFootprintOffset(worldOffset, -editSession.originalQuarterTurns);
            editSession.blockStatesByCanonicalOffset[canonicalOffset] = new List<int>(blockState);
        }
    }

    private Dictionary<Vector2Int, List<int>> BuildPackedInstallationDroppedBlockStates(InstallationEditSession editSession)
    {
        Dictionary<Vector2Int, List<int>> droppedStatesByCanonicalOffset = new Dictionary<Vector2Int, List<int>>();
        if (editSession == null || editSession.blockStatesByCanonicalOffset == null || editSession.blockStatesByCanonicalOffset.Count <= 0)
        {
            return droppedStatesByCanonicalOffset;
        }

        List<Vector2Int> keys = new List<Vector2Int>(editSession.blockStatesByCanonicalOffset.Keys);
        for (int keyIndex = 0; keyIndex < keys.Count; keyIndex++)
        {
            Vector2Int key = keys[keyIndex];
            if (!editSession.blockStatesByCanonicalOffset.TryGetValue(key, out List<int> blockState) || blockState == null || blockState.Count <= 0)
            {
                continue;
            }

            List<int> droppedItemIds = ExtractPackedItemSlotIds(blockState);

            if (droppedItemIds.Count > 0)
            {
                droppedStatesByCanonicalOffset[key] = droppedItemIds;
            }
        }

        return droppedStatesByCanonicalOffset;
    }

    private static List<int> ExtractPackedItemSlotIds(IReadOnlyList<int> blockState)
    {
        List<int> itemIds = new List<int>();
        if (blockState == null || blockState.Count <= 0)
        {
            return itemIds;
        }

        for (int i = 0; i < blockState.Count; i++)
        {
            int stateToken = blockState[i];
            if (stateToken == Block.InputAreaCenterStackStateSentinel)
            {
                AddPackedSequentialItemIds(blockState, ref i, itemIds);
                continue;
            }

            if (stateToken == Block.ConveyorStackStateSentinel)
            {
                AddPackedSequentialItemIds(blockState, ref i, itemIds);
                continue;
            }

            if (stateToken == Block.FloorStackStateSentinel)
            {
                SkipPackedFloorStackState(blockState, ref i);
            }
        }

        return itemIds;
    }

    private static void AddPackedSequentialItemIds(IReadOnlyList<int> blockState, ref int index, List<int> itemIds)
    {
        if (blockState == null || itemIds == null || index + 1 >= blockState.Count)
        {
            return;
        }

        int itemCount = Mathf.Max(0, blockState[++index]);
        for (int itemIndex = 0; itemIndex < itemCount && index + 1 < blockState.Count; itemIndex++)
        {
            int itemId = blockState[++index];
            if (itemId >= 0)
            {
                itemIds.Add(itemId);
            }
        }
    }

    private static void SkipPackedFloorStackState(IReadOnlyList<int> blockState, ref int index)
    {
        if (blockState == null || index + 1 >= blockState.Count)
        {
            return;
        }

        int stackCount = Mathf.Max(0, blockState[++index]);
        for (int stackIndex = 0; stackIndex < stackCount && index + 1 < blockState.Count; stackIndex++)
        {
            int stackItemCount = Mathf.Max(0, blockState[++index]);
            index = Mathf.Min(blockState.Count - 1, index + stackItemCount);
        }
    }

    private static List<int> CaptureExternalFloorObjectState(Block block)
    {
        return block != null
            ? FilterFloorObjectState(block.CaptureFloorObjectState(), true, false, false)
            : null;
    }

    private static List<int> FilterInternalObjectState(IReadOnlyList<int> blockState)
    {
        return FilterFloorObjectState(blockState, false, true, true);
    }

    private static List<int> MergeExternalFloorObjectState(Block block, IReadOnlyList<int> internalState)
    {
        List<int> externalState = CaptureExternalFloorObjectState(block);
        if ((externalState == null || externalState.Count <= 0)
            && (internalState == null || internalState.Count <= 0))
        {
            return null;
        }

        List<int> mergedState = new List<int>(
            (externalState != null ? externalState.Count : 0)
            + (internalState != null ? internalState.Count : 0));
        if (externalState != null)
        {
            mergedState.AddRange(externalState);
        }

        if (internalState != null)
        {
            mergedState.AddRange(internalState);
        }

        return mergedState;
    }

    private static List<int> FilterFloorObjectState(
        IReadOnlyList<int> blockState,
        bool includeFloorStack,
        bool includeInputAreaCenterStack,
        bool includeConveyorStack)
    {
        if (blockState == null || blockState.Count <= 0)
        {
            return null;
        }

        List<int> filteredState = new List<int>(blockState.Count);
        for (int i = 0; i < blockState.Count; i++)
        {
            int stateToken = blockState[i];
            if (stateToken == Block.FloorStackStateSentinel)
            {
                CopyOrSkipFloorStackState(blockState, ref i, filteredState, includeFloorStack);
                continue;
            }

            if (stateToken == Block.InputAreaCenterStackStateSentinel)
            {
                CopyOrSkipSequentialState(blockState, ref i, filteredState, includeInputAreaCenterStack);
                continue;
            }

            if (stateToken == Block.ConveyorStackStateSentinel)
            {
                CopyOrSkipSequentialState(blockState, ref i, filteredState, includeConveyorStack);
                continue;
            }

            if (includeFloorStack && stateToken >= 0)
            {
                filteredState.Add(stateToken);
            }
        }

        return filteredState.Count > 0 ? filteredState : null;
    }

    private static void CopyOrSkipFloorStackState(
        IReadOnlyList<int> blockState,
        ref int index,
        List<int> target,
        bool copy)
    {
        if (blockState == null || index + 1 >= blockState.Count)
        {
            return;
        }

        int stackCount = Mathf.Max(0, blockState[++index]);
        if (copy)
        {
            target.Add(Block.FloorStackStateSentinel);
            target.Add(stackCount);
        }

        for (int stackIndex = 0; stackIndex < stackCount && index + 1 < blockState.Count; stackIndex++)
        {
            int stackItemCount = Mathf.Max(0, blockState[++index]);
            if (copy)
            {
                target.Add(stackItemCount);
            }

            for (int objectIndex = 0; objectIndex < stackItemCount && index + 1 < blockState.Count; objectIndex++)
            {
                int itemId = blockState[++index];
                if (copy)
                {
                    target.Add(itemId);
                }
            }
        }
    }

    private static void CopyOrSkipSequentialState(
        IReadOnlyList<int> blockState,
        ref int index,
        List<int> target,
        bool copy)
    {
        if (blockState == null || index + 1 >= blockState.Count)
        {
            return;
        }

        int stateToken = blockState[index];
        int itemCount = Mathf.Max(0, blockState[++index]);
        if (copy)
        {
            target.Add(stateToken);
            target.Add(itemCount);
        }

        for (int itemIndex = 0; itemIndex < itemCount && index + 1 < blockState.Count; itemIndex++)
        {
            int itemId = blockState[++index];
            if (copy)
            {
                target.Add(itemId);
            }
        }
    }

    private void DetachInstallationForEditing(InstallationEditSession editSession, bool preserveConveyorItemsOnGround = false)
    {
        if (editSession == null || editSession.originalInstallation == null)
        {
            return;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        terrain?.RemoveInstallationPersistence(editSession.originalInstallation);
        DetachAttachedAreaBoxes(editSession, terrain);

        List<Vector2Int> stateCoordinates = editSession.originalStateCoordinates != null && editSession.originalStateCoordinates.Count > 0
            ? editSession.originalStateCoordinates
            : editSession.originalOccupiedCoordinates;
        for (int i = 0; i < stateCoordinates.Count; i++)
        {
            if (terrain == null || !terrain.TryGetLoadedBlock(stateCoordinates[i], out Block block) || block == null)
            {
                continue;
            }

            bool isOriginalOccupiedCoordinate = CoordinateListContains(
                editSession.originalOccupiedCoordinates,
                stateCoordinates[i]);
            bool preservesAreaBoxContents = !isOriginalOccupiedCoordinate
                                            && block.MapObject is BoxObject;
            if (preservesAreaBoxContents)
            {
                continue;
            }

            IReadOnlyList<int> detachedFloorState = preserveConveyorItemsOnGround
                ? block.CaptureFloorObjectStateWithDroppedConveyorObjects()
                : !isOriginalOccupiedCoordinate
                    ? CaptureExternalFloorObjectState(block)
                : null;

            if (block.MapObject == editSession.originalInstallation || IsAttachedAreaBox(editSession, block.MapObject))
            {
                block.SetMapObject(null);
            }

            block.ApplyFloorObjectState(detachedFloorState);
        }

        editSession.originalInstallation.gameObject.SetActive(false);
    }

    private void PreserveAttachedAreaBoxesForPacking(InstallationEditSession editSession)
    {
        if (editSession?.attachedAreaBoxes == null || editSession.attachedAreaBoxes.Count <= 0)
        {
            return;
        }

        RestoreAttachedAreaBoxes(
            editSession,
            editSession.originalAnchorCoordinate,
            editSession.originalQuarterTurns,
            ResolveInstallPreviewTerrain());
        editSession.attachedAreaBoxes.Clear();
    }

    private void DetachAttachedAreaBoxes(InstallationEditSession editSession, TerrainGenerator terrain)
    {
        if (editSession?.attachedAreaBoxes == null || editSession.attachedAreaBoxes.Count <= 0)
        {
            return;
        }

        for (int i = 0; i < editSession.attachedAreaBoxes.Count; i++)
        {
            AreaAttachedBoxState boxState = editSession.attachedAreaBoxes[i];
            if (boxState?.boxObject == null)
            {
                continue;
            }

            terrain?.RemoveInstallationPersistence(boxState.originalAnchorCoordinate);
            MapObject footprintSource = boxState.definition != null && boxState.definition.mapObject != null
                ? boxState.definition.mapObject
                : boxState.boxObject;
            List<Vector2Int> boxCoordinates = GetFootprintCoordinates(
                boxState.originalAnchorCoordinate,
                footprintSource,
                boxState.originalQuarterTurns);
            for (int coordinateIndex = 0; coordinateIndex < boxCoordinates.Count; coordinateIndex++)
            {
                if (terrain != null
                    && terrain.TryGetLoadedBlock(boxCoordinates[coordinateIndex], out Block block)
                    && block != null
                    && block.MapObject == boxState.boxObject)
                {
                    block.SetMapObject(null);
                }
            }

            boxState.boxObject.gameObject.SetActive(false);
        }
    }

    private bool IsAttachedAreaBox(InstallationEditSession editSession, MapObject mapObject)
    {
        if (editSession?.attachedAreaBoxes == null || !(mapObject is BoxObject boxObject))
        {
            return false;
        }

        for (int i = 0; i < editSession.attachedAreaBoxes.Count; i++)
        {
            AreaAttachedBoxState boxState = editSession.attachedAreaBoxes[i];
            if (boxState != null && boxState.boxObject == boxObject)
            {
                return true;
            }
        }

        return false;
    }

    private void BeginInstallationEditPreview(InstallationEditSession editSession)
    {
        activeInstallDefinition = editSession.definition;
        activeInstallPreview = null;
        MapObject previewSourcePrefab = editSession.definition.mapObject;
        if (editSession.definition.mapObject is Wall fencePrototype && editSession.originalConveyorVariantKind >= 0)
        {
            previewSourcePrefab = ResolveFenceVariantPrefab(fencePrototype, editSession.originalConveyorVariantKind)
                ?? editSession.definition.mapObject;
        }
        else if (editSession.definition.mapObject is Pipe pipePrototype
                 && !(pipePrototype is UndergroundPipe)
                 && editSession.originalConveyorVariantKind >= 0)
        {
            previewSourcePrefab = ResolvePipeVariantPrefab(pipePrototype, editSession.originalConveyorVariantKind)
                ?? editSession.definition.mapObject;
        }
        else if (editSession.definition.mapObject is ConveyorBelt conveyorPrototype && editSession.originalConveyorVariantKind >= 0)
        {
            previewSourcePrefab = ResolveConveyorVariantPrefab(conveyorPrototype, editSession.originalConveyorVariantKind)
                ?? editSession.definition.mapObject;
        }

        activeInstallBaseRotation = previewSourcePrefab != null
            ? previewSourcePrefab.transform.rotation
            : Quaternion.identity;
        installPreviewQuarterTurns = editSession.originalQuarterTurns;
        installPreviewConveyorVariantMode = editSession.originalConveyorVariantKind > 0
            ? ConveyorPreviewVariantMode.Corner
            : ConveyorPreviewVariantMode.Straight;
        waitForPointerReleaseAfterPreviewSpawn = true;
        GameManager.Instance?.SetInstallationPlacementActive(true);

        MapObject preview = CreateInstallPreviewInstance(previewSourcePrefab, editSession.definition != null ? editSession.definition.mapObject : null);
        if (preview == null)
        {
            CancelInstallationEdit();
            return;
        }

        if (preview is InstallationObject installationPreview)
        {
            installationPreview.SetStoredFluid(
                editSession.storedFluidItemId,
                editSession.storedFluidLiters,
                editSession.storedFluidTemperatureCelsius);
        }

        RegisterInstallPreview(preview, editSession.originalQuarterTurns);

        Vector2Int editPreviewAnchorCoordinate = editSession.editsUndergroundPipeEndpoint
            ? editSession.originalMovingEndpointCoordinate
            : editSession.originalAnchorCoordinate;
        installPreviewAnchorCoordinates[preview] = editPreviewAnchorCoordinate;
        SelectInstallPreview(preview, false, false);
        installPreviewConveyorVariantMode = editSession.originalConveyorVariantKind > 0
            ? ConveyorPreviewVariantMode.Corner
            : ConveyorPreviewVariantMode.Straight;

        MapObject editPlacementSource = ResolveInstallPreviewPlacementSource(activeInstallPreview);
        if (ResolveInstallPreviewTerrain() != null
            && ResolveInstallPreviewTerrain().TryGetLoadedBlock(editPreviewAnchorCoordinate, out Block anchorBlock)
            && anchorBlock != null)
        {
            activeInstallPreview.transform.position = ResolvePlacementWorldPosition(
                anchorBlock,
                editPlacementSource,
                editSession.originalQuarterTurns);
        }
        else
        {
            activeInstallPreview.transform.position = ResolvePlacementWorldPosition(
                editPreviewAnchorCoordinate,
                editPlacementSource,
                editSession.originalQuarterTurns);
        }

        activeInstallPreview.transform.rotation = editSession.originalInstallation is Wall
                                                || editSession.originalInstallation is Pipe
            ? GetInstallPreviewRotation()
            : editSession.originalRotation;
        SetInstallPreviewQuarterTurns(activeInstallPreview, editSession.originalQuarterTurns);
        SetInstallPreviewSelectionVisual(activeInstallPreview, true);

        if (activeInstallPreview is UndergroundPipe undergroundPipePreview
            && editSession.editsUndergroundPipeEndpoint)
        {
            TerrainGenerator terrain = ResolveInstallPreviewTerrain();
            Block movingBlock = null;
            Block fixedBlock = null;
            if (terrain != null)
            {
                terrain.TryGetLoadedBlock(editSession.originalMovingEndpointCoordinate, out movingBlock);
                terrain.TryGetLoadedBlock(editSession.fixedUndergroundEndpointCoordinate, out fixedBlock);
            }
            ConfigureUndergroundPipePreviewCandidate(
                undergroundPipePreview,
                editSession.originalMovingEndpointCoordinate,
                editSession.fixedUndergroundEndpointCoordinate,
                movingBlock,
                fixedBlock,
                true,
                true);
            int undergroundQuarterTurns = ResolveUndergroundPipeQuarterTurns(
                editSession.originalMovingEndpointCoordinate,
                editSession.fixedUndergroundEndpointCoordinate);
            SetInstallPreviewQuarterTurns(activeInstallPreview, undergroundQuarterTurns);
        }

        RefreshUtilityPolePreviewWires();
        RefreshInstallPreviewAreaMarkers(activeInstallPreview);
        RefreshPipePreviewVariantsAroundActivePreview(null);
        InvalidateInstallGrid();
    }

    private bool HasInstallationEditPlacementChanged(
        InstallationEditSession editSession,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        int conveyorVariantKind)
    {
        return HasInstallationEditPositionChanged(editSession, anchorCoordinate)
               || HasInstallationEditRotationChanged(editSession, quarterTurns)
               || HasInstallationEditVariantChanged(editSession, conveyorVariantKind);
    }

    private bool IsSimpleInstallationEditTransformChange(
        InstallationEditSession editSession,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        int conveyorVariantKind)
    {
        return !HasInstallationEditVariantChanged(editSession, conveyorVariantKind)
               && (HasInstallationEditPositionChanged(editSession, anchorCoordinate)
                   || HasInstallationEditRotationChanged(editSession, quarterTurns));
    }

    private static bool HasInstallationEditPositionChanged(InstallationEditSession editSession, Vector2Int anchorCoordinate)
    {
        if (editSession == null)
        {
            return false;
        }

        Vector2Int originalCoordinate = editSession.editsUndergroundPipeEndpoint
            ? editSession.originalMovingEndpointCoordinate
            : editSession.originalAnchorCoordinate;
        return anchorCoordinate != originalCoordinate;
    }

    private bool HasInstallationEditRotationChanged(InstallationEditSession editSession, int quarterTurns)
    {
        if (editSession == null)
        {
            return false;
        }

        MapObject sourcePrefab = editSession.definition != null ? editSession.definition.mapObject : null;
        return NormalizePlacementQuarterTurnsForObject(sourcePrefab, quarterTurns)
               != NormalizePlacementQuarterTurnsForObject(sourcePrefab, editSession.originalQuarterTurns);
    }

    private static bool HasInstallationEditVariantChanged(InstallationEditSession editSession, int variantKind)
    {
        return editSession != null && variantKind != editSession.originalConveyorVariantKind;
    }

    private int ResolveInstallationEditQuarterTurns(
        InstallationObject installationObject,
        ItemDefinition definition,
        Vector2Int anchorCoordinate,
        int runtimeQuarterTurns)
    {
        int normalizedRuntimeQuarterTurns = ((runtimeQuarterTurns % 4) + 4) % 4;
        if (installationObject == null || definition == null)
        {
            return normalizedRuntimeQuarterTurns;
        }

        MapObject sourcePrefab = definition.mapObject;
        if (installationObject is Wall installedFence && definition.mapObject is Wall fencePrototype)
        {
            sourcePrefab = ResolveFenceVariantPrefab(fencePrototype, GetFenceVariantKind(installedFence))
                ?? definition.mapObject;
        }
        else if (installationObject is Pipe installedPipe && definition.mapObject is Pipe pipePrototype)
        {
            sourcePrefab = ResolvePipeVariantPrefab(pipePrototype, GetPipeVariantKind(installedPipe))
                ?? definition.mapObject;
        }
        else if (installationObject is ConveyorBelt installedConveyor && definition.mapObject is ConveyorBelt conveyorPrototype)
        {
            sourcePrefab = ResolveConveyorVariantPrefab(conveyorPrototype, GetConveyorVariantKind(installedConveyor))
                ?? definition.mapObject;
        }

        if (sourcePrefab == null)
        {
            return normalizedRuntimeQuarterTurns;
        }

        if (UsesTwoStatePlacementRotation(sourcePrefab))
        {
            return ResolveTwoStateQuarterTurnsFromRotation(
                sourcePrefab,
                installationObject.transform.rotation,
                normalizedRuntimeQuarterTurns);
        }

        int candidateCount = GetPlacementRotationCandidateCount(sourcePrefab);
        for (int candidateQuarterTurns = 0; candidateQuarterTurns < candidateCount; candidateQuarterTurns++)
        {
            Quaternion candidateRotation = GetPlacementObjectRotation(sourcePrefab, candidateQuarterTurns);
            if (Mathf.Abs(Quaternion.Dot(candidateRotation, installationObject.transform.rotation)) >= 0.9999f)
            {
                return candidateQuarterTurns;
            }
        }

        return NormalizePlacementQuarterTurnsForObject(sourcePrefab, normalizedRuntimeQuarterTurns);
    }

    private void CancelInstallationEdit()
    {
        InstallationEditSession editSession = activeInstallationEditSession;
        activeInstallationEditSession = null;

        if (editSession != null)
        {
            RestoreEditedInstallation(
                editSession,
                editSession.editsUndergroundPipeEndpoint
                    ? editSession.originalMovingEndpointCoordinate
                    : editSession.originalAnchorCoordinate,
                editSession.originalQuarterTurns,
                editSession.originalConveyorVariantKind,
                editSession.originalRotation);
        }

        ClearInstallPreview();
    }

    private void CompleteInstallationEdit()
    {
        TryCompleteInstallationEdit();
    }

    private bool TryCompleteInstallationEdit()
    {
        InstallationEditSession editSession = activeInstallationEditSession;
        if (editSession == null)
        {
            ClearInstallPreview();
            SetMapEditModeActive(false);
            return true;
        }

        CleanupInstallPreviewReferences();
        if (activeInstallPreview == null || !TryGetPreviewAnchorCoordinate(activeInstallPreview, out Vector2Int anchorCoordinate))
        {
            CancelInstallationEdit();
            return false;
        }

        if (editSession.editsUndergroundPipeEndpoint
            && activeInstallPreview is UndergroundPipe undergroundPipePreview
            && !TryResolveCommittedUndergroundPipeEditCoordinate(
                editSession,
                undergroundPipePreview,
                out anchorCoordinate))
        {
            InvalidateInstallGrid();
            return false;
        }

        Quaternion previewRotation = activeInstallPreview.transform.rotation;
        Vector3 previewPosition = activeInstallPreview.transform.position;
        int quarterTurns = GetPreviewQuarterTurns(activeInstallPreview);
        int conveyorVariantKind = GetInstallationVariantKind(activeInstallPreview);
        if (!CanRestoreEditedInstallationAt(
                editSession,
                anchorCoordinate,
                quarterTurns,
                conveyorVariantKind,
                activeInstallPreview))
        {
            InvalidateInstallGrid();
            return false;
        }

        activeInstallationEditSession = null;
        MapObject restoredObject = RestoreEditedInstallation(
            editSession,
            anchorCoordinate,
            quarterTurns,
            conveyorVariantKind,
            previewRotation,
            previewPosition);
        if (restoredObject != null)
        {
            RememberLastInstalledRotation(editSession.definition, quarterTurns);
        }

        if (!IsSimpleInstallationEditTransformChange(
                editSession,
                anchorCoordinate,
                quarterTurns,
                conveyorVariantKind))
        {
            PlayInstallationEditCompleteAnimation(restoredObject, editSession);
        }

        ClearInstallPreview();
        SetMapEditModeActive(false);
        return true;
    }

    private bool CanRestoreEditedInstallationAt(
        InstallationEditSession editSession,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        int conveyorVariantKind,
        MapObject previewToIgnore)
    {
        if (editSession != null
            && editSession.editsUndergroundPipeEndpoint
            && previewToIgnore is UndergroundPipe undergroundPipePreview)
        {
            return TryResolveCommittedUndergroundPipeEditCoordinate(
                       editSession,
                       undergroundPipePreview,
                       out Vector2Int committedMovingCoordinate)
                   && committedMovingCoordinate == anchorCoordinate;
        }

        if (!TryResolveEditedInstallationFootprintSource(
                editSession,
                anchorCoordinate,
                quarterTurns,
                conveyorVariantKind,
                previewToIgnore,
                out MapObject footprintSource))
        {
            return false;
        }

        if (!TryGetFootprintBlocks(anchorCoordinate, footprintSource, quarterTurns, previewToIgnore, out _))
        {
            return false;
        }

        return CanRestoreAttachedAreaBoxesAt(editSession, anchorCoordinate, quarterTurns);
    }

    private static bool TryResolveCommittedUndergroundPipeEditCoordinate(
        InstallationEditSession editSession,
        UndergroundPipe preview,
        out Vector2Int movingCoordinate)
    {
        movingCoordinate = default;
        if (editSession == null
            || !editSession.editsUndergroundPipeEndpoint
            || preview == null
            || !preview.IsPreviewPairCommitted
            || !preview.TryGetPairCoordinates(
                out Vector2Int firstCoordinate,
                out Vector2Int secondCoordinate))
        {
            return false;
        }

        Vector2Int fixedCoordinate = editSession.fixedUndergroundEndpointCoordinate;
        if (secondCoordinate == fixedCoordinate)
        {
            movingCoordinate = firstCoordinate;
            return true;
        }

        if (firstCoordinate == fixedCoordinate)
        {
            movingCoordinate = secondCoordinate;
            return true;
        }

        return false;
    }

    private bool CanRestoreAttachedAreaBoxesAt(
        InstallationEditSession editSession,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        if (editSession?.attachedAreaBoxes == null || editSession.attachedAreaBoxes.Count <= 0)
        {
            return true;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        HashSet<MapObject> movingObjects = new HashSet<MapObject>();
        if (editSession.originalInstallation != null)
        {
            movingObjects.Add(editSession.originalInstallation);
        }

        for (int i = 0; i < editSession.attachedAreaBoxes.Count; i++)
        {
            if (editSession.attachedAreaBoxes[i]?.boxObject != null)
            {
                movingObjects.Add(editSession.attachedAreaBoxes[i].boxObject);
            }
        }

        for (int i = 0; i < editSession.attachedAreaBoxes.Count; i++)
        {
            AreaAttachedBoxState boxState = editSession.attachedAreaBoxes[i];
            if (boxState?.boxObject == null)
            {
                continue;
            }

            Vector2Int targetAnchorCoordinate = GetMovedAttachedBoxAnchorCoordinate(
                editSession,
                boxState,
                anchorCoordinate,
                quarterTurns);
            int targetQuarterTurns = GetMovedAttachedBoxQuarterTurns(editSession, boxState, quarterTurns);
            MapObject footprintSource = boxState.definition != null && boxState.definition.mapObject != null
                ? boxState.definition.mapObject
                : boxState.boxObject;
            List<Vector2Int> boxCoordinates = GetFootprintCoordinates(targetAnchorCoordinate, footprintSource, targetQuarterTurns);
            for (int coordinateIndex = 0; coordinateIndex < boxCoordinates.Count; coordinateIndex++)
            {
                if (!terrain.TryGetLoadedBlock(boxCoordinates[coordinateIndex], out Block block) || block == null)
                {
                    return false;
                }

                MapObject occupyingObject = GetBlockingMapObject(block);
                if (occupyingObject != null && !movingObjects.Contains(occupyingObject))
                {
                    return false;
                }
            }
        }

        return true;
    }

    private Vector2Int GetMovedAttachedBoxAnchorCoordinate(
        InstallationEditSession editSession,
        AreaAttachedBoxState boxState,
        Vector2Int newAnchorCoordinate,
        int newQuarterTurns)
    {
        if (editSession == null || boxState == null)
        {
            return newAnchorCoordinate;
        }

        return newAnchorCoordinate + RotateFootprintOffset(boxState.canonicalAnchorOffset, newQuarterTurns);
    }

    private int GetMovedAttachedBoxQuarterTurns(
        InstallationEditSession editSession,
        AreaAttachedBoxState boxState,
        int newQuarterTurns)
    {
        if (editSession == null || boxState == null)
        {
            return NormalizePlacementQuarterTurns(newQuarterTurns);
        }

        int quarterTurnDelta = NormalizePlacementQuarterTurns(newQuarterTurns - editSession.originalQuarterTurns);
        return NormalizePlacementQuarterTurns(boxState.originalQuarterTurns + quarterTurnDelta);
    }

    private bool TryResolveEditedInstallationFootprintSource(
        InstallationEditSession editSession,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        int conveyorVariantKind,
        MapObject fallbackSource,
        out MapObject footprintSource)
    {
        footprintSource = null;
        if (editSession == null)
        {
            return false;
        }

        MapObject desiredSourcePrefab = null;
        if (editSession.definition != null
            && editSession.definition.mapObject is Wall fencePrototype
            && conveyorVariantKind >= 0)
        {
            desiredSourcePrefab = ResolveFenceVariantPrefab(fencePrototype, conveyorVariantKind);
        }
        else if (editSession.definition != null
                 && editSession.definition.mapObject is Pipe pipePrototype
                 && conveyorVariantKind >= 0)
        {
            desiredSourcePrefab = ResolvePipeVariantPrefab(pipePrototype, conveyorVariantKind);
        }
        else if (editSession.definition != null
                 && editSession.definition.mapObject is ConveyorBelt conveyorPrototype
                 && conveyorVariantKind >= 0)
        {
            desiredSourcePrefab = ResolveConveyorVariantPrefab(conveyorPrototype, conveyorVariantKind);
        }

        if (desiredSourcePrefab == null && editSession.definition != null)
        {
            desiredSourcePrefab = ResolveInstalledObjectSourcePrefab(editSession.definition, anchorCoordinate, quarterTurns);
        }

        footprintSource = desiredSourcePrefab != null
            ? desiredSourcePrefab
            : (editSession.definition != null ? editSession.definition.mapObject : fallbackSource);
        return footprintSource != null;
    }

    public bool MapEditModeActive => mapEditModeActive;

    public bool PlacementOrMapEditModeActive =>
        mapEditModeActive
        || activeInstallDefinition != null
        || activeInstallPreview != null
        || (GameManager.Instance != null && GameManager.Instance.InstallationPlacementActive);

    public bool TryGetActiveBlueprintHudItemId(out int itemId)
    {
        itemId = activeInstallDefinition != null ? activeInstallDefinition.id : -1;
        return itemId >= 0 && IsInstallationModeActive();
    }

    private void SetMapEditModeActive(bool isActive)
    {
        if (mapEditModeActive == isActive)
        {
            RefreshMapEditButtonState();
            return;
        }

        mapEditModeActive = isActive;
        GameManager.Instance?.SetMapEditActive(mapEditModeActive);
        if (!mapEditModeActive)
        {
            ResetMapEditTrainDragTracking();
            SetWorkableRangeVisualRequested(selectedEditableInstallation, false);
            SetUtilityPoleRangeVisualRequested(selectedEditableInstallation, false);
            ClearSelectedEditableTint();
            selectedEditableInstallation = null;
            selectedEditableAnchorCoordinate = Vector2Int.zero;
            FinalizePackedInstallationHistory();
        }
        else
        {
            SetWorkableRangeVisualRequested(selectedEditableInstallation, true);
            SetUtilityPoleRangeVisualRequested(selectedEditableInstallation, true);
        }

        RefreshInstallOrEditWorkableRangeVisualRequest();
        UtilityPole.RefreshAllRangeVisuals();

        if (IsInstallGridModeActive())
        {
            InvalidateInstallGrid();
        }
        else
        {
            SetInstallGridVisible(false);
            ResetInstallGridRefreshState();
        }

        RefreshMapEditButtonState();
    }

    private MapObject RestoreEditedInstallation(
        InstallationEditSession editSession,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        int conveyorVariantKind = -1,
        Quaternion? previewRotationOverride = null,
        Vector3? previewPositionOverride = null)
    {
        if (editSession == null || editSession.originalInstallation == null || editSession.definition == null)
        {
            return null;
        }

        bool placementChanged = HasInstallationEditPlacementChanged(
            editSession,
            anchorCoordinate,
            quarterTurns,
            conveyorVariantKind);

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        MapObject desiredSourcePrefab = null;
        if (editSession.definition.mapObject is Wall fencePrototype && conveyorVariantKind >= 0)
        {
            desiredSourcePrefab = ResolveFenceVariantPrefab(fencePrototype, conveyorVariantKind);
        }
        else if (editSession.definition.mapObject is Pipe pipePrototype
                 && !(pipePrototype is UndergroundPipe)
                 && conveyorVariantKind >= 0)
        {
            desiredSourcePrefab = ResolvePipeVariantPrefab(pipePrototype, conveyorVariantKind);
        }
        else if (editSession.definition.mapObject is ConveyorBelt conveyorPrototype && conveyorVariantKind >= 0)
        {
            desiredSourcePrefab = ResolveConveyorVariantPrefab(conveyorPrototype, conveyorVariantKind);
        }

        if (editSession.editsUndergroundPipeEndpoint)
        {
            desiredSourcePrefab = editSession.definition.mapObject;
        }
        else if (desiredSourcePrefab == null)
        {
            desiredSourcePrefab = ResolveInstalledObjectSourcePrefab(editSession.definition, anchorCoordinate, quarterTurns);
        }
        MapObject restoredObject = ResolveRestoredInstallationObject(editSession, desiredSourcePrefab, terrain);
        if (restoredObject == null)
        {
            return null;
        }

        Transform installParent = terrain != null ? terrain.transform : transform;
        Quaternion restoredRotation = previewRotationOverride
            ?? GetInstalledObjectRotation(
                desiredSourcePrefab != null ? desiredSourcePrefab : editSession.definition.mapObject,
                quarterTurns);
        restoredObject.transform.SetParent(installParent, true);
        restoredObject.transform.SetPositionAndRotation(
            previewPositionOverride
                ?? GetInstalledObjectWorldPosition(
                    anchorCoordinate,
                    desiredSourcePrefab != null ? desiredSourcePrefab : editSession.definition.mapObject,
                    quarterTurns),
            restoredRotation);
        restoredObject.gameObject.SetActive(true);

        MapObject footprintSource = desiredSourcePrefab != null ? desiredSourcePrefab : editSession.definition.mapObject;
        List<Vector2Int> occupiedCoordinates = editSession.editsUndergroundPipeEndpoint
            ? new List<Vector2Int>
            {
                anchorCoordinate,
                editSession.fixedUndergroundEndpointCoordinate
            }
            : GetFootprintCoordinates(
                anchorCoordinate,
                footprintSource,
                quarterTurns);
        for (int i = 0; i < occupiedCoordinates.Count; i++)
        {
            if (terrain != null && terrain.TryGetLoadedBlock(occupiedCoordinates[i], out Block block) && block != null)
            {
                if (editSession.editsUndergroundPipeEndpoint
                    || ShouldBindInstalledObjectToBlock(block, anchorCoordinate, footprintSource, quarterTurns))
                {
                    block.SetMapObject(restoredObject);
                    block.ApplyFloorObjectState(null);
                }
            }
        }

        ConfigureInstalledObjectRuntime(
            restoredObject,
            anchorCoordinate,
            quarterTurns,
            editSession.inputOutputState,
            occupiedCoordinatesOverride: occupiedCoordinates);
        restoredObject.ApplyItemFilterMask(editSession.itemFilterMaskWords, editSession.itemFilterMaskInitialized);
        if (restoredObject is InstallationObject restoredInstallationObject)
        {
            restoredInstallationObject.SetStoredFluid(
                editSession.storedFluidItemId,
                editSession.storedFluidLiters,
                editSession.storedFluidTemperatureCelsius);
            if (restoredInstallationObject is IPersistentInstallationItemStorage itemStorage)
            {
                itemStorage.ApplyPersistentStoredItemId(editSession.storedInstallationItemId);
            }
            if (restoredInstallationObject is IPersistentInstallationItemCollectionStorage collectionStorage)
            {
                collectionStorage.ApplyPersistentStoredItemIds(editSession.storedInstallationItemIds);
            }
        }
        if (restoredObject is BoxObject restoredBoxObject && editSession.boxIsOpen.HasValue)
        {
            restoredBoxObject.SetOpenState(editSession.boxIsOpen.Value, false);
        }

        ApplyEditedInstallationBlockStates(editSession, anchorCoordinate, quarterTurns);
        RestoreAttachedAreaBoxes(editSession, anchorCoordinate, quarterTurns, terrain);
        RegisterInstalledObjectPersistence(restoredObject);

        if (restoredObject is InstallationObject restoredInstallation)
        {
            SelectEditableInstallation(restoredInstallation, anchorCoordinate);
        }

        RefreshInstalledConnectorVariantsAfterRestore(
            editSession,
            restoredObject,
            anchorCoordinate,
            quarterTurns,
            activeInstallPreview);

        return restoredObject;
    }

    private void RefreshInstalledConnectorVariantsAfterRemoval(
        InstallationEditSession editSession,
        Vector2Int removedAnchorCoordinate,
        int removedQuarterTurns)
    {
        RefreshInstalledConnectorVariantsAroundCoordinates(
            BuildInstallationEditAffectedCoordinates(editSession, removedAnchorCoordinate, removedQuarterTurns),
            editSession != null ? editSession.originalInstallation : null,
            true,
            null);
    }

    private void RefreshInstalledConnectorVariantsAfterRestore(
        InstallationEditSession editSession,
        MapObject restoredObject,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        RefreshInstalledConnectorVariantsAroundCoordinates(
            BuildInstallationEditAffectedCoordinates(editSession, anchorCoordinate, quarterTurns),
            restoredObject != null ? restoredObject : editSession != null ? editSession.originalInstallation : null,
            restoredObject is Pipe,
            previewToIgnore);
    }

    private void RefreshInstalledConnectorVariantsAroundCoordinates(
        IReadOnlyList<Vector2Int> changedCoordinates,
        MapObject connectorSource,
        bool includeSelf,
        MapObject previewToIgnore)
    {
        if (changedCoordinates == null || changedCoordinates.Count <= 0 || connectorSource == null)
        {
            return;
        }

        if (connectorSource is Wall)
        {
            NormalizeFenceCornersAroundCoordinates(changedCoordinates, includeSelf, previewToIgnore, null);
        }

        if (IsPipeConnectorObject(connectorSource))
        {
            NormalizePipeVariantsAroundCoordinates(changedCoordinates, includeSelf, previewToIgnore, null);
        }
    }

    private List<Vector2Int> BuildInstallationEditAffectedCoordinates(
        InstallationEditSession editSession,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        HashSet<Vector2Int> coordinates = new HashSet<Vector2Int>();
        if (editSession != null)
        {
            AddInstallationEditCoordinates(coordinates, editSession.originalStateCoordinates);
            AddInstallationEditCoordinates(coordinates, editSession.originalOccupiedCoordinates);
            AddInstallationEditCoordinates(
                coordinates,
                GetInstallationEditStateCoordinates(editSession, anchorCoordinate, quarterTurns));
            coordinates.Add(editSession.originalAnchorCoordinate);
        }

        coordinates.Add(anchorCoordinate);
        return new List<Vector2Int>(coordinates);
    }

    private static void AddInstallationEditCoordinates(
        HashSet<Vector2Int> target,
        IReadOnlyList<Vector2Int> source)
    {
        if (target == null || source == null)
        {
            return;
        }

        for (int i = 0; i < source.Count; i++)
        {
            target.Add(source[i]);
        }
    }

    private static bool CoordinateListContains(IReadOnlyList<Vector2Int> coordinates, Vector2Int coordinate)
    {
        if (coordinates == null)
        {
            return false;
        }

        for (int i = 0; i < coordinates.Count; i++)
        {
            if (coordinates[i] == coordinate)
            {
                return true;
            }
        }

        return false;
    }

    private void ApplyEditedInstallationBlockStates(InstallationEditSession editSession, Vector2Int newAnchorCoordinate, int newQuarterTurns)
    {
        if (editSession == null || editSession.originalInstallation == null)
        {
            return;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return;
        }

        MapObject footprintSource = editSession.definition != null && editSession.definition.mapObject != null
            ? editSession.definition.mapObject
            : editSession.originalInstallation;
        List<Vector2Int> newOccupiedCoordinates = GetInstalledObjectBlockingCoordinates(
            newAnchorCoordinate,
            footprintSource,
            newQuarterTurns);
        List<Vector2Int> newStateCoordinates = GetInstallationEditStateCoordinates(editSession, newAnchorCoordinate, newQuarterTurns);
        for (int i = 0; i < newStateCoordinates.Count; i++)
        {
            Vector2Int coordinate = newStateCoordinates[i];
            if (!terrain.TryGetLoadedBlock(coordinate, out Block block) || block == null)
            {
                continue;
            }

            Vector2Int worldOffset = coordinate - newAnchorCoordinate;
            Vector2Int canonicalOffset = RotateFootprintOffset(worldOffset, -newQuarterTurns);
            bool preserveExternalFloorObjects = !CoordinateListContains(newOccupiedCoordinates, coordinate);
            if (preserveExternalFloorObjects && block.MapObject is BoxObject)
            {
                continue;
            }

            if (editSession.blockStatesByCanonicalOffset.TryGetValue(canonicalOffset, out List<int> blockState))
            {
                block.ApplyFloorObjectState(preserveExternalFloorObjects
                    ? MergeExternalFloorObjectState(block, blockState)
                    : blockState);
            }
            else
            {
                block.ApplyFloorObjectState(preserveExternalFloorObjects
                    ? CaptureExternalFloorObjectState(block)
                    : null);
            }
        }
    }

    private void RestoreAttachedAreaBoxes(
        InstallationEditSession editSession,
        Vector2Int newAnchorCoordinate,
        int newQuarterTurns,
        TerrainGenerator terrain)
    {
        if (editSession?.attachedAreaBoxes == null || editSession.attachedAreaBoxes.Count <= 0)
        {
            return;
        }

        Transform installParent = terrain != null ? terrain.transform : transform;
        for (int i = 0; i < editSession.attachedAreaBoxes.Count; i++)
        {
            AreaAttachedBoxState boxState = editSession.attachedAreaBoxes[i];
            if (boxState?.boxObject == null)
            {
                continue;
            }

            BoxObject boxObject = boxState.boxObject;
            MapObject footprintSource = boxState.definition != null && boxState.definition.mapObject != null
                ? boxState.definition.mapObject
                : boxObject;
            Vector2Int targetAnchorCoordinate = GetMovedAttachedBoxAnchorCoordinate(
                editSession,
                boxState,
                newAnchorCoordinate,
                newQuarterTurns);
            int targetQuarterTurns = GetMovedAttachedBoxQuarterTurns(editSession, boxState, newQuarterTurns);

            boxObject.transform.SetParent(installParent, true);
            boxObject.transform.SetPositionAndRotation(
                GetInstalledObjectWorldPosition(targetAnchorCoordinate, footprintSource, targetQuarterTurns),
                GetInstalledObjectRotation(footprintSource, targetQuarterTurns));
            boxObject.gameObject.SetActive(true);

            List<Vector2Int> boxCoordinates = GetFootprintCoordinates(targetAnchorCoordinate, footprintSource, targetQuarterTurns);
            for (int coordinateIndex = 0; coordinateIndex < boxCoordinates.Count; coordinateIndex++)
            {
                if (terrain != null
                    && terrain.TryGetLoadedBlock(boxCoordinates[coordinateIndex], out Block block)
                    && block != null
                    && ShouldBindInstalledObjectToBlock(block, targetAnchorCoordinate, footprintSource, targetQuarterTurns))
                {
                    block.SetMapObject(boxObject);
                }
            }

            ConfigureInstalledObjectRuntime(boxObject, targetAnchorCoordinate, targetQuarterTurns);
            boxObject.ApplyItemFilterMask(boxState.itemFilterMaskWords, boxState.itemFilterMaskInitialized);
            if (boxState.boxIsOpen.HasValue)
            {
                boxObject.SetOpenState(boxState.boxIsOpen.Value, false);
            }

            RegisterInstalledObjectPersistence(boxObject);
        }
    }

    private MapObject ResolveRestoredInstallationObject(
        InstallationEditSession editSession,
        MapObject desiredSourcePrefab,
        TerrainGenerator terrain)
    {
        if (editSession?.originalInstallation == null)
        {
            return null;
        }

        MapObject originalObject = editSession.originalInstallation;
        if (!RequiresConveyorPreviewReplacement(originalObject, desiredSourcePrefab)
            && !RequiresFencePreviewReplacement(originalObject, desiredSourcePrefab)
            && !RequiresPipePreviewReplacement(originalObject, desiredSourcePrefab))
        {
            return originalObject;
        }

        if (desiredSourcePrefab == null)
        {
            return originalObject;
        }

        Transform installParent = terrain != null ? terrain.transform : transform;
        MapObject replacementObject = CreateInstalledObjectInstance(desiredSourcePrefab, installParent, terrain);
        if (replacementObject == null)
        {
            return originalObject;
        }

        replacementObject.ApplyItemFilterMask(editSession.itemFilterMaskWords, editSession.itemFilterMaskInitialized);
        if (replacementObject is InstallationObject replacementInstallation)
        {
            replacementInstallation.SetStoredFluid(
                editSession.storedFluidItemId,
                editSession.storedFluidLiters,
                editSession.storedFluidTemperatureCelsius);
            if (replacementInstallation is IPersistentInstallationItemStorage itemStorage)
            {
                itemStorage.ApplyPersistentStoredItemId(editSession.storedInstallationItemId);
            }
            if (replacementInstallation is IPersistentInstallationItemCollectionStorage collectionStorage)
            {
                collectionStorage.ApplyPersistentStoredItemIds(editSession.storedInstallationItemIds);
            }
        }

        ReleaseInstalledObjectInstance(
            editSession.originalInstallation,
            ResolveInstallationSourcePrefab(
                editSession.definition,
                editSession.originalConveyorVariantKind),
            terrain);

        editSession.originalInstallation = replacementObject as InstallationObject;
        return replacementObject;
    }

    private void HandleInstallRotationClicked()
    {
        if (IsRailloadInstallationModeActive())
        {
            railloadInstallationController.ToggleBendPriority();
            return;
        }

        if (TryRotateSelectedSteamTrain())
        {
            return;
        }

        if (activeInstallPreview == null)
        {
            CleanupInstallPreviewReferences();
            if (!IsInstallationModeActive() && !IsEditingInstallation())
            {
                return;
            }

            EnsureValidActiveInstallPreview();
        }

        ResetPreviewPointerTracking();
        RotateInstallPreviewClockwise();
    }

    private bool TryRotateSelectedSteamTrain()
    {
        if (!mapEditModeActive
            || IsEditingInstallation()
            || !(selectedEditableInstallation is SteamTrain steamTrain)
            || !steamTrain.TryGetCurrentRailPose(
                out Railload rail,
                out float distanceAlongPath,
                out Vector2 pathPoint,
                out Vector2 tangent)
            || tangent.sqrMagnitude <= 0.0001f)
        {
            return false;
        }

        if (!steamTrain.TryApplyExplicitRailPose(rail, distanceAlongPath, pathPoint, -tangent))
        {
            return false;
        }

        Physics.SyncTransforms();
        if (steamTrain.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out _))
        {
            selectedEditableAnchorCoordinate = anchorCoordinate;
        }

        RefreshMapEditButtonState();
        return true;
    }

    private void HandleInstallCompleteClicked()
    {
        if (IsEditingInstallation())
        {
            CompleteInstallationEdit();
            return;
        }

        if (mapEditModeActive)
        {
            SetMapEditModeActive(false);
            return;
        }

        if (!IsInstallationModeActive())
        {
            return;
        }

        if (IsRailloadInstallationModeActive())
        {
            if (railloadInstallationController.CommitCurrentPreview())
            {
                ClearInstallPreview();
            }

            return;
        }

        CleanupInstallPreviewReferences();
        if (installPreviewInstances.Count <= 0 || activeInstallDefinition == null)
        {
            ClearInstallPreview();
            return;
        }

        if (HasIncompleteUndergroundPipePreview())
        {
            InvalidateInstallGridPreview();
            return;
        }

        RefreshHandcartInstallPreviewConnectionPoses();
        ItemDefinition placementDefinition = activeInstallDefinition;
        MapObject placementMapObject = placementDefinition.mapObject;
        bool isPipeBlueprintPlacement = placementMapObject is Pipe;

        // Commit must never advance or reinterpret pipe topology. The visible
        // blueprint is already final; preserve newly placed previews and virtual
        // variant changes drawn over installed neighbours exactly as they are.
        List<InstalledPipeVariantPreviewPlan> installedPipeBlueprintPlans =
            isPipeBlueprintPlacement
                ? CaptureInstalledPipeVariantPreviewPlans()
                : null;

        List<MapObject> previewsToPlace = new List<MapObject>(installPreviewInstances);
        List<InstallPreviewPlacementPlan> placementPlans = new List<InstallPreviewPlacementPlan>(previewsToPlace.Count);
        List<InstallPreviewPlacementReservation> reservedFootprintReservations =
            new List<InstallPreviewPlacementReservation>();
        List<MapObject> placedPreviews = new List<MapObject>(previewsToPlace.Count);
        List<Vector2Int> placedAnchorCoordinates = new List<Vector2Int>(previewsToPlace.Count);
        List<MapObject> placedObjects = new List<MapObject>(previewsToPlace.Count);
        List<PortableObject> placedAnimationSources = new List<PortableObject>(previewsToPlace.Count);
        List<bool> placedUsedReservations = new List<bool>(previewsToPlace.Count);
        int placedCount = 0;
        int unreservedPlacedCount = 0;

        for (int i = 0; i < previewsToPlace.Count; i++)
        {
            if (TryCreateInstallPreviewPlacementPlan(
                    previewsToPlace[i],
                    reservedFootprintReservations,
                    out InstallPreviewPlacementPlan placementPlan))
            {
                placementPlans.Add(placementPlan);
            }
            else if (TryCreateStraightConveyorPlacementPlan(
                         previewsToPlace[i],
                         reservedFootprintReservations,
                         out placementPlan))
            {
                placementPlans.Add(placementPlan);
            }
        }

        if (isPipeBlueprintPlacement)
        {
            if (placementPlans.Count != previewsToPlace.Count
                || !HasEnoughItemsForCompletePlacementPlan(placementPlans)
                || !CanApplyInstalledPipeBlueprintPlans(installedPipeBlueprintPlans))
            {
                InvalidateInstallGridPreview();
                return;
            }
        }
        else if (!IsEditingInstallation())
        {
            TrimUnreservedPlacementPlansToAvailableItems(placementPlans);
        }

        List<MapObject> stagedPipeBlueprintObjects = null;
        if (isPipeBlueprintPlacement
            && !TryStagePipeBlueprintObjects(placementPlans, out stagedPipeBlueprintObjects))
        {
            InvalidateInstallGridPreview();
            return;
        }

        for (int i = 0; i < placementPlans.Count; i++)
        {
            InstallPreviewPlacementPlan placementPlan = placementPlans[i];
            Transform installParent = ResolvePlacementPlanInstallParent(
                placementPlan,
                out TerrainGenerator terrain);
            MapObject installedObject = stagedPipeBlueprintObjects != null
                ? stagedPipeBlueprintObjects[i]
                : CreateInstalledObjectInstance(placementPlan.sourcePrefab, installParent, terrain);
            if (installedObject == null)
            {
                continue;
            }

            installedObject.transform.SetPositionAndRotation(placementPlan.position, placementPlan.rotation);
            if (placementPlan.attachToFreightCarBoxPoint)
            {
                if (!(installedObject is InstallationObject installedLoad)
                    || placementPlan.freightCarBoxTarget == null
                    || !placementPlan.freightCarBoxTarget.TryAttachLoadObjectToPoint(
                        installedLoad,
                        placementPlan.freightCarBoxPoint))
                {
                    ReleaseInstalledObjectInstance(installedObject as InstallationObject, placementPlan.sourcePrefab, terrain);
                    continue;
                }
            }

            if (placementPlan.bindToFootprintBlocks)
            {
                for (int blockIndex = 0; blockIndex < placementPlan.footprintBlocks.Count; blockIndex++)
                {
                    Block footprintBlock = placementPlan.footprintBlocks[blockIndex];
                    PrepareBelt2FBridgeCenterForPassthroughPlacement(footprintBlock, placementPlan.sourcePrefab);
                    if (installedObject is UndergroundPipe
                        || ShouldBindInstalledObjectToBlock(
                            footprintBlock,
                            placementPlan.anchorBlock.Coordinate,
                            placementPlan.sourcePrefab,
                            placementPlan.quarterTurns))
                    {
                        footprintBlock.SetMapObject(installedObject);
                    }
                }
            }

            Vector2Int installedAnchorCoordinate = placementPlan.hasRuntimeAnchorCoordinate
                ? placementPlan.runtimeAnchorCoordinate
                : placementPlan.anchorBlock != null
                    ? placementPlan.anchorBlock.Coordinate
                    : RoundWorldPositionToCoordinate(placementPlan.position);
            if (!placementPlan.attachToFreightCarBoxPoint)
            {
                ConfigureInstalledObjectRuntime(
                    installedObject,
                    installedAnchorCoordinate,
                    placementPlan.quarterTurns,
                    occupiedCoordinatesOverride: ResolvePlacementPlanRuntimeOccupiedCoordinates(
                        installedObject,
                        installedAnchorCoordinate,
                        placementPlan));
            }

            InitializePlacedTrainRailSample(installedObject, installedAnchorCoordinate, placementPlan);
            ConnectHandcartToNearbyHandcarts(installedObject as Handcart);
            if (placementPlan.registerTerrainPersistence)
            {
                RegisterInstalledObjectPersistence(installedObject);
            }

            RememberLastInstalledRotation(activeInstallDefinition, placementPlan.quarterTurns);

            placedPreviews.Add(placementPlan.preview);
            if (!placementPlan.attachToFreightCarBoxPoint)
            {
                placedAnchorCoordinates.Add(installedAnchorCoordinate);
                if (installedObject is UndergroundPipe
                    && placementPlan.preview is UndergroundPipe undergroundPipePreview
                    && undergroundPipePreview.TryGetPairCoordinates(
                        out Vector2Int firstEndpoint,
                        out Vector2Int secondEndpoint))
                {
                    if (firstEndpoint != installedAnchorCoordinate)
                    {
                        placedAnchorCoordinates.Add(firstEndpoint);
                    }

                    if (secondEndpoint != installedAnchorCoordinate
                        && secondEndpoint != firstEndpoint)
                    {
                        placedAnchorCoordinates.Add(secondEndpoint);
                    }

                }
            }

            placedObjects.Add(installedObject);
            if (TryConsumeInstallPreviewReservation(placementPlan.preview, out PortableObject reservedSourcePortableObject))
            {
                placedAnimationSources.Add(reservedSourcePortableObject);
                placedUsedReservations.Add(true);
            }
            else
            {
                placedAnimationSources.Add(null);
                placedUsedReservations.Add(false);
                unreservedPlacedCount++;
            }

            placedCount++;
        }

        if (placedCount > 0)
        {
            List<PortableObject> handPortableSources = unreservedPlacedCount > 0
                ? GetPlayerHandPortableSources(activeInstallDefinition.id, unreservedPlacedCount)
                : new List<PortableObject>();
            int handPortableSourceIndex = 0;
            for (int i = 0; i < placedObjects.Count; i++)
            {
                PortableObject sourcePortableObject = i < placedAnimationSources.Count
                    ? placedAnimationSources[i]
                    : null;
                if (i < placedUsedReservations.Count
                    && !placedUsedReservations[i])
                {
                    sourcePortableObject = handPortableSourceIndex < handPortableSources.Count
                        ? handPortableSources[handPortableSourceIndex]
                        : null;
                    handPortableSourceIndex++;
                }

                PlayInstallPlacementAnimation(
                    placedObjects[i],
                    sourcePortableObject,
                    placementDefinition.id,
                    i * Mathf.Max(0f, installPlacementPortableLaunchInterval));
            }

            if (unreservedPlacedCount > 0)
            {
                RemoveInstallItemsFromPlayer(placementDefinition.id, unreservedPlacedCount);
            }
        }

        RemovePlacedInstallPreviews(placedPreviews);
        if (placedCount > 0)
        {
            WorkableObject.RefreshAllRangeVisuals();
        }

        bool placedFenceConnector = placementMapObject is Wall;
        bool placedPipeConnector = IsPipeConnectorObject(placementMapObject);
        if (placedFenceConnector)
        {
            RemoveInstalledFenceVariantPreviews(null);
        }

        if (placedAnchorCoordinates.Count > 0)
        {
            if (placedFenceConnector)
            {
                NormalizeFenceCornersAroundCoordinates(
                    placedAnchorCoordinates,
                    true,
                    null,
                    null);
                RefreshFencePreviewVariants(placedAnchorCoordinates);
                RefreshInstalledFenceVariantPreviews(placedAnchorCoordinates);
            }

            if (placedPipeConnector)
            {
                if (isPipeBlueprintPlacement)
                {
                    // Do not infer topology again after installation. The staged
                    // new pipes already use their visible blueprint variants; apply
                    // the same captured snapshot to affected installed neighbours.
                    ApplyInstalledPipeBlueprintPlans(installedPipeBlueprintPlans);
                }
                else
                {
                    HashSet<Vector2Int> pipeVariantRefreshCoordinates =
                        BuildPipeVariantRefreshCoordinates(placedAnchorCoordinates, true, null);
                    RemoveInstalledPipeVariantPreviews(null);
                    NormalizePipeVariantsAroundCoordinates(
                        placedAnchorCoordinates,
                        true,
                        null,
                        null);
                    RefreshPipeBlueprintTopology(pipeVariantRefreshCoordinates);
                }

                RefreshPipeFluidDisplaysAtCoordinates(placedAnchorCoordinates);

                // ConfigurePlacementRuntime fires before preview cleanup and pipe
                // variant normalization finish. Refresh tank connectors from the
                // committed topology so a newly installed tank/pipe is visible in
                // the same frame without requiring a later move or fluid update.
                Fluidtank.RefreshAllPipeVisuals();
            }
        }
    }

    private struct PipeRotationSetEndpoint
    {
        public Vector2Int direction;
        public bool hasPipeRoot;
        public Vector2Int pipeRootCoordinate;
        public bool hasConnectorRoot;
        public MapObject connectorOwner;
        public Vector2Int connectorAnchorCoordinate;
        public Vector2Int connectorCoordinate;
        public bool hasCurrentConnection;
        public bool hasFluidIdentity;
        public int fluidItemId;
    }

    private void RefreshPipeFluidDisplaysAtCoordinates(IReadOnlyList<Vector2Int> coordinates)
    {
        if (coordinates == null)
        {
            return;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return;
        }

        for (int i = 0; i < coordinates.Count; i++)
        {
            if (terrain.TryGetLoadedBlock(coordinates[i], out Block block)
                && block != null
                && block.MapObject is Pipe pipe
                && pipe.isActiveAndEnabled)
            {
                pipe.RefreshFluidDisplayImmediately();
            }
        }
    }

    private bool TryCreateInstallPreviewPlacementPlan(
        MapObject preview,
        List<InstallPreviewPlacementReservation> reservedFootprintReservations,
        out InstallPreviewPlacementPlan placementPlan)
    {
        placementPlan = null;
        bool targetsFreightCarBoxPoint = preview != null
                                         && installPreviewFreightCarBoxTargets.ContainsKey(preview);
        if (TryCreateFreightCarBoxInstallPreviewPlacementPlan(preview, out placementPlan))
        {
            return true;
        }

        if (targetsFreightCarBoxPoint)
        {
            return false;
        }

        if (preview == null
            || activeInstallDefinition == null
            || !TryGetBlockForPreview(preview, out Block anchorBlock))
        {
            return false;
        }

        int previewQuarterTurns = GetPreviewQuarterTurns(preview);
        installPreviewSourcePrefabsByPreview.TryGetValue(preview, out MapObject sourcePrefab);

        if (IsBelt2F(activeInstallDefinition.mapObject))
        {
            sourcePrefab = activeInstallDefinition.mapObject;
        }
        else if (activeInstallDefinition.mapObject is ConveyorBelt conveyorPrototype)
        {
            ConveyorPreviewVariantMode previewVariantMode = preview == activeInstallPreview
                ? installPreviewConveyorVariantMode
                : GetConveyorPreviewVariantMode(preview);

            if (previewVariantMode == ConveyorPreviewVariantMode.Straight)
            {
                sourcePrefab = ResolveConveyorVariantPrefab(conveyorPrototype, 0) ?? sourcePrefab;
            }
            else if (preview is ConveyorBelt previewConveyor)
            {
                sourcePrefab = ResolveConveyorVariantPrefab(conveyorPrototype, GetConveyorVariantKind(previewConveyor)) ?? sourcePrefab;
            }
            else
            {
                sourcePrefab = ResolveInstalledObjectSourcePrefab(
                                   activeInstallDefinition,
                                   anchorBlock.Coordinate,
                                   previewQuarterTurns,
                                   preview,
                                   previewVariantMode)
                               ?? sourcePrefab;
            }

            sourcePrefab = ResolveConveyorPreviewSourceForAnchor(
                conveyorPrototype,
                sourcePrefab,
                anchorBlock.Coordinate,
                previewQuarterTurns,
                preview);
            if (TryResolveActiveConveyorCornerPromotion(
                    conveyorPrototype,
                    sourcePrefab,
                    anchorBlock.Coordinate,
                    previewQuarterTurns,
                    preview,
                    out MapObject promotedConveyorPrefab,
                    out int promotedConveyorQuarterTurns))
            {
                sourcePrefab = promotedConveyorPrefab;
                previewQuarterTurns = promotedConveyorQuarterTurns;
            }
        }
        else if (activeInstallDefinition.mapObject is Wall placementFencePrototype
                 && sourcePrefab is Wall)
        {
            if (TryResolveFencePlacementVariant(
                    placementFencePrototype,
                    anchorBlock.Coordinate,
                    previewQuarterTurns,
                    preview,
                    out MapObject fenceSourcePrefab,
                    out int fenceQuarterTurns))
            {
                sourcePrefab = fenceSourcePrefab;
                previewQuarterTurns = fenceQuarterTurns;
            }

        }
        else if (activeInstallDefinition.mapObject is Wall fencePrototype
                 && TryResolveFencePlacementVariant(
                     fencePrototype,
                     anchorBlock.Coordinate,
                     previewQuarterTurns,
                     preview,
                     out MapObject fenceSourcePrefab,
                     out int fenceQuarterTurns))
        {
            sourcePrefab = fenceSourcePrefab;
            previewQuarterTurns = fenceQuarterTurns;
        }
        else if (activeInstallDefinition.mapObject is Pipe pipePrototype)
        {
            // A pipe may only be committed from its visible blueprint shape. Never
            // fall back to a cached or newly resolved variant at installation time.
            if (!(preview is Pipe visiblePreviewPipe))
            {
                return false;
            }

            MapObject visibleSourcePrefab = ResolvePipeVariantPrefab(
                pipePrototype,
                visiblePreviewPipe.VariantKindId);
            if (!(visibleSourcePrefab is Pipe)
                || !TryResolvePlacementQuarterTurnsFromRotation(
                    visibleSourcePrefab,
                    preview.transform.rotation,
                    out int visibleQuarterTurns))
            {
                return false;
            }

            sourcePrefab = visibleSourcePrefab;
            previewQuarterTurns = visibleQuarterTurns;
            installPreviewSourcePrefabsByPreview[preview] = visibleSourcePrefab;
            installPreviewQuarterTurnsByPreview[preview] =
                NormalizePlacementQuarterTurns(visibleQuarterTurns);
        }

        if (sourcePrefab == null)
        {
            sourcePrefab = ResolveInstalledObjectSourcePrefab(activeInstallDefinition, anchorBlock.Coordinate, previewQuarterTurns, preview);
        }

        if (sourcePrefab == null)
        {
            sourcePrefab = activeInstallDefinition.mapObject;
        }

        if (sourcePrefab == null)
        {
            return false;
        }

        int resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(sourcePrefab, previewQuarterTurns);
        bool hasManualPipeConnectionMask = sourcePrefab is Pipe
                                           && TryGetManualPipeConnectionMask(
                                               anchorBlock.Coordinate,
                                               preview,
                                               out _);
        if (sourcePrefab is Pipe resolvedPipePrefab
            && !hasManualPipeConnectionMask
            && !CanPipePlacementFluidConnectionsMatch(
                anchorBlock.Coordinate,
                resolvedPipePrefab,
                resolvedQuarterTurns,
                preview))
        {
            return false;
        }

        if (preview is UndergroundPipe undergroundPipePreview)
        {
            return TryCreateUndergroundPipePlacementPlan(
                undergroundPipePreview,
                reservedFootprintReservations,
                out placementPlan);
        }

        if (TryResolveWaterPumpOutwardQuarterTurns(
                anchorBlock.Coordinate,
                sourcePrefab,
                resolvedQuarterTurns,
                out int waterPumpQuarterTurns))
        {
            resolvedQuarterTurns = waterPumpQuarterTurns;
        }

        if (TryResolveTrainStationFacingQuarterTurns(
                anchorBlock.Coordinate,
                sourcePrefab,
                preview,
                resolvedQuarterTurns,
                out int trainStationQuarterTurns))
        {
            resolvedQuarterTurns = trainStationQuarterTurns;
        }

        if (IsTrainSource(sourcePrefab)
            && TryCreateTrainInstallPreviewPlacementPlan(
                preview,
                anchorBlock,
                sourcePrefab,
                resolvedQuarterTurns,
                out placementPlan))
        {
            return true;
        }

        if (!TryFindPlaceablePlacementPlanFootprint(
                anchorBlock.Coordinate,
                sourcePrefab,
                preview,
                resolvedQuarterTurns,
                reservedFootprintReservations,
                out resolvedQuarterTurns,
                out List<Block> footprintBlocks,
                out List<Vector2Int> footprintCoordinates))
        {
            return false;
        }

        AddReservedPlacementFootprint(
            reservedFootprintReservations,
            sourcePrefab,
            anchorBlock.Coordinate,
            resolvedQuarterTurns,
            footprintCoordinates);

        Vector3 placementPosition = ResolvePlacementWorldPosition(
            anchorBlock,
            sourcePrefab,
            resolvedQuarterTurns,
            preview.transform.position);
        Quaternion placementRotation = ResolvePlacementObjectRotation(
            sourcePrefab,
            anchorBlock.Coordinate,
            resolvedQuarterTurns,
            preview.transform.position);
        if (preview is Pipe || preview is Handcart)
        {
            placementPosition = preview.transform.position;
            placementRotation = preview.transform.rotation;
        }

        placementPlan = new InstallPreviewPlacementPlan
        {
            preview = preview,
            anchorBlock = anchorBlock,
            sourcePrefab = sourcePrefab,
            quarterTurns = resolvedQuarterTurns,
            footprintBlocks = footprintBlocks,
            position = placementPosition,
            rotation = placementRotation
        };
        return true;
    }

    private bool TryCreateFreightCarBoxInstallPreviewPlacementPlan(
        MapObject preview,
        out InstallPreviewPlacementPlan placementPlan)
    {
        placementPlan = null;
        if (preview == null
            || activeInstallDefinition == null
            || !IsFreightCarLoadInstallDefinition(activeInstallDefinition)
            || !installPreviewFreightCarBoxTargets.TryGetValue(preview, out FreightCar freightCar)
            || freightCar == null
            || !installPreviewFreightCarBoxPoints.TryGetValue(preview, out Transform boxPoint)
            || boxPoint == null
            || !freightCar.IsBoxPointAvailable(boxPoint)
            || IsFreightCarBoxPointReservedByPreview(freightCar, boxPoint, preview))
        {
            return false;
        }

        installPreviewSourcePrefabsByPreview.TryGetValue(preview, out MapObject sourcePrefab);
        if (sourcePrefab == null)
        {
            sourcePrefab = activeInstallDefinition.mapObject;
        }

        if (!CanFreightCarAcceptLoadPreview(freightCar, sourcePrefab))
        {
            return false;
        }

        Vector2Int runtimeAnchorCoordinate = freightCar.TryGetPlacementRuntime(out Vector2Int carAnchorCoordinate, out _)
            ? carAnchorCoordinate
            : RoundWorldPositionToCoordinate(boxPoint.position);
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        Block anchorBlock = null;
        if (terrain != null)
        {
            terrain.TryGetLoadedBlock(runtimeAnchorCoordinate, out anchorBlock);
        }

        placementPlan = new InstallPreviewPlacementPlan
        {
            preview = preview,
            anchorBlock = anchorBlock,
            sourcePrefab = sourcePrefab,
            quarterTurns = 0,
            bindToFootprintBlocks = false,
            attachToFreightCarBoxPoint = true,
            registerTerrainPersistence = false,
            freightCarBoxTarget = freightCar,
            freightCarBoxPoint = boxPoint,
            hasRuntimeAnchorCoordinate = true,
            runtimeAnchorCoordinate = runtimeAnchorCoordinate,
            position = boxPoint.position,
            rotation = boxPoint.rotation
        };
        return true;
    }

    private bool TryCreateTrainInstallPreviewPlacementPlan(
        MapObject preview,
        Block anchorBlock,
        MapObject sourcePrefab,
        int quarterTurns,
        out InstallPreviewPlacementPlan placementPlan)
    {
        placementPlan = null;
        if (preview == null
            || anchorBlock == null
            || sourcePrefab == null
            || !IsTrainSource(sourcePrefab))
        {
            return false;
        }

        int resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(sourcePrefab, quarterTurns);
        Vector3 referencePosition = preview.transform.position;
        if (installPreviewRailReferenceWorldPositions.TryGetValue(preview, out Vector3 storedRailReferencePosition))
        {
            referencePosition = storedRailReferencePosition;
        }

        if (!TryResolveTrainRailPlacementPose(
                sourcePrefab,
                anchorBlock.Coordinate,
                resolvedQuarterTurns,
                referencePosition,
                out Vector3 trainPosition,
                out Quaternion trainRotation,
                out TrainPlacementRailSample trainRailSample))
        {
            return false;
        }

        if (!CanPlaceTrainAtPose(sourcePrefab, trainPosition, trainRotation, preview))
        {
            return false;
        }

        placementPlan = new InstallPreviewPlacementPlan
        {
            preview = preview,
            anchorBlock = anchorBlock,
            sourcePrefab = sourcePrefab,
            quarterTurns = resolvedQuarterTurns,
            bindToFootprintBlocks = false,
            hasRuntimeAnchorCoordinate = true,
            runtimeAnchorCoordinate = RoundWorldPositionToCoordinate(trainPosition),
            hasTrainRailSample = true,
            trainRailSample = trainRailSample,
            position = trainPosition,
            rotation = trainRotation
        };
        return true;
    }

    private void TrimUnreservedPlacementPlansToAvailableItems(List<InstallPreviewPlacementPlan> placementPlans)
    {
        if (placementPlans == null || placementPlans.Count <= 0)
        {
            return;
        }

        int availableUnreservedItemCount = GetCurrentInstallItemCount();
        int unreservedPlanCount = 0;
        for (int i = placementPlans.Count - 1; i >= 0; i--)
        {
            InstallPreviewPlacementPlan placementPlan = placementPlans[i];
            if (placementPlan != null
                && placementPlan.preview != null
                && installPreviewItemReservationsByPreview.ContainsKey(placementPlan.preview))
            {
                continue;
            }

            unreservedPlanCount++;
            if (unreservedPlanCount > availableUnreservedItemCount)
            {
                placementPlans.RemoveAt(i);
            }
        }
    }

    private bool HasEnoughItemsForCompletePlacementPlan(
        IReadOnlyList<InstallPreviewPlacementPlan> placementPlans)
    {
        if (placementPlans == null)
        {
            return false;
        }

        int requiredUnreservedItemCount = 0;
        for (int planIndex = 0; planIndex < placementPlans.Count; planIndex++)
        {
            InstallPreviewPlacementPlan placementPlan = placementPlans[planIndex];
            if (placementPlan?.preview == null
                || installPreviewItemReservationsByPreview.ContainsKey(placementPlan.preview))
            {
                continue;
            }

            requiredUnreservedItemCount++;
        }

        return requiredUnreservedItemCount <= GetCurrentInstallItemCount();
    }

    private bool TryStagePipeBlueprintObjects(
        IReadOnlyList<InstallPreviewPlacementPlan> placementPlans,
        out List<MapObject> stagedObjects)
    {
        stagedObjects = null;
        if (placementPlans == null || placementPlans.Count <= 0)
        {
            return false;
        }

        List<MapObject> createdObjects = new List<MapObject>(placementPlans.Count);
        for (int planIndex = 0; planIndex < placementPlans.Count; planIndex++)
        {
            InstallPreviewPlacementPlan placementPlan = placementPlans[planIndex];
            Transform installParent = ResolvePlacementPlanInstallParent(
                placementPlan,
                out TerrainGenerator terrain);
            MapObject installedObject = placementPlan != null
                ? CreateInstalledObjectInstance(
                    placementPlan.sourcePrefab,
                    installParent,
                    terrain)
                : null;
            if (installedObject != null)
            {
                createdObjects.Add(installedObject);
                continue;
            }

            ReleaseStagedPipeBlueprintObjects(createdObjects, placementPlans);
            return false;
        }

        stagedObjects = createdObjects;
        return true;
    }

    private void ReleaseStagedPipeBlueprintObjects(
        IReadOnlyList<MapObject> stagedObjects,
        IReadOnlyList<InstallPreviewPlacementPlan> placementPlans)
    {
        for (int objectIndex = 0;
             stagedObjects != null && objectIndex < stagedObjects.Count;
             objectIndex++)
        {
            MapObject stagedObject = stagedObjects[objectIndex];
            InstallPreviewPlacementPlan placementPlan = placementPlans != null
                                                          && objectIndex < placementPlans.Count
                ? placementPlans[objectIndex]
                : null;
            ResolvePlacementPlanInstallParent(placementPlan, out TerrainGenerator terrain);
            ReleaseInstalledObjectInstance(
                stagedObject as InstallationObject,
                placementPlan?.sourcePrefab,
                terrain);
        }
    }

    private Transform ResolvePlacementPlanInstallParent(
        InstallPreviewPlacementPlan placementPlan,
        out TerrainGenerator terrain)
    {
        terrain = placementPlan != null && !placementPlan.attachToFreightCarBoxPoint
            ? ResolveInstallPreviewTerrain()
            : null;
        if (placementPlan == null)
        {
            return null;
        }

        if (placementPlan.attachToFreightCarBoxPoint
            && placementPlan.freightCarBoxPoint != null)
        {
            return placementPlan.freightCarBoxPoint;
        }

        return terrain != null
            ? terrain.transform
            : placementPlan.anchorBlock != null
                ? placementPlan.anchorBlock.transform
                : null;
    }

    private IReadOnlyList<Vector2Int> ResolvePlacementPlanRuntimeOccupiedCoordinates(
        MapObject installedObject,
        Vector2Int runtimeAnchorCoordinate,
        InstallPreviewPlacementPlan placementPlan)
    {
        if (installedObject is Train || IsTrainSource(placementPlan?.sourcePrefab))
        {
            return new[] { runtimeAnchorCoordinate };
        }

        if (installedObject is UndergroundPipe
            && placementPlan?.preview is UndergroundPipe undergroundPipePreview
            && undergroundPipePreview.TryGetPairCoordinates(
                out Vector2Int firstCoordinate,
                out Vector2Int secondCoordinate))
        {
            return new[] { firstCoordinate, secondCoordinate };
        }

        return null;
    }

    private bool TryCreateUndergroundPipePlacementPlan(
        UndergroundPipe preview,
        List<InstallPreviewPlacementReservation> reservedFootprintReservations,
        out InstallPreviewPlacementPlan placementPlan)
    {
        placementPlan = null;
        if (preview == null
            || activeInstallDefinition == null
            || !(activeInstallDefinition.mapObject is UndergroundPipe sourcePrefab)
            || !preview.IsPreviewPairCommitted
            || !preview.TryGetPairCoordinates(
                out Vector2Int firstCoordinate,
                out Vector2Int secondCoordinate)
            || !TryValidateUndergroundPipePair(
                firstCoordinate,
                secondCoordinate,
                preview,
                out Block firstBlock,
                out Block secondBlock))
        {
            return false;
        }

        List<Vector2Int> footprintCoordinates = new List<Vector2Int>(2)
        {
            firstCoordinate,
            secondCoordinate
        };
        if (CoordinatesOverlapReserved(
                firstCoordinate,
                sourcePrefab,
                ResolveUndergroundPipeQuarterTurns(firstCoordinate, secondCoordinate),
                footprintCoordinates,
                reservedFootprintReservations))
        {
            return false;
        }

        int quarterTurns = ResolveUndergroundPipeQuarterTurns(firstCoordinate, secondCoordinate);
        AddReservedPlacementFootprint(
            reservedFootprintReservations,
            sourcePrefab,
            firstCoordinate,
            quarterTurns,
            footprintCoordinates);

        placementPlan = new InstallPreviewPlacementPlan
        {
            preview = preview,
            anchorBlock = firstBlock,
            sourcePrefab = sourcePrefab,
            quarterTurns = quarterTurns,
            footprintBlocks = new List<Block>(2) { firstBlock, secondBlock },
            hasRuntimeAnchorCoordinate = true,
            runtimeAnchorCoordinate = firstCoordinate,
            position = firstBlock.transform.position,
            rotation = preview.transform.rotation
        };
        return true;
    }

    private bool TryValidateUndergroundPipePair(
        Vector2Int firstCoordinate,
        Vector2Int secondCoordinate,
        UndergroundPipe previewToIgnore,
        out Block firstBlock,
        out Block secondBlock)
    {
        firstBlock = null;
        secondBlock = null;
        UndergroundPipe definitionPipe = activeInstallDefinition != null
            ? activeInstallDefinition.mapObject as UndergroundPipe
            : null;
        int maxDistance = activeInstallDefinition != null
            ? activeInstallDefinition.UndergroundPipeMaxDistance
            : definitionPipe != null ? definitionPipe.MaxPairDistance : 5;
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (definitionPipe == null
            || terrain == null
            || !UndergroundPipe.IsValidPairGeometry(
                firstCoordinate,
                secondCoordinate,
                maxDistance)
            || UndergroundPipe.RouteOverlapsCollinearPair(
                firstCoordinate,
                secondCoordinate,
                previewToIgnore)
            || !terrain.TryGetLoadedBlock(firstCoordinate, out firstBlock)
            || firstBlock == null
            || !terrain.TryGetLoadedBlock(secondCoordinate, out secondBlock)
            || secondBlock == null
            || terrain.HasDroppedFloorObjectsAt(firstCoordinate)
            || terrain.HasDroppedFloorObjectsAt(secondCoordinate))
        {
            return false;
        }

        if (!UndergroundPipeFluidConnectionsMatch(
                firstCoordinate,
                secondCoordinate,
                previewToIgnore))
        {
            return false;
        }

        int quarterTurns = ResolveUndergroundPipeQuarterTurns(firstCoordinate, secondCoordinate);
        if (!CanPlacePreviewOnTargetBlockType(
                firstBlock,
                definitionPipe,
                InputOutputModule.RectGridBlockType.None,
                firstCoordinate,
                quarterTurns,
                previewToIgnore)
            || !CanPlacePreviewOnTargetBlockType(
                secondBlock,
                definitionPipe,
                InputOutputModule.RectGridBlockType.None,
                firstCoordinate,
                quarterTurns,
                previewToIgnore))
        {
            return false;
        }

        if (TryGetInstallPreviewAtCoordinate(firstCoordinate, out MapObject firstPreview)
            && firstPreview != null
            && firstPreview != previewToIgnore)
        {
            return false;
        }

        return !TryGetInstallPreviewAtCoordinate(secondCoordinate, out MapObject secondPreview)
               || secondPreview == null
               || secondPreview == previewToIgnore;
    }

    private bool UndergroundPipeFluidConnectionsMatch(
        Vector2Int firstCoordinate,
        Vector2Int secondCoordinate,
        MapObject previewToIgnore)
    {
        Vector2Int tunnelDirection = secondCoordinate - firstCoordinate;
        tunnelDirection = new Vector2Int(
            tunnelDirection.x == 0 ? 0 : (tunnelDirection.x > 0 ? 1 : -1),
            tunnelDirection.y == 0 ? 0 : (tunnelDirection.y > 0 ? 1 : -1));
        if (tunnelDirection == Vector2Int.zero)
        {
            return false;
        }

        firstUndergroundEndpointFluidItemIdsScratch.Clear();
        secondUndergroundEndpointFluidItemIdsScratch.Clear();
        bool firstHasFluidConstraint = false;
        bool secondHasFluidConstraint = false;
        bool collectedEndpoints = TryCollectUndergroundEndpointFluidConstraints(
                                      firstCoordinate,
                                      -tunnelDirection,
                                      previewToIgnore,
                                      firstUndergroundEndpointFluidItemIdsScratch,
                                      ref firstHasFluidConstraint)
                                  && TryCollectUndergroundEndpointFluidConstraints(
                                      secondCoordinate,
                                      tunnelDirection,
                                      previewToIgnore,
                                      secondUndergroundEndpointFluidItemIdsScratch,
                                      ref secondHasFluidConstraint);
        bool endpointsMatch = collectedEndpoints
                              && (!firstHasFluidConstraint
                                  || !secondHasFluidConstraint
                                  || FluidConstraintSetsOverlap(
                                      firstUndergroundEndpointFluidItemIdsScratch,
                                      secondUndergroundEndpointFluidItemIdsScratch));
        if (!endpointsMatch && collectedEndpoints)
        {
            // The underground pair is fixed. If its two ends would merge different
            // fluids, an adjacent ordinary pipe may turn away instead of rejecting
            // the underground-pipe placement.
            endpointsMatch = CanSeparateUndergroundEndpointPipe(
                                 firstCoordinate,
                                 -tunnelDirection,
                                 previewToIgnore)
                             || CanSeparateUndergroundEndpointPipe(
                                 secondCoordinate,
                                 tunnelDirection,
                                 previewToIgnore);
        }

        firstUndergroundEndpointFluidItemIdsScratch.Clear();
        secondUndergroundEndpointFluidItemIdsScratch.Clear();
        return endpointsMatch;
    }

    private bool CanSeparateUndergroundEndpointPipe(
        Vector2Int endpointCoordinate,
        Vector2Int outwardDirection,
        MapObject previewToIgnore)
    {
        Vector2Int neighborCoordinate = endpointCoordinate + outwardDirection;
        if (!TryGetPipePlacementAtCoordinate(
                neighborCoordinate,
                previewToIgnore,
                out Pipe neighborPipe,
                out Quaternion neighborRotation)
            || neighborPipe == null
            || neighborPipe is UndergroundPipe
            || !HasEffectivePipeConnectionTowardsAt(
                neighborCoordinate,
                neighborPipe,
                neighborRotation,
                -outwardDirection))
        {
            return false;
        }

        separatedPipeForbiddenDirectionsScratch.Clear();
        separatedPipeForbiddenDirectionsScratch.Add(-outwardDirection);
        bool canSeparate = TryResolvePipeVariantAvoidingConnections(
            neighborCoordinate,
            neighborPipe,
            neighborRotation,
            separatedPipeForbiddenDirectionsScratch,
            previewToIgnore,
            out _,
            out _);
        separatedPipeForbiddenDirectionsScratch.Clear();
        return canSeparate;
    }

    private bool TryCollectUndergroundEndpointFluidConstraints(
        Vector2Int endpointCoordinate,
        Vector2Int outwardDirection,
        MapObject previewToIgnore,
        HashSet<int> compatibleFluidItemIds,
        ref bool hasFluidConstraint)
    {
        if (!TryCollectAdjacentPipeConnectionFluidConstraints(
                endpointCoordinate,
                outwardDirection,
                previewToIgnore,
                compatibleFluidItemIds,
                ref hasFluidConstraint))
        {
            return false;
        }

        Vector2Int neighborCoordinate = endpointCoordinate + outwardDirection;
        if (!TryGetPipePlacementAtCoordinate(
                neighborCoordinate,
                previewToIgnore,
                out Pipe neighborPipe,
                out Quaternion neighborRotation)
            || neighborPipe == null
            || !HasEffectivePipeConnectionTowardsAt(
                neighborCoordinate,
                neighborPipe,
                neighborRotation,
                -outwardDirection))
        {
            return true;
        }

        return TryCollectPipeNetworkFluidConstraints(
            neighborCoordinate,
            neighborPipe,
            neighborRotation,
            previewToIgnore,
            compatibleFluidItemIds,
            ref hasFluidConstraint);
    }

    private static int ResolveUndergroundPipeQuarterTurns(
        Vector2Int firstCoordinate,
        Vector2Int secondCoordinate)
    {
        Vector2Int direction = secondCoordinate - firstCoordinate;
        if (direction.x > 0)
        {
            return 1;
        }

        if (direction.x < 0)
        {
            return 3;
        }

        return direction.y < 0 ? 2 : 0;
    }

    private bool TryCreateStraightConveyorPlacementPlan(
        MapObject preview,
        List<InstallPreviewPlacementReservation> reservedFootprintReservations,
        out InstallPreviewPlacementPlan placementPlan)
    {
        placementPlan = null;
        if (preview == null
            || activeInstallDefinition == null
            || !CanUseStraightConveyorFallback(preview)
            || !TryGetBlockForPreview(preview, out Block anchorBlock)
            || !TryResolveStraightConveyorPlacementSource(out MapObject sourcePrefab))
        {
            return false;
        }

        int previewQuarterTurns = GetPreviewQuarterTurns(preview);
        int resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(sourcePrefab, previewQuarterTurns);

        if (!TryFindPlaceablePlacementPlanFootprint(
                anchorBlock.Coordinate,
                sourcePrefab,
                preview,
                resolvedQuarterTurns,
                reservedFootprintReservations,
                out resolvedQuarterTurns,
                out List<Block> footprintBlocks,
                out List<Vector2Int> footprintCoordinates))
        {
            return false;
        }

        AddReservedPlacementFootprint(
            reservedFootprintReservations,
            sourcePrefab,
            anchorBlock.Coordinate,
            resolvedQuarterTurns,
            footprintCoordinates);

        placementPlan = new InstallPreviewPlacementPlan
        {
            preview = preview,
            anchorBlock = anchorBlock,
            sourcePrefab = sourcePrefab,
            quarterTurns = resolvedQuarterTurns,
            footprintBlocks = footprintBlocks,
            position = ResolvePlacementWorldPosition(anchorBlock, sourcePrefab, resolvedQuarterTurns, preview.transform.position),
            rotation = ResolvePlacementObjectRotation(sourcePrefab, anchorBlock.Coordinate, resolvedQuarterTurns, preview.transform.position)
        };
        return true;
    }

    private bool TryFindPlaceablePlacementPlanFootprint(
        Vector2Int anchorCoordinate,
        MapObject sourcePrefab,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        List<InstallPreviewPlacementReservation> reservedFootprintReservations,
        out int resolvedQuarterTurns,
        out List<Block> footprintBlocks,
        out List<Vector2Int> footprintCoordinates)
    {
        resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(sourcePrefab, preferredQuarterTurns);
        footprintBlocks = null;
        footprintCoordinates = null;

        if (sourcePrefab == null)
        {
            return false;
        }

        if (TryResolveOilDrillingMachineFacingQuarterTurns(
                anchorCoordinate,
                sourcePrefab,
                previewToIgnore,
                resolvedQuarterTurns,
                reservedFootprintReservations,
                out int oilDrillingMachineQuarterTurns))
        {
            resolvedQuarterTurns = oilDrillingMachineQuarterTurns;
        }

        if (TryResolveWaterPumpOutwardQuarterTurns(
                anchorCoordinate,
                sourcePrefab,
                resolvedQuarterTurns,
                out int waterPumpQuarterTurns))
        {
            resolvedQuarterTurns = waterPumpQuarterTurns;
        }

        if (TryResolveTrainStationFacingQuarterTurns(
                anchorCoordinate,
                sourcePrefab,
                previewToIgnore,
                resolvedQuarterTurns,
                out int trainStationQuarterTurns))
        {
            resolvedQuarterTurns = trainStationQuarterTurns;
        }

        if (!TryGetFootprintBlocks(
                anchorCoordinate,
                sourcePrefab,
                resolvedQuarterTurns,
                previewToIgnore,
                out List<Block> resolvedFootprintBlocks,
                true)
            || resolvedFootprintBlocks == null
            || resolvedFootprintBlocks.Count <= 0)
        {
            return false;
        }

        List<Vector2Int> resolvedFootprintCoordinates = GetFootprintCoordinates(
            anchorCoordinate,
            sourcePrefab,
            resolvedQuarterTurns);
        if (CoordinatesOverlapReserved(
                anchorCoordinate,
                sourcePrefab,
                resolvedQuarterTurns,
                resolvedFootprintCoordinates,
                reservedFootprintReservations))
        {
            return false;
        }

        footprintBlocks = resolvedFootprintBlocks;
        footprintCoordinates = resolvedFootprintCoordinates;
        return true;
    }

    private static void AddReservedPlacementFootprint(
        List<InstallPreviewPlacementReservation> reservations,
        MapObject sourcePrefab,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        IReadOnlyList<Vector2Int> footprintCoordinates)
    {
        if (reservations == null
            || sourcePrefab == null
            || footprintCoordinates == null
            || footprintCoordinates.Count <= 0)
        {
            return;
        }

        InstallPreviewPlacementReservation reservation = new InstallPreviewPlacementReservation
        {
            sourcePrefab = sourcePrefab,
            anchorCoordinate = anchorCoordinate,
            quarterTurns = NormalizePlacementQuarterTurns(quarterTurns),
            footprintCoordinates = new List<Vector2Int>(footprintCoordinates)
        };
        if (IsOilDrillingMachineSource(sourcePrefab))
        {
            reservation.hasOilTargetCoordinate = true;
            reservation.oilTargetCoordinate = ResolveOilDrillingMachineTargetCoordinate(
                anchorCoordinate,
                quarterTurns);
        }

        reservations.Add(reservation);
    }

    private bool CoordinatesOverlapReserved(
        Vector2Int anchorCoordinate,
        MapObject sourcePrefab,
        int quarterTurns,
        IReadOnlyList<Vector2Int> coordinates,
        IReadOnlyList<InstallPreviewPlacementReservation> reservedFootprintReservations)
    {
        if (coordinates == null
            || reservedFootprintReservations == null
            || reservedFootprintReservations.Count <= 0)
        {
            return false;
        }

        for (int i = 0; i < coordinates.Count; i++)
        {
            Vector2Int coordinate = coordinates[i];
            for (int reservationIndex = 0; reservationIndex < reservedFootprintReservations.Count; reservationIndex++)
            {
                InstallPreviewPlacementReservation reservation = reservedFootprintReservations[reservationIndex];
                if (reservation == null
                    || reservation.footprintCoordinates == null
                    || !reservation.footprintCoordinates.Contains(coordinate))
                {
                    continue;
                }

                if (!CanOverlapCompatiblePlacementItemAreas(
                        coordinate,
                        sourcePrefab,
                        GetRectGridBlockTypeAtCoordinate(
                            anchorCoordinate,
                            sourcePrefab,
                            quarterTurns,
                            coordinate),
                        anchorCoordinate,
                        quarterTurns,
                        reservation.sourcePrefab,
                        GetRectGridBlockTypeAtCoordinate(
                            reservation.anchorCoordinate,
                            reservation.sourcePrefab,
                            reservation.quarterTurns,
                            coordinate),
                        reservation.anchorCoordinate,
                        reservation.quarterTurns))
                {
                    return true;
                }
            }
        }

        return false;
    }

    private void ConfigureInstalledInputOutputMarkers(MapObject installedObject, Vector2Int anchorCoordinate, int quarterTurns)
    {
        if (ConfigureTrainStationRailMarkers(installedObject, installedObject, anchorCoordinate, quarterTurns, false))
        {
            return;
        }

        ConfigureInputOutputMarkers(installedObject, anchorCoordinate, quarterTurns, false);
    }

    private void RefreshInstallPreviewAreaMarkers(MapObject preview)
    {
        if (preview == null)
        {
            return;
        }

        if (!TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate))
        {
            ClearInputOutputMarkers(preview);
            if (preview is ConveyorBelt conveyorPreviewWithoutAnchor)
            {
                conveyorPreviewWithoutAnchor.ClearEndpointVisualsForPreview();
            }

            RememberInstallPreviewVisualSyncState(
                preview,
                false,
                Vector2Int.zero,
                GetPreviewAreaQuarterTurns(preview));
            return;
        }

        int quarterTurns = GetPreviewAreaQuarterTurns(preview);
        MapObject footprintSource = ResolveInstallPreviewPlacementSource(preview);
        if (ConfigureRobotArmInstallDirectionMarkers(preview, footprintSource, anchorCoordinate, quarterTurns))
        {
            RememberInstallPreviewVisualSyncState(preview, true, anchorCoordinate, quarterTurns);
            return;
        }

        if (ConfigureTrainStationRailMarkers(preview, footprintSource, anchorCoordinate, quarterTurns, true))
        {
            RememberInstallPreviewVisualSyncState(preview, true, anchorCoordinate, quarterTurns);
            return;
        }

        ConfigureInputOutputMarkers(preview, footprintSource, anchorCoordinate, quarterTurns, true);
        RememberInstallPreviewVisualSyncState(preview, true, anchorCoordinate, quarterTurns);
        RefreshInstallPreviewConveyorEndpointVisualsAround(preview, anchorCoordinate, quarterTurns);
    }

    private void RefreshInstallPreviewConveyorEndpointVisualsAround(
        MapObject preview,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        if (!(preview is ConveyorBelt))
        {
            return;
        }

        conveyorEndpointRefreshPreviewScratch.Clear();
        conveyorEndpointRefreshPreviewScratch.Add(preview);

        MapObject footprintSource = ResolveInstallPreviewPlacementSource(preview);
        List<Vector2Int> footprintCoordinates = GetFootprintCoordinates(anchorCoordinate, footprintSource, quarterTurns);
        for (int i = 0; i < footprintCoordinates.Count; i++)
        {
            AddInstallPreviewConveyorEndpointRefreshPreviewAtCoordinate(footprintCoordinates[i]);
            for (int directionIndex = 0; directionIndex < PipeCardinalDirections.Length; directionIndex++)
            {
                AddInstallPreviewConveyorEndpointRefreshPreviewAtCoordinate(
                    footprintCoordinates[i] + PipeCardinalDirections[directionIndex]);
            }
        }

        foreach (MapObject refreshPreview in conveyorEndpointRefreshPreviewScratch)
        {
            RefreshInstallPreviewConveyorEndpointVisuals(refreshPreview);
        }

        conveyorEndpointRefreshPreviewScratch.Clear();
    }

    private void AddInstallPreviewConveyorEndpointRefreshPreviewAtCoordinate(Vector2Int coordinate)
    {
        if (!TryGetPreviewPlacementSnapshot(coordinate, null, out PlacementSnapshot snapshot)
            || !(snapshot?.mapObject is ConveyorBelt))
        {
            return;
        }

        conveyorEndpointRefreshPreviewScratch.Add(snapshot.mapObject);
    }

    private void RefreshInstallPreviewConveyorEndpointVisuals(MapObject preview)
    {
        if (!(preview is ConveyorBelt previewBelt))
        {
            return;
        }

        if (!TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate))
        {
            previewBelt.ClearEndpointVisualsForPreview();
            return;
        }

        MapObject footprintSource = ResolveInstallPreviewPlacementSource(preview);
        int quarterTurns = GetPreviewAreaQuarterTurns(preview);
        List<Vector2Int> footprintCoordinates = GetFootprintCoordinates(anchorCoordinate, footprintSource, quarterTurns);
        previewBelt.RefreshEndpointVisualsForPreview(
            anchorCoordinate,
            footprintCoordinates,
            TryResolveConveyorEndpointPlacementForPreview);
    }

    private void RefreshAllInstallPreviewConveyorEndpointVisuals()
    {
        CleanupInstallPreviewReferences();
        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            RefreshInstallPreviewConveyorEndpointVisuals(installPreviewInstances[i]);
        }
    }

    private bool TryResolveConveyorEndpointPlacementForPreview(
        Vector2Int coordinate,
        ConveyorBelt ignoredBelt,
        out ConveyorBelt conveyorBelt,
        out Quaternion rotation)
    {
        conveyorBelt = null;
        rotation = Quaternion.identity;

        if (TryGetPreviewPlacementSnapshot(coordinate, ignoredBelt, out PlacementSnapshot previewSnapshot)
            && TryResolveConveyorEndpointSnapshot(previewSnapshot, out conveyorBelt, out rotation))
        {
            return true;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain != null
            && terrain.TryGetLoadedBlock(coordinate, out Block block)
            && block != null
            && block.MapObject is ConveyorBelt directConveyor
            && directConveyor != null
            && directConveyor != ignoredBelt
            && directConveyor.gameObject.activeInHierarchy)
        {
            conveyorBelt = directConveyor;
            rotation = directConveyor.transform.rotation;
            return true;
        }

        if (ConvayorBelt2F.TryFindCoveringBelt(coordinate, out ConvayorBelt2F coveringBelt)
            && coveringBelt != null
            && coveringBelt != ignoredBelt
            && coveringBelt.gameObject.activeInHierarchy)
        {
            conveyorBelt = coveringBelt;
            rotation = coveringBelt.transform.rotation;
            return true;
        }

        return TryGetSavedPlacementSnapshot(coordinate, out PlacementSnapshot savedSnapshot)
               && TryResolveConveyorEndpointSnapshot(savedSnapshot, out conveyorBelt, out rotation)
               && conveyorBelt != ignoredBelt;
    }

    private bool TryResolveConveyorEndpointSnapshot(
        PlacementSnapshot snapshot,
        out ConveyorBelt conveyorBelt,
        out Quaternion rotation)
    {
        conveyorBelt = null;
        rotation = Quaternion.identity;
        if (snapshot == null)
        {
            return false;
        }

        MapObject sourcePrefab = ResolveInstallPreviewFootprintSource(snapshot.mapObject) ?? snapshot.mapObject;
        conveyorBelt = snapshot.mapObject as ConveyorBelt ?? sourcePrefab as ConveyorBelt;
        if (conveyorBelt == null)
        {
            return false;
        }

        rotation = snapshot.rotation;
        return true;
    }

    private static void ClearInputOutputMarkers(MapObject mapObject)
    {
        InputOutputModuleAreaMarkerController markerController =
            mapObject != null ? mapObject.GetComponent<InputOutputModuleAreaMarkerController>() : null;
        if (markerController != null)
        {
            markerController.Configure(null, null);
        }
    }

    private void ConfigureInputOutputMarkers(
        MapObject mapObject,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        bool isInstallPreview)
    {
        ConfigureInputOutputMarkers(
            mapObject,
            mapObject,
            anchorCoordinate,
            quarterTurns,
            isInstallPreview);
    }

    private void ConfigureInputOutputMarkers(
        MapObject mapObject,
        MapObject footprintSource,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        bool isInstallPreview)
    {
        if (mapObject == null || !TryGetInputOutputModule(footprintSource, out _))
        {
            ClearInputOutputMarkers(mapObject);
            return;
        }

        areaMarkerRequestScratch.Clear();
        FillRectGridBlockWorldPositions(
            anchorCoordinate,
            footprintSource,
            quarterTurns,
            ObjectRectGridBlockTypes,
            areaMarkerPrimaryWorldPositionScratch);
        if (areaMarkerPrimaryWorldPositionScratch.Count <= 0)
        {
            areaMarkerPrimaryWorldPositionScratch.Add(mapObject.transform.position);
        }

        Sprite arrowIcon = ResolveArrowMarkerIcon();

        FillRectGridBlockWorldPositions(
            anchorCoordinate,
            footprintSource,
            quarterTurns,
            InputEnergyRectGridBlockTypes,
            areaMarkerInputEnergyWorldPositionScratch);
        AddAreaMarkerRequests(
            areaMarkerRequestScratch,
            areaMarkerInputEnergyWorldPositionScratch,
            ResolveInputEnergyMarkerIcon(footprintSource));

        FillRectGridBlockWorldPositions(
            anchorCoordinate,
            footprintSource,
            quarterTurns,
            InputItemRectGridBlockTypes,
            areaMarkerInputItemWorldPositionScratch);
        AddDirectionalAreaMarkerRequests(
            areaMarkerRequestScratch,
            areaMarkerInputItemWorldPositionScratch,
            arrowIcon,
            areaMarkerPrimaryWorldPositionScratch,
            false);

        FillRectGridBlockWorldPositions(
            anchorCoordinate,
            footprintSource,
            quarterTurns,
            OutputRectGridBlockTypes,
            areaMarkerOutputWorldPositionScratch);
        AddDirectionalAreaMarkerRequests(
            areaMarkerRequestScratch,
            areaMarkerOutputWorldPositionScratch,
            arrowIcon,
            areaMarkerPrimaryWorldPositionScratch,
            true);

        FillRectGridBlockWorldPositions(
            anchorCoordinate,
            footprintSource,
            quarterTurns,
            PipeInputRectGridBlockTypes,
            areaMarkerPipeInputWorldPositionScratch);
        AddAreaMarkerRequests(
            areaMarkerRequestScratch,
            areaMarkerPipeInputWorldPositionScratch,
            ResolvePipePassMarkerIcon(footprintSource));

        if (areaMarkerRequestScratch.Count <= 0)
        {
            ClearInputOutputMarkers(mapObject);
            return;
        }

        ConfigureAreaMarkers(mapObject, areaMarkerRequestScratch, isInstallPreview);
    }

    private bool ConfigureRobotArmInstallDirectionMarkers(
        MapObject mapObject,
        MapObject footprintSource,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        if (!TryGetRobotArm(mapObject, out _))
        {
            return false;
        }

        Sprite arrowIcon = ResolveArrowMarkerIcon();
        if (arrowIcon == null || !TryGetRobotArmFlowDirection(mapObject, out Vector2Int flowDirection))
        {
            ClearInputOutputMarkers(mapObject);
            return true;
        }

        List<Vector2Int> objectCoordinates = GetPlacementVisualCoordinates(
            anchorCoordinate,
            footprintSource,
            quarterTurns);
        if (objectCoordinates.Count <= 0)
        {
            objectCoordinates.Add(anchorCoordinate);
        }

        Vector2Int inputMarkerCoordinate = GetRobotArmEdgeCoordinate(objectCoordinates, flowDirection, false) - flowDirection;
        Vector2Int outputMarkerCoordinate = GetRobotArmEdgeCoordinate(objectCoordinates, flowDirection, true) + flowDirection;
        Vector3 inputMarkerWorldPosition = GetAreaMarkerWorldPosition(inputMarkerCoordinate);
        Vector3 outputMarkerWorldPosition = GetAreaMarkerWorldPosition(outputMarkerCoordinate);
        float iconRotationZ = GetArrowMarkerRotationZ(inputMarkerWorldPosition, outputMarkerWorldPosition);

        List<AreaMarkerSpawnRequest> markerRequests = new List<AreaMarkerSpawnRequest>
        {
            new AreaMarkerSpawnRequest(inputMarkerWorldPosition, arrowIcon, iconRotationZ),
            new AreaMarkerSpawnRequest(outputMarkerWorldPosition, arrowIcon, iconRotationZ)
        };

        ConfigureAreaMarkers(mapObject, markerRequests, true);
        return true;
    }

    private bool ConfigureTrainStationRailMarkers(
        MapObject mapObject,
        MapObject footprintSource,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        bool isInstallPreview)
    {
        if (mapObject == null || !IsTrainStationSource(footprintSource))
        {
            return false;
        }

        Sprite stationIcon = ResolveTrainStationMarkerIcon(mapObject, footprintSource);
        if (stationIcon == null)
        {
            ClearInputOutputMarkers(mapObject);
            return true;
        }

        areaMarkerRequestScratch.Clear();
        MapObject previewToIgnore = isInstallPreview ? mapObject : null;
        if (TryResolveTrainStationSelectedRailCoordinate(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                previewToIgnore,
                out Vector2Int railCoordinate))
        {
            areaMarkerRequestScratch.Add(new AreaMarkerSpawnRequest(
                GetAreaMarkerWorldPosition(railCoordinate),
                stationIcon));
        }

        if (areaMarkerRequestScratch.Count <= 0)
        {
            ClearInputOutputMarkers(mapObject);
            return true;
        }

        ConfigureAreaMarkers(
            mapObject,
            areaMarkerRequestScratch,
            isInstallPreview,
            TrainStationAreaMarkerSortingOrderOffset,
            false,
            TrainStationAreaMarkerVerticalOffset);
        return true;
    }

    private bool ConfigureAreaMarkers(
        MapObject mapObject,
        IReadOnlyList<AreaMarkerSpawnRequest> markerRequests,
        bool isInstallPreview,
        int? sortingOrderOffsetOverride = null,
        bool? renderOnTopOverride = null,
        float? verticalOffsetOverride = null)
    {
        if (mapObject == null || markerRequests == null || markerRequests.Count <= 0)
        {
            ClearInputOutputMarkers(mapObject);
            return false;
        }

        AreaMarkerPool pool = ResolveAreaMarkerPool();
        if (pool == null)
        {
            ClearInputOutputMarkers(mapObject);
            return false;
        }

        InputOutputModuleAreaMarkerController markerController = mapObject.GetComponent<InputOutputModuleAreaMarkerController>();
        if (markerController == null)
        {
            markerController = mapObject.gameObject.AddComponent<InputOutputModuleAreaMarkerController>();
        }

        markerController.enabled = true;
        markerController.Configure(
            pool,
            markerRequests,
            isInstallPreview,
            sortingOrderOffsetOverride ?? (isInstallPreview ? InstallPreviewAreaMarkerSortingOrderOffset : 0),
            renderOnTopOverride ?? isInstallPreview,
            isInstallPreview ? mapObject.transform : null,
            verticalOffsetOverride);
        return true;
    }

    private bool TryResolveTrainStationSelectedRailCoordinate(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore,
        out Vector2Int railCoordinate)
    {
        railCoordinate = default;
        int normalizedQuarterTurns = NormalizePlacementQuarterTurnsForObject(footprintSource, quarterTurns);
        if (!IsTrainStationSource(footprintSource)
            || !Trainstation.TryGetFacingDirection(
                normalizedQuarterTurns,
                out Vector2Int selectedDirection))
        {
            return false;
        }

        List<Vector2Int> stationCoordinates = GetPlacementVisualCoordinates(
            anchorCoordinate,
            footprintSource,
            normalizedQuarterTurns);
        if (stationCoordinates.Count <= 0)
        {
            stationCoordinates.Add(anchorCoordinate);
        }

        for (int i = 0; i < stationCoordinates.Count; i++)
        {
            Vector2Int candidateRailCoordinate = stationCoordinates[i] + selectedDirection;
            if (!HasRailloadForTrainStationAtCoordinate(candidateRailCoordinate, previewToIgnore))
            {
                continue;
            }

            railCoordinate = candidateRailCoordinate;
            return true;
        }

        return false;
    }

    private Sprite ResolveTrainStationMarkerIcon(MapObject mapObject, MapObject footprintSource)
    {
        if (TryGetTrainStation(mapObject, out Trainstation station)
            && station.StationMarkerIcon != null)
        {
            return station.StationMarkerIcon;
        }

        if (TryGetTrainStation(footprintSource, out station)
            && station.StationMarkerIcon != null)
        {
            return station.StationMarkerIcon;
        }

        if (trainStationMarkerIcon != null)
        {
            return trainStationMarkerIcon;
        }

#if UNITY_EDITOR
        trainStationMarkerIcon = UnityEditor.AssetDatabase.LoadAssetAtPath<Sprite>(TrainStationMarkerIconAssetPath);
        if (trainStationMarkerIcon != null)
        {
            return trainStationMarkerIcon;
        }
#endif

        ItemDefinition stationDefinition = ResolveItemDefinition(footprintSource) ?? ResolveItemDefinition(mapObject);
        return stationDefinition != null ? stationDefinition.icon : null;
    }

    private static bool TryGetTrainStation(MapObject mapObject, out Trainstation station)
    {
        station = mapObject as Trainstation;
        if (station != null)
        {
            return true;
        }

        if (mapObject == null)
        {
            return false;
        }

        station = mapObject.GetComponent<Trainstation>();
        if (station != null)
        {
            return true;
        }

        station = mapObject.GetComponentInChildren<Trainstation>(true);
        return station != null;
    }

    private void ConfigureInstalledInputOutputEnergyAreas(MapObject installedObject, Vector2Int anchorCoordinate, int quarterTurns)
    {
        if (!TryGetInputOutputModule(installedObject, out _))
        {
            return;
        }

        ItemDefinition installationDefinition = ResolveItemDefinition(installedObject);
        if (installationDefinition == null || installationDefinition.useEnergyType == ItemDefinition.EnergyType.None)
        {
            return;
        }

        if (!TryGetRectGridBlockCoordinates(
                anchorCoordinate,
                installedObject,
                quarterTurns,
                DirectInputEnergyRectGridBlockTypes,
                out List<Vector2Int> inputEnergyCoordinates)
            || inputEnergyCoordinates == null
            || inputEnergyCoordinates.Count <= 0)
        {
            return;
        }

        InputOutputModuleEnergyAreaController energyAreaController = installedObject.GetComponent<InputOutputModuleEnergyAreaController>();
        if (energyAreaController == null)
        {
            energyAreaController = installedObject.gameObject.AddComponent<InputOutputModuleEnergyAreaController>();
        }

        energyAreaController.Configure(installationDefinition.useEnergyType, inputEnergyCoordinates);
    }

    private void ConfigureInstalledInputOutputItemAreas(MapObject installedObject, Vector2Int anchorCoordinate, int quarterTurns)
    {
        if (!TryGetInputOutputModule(installedObject, out InputOutputModule inputOutputModule))
        {
            return;
        }

        InputOutputModuleItemAreaController itemAreaController = installedObject.GetComponent<InputOutputModuleItemAreaController>();
        if (!TryGetOrderedInputItemAreaBindings(
                anchorCoordinate,
                installedObject,
                quarterTurns,
                inputOutputModule,
                out List<InputOutputModuleItemAreaBinding> itemAreaBindings,
                true)
            || itemAreaBindings == null
            || itemAreaBindings.Count <= 0)
        {
            itemAreaController?.Configure(null);
            return;
        }

        if (itemAreaController == null)
        {
            itemAreaController = installedObject.gameObject.AddComponent<InputOutputModuleItemAreaController>();
        }

        itemAreaController.Configure(itemAreaBindings);
    }

    private void ConfigureInstalledInputOutputOutputAreas(MapObject installedObject, Vector2Int anchorCoordinate, int quarterTurns)
    {
        if (!TryGetInputOutputModule(installedObject, out _))
        {
            return;
        }

        InputOutputModuleOutputAreaController outputAreaController = installedObject.GetComponent<InputOutputModuleOutputAreaController>();
        if (!TryGetRectGridBlockCoordinates(
                anchorCoordinate,
                installedObject,
                quarterTurns,
                DirectOutputRectGridBlockTypes,
                out List<Vector2Int> outputCoordinates)
            || outputCoordinates == null
            || outputCoordinates.Count <= 0)
        {
            outputAreaController?.Configure(null);
            return;
        }

        if (outputAreaController == null)
        {
            outputAreaController = installedObject.gameObject.AddComponent<InputOutputModuleOutputAreaController>();
        }

        outputAreaController.Configure(outputCoordinates);
    }

    private void ConfigureInstalledInputOutputRuntimeAreas(MapObject installedObject, Vector2Int anchorCoordinate, int quarterTurns)
    {
        if (!TryGetInputOutputModule(installedObject, out InputOutputModule inputOutputModule))
        {
            return;
        }

        List<Vector2Int> inputEnergyCoordinates = new List<Vector2Int>();
        TryGetRectGridBlockCoordinates(
            anchorCoordinate,
            installedObject,
            quarterTurns,
            InputEnergyRectGridBlockTypes,
            out inputEnergyCoordinates);

        List<InputOutputModuleItemAreaBinding> itemAreaBindings = new List<InputOutputModuleItemAreaBinding>();
        TryGetOrderedInputItemAreaBindings(
            anchorCoordinate,
            installedObject,
            quarterTurns,
            inputOutputModule,
            out itemAreaBindings);

        List<Vector2Int> outputCoordinates = new List<Vector2Int>();
        TryGetRectGridBlockCoordinates(
            anchorCoordinate,
            installedObject,
            quarterTurns,
            OutputRectGridBlockTypes,
            out outputCoordinates);

        List<Vector2Int> pipeInputCoordinates = new List<Vector2Int>();
        TryGetRectGridBlockCoordinates(
            anchorCoordinate,
            installedObject,
            quarterTurns,
            PipeInputRectGridBlockTypes,
            out pipeInputCoordinates);

        inputOutputModule.ConfigureRuntimeAreas(
            inputEnergyCoordinates,
            itemAreaBindings,
            outputCoordinates,
            pipeInputCoordinates);
    }

    private void ConfigureInstalledInputOutputRuntimeGrid(MapObject installedObject, Vector2Int anchorCoordinate, int quarterTurns)
    {
        if (!TryGetInputOutputModule(installedObject, out InputOutputModule inputOutputModule))
        {
            return;
        }

        List<Vector2Int> footprintCoordinates = GetRectGridPlacementCoordinates(
            anchorCoordinate,
            installedObject,
            quarterTurns);
        if (footprintCoordinates.Count <= 0)
        {
            footprintCoordinates = GetFootprintCoordinates(anchorCoordinate, installedObject, quarterTurns);
        }

        List<Vector2Int> focusCoordinates = GetPlacementVisualCoordinates(anchorCoordinate, installedObject, quarterTurns);
        inputOutputModule.ConfigureRuntimeGridCoordinates(footprintCoordinates);
        inputOutputModule.ConfigureRuntimeFocusCoordinates(focusCoordinates);
    }

    private List<Vector2Int> GetInstalledObjectBlockingCoordinates(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns)
    {
        if (TryGetRectGridBlockCoordinates(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                InputOutputModule.RectGridBlockType.Object,
                out List<Vector2Int> objectCoordinates)
            && objectCoordinates.Count > 0)
        {
            return objectCoordinates;
        }

        List<Vector2Int> coordinates = GetFootprintCoordinates(anchorCoordinate, footprintSource, quarterTurns);
        if (ShouldSkipBelt2FBridgeCenterBinding(anchorCoordinate, footprintSource, quarterTurns, out Vector2Int bridgeCenterCoordinate))
        {
            coordinates.Remove(bridgeCenterCoordinate);
        }

        return coordinates;
    }

    private IReadOnlyList<Vector2Int> ResolveInstalledObjectRuntimeOccupiedCoordinates(
        MapObject installedObject,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        IReadOnlyList<Vector2Int> occupiedCoordinatesOverride)
    {
        // 지하 파이프 쌍, 선로, 열차는 설치 계획이 계산한 명시적 점유 좌표가
        // 실제 본체 좌표다. 특히 선로는 복원 시 저장된 경로를 버리면 기본 점유 1칸만 남아
        // 메시를 생성할 수 없다.
        if (occupiedCoordinatesOverride != null
            && occupiedCoordinatesOverride.Count > 0
            && (installedObject is UndergroundPipe
                || installedObject is Railload
                || installedObject is Train))
        {
            return occupiedCoordinatesOverride;
        }

        // 일반 설치물의 RuntimeOccupiedCoordinates에는 Object 칸만 저장한다.
        // Input/Output/Energy Area까지 포함하면 포커싱에서 본체와 Area가 한 그룹으로 합쳐진다.
        return GetInstalledObjectBlockingCoordinates(
            anchorCoordinate,
            installedObject,
            quarterTurns);
    }

    public void ConfigureInstalledObjectRuntime(
        MapObject installedObject,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        InputOutputModule.PersistentState persistentState = null,
        long placementSequence = 0,
        IReadOnlyList<Vector2Int> occupiedCoordinatesOverride = null)
    {
        if (installedObject == null)
        {
            return;
        }

        ApplyFenceVariantSharedMapObjectSettings(installedObject);
        ApplyConveyorVariantSharedInstallationSettings(installedObject);
        ApplyPipeVariantSharedMapObjectSettings(installedObject);

        if (installedObject is InstallationObject installationObject)
        {
            IReadOnlyList<Vector2Int> occupiedCoordinates =
                ResolveInstalledObjectRuntimeOccupiedCoordinates(
                    installedObject,
                    anchorCoordinate,
                    quarterTurns,
                    occupiedCoordinatesOverride);

            installationObject.ConfigurePlacementRuntime(
                anchorCoordinate,
                quarterTurns,
                occupiedCoordinates,
                placementSequence);

            if (installationObject is ConvayorBelt2F belt2F)
            {
                ConvayorBelt2F.MarkCoverageDirty();
                belt2F.RefreshCoveredConveyorTopology();
            }
        }

        ConfigureInstalledInputOutputMarkers(installedObject, anchorCoordinate, quarterTurns);
        ConfigureInstalledInputOutputEnergyAreas(installedObject, anchorCoordinate, quarterTurns);
        ConfigureInstalledInputOutputItemAreas(installedObject, anchorCoordinate, quarterTurns);
        ConfigureInstalledInputOutputOutputAreas(installedObject, anchorCoordinate, quarterTurns);
        ConfigureInstalledInputOutputRuntimeAreas(installedObject, anchorCoordinate, quarterTurns);
        ConfigureInstalledInputOutputRuntimeGrid(installedObject, anchorCoordinate, quarterTurns);

        if (persistentState != null && TryGetInputOutputModule(installedObject, out InputOutputModule inputOutputModule))
        {
            inputOutputModule.ApplyPersistentState(persistentState);
            ConfigureInstalledInputOutputRuntimeAreas(installedObject, anchorCoordinate, quarterTurns);
            ConfigureInstalledInputOutputRuntimeGrid(installedObject, anchorCoordinate, quarterTurns);
        }

        if (installedObject is UtilityPole)
        {
            UtilityPole.RefreshPoleTopologyNow();
        }
    }

    public bool BindInstalledObjectToFootprintBlocks(
        MapObject installedObject,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        if (installedObject == null)
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        bool boundAnyBlock = false;
        List<Vector2Int> footprintCoordinates = GetFootprintCoordinates(anchorCoordinate, installedObject, quarterTurns);
        for (int i = 0; i < footprintCoordinates.Count; i++)
        {
            if (!terrain.TryGetLoadedBlock(footprintCoordinates[i], out Block block)
                || block == null
                || !ShouldBindInstalledObjectToBlock(block, anchorCoordinate, installedObject, quarterTurns))
            {
                continue;
            }

            block.SetMapObject(installedObject);
            boundAnyBlock = true;
        }

        return boundAnyBlock;
    }

    private static void ApplyFenceVariantSharedMapObjectSettings(MapObject mapObject)
    {
        if (!(mapObject is Wall fence))
        {
            return;
        }

        Wall straightPrefab = fence.StraightVariantPrefab;
        if (straightPrefab == null || straightPrefab == fence)
        {
            return;
        }

        fence.MapFilter = straightPrefab.MapFilter;
        mapObject.CopyFocusSettingsFrom(straightPrefab);
    }

    private static void ApplyConveyorVariantSharedInstallationSettings(MapObject mapObject)
    {
        if (!(mapObject is ConveyorBelt conveyorBelt) || !conveyorBelt.IsCornerVariant)
        {
            return;
        }

        ConveyorBelt straightPrefab = conveyorBelt.StraightVariantPrefab;
        if (straightPrefab == null || straightPrefab == conveyorBelt)
        {
            return;
        }

        conveyorBelt.MapFilter = straightPrefab.MapFilter;
        conveyorBelt.CopyFocusSettingsFrom(straightPrefab);
    }

    private static void ApplyPipeVariantSharedMapObjectSettings(MapObject mapObject)
    {
        if (!(mapObject is Pipe pipe) || pipe.VariantKind == PipeVariantKind.Straight)
        {
            return;
        }

        Pipe straightPrefab = pipe.StraightVariantPrefab;
        if (straightPrefab == null || straightPrefab == pipe)
        {
            return;
        }

        pipe.MapFilter = straightPrefab.MapFilter;
        pipe.CopyFocusSettingsFrom(straightPrefab);
    }

    public Quaternion GetInstalledObjectRotation(ItemDefinition definition, int quarterTurns)
    {
        return GetInstalledObjectRotation(definition != null ? definition.mapObject : null, quarterTurns);
    }

    public Quaternion GetInstalledObjectRotation(MapObject sourcePrefab, int quarterTurns)
    {
        return GetPlacementObjectRotation(sourcePrefab, quarterTurns);
    }

    private static int GetConveyorVariantKind(MapObject mapObject)
    {
        if (!(mapObject is ConveyorBelt conveyorBelt) || conveyorBelt == null)
        {
            return -1;
        }

        if (conveyorBelt.IsReverseCornerVariant)
        {
            return 2;
        }

        if (conveyorBelt.IsCornerVariant)
        {
            return 1;
        }

        return 0;
    }

    private static ConveyorPreviewVariantMode GetConveyorPreviewVariantMode(MapObject mapObject)
    {
        return GetConveyorVariantKind(mapObject) > 0
            ? ConveyorPreviewVariantMode.Corner
            : ConveyorPreviewVariantMode.Straight;
    }

    private static MapObject ResolveConveyorVariantPrefab(ConveyorBelt conveyorPrototype, int conveyorVariantKind)
    {
        if (conveyorPrototype == null)
        {
            return null;
        }

        if (IsBelt2F(conveyorPrototype))
        {
            return conveyorPrototype;
        }

        return conveyorVariantKind switch
        {
            2 => conveyorPrototype.ReverseCornerVariantPrefab != null
                ? conveyorPrototype.ReverseCornerVariantPrefab
                : conveyorPrototype.CornerVariantPrefab,
            1 => conveyorPrototype.CornerVariantPrefab != null
                ? conveyorPrototype.CornerVariantPrefab
                : conveyorPrototype.StraightVariantPrefab,
            0 => conveyorPrototype.StraightVariantPrefab,
            _ => null
        };
    }

    private static int GetFenceVariantKind(MapObject mapObject)
    {
        if (!(mapObject is Wall fence) || fence == null)
        {
            return -1;
        }

        return fence.VariantKindId;
    }

    private static int GetPipeVariantKind(MapObject mapObject)
    {
        if (!(mapObject is Pipe pipe) || pipe == null)
        {
            return -1;
        }

        return pipe.VariantKindId;
    }

    private static int GetInstallationVariantKind(MapObject mapObject)
    {
        int conveyorVariantKind = GetConveyorVariantKind(mapObject);
        if (conveyorVariantKind >= 0)
        {
            return conveyorVariantKind;
        }

        int fenceVariantKind = GetFenceVariantKind(mapObject);
        if (fenceVariantKind >= 0)
        {
            return fenceVariantKind;
        }

        return GetPipeVariantKind(mapObject);
    }

    public static MapObject ResolveFenceVariantPrefab(Wall fencePrototype, int fenceVariantKind)
    {
        if (fencePrototype == null)
        {
            return null;
        }

        return fenceVariantKind switch
        {
            3 => fencePrototype.CrossVariantPrefab != null
                ? fencePrototype.CrossVariantPrefab
                : fencePrototype.TriCornerVariantPrefab != null
                    ? fencePrototype.TriCornerVariantPrefab
                    : fencePrototype.CornerVariantPrefab != null
                        ? fencePrototype.CornerVariantPrefab
                        : fencePrototype.StraightVariantPrefab,
            2 => fencePrototype.TriCornerVariantPrefab != null
                ? fencePrototype.TriCornerVariantPrefab
                : fencePrototype.CornerVariantPrefab != null
                    ? fencePrototype.CornerVariantPrefab
                    : fencePrototype.StraightVariantPrefab,
            1 => fencePrototype.CornerVariantPrefab != null
                ? fencePrototype.CornerVariantPrefab
                : fencePrototype.StraightVariantPrefab,
            0 => fencePrototype.StraightVariantPrefab,
            _ => null
        };
    }

    public static MapObject ResolvePipeVariantPrefab(Pipe pipePrototype, int pipeVariantKind)
    {
        if (pipePrototype == null)
        {
            return null;
        }

        // An underground pair is one logical object with two remote endpoints.
        // Replacing it with a surface-pipe variant discards the remote endpoint.
        if (pipePrototype is UndergroundPipe)
        {
            return pipePrototype;
        }

        return pipeVariantKind switch
        {
            3 => pipePrototype.CrossVariantPrefab != null
                ? pipePrototype.CrossVariantPrefab
                : pipePrototype.TeeVariantPrefab != null
                    ? pipePrototype.TeeVariantPrefab
                    : pipePrototype.CornerVariantPrefab != null
                        ? pipePrototype.CornerVariantPrefab
                        : pipePrototype.StraightVariantPrefab,
            2 => pipePrototype.TeeVariantPrefab != null
                ? pipePrototype.TeeVariantPrefab
                : pipePrototype.CornerVariantPrefab != null
                    ? pipePrototype.CornerVariantPrefab
                    : pipePrototype.StraightVariantPrefab,
            1 => pipePrototype.CornerVariantPrefab != null
                ? pipePrototype.CornerVariantPrefab
                : pipePrototype.StraightVariantPrefab,
            0 => pipePrototype.StraightVariantPrefab,
            _ => null
        };
    }

    public bool TryResolvePipeLoadPlacement(
        ItemDefinition definition,
        Vector2Int anchorCoordinate,
        int preferredQuarterTurns,
        out MapObject resolvedPrefab,
        out int resolvedQuarterTurns,
        out int resolvedVariantKind)
    {
        return TryResolvePipeLoadPlacement(
            definition,
            anchorCoordinate,
            preferredQuarterTurns,
            -1,
            -1,
            out resolvedPrefab,
            out resolvedQuarterTurns,
            out resolvedVariantKind);
    }

    public bool TryResolvePipeLoadPlacement(
        ItemDefinition definition,
        Vector2Int anchorCoordinate,
        int preferredQuarterTurns,
        int savedVariantKind,
        int savedConnectionMask,
        out MapObject resolvedPrefab,
        out int resolvedQuarterTurns,
        out int resolvedVariantKind)
    {
        resolvedPrefab = null;
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        resolvedVariantKind = -1;

        if (definition == null || !(definition.mapObject is Pipe pipePrototype))
        {
            return false;
        }

        if (pipePrototype is UndergroundPipe)
        {
            resolvedPrefab = pipePrototype;
            resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                pipePrototype,
                preferredQuarterTurns);
            resolvedVariantKind = pipePrototype.VariantKindId;
            return true;
        }

        Pipe exactPipe = savedVariantKind >= 0
            ? ResolvePipeVariantPrefab(pipePrototype, savedVariantKind) as Pipe
            : null;
        if (savedConnectionMask >= 0
            && TryResolvePipePlacementFromConnectionMask(
                pipePrototype,
                exactPipe,
                savedConnectionMask,
                resolvedQuarterTurns,
                out Pipe maskPipe,
                out int maskQuarterTurns))
        {
            exactPipe = maskPipe;
            resolvedQuarterTurns = maskQuarterTurns;
        }

        if (exactPipe != null)
        {
            Quaternion exactRotation = GetPlacementObjectRotation(
                exactPipe,
                resolvedQuarterTurns);
            int exactConnectionMask = exactPipe.GetConnectionMask(exactRotation);
            if ((savedConnectionMask < 0 || exactConnectionMask == savedConnectionMask)
                && CanPipePlacementFluidConnectionsMatch(
                    anchorCoordinate,
                    exactPipe,
                    exactRotation,
                    null,
                    exactConnectionMask))
            {
                resolvedPrefab = exactPipe;
                resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                    exactPipe,
                    resolvedQuarterTurns);
                resolvedVariantKind = exactPipe.VariantKindId;
                return true;
            }
        }

        // Repair invalid legacy junctions before the restored object is activated.
        // No old port is protected here: a mixed saved Tee/Cross must be split now,
        // while the final compatibility gate still preserves separated neighbours.
        if (!TryResolvePipePlacementVariant(
                pipePrototype,
                anchorCoordinate,
                preferredQuarterTurns,
                null,
                out resolvedPrefab,
                out resolvedQuarterTurns,
                0)
            || !(resolvedPrefab is Pipe resolvedPipe))
        {
            return false;
        }

        resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(resolvedPrefab, resolvedQuarterTurns);
        resolvedVariantKind = resolvedPipe.VariantKindId;
        return true;
    }

    public bool TryResolvePipeQuarterTurnsFromConnectionMask(
        Pipe pipePrefab,
        int connectionMask,
        int preferredQuarterTurns,
        out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            pipePrefab,
            preferredQuarterTurns);
        if (pipePrefab == null || connectionMask < 0)
        {
            return false;
        }

        int normalizedPreferredQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        for (int offset = 0; offset < 4; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurns(
                normalizedPreferredQuarterTurns + offset);
            Quaternion candidateRotation = GetPlacementObjectRotation(
                pipePrefab,
                candidateQuarterTurns);
            if (pipePrefab.GetConnectionMask(candidateRotation) != connectionMask)
            {
                continue;
            }

            resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                pipePrefab,
                candidateQuarterTurns);
            return true;
        }

        return false;
    }

    private bool TryResolvePipePlacementFromConnectionMask(
        Pipe pipePrototype,
        Pipe preferredPipe,
        int connectionMask,
        int preferredQuarterTurns,
        out Pipe resolvedPipe,
        out int resolvedQuarterTurns)
    {
        resolvedPipe = null;
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        if (pipePrototype == null || connectionMask < 0)
        {
            return false;
        }

        if (preferredPipe != null
            && TryResolvePipeQuarterTurnsFromConnectionMask(
                preferredPipe,
                connectionMask,
                preferredQuarterTurns,
                out resolvedQuarterTurns))
        {
            resolvedPipe = preferredPipe;
            return true;
        }

        for (int variantKind = 0; variantKind <= 3; variantKind++)
        {
            if (!(ResolvePipeVariantPrefab(pipePrototype, variantKind) is Pipe candidatePipe)
                || candidatePipe == preferredPipe
                || !TryResolvePipeQuarterTurnsFromConnectionMask(
                    candidatePipe,
                    connectionMask,
                    preferredQuarterTurns,
                    out resolvedQuarterTurns))
            {
                continue;
            }

            resolvedPipe = candidatePipe;
            return true;
        }

        return false;
    }

    public bool TryResolveFenceLoadPlacement(
        ItemDefinition definition,
        Vector2Int anchorCoordinate,
        int preferredQuarterTurns,
        out MapObject resolvedPrefab,
        out int resolvedQuarterTurns,
        out int resolvedVariantKind)
    {
        resolvedPrefab = null;
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        resolvedVariantKind = -1;

        if (definition == null || !(definition.mapObject is Wall fencePrototype))
        {
            return false;
        }

        if (!TryResolveFencePlacementVariant(
                fencePrototype,
                anchorCoordinate,
                preferredQuarterTurns,
                null,
                out resolvedPrefab,
                out resolvedQuarterTurns)
            || !(resolvedPrefab is Wall resolvedFence))
        {
            return false;
        }

        resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(resolvedPrefab, resolvedQuarterTurns);
        resolvedVariantKind = resolvedFence.VariantKindId;
        return true;
    }

    private bool TryResolveFencePlacementVariant(
        Wall fencePrototype,
        Vector2Int anchorCoordinate,
        int preferredQuarterTurns,
        MapObject previewToIgnore,
        out MapObject resolvedPrefab,
        out int resolvedQuarterTurns)
    {
        resolvedPrefab = null;
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        if (fencePrototype == null)
        {
            return false;
        }

        Wall straightPrefab = fencePrototype.StraightVariantPrefab != null
            ? fencePrototype.StraightVariantPrefab
            : fencePrototype;
        Wall cornerPrefab = fencePrototype.CornerVariantPrefab;
        Wall triCornerPrefab = fencePrototype.TriCornerVariantPrefab;
        Wall crossPrefab = fencePrototype.CrossVariantPrefab;
        List<Vector2Int> neighborDirections = GetFenceNeighborConnectionDirections(
            anchorCoordinate,
            previewToIgnore,
            true);

        int neighborDirectionCount = CountFenceNeighborDirections(neighborDirections);
        if (neighborDirectionCount <= 0 && IsFenceDoor(fencePrototype, previewToIgnore))
        {
            resolvedPrefab = straightPrefab != null ? straightPrefab : fencePrototype;
            resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                resolvedPrefab,
                GetFenceDoorStandaloneQuarterTurns(previewToIgnore, resolvedQuarterTurns));
            return resolvedPrefab != null;
        }

        if (neighborDirectionCount >= 4
            && crossPrefab != null
            && TryResolveFenceVariantQuarterTurns(
                crossPrefab,
                neighborDirections,
                resolvedQuarterTurns,
                out int crossQuarterTurns))
        {
            resolvedPrefab = crossPrefab;
            resolvedQuarterTurns = crossQuarterTurns;
            return true;
        }

        if (neighborDirectionCount >= 3
            && triCornerPrefab != null
            && TryResolveFenceVariantQuarterTurns(
                triCornerPrefab,
                neighborDirections,
                resolvedQuarterTurns,
                out int triCornerQuarterTurns))
        {
            resolvedPrefab = triCornerPrefab;
            resolvedQuarterTurns = triCornerQuarterTurns;
            return true;
        }

        if (neighborDirectionCount >= 2
            && cornerPrefab != null
            && TryResolveFenceVariantQuarterTurns(
                cornerPrefab,
                neighborDirections,
                resolvedQuarterTurns,
                out int cornerQuarterTurns))
        {
            resolvedPrefab = cornerPrefab;
            resolvedQuarterTurns = cornerQuarterTurns;
            return true;
        }

        resolvedPrefab = straightPrefab != null ? straightPrefab : fencePrototype;
        if (resolvedPrefab is Wall straightFencePrefab
            && IsFenceDoor(straightFencePrefab, previewToIgnore)
            && TryResolveFenceDoorAlignedQuarterTurns(
                straightFencePrefab,
                anchorCoordinate,
                neighborDirections,
                resolvedQuarterTurns,
                previewToIgnore,
                out int alignedDoorQuarterTurns))
        {
            resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                resolvedPrefab,
                alignedDoorQuarterTurns);
        }
        else if (resolvedPrefab is Wall fallbackStraightFencePrefab
            && TryResolveFenceStraightQuarterTurns(
                fallbackStraightFencePrefab,
                neighborDirections,
                resolvedQuarterTurns,
                out int straightQuarterTurns))
        {
            resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                resolvedPrefab,
                straightQuarterTurns);
        }
        else
        {
            resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                resolvedPrefab,
                resolvedQuarterTurns);
        }

        return resolvedPrefab != null;
    }

    private static bool IsFenceDoor(Wall fencePrototype, MapObject preview)
    {
        return fencePrototype is FenceDoor || preview is FenceDoor;
    }

    private bool ShouldAutoAlignFenceDoorPreview(MapObject preview, Vector2Int anchorCoordinate)
    {
        Wall activeFencePrototype = activeInstallDefinition != null
            ? activeInstallDefinition.mapObject as Wall
            : null;
        if (!IsFenceDoor(activeFencePrototype, preview))
        {
            return false;
        }

        return HasFenceNeighborConnections(anchorCoordinate, preview, true);
    }

    private int GetFenceDoorStandaloneQuarterTurns(MapObject preview, int fallbackQuarterTurns)
    {
        if (preview != null
            && installPreviewFenceDoorStandaloneQuarterTurnsByPreview.TryGetValue(preview, out int standaloneQuarterTurns))
        {
            return NormalizePlacementQuarterTurns(standaloneQuarterTurns);
        }

        return NormalizePlacementQuarterTurns(fallbackQuarterTurns);
    }

    private bool ShouldRememberFenceDoorStandaloneQuarterTurns(
        MapObject preview,
        bool hasAnchorBlock,
        Vector2Int anchorCoordinate)
    {
        return IsFenceDoorDefinition(activeInstallDefinition)
               && preview is FenceDoor
               && (!hasAnchorBlock || !HasFenceNeighborConnections(anchorCoordinate, preview, true));
    }

    private bool TryResolveFenceDoorAlignedQuarterTurns(
        Wall doorPrefab,
        Vector2Int anchorCoordinate,
        IReadOnlyList<Vector2Int> neighborDirections,
        int preferredQuarterTurns,
        MapObject previewToIgnore,
        out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        if (!(doorPrefab is FenceDoor)
            || neighborDirections == null
            || CountFenceNeighborDirections(neighborDirections) <= 0)
        {
            return false;
        }

        Vector2Int[] sideDirections =
        {
            Vector2Int.up,
            Vector2Int.right,
            Vector2Int.down,
            Vector2Int.left
        };

        for (int i = 0; i < sideDirections.Length; i++)
        {
            Vector2Int sideDirection = sideDirections[i];
            if (!TryGetFencePlacementAtCoordinate(
                    anchorCoordinate + sideDirection,
                    previewToIgnore,
                    out Wall neighborFence,
                    out Quaternion neighborRotation)
                || !neighborFence.HasConnectionTowards(neighborRotation, -sideDirection)
                || !TryResolvePlacementQuarterTurnsFromRotation(
                    doorPrefab,
                    neighborRotation,
                    out int neighborQuarterTurns)
                || !FenceCandidateConnectsToDirections(
                    doorPrefab,
                    neighborQuarterTurns,
                    neighborDirections))
            {
                continue;
            }

            resolvedQuarterTurns = NormalizePlacementQuarterTurns(neighborQuarterTurns);
            return true;
        }

        return false;
    }

    private bool FenceCandidateConnectsToDirections(
        Wall fencePrefab,
        int quarterTurns,
        IReadOnlyList<Vector2Int> neighborDirections)
    {
        if (fencePrefab == null || neighborDirections == null || neighborDirections.Count <= 0)
        {
            return false;
        }

        Quaternion candidateRotation = GetPlacementObjectRotation(fencePrefab, quarterTurns);
        bool foundDirection = false;
        for (int i = 0; i < neighborDirections.Count; i++)
        {
            Vector2Int direction = neighborDirections[i];
            if (direction == Vector2Int.zero)
            {
                continue;
            }

            foundDirection = true;
            if (!fencePrefab.HasConnectionTowards(candidateRotation, direction))
            {
                return false;
            }
        }

        return foundDirection;
    }

    private static int CountFenceNeighborDirections(IReadOnlyList<Vector2Int> neighborDirections)
    {
        if (neighborDirections == null || neighborDirections.Count <= 0)
        {
            return 0;
        }

        int count = 0;
        bool hasUp = false;
        bool hasRight = false;
        bool hasDown = false;
        bool hasLeft = false;
        for (int i = 0; i < neighborDirections.Count; i++)
        {
            Vector2Int direction = neighborDirections[i];
            if (direction == Vector2Int.up)
            {
                if (!hasUp)
                {
                    hasUp = true;
                    count++;
                }
            }
            else if (direction == Vector2Int.right)
            {
                if (!hasRight)
                {
                    hasRight = true;
                    count++;
                }
            }
            else if (direction == Vector2Int.down)
            {
                if (!hasDown)
                {
                    hasDown = true;
                    count++;
                }
            }
            else if (direction == Vector2Int.left && !hasLeft)
            {
                hasLeft = true;
                count++;
            }
        }

        return count;
    }

    private bool TryResolveFenceStraightQuarterTurns(
        Wall straightPrefab,
        IReadOnlyList<Vector2Int> neighborDirections,
        int preferredQuarterTurns,
        out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        if (straightPrefab == null || neighborDirections == null || neighborDirections.Count <= 0)
        {
            return false;
        }

        Vector2Int targetDirection = Vector2Int.zero;
        for (int i = 0; i < neighborDirections.Count; i++)
        {
            Vector2Int neighborDirection = neighborDirections[i];
            if (neighborDirection == Vector2Int.zero)
            {
                continue;
            }

            if (targetDirection == Vector2Int.zero)
            {
                targetDirection = neighborDirection;
                continue;
            }

            if (neighborDirection != targetDirection && neighborDirection != -targetDirection)
            {
                return false;
            }
        }

        if (targetDirection == Vector2Int.zero)
        {
            return false;
        }

        int normalizedPreferredQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        for (int offset = 0; offset < 4; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurns(normalizedPreferredQuarterTurns + offset);
            Quaternion candidateRotation = GetPlacementObjectRotation(straightPrefab, candidateQuarterTurns);
            if (straightPrefab.HasConnectionTowards(candidateRotation, targetDirection))
            {
                resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                    straightPrefab,
                    candidateQuarterTurns);
                return true;
            }
        }

        return false;
    }

    private bool TryResolveFenceVariantQuarterTurns(
        Wall fencePrefab,
        IReadOnlyList<Vector2Int> neighborDirections,
        int preferredQuarterTurns,
        out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        if (fencePrefab == null || neighborDirections == null || neighborDirections.Count <= 0)
        {
            return false;
        }

        int normalizedPreferredQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        for (int offset = 0; offset < 4; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurns(normalizedPreferredQuarterTurns + offset);
            Quaternion candidateRotation = GetPlacementObjectRotation(fencePrefab, candidateQuarterTurns);
            bool allDirectionsConnected = true;
            for (int i = 0; i < neighborDirections.Count; i++)
            {
                Vector2Int direction = neighborDirections[i];
                if (direction == Vector2Int.zero)
                {
                    continue;
                }

                if (!fencePrefab.HasConnectionTowards(candidateRotation, direction))
                {
                    allDirectionsConnected = false;
                    break;
                }
            }

            if (allDirectionsConnected)
            {
                resolvedQuarterTurns = candidateQuarterTurns;
                return true;
            }
        }

        return false;
    }

    private List<Vector2Int> GetFenceNeighborConnectionDirections(
        Vector2Int anchorCoordinate,
        MapObject previewToIgnore,
        bool allowPotentialConnections = true)
    {
        List<Vector2Int> directions = new List<Vector2Int>(4);
        Vector2Int[] sideDirections =
        {
            Vector2Int.up,
            Vector2Int.right,
            Vector2Int.down,
            Vector2Int.left
        };

        for (int i = 0; i < sideDirections.Length; i++)
        {
            Vector2Int sideDirection = sideDirections[i];
            if (!TryGetFencePlacementAtCoordinate(
                    anchorCoordinate + sideDirection,
                    previewToIgnore,
                    out Wall neighborFence,
                    out Quaternion neighborRotation))
            {
                continue;
            }

            if (ShouldFenceNeighborContributeToCorner(
                    neighborFence,
                    neighborRotation,
                    -sideDirection,
                    allowPotentialConnections))
            {
                directions.Add(sideDirection);
            }
        }

        return directions;
    }

    private static bool ShouldFenceNeighborContributeToCorner(
        Wall neighborFence,
        Quaternion neighborRotation,
        Vector2Int directionToCandidate,
        bool allowPotentialConnections)
    {
        if (neighborFence == null || directionToCandidate == Vector2Int.zero)
        {
            return false;
        }

        if (neighborFence.HasConnectionTowards(neighborRotation, directionToCandidate))
        {
            return true;
        }

        return allowPotentialConnections
               && CanFencePotentiallyConnectTowards(neighborFence, neighborRotation, directionToCandidate);
    }

    private static bool CanFencePotentiallyConnectTowards(
        Wall fence,
        Quaternion baseRotation,
        Vector2Int direction)
    {
        if (fence == null || direction == Vector2Int.zero)
        {
            return false;
        }

        for (int offset = 1; offset < 4; offset++)
        {
            Quaternion candidateRotation = baseRotation * Quaternion.Euler(0f, offset * 90f, 0f);
            if (fence.HasConnectionTowards(candidateRotation, direction))
            {
                return true;
            }
        }

        return false;
    }

    private bool TryGetFencePlacementAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out Wall fence,
        out Quaternion rotation)
    {
        fence = null;
        rotation = Quaternion.identity;

        if (TryGetInstallPreviewAtCoordinate(coordinate, out MapObject preview)
            && preview != null
            && preview != previewToIgnore
            && preview is Wall previewFence)
        {
            fence = previewFence;
            rotation = previewFence.transform.rotation;
            return true;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain != null
            && terrain.TryGetLoadedBlock(coordinate, out Block block)
            && block != null
            && block.MapObject is Wall installedFence
            && installedFence != null
            && installedFence.gameObject.activeInHierarchy)
        {
            if (TryGetInstalledFenceVariantPreview(installedFence, out Wall variantPreviewFence, out Quaternion previewRotation))
            {
                fence = variantPreviewFence;
                rotation = previewRotation;
                return true;
            }

            fence = installedFence;
            rotation = installedFence.transform.rotation;
            return true;
        }

        if (TryGetSavedInstallationPlacementAtCoordinate(
                coordinate,
                out MapObject savedSourcePrefab,
                out Quaternion savedRotation,
                out _)
            && savedSourcePrefab is Wall savedFence)
        {
            fence = savedFence;
            rotation = savedRotation;
            return true;
        }

        return false;
    }

    private bool TryResolvePipePlacementVariant(
        Pipe pipePrototype,
        Vector2Int anchorCoordinate,
        int preferredQuarterTurns,
        MapObject previewToIgnore,
        out MapObject resolvedPrefab,
        out int resolvedQuarterTurns,
        int baselineConnectionMask = 0,
        bool allowPotentialConnections = true)
    {
        resolvedPrefab = null;
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        if (pipePrototype == null)
        {
            return false;
        }

        if (pipePrototype is UndergroundPipe)
        {
            resolvedPrefab = pipePrototype;
            resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                pipePrototype,
                preferredQuarterTurns);
            return true;
        }

        Pipe straightPrefab = pipePrototype.StraightVariantPrefab != null
            ? pipePrototype.StraightVariantPrefab
            : pipePrototype;
        Pipe cornerPrefab = pipePrototype.CornerVariantPrefab;
        Pipe teePrefab = pipePrototype.TeeVariantPrefab;
        Pipe crossPrefab = pipePrototype.CrossVariantPrefab;
        TryGetPipeVariantAnchorFluidItemId(
            anchorCoordinate,
            previewToIgnore,
            out int anchorFluidItemId);
        bool hasManualConnectionMask = TryGetManualPipeConnectionMask(
            anchorCoordinate,
            previewToIgnore,
            out int manualConnectionMask);
        if (hasManualConnectionMask)
        {
            if (TryResolvePipePlacementFromConnectionMask(
                    pipePrototype,
                    null,
                    manualConnectionMask,
                    preferredQuarterTurns,
                    out Pipe manuallySelectedPipe,
                    out int manuallySelectedQuarterTurns))
            {
                resolvedPrefab = manuallySelectedPipe;
                resolvedQuarterTurns = manuallySelectedQuarterTurns;
                return true;
            }

            return false;
        }

        int preferredFluidItemId = ResolvePreferredPipeVariantFluidItemId(
            anchorCoordinate,
            anchorFluidItemId,
            previewToIgnore);
        List<Vector2Int> neighborDirections = GetPipeNeighborConnectionDirections(
            pipePrototype,
            anchorCoordinate,
            previewToIgnore,
            allowPotentialConnections,
            preferredFluidItemId);
        List<Vector2Int> actualNeighborDirections = GetPipeNeighborConnectionDirections(
            pipePrototype,
            anchorCoordinate,
            previewToIgnore,
            false,
            preferredFluidItemId);

        RemoveIncompatibleRuntimePipeDirections(
            anchorCoordinate,
            preferredFluidItemId,
            previewToIgnore,
            neighborDirections,
            baselineConnectionMask);
        RemoveIncompatibleRuntimePipeDirections(
            anchorCoordinate,
            preferredFluidItemId,
            previewToIgnore,
            actualNeighborDirections,
            baselineConnectionMask);
        List<Vector2Int> fixedConnectorDirections = GetPipeVariantFixedConnectionDirections(
            anchorCoordinate,
            previewToIgnore);
        bool hadFixedConnectorDirections = fixedConnectorDirections.Count > 0;
        RemoveIncompatibleFixedFluidConnectorDirections(
            anchorCoordinate,
            preferredFluidItemId,
            previewToIgnore,
            fixedConnectorDirections);

        List<Vector2Int> connectionDirections = MergePipeDirections(neighborDirections, fixedConnectorDirections);
        List<Vector2Int> actualConnectionDirections = MergePipeDirections(actualNeighborDirections, fixedConnectorDirections);
        int connectionDirectionCount = CountFenceNeighborDirections(connectionDirections);
        int actualConnectionDirectionCount = CountFenceNeighborDirections(actualConnectionDirections);

        // The fixed-connector corner shortcut is valid only for exactly two branches.
        // When a PipeOutput cell also touches a tank, a newly connected pipe forms a tee;
        // returning a corner here would silently discard one of those three connections.
        if (connectionDirectionCount == 2
            && fixedConnectorDirections.Count > 0
            && cornerPrefab != null
            && !HasOppositePipeNeighborDirections(fixedConnectorDirections))
        {
            if (TryResolveFixedConnectorCornerPipeVariant(
                    cornerPrefab,
                    actualNeighborDirections,
                    fixedConnectorDirections,
                    resolvedQuarterTurns,
                    out int fixedConnectorCornerQuarterTurns)
                && CanPipePlacementFluidConnectionsMatch(
                    anchorCoordinate,
                    cornerPrefab,
                    fixedConnectorCornerQuarterTurns,
                    previewToIgnore,
                    baselineConnectionMask)
                || TryResolveFixedConnectorCornerPipeVariant(
                    cornerPrefab,
                    neighborDirections,
                    fixedConnectorDirections,
                    resolvedQuarterTurns,
                    out fixedConnectorCornerQuarterTurns)
                && CanPipePlacementFluidConnectionsMatch(
                    anchorCoordinate,
                    cornerPrefab,
                    fixedConnectorCornerQuarterTurns,
                    previewToIgnore,
                    baselineConnectionMask))
            {
                resolvedPrefab = cornerPrefab;
                resolvedQuarterTurns = fixedConnectorCornerQuarterTurns;
                return true;
            }
        }

        // Current ports encode placement history. Junction degree must instead use
        // every compatible adjacent direction so the final shape is order-independent.
        if (connectionDirectionCount >= 4
            && crossPrefab != null
            && TryResolvePipeVariantQuarterTurns(
                crossPrefab,
                connectionDirections,
                resolvedQuarterTurns,
                out int crossQuarterTurns)
            && CanPipePlacementFluidConnectionsMatch(
                anchorCoordinate,
                crossPrefab,
                crossQuarterTurns,
                previewToIgnore,
                baselineConnectionMask))
        {
            resolvedPrefab = crossPrefab;
            resolvedQuarterTurns = crossQuarterTurns;
            return true;
        }

        if (connectionDirectionCount >= 3
            && teePrefab != null
            && TryResolvePipeVariantQuarterTurns(
                teePrefab,
                connectionDirections,
                resolvedQuarterTurns,
                out int teeQuarterTurns)
            && CanPipePlacementFluidConnectionsMatch(
                anchorCoordinate,
                teePrefab,
                teeQuarterTurns,
                previewToIgnore,
                baselineConnectionMask))
        {
            resolvedPrefab = teePrefab;
            resolvedQuarterTurns = teeQuarterTurns;
            return true;
        }

        List<Vector2Int> boilerConnectorDirections = null;
        if (teePrefab != null
            && TryResolveBoilerTeePipeVariant(
                teePrefab,
                actualNeighborDirections,
                boilerConnectorDirections ??= GetBoilerFixedFluidPipeConnectionDirections(anchorCoordinate, previewToIgnore),
                resolvedQuarterTurns,
                out int boilerTeeQuarterTurns)
            && CanPipePlacementFluidConnectionsMatch(
                anchorCoordinate,
                teePrefab,
                boilerTeeQuarterTurns,
                previewToIgnore,
                baselineConnectionMask))
        {
            resolvedPrefab = teePrefab;
            resolvedQuarterTurns = boilerTeeQuarterTurns;
            return true;
        }

        // If four geometrical neighbours contain a 3:1 fluid split, the cross is
        // invalid but the three compatible branches still form a valid tee. Do
        // not require the tee to cover the already-rejected foreign direction.
        if (actualConnectionDirectionCount >= 3
            && !hadFixedConnectorDirections
            && (boilerConnectorDirections == null || boilerConnectorDirections.Count <= 0)
            && teePrefab != null
            && TryResolveBestCompatibleTeePipeVariant(
                anchorCoordinate,
                teePrefab,
                actualConnectionDirections,
                resolvedQuarterTurns,
                previewToIgnore,
                baselineConnectionMask,
                out int compatibleTeeQuarterTurns))
        {
            resolvedPrefab = teePrefab;
            resolvedQuarterTurns = compatibleTeeQuarterTurns;
            return true;
        }

        if (connectionDirectionCount >= 2
            && cornerPrefab != null
            && HasPerpendicularPipeNeighborDirections(connectionDirections)
            && TryResolvePipeVariantQuarterTurns(
                cornerPrefab,
                connectionDirections,
                resolvedQuarterTurns,
                out int cornerQuarterTurns)
            && CanPipePlacementFluidConnectionsMatch(
                anchorCoordinate,
                cornerPrefab,
                cornerQuarterTurns,
                previewToIgnore,
                baselineConnectionMask))
        {
            resolvedPrefab = cornerPrefab;
            resolvedQuarterTurns = cornerQuarterTurns;
            return true;
        }

        if (cornerPrefab != null
            && TryResolveBoilerCornerPipeVariant(
                cornerPrefab,
                neighborDirections,
                boilerConnectorDirections ??= GetBoilerFixedFluidPipeConnectionDirections(anchorCoordinate, previewToIgnore),
                resolvedQuarterTurns,
                out int boilerCornerQuarterTurns)
            && CanPipePlacementFluidConnectionsMatch(
                anchorCoordinate,
                cornerPrefab,
                boilerCornerQuarterTurns,
                previewToIgnore,
                baselineConnectionMask))
        {
            resolvedPrefab = cornerPrefab;
            resolvedQuarterTurns = boilerCornerQuarterTurns;
            return true;
        }

        resolvedPrefab = straightPrefab != null ? straightPrefab : pipePrototype;
        if (resolvedPrefab is Pipe straightPipePrefab
            && TryResolvePipeStraightQuarterTurns(
                straightPipePrefab,
                connectionDirections,
                resolvedQuarterTurns,
                out int straightQuarterTurns))
        {
            resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                resolvedPrefab,
                straightQuarterTurns);
        }
        else
        {
            resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                resolvedPrefab,
                resolvedQuarterTurns);
        }

        if (resolvedPrefab == null || !(resolvedPrefab is Pipe resolvedPipePrefab))
        {
            return resolvedPrefab != null;
        }

        if (CanPipePlacementFluidConnectionsMatch(
                anchorCoordinate,
                resolvedPipePrefab,
                resolvedQuarterTurns,
                previewToIgnore,
                baselineConnectionMask))
        {
            return true;
        }

        // Keep only compatible branches. If the minimal straight shape still exposes
        // its opposite end to another fluid, select a safe corner instead of rejecting
        // the placement. A foreign branch can therefore never promote this pipe to a
        // tee or cross, and fixed connectors remain untouched.
        if (TryResolveFluidSeparatedPipeVariant(
                anchorCoordinate,
                pipePrototype,
                connectionDirections,
                preferredQuarterTurns,
                previewToIgnore,
                baselineConnectionMask,
                true,
                null,
                out Pipe separatedPipe,
                out int separatedQuarterTurns))
        {
            resolvedPrefab = separatedPipe;
            resolvedQuarterTurns = separatedQuarterTurns;
            return true;
        }

        return false;
    }

    private bool TryGetCurrentRuntimeFluidItemIdAtPipeCoordinate(
        Vector2Int coordinate,
        out int fluidItemId)
    {
        fluidItemId = -1;
        if (InputOutputModule.TryGetRuntimePipeFluidStorageAtCoordinate(
                coordinate,
                null,
                false,
                storage => storage != null && storage.StoredFluidItemId >= 0,
                out InstallationObject storage)
            && storage != null
            && InputOutputModule.IsFluidItemId(storage.StoredFluidItemId))
        {
            fluidItemId = storage.StoredFluidItemId;
            return true;
        }

        if (InputOutputModule.TryGetRuntimePipeSourceAtCoordinate(coordinate, out Pump pump)
            && pump != null
            && pump.TryGetObjectInfoOutputRate(out int pumpFluidItemId, out float litersPerSecond)
            && litersPerSecond > 0.0001f
            && InputOutputModule.IsFluidItemId(pumpFluidItemId))
        {
            fluidItemId = pumpFluidItemId;
            return true;
        }

        if (InputOutputModule.TryGetFluidOutputInfoAtRuntimeGridCoordinate(
                coordinate,
                out int outputFluidItemId,
                out _)
            && InputOutputModule.IsFluidItemId(outputFluidItemId))
        {
            fluidItemId = outputFluidItemId;
            return true;
        }

        return false;
    }

    private bool TryGetPipeEndpointFluidItemIdAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out int fluidItemId)
    {
        fluidItemId = -1;
        HashSet<int> compatibleFluidItemIds = new HashSet<int>();
        bool hasFluidConstraint = false;
        if (TryGetCurrentRuntimeFluidItemIdAtPipeCoordinate(
                coordinate,
                out int runtimeFluidItemId))
        {
            pipeFluidEndpointItemIdsScratch.Clear();
            pipeFluidEndpointItemIdsScratch.Add(runtimeFluidItemId);
            if (!TryMergeFluidCompatibilityConstraint(
                    compatibleFluidItemIds,
                    ref hasFluidConstraint,
                    pipeFluidEndpointItemIdsScratch))
            {
                pipeFluidEndpointItemIdsScratch.Clear();
                return false;
            }

            pipeFluidEndpointItemIdsScratch.Clear();
        }

        List<PipeAreaBlockCandidate> candidates = new List<PipeAreaBlockCandidate>(4);
        List<Vector2Int> candidateDirections = new List<Vector2Int>(4);
        HashSet<int> candidateFluidItemIds = new HashSet<int>();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
            coordinate,
            previewToIgnore,
            candidates);
        for (int candidateIndex = 0; candidateIndex < candidates.Count; candidateIndex++)
        {
            PipeAreaBlockCandidate candidate = candidates[candidateIndex];
            candidateDirections.Clear();
            if (!TryGetPipeAreaCandidateConnectionDirections(
                    coordinate,
                    candidate,
                    candidateDirections))
            {
                continue;
            }

            candidateFluidItemIds.Clear();
            PipeAreaFluidResolution resolution = ResolvePipeAreaCandidateFluidItemIds(
                coordinate,
                candidate,
                candidateFluidItemIds);
            if (resolution == PipeAreaFluidResolution.UnresolvedFluidEndpoint
                || resolution == PipeAreaFluidResolution.Resolved
                && !TryMergeFluidCompatibilityConstraint(
                    compatibleFluidItemIds,
                    ref hasFluidConstraint,
                    candidateFluidItemIds))
            {
                return false;
            }
        }

        if (!hasFluidConstraint || compatibleFluidItemIds.Count != 1)
        {
            return false;
        }

        foreach (int candidateFluidItemId in compatibleFluidItemIds)
        {
            fluidItemId = candidateFluidItemId;
            return true;
        }

        return false;
    }

    private bool TryResolvePipeStraightQuarterTurns(
        Pipe straightPrefab,
        IReadOnlyList<Vector2Int> neighborDirections,
        int preferredQuarterTurns,
        out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        if (straightPrefab == null || neighborDirections == null || neighborDirections.Count <= 0)
        {
            return false;
        }

        Vector2Int targetDirection = Vector2Int.zero;
        for (int i = 0; i < neighborDirections.Count; i++)
        {
            Vector2Int neighborDirection = neighborDirections[i];
            if (neighborDirection == Vector2Int.zero)
            {
                continue;
            }

            if (targetDirection == Vector2Int.zero)
            {
                targetDirection = neighborDirection;
                continue;
            }

            if (neighborDirection != targetDirection && neighborDirection != -targetDirection)
            {
                return false;
            }
        }

        if (targetDirection == Vector2Int.zero)
        {
            return false;
        }

        int normalizedPreferredQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        for (int offset = 0; offset < 4; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurns(normalizedPreferredQuarterTurns + offset);
            Quaternion candidateRotation = GetPlacementObjectRotation(straightPrefab, candidateQuarterTurns);
            if (straightPrefab.HasConnectionTowards(candidateRotation, targetDirection))
            {
                resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                    straightPrefab,
                    candidateQuarterTurns);
                return true;
            }
        }

        return false;
    }

    private bool TryResolvePipeVariantQuarterTurns(
        Pipe pipePrefab,
        IReadOnlyList<Vector2Int> neighborDirections,
        int preferredQuarterTurns,
        out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        if (pipePrefab == null || neighborDirections == null || neighborDirections.Count <= 0)
        {
            return false;
        }

        int normalizedPreferredQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        for (int offset = 0; offset < 4; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurns(normalizedPreferredQuarterTurns + offset);
            Quaternion candidateRotation = GetPlacementObjectRotation(pipePrefab, candidateQuarterTurns);
            bool allDirectionsConnected = true;
            for (int i = 0; i < neighborDirections.Count; i++)
            {
                Vector2Int direction = neighborDirections[i];
                if (direction == Vector2Int.zero)
                {
                    continue;
                }

                if (!pipePrefab.HasConnectionTowards(candidateRotation, direction))
                {
                    allDirectionsConnected = false;
                    break;
                }
            }

            if (allDirectionsConnected)
            {
                resolvedQuarterTurns = candidateQuarterTurns;
                return true;
            }
        }

        return false;
    }

    private bool TryResolveBestCompatibleTeePipeVariant(
        Vector2Int anchorCoordinate,
        Pipe teePrefab,
        IReadOnlyList<Vector2Int> desiredDirections,
        int preferredQuarterTurns,
        MapObject previewToIgnore,
        int baselineConnectionMask,
        out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        if (teePrefab == null || desiredDirections == null || desiredDirections.Count < 3)
        {
            return false;
        }

        int normalizedPreferredQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        for (int offset = 0; offset < 4; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurns(
                normalizedPreferredQuarterTurns + offset);
            Quaternion candidateRotation = GetPlacementObjectRotation(
                teePrefab,
                candidateQuarterTurns);
            int connectedDesiredDirectionCount = 0;
            for (int directionIndex = 0;
                 directionIndex < desiredDirections.Count;
                 directionIndex++)
            {
                Vector2Int direction = desiredDirections[directionIndex];
                if (direction != Vector2Int.zero
                    && teePrefab.HasConnectionTowards(candidateRotation, direction))
                {
                    connectedDesiredDirectionCount++;
                }
            }

            if (connectedDesiredDirectionCount < 3
                || !CanPipePlacementFluidConnectionsMatch(
                    anchorCoordinate,
                    teePrefab,
                    candidateRotation,
                    previewToIgnore,
                    baselineConnectionMask))
            {
                continue;
            }

            resolvedQuarterTurns = candidateQuarterTurns;
            return true;
        }

        return false;
    }

    private static List<Vector2Int> MergePipeDirections(
        IReadOnlyList<Vector2Int> firstDirections,
        IReadOnlyList<Vector2Int> secondDirections)
    {
        List<Vector2Int> mergedDirections = new List<Vector2Int>(4);
        AddPipeDirections(mergedDirections, firstDirections);
        AddPipeDirections(mergedDirections, secondDirections);
        return mergedDirections;
    }

    private static void AddPipeDirections(
        List<Vector2Int> targetDirections,
        IReadOnlyList<Vector2Int> sourceDirections)
    {
        if (targetDirections == null || sourceDirections == null)
        {
            return;
        }

        for (int i = 0; i < sourceDirections.Count; i++)
        {
            AddPipeDirection(targetDirections, sourceDirections[i]);
        }
    }

    private bool TryResolveBoilerTeePipeVariant(
        Pipe teePrefab,
        IReadOnlyList<Vector2Int> neighborDirections,
        IReadOnlyList<Vector2Int> boilerNeighborDirections,
        int preferredQuarterTurns,
        out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        if (teePrefab == null || boilerNeighborDirections == null || boilerNeighborDirections.Count <= 0)
        {
            return false;
        }

        for (int i = 0; i < boilerNeighborDirections.Count; i++)
        {
            Vector2Int boilerDirection = boilerNeighborDirections[i];
            if (boilerDirection == Vector2Int.zero)
            {
                continue;
            }

            Vector2Int clockwiseDirection = RotateCardinalDirectionClockwise(boilerDirection);
            Vector2Int counterClockwiseDirection = RotateCardinalDirectionCounterClockwise(boilerDirection);
            if (!PipeDirectionsContain(neighborDirections, clockwiseDirection)
                || !PipeDirectionsContain(neighborDirections, counterClockwiseDirection))
            {
                continue;
            }

            List<Vector2Int> requiredDirections = new List<Vector2Int>(3);
            AddPipeDirection(requiredDirections, boilerDirection);
            AddPipeDirection(requiredDirections, clockwiseDirection);
            AddPipeDirection(requiredDirections, counterClockwiseDirection);

            if (!PipeDirectionsContainAll(requiredDirections, neighborDirections))
            {
                continue;
            }

            if (TryResolvePipeVariantQuarterTurns(
                    teePrefab,
                    requiredDirections,
                    preferredQuarterTurns,
                    out resolvedQuarterTurns))
            {
                return true;
            }
        }

        return false;
    }

    private bool TryResolveBoilerCornerPipeVariant(
        Pipe cornerPrefab,
        IReadOnlyList<Vector2Int> neighborDirections,
        IReadOnlyList<Vector2Int> boilerNeighborDirections,
        int preferredQuarterTurns,
        out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        if (cornerPrefab == null
            || neighborDirections == null
            || neighborDirections.Count <= 0
            || boilerNeighborDirections == null
            || boilerNeighborDirections.Count <= 0)
        {
            return false;
        }

        int normalizedPreferredQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        for (int offset = 0; offset < 4; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurns(normalizedPreferredQuarterTurns + offset);
            Quaternion candidateRotation = GetPlacementObjectRotation(cornerPrefab, candidateQuarterTurns);

            for (int boilerIndex = 0; boilerIndex < boilerNeighborDirections.Count; boilerIndex++)
            {
                Vector2Int boilerDirection = boilerNeighborDirections[boilerIndex];
                if (boilerDirection == Vector2Int.zero
                    || !cornerPrefab.HasConnectionTowards(candidateRotation, boilerDirection))
                {
                    continue;
                }

                for (int neighborIndex = 0; neighborIndex < neighborDirections.Count; neighborIndex++)
                {
                    Vector2Int neighborDirection = neighborDirections[neighborIndex];
                    if (neighborDirection == Vector2Int.zero
                        || !DirectionsArePerpendicular(boilerDirection, neighborDirection)
                        || !cornerPrefab.HasConnectionTowards(candidateRotation, neighborDirection))
                    {
                        continue;
                    }

                    resolvedQuarterTurns = candidateQuarterTurns;
                    return true;
                }
            }
        }

        return false;
    }

    private bool TryResolveFixedConnectorCornerPipeVariant(
        Pipe cornerPrefab,
        IReadOnlyList<Vector2Int> actualNeighborDirections,
        IReadOnlyList<Vector2Int> fixedConnectorDirections,
        int preferredQuarterTurns,
        out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        if (cornerPrefab == null
            || CountFenceNeighborDirections(actualNeighborDirections) != 1
            || fixedConnectorDirections == null
            || fixedConnectorDirections.Count <= 0)
        {
            return false;
        }

        Vector2Int actualNeighborDirection = Vector2Int.zero;
        for (int i = 0; i < actualNeighborDirections.Count; i++)
        {
            if (actualNeighborDirections[i] != Vector2Int.zero)
            {
                actualNeighborDirection = actualNeighborDirections[i];
                break;
            }
        }

        if (actualNeighborDirection == Vector2Int.zero)
        {
            return false;
        }

        for (int i = 0; i < fixedConnectorDirections.Count; i++)
        {
            Vector2Int fixedConnectorDirection = fixedConnectorDirections[i];
            if (fixedConnectorDirection == Vector2Int.zero
                || !DirectionsArePerpendicular(actualNeighborDirection, fixedConnectorDirection))
            {
                continue;
            }

            List<Vector2Int> requiredDirections = new List<Vector2Int>(2);
            AddPipeDirection(requiredDirections, actualNeighborDirection);
            AddPipeDirection(requiredDirections, fixedConnectorDirection);
            if (TryResolvePipeVariantQuarterTurns(
                    cornerPrefab,
                    requiredDirections,
                    preferredQuarterTurns,
                    out resolvedQuarterTurns))
            {
                return true;
            }
        }

        return false;
    }

    private static void AddPipeDirection(List<Vector2Int> directions, Vector2Int direction)
    {
        if (directions == null || direction == Vector2Int.zero || directions.Contains(direction))
        {
            return;
        }

        directions.Add(direction);
    }

    private static bool PipeDirectionsContainAll(
        IReadOnlyList<Vector2Int> availableDirections,
        IReadOnlyList<Vector2Int> requiredDirections)
    {
        if (requiredDirections == null || requiredDirections.Count <= 0)
        {
            return true;
        }

        if (availableDirections == null)
        {
            return false;
        }

        for (int i = 0; i < requiredDirections.Count; i++)
        {
            Vector2Int direction = requiredDirections[i];
            if (direction != Vector2Int.zero && !PipeDirectionsContain(availableDirections, direction))
            {
                return false;
            }
        }

        return true;
    }

    private static bool PipeDirectionsContain(IReadOnlyList<Vector2Int> directions, Vector2Int direction)
    {
        if (directions == null)
        {
            return false;
        }

        for (int i = 0; i < directions.Count; i++)
        {
            if (directions[i] == direction)
            {
                return true;
            }
        }

        return false;
    }

    private static Vector2Int RotateCardinalDirectionClockwise(Vector2Int direction)
    {
        return new Vector2Int(direction.y, -direction.x);
    }

    private static Vector2Int RotateCardinalDirectionCounterClockwise(Vector2Int direction)
    {
        return new Vector2Int(-direction.y, direction.x);
    }

    private static bool HasPerpendicularPipeNeighborDirections(IReadOnlyList<Vector2Int> neighborDirections)
    {
        if (neighborDirections == null || neighborDirections.Count < 2)
        {
            return false;
        }

        for (int i = 0; i < neighborDirections.Count; i++)
        {
            for (int j = i + 1; j < neighborDirections.Count; j++)
            {
                if (DirectionsArePerpendicular(neighborDirections[i], neighborDirections[j]))
                {
                    return true;
                }
            }
        }

        return false;
    }

    private static bool HasOppositePipeNeighborDirections(IReadOnlyList<Vector2Int> neighborDirections)
    {
        if (neighborDirections == null || neighborDirections.Count < 2)
        {
            return false;
        }

        for (int i = 0; i < neighborDirections.Count; i++)
        {
            Vector2Int firstDirection = neighborDirections[i];
            if (firstDirection == Vector2Int.zero)
            {
                continue;
            }

            for (int j = i + 1; j < neighborDirections.Count; j++)
            {
                Vector2Int secondDirection = neighborDirections[j];
                if (secondDirection != Vector2Int.zero && secondDirection == -firstDirection)
                {
                    return true;
                }
            }
        }

        return false;
    }

    private List<Vector2Int> GetPipeNeighborConnectionDirections(
        Pipe pipePrototype,
        Vector2Int anchorCoordinate,
        MapObject previewToIgnore,
        bool allowPotentialConnections,
        int preferredFluidItemId)
    {
        List<Vector2Int> directions = new List<Vector2Int>(4);
        // A single pipe variant must not borrow shape directions from incompatible fluid networks.
        HashSet<int> acceptedFluidItemIds = new HashSet<int>();
        bool hasAcceptedFluidConstraint = preferredFluidItemId >= 0;
        if (hasAcceptedFluidConstraint)
        {
            acceptedFluidItemIds.Add(preferredFluidItemId);
        }

        for (int i = 0; i < PipeCardinalDirections.Length; i++)
        {
            Vector2Int sideDirection = PipeCardinalDirections[i];
            if (TryGetPipeOnlyConnectionAtCoordinate(
                    pipePrototype,
                    anchorCoordinate + sideDirection,
                    previewToIgnore,
                    -sideDirection,
                    allowPotentialConnections,
                    acceptedFluidItemIds,
                    ref hasAcceptedFluidConstraint,
                    PipeNeighborConnectionSearchMode.PreviewOnly))
            {
                directions.Add(sideDirection);
            }
        }

        // During topology resolution, compatible adjacency is authoritative even
        // when neither current shape has exposed a port yet. Evaluate installed
        // pipes as potential connections so both ends resolve symmetrically.
        for (int i = 0; i < PipeCardinalDirections.Length; i++)
        {
            Vector2Int sideDirection = PipeCardinalDirections[i];
            if (PipeDirectionsContain(directions, sideDirection))
            {
                continue;
            }

            if (TryGetPipeOnlyConnectionAtCoordinate(
                    pipePrototype,
                    anchorCoordinate + sideDirection,
                    previewToIgnore,
                    -sideDirection,
                    allowPotentialConnections,
                    acceptedFluidItemIds,
                    ref hasAcceptedFluidConstraint,
                    PipeNeighborConnectionSearchMode.NonPreviewOnly))
            {
                directions.Add(sideDirection);
            }
        }

        return directions;
    }

    private bool TryGetPipeOnlyConnectionAtCoordinate(
        Pipe pipePrototype,
        Vector2Int coordinate,
        MapObject previewToIgnore,
        Vector2Int directionToCandidate,
        bool allowPotentialConnections,
        HashSet<int> acceptedFluidItemIds,
        ref bool hasAcceptedFluidConstraint,
        PipeNeighborConnectionSearchMode searchMode)
    {
        if (directionToCandidate == Vector2Int.zero)
        {
            return false;
        }

        if (searchMode != PipeNeighborConnectionSearchMode.NonPreviewOnly
            && TryGetInstallPreviewAtCoordinate(coordinate, out MapObject preview)
            && preview != null
            && preview != previewToIgnore
            && preview is Pipe previewPipe
            && ShouldPipeNeighborContributeToVariant(
                coordinate,
                previewPipe,
                preview.transform.rotation,
                directionToCandidate,
                allowPotentialConnections)
            && CanPipeNeighborContributeToVariant(
                pipePrototype,
                coordinate + directionToCandidate,
                coordinate,
                previewPipe,
                preview.transform.rotation,
                directionToCandidate,
                previewToIgnore,
                allowPotentialConnections,
                acceptedFluidItemIds,
                ref hasAcceptedFluidConstraint))
        {
            return true;
        }

        if (searchMode == PipeNeighborConnectionSearchMode.PreviewOnly)
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain != null
            && terrain.TryGetLoadedBlock(coordinate, out Block block)
            && block != null
            && block.MapObject is Pipe installedPipe
            && installedPipe.gameObject.activeInHierarchy)
        {
            Pipe pipeToEvaluate = installedPipe;
            Quaternion pipeRotation = installedPipe.transform.rotation;
            if (TryGetInstalledPipeVariantPreview(installedPipe, out Pipe variantPreviewPipe, out Quaternion previewRotation))
            {
                pipeToEvaluate = variantPreviewPipe;
                pipeRotation = previewRotation;
            }

            if (ShouldPipeNeighborContributeToVariant(
                    coordinate,
                    pipeToEvaluate,
                    pipeRotation,
                    directionToCandidate,
                    allowPotentialConnections)
                && CanPipeNeighborContributeToVariant(
                    pipePrototype,
                    coordinate + directionToCandidate,
                    coordinate,
                    pipeToEvaluate,
                    pipeRotation,
                    directionToCandidate,
                    previewToIgnore,
                    allowPotentialConnections,
                    acceptedFluidItemIds,
                    ref hasAcceptedFluidConstraint))
            {
                return true;
            }
        }

        return TryGetSavedPipePlacementAtCoordinate(
                   coordinate,
                   out Pipe savedPipe,
                   out Quaternion savedRotation)
               && ShouldPipeNeighborContributeToVariant(
                   coordinate,
                   savedPipe,
                   savedRotation,
                   directionToCandidate,
                   allowPotentialConnections)
               && CanPipeNeighborContributeToVariant(
                   pipePrototype,
                   coordinate + directionToCandidate,
                   coordinate,
                   savedPipe,
                   savedRotation,
                   directionToCandidate,
                   previewToIgnore,
                   allowPotentialConnections,
                   acceptedFluidItemIds,
                   ref hasAcceptedFluidConstraint);
    }

    private bool CanPipeNeighborContributeToVariant(
        Pipe pipePrototype,
        Vector2Int candidateCoordinate,
        Vector2Int neighborCoordinate,
        Pipe neighborPipe,
        Quaternion neighborRotation,
        Vector2Int directionToCandidate,
        MapObject previewToIgnore,
        bool allowPotentialConnections,
        HashSet<int> acceptedFluidItemIds,
        ref bool hasAcceptedFluidConstraint)
    {
        if (pipePrototype == null || neighborPipe == null || directionToCandidate == Vector2Int.zero)
        {
            return true;
        }

        Pipe neighborPipeForFluidMatch = neighborPipe;
        Quaternion neighborRotationForFluidMatch = neighborRotation;
        if (!HasEffectivePipeConnectionTowardsAt(
                neighborCoordinate,
                neighborPipeForFluidMatch,
                neighborRotationForFluidMatch,
                directionToCandidate))
        {
            if (!allowPotentialConnections
                || !TryResolvePipeVariantForForcedConnection(
                    neighborCoordinate,
                    neighborPipe,
                    neighborRotation,
                    directionToCandidate,
                    out neighborPipeForFluidMatch,
                    out neighborRotationForFluidMatch,
                    previewToIgnore))
            {
                return false;
            }
        }

        HashSet<int> candidateFluidItemIds = new HashSet<int>();
        bool hasCandidateFluidConstraint = false;
        if (!TryCollectCandidatePipeFluidConstraintsForNeighborDirection(
                pipePrototype,
                candidateCoordinate,
                -directionToCandidate,
                previewToIgnore,
                candidateFluidItemIds,
                ref hasCandidateFluidConstraint))
        {
            return false;
        }

        if (hasAcceptedFluidConstraint
            && !TryMergeFluidCompatibilityConstraint(
                candidateFluidItemIds,
                ref hasCandidateFluidConstraint,
                acceptedFluidItemIds))
        {
            return false;
        }

        HashSet<int> neighborFluidItemIds = new HashSet<int>();
        bool hasNeighborFluidConstraint = false;
        if (!TryCollectPipeNetworkFluidConstraintsExcludingConnection(
                neighborCoordinate,
                neighborPipeForFluidMatch,
                neighborRotationForFluidMatch,
                previewToIgnore,
                neighborCoordinate,
                directionToCandidate,
                neighborFluidItemIds,
                ref hasNeighborFluidConstraint))
        {
            return false;
        }

        if (hasNeighborFluidConstraint
            && !TryMergeFluidCompatibilityConstraint(
                candidateFluidItemIds,
                ref hasCandidateFluidConstraint,
                neighborFluidItemIds))
        {
            return false;
        }

        return !hasCandidateFluidConstraint
               || TryMergeFluidCompatibilityConstraint(
                   acceptedFluidItemIds,
                   ref hasAcceptedFluidConstraint,
                   candidateFluidItemIds);
    }

    private bool TryCollectCandidatePipeFluidConstraintsForNeighborDirection(
        Pipe pipePrototype,
        Vector2Int candidateCoordinate,
        Vector2Int directionToNeighbor,
        MapObject previewToIgnore,
        HashSet<int> candidateFluidItemIds,
        ref bool hasCandidateFluidConstraint)
    {
        if (pipePrototype == null || directionToNeighbor == Vector2Int.zero)
        {
            return true;
        }

        if (TryGetPipePlacementAtCoordinate(
                candidateCoordinate,
                previewToIgnore,
                out Pipe existingCandidatePipe,
                out Quaternion existingCandidateRotation)
            && existingCandidatePipe != null
            && !TryCollectPipeNetworkFluidConstraintsExcludingConnection(
                candidateCoordinate,
                existingCandidatePipe,
                existingCandidateRotation,
                previewToIgnore,
                candidateCoordinate,
                directionToNeighbor,
                candidateFluidItemIds,
                ref hasCandidateFluidConstraint))
        {
            return false;
        }

        List<Vector2Int> candidateDirections = new List<Vector2Int>(4);
        AddPipeDirection(candidateDirections, directionToNeighbor);
        AddPipeDirections(
            candidateDirections,
            GetPipeVariantFixedConnectionDirections(candidateCoordinate, previewToIgnore));

        if (!TryResolvePipeVariantForConnectionDirections(
                pipePrototype,
                candidateDirections,
                0,
                out Pipe candidatePipe,
                out int candidateQuarterTurns)
            || candidatePipe == null)
        {
            return false;
        }

        return TryCollectPipeNetworkFluidConstraintsExcludingConnection(
            candidateCoordinate,
            candidatePipe,
            GetPlacementObjectRotation(candidatePipe, candidateQuarterTurns),
            previewToIgnore,
            candidateCoordinate,
            directionToNeighbor,
            candidateFluidItemIds,
            ref hasCandidateFluidConstraint);
    }

    private bool CanPipePlacementFluidConnectionsMatch(
        Vector2Int pipeCoordinate,
        Pipe pipePrefab,
        int quarterTurns,
        MapObject previewToIgnore,
        int baselineConnectionMask = 0)
    {
        if (pipePrefab == null)
        {
            return false;
        }

        return CanPipePlacementFluidConnectionsMatch(
            pipeCoordinate,
            pipePrefab,
            GetPlacementObjectRotation(pipePrefab, quarterTurns),
            previewToIgnore,
            baselineConnectionMask);
    }

    private bool CanPipePlacementFluidConnectionsMatch(
        Vector2Int pipeCoordinate,
        Pipe pipe,
        Quaternion pipeRotation,
        MapObject previewToIgnore,
        int baselineConnectionMask = 0)
    {
        if (pipe == null)
        {
            return false;
        }

        HashSet<int> compatibleFluidItemIds = new HashSet<int>();
        bool hasFluidConstraint = false;
        if (!TryCollectPipeNetworkFluidConstraints(
                pipeCoordinate,
                pipe,
                pipeRotation,
                previewToIgnore,
                compatibleFluidItemIds,
                ref hasFluidConstraint))
        {
            return false;
        }

        // The normal network walk follows only mutually facing pipe ends. A newly
        // resolved tee/cross can expose a side towards a neighbouring corner that
        // is currently bent away, so that side was previously invisible to the
        // compatibility check. Validate those newly exposed sides as well; a pipe
        // variant must never point into a different-fluid branch. Existing ports in
        // the baseline stay separated when the neighbour is already bent away.
        for (int directionIndex = 0;
             directionIndex < PipeCardinalDirections.Length;
            directionIndex++)
        {
            Vector2Int direction = PipeCardinalDirections[directionIndex];
            if (PipeConnectionMaskContainsDirection(baselineConnectionMask, direction)
                || !pipe.HasConnectionTowardsAt(pipeCoordinate, pipeRotation, direction))
            {
                continue;
            }

            Vector2Int neighborCoordinate = pipeCoordinate + direction;
            if (!TryGetPipePlacementAtCoordinate(
                    neighborCoordinate,
                    previewToIgnore,
                    out Pipe neighborPipe,
                    out Quaternion neighborRotation)
                || neighborPipe == null
                || HasEffectivePipeConnectionTowardsAt(
                    neighborCoordinate,
                    neighborPipe,
                    neighborRotation,
                    -direction))
            {
                continue;
            }

            HashSet<int> neighborBranchFluidItemIds = new HashSet<int>();
            bool hasNeighborBranchFluidConstraint = false;
            if (!TryCollectPipeNetworkFluidConstraintsExcludingConnection(
                    neighborCoordinate,
                    neighborPipe,
                    neighborRotation,
                    previewToIgnore,
                    neighborCoordinate,
                    -direction,
                    neighborBranchFluidItemIds,
                    ref hasNeighborBranchFluidConstraint)
                || hasNeighborBranchFluidConstraint
                && !TryMergeFluidCompatibilityConstraint(
                    compatibleFluidItemIds,
                    ref hasFluidConstraint,
                    neighborBranchFluidItemIds))
            {
                return false;
            }
        }

        return true;
    }

    private bool TryResolvePipeVariantForForcedConnection(
        Vector2Int pipeCoordinate,
        Pipe existingPipe,
        Quaternion existingPipeRotation,
        Vector2Int requiredConnectionDirection,
        out Pipe resolvedPipe,
        out Quaternion resolvedPipeRotation,
        MapObject previewToIgnore = null)
    {
        resolvedPipe = existingPipe;
        resolvedPipeRotation = existingPipeRotation;
        if (existingPipe == null || requiredConnectionDirection == Vector2Int.zero)
        {
            return false;
        }

        if (existingPipe is UndergroundPipe)
        {
            return HasEffectivePipeConnectionTowardsAt(
                pipeCoordinate,
                existingPipe,
                existingPipeRotation,
                requiredConnectionDirection);
        }

        int baselineConnectionMask = existingPipe.GetConnectionMask(existingPipeRotation);
        int preferredQuarterTurns = 0;
        if (existingPipe.TryGetPlacementRuntime(out _, out int runtimeQuarterTurns))
        {
            preferredQuarterTurns = runtimeQuarterTurns;
        }
        else if (TryResolvePlacementQuarterTurnsFromRotation(
                     existingPipe,
                     existingPipeRotation,
                     out int rotationQuarterTurns))
        {
            preferredQuarterTurns = rotationQuarterTurns;
        }

        Pipe pipePrototype = existingPipe.StraightVariantPrefab != null
            ? existingPipe.StraightVariantPrefab
            : existingPipe;

        TryGetPipeVariantAnchorFluidItemId(
            pipeCoordinate,
            previewToIgnore,
            out int anchorFluidItemId);
        int preferredFluidItemId = ResolvePreferredPipeVariantFluidItemId(
            pipeCoordinate,
            anchorFluidItemId,
            previewToIgnore);
        List<Vector2Int> requiredDirections = GetPipeNeighborConnectionDirections(
            pipePrototype,
            pipeCoordinate,
            previewToIgnore,
            false,
            preferredFluidItemId);
        RemoveIncompatibleRuntimePipeDirections(
            pipeCoordinate,
            preferredFluidItemId,
            previewToIgnore,
            requiredDirections,
            baselineConnectionMask);

        List<Vector2Int> fixedConnectorDirections = GetPipeVariantFixedConnectionDirections(
            pipeCoordinate,
            previewToIgnore);
        RemoveIncompatibleFixedFluidConnectorDirections(
            pipeCoordinate,
            preferredFluidItemId,
            previewToIgnore,
            fixedConnectorDirections);
        AddPipeDirections(requiredDirections, fixedConnectorDirections);
        AddPipeDirection(requiredDirections, requiredConnectionDirection);

        if (!TryResolvePipeVariantForConnectionDirections(
                pipePrototype,
                requiredDirections,
                preferredQuarterTurns,
                out Pipe resolvedPipePrefab,
                out int resolvedQuarterTurns)
            || resolvedPipePrefab == null)
        {
            return existingPipe.HasConnectionTowards(existingPipeRotation, requiredConnectionDirection)
                   && CanPipePlacementFluidConnectionsMatch(
                       pipeCoordinate,
                       existingPipe,
                       existingPipeRotation,
                       previewToIgnore,
                       baselineConnectionMask);
        }

        Quaternion candidateRotation = GetPlacementObjectRotation(resolvedPipePrefab, resolvedQuarterTurns);
        if (!resolvedPipePrefab.HasConnectionTowards(candidateRotation, requiredConnectionDirection)
            || !CanPipePlacementFluidConnectionsMatch(
                pipeCoordinate,
                resolvedPipePrefab,
                candidateRotation,
                previewToIgnore,
                baselineConnectionMask))
        {
            if (!TryResolveFluidSeparatedPipeVariant(
                    pipeCoordinate,
                    pipePrototype,
                    requiredDirections,
                    preferredQuarterTurns,
                    previewToIgnore,
                    baselineConnectionMask,
                    true,
                    null,
                    out resolvedPipePrefab,
                    out resolvedQuarterTurns))
            {
                return false;
            }

            candidateRotation = GetPlacementObjectRotation(
                resolvedPipePrefab,
                resolvedQuarterTurns);
            if (!resolvedPipePrefab.HasConnectionTowards(
                    candidateRotation,
                    requiredConnectionDirection))
            {
                return false;
            }
        }

        resolvedPipe = resolvedPipePrefab;
        resolvedPipeRotation = candidateRotation;
        return true;
    }

    private bool TryResolvePipeVariantForConnectionDirections(
        Pipe pipePrototype,
        IReadOnlyList<Vector2Int> requiredDirections,
        int preferredQuarterTurns,
        out Pipe resolvedPipe,
        out int resolvedQuarterTurns)
    {
        resolvedPipe = null;
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        if (pipePrototype == null)
        {
            return false;
        }

        Pipe straightPrefab = pipePrototype.StraightVariantPrefab != null
            ? pipePrototype.StraightVariantPrefab
            : pipePrototype;
        Pipe cornerPrefab = pipePrototype.CornerVariantPrefab;
        Pipe teePrefab = pipePrototype.TeeVariantPrefab;
        Pipe crossPrefab = pipePrototype.CrossVariantPrefab;
        int directionCount = CountFenceNeighborDirections(requiredDirections);

        if (directionCount >= 4
            && crossPrefab != null
            && TryResolvePipeVariantQuarterTurns(
                crossPrefab,
                requiredDirections,
                preferredQuarterTurns,
                out resolvedQuarterTurns))
        {
            resolvedPipe = crossPrefab;
            return true;
        }

        if (directionCount >= 3
            && teePrefab != null
            && TryResolvePipeVariantQuarterTurns(
                teePrefab,
                requiredDirections,
                preferredQuarterTurns,
                out resolvedQuarterTurns))
        {
            resolvedPipe = teePrefab;
            return true;
        }

        if (directionCount >= 2
            && cornerPrefab != null
            && HasPerpendicularPipeNeighborDirections(requiredDirections)
            && TryResolvePipeVariantQuarterTurns(
                cornerPrefab,
                requiredDirections,
                preferredQuarterTurns,
                out resolvedQuarterTurns))
        {
            resolvedPipe = cornerPrefab;
            return true;
        }

        if (directionCount >= 1
            && straightPrefab != null
            && TryResolvePipeStraightQuarterTurns(
                straightPrefab,
                requiredDirections,
                preferredQuarterTurns,
                out resolvedQuarterTurns))
        {
            resolvedPipe = straightPrefab;
            return true;
        }

        return false;
    }

    private bool TryResolveFluidSeparatedPipeVariant(
        Vector2Int pipeCoordinate,
        Pipe pipePrototype,
        IReadOnlyList<Vector2Int> requiredDirections,
        int preferredQuarterTurns,
        MapObject previewToIgnore,
        int baselineConnectionMask,
        bool allowCornerForSingleDirection,
        IReadOnlyList<Vector2Int> forbiddenDirections,
        out Pipe resolvedPipe,
        out int resolvedQuarterTurns,
        bool enforceFluidCompatibility = true)
    {
        resolvedPipe = null;
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        if (pipePrototype == null)
        {
            return false;
        }

        Pipe straightPrefab = pipePrototype.StraightVariantPrefab != null
            ? pipePrototype.StraightVariantPrefab
            : pipePrototype;
        Pipe cornerPrefab = pipePrototype.CornerVariantPrefab;
        int directionCount = CountFenceNeighborDirections(requiredDirections);

        if (directionCount >= 4)
        {
            return TryResolveCompatiblePipeVariantCandidate(
                pipeCoordinate,
                pipePrototype.CrossVariantPrefab,
                requiredDirections,
                preferredQuarterTurns,
                previewToIgnore,
                baselineConnectionMask,
                forbiddenDirections,
                enforceFluidCompatibility,
                out resolvedPipe,
                out resolvedQuarterTurns);
        }

        if (directionCount == 3)
        {
            return TryResolveCompatiblePipeVariantCandidate(
                pipeCoordinate,
                pipePrototype.TeeVariantPrefab,
                requiredDirections,
                preferredQuarterTurns,
                previewToIgnore,
                baselineConnectionMask,
                forbiddenDirections,
                enforceFluidCompatibility,
                out resolvedPipe,
                out resolvedQuarterTurns);
        }

        if (directionCount == 2)
        {
            Pipe twoDirectionPrefab = HasPerpendicularPipeNeighborDirections(requiredDirections)
                ? cornerPrefab
                : straightPrefab;
            return TryResolveCompatiblePipeVariantCandidate(
                pipeCoordinate,
                twoDirectionPrefab,
                requiredDirections,
                preferredQuarterTurns,
                previewToIgnore,
                baselineConnectionMask,
                forbiddenDirections,
                enforceFluidCompatibility,
                out resolvedPipe,
                out resolvedQuarterTurns);
        }

        if (TryResolveCompatiblePipeVariantCandidate(
                pipeCoordinate,
                straightPrefab,
                requiredDirections,
                preferredQuarterTurns,
                previewToIgnore,
                baselineConnectionMask,
                forbiddenDirections,
                enforceFluidCompatibility,
                out resolvedPipe,
                out resolvedQuarterTurns))
        {
            return true;
        }

        return allowCornerForSingleDirection
               && TryResolveCompatiblePipeVariantCandidate(
                   pipeCoordinate,
                   cornerPrefab,
                   requiredDirections,
                   preferredQuarterTurns,
                   previewToIgnore,
                   baselineConnectionMask,
                   forbiddenDirections,
                   enforceFluidCompatibility,
                   out resolvedPipe,
                   out resolvedQuarterTurns);
    }

    private bool TryResolveCompatiblePipeVariantCandidate(
        Vector2Int pipeCoordinate,
        Pipe candidatePrefab,
        IReadOnlyList<Vector2Int> requiredDirections,
        int preferredQuarterTurns,
        MapObject previewToIgnore,
        int baselineConnectionMask,
        IReadOnlyList<Vector2Int> forbiddenDirections,
        bool enforceFluidCompatibility,
        out Pipe resolvedPipe,
        out int resolvedQuarterTurns)
    {
        resolvedPipe = null;
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        if (candidatePrefab == null)
        {
            return false;
        }

        int normalizedPreferredQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        for (int offset = 0; offset < 4; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurns(
                normalizedPreferredQuarterTurns + offset);
            Quaternion candidateRotation = GetPlacementObjectRotation(
                candidatePrefab,
                candidateQuarterTurns);
            if (forbiddenDirections != null
                && forbiddenDirections.Count > 0
                && PipeHasConnectionTowardsAnyDirection(
                    candidatePrefab,
                    candidateRotation,
                    forbiddenDirections))
            {
                continue;
            }

            bool containsRequiredDirections = true;
            if (requiredDirections != null)
            {
                for (int directionIndex = 0;
                     directionIndex < requiredDirections.Count;
                     directionIndex++)
                {
                    Vector2Int direction = requiredDirections[directionIndex];
                    if (direction != Vector2Int.zero
                        && !candidatePrefab.HasConnectionTowards(
                            candidateRotation,
                            direction))
                    {
                        containsRequiredDirections = false;
                        break;
                    }
                }
            }

            if (!containsRequiredDirections
                || enforceFluidCompatibility
                && !CanPipePlacementFluidConnectionsMatch(
                    pipeCoordinate,
                    candidatePrefab,
                    candidateRotation,
                    previewToIgnore,
                    baselineConnectionMask))
            {
                continue;
            }

            resolvedPipe = candidatePrefab;
            resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                candidatePrefab,
                candidateQuarterTurns);
            return true;
        }

        return false;
    }

    private bool TryResolvePipeVariantAvoidingConnections(
        Vector2Int pipeCoordinate,
        Pipe existingPipe,
        Quaternion existingPipeRotation,
        IReadOnlyList<Vector2Int> forbiddenDirections,
        MapObject previewToIgnore,
        out Pipe resolvedPipe,
        out Quaternion resolvedPipeRotation)
    {
        resolvedPipe = existingPipe;
        resolvedPipeRotation = existingPipeRotation;
        if (existingPipe == null
            || existingPipe is UndergroundPipe
            || forbiddenDirections == null
            || forbiddenDirections.Count <= 0)
        {
            return false;
        }

        Pipe pipePrototype = existingPipe.StraightVariantPrefab != null
            ? existingPipe.StraightVariantPrefab
            : existingPipe;
        int preferredQuarterTurns = 0;
        if (existingPipe.TryGetPlacementRuntime(out _, out int runtimeQuarterTurns))
        {
            preferredQuarterTurns = runtimeQuarterTurns;
        }
        else
        {
            TryResolvePlacementQuarterTurnsFromRotation(
                existingPipe,
                existingPipeRotation,
                out preferredQuarterTurns);
        }

        int baselineConnectionMask = existingPipe.GetConnectionMask(existingPipeRotation);
        TryGetPipeVariantAnchorFluidItemId(
            pipeCoordinate,
            previewToIgnore,
            out int anchorFluidItemId);
        int preferredFluidItemId = ResolvePreferredPipeVariantFluidItemId(
            pipeCoordinate,
            anchorFluidItemId,
            previewToIgnore);
        List<Vector2Int> requiredDirections = GetPipeNeighborConnectionDirections(
            pipePrototype,
            pipeCoordinate,
            previewToIgnore,
            false,
            preferredFluidItemId);
        RemoveIncompatibleRuntimePipeDirections(
            pipeCoordinate,
            preferredFluidItemId,
            previewToIgnore,
            requiredDirections,
            baselineConnectionMask);

        // A forced side connection extends the installed pipe; it must never bend
        // or discard the ports the player already placed. Preserve the complete
        // baseline shape before adding the new side so straight pipes resolve to a
        // tee (and tees to a cross) instead of becoming a detached straight/corner.
        AddPipeConnectionMaskDirections(requiredDirections, baselineConnectionMask);

        List<Vector2Int> fixedConnectorDirections = GetPipeVariantFixedConnectionDirections(
            pipeCoordinate,
            previewToIgnore);
        RemoveIncompatibleFixedFluidConnectorDirections(
            pipeCoordinate,
            preferredFluidItemId,
            previewToIgnore,
            fixedConnectorDirections);
        AddPipeDirections(requiredDirections, fixedConnectorDirections);
        for (int directionIndex = requiredDirections.Count - 1;
             directionIndex >= 0;
             directionIndex--)
        {
            if (PipeDirectionsContain(
                    forbiddenDirections,
                    requiredDirections[directionIndex]))
            {
                requiredDirections.RemoveAt(directionIndex);
            }
        }

        if (!TryResolveFluidSeparatedPipeVariant(
                pipeCoordinate,
                pipePrototype,
                requiredDirections,
                preferredQuarterTurns,
                previewToIgnore,
                baselineConnectionMask,
                true,
                forbiddenDirections,
                out resolvedPipe,
                out int resolvedQuarterTurns))
        {
            return false;
        }

        resolvedPipeRotation = GetPlacementObjectRotation(
            resolvedPipe,
            resolvedQuarterTurns);
        return true;
    }

    private bool TryCollectPipeNetworkFluidConstraints(
        Vector2Int startCoordinate,
        Pipe startPipe,
        Quaternion startPipeRotation,
        MapObject previewToIgnore,
        HashSet<int> compatibleFluidItemIds,
        ref bool hasFluidConstraint)
    {
        return TryCollectPipeNetworkFluidConstraints(
            startCoordinate,
            startPipe,
            startPipeRotation,
            previewToIgnore,
            compatibleFluidItemIds,
            ref hasFluidConstraint,
            false,
            Vector2Int.zero,
            Vector2Int.zero);
    }

    private bool TryCollectPipeNetworkFluidConstraintsExcludingConnection(
        Vector2Int startCoordinate,
        Pipe startPipe,
        Quaternion startPipeRotation,
        MapObject previewToIgnore,
        Vector2Int excludedConnectionCoordinate,
        Vector2Int excludedConnectionDirection,
        HashSet<int> compatibleFluidItemIds,
        ref bool hasFluidConstraint)
    {
        return TryCollectPipeNetworkFluidConstraints(
            startCoordinate,
            startPipe,
            startPipeRotation,
            previewToIgnore,
            compatibleFluidItemIds,
            ref hasFluidConstraint,
            excludedConnectionDirection != Vector2Int.zero,
            excludedConnectionCoordinate,
            excludedConnectionDirection);
    }

    private bool TryCollectPipeNetworkFluidConstraints(
        Vector2Int startCoordinate,
        Pipe startPipe,
        Quaternion startPipeRotation,
        MapObject previewToIgnore,
        HashSet<int> compatibleFluidItemIds,
        ref bool hasFluidConstraint,
        bool hasExcludedConnection,
        Vector2Int excludedConnectionCoordinate,
        Vector2Int excludedConnectionDirection)
    {
        if (startPipe == null)
        {
            return false;
        }

        pipeFluidCompatibilityQueue.Clear();
        pipeFluidCompatibilityVisited.Clear();
        pipeFluidCompatibilityQueue.Enqueue(startCoordinate);
        pipeFluidCompatibilityVisited.Add(startCoordinate);

        int searchedNodeCount = 0;
        while (pipeFluidCompatibilityQueue.Count > 0
               && searchedNodeCount < MaxPipeFluidCompatibilitySearchNodes)
        {
            Vector2Int pipeCoordinate = pipeFluidCompatibilityQueue.Dequeue();
            searchedNodeCount++;

            Pipe pipe = null;
            Quaternion pipeRotation = Quaternion.identity;
            if (pipeCoordinate == startCoordinate)
            {
                pipe = startPipe;
                pipeRotation = startPipeRotation;
            }
            else if (!TryGetPipePlacementAtCoordinate(
                         pipeCoordinate,
                         previewToIgnore,
                         out pipe,
                         out pipeRotation))
            {
                continue;
            }

            if (pipe == null)
            {
                continue;
            }

            if (!TryMergePipeAreaFluidConstraintsAtPipeCoordinate(
                    pipeCoordinate,
                    pipe,
                    pipeRotation,
                    previewToIgnore,
                    compatibleFluidItemIds,
                    ref hasFluidConstraint))
            {
                return false;
            }

            for (int i = 0; i < PipeCardinalDirections.Length; i++)
            {
                Vector2Int direction = PipeCardinalDirections[i];
                if (hasExcludedConnection
                    && PipeConnectionMatchesExcludedConnection(
                        pipeCoordinate,
                        direction,
                        excludedConnectionCoordinate,
                        excludedConnectionDirection))
                {
                    continue;
                }

                if (!HasEffectivePipeConnectionTowardsAt(
                        pipeCoordinate,
                        pipe,
                        pipeRotation,
                        direction))
                {
                    continue;
                }

                if (!TryCollectAdjacentPipeConnectionFluidConstraints(
                        pipeCoordinate,
                        direction,
                        previewToIgnore,
                        compatibleFluidItemIds,
                        ref hasFluidConstraint))
                {
                    return false;
                }

                Vector2Int neighborCoordinate = pipeCoordinate + direction;
                if (pipeFluidCompatibilityVisited.Contains(neighborCoordinate))
                {
                    continue;
                }

                if (TryGetPipePlacementAtCoordinate(
                        neighborCoordinate,
                        previewToIgnore,
                        out Pipe neighborPipe,
                        out Quaternion neighborPipeRotation)
                    && neighborPipe != null
                    && HasEffectivePipeConnectionTowardsAt(
                        neighborCoordinate,
                        neighborPipe,
                        neighborPipeRotation,
                        -direction))
                {
                    pipeFluidCompatibilityVisited.Add(neighborCoordinate);
                    pipeFluidCompatibilityQueue.Enqueue(neighborCoordinate);
                }
            }

            if (pipe.TryGetRemoteConnectionCoordinate(
                    pipeCoordinate,
                    out Vector2Int remoteCoordinate)
                && pipeFluidCompatibilityVisited.Add(remoteCoordinate))
            {
                pipeFluidCompatibilityQueue.Enqueue(remoteCoordinate);
            }
        }

        // A partially searched network has no trustworthy single-fluid identity.
        // Fail closed instead of allowing a distant, unchecked branch to mix.
        return pipeFluidCompatibilityQueue.Count <= 0;
    }

    private static bool PipeConnectionMatchesExcludedConnection(
        Vector2Int pipeCoordinate,
        Vector2Int direction,
        Vector2Int excludedCoordinate,
        Vector2Int excludedDirection)
    {
        if (direction == Vector2Int.zero || excludedDirection == Vector2Int.zero)
        {
            return false;
        }

        return (pipeCoordinate == excludedCoordinate && direction == excludedDirection)
               || (pipeCoordinate == excludedCoordinate + excludedDirection && direction == -excludedDirection);
    }

    private bool TryMergePipeAreaFluidConstraintsAtPipeCoordinate(
        Vector2Int pipeCoordinate,
        Pipe pipe,
        Quaternion pipeRotation,
        MapObject previewToIgnore,
        HashSet<int> compatibleFluidItemIds,
        ref bool hasFluidConstraint)
    {
        List<PipeAreaBlockCandidate> candidates = new List<PipeAreaBlockCandidate>(4);
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(pipeCoordinate, previewToIgnore, candidates);

        List<Vector2Int> candidateDirections = new List<Vector2Int>(4);
        HashSet<int> candidateFluidItemIds = new HashSet<int>();
        for (int i = 0; i < candidates.Count; i++)
        {
            PipeAreaBlockCandidate candidate = candidates[i];
            candidateDirections.Clear();
            if (!TryGetPipeAreaCandidateConnectionDirections(pipeCoordinate, candidate, candidateDirections)
                || !HasEffectivePipeConnectionTowardsAnyDirection(
                    pipeCoordinate,
                    pipe,
                    pipeRotation,
                    candidateDirections))
            {
                continue;
            }

            candidateFluidItemIds.Clear();
            PipeAreaFluidResolution candidateFluidResolution = ResolvePipeAreaCandidateFluidItemIds(
                pipeCoordinate,
                candidate,
                candidateFluidItemIds);
            if (candidateFluidResolution == PipeAreaFluidResolution.UnresolvedFluidEndpoint
                || candidateFluidResolution == PipeAreaFluidResolution.Resolved
                && !TryMergeFluidCompatibilityConstraint(
                    compatibleFluidItemIds,
                    ref hasFluidConstraint,
                    candidateFluidItemIds))
            {
                return false;
            }
        }

        return true;
    }

    private bool TryCollectAdjacentPipeConnectionFluidConstraints(
        Vector2Int pipeCoordinate,
        Vector2Int direction,
        MapObject previewToIgnore,
        HashSet<int> compatibleFluidItemIds,
        ref bool hasFluidConstraint)
    {
        if (direction == Vector2Int.zero)
        {
            return true;
        }

        Vector2Int neighborCoordinate = pipeCoordinate + direction;
        Vector2Int directionToPipe = -direction;

        if (!TryMergeRuntimeAdjacentFluidStorageConstraint(
                neighborCoordinate,
                directionToPipe,
                compatibleFluidItemIds,
                ref hasFluidConstraint)
            || !TryMergeAdjacentFluidStorageSnapshotConstraint(
                neighborCoordinate,
                directionToPipe,
                previewToIgnore,
                compatibleFluidItemIds,
                ref hasFluidConstraint))
        {
            return false;
        }

        HashSet<int> connectorFluidItemIds = new HashSet<int>();
        bool hasConnectorFluidConstraint = false;
        if (!TryCollectAdjacentPipeAreaFluidConstraints(
                neighborCoordinate,
                directionToPipe,
                previewToIgnore,
                connectorFluidItemIds,
                ref hasConnectorFluidConstraint))
        {
            return false;
        }

        if (hasConnectorFluidConstraint
            && !TryMergeFluidCompatibilityConstraint(
                compatibleFluidItemIds,
                ref hasFluidConstraint,
                connectorFluidItemIds))
        {
            return false;
        }

        if (!TryGetPipePlacementAtCoordinate(
                neighborCoordinate,
                previewToIgnore,
                out Pipe neighborPipe,
                out Quaternion neighborPipeRotation)
            || !HasEffectivePipeConnectionTowardsAt(
                neighborCoordinate,
                neighborPipe,
                neighborPipeRotation,
                directionToPipe))
        {
            return true;
        }

        HashSet<int> neighborPipeAreaFluidItemIds = new HashSet<int>();
        bool hasNeighborPipeAreaFluidConstraint = false;
        if (!TryMergePipeAreaFluidConstraintsAtPipeCoordinate(
                neighborCoordinate,
                neighborPipe,
                neighborPipeRotation,
                previewToIgnore,
                neighborPipeAreaFluidItemIds,
                ref hasNeighborPipeAreaFluidConstraint))
        {
            return false;
        }

        return !hasNeighborPipeAreaFluidConstraint
               || TryMergeFluidCompatibilityConstraint(
                   compatibleFluidItemIds,
                   ref hasFluidConstraint,
                   neighborPipeAreaFluidItemIds);
    }

    private bool TryMergeRuntimeAdjacentFluidStorageConstraint(
        Vector2Int storageCoordinate,
        Vector2Int directionToPipe,
        HashSet<int> compatibleFluidItemIds,
        ref bool hasFluidConstraint)
    {
        if (directionToPipe == Vector2Int.zero)
        {
            return true;
        }

        pipeFluidEndpointInstallationsScratch.Clear();
        InstallationObject.CollectActiveInstallationsAtRuntimeGridCoordinate(
            storageCoordinate,
            pipeFluidEndpointInstallationsScratch);

        for (int i = 0; i < pipeFluidEndpointInstallationsScratch.Count; i++)
        {
            InstallationObject storage = pipeFluidEndpointInstallationsScratch[i];
            if (storage == null
                || storage is Pipe
                || !storage.gameObject.activeInHierarchy
                || storage.StoredFluidItemId < 0
                || !InputOutputModule.IsFluidItemId(storage.StoredFluidItemId))
            {
                continue;
            }

            bool exposesFluidAtCoordinate;
            if (storage is InputOutputModule module)
            {
                pipeFluidEndpointExposureItemIdsScratch.Clear();
                exposesFluidAtCoordinate = module.TryGetPlacementRuntime(
                                               out Vector2Int moduleAnchorCoordinate,
                                               out int moduleQuarterTurns)
                                           && TryResolveFixedFluidConnectorCompatibility(
                                               module,
                                               module.transform.rotation,
                                               moduleAnchorCoordinate,
                                               moduleQuarterTurns,
                                               storageCoordinate,
                                               directionToPipe,
                                               out bool moduleConnectorCanConnect)
                                           && moduleConnectorCanConnect
                                           && module.CanExposeStoredFluidAtRuntimePipeCoordinate(
                                               storageCoordinate,
                                               storage.StoredFluidItemId,
                                               pipeFluidEndpointExposureItemIdsScratch);
            }
            else
            {
                exposesFluidAtCoordinate = storage.TryGetPlacementRuntime(
                                               out Vector2Int storageAnchorCoordinate,
                                               out int storageQuarterTurns)
                                           && TryResolveFixedFluidConnectorCompatibility(
                                               storage,
                                               storage.transform.rotation,
                                               storageAnchorCoordinate,
                                               storageQuarterTurns,
                                               storageCoordinate,
                                               directionToPipe,
                                               out bool connectorCanConnect)
                                           && connectorCanConnect;
            }

            if (!exposesFluidAtCoordinate)
            {
                continue;
            }

            pipeFluidEndpointItemIdsScratch.Clear();
            pipeFluidEndpointItemIdsScratch.Add(storage.StoredFluidItemId);
            if (!TryMergeFluidCompatibilityConstraint(
                    compatibleFluidItemIds,
                    ref hasFluidConstraint,
                    pipeFluidEndpointItemIdsScratch))
            {
                pipeFluidEndpointInstallationsScratch.Clear();
                pipeFluidEndpointItemIdsScratch.Clear();
                pipeFluidEndpointExposureItemIdsScratch.Clear();
                return false;
            }
        }

        pipeFluidEndpointInstallationsScratch.Clear();
        pipeFluidEndpointItemIdsScratch.Clear();
        pipeFluidEndpointExposureItemIdsScratch.Clear();
        return true;
    }

    private bool TryMergeAdjacentFluidStorageSnapshotConstraint(
        Vector2Int storageCoordinate,
        Vector2Int directionToPipe,
        MapObject previewToIgnore,
        HashSet<int> compatibleFluidItemIds,
        ref bool hasFluidConstraint)
    {
        if (directionToPipe == Vector2Int.zero)
        {
            return true;
        }

        PlacementSnapshot storageSnapshot;
        if (!TryGetPreviewPlacementSnapshot(
                storageCoordinate,
                previewToIgnore,
                out storageSnapshot)
            && !TryGetInstalledPlacementSnapshot(storageCoordinate, out storageSnapshot)
            && !TryGetSavedPlacementSnapshot(storageCoordinate, out storageSnapshot))
        {
            return true;
        }

        if (storageSnapshot?.mapObject is not InstallationObject storage
            || storage is Pipe
            || storage is InputOutputModule
            || storageSnapshot.storedFluidItemId < 0
            || !InputOutputModule.IsFluidItemId(storageSnapshot.storedFluidItemId)
            || !TryResolveFixedFluidConnectorCompatibility(
                storageSnapshot,
                storageCoordinate,
                directionToPipe,
                out bool connectorCanConnect)
            || !connectorCanConnect)
        {
            return true;
        }

        pipeFluidEndpointItemIdsScratch.Clear();
        pipeFluidEndpointItemIdsScratch.Add(storageSnapshot.storedFluidItemId);
        bool compatible = TryMergeFluidCompatibilityConstraint(
            compatibleFluidItemIds,
            ref hasFluidConstraint,
            pipeFluidEndpointItemIdsScratch);
        pipeFluidEndpointItemIdsScratch.Clear();
        return compatible;
    }

    private bool TryCollectAdjacentPipeAreaFluidConstraints(
        Vector2Int connectorCoordinate,
        Vector2Int directionToPipe,
        MapObject previewToIgnore,
        HashSet<int> compatibleFluidItemIds,
        ref bool hasFluidConstraint)
    {
        List<PipeAreaBlockCandidate> candidates = new List<PipeAreaBlockCandidate>(4);
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(connectorCoordinate, previewToIgnore, candidates);

        HashSet<int> candidateFluidItemIds = new HashSet<int>();
        for (int i = 0; i < candidates.Count; i++)
        {
            PipeAreaBlockCandidate candidate = candidates[i];
            if (candidate.snapshot == null
                || !TryResolveFixedFluidConnectorCompatibility(
                    candidate.snapshot,
                    connectorCoordinate,
                    directionToPipe,
                    out bool connectorCanConnect)
                || !connectorCanConnect)
            {
                continue;
            }

            candidateFluidItemIds.Clear();
            PipeAreaFluidResolution candidateFluidResolution = ResolvePipeAreaCandidateFluidItemIds(
                connectorCoordinate,
                candidate,
                candidateFluidItemIds);
            if (candidateFluidResolution == PipeAreaFluidResolution.UnresolvedFluidEndpoint
                || candidateFluidResolution == PipeAreaFluidResolution.Resolved
                && !TryMergeFluidCompatibilityConstraint(
                    compatibleFluidItemIds,
                    ref hasFluidConstraint,
                    candidateFluidItemIds))
            {
                return false;
            }
        }

        return true;
    }

    private bool TryGetPipeAreaCandidateConnectionDirections(
        Vector2Int coordinate,
        PipeAreaBlockCandidate candidate,
        List<Vector2Int> directions)
    {
        if (candidate.snapshot == null
            || candidate.snapshot.mapObject == null
            || directions == null)
        {
            return false;
        }

        int beforeCount = directions.Count;
        TryAppendFixedFluidPipeConnectionDirections(
            candidate.snapshot,
            coordinate,
            directions);
        return directions.Count > beforeCount;
    }

    private PipeAreaFluidResolution ResolvePipeAreaCandidateFluidItemIds(
        Vector2Int coordinate,
        PipeAreaBlockCandidate candidate,
        ISet<int> fluidItemIds)
    {
        if (fluidItemIds == null || candidate.snapshot == null)
        {
            return PipeAreaFluidResolution.UnresolvedFluidEndpoint;
        }

        // An installed storage's current contents are stricter than its configured
        // input/output list. For example, a generic tank containing water must not
        // allow its pipe network to merge with an oil network merely because the
        // tank definition supports both fluids.
        if (candidate.snapshot.mapObject is InstallationObject installationObject
            && installationObject is not InputOutputModule)
        {
            int storedFluidItemId = candidate.snapshot.storedFluidItemId >= 0
                ? candidate.snapshot.storedFluidItemId
                : installationObject.StoredFluidItemId;
            if (storedFluidItemId >= 0 && InputOutputModule.IsFluidItemId(storedFluidItemId))
            {
                fluidItemIds.Add(storedFluidItemId);
                return PipeAreaFluidResolution.Resolved;
            }

            if (storedFluidItemId >= 0)
            {
                return PipeAreaFluidResolution.UnresolvedFluidEndpoint;
            }
        }

        HashSet<int> candidateItemIds = new HashSet<int>();
        bool foundAny = false;
        if (InputOutputModule.IsOutputBlockType(candidate.blockType))
        {
            foundAny = candidate.snapshot.mapObject is InputOutputModule runtimeModule
                       && runtimeModule.TryGetRuntimeOutputItemIdsAtCoordinate(
                           coordinate,
                           candidateItemIds);
            if (!foundAny)
            {
                foundAny = TryGetCandidateOutputItemIds(
                    candidate.snapshot.anchorCoordinate,
                    candidate.snapshot.mapObject,
                    candidate.snapshot.quarterTurns,
                    candidateItemIds);
            }
        }
        else if (InputOutputModule.IsInputItemBlockType(candidate.blockType))
        {
            foundAny = TryGetCandidateInputItemIdsAtCoordinate(
                candidate.snapshot.anchorCoordinate,
                candidate.snapshot.mapObject,
                candidate.snapshot.quarterTurns,
                coordinate,
                candidateItemIds);
        }
        else if (IsPipePassBlockType(candidate.blockType))
        {
            foundAny = TryGetCandidatePipePassItemIds(candidate, candidateItemIds);
        }

        if (!foundAny)
        {
            return PipeAreaCandidateRequiresResolvedFluidIdentity(candidate)
                ? PipeAreaFluidResolution.UnresolvedFluidEndpoint
                : PipeAreaFluidResolution.NoFluidConstraint;
        }

        bool foundFluid = false;
        foreach (int itemId in candidateItemIds)
        {
            if (!InputOutputModule.IsFluidItemId(itemId))
            {
                continue;
            }

            fluidItemIds.Add(itemId);
            foundFluid = true;
        }

        if (foundFluid)
        {
            return PipeAreaFluidResolution.Resolved;
        }

        return PipeAreaCandidateRequiresResolvedFluidIdentity(candidate)
            ? PipeAreaFluidResolution.UnresolvedFluidEndpoint
            : PipeAreaFluidResolution.NoFluidConstraint;
    }

    private static bool PipeAreaCandidateRequiresResolvedFluidIdentity(
        PipeAreaBlockCandidate candidate)
    {
        MapObject mapObject = candidate.snapshot != null
            ? candidate.snapshot.mapObject
            : null;
        return mapObject is Pump
               || mapObject is OilDrillingMachine
               || mapObject is Boiler
               || mapObject is SteamGenerator;
    }

    private bool PipeAreaCandidateFluidMatchesPipeNetwork(
        Vector2Int pipeCoordinate,
        Pipe pipe,
        Quaternion pipeRotation,
        Vector2Int pipeAreaCoordinate,
        PipeAreaBlockCandidate pipeAreaCandidate,
        MapObject previewToIgnore)
    {
        if (pipe == null)
        {
            return true;
        }

        List<Vector2Int> candidateDirections = new List<Vector2Int>(4);
        if (!TryGetPipeAreaCandidateConnectionDirections(
                pipeAreaCoordinate,
                pipeAreaCandidate,
                candidateDirections)
            || !PipeAreaCandidateConnectsPipe(
                pipeCoordinate,
                pipe,
                pipeRotation,
                pipeAreaCoordinate,
                candidateDirections))
        {
            return false;
        }

        HashSet<int> compatibleFluidItemIds = new HashSet<int>();
        bool hasFluidConstraint = false;
        HashSet<int> candidateFluidItemIds = new HashSet<int>();
        PipeAreaFluidResolution candidateFluidResolution = ResolvePipeAreaCandidateFluidItemIds(
            pipeAreaCoordinate,
            pipeAreaCandidate,
            candidateFluidItemIds);
        if (candidateFluidResolution == PipeAreaFluidResolution.UnresolvedFluidEndpoint
            || candidateFluidResolution == PipeAreaFluidResolution.Resolved
            && !TryMergeFluidCompatibilityConstraint(
                compatibleFluidItemIds,
                ref hasFluidConstraint,
                candidateFluidItemIds))
        {
            return false;
        }

        HashSet<int> pipeAreaFluidItemIds = new HashSet<int>();
        bool hasPipeAreaFluidConstraint = false;
        if (!TryCollectPipeNetworkFluidConstraints(
                pipeCoordinate,
                pipe,
                pipeRotation,
                previewToIgnore,
                pipeAreaFluidItemIds,
                ref hasPipeAreaFluidConstraint))
        {
            return false;
        }

        return !hasPipeAreaFluidConstraint
               || TryMergeFluidCompatibilityConstraint(
                   compatibleFluidItemIds,
                   ref hasFluidConstraint,
                   pipeAreaFluidItemIds);
    }

    private bool PipeAreaCandidateConnectsPipe(
        Vector2Int pipeCoordinate,
        Pipe pipe,
        Quaternion pipeRotation,
        Vector2Int pipeAreaCoordinate,
        IReadOnlyList<Vector2Int> candidateDirections)
    {
        if (pipe == null)
        {
            return true;
        }

        if (pipeCoordinate == pipeAreaCoordinate)
        {
            return HasEffectivePipeConnectionTowardsAnyDirection(
                pipeCoordinate,
                pipe,
                pipeRotation,
                candidateDirections);
        }

        Vector2Int directionFromPipeToArea = pipeAreaCoordinate - pipeCoordinate;
        if (!IsCardinalPipeDirection(directionFromPipeToArea))
        {
            return false;
        }

        return PipeDirectionsContain(candidateDirections, directionFromPipeToArea)
               && HasEffectivePipeConnectionTowardsAt(
                   pipeCoordinate,
                   pipe,
                   pipeRotation,
                   directionFromPipeToArea);
    }

    private static bool TryMergeFluidCompatibilityConstraint(
        HashSet<int> compatibleFluidItemIds,
        ref bool hasFluidConstraint,
        ISet<int> candidateFluidItemIds)
    {
        if (candidateFluidItemIds == null || candidateFluidItemIds.Count <= 0)
        {
            return true;
        }

        if (compatibleFluidItemIds == null)
        {
            return false;
        }

        if (!hasFluidConstraint)
        {
            compatibleFluidItemIds.Clear();
            foreach (int itemId in candidateFluidItemIds)
            {
                if (itemId >= 0)
                {
                    compatibleFluidItemIds.Add(itemId);
                }
            }

            hasFluidConstraint = compatibleFluidItemIds.Count > 0;
            return true;
        }

        bool hasSharedItemId = false;
        foreach (int itemId in candidateFluidItemIds)
        {
            if (itemId >= 0 && compatibleFluidItemIds.Contains(itemId))
            {
                hasSharedItemId = true;
                break;
            }
        }

        if (!hasSharedItemId)
        {
            return false;
        }

        List<int> itemIdsToRemove = new List<int>();
        foreach (int itemId in compatibleFluidItemIds)
        {
            if (!candidateFluidItemIds.Contains(itemId))
            {
                itemIdsToRemove.Add(itemId);
            }
        }

        for (int i = 0; i < itemIdsToRemove.Count; i++)
        {
            compatibleFluidItemIds.Remove(itemIdsToRemove[i]);
        }

        return compatibleFluidItemIds.Count > 0;
    }

    private List<Vector2Int> GetFixedFluidConnectorNeighborConnectionDirections(Vector2Int anchorCoordinate)
    {
        List<Vector2Int> directions = new List<Vector2Int>(4);

        for (int i = 0; i < PipeCardinalDirections.Length; i++)
        {
            Vector2Int sideDirection = PipeCardinalDirections[i];
            if (TryGetFixedFluidConnectorCompatibilityAtCoordinate(
                    anchorCoordinate + sideDirection,
                    -sideDirection,
                    out bool connectorCanConnect)
                && CanPipeAreaBlocksConnect(anchorCoordinate, anchorCoordinate + sideDirection)
                && connectorCanConnect)
            {
                AddPipeDirection(directions, sideDirection);
            }
        }

        return directions;
    }

    private bool TryGetPipeVariantAnchorFluidItemId(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out int fluidItemId)
    {
        fluidItemId = -1;
        // A source/storage connector sharing this cell owns the pipe's fluid.
        // Resolve it before the pipe network, whose first-found fluid can be stale
        // while an invalid mixed junction is being repaired.
        if (TryGetPipeEndpointFluidItemIdAtCoordinate(
                coordinate,
                previewToIgnore,
                out fluidItemId))
        {
            return true;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain != null
            && terrain.TryGetLoadedBlock(coordinate, out Block block)
            && block != null
            && block.MapObject is Pipe installedPipe
            && installedPipe.gameObject.activeInHierarchy
            && installedPipe.TryGetObjectInfoFluidItemId(out fluidItemId)
            && fluidItemId >= 0)
        {
            return true;
        }

        return false;
    }

    private int ResolvePreferredPipeVariantFluidItemId(
        Vector2Int anchorCoordinate,
        int anchorFluidItemId,
        MapObject previewToIgnore)
    {
        // Same-cell machine/storage fluid is a hard constraint. Neighbour counts
        // may choose between pipe branches, but must never override the connector
        // that the pipe is directly attached to.
        if (TryGetPipeEndpointFluidItemIdAtCoordinate(
                anchorCoordinate,
                previewToIgnore,
                out int fixedConnectorFluidItemId))
        {
            return fixedConnectorFluidItemId;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return anchorFluidItemId;
        }

        for (int directionIndex = 0; directionIndex < PipeCardinalDirections.Length; directionIndex++)
        {
            adjacentPipeFluidItemIdsScratch[directionIndex] = -1;
            adjacentPipePlacementSequencesScratch[directionIndex] = long.MinValue;
            adjacentPipeIsPreviewScratch[directionIndex] = false;
            Vector2Int neighborCoordinate = anchorCoordinate + PipeCardinalDirections[directionIndex];
            if (!TryGetPipePlacementAtCoordinate(
                    neighborCoordinate,
                    previewToIgnore,
                    out Pipe neighborPipe,
                    out Quaternion neighborRotation)
                || neighborPipe == null
                || !TryGetAdjacentPipeBranchFluidItemId(
                    anchorCoordinate,
                    neighborCoordinate,
                    neighborPipe,
                    neighborRotation,
                    previewToIgnore,
                    out int neighborFluidItemId))
            {
                continue;
            }

            adjacentPipeFluidItemIdsScratch[directionIndex] = neighborFluidItemId;
            adjacentPipePlacementSequencesScratch[directionIndex] = ResolvePipePlacementSequenceAtCoordinate(
                neighborCoordinate,
                neighborPipe,
                previewToIgnore,
                out adjacentPipeIsPreviewScratch[directionIndex]);
        }

        bool hasPreviewFluidConstraint = false;
        for (int directionIndex = 0; directionIndex < PipeCardinalDirections.Length; directionIndex++)
        {
            if (adjacentPipeFluidItemIdsScratch[directionIndex] >= 0
                && adjacentPipeIsPreviewScratch[directionIndex])
            {
                hasPreviewFluidConstraint = true;
                break;
            }
        }
        bool currentPlacementIsPipePreview = previewToIgnore is Pipe
                                             && TryGetPreviewAnchorCoordinate(
                                                 previewToIgnore,
                                                 out Vector2Int currentPreviewAnchorCoordinate)
                                             && currentPreviewAnchorCoordinate == anchorCoordinate;
        bool prioritizePreviewFluid = hasPreviewFluidConstraint && currentPlacementIsPipePreview;

        int preferredFluidItemId = -1;
        int preferredPreviewDirectionCount = -1;
        int preferredFluidDirectionCount = 0;
        long preferredFluidPlacementSequence = long.MinValue;
        for (int directionIndex = 0; directionIndex < PipeCardinalDirections.Length; directionIndex++)
        {
            int candidateFluidItemId = adjacentPipeFluidItemIdsScratch[directionIndex];
            if (candidateFluidItemId < 0)
            {
                continue;
            }

            int candidatePreviewDirectionCount = 0;
            int candidateDirectionCount = 0;
            long candidatePlacementSequence = long.MinValue;
            for (int candidateIndex = 0; candidateIndex < PipeCardinalDirections.Length; candidateIndex++)
            {
                if (adjacentPipeFluidItemIdsScratch[candidateIndex] != candidateFluidItemId)
                {
                    continue;
                }

                candidateDirectionCount++;
                if (adjacentPipeIsPreviewScratch[candidateIndex])
                {
                    candidatePreviewDirectionCount++;
                }
                candidatePlacementSequence = System.Math.Max(
                    candidatePlacementSequence,
                    adjacentPipePlacementSequencesScratch[candidateIndex]);
            }

            if (prioritizePreviewFluid && candidatePreviewDirectionCount <= 0)
            {
                continue;
            }

            int candidatePreviewPriority = prioritizePreviewFluid
                ? candidatePreviewDirectionCount
                : 0;

            if (candidatePreviewPriority > preferredPreviewDirectionCount
                || candidatePreviewPriority == preferredPreviewDirectionCount
                && candidateDirectionCount > preferredFluidDirectionCount
                || candidatePreviewPriority == preferredPreviewDirectionCount
                && candidateDirectionCount == preferredFluidDirectionCount
                && candidatePlacementSequence > preferredFluidPlacementSequence)
            {
                preferredFluidItemId = candidateFluidItemId;
                preferredPreviewDirectionCount = candidatePreviewPriority;
                preferredFluidDirectionCount = candidateDirectionCount;
                preferredFluidPlacementSequence = candidatePlacementSequence;
            }
        }

        if (preferredFluidItemId < 0)
        {
            return anchorFluidItemId;
        }

        if (anchorFluidItemId < 0)
        {
            return preferredFluidItemId;
        }

        // The pipe currently being drawn owns its junction. It must keep the new
        // line's fluid and bend away from an older, different-fluid line rather
        // than being absorbed into that line because it has more neighbours.
        if (prioritizePreviewFluid)
        {
            return preferredFluidItemId;
        }

        int anchorFluidDirectionCount = 0;
        for (int directionIndex = 0; directionIndex < PipeCardinalDirections.Length; directionIndex++)
        {
            if (adjacentPipeFluidItemIdsScratch[directionIndex] == anchorFluidItemId)
            {
                anchorFluidDirectionCount++;
            }
        }

        // A previously resolved cross may already expose one of the mixed fluids at the
        // anchor. Do not let that stale value preserve a four-way connection: when the
        // neighboring branches have a strict majority (3:1, for example), that majority
        // owns the junction and the different-fluid side must be excluded to form a tee.
        // A tie must keep the anchor's established fluid; otherwise a newer foreign pipe
        // can steal the junction before unfilled compatible branches receive that fluid.
        return preferredFluidDirectionCount > anchorFluidDirectionCount
            ? preferredFluidItemId
            : anchorFluidItemId;
    }

    private bool TryGetManualPipeConnectionMask(
        Vector2Int anchorCoordinate,
        MapObject previewToIgnore,
        out int connectionMask)
    {
        connectionMask = 0;
        // A rotation selection is part of the authoritative blueprint snapshot.
        // Virtual installed-neighbour resolution must read it as well; suppressing
        // it here immediately overwrites the button result with automatic topology.
        if (previewToIgnore != null
            && TryGetPreviewAnchorCoordinate(previewToIgnore, out Vector2Int ignoredPreviewCoordinate)
            && ignoredPreviewCoordinate == anchorCoordinate
            && installPreviewPipeConnectionMasksByPreview.TryGetValue(
                previewToIgnore,
                out connectionMask)
            && HasValidManualPipeConnectionMask(connectionMask))
        {
            return true;
        }

        return TryGetInstallPreviewAtCoordinate(anchorCoordinate, out MapObject preview)
               && preview != null
               && installPreviewPipeConnectionMasksByPreview.TryGetValue(
                   preview,
                   out connectionMask)
               && HasValidManualPipeConnectionMask(connectionMask);
    }

    private bool TryGetManualPipeConnectionMask(
        Pipe previewPipe,
        Vector2Int coordinate,
        out int connectionMask)
    {
        connectionMask = 0;
        return previewPipe != null
               && installPreviewPipeConnectionMasksByPreview.TryGetValue(
                   previewPipe,
                   out connectionMask)
               && HasValidManualPipeConnectionMask(connectionMask)
               && TryGetPreviewAnchorCoordinate(previewPipe, out Vector2Int anchorCoordinate)
               && anchorCoordinate == coordinate;
    }

    private bool HasEffectivePipeConnectionTowardsAt(
        Vector2Int coordinate,
        Pipe pipe,
        Quaternion pipeRotation,
        Vector2Int direction)
    {
        if (pipe == null || direction == Vector2Int.zero)
        {
            return false;
        }

        return TryGetManualPipeConnectionMask(
                pipe,
                coordinate,
                out int selectedConnectionMask)
            ? PipeConnectionMaskContainsDirection(selectedConnectionMask, direction)
            : pipe.HasConnectionTowardsAt(
                coordinate,
                pipeRotation,
                direction);
    }

    private bool HasEffectivePipeConnectionTowardsAnyDirection(
        Vector2Int coordinate,
        Pipe pipe,
        Quaternion pipeRotation,
        IReadOnlyList<Vector2Int> directions)
    {
        if (directions == null)
        {
            return false;
        }

        for (int i = 0; i < directions.Count; i++)
        {
            if (HasEffectivePipeConnectionTowardsAt(
                    coordinate,
                    pipe,
                    pipeRotation,
                    directions[i]))
            {
                return true;
            }
        }

        return false;
    }

    private long ResolvePipePlacementSequenceAtCoordinate(
        Vector2Int coordinate,
        Pipe pipe,
        MapObject previewToIgnore,
        out bool isPreview)
    {
        isPreview = false;
        if (TryGetInstallPreviewAtCoordinate(coordinate, out MapObject preview)
            && preview != null
            && preview != previewToIgnore)
        {
            MapObject previewSource = ResolveInstallPreviewFootprintSource(preview) ?? preview;
            Pipe previewPipe = preview as Pipe ?? previewSource as Pipe;
            if (previewPipe == pipe)
            {
                isPreview = true;
                return installPreviewPlacementSequencesByPreview.TryGetValue(
                    preview,
                    out long previewSequence)
                    ? previewSequence
                    : long.MaxValue;
            }
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain != null
            && terrain.TryGetLoadedBlock(coordinate, out Block block)
            && block != null
            && block.MapObject is Pipe installedPipe
            && installedPipe.gameObject.activeInHierarchy)
        {
            return installedPipe.RuntimePlacementSequence;
        }

        if (terrain != null
            && terrain.TryGetSavedPipeInstallationStateAtCoordinate(
                coordinate,
                out BlockStateStore.InstallationSaveState savedState)
            && savedState != null)
        {
            return savedState.placementSequence;
        }

        return pipe != null ? pipe.RuntimePlacementSequence : long.MinValue;
    }

    private void RemoveIncompatibleRuntimePipeDirections(
        Vector2Int anchorCoordinate,
        int preferredFluidItemId,
        MapObject previewToIgnore,
        List<Vector2Int> directions,
        int baselineConnectionMask = 0)
    {
        if (preferredFluidItemId < 0 || directions == null || directions.Count <= 0)
        {
            return;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return;
        }

        for (int directionIndex = directions.Count - 1; directionIndex >= 0; directionIndex--)
        {
            Vector2Int direction = directions[directionIndex];
            Vector2Int neighborCoordinate = anchorCoordinate + direction;
            if (TryGetPipePlacementAtCoordinate(
                    neighborCoordinate,
                    previewToIgnore,
                    out Pipe neighborPipe,
                    out Quaternion neighborRotation)
                && neighborPipe != null)
            {
                adjacentPipeBranchFluidItemIdsScratch.Clear();
                bool hasNeighborFluidConstraint = false;
                bool collectedNeighborFluidConstraints =
                    TryCollectPipeNetworkFluidConstraintsExcludingConnection(
                    neighborCoordinate,
                    neighborPipe,
                    neighborRotation,
                    previewToIgnore,
                    neighborCoordinate,
                    anchorCoordinate - neighborCoordinate,
                    adjacentPipeBranchFluidItemIdsScratch,
                    ref hasNeighborFluidConstraint);

                if (!collectedNeighborFluidConstraints
                    || hasNeighborFluidConstraint
                    && !adjacentPipeBranchFluidItemIdsScratch.Contains(preferredFluidItemId))
                {
                    directions.RemoveAt(directionIndex);
                }
            }
        }

        adjacentPipeBranchFluidItemIdsScratch.Clear();
    }

    private static bool PipeConnectionMaskContainsDirection(
        int connectionMask,
        Vector2Int direction)
    {
        if (connectionMask < 0 || direction == Vector2Int.zero)
        {
            return false;
        }

        for (int directionIndex = 0;
             directionIndex < PipeCardinalDirections.Length;
             directionIndex++)
        {
            if (PipeCardinalDirections[directionIndex] == direction)
            {
                return (connectionMask & (1 << directionIndex)) != 0;
            }
        }

        return false;
    }

    private static int GetPipeConnectionDirectionBit(Vector2Int direction)
    {
        for (int directionIndex = 0;
             directionIndex < PipeCardinalDirections.Length;
             directionIndex++)
        {
            if (PipeCardinalDirections[directionIndex] == direction)
            {
                return 1 << directionIndex;
            }
        }

        return 0;
    }

    private static bool HasValidManualPipeConnectionMask(int connectionMask)
    {
        int cardinalMask = connectionMask & 0xF;
        return cardinalMask != 0
               && (cardinalMask & (cardinalMask - 1)) != 0;
    }

    private static void AddPipeConnectionMaskDirections(
        List<Vector2Int> directions,
        int connectionMask)
    {
        if (directions == null || connectionMask <= 0)
        {
            return;
        }

        for (int directionIndex = 0;
             directionIndex < PipeCardinalDirections.Length;
             directionIndex++)
        {
            Vector2Int direction = PipeCardinalDirections[directionIndex];
            if (PipeConnectionMaskContainsDirection(connectionMask, direction))
            {
                AddPipeDirection(directions, direction);
            }
        }
    }

    private bool TryAlignPipeVariantToExposedNeighborConnections(
        Vector2Int anchorCoordinate,
        Pipe currentPipe,
        Quaternion currentRotation,
        MapObject previewToIgnore,
        out Pipe alignedPipe,
        out Quaternion alignedRotation)
    {
        alignedPipe = currentPipe;
        alignedRotation = currentRotation;
        if (currentPipe == null || currentPipe is UndergroundPipe)
        {
            return false;
        }

        bool changed = false;
        // Potential connections are useful while choosing a junction, but the final
        // resolved pair must be symmetrical. If an adjacent pipe already exposes a
        // real port towards this coordinate, make this side face it as well instead
        // of leaving a visually open but disconnected branch.
        for (int pass = 0; pass < PipeCardinalDirections.Length; pass++)
        {
            bool changedThisPass = false;
            for (int directionIndex = 0;
                 directionIndex < PipeCardinalDirections.Length;
                 directionIndex++)
            {
                Vector2Int direction = PipeCardinalDirections[directionIndex];
                if (alignedPipe.HasConnectionTowardsAt(
                        anchorCoordinate,
                        alignedRotation,
                        direction))
                {
                    continue;
                }

                Vector2Int neighborCoordinate = anchorCoordinate + direction;
                if (!TryGetPipePlacementAtCoordinate(
                        neighborCoordinate,
                        previewToIgnore,
                        out Pipe neighborPipe,
                        out Quaternion neighborRotation)
                    || neighborPipe == null)
                {
                    continue;
                }

                Pipe neighborPipeToEvaluate = neighborPipe;
                Quaternion neighborRotationToEvaluate = neighborRotation;
                if (TryGetInstalledPipeVariantPreview(
                        neighborPipe,
                        out Pipe neighborVariantPreview,
                        out Quaternion neighborVariantPreviewRotation))
                {
                    neighborPipeToEvaluate = neighborVariantPreview;
                    neighborRotationToEvaluate = neighborVariantPreviewRotation;
                }

                if (!HasEffectivePipeConnectionTowardsAt(
                        neighborCoordinate,
                        neighborPipeToEvaluate,
                        neighborRotationToEvaluate,
                        -direction)
                    || !TryResolvePipeVariantForForcedConnection(
                        anchorCoordinate,
                        alignedPipe,
                        alignedRotation,
                        direction,
                        out Pipe forcedPipe,
                        out Quaternion forcedRotation,
                        previewToIgnore)
                    || forcedPipe == null
                    || !forcedPipe.HasConnectionTowardsAt(
                        anchorCoordinate,
                        forcedRotation,
                        direction))
                {
                    continue;
                }

                bool sameVariant = alignedPipe.VariantKind == forcedPipe.VariantKind;
                bool sameRotation = Mathf.Abs(Quaternion.Dot(alignedRotation, forcedRotation)) >= 0.9999f;
                if (sameVariant && sameRotation)
                {
                    continue;
                }

                alignedPipe = forcedPipe;
                alignedRotation = forcedRotation;
                changed = true;
                changedThisPass = true;
            }

            if (!changedThisPass)
            {
                break;
            }
        }

        return changed;
    }

    // Preview and committed topology share this order-independent entry point.
    private bool TryResolvePipePlacementVariantWithCompatibleAdjacency(
        Pipe pipePrototype,
        Vector2Int anchorCoordinate,
        int preferredQuarterTurns,
        MapObject previewToIgnore,
        int baselineConnectionMask,
        out MapObject resolvedPrefab,
        out int resolvedQuarterTurns)
    {
        if (!TryResolvePipePlacementVariant(
                pipePrototype,
                anchorCoordinate,
                preferredQuarterTurns,
                previewToIgnore,
                out resolvedPrefab,
                out resolvedQuarterTurns,
                baselineConnectionMask,
                true))
        {
            return false;
        }

        if (!(resolvedPrefab is Pipe resolvedPipe))
        {
            return resolvedPrefab != null;
        }

        Quaternion resolvedRotation = GetPlacementObjectRotation(
            resolvedPipe,
            resolvedQuarterTurns);
        bool hasManualConnectionMask = TryGetManualPipeConnectionMask(
            anchorCoordinate,
            previewToIgnore,
            out _);
        if (!hasManualConnectionMask
            && TryAlignPipeVariantToExposedNeighborConnections(
                anchorCoordinate,
                resolvedPipe,
                resolvedRotation,
                previewToIgnore,
                out Pipe alignedPipe,
                out Quaternion alignedRotation)
            && TryResolvePlacementQuarterTurnsFromRotation(
                alignedPipe,
                alignedRotation,
                out int alignedQuarterTurns))
        {
            resolvedPrefab = alignedPipe;
            resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                alignedPipe,
                alignedQuarterTurns);
        }

        return true;
    }

    private void RemoveIncompatibleFixedFluidConnectorDirections(
        Vector2Int anchorCoordinate,
        int preferredFluidItemId,
        MapObject previewToIgnore,
        List<Vector2Int> directions)
    {
        if (preferredFluidItemId < 0 || directions == null || directions.Count <= 0)
        {
            return;
        }

        for (int directionIndex = directions.Count - 1; directionIndex >= 0; directionIndex--)
        {
            Vector2Int direction = directions[directionIndex];
            if (direction == Vector2Int.zero)
            {
                directions.RemoveAt(directionIndex);
                continue;
            }

            HashSet<int> directionFluidItemIds = new HashSet<int>();
            bool hasDirectionFluidConstraint = false;
            if (!TryCollectSameCoordinateFixedFluidConstraintsForDirection(
                    anchorCoordinate,
                    direction,
                    previewToIgnore,
                    directionFluidItemIds,
                    ref hasDirectionFluidConstraint)
                || !TryMergeRuntimeAdjacentFluidStorageConstraint(
                    anchorCoordinate + direction,
                    -direction,
                    directionFluidItemIds,
                    ref hasDirectionFluidConstraint)
                || !TryMergeAdjacentFluidStorageSnapshotConstraint(
                    anchorCoordinate + direction,
                    -direction,
                    previewToIgnore,
                    directionFluidItemIds,
                    ref hasDirectionFluidConstraint)
                || !TryCollectAdjacentPipeAreaFluidConstraints(
                    anchorCoordinate + direction,
                    -direction,
                    previewToIgnore,
                    directionFluidItemIds,
                    ref hasDirectionFluidConstraint)
                || hasDirectionFluidConstraint
                && !directionFluidItemIds.Contains(preferredFluidItemId))
            {
                directions.RemoveAt(directionIndex);
            }
        }
    }

    private bool TryCollectSameCoordinateFixedFluidConstraintsForDirection(
        Vector2Int coordinate,
        Vector2Int direction,
        MapObject previewToIgnore,
        HashSet<int> compatibleFluidItemIds,
        ref bool hasFluidConstraint)
    {
        List<PipeAreaBlockCandidate> candidates = new List<PipeAreaBlockCandidate>(4);
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(coordinate, previewToIgnore, candidates);

        List<Vector2Int> candidateDirections = new List<Vector2Int>(4);
        HashSet<int> candidateFluidItemIds = new HashSet<int>();
        for (int candidateIndex = 0; candidateIndex < candidates.Count; candidateIndex++)
        {
            PipeAreaBlockCandidate candidate = candidates[candidateIndex];
            candidateDirections.Clear();
            if (!TryGetPipeAreaCandidateConnectionDirections(
                    coordinate,
                    candidate,
                    candidateDirections)
                || !PipeDirectionsContain(candidateDirections, direction))
            {
                continue;
            }

            candidateFluidItemIds.Clear();
            PipeAreaFluidResolution candidateFluidResolution = ResolvePipeAreaCandidateFluidItemIds(
                coordinate,
                candidate,
                candidateFluidItemIds);
            if (candidateFluidResolution == PipeAreaFluidResolution.UnresolvedFluidEndpoint
                || candidateFluidResolution == PipeAreaFluidResolution.Resolved
                && !TryMergeFluidCompatibilityConstraint(
                    compatibleFluidItemIds,
                    ref hasFluidConstraint,
                    candidateFluidItemIds))
            {
                return false;
            }
        }

        return true;
    }

    private bool TryGetAdjacentPipeBranchFluidItemId(
        Vector2Int anchorCoordinate,
        Vector2Int neighborCoordinate,
        Pipe neighborPipe,
        Quaternion neighborRotation,
        MapObject previewToIgnore,
        out int fluidItemId)
    {
        fluidItemId = -1;
        if (neighborPipe == null)
        {
            return false;
        }

        Vector2Int directionToAnchor = anchorCoordinate - neighborCoordinate;
        adjacentPipeBranchFluidItemIdsScratch.Clear();
        bool hasFluidConstraint = false;
        if (!TryCollectPipeNetworkFluidConstraintsExcludingConnection(
                neighborCoordinate,
                neighborPipe,
                neighborRotation,
                previewToIgnore,
                neighborCoordinate,
                directionToAnchor,
                adjacentPipeBranchFluidItemIdsScratch,
                ref hasFluidConstraint)
            || !hasFluidConstraint
            || adjacentPipeBranchFluidItemIdsScratch.Count != 1)
        {
            return false;
        }

        foreach (int branchFluidItemId in adjacentPipeBranchFluidItemIdsScratch)
        {
            fluidItemId = branchFluidItemId;
            return true;
        }

        return false;
    }

    private List<Vector2Int> GetPipeVariantFixedConnectionDirections(
        Vector2Int anchorCoordinate,
        MapObject previewToIgnore)
    {
        List<Vector2Int> directions = new List<Vector2Int>(4);
        AppendFixedFluidPipeConnectionDirections(anchorCoordinate, previewToIgnore, directions);
        if (directions.Count <= 0)
        {
            AddPipeDirections(
                directions,
                GetFixedFluidConnectorNeighborConnectionDirections(anchorCoordinate));
        }
        else
        {
            // A pipe sharing a PipeOutput/PipeInput cell already has a fixed direction.
            // Adjacent tanks remain real branches and must participate in every variant path,
            // including forced re-resolution when another pipe is connected later.
            AddPipeDirections(
                directions,
                GetFluidTankNeighborConnectionDirections(anchorCoordinate, previewToIgnore));
        }

        return directions;
    }

    private List<Vector2Int> GetFluidTankNeighborConnectionDirections(
        Vector2Int anchorCoordinate,
        MapObject previewToIgnore)
    {
        List<Vector2Int> directions = new List<Vector2Int>(4);
        for (int i = 0; i < PipeCardinalDirections.Length; i++)
        {
            Vector2Int sideDirection = PipeCardinalDirections[i];
            Vector2Int connectorCoordinate = anchorCoordinate + sideDirection;
            if (!TryGetFluidTankPlacementSnapshotAtCoordinate(
                    connectorCoordinate,
                    previewToIgnore,
                    out PlacementSnapshot tankSnapshot)
                || !TryGetFixedFluidConnectorCompatibilityAtCoordinate(
                    connectorCoordinate,
                    -sideDirection,
                    out bool connectorCanConnect)
                || !connectorCanConnect
                || !CanPipeConnectionMatchFluidTank(
                    anchorCoordinate,
                    sideDirection,
                    tankSnapshot,
                    previewToIgnore)
                || !CanPipeAreaBlocksConnect(anchorCoordinate, connectorCoordinate))
            {
                continue;
            }

            AddPipeDirection(directions, sideDirection);
        }

        return directions;
    }

    private bool CanPipeConnectionMatchFluidTank(
        Vector2Int pipeCoordinate,
        Vector2Int directionFromPipe,
        PlacementSnapshot tankSnapshot,
        MapObject previewToIgnore)
    {
        int tankFluidItemId = ResolveSnapshotStoredFluidItemId(tankSnapshot);
        if (tankFluidItemId < 0
            || !TryGetPipePlacementAtCoordinate(
                pipeCoordinate,
                previewToIgnore,
                out Pipe pipe,
                out Quaternion pipeRotation)
            || pipe == null)
        {
            return true;
        }

        adjacentPipeBranchFluidItemIdsScratch.Clear();
        bool hasPipeFluidConstraint = false;
        bool collected = TryCollectPipeNetworkFluidConstraintsExcludingConnection(
            pipeCoordinate,
            pipe,
            pipeRotation,
            previewToIgnore,
            pipeCoordinate,
            directionFromPipe,
            adjacentPipeBranchFluidItemIdsScratch,
            ref hasPipeFluidConstraint);
        bool compatible = collected
                          && (!hasPipeFluidConstraint
                              || adjacentPipeBranchFluidItemIdsScratch.Contains(tankFluidItemId));
        adjacentPipeBranchFluidItemIdsScratch.Clear();
        return compatible;
    }

    private List<Vector2Int> GetBoilerFixedFluidPipeConnectionDirections(
        Vector2Int anchorCoordinate,
        MapObject previewToIgnore)
    {
        List<Vector2Int> directions = new List<Vector2Int>(4);
        AppendBoilerFixedFluidPipeConnectionDirections(anchorCoordinate, previewToIgnore, directions);
        if (directions.Count <= 0)
        {
            AddPipeDirections(directions, GetBoilerFixedFluidConnectorNeighborConnectionDirections(anchorCoordinate));
        }

        return directions;
    }

    private List<Vector2Int> GetBoilerFixedFluidConnectorNeighborConnectionDirections(Vector2Int anchorCoordinate)
    {
        List<Vector2Int> directions = new List<Vector2Int>(4);

        for (int i = 0; i < PipeCardinalDirections.Length; i++)
        {
            Vector2Int sideDirection = PipeCardinalDirections[i];
            if (TryGetBoilerFixedFluidConnectorCompatibilityAtCoordinate(
                    anchorCoordinate + sideDirection,
                    -sideDirection,
                    out bool connectorCanConnect)
                && CanPipeAreaBlocksConnect(anchorCoordinate, anchorCoordinate + sideDirection)
                && connectorCanConnect)
            {
                AddPipeDirection(directions, sideDirection);
            }
        }

        return directions;
    }

    private void AppendBoilerFixedFluidPipeConnectionDirections(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        List<Vector2Int> directions)
    {
        if (directions == null)
        {
            return;
        }

        if (TryGetPreviewPlacementSnapshot(coordinate, previewToIgnore, out PlacementSnapshot previewSnapshot))
        {
            TryAppendBoilerPipeAxisDirections(previewSnapshot, coordinate, directions);
        }

        if (TryGetInstalledPlacementSnapshot(coordinate, out PlacementSnapshot installedSnapshot))
        {
            TryAppendBoilerPipeAxisDirections(installedSnapshot, coordinate, directions);
        }

        runtimeGridModuleScratch.Clear();
        if (InputOutputModule.CollectModulesAtRuntimeGridCoordinate(coordinate, runtimeGridModuleScratch))
        {
            for (int i = 0; i < runtimeGridModuleScratch.Count; i++)
            {
                if (TryGetRuntimeModulePlacementSnapshot(
                        runtimeGridModuleScratch[i],
                        out PlacementSnapshot runtimeGridSnapshot))
                {
                    TryAppendBoilerPipeAxisDirections(runtimeGridSnapshot, coordinate, directions);
                }
            }
            runtimeGridModuleScratch.Clear();
        }
        else if (TryGetRuntimeGridPlacementSnapshot(coordinate, out PlacementSnapshot runtimeGridSnapshot))
        {
            TryAppendBoilerPipeAxisDirections(runtimeGridSnapshot, coordinate, directions);
        }

        runtimeAreaModuleScratch.Clear();
        if (InputOutputModule.CollectModulesAtRuntimeAreaCoordinate(coordinate, runtimeAreaModuleScratch))
        {
            for (int i = 0; i < runtimeAreaModuleScratch.Count; i++)
            {
                if (TryGetRuntimeModulePlacementSnapshot(
                        runtimeAreaModuleScratch[i],
                        out PlacementSnapshot runtimeAreaSnapshot))
                {
                    TryAppendBoilerPipeAxisDirections(runtimeAreaSnapshot, coordinate, directions);
                }
            }
            runtimeAreaModuleScratch.Clear();
        }
        else if (TryGetRuntimeAreaPlacementSnapshot(coordinate, out PlacementSnapshot runtimeAreaSnapshot))
        {
            TryAppendBoilerPipeAxisDirections(runtimeAreaSnapshot, coordinate, directions);
        }

        if (TryGetSavedPlacementSnapshot(coordinate, out PlacementSnapshot savedSnapshot))
        {
            TryAppendBoilerPipeAxisDirections(savedSnapshot, coordinate, directions);
        }
    }

    private void AppendFixedFluidPipeConnectionDirections(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        List<Vector2Int> directions)
    {
        if (directions == null)
        {
            return;
        }

        if (TryGetPreviewPlacementSnapshot(coordinate, previewToIgnore, out PlacementSnapshot previewSnapshot))
        {
            TryAppendFixedFluidPipeConnectionDirections(previewSnapshot, coordinate, directions);
        }
        AppendPreviewRectGridPipeAreaConnectionDirections(coordinate, previewToIgnore, directions);

        if (TryGetInstalledPlacementSnapshot(coordinate, out PlacementSnapshot installedSnapshot))
        {
            TryAppendFixedFluidPipeConnectionDirections(installedSnapshot, coordinate, directions);
        }

        runtimeGridModuleScratch.Clear();
        if (InputOutputModule.CollectModulesAtRuntimeGridCoordinate(coordinate, runtimeGridModuleScratch))
        {
            for (int i = 0; i < runtimeGridModuleScratch.Count; i++)
            {
                if (TryGetRuntimeModulePlacementSnapshot(
                        runtimeGridModuleScratch[i],
                        out PlacementSnapshot runtimeGridSnapshot))
                {
                    TryAppendFixedFluidPipeConnectionDirections(runtimeGridSnapshot, coordinate, directions);
                }
            }
            runtimeGridModuleScratch.Clear();
        }
        else if (TryGetRuntimeGridPlacementSnapshot(coordinate, out PlacementSnapshot runtimeGridSnapshot))
        {
            TryAppendFixedFluidPipeConnectionDirections(runtimeGridSnapshot, coordinate, directions);
        }

        runtimeAreaModuleScratch.Clear();
        if (InputOutputModule.CollectModulesAtRuntimeAreaCoordinate(coordinate, runtimeAreaModuleScratch))
        {
            for (int i = 0; i < runtimeAreaModuleScratch.Count; i++)
            {
                if (TryGetRuntimeModulePlacementSnapshot(
                        runtimeAreaModuleScratch[i],
                        out PlacementSnapshot runtimeAreaSnapshot))
                {
                    TryAppendFixedFluidPipeConnectionDirections(runtimeAreaSnapshot, coordinate, directions);
                }
            }
            runtimeAreaModuleScratch.Clear();
        }
        else if (TryGetRuntimeAreaPlacementSnapshot(coordinate, out PlacementSnapshot runtimeAreaSnapshot))
        {
            TryAppendFixedFluidPipeConnectionDirections(runtimeAreaSnapshot, coordinate, directions);
        }

        if (TryGetSavedPlacementSnapshot(coordinate, out PlacementSnapshot savedSnapshot))
        {
            TryAppendFixedFluidPipeConnectionDirections(savedSnapshot, coordinate, directions);
        }
    }

    private bool CanPipeAreaBlocksConnect(Vector2Int firstCoordinate, Vector2Int secondCoordinate)
    {
        pipeAreaBlockCandidateScratchA.Clear();
        pipeAreaBlockCandidateScratchB.Clear();

        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(firstCoordinate, null, pipeAreaBlockCandidateScratchA);
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(secondCoordinate, null, pipeAreaBlockCandidateScratchB);

        bool hasTypedPipeAreaCandidates = pipeAreaBlockCandidateScratchA.Count > 0
            && pipeAreaBlockCandidateScratchB.Count > 0;
        bool canConnect = !hasTypedPipeAreaCandidates;
        if (hasTypedPipeAreaCandidates)
        {
            for (int firstIndex = 0; firstIndex < pipeAreaBlockCandidateScratchA.Count; firstIndex++)
            {
                for (int secondIndex = 0; secondIndex < pipeAreaBlockCandidateScratchB.Count; secondIndex++)
                {
                    if (CanPipeAreaBlockCandidatesConnect(
                            firstCoordinate,
                            pipeAreaBlockCandidateScratchA[firstIndex],
                            secondCoordinate,
                            pipeAreaBlockCandidateScratchB[secondIndex]))
                    {
                        canConnect = true;
                        break;
                    }
                }

                if (canConnect)
                {
                    break;
                }
            }
        }
        else if (HasPipeAreaFluidStorageAtCoordinate(firstCoordinate)
                 || HasPipeAreaFluidStorageAtCoordinate(secondCoordinate))
        {
            canConnect = true;
        }

        pipeAreaBlockCandidateScratchA.Clear();
        pipeAreaBlockCandidateScratchB.Clear();
        return canConnect;
    }

    private bool HasPipeAreaFluidStorageAtCoordinate(Vector2Int coordinate)
    {
        if (TryGetPreviewPlacementSnapshot(coordinate, null, out PlacementSnapshot previewSnapshot)
            && IsFluidStoragePipeNodeAtCoordinate(previewSnapshot, coordinate))
        {
            return true;
        }

        if (TryGetInstalledPlacementSnapshot(coordinate, out PlacementSnapshot installedSnapshot)
            && IsFluidStoragePipeNodeAtCoordinate(installedSnapshot, coordinate))
        {
            return true;
        }

        runtimeGridModuleScratch.Clear();
        if (InputOutputModule.CollectModulesAtRuntimeGridCoordinate(coordinate, runtimeGridModuleScratch))
        {
            for (int i = 0; i < runtimeGridModuleScratch.Count; i++)
            {
                if (TryGetRuntimeModulePlacementSnapshot(
                        runtimeGridModuleScratch[i],
                        out PlacementSnapshot runtimeGridSnapshot)
                    && IsFluidStoragePipeNodeAtCoordinate(runtimeGridSnapshot, coordinate))
                {
                    runtimeGridModuleScratch.Clear();
                    return true;
                }
            }

            runtimeGridModuleScratch.Clear();
        }
        else if (TryGetRuntimeGridPlacementSnapshot(coordinate, out PlacementSnapshot runtimeGridSnapshot)
                 && IsFluidStoragePipeNodeAtCoordinate(runtimeGridSnapshot, coordinate))
        {
            return true;
        }

        runtimeAreaModuleScratch.Clear();
        if (InputOutputModule.CollectModulesAtRuntimeAreaCoordinate(coordinate, runtimeAreaModuleScratch))
        {
            for (int i = 0; i < runtimeAreaModuleScratch.Count; i++)
            {
                if (TryGetRuntimeModulePlacementSnapshot(
                        runtimeAreaModuleScratch[i],
                        out PlacementSnapshot runtimeAreaSnapshot)
                    && IsFluidStoragePipeNodeAtCoordinate(runtimeAreaSnapshot, coordinate))
                {
                    runtimeAreaModuleScratch.Clear();
                    return true;
                }
            }

            runtimeAreaModuleScratch.Clear();
        }
        else if (TryGetRuntimeAreaPlacementSnapshot(coordinate, out PlacementSnapshot runtimeAreaSnapshot)
                 && IsFluidStoragePipeNodeAtCoordinate(runtimeAreaSnapshot, coordinate))
        {
            return true;
        }

        return TryGetSavedPlacementSnapshot(coordinate, out PlacementSnapshot savedSnapshot)
               && IsFluidStoragePipeNodeAtCoordinate(savedSnapshot, coordinate);
    }

    private void AppendPreviewRectGridPipeAreaConnectionDirections(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        List<Vector2Int> directions)
    {
        if (directions == null)
        {
            return;
        }

        pipeAreaBlockCandidateScratchC.Clear();
        CollectPreviewRectGridPipeAreaBlockCandidatesAtCoordinate(
            coordinate,
            previewToIgnore,
            pipeAreaBlockCandidateScratchC);

        for (int i = 0; i < pipeAreaBlockCandidateScratchC.Count; i++)
        {
            PipeAreaBlockCandidate candidate = pipeAreaBlockCandidateScratchC[i];
            if (candidate.snapshot == null
                || !TryGetInputOutputModule(candidate.snapshot.mapObject, out InputOutputModule inputOutputModule)
                || !TryGetRectGridPipeAreaConnectionDirection(
                    candidate.snapshot.mapObject,
                    inputOutputModule,
                    candidate.snapshot.anchorCoordinate,
                    candidate.snapshot.quarterTurns,
                    coordinate,
                    out Vector2Int connectionDirection))
            {
                continue;
            }

            AddPipeDirection(directions, connectionDirection);
        }

        pipeAreaBlockCandidateScratchC.Clear();
    }

    private bool IsFluidStoragePipeNodeAtCoordinate(PlacementSnapshot snapshot, Vector2Int coordinate)
    {
        if (snapshot == null
            || !(snapshot.mapObject is InstallationObject installationObject)
            || installationObject is Pipe
            || installationObject is Pump
            || installationObject is InputOutputModule
            || !installationObject.CanStoreFluid)
        {
            return false;
        }

        List<Vector2Int> coordinates = GetFootprintCoordinates(
            snapshot.anchorCoordinate,
            snapshot.mapObject,
            snapshot.quarterTurns);
        return coordinates.Contains(coordinate);
    }

    private void CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        List<PipeAreaBlockCandidate> candidates)
    {
        if (candidates == null)
        {
            return;
        }

        if (TryGetPreviewPlacementSnapshot(coordinate, previewToIgnore, out PlacementSnapshot previewSnapshot))
        {
            TryAddRectGridPipeAreaBlockCandidate(previewSnapshot, coordinate, candidates);
        }

        CollectPreviewRectGridPipeAreaBlockCandidatesAtCoordinate(coordinate, previewToIgnore, candidates);

        if (TryGetInstalledPlacementSnapshot(coordinate, out PlacementSnapshot installedSnapshot))
        {
            TryAddRectGridPipeAreaBlockCandidate(installedSnapshot, coordinate, candidates);
        }

        runtimeGridModuleScratch.Clear();
        if (InputOutputModule.CollectModulesAtRuntimeGridCoordinate(coordinate, runtimeGridModuleScratch))
        {
            for (int i = 0; i < runtimeGridModuleScratch.Count; i++)
            {
                if (TryGetRuntimeModulePlacementSnapshot(
                        runtimeGridModuleScratch[i],
                        out PlacementSnapshot runtimeGridSnapshot))
                {
                    TryAddRectGridPipeAreaBlockCandidate(runtimeGridSnapshot, coordinate, candidates);
                }
            }

            runtimeGridModuleScratch.Clear();
        }
        else if (TryGetRuntimeGridPlacementSnapshot(coordinate, out PlacementSnapshot runtimeGridSnapshot))
        {
            TryAddRectGridPipeAreaBlockCandidate(runtimeGridSnapshot, coordinate, candidates);
        }

        runtimeAreaModuleScratch.Clear();
        if (InputOutputModule.CollectModulesAtRuntimeAreaCoordinate(coordinate, runtimeAreaModuleScratch))
        {
            for (int i = 0; i < runtimeAreaModuleScratch.Count; i++)
            {
                if (TryGetRuntimeModulePlacementSnapshot(
                        runtimeAreaModuleScratch[i],
                        out PlacementSnapshot runtimeAreaSnapshot))
                {
                    TryAddRectGridPipeAreaBlockCandidate(runtimeAreaSnapshot, coordinate, candidates);
                }
            }

            runtimeAreaModuleScratch.Clear();
        }
        else if (TryGetRuntimeAreaPlacementSnapshot(coordinate, out PlacementSnapshot runtimeAreaSnapshot))
        {
            TryAddRectGridPipeAreaBlockCandidate(runtimeAreaSnapshot, coordinate, candidates);
        }

        if (TryGetSavedPlacementSnapshot(coordinate, out PlacementSnapshot savedSnapshot))
        {
            TryAddRectGridPipeAreaBlockCandidate(savedSnapshot, coordinate, candidates);
        }

        savedPipeAreaInstallationStatesScratch.Clear();
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain != null)
        {
            terrain.CollectSavedInstallationStatesAtInteractionCoordinate(
                coordinate,
                savedPipeAreaInstallationStatesScratch);
            for (int stateIndex = 0;
                 stateIndex < savedPipeAreaInstallationStatesScratch.Count;
                 stateIndex++)
            {
                if (TryCreateSavedPlacementSnapshot(
                        savedPipeAreaInstallationStatesScratch[stateIndex],
                        out PlacementSnapshot interactionSnapshot))
                {
                    TryAddRectGridPipeAreaBlockCandidate(
                        interactionSnapshot,
                        coordinate,
                        candidates);
                }
            }
        }

        savedPipeAreaInstallationStatesScratch.Clear();
    }

    private void CollectPreviewRectGridPipeAreaBlockCandidatesAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        List<PipeAreaBlockCandidate> candidates)
    {
        if (candidates == null)
        {
            return;
        }

        CleanupInstallPreviewReferences();
        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            MapObject preview = installPreviewInstances[i];
            if (preview == null
                || preview == previewToIgnore
                || !TryGetPreviewAnchorCoordinate(preview, out Vector2Int previewAnchorCoordinate))
            {
                continue;
            }

            MapObject footprintSource = ResolveInstallPreviewFootprintSource(preview) ?? preview;
            PlacementSnapshot snapshot = new PlacementSnapshot
            {
                mapObject = footprintSource,
                rotation = preview.transform.rotation,
                anchorCoordinate = previewAnchorCoordinate,
                quarterTurns = GetPreviewAreaQuarterTurns(preview),
                storedFluidItemId = preview is InstallationObject previewInstallation
                    ? previewInstallation.StoredFluidItemId
                    : -1
            };
            TryAddRectGridPipeAreaBlockCandidate(snapshot, coordinate, candidates);
        }
    }

    private bool TryAddRectGridPipeAreaBlockCandidate(
        PlacementSnapshot snapshot,
        Vector2Int coordinate,
        List<PipeAreaBlockCandidate> candidates)
    {
        if (snapshot == null
            || snapshot.mapObject == null
            || candidates == null
            || !TryGetRectGridFootprintBlockType(
                snapshot.anchorCoordinate,
                snapshot.mapObject,
                snapshot.quarterTurns,
                coordinate,
                out InputOutputModule.RectGridBlockType blockType)
            || !InputOutputModule.AllowsPipeAreaInteraction(blockType)
            || PipeAreaBlockCandidatesContain(candidates, snapshot, blockType))
        {
            return false;
        }

        candidates.Add(new PipeAreaBlockCandidate(snapshot, blockType));
        return true;
    }

    private static bool PipeAreaBlockCandidatesContain(
        List<PipeAreaBlockCandidate> candidates,
        PlacementSnapshot snapshot,
        InputOutputModule.RectGridBlockType blockType)
    {
        if (candidates == null)
        {
            return false;
        }

        for (int i = 0; i < candidates.Count; i++)
        {
            PipeAreaBlockCandidate candidate = candidates[i];
            if (candidate.blockType == blockType
                && candidate.snapshot != null
                && snapshot != null
                && candidate.snapshot.mapObject == snapshot.mapObject
                && candidate.snapshot.anchorCoordinate == snapshot.anchorCoordinate
                && candidate.snapshot.quarterTurns == snapshot.quarterTurns)
            {
                return true;
            }
        }

        return false;
    }

    private static bool CanPipeAreaBlockTypesConnect(
        InputOutputModule.RectGridBlockType firstBlockType,
        InputOutputModule.RectGridBlockType secondBlockType)
    {
        if (!InputOutputModule.AllowsPipeAreaInteraction(firstBlockType)
            || !InputOutputModule.AllowsPipeAreaInteraction(secondBlockType))
        {
            return false;
        }

        if (IsPipePassBlockType(firstBlockType) || IsPipePassBlockType(secondBlockType))
        {
            return true;
        }

        return InputOutputModule.IsOutputBlockType(firstBlockType)
               != InputOutputModule.IsOutputBlockType(secondBlockType);
    }

    private bool CanPipeAreaBlockCandidatesConnect(
        Vector2Int firstCoordinate,
        PipeAreaBlockCandidate firstCandidate,
        Vector2Int secondCoordinate,
        PipeAreaBlockCandidate secondCandidate)
    {
        if (!CanPipeAreaBlockTypesConnect(firstCandidate.blockType, secondCandidate.blockType))
        {
            return false;
        }

        if (IsPipePassBlockType(firstCandidate.blockType) || IsPipePassBlockType(secondCandidate.blockType))
        {
            return PipePassMatchesPipeArea(
                firstCoordinate,
                firstCandidate,
                secondCoordinate,
                secondCandidate);
        }

        if (InputOutputModule.IsOutputBlockType(firstCandidate.blockType))
        {
            return PipeOutputMatchesPipeInput(
                firstCoordinate,
                firstCandidate,
                secondCoordinate,
                secondCandidate);
        }

        if (InputOutputModule.IsOutputBlockType(secondCandidate.blockType))
        {
            return PipeOutputMatchesPipeInput(
                secondCoordinate,
                secondCandidate,
                firstCoordinate,
                firstCandidate);
        }

        return false;
    }

    private bool PipeAreaBlockCandidatesWouldConnect(
        Vector2Int firstCoordinate,
        PipeAreaBlockCandidate firstCandidate,
        Vector2Int secondCoordinate,
        PipeAreaBlockCandidate secondCandidate)
    {
        if (!CanPipeAreaBlockTypesConnect(firstCandidate.blockType, secondCandidate.blockType))
        {
            return false;
        }

        if (IsPipePassBlockType(firstCandidate.blockType) || IsPipePassBlockType(secondCandidate.blockType))
        {
            return PipePassWouldConnectPipeArea(
                firstCoordinate,
                firstCandidate,
                secondCoordinate,
                secondCandidate);
        }

        if (InputOutputModule.IsOutputBlockType(firstCandidate.blockType))
        {
            return PipeOutputDirectionMatchesPipeInput(
                firstCoordinate,
                firstCandidate,
                secondCoordinate,
                secondCandidate);
        }

        if (InputOutputModule.IsOutputBlockType(secondCandidate.blockType))
        {
            return PipeOutputDirectionMatchesPipeInput(
                secondCoordinate,
                secondCandidate,
                firstCoordinate,
                firstCandidate);
        }

        return false;
    }

    private bool PipePassWouldConnectPipeArea(
        Vector2Int firstCoordinate,
        PipeAreaBlockCandidate firstCandidate,
        Vector2Int secondCoordinate,
        PipeAreaBlockCandidate secondCandidate)
    {
        bool firstIsPipePass = IsPipePassBlockType(firstCandidate.blockType);
        bool secondIsPipePass = IsPipePassBlockType(secondCandidate.blockType);
        if (!firstIsPipePass && !secondIsPipePass)
        {
            return false;
        }

        if (firstIsPipePass && secondIsPipePass)
        {
            return TryGetPipeAreaObjectDirection(firstCoordinate, firstCandidate, out Vector2Int firstObjectDirection)
                   && TryGetPipeAreaObjectDirection(secondCoordinate, secondCandidate, out Vector2Int secondObjectDirection)
                   && PipePassDirectionsMatch(
                       firstCoordinate,
                       firstObjectDirection,
                       secondCoordinate,
                       secondObjectDirection);
        }

        if (firstIsPipePass)
        {
            return PipePassWouldConnectTypedPipeArea(
                firstCoordinate,
                firstCandidate,
                secondCoordinate,
                secondCandidate);
        }

        return PipePassWouldConnectTypedPipeArea(
            secondCoordinate,
            secondCandidate,
            firstCoordinate,
            firstCandidate);
    }

    private bool PipePassWouldConnectTypedPipeArea(
        Vector2Int pipePassCoordinate,
        PipeAreaBlockCandidate pipePassCandidate,
        Vector2Int typedCoordinate,
        PipeAreaBlockCandidate typedCandidate)
    {
        if (!TryGetPipeAreaObjectDirection(pipePassCoordinate, pipePassCandidate, out Vector2Int pipePassObjectDirection)
            || !TryGetPipeAreaObjectDirection(typedCoordinate, typedCandidate, out Vector2Int typedObjectDirection))
        {
            return false;
        }

        if (InputOutputModule.IsOutputBlockType(typedCandidate.blockType))
        {
            Vector2Int outputFlowDirection = -typedObjectDirection;
            return PipeOutputDirectionMatchesPipePass(
                typedCoordinate,
                outputFlowDirection,
                pipePassCoordinate,
                pipePassObjectDirection);
        }

        if (InputOutputModule.IsInputItemBlockType(typedCandidate.blockType))
        {
            return PipePassDirectionMatchesPipeInput(
                pipePassCoordinate,
                pipePassObjectDirection,
                typedCoordinate,
                typedObjectDirection);
        }

        return false;
    }

    private bool PipePassMatchesPipeArea(
        Vector2Int firstCoordinate,
        PipeAreaBlockCandidate firstCandidate,
        Vector2Int secondCoordinate,
        PipeAreaBlockCandidate secondCandidate)
    {
        bool firstIsPipePass = IsPipePassBlockType(firstCandidate.blockType);
        bool secondIsPipePass = IsPipePassBlockType(secondCandidate.blockType);
        if (!firstIsPipePass && !secondIsPipePass)
        {
            return false;
        }

        if (firstIsPipePass && secondIsPipePass)
        {
            return PipePassMatchesPipePass(
                firstCoordinate,
                firstCandidate,
                secondCoordinate,
                secondCandidate);
        }

        if (firstIsPipePass)
        {
            return PipePassMatchesTypedPipeArea(
                firstCoordinate,
                firstCandidate,
                secondCoordinate,
                secondCandidate);
        }

        return PipePassMatchesTypedPipeArea(
            secondCoordinate,
            secondCandidate,
            firstCoordinate,
            firstCandidate);
    }

    private bool PipePassMatchesTypedPipeArea(
        Vector2Int pipePassCoordinate,
        PipeAreaBlockCandidate pipePassCandidate,
        Vector2Int typedCoordinate,
        PipeAreaBlockCandidate typedCandidate)
    {
        if (!TryGetPipeAreaObjectDirection(pipePassCoordinate, pipePassCandidate, out Vector2Int pipePassObjectDirection)
            || !TryGetPipeAreaObjectDirection(typedCoordinate, typedCandidate, out Vector2Int typedObjectDirection))
        {
            return false;
        }

        if (InputOutputModule.IsOutputBlockType(typedCandidate.blockType))
        {
            Vector2Int outputFlowDirection = -typedObjectDirection;
            return PipeOutputDirectionMatchesPipePass(
                    typedCoordinate,
                    outputFlowDirection,
                    pipePassCoordinate,
                    pipePassObjectDirection)
                && PipePassItemsMatchOutput(pipePassCandidate, typedCandidate);
        }

        if (InputOutputModule.IsInputItemBlockType(typedCandidate.blockType))
        {
            return PipePassDirectionMatchesPipeInput(
                    pipePassCoordinate,
                    pipePassObjectDirection,
                    typedCoordinate,
                    typedObjectDirection)
                && PipePassItemsMatchInput(pipePassCandidate, typedCandidate, typedCoordinate);
        }

        return false;
    }

    private bool PipePassMatchesPipePass(
        Vector2Int firstCoordinate,
        PipeAreaBlockCandidate firstCandidate,
        Vector2Int secondCoordinate,
        PipeAreaBlockCandidate secondCandidate)
    {
        return TryGetPipeAreaObjectDirection(firstCoordinate, firstCandidate, out Vector2Int firstObjectDirection)
               && TryGetPipeAreaObjectDirection(secondCoordinate, secondCandidate, out Vector2Int secondObjectDirection)
               && PipePassDirectionsMatch(
                   firstCoordinate,
                   firstObjectDirection,
                   secondCoordinate,
                   secondObjectDirection)
               && PipePassItemsMatchPipePass(firstCandidate, secondCandidate);
    }

    private bool TryGetPipeAreaObjectDirection(
        Vector2Int coordinate,
        PipeAreaBlockCandidate candidate,
        out Vector2Int direction)
    {
        direction = Vector2Int.zero;
        return candidate.snapshot != null
               && candidate.snapshot.mapObject != null
               && TryGetInputOutputModule(candidate.snapshot.mapObject, out InputOutputModule inputOutputModule)
               && TryGetRectGridPipeAreaConnectionDirection(
                   candidate.snapshot.mapObject,
                   inputOutputModule,
                   candidate.snapshot.anchorCoordinate,
                   candidate.snapshot.quarterTurns,
                   coordinate,
                   out direction)
               && direction != Vector2Int.zero;
    }

    private static bool PipePassDirectionMatchesPipeInput(
        Vector2Int pipePassCoordinate,
        Vector2Int pipePassObjectDirection,
        Vector2Int inputCoordinate,
        Vector2Int inputObjectDirection)
    {
        Vector2Int coordinateDelta = inputCoordinate - pipePassCoordinate;
        if (coordinateDelta == Vector2Int.zero)
        {
            return inputObjectDirection == -pipePassObjectDirection;
        }

        return coordinateDelta == -pipePassObjectDirection
               && inputObjectDirection == coordinateDelta;
    }

    private static bool PipeOutputDirectionMatchesPipePass(
        Vector2Int outputCoordinate,
        Vector2Int outputFlowDirection,
        Vector2Int pipePassCoordinate,
        Vector2Int pipePassObjectDirection)
    {
        if (outputFlowDirection == Vector2Int.zero)
        {
            return false;
        }

        Vector2Int coordinateDelta = pipePassCoordinate - outputCoordinate;
        return (coordinateDelta == Vector2Int.zero || coordinateDelta == outputFlowDirection)
               && pipePassObjectDirection == outputFlowDirection;
    }

    private static bool PipePassDirectionsMatch(
        Vector2Int firstCoordinate,
        Vector2Int firstObjectDirection,
        Vector2Int secondCoordinate,
        Vector2Int secondObjectDirection)
    {
        Vector2Int coordinateDelta = secondCoordinate - firstCoordinate;
        if (coordinateDelta == Vector2Int.zero)
        {
            return firstObjectDirection == -secondObjectDirection;
        }

        return coordinateDelta == -firstObjectDirection
               && secondObjectDirection == coordinateDelta;
    }

    private bool PipePassItemsMatchInput(
        PipeAreaBlockCandidate pipePassCandidate,
        PipeAreaBlockCandidate inputCandidate,
        Vector2Int inputCoordinate)
    {
        HashSet<int> pipePassItemIds = new HashSet<int>();
        HashSet<int> inputItemIds = new HashSet<int>();
        bool hasPipePassItems = TryGetCandidatePipePassItemIds(pipePassCandidate, pipePassItemIds);
        bool hasInputItems = inputCandidate.snapshot != null
                             && TryGetCandidateInputItemIdsAtCoordinate(
                                 inputCandidate.snapshot.anchorCoordinate,
                                 inputCandidate.snapshot.mapObject,
                                 inputCandidate.snapshot.quarterTurns,
                                 inputCoordinate,
                                 inputItemIds);

        return !hasPipePassItems || !hasInputItems || HasSharedItemId(pipePassItemIds, inputItemIds);
    }

    private bool PipePassItemsMatchOutput(
        PipeAreaBlockCandidate pipePassCandidate,
        PipeAreaBlockCandidate outputCandidate)
    {
        HashSet<int> pipePassItemIds = new HashSet<int>();
        HashSet<int> outputItemIds = new HashSet<int>();
        bool hasPipePassItems = TryGetCandidatePipePassItemIds(pipePassCandidate, pipePassItemIds);
        bool hasOutputItems = outputCandidate.snapshot != null
                              && TryGetCandidateOutputItemIds(
                                  outputCandidate.snapshot.anchorCoordinate,
                                  outputCandidate.snapshot.mapObject,
                                  outputCandidate.snapshot.quarterTurns,
                                  outputItemIds);

        return !hasPipePassItems || !hasOutputItems || HasSharedItemId(pipePassItemIds, outputItemIds);
    }

    private bool PipePassItemsMatchPipePass(
        PipeAreaBlockCandidate firstCandidate,
        PipeAreaBlockCandidate secondCandidate)
    {
        HashSet<int> firstItemIds = new HashSet<int>();
        HashSet<int> secondItemIds = new HashSet<int>();
        bool hasFirstItems = TryGetCandidatePipePassItemIds(firstCandidate, firstItemIds);
        bool hasSecondItems = TryGetCandidatePipePassItemIds(secondCandidate, secondItemIds);
        return !hasFirstItems || !hasSecondItems || HasSharedItemId(firstItemIds, secondItemIds);
    }

    private bool TryGetCandidatePipePassItemIds(PipeAreaBlockCandidate candidate, ISet<int> itemIds)
    {
        if (itemIds == null
            || !IsPipePassBlockType(candidate.blockType)
            || candidate.snapshot == null
            || !TryGetInputOutputModule(candidate.snapshot.mapObject, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        bool foundAny = false;
        IReadOnlyList<InputOutputModule.ItemIoEntry> inputList = inputOutputModule.InputList;
        if (inputList == null)
        {
            return false;
        }

        for (int i = 0; i < inputList.Count; i++)
        {
            ItemDefinition itemDefinition = inputList[i].itemDefinition;
            if (itemDefinition == null || itemDefinition.id < 0)
            {
                continue;
            }

            itemIds.Add(itemDefinition.id);
            foundAny = true;
        }

        return foundAny;
    }

    private bool PipeOutputMatchesPipeInput(
        Vector2Int outputCoordinate,
        PipeAreaBlockCandidate outputCandidate,
        Vector2Int inputCoordinate,
        PipeAreaBlockCandidate inputCandidate)
    {
        if (outputCandidate.snapshot == null || inputCandidate.snapshot == null)
        {
            return false;
        }

        if (!PipeOutputDirectionMatchesPipeInput(
                outputCoordinate,
                outputCandidate,
                inputCoordinate,
                inputCandidate))
        {
            return false;
        }

        HashSet<int> outputItemIds = new HashSet<int>();
        if (!TryGetCandidateOutputItemIds(
                outputCandidate.snapshot.anchorCoordinate,
                outputCandidate.snapshot.mapObject,
                outputCandidate.snapshot.quarterTurns,
                outputItemIds))
        {
            return false;
        }

        if (InputOutputModule.IsInputItemBlockType(inputCandidate.blockType))
        {
            HashSet<int> inputItemIds = new HashSet<int>();
            return TryGetCandidateInputItemIdsAtCoordinate(
                    inputCandidate.snapshot.anchorCoordinate,
                    inputCandidate.snapshot.mapObject,
                    inputCandidate.snapshot.quarterTurns,
                    inputCoordinate,
                    inputItemIds)
                && HasSharedItemId(outputItemIds, inputItemIds);
        }

        if (InputOutputModule.IsInputEnergyBlockType(inputCandidate.blockType))
        {
            HashSet<ItemDefinition.EnergyType> inputEnergyTypes = new HashSet<ItemDefinition.EnergyType>();
            return TryGetCandidateInputEnergyTypes(inputCandidate.snapshot.mapObject, inputEnergyTypes)
                && HasOutputItemWithEnergyType(outputItemIds, inputEnergyTypes);
        }

        return false;
    }

    private bool PipeOutputDirectionMatchesPipeInput(
        Vector2Int outputCoordinate,
        PipeAreaBlockCandidate outputCandidate,
        Vector2Int inputCoordinate,
        PipeAreaBlockCandidate inputCandidate)
    {
        if (!TryGetInputOutputModule(outputCandidate.snapshot.mapObject, out InputOutputModule outputModule)
            || !TryGetInputOutputModule(inputCandidate.snapshot.mapObject, out InputOutputModule inputModule)
            || !TryGetRectGridPipeAreaConnectionDirection(
                outputCandidate.snapshot.mapObject,
                outputModule,
                outputCandidate.snapshot.anchorCoordinate,
                outputCandidate.snapshot.quarterTurns,
                outputCoordinate,
                out Vector2Int outputObjectDirection)
            || !TryGetRectGridPipeAreaConnectionDirection(
                inputCandidate.snapshot.mapObject,
                inputModule,
                inputCandidate.snapshot.anchorCoordinate,
                inputCandidate.snapshot.quarterTurns,
                inputCoordinate,
                out Vector2Int inputObjectDirection))
        {
            return false;
        }

        Vector2Int outputFlowDirection = -outputObjectDirection;
        if (outputFlowDirection == Vector2Int.zero || inputObjectDirection == Vector2Int.zero)
        {
            return false;
        }

        Vector2Int coordinateDelta = inputCoordinate - outputCoordinate;
        if (IsBoilerSteamGeneratorDirectCenterOutputMatch(
                outputCoordinate,
                outputCandidate,
                inputCoordinate,
                inputCandidate,
                outputFlowDirection,
                inputObjectDirection))
        {
            return true;
        }

        return (coordinateDelta == Vector2Int.zero || coordinateDelta == outputFlowDirection)
               && inputObjectDirection == outputFlowDirection;
    }

    private static bool IsBoilerSteamGeneratorDirectCenterOutputMatch(
        Vector2Int outputCoordinate,
        PipeAreaBlockCandidate outputCandidate,
        Vector2Int inputCoordinate,
        PipeAreaBlockCandidate inputCandidate,
        Vector2Int outputFlowDirection,
        Vector2Int inputObjectDirection)
    {
        return outputCandidate.snapshot != null
               && inputCandidate.snapshot != null
               && IsBoilerSource(outputCandidate.snapshot.mapObject)
               && IsSteamGeneratorSource(inputCandidate.snapshot.mapObject)
               && outputCoordinate == inputCandidate.snapshot.anchorCoordinate
               && inputCoordinate == outputCoordinate - outputFlowDirection
               && inputObjectDirection == outputFlowDirection
               && TryGetSteamGeneratorBodyDirectionFromCenter(
                   inputCandidate.snapshot.mapObject,
                   inputCandidate.snapshot.quarterTurns,
                   out Vector2Int adjacentBodyDirection)
               && adjacentBodyDirection == outputFlowDirection;
    }

    private bool TryGetBoilerPipeOutputDirectionAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out Vector2Int outputDirection)
    {
        outputDirection = Vector2Int.zero;
        pipeAreaBlockCandidateScratchA.Clear();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
            coordinate,
            previewToIgnore,
            pipeAreaBlockCandidateScratchA);

        for (int i = 0; i < pipeAreaBlockCandidateScratchA.Count; i++)
        {
            PipeAreaBlockCandidate candidate = pipeAreaBlockCandidateScratchA[i];
            if (candidate.snapshot == null
                || !TryResolveBoiler(candidate.snapshot.mapObject, out Boiler boiler)
                || !InputOutputModule.IsOutputBlockType(candidate.blockType)
                || !boiler.TryGetOutputDirectionAtCoordinate(
                    candidate.snapshot.mapObject,
                    candidate.snapshot.anchorCoordinate,
                    candidate.snapshot.quarterTurns,
                    coordinate,
                    out Vector2Int candidateOutputDirection))
            {
                continue;
            }

            if (candidateOutputDirection == Vector2Int.zero)
            {
                continue;
            }

            outputDirection = candidateOutputDirection;
            pipeAreaBlockCandidateScratchA.Clear();
            return true;
        }

        pipeAreaBlockCandidateScratchA.Clear();
        return false;
    }

    private bool TryGetSteamGeneratorPipePassTailDirectionAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out Vector2Int tailDirection,
        out PipeAreaBlockCandidate pipePassCandidate)
    {
        tailDirection = Vector2Int.zero;
        pipePassCandidate = default;
        pipeAreaBlockCandidateScratchB.Clear();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
            coordinate,
            previewToIgnore,
            pipeAreaBlockCandidateScratchB);

        for (int i = 0; i < pipeAreaBlockCandidateScratchB.Count; i++)
        {
            PipeAreaBlockCandidate candidate = pipeAreaBlockCandidateScratchB[i];
            if (!TryGetSteamGeneratorPipePassTailDirection(
                    coordinate,
                    candidate,
                    out Vector2Int candidateTailDirection))
            {
                continue;
            }

            tailDirection = candidateTailDirection;
            pipePassCandidate = candidate;
            pipeAreaBlockCandidateScratchB.Clear();
            return true;
        }

        pipeAreaBlockCandidateScratchB.Clear();
        return false;
    }

    private bool TryGetSteamGeneratorPipePassTailDirection(
        Vector2Int coordinate,
        PipeAreaBlockCandidate candidate,
        out Vector2Int tailDirection)
    {
        tailDirection = Vector2Int.zero;
        if (candidate.snapshot == null
            || !TryResolveSteamGenerator(candidate.snapshot.mapObject, out SteamGenerator steamGenerator)
            || !IsPipePassBlockType(candidate.blockType))
        {
            return false;
        }

        return steamGenerator.TryGetPipePassTailDirectionAtCoordinate(
            candidate.snapshot.mapObject,
            candidate.snapshot.anchorCoordinate,
            candidate.snapshot.quarterTurns,
            coordinate,
            out tailDirection);
    }

    private static bool IsPipePassBlockType(InputOutputModule.RectGridBlockType blockType)
    {
        return blockType == InputOutputModule.RectGridBlockType.PipeInput;
    }

    private bool TryGetPreviewPlacementSnapshot(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out PlacementSnapshot snapshot)
    {
        snapshot = null;
        if (!TryGetInstallPreviewAtCoordinate(coordinate, out MapObject preview)
            || preview == null
            || preview == previewToIgnore
            || !TryGetPreviewAnchorCoordinate(preview, out Vector2Int previewAnchorCoordinate))
        {
            return false;
        }

        snapshot = new PlacementSnapshot
        {
            mapObject = preview,
            rotation = preview.transform.rotation,
            anchorCoordinate = previewAnchorCoordinate,
            quarterTurns = GetPreviewAreaQuarterTurns(preview),
            storedFluidItemId = preview is InstallationObject previewInstallation
                ? previewInstallation.StoredFluidItemId
                : -1
        };
        return true;
    }

    private bool TryGetInstalledPlacementSnapshot(Vector2Int coordinate, out PlacementSnapshot snapshot)
    {
        snapshot = null;
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null
            || !terrain.TryGetLoadedBlock(coordinate, out Block block)
            || block == null
            || block.MapObject == null
            || !block.MapObject.gameObject.activeInHierarchy
            || !(block.MapObject is InstallationObject installationObject)
            || !installationObject.TryGetPlacementRuntime(
                out Vector2Int anchorCoordinate,
                out int quarterTurns))
        {
            return false;
        }

        snapshot = new PlacementSnapshot
        {
            mapObject = block.MapObject,
            rotation = block.MapObject.transform.rotation,
            anchorCoordinate = anchorCoordinate,
            quarterTurns = quarterTurns,
            storedFluidItemId = installationObject.StoredFluidItemId
        };
        return true;
    }

    private static bool TryGetRuntimeModulePlacementSnapshot(
        InputOutputModule module,
        out PlacementSnapshot snapshot)
    {
        snapshot = null;
        if (module == null
            || !module.gameObject.activeInHierarchy
            || !module.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out int quarterTurns))
        {
            return false;
        }

        snapshot = new PlacementSnapshot
        {
            mapObject = module,
            rotation = module.transform.rotation,
            anchorCoordinate = anchorCoordinate,
            quarterTurns = quarterTurns,
            storedFluidItemId = module.StoredFluidItemId
        };
        return true;
    }

    private bool TryGetRuntimeGridPlacementSnapshot(Vector2Int coordinate, out PlacementSnapshot snapshot)
    {
        snapshot = null;
        return InputOutputModule.TryGetModuleAtRuntimeGridCoordinate(coordinate, out InputOutputModule module)
               && TryGetRuntimeModulePlacementSnapshot(module, out snapshot);
    }

    private bool TryGetRuntimeAreaPlacementSnapshot(Vector2Int coordinate, out PlacementSnapshot snapshot)
    {
        snapshot = null;
        return InputOutputModule.TryGetModuleAtRuntimeAreaCoordinate(coordinate, out InputOutputModule module)
               && TryGetRuntimeModulePlacementSnapshot(module, out snapshot);
    }

    private bool TryGetSavedPlacementSnapshot(Vector2Int coordinate, out PlacementSnapshot snapshot)
    {
        snapshot = null;
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null
            || !terrain.TryGetInstallationStateAtCoordinate(
                coordinate,
                out BlockStateStore.InstallationSaveState savedState))
        {
            return false;
        }

        return TryCreateSavedPlacementSnapshot(savedState, out snapshot);
    }

    private bool TryCreateSavedPlacementSnapshot(
        BlockStateStore.InstallationSaveState savedState,
        out PlacementSnapshot snapshot)
    {
        snapshot = null;
        if (savedState == null
            || !TryGetInstallationDefinition(savedState, out ItemDefinition savedDefinition)
            || savedDefinition == null
            || savedDefinition.mapObject == null)
        {
            return false;
        }

        if (!TryResolveSavedInstallationSourceAndQuarterTurns(
                savedDefinition,
                savedState,
                out MapObject savedSourcePrefab,
                out int savedQuarterTurns))
        {
            return false;
        }

        snapshot = new PlacementSnapshot
        {
            mapObject = savedSourcePrefab,
            rotation = GetPlacementObjectRotation(savedSourcePrefab, savedQuarterTurns),
            anchorCoordinate = savedState.anchorCoordinate,
            quarterTurns = savedQuarterTurns,
            storedFluidItemId = savedState.storedFluidItemId
        };
        return true;
    }

    private bool TryGetSavedPipePlacementAtCoordinate(
        Vector2Int coordinate,
        out Pipe pipe,
        out Quaternion pipeRotation)
    {
        pipe = null;
        pipeRotation = Quaternion.identity;

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null
            || !terrain.TryGetSavedPipeInstallationStateAtCoordinate(
                coordinate,
                out BlockStateStore.InstallationSaveState savedState)
            || !TryCreateSavedPlacementSnapshot(savedState, out PlacementSnapshot snapshot)
            || !(snapshot.mapObject is Pipe savedPipe))
        {
            return false;
        }

        pipe = savedPipe;
        pipeRotation = snapshot.rotation;
        return true;
    }

    private bool TryAppendFixedFluidPipeConnectionDirections(
        PlacementSnapshot snapshot,
        Vector2Int coordinate,
        List<Vector2Int> directions)
    {
        if (snapshot?.mapObject is Pump)
        {
            return TryAppendPumpPipeOutputDirection(snapshot, coordinate, directions);
        }

        if (snapshot?.mapObject is Boiler
            && TryAppendBoilerPipeAxisDirections(snapshot, coordinate, directions))
        {
            return true;
        }

        return TryAppendRectGridPipeAreaConnectionDirection(snapshot, coordinate, directions);
    }

    private bool TryAppendPumpPipeOutputDirection(
        PlacementSnapshot snapshot,
        Vector2Int coordinate,
        List<Vector2Int> directions)
    {
        if (snapshot == null
            || !(snapshot.mapObject is Pump pump)
            || directions == null
            || !TryGetRectGridFootprintBlockType(
                snapshot.anchorCoordinate,
                snapshot.mapObject,
                snapshot.quarterTurns,
                coordinate,
                out InputOutputModule.RectGridBlockType blockType)
            || blockType != InputOutputModule.RectGridBlockType.PipeOutputItem)
        {
            return false;
        }

        if (TryGetInputOutputModule(snapshot.mapObject, out InputOutputModule inputOutputModule)
            && TryGetRectGridPipeAreaConnectionDirection(
                snapshot.mapObject,
                inputOutputModule,
                snapshot.anchorCoordinate,
                snapshot.quarterTurns,
                coordinate,
                out Vector2Int connectionDirection))
        {
            AddPipeDirection(directions, connectionDirection);
            return true;
        }

        if (pump.TryGetPipeConnectionDirection(snapshot.rotation, out Vector2Int pumpOutputDirection)
            && pumpOutputDirection != Vector2Int.zero)
        {
            AddPipeDirection(directions, -pumpOutputDirection);
            return true;
        }

        return false;
    }

    private bool TryAppendBoilerPipeAxisDirections(
        PlacementSnapshot snapshot,
        Vector2Int coordinate,
        List<Vector2Int> directions)
    {
        if (snapshot == null || !(snapshot.mapObject is Boiler boiler))
        {
            return false;
        }

        return TryAppendBoilerPipeAxisDirectionsAtCoordinate(
            boiler,
            snapshot.anchorCoordinate,
            snapshot.quarterTurns,
            coordinate,
            directions);
    }

    private bool TryAppendRectGridPipeAreaConnectionDirection(
        PlacementSnapshot snapshot,
        Vector2Int coordinate,
        List<Vector2Int> directions)
    {
        if (snapshot == null
            || snapshot.mapObject == null
            || directions == null
            || !TryGetInputOutputModule(snapshot.mapObject, out InputOutputModule inputOutputModule)
            || !TryGetRectGridFootprintBlockType(
                snapshot.anchorCoordinate,
                snapshot.mapObject,
                snapshot.quarterTurns,
                coordinate,
                out InputOutputModule.RectGridBlockType blockType)
            || !InputOutputModule.AllowsPipeAreaInteraction(blockType)
            || !TryGetRectGridPipeAreaConnectionDirection(
                snapshot.mapObject,
                inputOutputModule,
                snapshot.anchorCoordinate,
                snapshot.quarterTurns,
                coordinate,
                out Vector2Int connectionDirection))
        {
            return false;
        }

        AddPipeDirection(directions, connectionDirection);
        return true;
    }

    private bool TryGetRectGridPipeAreaConnectionDirection(
        MapObject footprintSource,
        InputOutputModule inputOutputModule,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        Vector2Int coordinate,
        out Vector2Int direction)
    {
        direction = Vector2Int.zero;
        if (TryResolveSteamGenerator(footprintSource, out SteamGenerator steamGenerator)
            && TryGetRectGridFootprintBlockType(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                coordinate,
                out InputOutputModule.RectGridBlockType blockType)
            && InputOutputModule.IsInputItemBlockType(blockType))
        {
            if (steamGenerator.TryGetInputDirectionAtCoordinate(
                    footprintSource,
                    anchorCoordinate,
                    quarterTurns,
                    coordinate,
                    out direction)
                && direction != Vector2Int.zero)
            {
                return true;
            }

            return steamGenerator.TryGetPipeAreaConnectionDirection(
                    GetPlacementObjectRotation(footprintSource, quarterTurns),
                    out direction)
                && direction != Vector2Int.zero;
        }

        return TryGetNearestRectGridObjectDirection(
            inputOutputModule,
            footprintSource,
            anchorCoordinate,
            quarterTurns,
            coordinate,
            out direction);
    }

    private bool TryGetNearestRectGridObjectDirection(
        InputOutputModule inputOutputModule,
        MapObject footprintSource,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        Vector2Int coordinate,
        out Vector2Int direction)
    {
        direction = Vector2Int.zero;
        return inputOutputModule != null
               && inputOutputModule.TryGetNearestRectGridObjectDirection(
                   footprintSource,
                   anchorCoordinate,
                   quarterTurns,
                   coordinate,
                   out direction);
    }

    private static bool TryGetDominantCardinalDirection(Vector2Int offset, out Vector2Int direction)
    {
        return InputOutputModule.TryGetDominantCardinalDirection(offset, out direction);
    }

    private bool TryGetInstalledPipeVariantPreview(
        Pipe installedPipe,
        out Pipe previewPipe,
        out Quaternion previewRotation)
    {
        previewPipe = null;
        previewRotation = Quaternion.identity;
        if (installedPipe == null)
        {
            return false;
        }

        if (isResolvingInstalledPipeVariantPreviewPlans)
        {
            if (installedPipeVariantResolutionOverrides.TryGetValue(
                    installedPipe,
                    out InstalledPipeVariantPreviewPlan resolutionOverride)
                && resolutionOverride.sourcePrefab is Pipe resolvedPipe)
            {
                previewPipe = resolvedPipe;
                previewRotation = resolutionOverride.rotation;
                return true;
            }

            return false;
        }

        if (!installedPipeVariantPreviews.TryGetValue(installedPipe, out MapObject preview)
            || !(preview is Pipe pipePreview)
            || !pipePreview.gameObject.activeInHierarchy)
        {
            return false;
        }

        previewPipe = pipePreview;
        previewRotation = pipePreview.transform.rotation;
        return true;
    }

    private bool ShouldPipeNeighborContributeToVariant(
        Vector2Int coordinate,
        Pipe neighborPipe,
        Quaternion neighborRotation,
        Vector2Int directionToCandidate,
        bool allowPotentialConnections)
    {
        if (neighborPipe == null || directionToCandidate == Vector2Int.zero)
        {
            return false;
        }

        if (TryGetManualPipeConnectionMask(
                neighborPipe,
                coordinate,
                out int selectedConnectionMask))
        {
            return PipeConnectionMaskContainsDirection(
                selectedConnectionMask,
                directionToCandidate);
        }

        if (HasEffectivePipeConnectionTowardsAt(
                coordinate,
                neighborPipe,
                neighborRotation,
                directionToCandidate))
        {
            return true;
        }

        return !(neighborPipe is UndergroundPipe)
               && allowPotentialConnections
               && CanPipePotentiallyConnectTowards(neighborPipe, neighborRotation, directionToCandidate);
    }

    private static bool CanPipePotentiallyConnectTowards(
        Pipe pipe,
        Quaternion baseRotation,
        Vector2Int direction)
    {
        if (pipe == null || direction == Vector2Int.zero)
        {
            return false;
        }

        for (int offset = 1; offset < 4; offset++)
        {
            Quaternion candidateRotation = baseRotation * Quaternion.Euler(0f, offset * 90f, 0f);
            if (pipe.HasConnectionTowards(candidateRotation, direction))
            {
                return true;
            }
        }

        return false;
    }

    private bool TryGetInstalledFenceVariantPreview(
        Wall installedFence,
        out Wall previewFence,
        out Quaternion previewRotation)
    {
        previewFence = null;
        previewRotation = Quaternion.identity;
        if (installedFence == null
            || !installedFenceVariantPreviews.TryGetValue(installedFence, out MapObject preview)
            || !(preview is Wall wallPreview)
            || !wallPreview.gameObject.activeInHierarchy)
        {
            return false;
        }

        previewFence = wallPreview;
        previewRotation = wallPreview.transform.rotation;
        return true;
    }

    private bool TryGetSavedInstallationPlacementAtCoordinate(
        Vector2Int coordinate,
        out MapObject sourcePrefab,
        out Quaternion rotation,
        out BlockStateStore.InstallationSaveState savedState)
    {
        sourcePrefab = null;
        rotation = Quaternion.identity;
        savedState = null;

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null
            || !terrain.TryGetInstallationStateAtCoordinate(coordinate, out savedState)
            || savedState == null
            || !TryGetInstallationDefinition(savedState, out ItemDefinition savedDefinition)
            || savedDefinition == null
            || savedDefinition.mapObject == null)
        {
            return false;
        }

        if (!TryResolveSavedInstallationSourceAndQuarterTurns(
                savedDefinition,
                savedState,
                out sourcePrefab,
                out int savedQuarterTurns))
        {
            return false;
        }

        rotation = GetPlacementObjectRotation(sourcePrefab, savedQuarterTurns);
        return true;
    }

    private bool TryResolveSavedInstallationSourceAndQuarterTurns(
        ItemDefinition savedDefinition,
        BlockStateStore.InstallationSaveState savedState,
        out MapObject sourcePrefab,
        out int quarterTurns)
    {
        sourcePrefab = null;
        quarterTurns = savedState != null
            ? NormalizePlacementQuarterTurns(savedState.quarterTurns)
            : 0;
        if (savedDefinition == null || savedDefinition.mapObject == null || savedState == null)
        {
            return false;
        }

        sourcePrefab = ResolveSavedInstallationSourcePrefab(savedDefinition, savedState)
                       ?? savedDefinition.mapObject;
        if (!(savedDefinition.mapObject is Pipe pipePrototype)
            || savedState.pipeConnectionMask < 0)
        {
            return sourcePrefab != null;
        }

        // Legacy or partially written saves can disagree on variant kind and mask.
        // The mask is the exact persisted topology, so recover the matching variant
        // instead of walking the unloaded network with a fabricated rotation.
        if (TryResolvePipePlacementFromConnectionMask(
                pipePrototype,
                sourcePrefab as Pipe,
                savedState.pipeConnectionMask,
                quarterTurns,
                out Pipe resolvedPipe,
                out int maskQuarterTurns))
        {
            sourcePrefab = resolvedPipe;
            quarterTurns = maskQuarterTurns;
            return true;
        }

        return false;
    }

    private static MapObject ResolveSavedInstallationSourcePrefab(
        ItemDefinition savedDefinition,
        BlockStateStore.InstallationSaveState savedState)
    {
        if (savedDefinition == null || savedDefinition.mapObject == null || savedState == null)
        {
            return null;
        }

        if (savedDefinition.mapObject is Wall fencePrototype && savedState.conveyorVariantKind >= 0)
        {
            return ResolveFenceVariantPrefab(fencePrototype, savedState.conveyorVariantKind);
        }

        if (savedDefinition.mapObject is Pipe pipePrototype && savedState.conveyorVariantKind >= 0)
        {
            return ResolvePipeVariantPrefab(pipePrototype, savedState.conveyorVariantKind);
        }

        if (!IsBelt2F(savedDefinition.mapObject)
            && savedDefinition.mapObject is ConveyorBelt conveyorPrototype
            && savedState.conveyorVariantKind >= 0)
        {
            return ResolveConveyorVariantPrefab(conveyorPrototype, savedState.conveyorVariantKind);
        }

        return savedDefinition.mapObject;
    }

    private static bool DirectionsArePerpendicular(Vector2Int firstDirection, Vector2Int secondDirection)
    {
        return firstDirection != Vector2Int.zero
               && secondDirection != Vector2Int.zero
               && firstDirection != secondDirection
               && firstDirection != -secondDirection
               && ((firstDirection.x * secondDirection.x) + (firstDirection.y * secondDirection.y)) == 0;
    }

