    private Quaternion GetPlacementObjectRotation(MapObject sourcePrefab, int quarterTurns)
    {
        if (sourcePrefab == null)
        {
            return Quaternion.identity;
        }

        return GetPlacementObjectRotation(sourcePrefab.transform.rotation, sourcePrefab, quarterTurns);
    }

    private Quaternion GetPlacementObjectRotation(Quaternion baseRotation, MapObject sourcePrefab, int quarterTurns)
    {
        if (sourcePrefab == null)
        {
            return baseRotation;
        }

        int normalizedQuarterTurns = NormalizePlacementQuarterTurnsForObject(sourcePrefab, quarterTurns);
        int rotationQuarterTurns = normalizedQuarterTurns;
        if (sourcePrefab is ConveyorBelt conveyorBelt)
        {
            rotationQuarterTurns = (rotationQuarterTurns + conveyorBelt.PlacementRotationQuarterTurnOffset) % 4;
        }

        Quaternion rotation = baseRotation * Quaternion.Euler(0f, rotationQuarterTurns * 90f, 0f);
        return rotation;
    }

    private Quaternion ResolvePlacementObjectRotation(
        MapObject sourcePrefab,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        Vector3? railReferenceWorldPosition = null)
    {
        return TryResolveRailAlignedPlacementRotation(
            sourcePrefab,
            anchorCoordinate,
            quarterTurns,
            railReferenceWorldPosition,
            out Quaternion railAlignedRotation)
            ? railAlignedRotation
            : GetPlacementObjectRotation(sourcePrefab, quarterTurns);
    }

    private Quaternion ResolvePlacementObjectRotation(
        Quaternion baseRotation,
        MapObject sourcePrefab,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        Vector3? railReferenceWorldPosition = null)
    {
        return TryResolveRailAlignedPlacementRotation(
            baseRotation,
            sourcePrefab,
            anchorCoordinate,
            quarterTurns,
            railReferenceWorldPosition,
            out Quaternion railAlignedRotation)
            ? railAlignedRotation
            : GetPlacementObjectRotation(baseRotation, sourcePrefab, quarterTurns);
    }

    private bool TryResolveRailAlignedPlacementRotation(
        MapObject sourcePrefab,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        Vector3? railReferenceWorldPosition,
        out Quaternion rotation)
    {
        Quaternion baseRotation = sourcePrefab != null
            ? sourcePrefab.transform.rotation
            : Quaternion.identity;
        return TryResolveRailAlignedPlacementRotation(
            baseRotation,
            sourcePrefab,
            anchorCoordinate,
            quarterTurns,
            railReferenceWorldPosition,
            out rotation);
    }

    private bool TryResolveRailAlignedPlacementRotation(
        Quaternion baseRotation,
        MapObject sourcePrefab,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        Vector3? railReferenceWorldPosition,
        out Quaternion rotation)
    {
        rotation = Quaternion.identity;
        Vector2 positionOffset = GetPlacementWorldPositionOffset(sourcePrefab, quarterTurns);
        Vector2 referencePoint = railReferenceWorldPosition.HasValue
            ? new Vector2(railReferenceWorldPosition.Value.x, railReferenceWorldPosition.Value.z)
            : new Vector2(
                anchorCoordinate.x + positionOffset.x,
                anchorCoordinate.y + positionOffset.y);
        Vector3 referencePosition = railReferenceWorldPosition
                                    ?? new Vector3(referencePoint.x, 0f, referencePoint.y);
        if (IsTrainSource(sourcePrefab)
            && TryResolveTrainRailPlacementPose(
                sourcePrefab,
                anchorCoordinate,
                quarterTurns,
                referencePosition,
                out _,
                out rotation))
        {
            return true;
        }

        if (!IsTrainSource(sourcePrefab)
            || !TryFindNearestRailPathAtCoordinate(
                anchorCoordinate,
                referencePoint,
                out _,
                out _,
                out Vector2 railTangent,
                out float railSqrDistance)
            || railSqrDistance > ResolveRailAlignedPlacementMaxSqrDistance())
        {
            return false;
        }

        if (railTangent.sqrMagnitude <= 0.0001f)
        {
            return false;
        }

        Vector3 railForward = new Vector3(railTangent.x, 0f, railTangent.y);
        railForward = FlattenHorizontalDirection(railForward);
        if (railForward.sqrMagnitude <= 0.0001f)
        {
            return false;
        }

        Quaternion preferredRotation = GetPlacementObjectRotation(baseRotation, sourcePrefab, quarterTurns);
        Vector3 preferredForward = FlattenHorizontalDirection(preferredRotation * Vector3.forward);
        if (preferredForward.sqrMagnitude > 0.0001f
            && Vector3.Dot(railForward, preferredForward) < 0f)
        {
            railForward = -railForward;
        }

        rotation = AlignBaseRotationForwardToDirection(baseRotation, railForward);
        return true;
    }

    private bool TryFindNearestRailPathAtCoordinate(
        Vector2Int coordinate,
        Vector2 referencePoint,
        out Railload railload,
        out Vector2 pathPoint,
        out Vector2 tangent,
        out float sqrDistance)
    {
        railload = null;
        pathPoint = referencePoint;
        tangent = Vector2.zero;
        sqrDistance = float.MaxValue;
        bool found = false;

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain != null
            && terrain.TryGetLoadedBlock(coordinate, out Block block)
            && block != null
            && block.MapObject is Railload blockRailload)
        {
            found |= TryUpdateNearestRailPath(
                blockRailload,
                referencePoint,
                ref railload,
                ref pathPoint,
                ref tangent,
                ref sqrDistance);
        }

        railAlignmentInstallationScratch.Clear();
        InstallationObject.CollectActiveInstallationsAtRuntimeGridCoordinate(
            coordinate,
            railAlignmentInstallationScratch);
        for (int i = 0; i < railAlignmentInstallationScratch.Count; i++)
        {
            if (railAlignmentInstallationScratch[i] is Railload runtimeRailload)
            {
                found |= TryUpdateNearestRailPath(
                    runtimeRailload,
                    referencePoint,
                    ref railload,
                    ref pathPoint,
                    ref tangent,
                    ref sqrDistance);
            }
        }

        railAlignmentInstallationScratch.Clear();
        return found;
    }

    private bool TryFindNearestTrainPlacementRailSampleAroundCoordinate(
        Vector2Int centerCoordinate,
        Vector2 referencePoint,
        int searchCells,
        out TrainPlacementRailSample nearestSample)
    {
        nearestSample = default;
        nearestSample.SqrDistance = float.MaxValue;
        bool found = false;
        int clampedSearchCells = Mathf.Max(0, searchCells);

        for (int offsetY = -clampedSearchCells; offsetY <= clampedSearchCells; offsetY++)
        {
            for (int offsetX = -clampedSearchCells; offsetX <= clampedSearchCells; offsetX++)
            {
                Vector2Int coordinate = centerCoordinate + new Vector2Int(offsetX, offsetY);
                found |= TryFindNearestTrainPlacementRailSampleAtCoordinate(
                    coordinate,
                    referencePoint,
                    ref nearestSample);
            }
        }

        trainPlacementRailSearchScratch.Clear();
        return found;
    }

    private bool TryFindNearestTrainPlacementRailSampleAtCoordinate(
        Vector2Int coordinate,
        Vector2 referencePoint,
        ref TrainPlacementRailSample nearestSample)
    {
        bool found = false;
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain != null
            && terrain.TryGetLoadedBlock(coordinate, out Block block)
            && block != null
            && block.MapObject is Railload blockRailload)
        {
            found |= TryUpdateNearestTrainPlacementRailSample(
                blockRailload,
                referencePoint,
                ref nearestSample);
        }

        trainPlacementRailSearchScratch.Clear();
        InstallationObject.CollectActiveInstallationsAtRuntimeGridCoordinate(
            coordinate,
            trainPlacementRailSearchScratch);
        for (int i = 0; i < trainPlacementRailSearchScratch.Count; i++)
        {
            if (trainPlacementRailSearchScratch[i] is Railload runtimeRailload)
            {
                found |= TryUpdateNearestTrainPlacementRailSample(
                    runtimeRailload,
                    referencePoint,
                    ref nearestSample);
            }
        }

        trainPlacementRailSearchScratch.Clear();
        return found;
    }

    private static bool TryUpdateNearestTrainPlacementRailSample(
        Railload candidate,
        Vector2 referencePoint,
        ref TrainPlacementRailSample nearestSample)
    {
        if (candidate == null
            || !candidate.TryFindNearestRenderedPathSample(
                referencePoint,
                out float distanceAlongPath,
                out Vector2 pathPoint,
                out Vector2 tangent,
                out float sqrDistance))
        {
            return false;
        }

        if (sqrDistance < nearestSample.SqrDistance)
        {
            nearestSample.Rail = candidate;
            nearestSample.DistanceAlongPath = distanceAlongPath;
            nearestSample.Point = pathPoint;
            nearestSample.Tangent = tangent;
            nearestSample.SqrDistance = sqrDistance;
        }

        return true;
    }

    private static Vector2 ResolveTrainPlacementFacingTangent(Vector2 railTangent, Vector2 referenceFacing)
    {
        if (railTangent.sqrMagnitude <= 0.0001f)
        {
            return referenceFacing.sqrMagnitude > 0.0001f
                ? referenceFacing.normalized
                : Vector2.up;
        }

        railTangent.Normalize();
        if (referenceFacing.sqrMagnitude > 0.0001f
            && Vector2.Dot(railTangent, referenceFacing.normalized) < 0f)
        {
            railTangent = -railTangent;
        }

        return railTangent;
    }

    public void InitializePlacedTrainRailSample(MapObject installedObject, Vector2Int anchorCoordinate)
    {
        InitializePlacedTrainRailSample(installedObject, anchorCoordinate, null);
        ConnectHandcartToNearbyHandcarts(installedObject as Handcart);
    }

    public bool TryRestorePlacedTrainRailSample(
        MapObject installedObject,
        BlockStateStore.InstallationSaveState savedState)
    {
        if (!(installedObject is Train train)
            || savedState == null
            || !savedState.hasTrainRailSample
            || !TryFindSavedTrainRailSample(savedState, out TrainPlacementRailSample railSample))
        {
            return false;
        }

        Vector2 referenceFacing = savedState.trainRailFacingTangent;
        if (referenceFacing.sqrMagnitude <= 0.0001f)
        {
            Vector3 fallbackForward = savedState.hasWorldPose
                ? savedState.worldRotation * Vector3.forward
                : train.transform.forward;
            referenceFacing = new Vector2(fallbackForward.x, fallbackForward.z);
        }

        Vector2 facing = ResolveTrainPlacementFacingTangent(railSample.Tangent, referenceFacing);
        if (facing.sqrMagnitude <= 0.0001f)
        {
            return false;
        }

        if (train is RailHandcar railHandcar)
        {
            railHandcar.ResetRailPlacementState();
        }

        train.ApplyPlacedRailSample(
            railSample.Rail,
            railSample.DistanceAlongPath,
            railSample.Point,
            facing);
        ConnectTrainToNearbyTrains(train);
        return true;
    }

    private bool TryFindSavedTrainRailSample(
        BlockStateStore.InstallationSaveState savedState,
        out TrainPlacementRailSample railSample)
    {
        railSample = default;
        railSample.SqrDistance = float.MaxValue;
        if (savedState == null || !savedState.hasTrainRailSample)
        {
            return false;
        }

        if (TryFindSavedTrainRail(savedState, out Railload rail)
            && rail.TrySampleRenderedPath(
                Mathf.Max(0f, savedState.trainRailDistanceAlongPath),
                out Vector2 pathPoint,
                out Vector2 tangent))
        {
            railSample.Rail = rail;
            railSample.DistanceAlongPath = Mathf.Max(0f, savedState.trainRailDistanceAlongPath);
            railSample.Point = pathPoint;
            railSample.Tangent = tangent;
            railSample.SqrDistance = (pathPoint - savedState.trainRailPathPoint).sqrMagnitude;
            return true;
        }

        Vector2 referencePoint = savedState.trainRailPathPoint;
        if (referencePoint.sqrMagnitude <= 0.0001f && savedState.hasWorldPose)
        {
            referencePoint = new Vector2(savedState.worldPosition.x, savedState.worldPosition.z);
        }

        Vector2Int searchCoordinate = new Vector2Int(
            Mathf.RoundToInt(referencePoint.x),
            Mathf.RoundToInt(referencePoint.y));
        int searchCells = Mathf.CeilToInt(Mathf.Max(1f, TrainPlacementRailSearchRadius));
        return TryFindNearestTrainPlacementRailSampleAroundCoordinate(
            searchCoordinate,
            referencePoint,
            searchCells,
            out railSample);
    }

    private bool TryFindSavedTrainRail(
        BlockStateStore.InstallationSaveState savedState,
        out Railload rail)
    {
        rail = null;
        if (savedState == null)
        {
            return false;
        }

        long placementSequence = savedState.trainRailPlacementSequence;
        if (placementSequence > 0)
        {
            Railload[] activeRails = FindObjectsOfType<Railload>(false);
            for (int i = 0; i < activeRails.Length; i++)
            {
                Railload candidate = activeRails[i];
                if (candidate != null
                    && candidate.RuntimePlacementSequence == placementSequence)
                {
                    rail = candidate;
                    return true;
                }
            }
        }

        trainPlacementRailSearchScratch.Clear();
        InstallationObject.CollectActiveInstallationsAtRuntimeGridCoordinate(
            savedState.trainRailAnchorCoordinate,
            trainPlacementRailSearchScratch);
        for (int i = 0; i < trainPlacementRailSearchScratch.Count; i++)
        {
            if (trainPlacementRailSearchScratch[i] is not Railload candidate)
            {
                continue;
            }

            if (placementSequence <= 0 || candidate.RuntimePlacementSequence == placementSequence)
            {
                rail = candidate;
                trainPlacementRailSearchScratch.Clear();
                return true;
            }

            rail ??= candidate;
        }

        trainPlacementRailSearchScratch.Clear();
        return rail != null;
    }

    private void InitializePlacedTrainRailSample(
        MapObject installedObject,
        Vector2Int anchorCoordinate,
        InstallPreviewPlacementPlan placementPlan)
    {
        if (!(installedObject is Train train))
        {
            return;
        }

        TrainPlacementRailSample railSample;
        if (placementPlan != null && placementPlan.hasTrainRailSample)
        {
            railSample = placementPlan.trainRailSample;
        }
        else
        {
            Vector2 trainPoint = new Vector2(
                train.transform.position.x,
                train.transform.position.z);
            int searchCells = Mathf.CeilToInt(
                Mathf.Max(1f, TrainPlacementRailSearchRadius));
            if (!TryFindNearestTrainPlacementRailSampleAroundCoordinate(
                    anchorCoordinate,
                    trainPoint,
                    searchCells,
                    out railSample))
            {
                return;
            }
        }

        float maxRailDistance = RailAlignedPlacementMaxDistance;
        if (railSample.SqrDistance > maxRailDistance * maxRailDistance)
        {
            return;
        }

        Vector2 facing = new Vector2(
            train.transform.forward.x,
            train.transform.forward.z);
        facing = ResolveTrainPlacementFacingTangent(railSample.Tangent, facing);
        if (facing.sqrMagnitude <= 0.0001f)
        {
            return;
        }

        if (train is RailHandcar railHandcar)
        {
            railHandcar.ResetRailPlacementState();
        }

        train.ApplyPlacedRailSample(
            railSample.Rail,
            railSample.DistanceAlongPath,
            railSample.Point,
            facing);
        ConnectTrainToNearbyTrains(train);
    }

    private void ConnectTrainToNearbyTrains(Train train)
    {
        if (train == null || !train.TryGetPlacementRuntime(out _, out _))
        {
            return;
        }

        trainConnectionInstalledScratch.Clear();
        Train.CollectActiveRuntimeTrains(trainConnectionInstalledScratch);
        for (int i = 0; i < trainConnectionInstalledScratch.Count; i++)
        {
            Train otherTrain = trainConnectionInstalledScratch[i];
            if (otherTrain == null || otherTrain == train)
            {
                continue;
            }

            train.ConnectTo(otherTrain);
        }

        trainConnectionInstalledScratch.Clear();
    }

    private void RefreshHandcartInstallPreviewConnectionPoses()
    {
        ClearHandcartConnectionPreviewHandleOverrides();
        if (installPreviewInstances.Count <= 0)
        {
            return;
        }

        bool hasHandcartPreview = false;
        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            if (installPreviewInstances[i] is Handcart)
            {
                hasHandcartPreview = true;
                break;
            }
        }

        if (!hasHandcartPreview)
        {
            return;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return;
        }

        handcartConnectionInstalledScratch.Clear();
        Handcart.CollectActiveRuntimeHandcarts(handcartConnectionInstalledScratch);

        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            if (!(installPreviewInstances[i] is Handcart previewHandcart))
            {
                continue;
            }

            previewHandcart.RefreshConnectionHandleObject();
            if (!TryResolveHandcartPreviewGridPose(
                    previewHandcart,
                    terrain,
                    out _,
                    out Vector3 gridPosition,
                    out Quaternion gridRotation))
            {
                continue;
            }

            previewHandcart.transform.SetPositionAndRotation(gridPosition, gridRotation);
        }

        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            if (!(installPreviewInstances[i] is Handcart previewHandcart)
                || !TryResolveHandcartPreviewGridPose(
                    previewHandcart,
                    terrain,
                    out Vector2Int anchorCoordinate,
                    out Vector3 gridPosition,
                    out Quaternion gridRotation))
            {
                continue;
            }

            bool foundConnection = false;
            float bestDistanceSqr = float.MaxValue;
            Vector3 snappedPosition = gridPosition;
            Quaternion snappedRotation = gridRotation;
            Handcart bestConnectionSource = null;
            int bestConnectionSourceSide = 0;
            for (int sourceIndex = 0; sourceIndex < handcartConnectionInstalledScratch.Count; sourceIndex++)
            {
                TryUseHandcartPreviewConnectionSource(
                    previewHandcart,
                    handcartConnectionInstalledScratch[sourceIndex],
                    anchorCoordinate,
                    gridPosition,
                    ref foundConnection,
                    ref bestDistanceSqr,
                    ref snappedPosition,
                    ref snappedRotation,
                    ref bestConnectionSource,
                    ref bestConnectionSourceSide);
            }

            long previewSequence = installPreviewPlacementSequencesByPreview.TryGetValue(
                previewHandcart,
                out long storedPreviewSequence)
                ? storedPreviewSequence
                : long.MaxValue;
            for (int sourceIndex = 0; sourceIndex < installPreviewInstances.Count; sourceIndex++)
            {
                if (!(installPreviewInstances[sourceIndex] is Handcart previewSource)
                    || previewSource == previewHandcart
                    || !installPreviewPlacementSequencesByPreview.TryGetValue(
                        previewSource,
                        out long sourceSequence)
                    || sourceSequence >= previewSequence
                    || !TryGetPreviewAnchorCoordinate(previewSource, out _))
                {
                    continue;
                }

                TryUseHandcartPreviewConnectionSource(
                    previewHandcart,
                    previewSource,
                    anchorCoordinate,
                    gridPosition,
                    ref foundConnection,
                    ref bestDistanceSqr,
                    ref snappedPosition,
                    ref snappedRotation,
                    ref bestConnectionSource,
                    ref bestConnectionSourceSide);
            }

            previewHandcart.transform.SetPositionAndRotation(snappedPosition, snappedRotation);
            if (foundConnection)
            {
                ApplyHandcartConnectionPreviewSide(bestConnectionSource, bestConnectionSourceSide);
                ApplyHandcartConnectionPreviewSide(previewHandcart, -bestConnectionSourceSide);
            }
            previewHandcart.RefreshInstalledDirectionFromCurrentTransform();
        }

        handcartConnectionInstalledScratch.Clear();
    }

    private bool TryResolveHandcartPreviewGridPose(
        Handcart preview,
        TerrainGenerator terrain,
        out Vector2Int anchorCoordinate,
        out Vector3 gridPosition,
        out Quaternion gridRotation)
    {
        anchorCoordinate = Vector2Int.zero;
        gridPosition = default;
        gridRotation = Quaternion.identity;
        if (preview == null
            || terrain == null
            || !TryGetPreviewAnchorCoordinate(preview, out anchorCoordinate)
            || !terrain.TryGetLoadedBlock(anchorCoordinate, out Block anchorBlock)
            || anchorBlock == null)
        {
            return false;
        }

        MapObject placementSource = ResolveInstallPreviewPlacementSource(preview) ?? preview;
        MapObject rotationSource = ResolveInstallPreviewRotationSource(preview) ?? placementSource;
        int quarterTurns = GetPreviewQuarterTurns(preview);
        Quaternion baseRotation = installPreviewBaseRotationsByPreview.TryGetValue(
            preview,
            out Quaternion storedBaseRotation)
            ? storedBaseRotation
            : rotationSource.transform.rotation;
        gridPosition = ResolvePlacementWorldPosition(
            anchorBlock,
            placementSource,
            quarterTurns,
            preview.transform.position);
        gridRotation = GetPlacementObjectRotation(baseRotation, rotationSource, quarterTurns);
        return true;
    }

    private static void TryUseHandcartPreviewConnectionSource(
        Handcart preview,
        Handcart connectionSource,
        Vector2Int anchorCoordinate,
        Vector3 gridPosition,
        ref bool foundConnection,
        ref float bestDistanceSqr,
        ref Vector3 bestPosition,
        ref Quaternion bestRotation,
        ref Handcart bestConnectionSource,
        ref int bestConnectionSourceSide)
    {
        if (connectionSource == null
            || connectionSource == preview
            || !Handcart.TryResolveConnectionPreviewPose(
                preview,
                connectionSource,
                gridPosition,
                out int candidateSourceSide,
                out Vector3 candidatePosition,
                out Quaternion candidateRotation)
            || RoundWorldPositionToCoordinate(candidatePosition) != anchorCoordinate)
        {
            return;
        }

        float distanceSqr = (candidatePosition - gridPosition).sqrMagnitude;
        if (distanceSqr >= bestDistanceSqr)
        {
            return;
        }

        foundConnection = true;
        bestDistanceSqr = distanceSqr;
        bestPosition = candidatePosition;
        bestRotation = candidateRotation;
        bestConnectionSource = connectionSource;
        bestConnectionSourceSide = candidateSourceSide;
    }

    private void ApplyHandcartConnectionPreviewSide(Handcart handcart, int connectionSide)
    {
        if (handcart != null && handcart.ApplyConnectionPreviewSide(connectionSide))
        {
            handcartConnectionPreviewHandleOverrides.Add(handcart);
        }
    }

    private void ClearHandcartConnectionPreviewHandleOverrides()
    {
        foreach (Handcart handcart in handcartConnectionPreviewHandleOverrides)
        {
            handcart?.ClearConnectionPreviewHandleOverride();
        }

        handcartConnectionPreviewHandleOverrides.Clear();
    }

    private void ConnectHandcartToNearbyHandcarts(Handcart handcart)
    {
        handcart?.ConnectToNearbyActiveHandcarts();
    }

    private static void ApplyTrainPlacementPose(Train train, Vector3 position, Quaternion rotation)
    {
        if (train == null)
        {
            return;
        }

        Rigidbody trainRigidbody = train.GetComponent<Rigidbody>();
        if (trainRigidbody != null)
        {
            trainRigidbody.position = position;
            trainRigidbody.rotation = rotation;
            trainRigidbody.linearVelocity = Vector3.zero;
            trainRigidbody.angularVelocity = Vector3.zero;
        }

        train.transform.SetPositionAndRotation(position, rotation);
        Physics.SyncTransforms();
    }

    private bool CanPlaceTrainAtPose(
        MapObject sourcePrefab,
        Vector3 position,
        Quaternion rotation,
        MapObject previewToIgnore)
    {
        if (!IsTrainSource(sourcePrefab))
        {
            return true;
        }

        BuildTrainCollisionBoxes(sourcePrefab, position, rotation, trainPlacementCollisionBoxes);
        if (trainPlacementCollisionBoxes.Count <= 0)
        {
            return true;
        }

        Train[] activeTrains = FindObjectsOfType<Train>(false);
        for (int i = 0; i < activeTrains.Length; i++)
        {
            Train train = activeTrains[i];
            if (train == null
                || train == previewToIgnore
                || !train.gameObject.activeInHierarchy
                || !train.TryGetPlacementRuntime(out _, out _)
                || !TrainCollisionBoxesOverlapWith(
                    trainPlacementCollisionBoxes,
                    train,
                    train.transform.position,
                    train.transform.rotation))
            {
                continue;
            }

            trainPlacementOtherCollisionBoxes.Clear();
            return false;
        }

        CleanupInstallPreviewReferences();
        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            MapObject otherPreview = installPreviewInstances[i];
            MapObject otherPreviewSource = otherPreview != null
                ? ResolveInstallPreviewPlacementSource(otherPreview)
                : null;
            Train otherPreviewTrain = ResolveTrainSource(otherPreviewSource) ?? ResolveTrainSource(otherPreview);
            if (otherPreview == null
                || otherPreview == previewToIgnore
                || !otherPreview.gameObject.activeInHierarchy
                || otherPreviewTrain == null
                || !TrainCollisionBoxesOverlapWith(
                    trainPlacementCollisionBoxes,
                    otherPreviewSource ?? otherPreview,
                    otherPreview.transform.position,
                    otherPreview.transform.rotation))
            {
                continue;
            }

            trainPlacementOtherCollisionBoxes.Clear();
            return false;
        }

        trainPlacementOtherCollisionBoxes.Clear();
        return true;
    }

    private bool TrainCollisionBoxesOverlapWith(
        IReadOnlyList<TrainCollisionBox2D> candidateBoxes,
        MapObject otherSource,
        Vector3 otherPosition,
        Quaternion otherRotation)
    {
        if (otherSource == null)
        {
            return false;
        }

        BuildTrainCollisionBoxes(
            otherSource,
            otherPosition,
            otherRotation,
            trainPlacementOtherCollisionBoxes);
        for (int candidateIndex = 0; candidateIndex < candidateBoxes.Count; candidateIndex++)
        {
            TrainCollisionBox2D candidateBox = candidateBoxes[candidateIndex];
            for (int otherIndex = 0; otherIndex < trainPlacementOtherCollisionBoxes.Count; otherIndex++)
            {
                TrainCollisionBox2D otherBox = trainPlacementOtherCollisionBoxes[otherIndex];
                if (TrainCollisionBoxesOverlap(candidateBox, otherBox, out _))
                {
                    return true;
                }
            }
        }

        return false;
    }

    private static void BuildTrainCollisionBoxes(
        MapObject source,
        Vector3 position,
        Quaternion rotation,
        List<TrainCollisionBox2D> boxes)
    {
        if (boxes == null)
        {
            return;
        }

        boxes.Clear();
        if (source == null)
        {
            return;
        }

        Transform root = source.transform;
        BoxCollider[] colliders = source.GetComponentsInChildren<BoxCollider>(true);
        for (int i = 0; i < colliders.Length; i++)
        {
            BoxCollider boxCollider = colliders[i];
            if (boxCollider == null || !boxCollider.enabled)
            {
                continue;
            }

            Transform colliderTransform = boxCollider.transform;
            Vector3 localCenter = root.InverseTransformPoint(colliderTransform.TransformPoint(boxCollider.center));
            Quaternion localRotation = Quaternion.Inverse(root.rotation) * colliderTransform.rotation;
            Vector3 relativeScale = ResolveRelativeLossyScale(colliderTransform, root);
            Vector3 halfSize = new Vector3(
                Mathf.Abs(boxCollider.size.x * relativeScale.x) * 0.5f,
                Mathf.Abs(boxCollider.size.y * relativeScale.y) * 0.5f,
                Mathf.Abs(boxCollider.size.z * relativeScale.z) * 0.5f);
            AddTrainCollisionBox(boxes, position, rotation, localCenter, localRotation, halfSize);
        }

        if (boxes.Count <= 0)
        {
            AddTrainCollisionBox(
                boxes,
                position,
                rotation,
                Vector3.zero,
                Quaternion.identity,
                new Vector3(FallbackTrainCollisionHalfWidth, 0.5f, FallbackTrainCollisionHalfLength));
        }
    }

    private static void AddTrainCollisionBox(
        List<TrainCollisionBox2D> boxes,
        Vector3 rootPosition,
        Quaternion rootRotation,
        Vector3 localCenter,
        Quaternion localRotation,
        Vector3 halfSize)
    {
        if (boxes == null)
        {
            return;
        }

        Vector3 worldCenter = rootPosition + rootRotation * localCenter;
        Vector2 axisRight = FlattenTrainCollisionAxis(rootRotation * (localRotation * Vector3.right));
        Vector2 axisForward = FlattenTrainCollisionAxis(rootRotation * (localRotation * Vector3.forward));
        if (axisRight.sqrMagnitude <= 0.0001f || axisForward.sqrMagnitude <= 0.0001f)
        {
            axisRight = FlattenTrainCollisionAxis(rootRotation * Vector3.right);
            axisForward = FlattenTrainCollisionAxis(rootRotation * Vector3.forward);
        }

        if (axisRight.sqrMagnitude <= 0.0001f || axisForward.sqrMagnitude <= 0.0001f)
        {
            axisRight = Vector2.right;
            axisForward = Vector2.up;
        }

        boxes.Add(new TrainCollisionBox2D
        {
            Center = new Vector2(worldCenter.x, worldCenter.z),
            AxisRight = axisRight.normalized,
            AxisForward = axisForward.normalized,
            HalfExtents = new Vector2(
                Mathf.Max(0.001f, halfSize.x),
                Mathf.Max(0.001f, halfSize.z))
        });
    }

    private static bool TrainCollisionBoxesOverlap(
        TrainCollisionBox2D first,
        TrainCollisionBox2D second,
        out float overlapDepth)
    {
        overlapDepth = float.MaxValue;
        return TrainCollisionBoxesOverlapOnAxis(first, second, first.AxisRight, ref overlapDepth)
               && TrainCollisionBoxesOverlapOnAxis(first, second, first.AxisForward, ref overlapDepth)
               && TrainCollisionBoxesOverlapOnAxis(first, second, second.AxisRight, ref overlapDepth)
               && TrainCollisionBoxesOverlapOnAxis(first, second, second.AxisForward, ref overlapDepth);
    }

    private static bool TrainCollisionBoxesOverlapOnAxis(
        TrainCollisionBox2D first,
        TrainCollisionBox2D second,
        Vector2 axis,
        ref float overlapDepth)
    {
        if (axis.sqrMagnitude <= 0.0001f)
        {
            return true;
        }

        axis.Normalize();
        float distance = Mathf.Abs(Vector2.Dot(second.Center - first.Center, axis));
        float firstRadius =
            Mathf.Abs(Vector2.Dot(first.AxisRight, axis)) * first.HalfExtents.x
            + Mathf.Abs(Vector2.Dot(first.AxisForward, axis)) * first.HalfExtents.y;
        float secondRadius =
            Mathf.Abs(Vector2.Dot(second.AxisRight, axis)) * second.HalfExtents.x
            + Mathf.Abs(Vector2.Dot(second.AxisForward, axis)) * second.HalfExtents.y;
        float axisOverlapDepth = firstRadius + secondRadius - distance;
        if (axisOverlapDepth <= TrainPlacementOverlapEpsilon)
        {
            return false;
        }

        overlapDepth = Mathf.Min(overlapDepth, axisOverlapDepth);
        return true;
    }

    private static Vector2 FlattenTrainCollisionAxis(Vector3 axis)
    {
        Vector2 flatAxis = new Vector2(axis.x, axis.z);
        return flatAxis.sqrMagnitude > 0.0001f ? flatAxis.normalized : Vector2.zero;
    }

    private static Vector3 ResolveRelativeLossyScale(Transform transform, Transform root)
    {
        if (transform == null)
        {
            return Vector3.one;
        }

        Vector3 scale = transform.lossyScale;
        if (root == null)
        {
            return scale;
        }

        Vector3 rootScale = root.lossyScale;
        return new Vector3(
            SafeDivideScale(scale.x, rootScale.x),
            SafeDivideScale(scale.y, rootScale.y),
            SafeDivideScale(scale.z, rootScale.z));
    }

    private static float SafeDivideScale(float value, float divisor)
    {
        return Mathf.Abs(divisor) > 0.0001f ? value / divisor : value;
    }

    private static Vector2Int RoundWorldPositionToCoordinate(Vector3 worldPosition)
    {
        return new Vector2Int(
            Mathf.RoundToInt(worldPosition.x),
            Mathf.RoundToInt(worldPosition.z));
    }

    private static float GetPlanarSqrDistance(Vector3 a, Vector3 b)
    {
        float deltaX = a.x - b.x;
        float deltaZ = a.z - b.z;
        return deltaX * deltaX + deltaZ * deltaZ;
    }

    private static bool TryUpdateNearestRailPath(
        Railload candidate,
        Vector2 referencePoint,
        ref Railload nearestRail,
        ref Vector2 nearestPathPoint,
        ref Vector2 nearestTangent,
        ref float nearestSqrDistance)
    {
        if (candidate == null
            || !candidate.TryFindNearestPathPointAndTangent(
                referencePoint,
                out Vector2 candidatePathPoint,
                out Vector2 candidateTangent,
                out float candidateSqrDistance))
        {
            return false;
        }

        if (candidateSqrDistance >= nearestSqrDistance)
        {
            return true;
        }

        nearestRail = candidate;
        nearestPathPoint = candidatePathPoint;
        nearestTangent = candidateTangent;
        nearestSqrDistance = candidateSqrDistance;
        return true;
    }

    private static bool IsTrainSource(MapObject sourcePrefab)
    {
        return ResolveTrainSource(sourcePrefab) != null;
    }

    private static bool IsTrainStationSource(MapObject sourcePrefab)
    {
        if (sourcePrefab == null)
        {
            return false;
        }

        ItemDefinition definition = sourcePrefab.BoundItemDefinition;
        return IsTrainStationLookupName(definition != null ? definition.itemName : null)
               || IsTrainStationLookupName(definition != null ? definition.name : null)
               || IsTrainStationLookupName(sourcePrefab.name)
               || IsTrainStationLookupName(sourcePrefab.gameObject != null ? sourcePrefab.gameObject.name : null);
    }

    private static bool IsTrainStationLookupName(string value)
    {
        return NormalizePlacementLookupName(value) == TrainStationLookupName;
    }

    private static string NormalizePlacementLookupName(string value)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            return string.Empty;
        }

        return value.Replace("(Clone)", string.Empty)
            .Replace("_Blueprint", string.Empty)
            .Replace(" ", string.Empty)
            .Replace("_", string.Empty)
            .Replace("-", string.Empty)
            .Trim()
            .ToLowerInvariant();
    }

    private static bool IsRailloadSource(MapObject sourcePrefab)
    {
        if (sourcePrefab == null)
        {
            return false;
        }

        if (sourcePrefab is Railload)
        {
            return true;
        }

        return sourcePrefab.GetComponent<Railload>() != null
               || sourcePrefab.GetComponentInChildren<Railload>(true) != null;
    }

    private static Train ResolveTrainSource(MapObject sourcePrefab)
    {
        if (sourcePrefab == null)
        {
            return null;
        }

        if (sourcePrefab is Train train)
        {
            return train;
        }

        Train trainComponent = sourcePrefab.GetComponent<Train>();
        return trainComponent != null
            ? trainComponent
            : sourcePrefab.GetComponentInChildren<Train>(true);
    }

    private static float ResolveRailAlignedPlacementMaxSqrDistance()
    {
        return RailAlignedPlacementMaxDistance * RailAlignedPlacementMaxDistance;
    }

    private static Quaternion AlignBaseRotationForwardToDirection(Quaternion baseRotation, Vector3 targetForward)
    {
        targetForward = FlattenHorizontalDirection(targetForward);
        if (targetForward.sqrMagnitude <= 0.0001f)
        {
            return baseRotation;
        }

        Vector3 baseForward = FlattenHorizontalDirection(baseRotation * Vector3.forward);
        if (baseForward.sqrMagnitude <= 0.0001f)
        {
            return Quaternion.LookRotation(targetForward, Vector3.up);
        }

        Quaternion baseForwardRotation = Quaternion.LookRotation(baseForward, Vector3.up);
        Quaternion targetForwardRotation = Quaternion.LookRotation(targetForward, Vector3.up);
        return targetForwardRotation * Quaternion.Inverse(baseForwardRotation) * baseRotation;
    }

    private static Vector3 FlattenHorizontalDirection(Vector3 direction)
    {
        direction.y = 0f;
        return direction.sqrMagnitude > 0.0001f ? direction.normalized : Vector3.zero;
    }

    private bool TryResolveConveyorCornerPlacementPrefab(
        ConveyorBelt conveyorPrototype,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore,
        out MapObject resolvedPrefab)
    {
        return TryResolveConveyorCornerPlacementPrefab(
            conveyorPrototype,
            anchorCoordinate,
            quarterTurns,
            previewToIgnore,
            out resolvedPrefab,
            out _,
            false);
    }

    private bool TryResolveConveyorCornerPlacementPrefab(
        ConveyorBelt conveyorPrototype,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore,
        out MapObject resolvedPrefab,
        out int resolvedQuarterTurns,
        bool preferDifferentFromPreview = false,
        bool requireMoreConnectionsThanStraight = true)
    {
        resolvedPrefab = null;
        resolvedQuarterTurns = quarterTurns;
        if (conveyorPrototype == null)
        {
            return false;
        }

        if (!TryGetConveyorPlacementOutputDirection(conveyorPrototype, quarterTurns, out Vector2Int desiredOutputDirection))
        {
            return false;
        }

        TryGetConveyorPlacementInputDirection(conveyorPrototype, quarterTurns, out Vector2Int desiredInputDirection);

        ConveyorBelt cornerCandidate = conveyorPrototype.CornerVariantPrefab != null
            ? conveyorPrototype.CornerVariantPrefab
            : conveyorPrototype.StraightVariantPrefab;
        ConveyorBelt reverseCornerCandidate = conveyorPrototype.ReverseCornerVariantPrefab != null
            ? conveyorPrototype.ReverseCornerVariantPrefab
            : conveyorPrototype.CornerVariantPrefab;

        int cornerQuarterTurns = quarterTurns;
        bool cornerInputConnected = false;
        bool cornerOutputConnected = false;
        int cornerConnectionCount = 0;
        int cornerScore = 0;
        long cornerLatestConnectedPlacementSequence = long.MinValue;
        bool cornerTurnEndpointConnected = false;
        bool cornerMatches = TryResolveConveyorCornerCandidateQuarterTurns(
            cornerCandidate,
            out cornerQuarterTurns,
            out cornerInputConnected,
            out cornerOutputConnected,
            out cornerConnectionCount,
            out cornerScore,
            out cornerLatestConnectedPlacementSequence,
            out cornerTurnEndpointConnected);

        int reverseQuarterTurns = quarterTurns;
        bool reverseInputConnected = false;
        bool reverseOutputConnected = false;
        int reverseConnectionCount = 0;
        int reverseScore = 0;
        long reverseLatestConnectedPlacementSequence = long.MinValue;
        bool reverseTurnEndpointConnected = false;
        bool reverseMatches = TryResolveConveyorCornerCandidateQuarterTurns(
            reverseCornerCandidate,
            out reverseQuarterTurns,
            out reverseInputConnected,
            out reverseOutputConnected,
            out reverseConnectionCount,
            out reverseScore,
            out reverseLatestConnectedPlacementSequence,
            out reverseTurnEndpointConnected);

        int straightConnectionCount = GetPlacementEndpointConnectionCount(
            conveyorPrototype.StraightVariantPrefab != null
                ? conveyorPrototype.StraightVariantPrefab
                : conveyorPrototype,
            quarterTurns);
        int straightScore = GetPlacementEndpointCandidateScore(
            conveyorPrototype.StraightVariantPrefab != null
                ? conveyorPrototype.StraightVariantPrefab
                : conveyorPrototype,
            quarterTurns);
        if (!preferDifferentFromPreview && requireMoreConnectionsThanStraight)
        {
            bool cornerCanReplaceStraight = cornerMatches
                                            && cornerConnectionCount >= 2
                                            && (cornerConnectionCount > straightConnectionCount || cornerScore > straightScore);
            bool reverseCanReplaceStraight = reverseMatches
                                             && reverseConnectionCount >= 2
                                             && (reverseConnectionCount > straightConnectionCount || reverseScore > straightScore);
            if (!cornerCanReplaceStraight && !reverseCanReplaceStraight)
            {
                return false;
            }

            if (!cornerCanReplaceStraight)
            {
                cornerMatches = false;
            }

            if (!reverseCanReplaceStraight)
            {
                reverseMatches = false;
            }
        }

        if (preferDifferentFromPreview
            && TryResolveDifferentCurrentConveyorCornerState(
                previewToIgnore,
                cornerCandidate,
                cornerMatches,
                cornerInputConnected,
                cornerOutputConnected,
                cornerQuarterTurns,
                reverseCornerCandidate,
                reverseMatches,
                reverseInputConnected,
                reverseOutputConnected,
                reverseQuarterTurns,
                out resolvedPrefab,
                out resolvedQuarterTurns))
        {
            return resolvedPrefab != null;
        }

        if (cornerMatches
            && reverseMatches
            && cornerConnectionCount != reverseConnectionCount)
        {
            bool preferCornerConnectionCount = cornerConnectionCount > reverseConnectionCount;
            resolvedPrefab = preferCornerConnectionCount ? cornerCandidate : reverseCornerCandidate;
            resolvedQuarterTurns = preferCornerConnectionCount ? cornerQuarterTurns : reverseQuarterTurns;
            return resolvedPrefab != null;
        }

        if (cornerMatches
            && reverseMatches
            && cornerTurnEndpointConnected != reverseTurnEndpointConnected)
        {
            resolvedPrefab = cornerTurnEndpointConnected ? cornerCandidate : reverseCornerCandidate;
            resolvedQuarterTurns = cornerTurnEndpointConnected ? cornerQuarterTurns : reverseQuarterTurns;
            return resolvedPrefab != null;
        }

        if (cornerMatches
            && reverseMatches
            && cornerLatestConnectedPlacementSequence != reverseLatestConnectedPlacementSequence)
        {
            bool preferCornerSequence = cornerLatestConnectedPlacementSequence > reverseLatestConnectedPlacementSequence;
            resolvedPrefab = preferCornerSequence ? cornerCandidate : reverseCornerCandidate;
            resolvedQuarterTurns = preferCornerSequence ? cornerQuarterTurns : reverseQuarterTurns;
            return resolvedPrefab != null;
        }

        if (!cornerMatches && !reverseMatches)
        {
            return false;
        }

        if (cornerMatches && !reverseMatches)
        {
            resolvedPrefab = cornerCandidate;
            resolvedQuarterTurns = cornerQuarterTurns;
            return resolvedPrefab != null;
        }

        if (reverseMatches && !cornerMatches)
        {
            resolvedPrefab = reverseCornerCandidate;
            resolvedQuarterTurns = reverseQuarterTurns;
            return resolvedPrefab != null;
        }

        if (cornerScore != reverseScore)
        {
            bool preferCornerScore = cornerScore > reverseScore;
            resolvedPrefab = preferCornerScore ? cornerCandidate : reverseCornerCandidate;
            resolvedQuarterTurns = preferCornerScore ? cornerQuarterTurns : reverseQuarterTurns;
            return resolvedPrefab != null;
        }

        if (!preferDifferentFromPreview
            && TryPreserveCurrentConveyorCornerState(
                anchorCoordinate,
                previewToIgnore,
                cornerCandidate,
                cornerMatches,
                cornerInputConnected,
                cornerOutputConnected,
                cornerQuarterTurns,
                reverseCornerCandidate,
                reverseMatches,
                reverseInputConnected,
                reverseOutputConnected,
                reverseQuarterTurns,
                out resolvedPrefab,
                out resolvedQuarterTurns))
        {
            return resolvedPrefab != null;
        }

        bool cornerPreferred = cornerMatches && cornerInputConnected;
        bool reversePreferred = reverseMatches && reverseInputConnected;

        if (cornerPreferred && !reversePreferred)
        {
            resolvedPrefab = cornerCandidate;
            resolvedQuarterTurns = cornerQuarterTurns;
            return resolvedPrefab != null;
        }

        if (reversePreferred && !cornerPreferred)
        {
            resolvedPrefab = reverseCornerCandidate;
            resolvedQuarterTurns = reverseQuarterTurns;
            return resolvedPrefab != null;
        }

        bool preferReverseVariant = previewToIgnore is ConveyorBelt previewConveyor && previewConveyor.IsReverseCornerVariant;
        resolvedPrefab = preferReverseVariant ? reverseCornerCandidate : cornerCandidate;
        resolvedQuarterTurns = preferReverseVariant ? reverseQuarterTurns : cornerQuarterTurns;
        return resolvedPrefab != null;

        bool TryResolveConveyorCornerCandidateQuarterTurns(
            ConveyorBelt candidate,
            out int candidateQuarterTurns,
            out bool candidateInputConnected,
            out bool candidateOutputConnected,
            out int candidateConnectionCount,
            out int candidateScore,
            out long candidateLatestConnectedPlacementSequence,
            out bool candidateTurnEndpointConnected)
        {
            candidateQuarterTurns = quarterTurns;
            candidateInputConnected = false;
            candidateOutputConnected = false;
            candidateConnectionCount = 0;
            candidateScore = 0;
            candidateLatestConnectedPlacementSequence = long.MinValue;
            candidateTurnEndpointConnected = false;
            if (candidate == null || !candidate.IsCornerVariant)
            {
                return false;
            }

            bool found = false;
            bool bestIsCurrent = false;
            int bestQuarterTurns = candidateQuarterTurns;
            bool bestInputConnected = candidateInputConnected;
            bool bestOutputConnected = candidateOutputConnected;
            int bestConnectionCount = candidateConnectionCount;
            int bestScore = candidateScore;
            long bestLatestConnectedPlacementSequence = candidateLatestConnectedPlacementSequence;
            bool bestTurnEndpointConnected = candidateTurnEndpointConnected;
            ConsiderCornerCandidateQuarterTurns(desiredOutputDirection, true);
            ConsiderCornerCandidateQuarterTurns(desiredInputDirection, false);
            candidateQuarterTurns = bestQuarterTurns;
            candidateInputConnected = bestInputConnected;
            candidateOutputConnected = bestOutputConnected;
            candidateConnectionCount = bestConnectionCount;
            candidateScore = bestScore;
            candidateLatestConnectedPlacementSequence = bestLatestConnectedPlacementSequence;
            candidateTurnEndpointConnected = bestTurnEndpointConnected;
            return found;

            void ConsiderCornerCandidateQuarterTurns(Vector2Int preservedDirection, bool preserveOutput)
            {
                if (preservedDirection == Vector2Int.zero)
                {
                    return;
                }

                int resolvedCandidateQuarterTurns;
                bool resolved = preserveOutput
                    ? TryGetConveyorPlacementQuarterTurnsForOutput(candidate, preservedDirection, out resolvedCandidateQuarterTurns)
                    : TryGetConveyorPlacementQuarterTurnsForInput(candidate, preservedDirection, out resolvedCandidateQuarterTurns);
                if (!resolved
                    || !TryGetConveyorEndpointConnectionCandidatesAtCoordinate(
                        candidate,
                        anchorCoordinate,
                        resolvedCandidateQuarterTurns,
                        previewToIgnore,
                        out bool inputConnected,
                        out bool outputConnected,
                        out bool inputHasConveyor,
                        out bool outputHasConveyor,
                        out bool inputSeamConnected,
                        out bool outputSeamConnected,
                        out long latestConnectedPlacementSequence))
                {
                    return;
                }

                int resolvedScore = GetConveyorEndpointConnectionCandidateScore(
                    inputConnected,
                    outputConnected,
                    inputHasConveyor,
                    outputHasConveyor,
                    inputSeamConnected,
                    outputSeamConnected);
                bool inputCompatible = inputConnected || inputSeamConnected;
                bool outputCompatible = outputConnected || outputSeamConnected;
                bool turnEndpointConnected = preserveOutput ? inputCompatible : outputCompatible;
                bool candidateIsCurrent = IsSameConveyorPreviewState(previewToIgnore, candidate, resolvedCandidateQuarterTurns);
                if (found)
                {
                    if (resolvedScore < bestScore)
                    {
                        return;
                    }

                    if (resolvedScore == bestScore)
                    {
                        if (latestConnectedPlacementSequence < bestLatestConnectedPlacementSequence)
                        {
                            return;
                        }

                        if (turnEndpointConnected != bestTurnEndpointConnected)
                        {
                            if (!turnEndpointConnected)
                            {
                                return;
                            }
                        }
                        else if (latestConnectedPlacementSequence == bestLatestConnectedPlacementSequence)
                        {
                            if (bestIsCurrent && !candidateIsCurrent)
                            {
                                return;
                            }

                            if (candidateIsCurrent == bestIsCurrent && !inputConnected && bestInputConnected)
                            {
                                return;
                            }
                        }
                    }
                }

                found = true;
                bestQuarterTurns = NormalizePlacementQuarterTurns(resolvedCandidateQuarterTurns);
                bestInputConnected = inputConnected;
                bestOutputConnected = outputConnected;
                bestConnectionCount = (inputCompatible ? 1 : 0) + (outputCompatible ? 1 : 0);
                bestScore = resolvedScore;
                bestLatestConnectedPlacementSequence = latestConnectedPlacementSequence;
                bestTurnEndpointConnected = turnEndpointConnected;
                bestIsCurrent = candidateIsCurrent;
            }
        }

        int GetPlacementEndpointConnectionCount(MapObject sourcePrefab, int sourceQuarterTurns)
        {
            if (!(sourcePrefab is ConveyorBelt conveyorSource))
            {
                return 0;
            }

            Quaternion sourceRotation = GetPlacementObjectRotation(conveyorSource, sourceQuarterTurns);
            if (!conveyorSource.TryGetInputDirection(sourceRotation, out Vector2Int sourceInputDirection)
                || !conveyorSource.TryGetOutputDirection(sourceRotation, out Vector2Int sourceOutputDirection))
            {
                return 0;
            }

            return GetConveyorEndpointConnectionScore(
                anchorCoordinate,
                sourceInputDirection,
                sourceOutputDirection,
                previewToIgnore);
        }

        int GetPlacementEndpointCandidateScore(MapObject sourcePrefab, int sourceQuarterTurns)
        {
            if (!(sourcePrefab is ConveyorBelt conveyorSource))
            {
                return 0;
            }

            Quaternion sourceRotation = GetPlacementObjectRotation(conveyorSource, sourceQuarterTurns);
            if (!conveyorSource.TryGetInputDirection(sourceRotation, out Vector2Int sourceInputDirection)
                || !conveyorSource.TryGetOutputDirection(sourceRotation, out Vector2Int sourceOutputDirection))
            {
                return 0;
            }

            return GetConveyorEndpointConnectionCandidateScore(
                anchorCoordinate,
                sourceInputDirection,
                sourceOutputDirection,
                previewToIgnore);
        }
    }

    private bool TryPreserveCurrentConveyorCornerState(
        Vector2Int anchorCoordinate,
        MapObject currentPreview,
        ConveyorBelt cornerCandidate,
        bool cornerMatches,
        bool cornerInputConnected,
        bool cornerOutputConnected,
        int cornerQuarterTurns,
        ConveyorBelt reverseCornerCandidate,
        bool reverseMatches,
        bool reverseInputConnected,
        bool reverseOutputConnected,
        int reverseQuarterTurns,
        out MapObject resolvedPrefab,
        out int resolvedQuarterTurns)
    {
        resolvedPrefab = null;
        resolvedQuarterTurns = 0;
        if (!(currentPreview is ConveyorBelt currentConveyor)
            || !currentConveyor.IsCornerVariant
            || !TryGetPreviewAnchorCoordinate(currentPreview, out Vector2Int currentAnchorCoordinate)
            || currentAnchorCoordinate != anchorCoordinate)
        {
            return false;
        }

        if (cornerMatches
            && (cornerInputConnected || cornerOutputConnected)
            && IsSameConveyorPreviewState(currentPreview, cornerCandidate, cornerQuarterTurns))
        {
            resolvedPrefab = cornerCandidate;
            resolvedQuarterTurns = cornerQuarterTurns;
            return true;
        }

        if (reverseMatches
            && (reverseInputConnected || reverseOutputConnected)
            && IsSameConveyorPreviewState(currentPreview, reverseCornerCandidate, reverseQuarterTurns))
        {
            resolvedPrefab = reverseCornerCandidate;
            resolvedQuarterTurns = reverseQuarterTurns;
            return true;
        }

        return false;
    }

    private bool TryResolveDifferentCurrentConveyorCornerState(
        MapObject currentPreview,
        ConveyorBelt cornerCandidate,
        bool cornerMatches,
        bool cornerInputConnected,
        bool cornerOutputConnected,
        int cornerQuarterTurns,
        ConveyorBelt reverseCornerCandidate,
        bool reverseMatches,
        bool reverseInputConnected,
        bool reverseOutputConnected,
        int reverseQuarterTurns,
        out MapObject resolvedPrefab,
        out int resolvedQuarterTurns)
    {
        resolvedPrefab = null;
        resolvedQuarterTurns = 0;
        if (!(currentPreview is ConveyorBelt currentConveyor) || !currentConveyor.IsCornerVariant)
        {
            return false;
        }

        if (cornerMatches
            && (cornerInputConnected || cornerOutputConnected)
            && !IsSameConveyorPreviewState(currentPreview, cornerCandidate, cornerQuarterTurns))
        {
            resolvedPrefab = cornerCandidate;
            resolvedQuarterTurns = cornerQuarterTurns;
            return true;
        }

        if (reverseMatches
            && (reverseInputConnected || reverseOutputConnected)
            && !IsSameConveyorPreviewState(currentPreview, reverseCornerCandidate, reverseQuarterTurns))
        {
            resolvedPrefab = reverseCornerCandidate;
            resolvedQuarterTurns = reverseQuarterTurns;
            return true;
        }

        return false;
    }

    private bool TryGetConveyorEndpointConnectionCandidatesAtCoordinate(
        ConveyorBelt candidatePrefab,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore,
        out bool inputConnected,
        out bool outputConnected,
        out bool inputHasConveyor,
        out bool outputHasConveyor,
        out bool inputSeamConnected,
        out bool outputSeamConnected,
        out long latestConnectedPlacementSequence)
    {
        inputConnected = false;
        outputConnected = false;
        inputHasConveyor = false;
        outputHasConveyor = false;
        inputSeamConnected = false;
        outputSeamConnected = false;
        latestConnectedPlacementSequence = long.MinValue;
        if (candidatePrefab == null)
        {
            return false;
        }

        Quaternion candidateRotation = GetPlacementObjectRotation(candidatePrefab, quarterTurns);
        if (!candidatePrefab.TryGetInputDirection(candidateRotation, out Vector2Int inputDirection)
            || !candidatePrefab.TryGetOutputDirection(candidateRotation, out Vector2Int outputDirection))
        {
            return false;
        }

        Vector2Int neighborOutputDirection = Vector2Int.zero;
        long inputPlacementSequence = 0;
        ConveyorBelt inputNeighborConveyor = null;
        inputHasConveyor = inputDirection != Vector2Int.zero
                           && TryGetConveyorPlacementDirectionsAndSequenceAtCoordinate(
                               anchorCoordinate + inputDirection,
                               previewToIgnore,
                               out inputNeighborConveyor,
                               out _,
                               out neighborOutputDirection,
                               out inputPlacementSequence);
        inputConnected = inputHasConveyor && neighborOutputDirection == -inputDirection;
        inputSeamConnected = inputHasConveyor
                             && !inputConnected
                             && IsStraightConveyorSideSeamConnection(
                                 inputNeighborConveyor,
                                 inputDirection,
                                 neighborOutputDirection);
        if (inputHasConveyor && !inputConnected && !inputSeamConnected)
        {
            return false;
        }

        if (inputConnected || inputSeamConnected)
        {
            latestConnectedPlacementSequence = inputPlacementSequence > latestConnectedPlacementSequence
                ? inputPlacementSequence
                : latestConnectedPlacementSequence;
        }

        Vector2Int neighborInputDirection = Vector2Int.zero;
        Vector2Int outputNeighborOutputDirection = Vector2Int.zero;
        long outputPlacementSequence = 0;
        ConveyorBelt outputNeighborConveyor = null;
        outputHasConveyor = outputDirection != Vector2Int.zero
                            && TryGetConveyorPlacementDirectionsAndSequenceAtCoordinate(
                                anchorCoordinate + outputDirection,
                                previewToIgnore,
                                out outputNeighborConveyor,
                                out neighborInputDirection,
                                out outputNeighborOutputDirection,
                                out outputPlacementSequence);
        outputConnected = outputHasConveyor && neighborInputDirection == -outputDirection;
        outputSeamConnected = outputHasConveyor
                              && !outputConnected
                              && IsStraightConveyorSideSeamConnection(
                                  outputNeighborConveyor,
                                  outputDirection,
                                  outputNeighborOutputDirection);
        if (outputHasConveyor && !outputConnected && !outputSeamConnected)
        {
            return false;
        }

        if (outputConnected || outputSeamConnected)
        {
            latestConnectedPlacementSequence = outputPlacementSequence > latestConnectedPlacementSequence
                ? outputPlacementSequence
                : latestConnectedPlacementSequence;
        }

        return inputConnected || outputConnected || inputSeamConnected || outputSeamConnected;
    }

    private bool TryGetInstalledConveyorPlacementDirectionsAtCoordinate(
        Vector2Int coordinate,
        out ConveyorBelt conveyorBelt,
        out Vector2Int inputDirection,
        out Vector2Int outputDirection,
        out long placementSequence)
    {
        conveyorBelt = null;
        inputDirection = Vector2Int.zero;
        outputDirection = Vector2Int.zero;
        placementSequence = 0;

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        if (terrain.TryGetLoadedBlock(coordinate, out Block block)
            && block != null
            && block.MapObject is ConveyorBelt liveConveyor
            && liveConveyor != null
            && liveConveyor.gameObject.activeInHierarchy)
        {
            conveyorBelt = liveConveyor;
            placementSequence = liveConveyor.RuntimePlacementSequence;
            return liveConveyor.TryGetInputDirection(liveConveyor.transform.rotation, out inputDirection)
                && liveConveyor.TryGetOutputDirection(liveConveyor.transform.rotation, out outputDirection);
        }

        if (!terrain.TryGetInstallationStateAtCoordinate(coordinate, out BlockStateStore.InstallationSaveState savedState)
            || savedState == null
            || !TryGetInstallationDefinition(savedState, out ItemDefinition savedDefinition)
            || !(savedDefinition.mapObject is ConveyorBelt))
        {
            return false;
        }

        MapObject savedSourcePrefab = null;
        if (!IsBelt2F(savedDefinition.mapObject)
            && savedDefinition.mapObject is ConveyorBelt savedPrototype
            && savedState.conveyorVariantKind >= 0)
        {
            savedSourcePrefab = ResolveConveyorVariantPrefab(savedPrototype, savedState.conveyorVariantKind);
        }

        if (savedSourcePrefab == null)
        {
            savedSourcePrefab = ResolveInstalledObjectSourcePrefab(
                savedDefinition,
                savedState.anchorCoordinate,
                savedState.quarterTurns,
                null,
                ConveyorPreviewVariantMode.Corner);
        }

        if (!(savedSourcePrefab is ConveyorBelt savedConveyor))
        {
            return false;
        }

        conveyorBelt = savedConveyor;
        placementSequence = savedState.placementSequence;
        Quaternion savedRotation = GetPlacementObjectRotation(savedConveyor, savedState.quarterTurns);
        return savedConveyor.TryGetInputDirection(savedRotation, out inputDirection)
            && savedConveyor.TryGetOutputDirection(savedRotation, out outputDirection);
    }

    private bool TryResolveInitialConveyorPreviewQuarterTurns(
        Vector2Int anchorCoordinate,
        ConveyorBelt conveyorPrototype,
        out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = 0;
        if (conveyorPrototype == null)
        {
            return false;
        }

        ConveyorBelt straightPrefab = conveyorPrototype.StraightVariantPrefab != null
            ? conveyorPrototype.StraightVariantPrefab
            : conveyorPrototype;
        if (TryResolveConveyorEndpointAlignedQuarterTurnsForSource(
                straightPrefab,
                anchorCoordinate,
                null,
                resolvedQuarterTurns,
                out resolvedQuarterTurns,
                out _))
        {
            return true;
        }

        if (!TryGetLatestAdjacentConveyorOutputDirection(anchorCoordinate, out Vector2Int desiredOutputDirection))
        {
            return false;
        }

        return TryGetConveyorPlacementQuarterTurnsForOutput(straightPrefab, desiredOutputDirection, out resolvedQuarterTurns);
    }

    private bool TryGetLatestAdjacentConveyorOutputDirection(Vector2Int anchorCoordinate, out Vector2Int desiredOutputDirection)
    {
        desiredOutputDirection = Vector2Int.zero;
        bool found = false;
        long bestPlacementSequence = long.MinValue;
        Vector2Int[] directions =
        {
            Vector2Int.up,
            Vector2Int.right,
            Vector2Int.down,
            Vector2Int.left
        };

        for (int pass = 0; pass < 2; pass++)
        {
            for (int i = 0; i < directions.Length; i++)
            {
                Vector2Int sideDirection = directions[i];
                if (!TryGetConveyorPlacementSequenceAndOutputDirectionAtCoordinate(
                        anchorCoordinate + sideDirection,
                        out Vector2Int neighborOutputDirection,
                        out long placementSequence))
                {
                    continue;
                }

                bool matchesIncomingConnection = neighborOutputDirection == -sideDirection;
                if ((pass == 0 && !matchesIncomingConnection) || (pass == 1 && matchesIncomingConnection))
                {
                    continue;
                }

                if (found && placementSequence <= bestPlacementSequence)
                {
                    continue;
                }

                bestPlacementSequence = placementSequence;
                desiredOutputDirection = neighborOutputDirection;
                found = true;
            }

            if (found)
            {
                return true;
            }
        }

        return false;
    }

    private bool TryGetConveyorPlacementSequenceAndOutputDirectionAtCoordinate(
        Vector2Int coordinate,
        out Vector2Int outputDirection,
        out long placementSequence)
    {
        outputDirection = Vector2Int.zero;
        placementSequence = 0;

        if (TryGetInstallPreviewAtCoordinate(coordinate, out MapObject preview)
            && preview != null
            && preview is ConveyorBelt previewConveyor)
        {
            placementSequence = installPreviewPlacementSequencesByPreview.TryGetValue(preview, out long previewSequence)
                ? previewSequence
                : 0;
            return previewConveyor.TryGetOutputDirection(previewConveyor.transform.rotation, out outputDirection);
        }

        return TryGetInstalledConveyorPlacementDirectionsAtCoordinate(
            coordinate,
            out _,
            out _,
            out outputDirection,
            out placementSequence);
    }

    private void RefreshFencePreviewVariantsAroundActivePreview(
        Vector2Int? previousAnchorCoordinate = null,
        bool preserveActivePreviewQuarterTurns = false)
    {
        if (!(activeInstallPreview is Wall))
        {
            return;
        }

        List<Vector2Int> coordinates = new List<Vector2Int>(2);
        if (previousAnchorCoordinate.HasValue)
        {
            coordinates.Add(previousAnchorCoordinate.Value);
        }

        if (TryGetPreviewAnchorCoordinate(activeInstallPreview, out Vector2Int currentAnchorCoordinate)
            && !coordinates.Contains(currentAnchorCoordinate))
        {
            coordinates.Add(currentAnchorCoordinate);
        }

        RefreshFencePreviewVariants(coordinates, null, preserveActivePreviewQuarterTurns);
        RefreshInstalledFenceVariantPreviews(coordinates);
    }

    private void RefreshAllPipeBlueprintTopology()
    {
        CleanupInstallPreviewReferences();
        List<Vector2Int> previewAnchorCoordinates = new List<Vector2Int>(
            installPreviewInstances.Count);
        for (int previewIndex = 0;
             previewIndex < installPreviewInstances.Count;
             previewIndex++)
        {
            MapObject preview = installPreviewInstances[previewIndex];
            if (!(preview is Pipe))
            {
                continue;
            }

            if (preview is UndergroundPipe undergroundPipe
                && undergroundPipe.HasValidPreviewCandidate
                && undergroundPipe.TryGetPreviewCandidateCoordinates(
                    out Vector2Int firstEndpoint,
                    out Vector2Int secondEndpoint))
            {
                previewAnchorCoordinates.Add(firstEndpoint);
                if (secondEndpoint != firstEndpoint)
                {
                    previewAnchorCoordinates.Add(secondEndpoint);
                }
                continue;
            }

            if (TryGetPreviewAnchorCoordinate(
                    preview,
                    out Vector2Int previewAnchorCoordinate))
            {
                previewAnchorCoordinates.Add(previewAnchorCoordinate);
            }
        }

        HashSet<Vector2Int> refreshCoordinates = BuildPipeVariantRefreshCoordinates(
            previewAnchorCoordinates,
            true,
            null);
        if (refreshCoordinates != null && refreshCoordinates.Count > 0)
        {
            RefreshPipeBlueprintTopology(refreshCoordinates);
        }
    }

    private void RefreshPipePreviewVariantsAroundActivePreview(Vector2Int? previousAnchorCoordinate = null)
    {
        if (!IsPipeConnectorObject(activeInstallPreview))
        {
            return;
        }

        HashSet<Vector2Int> coordinates = new HashSet<Vector2Int>();
        MapObject footprintSource = ResolveInstallPreviewFootprintSource(activeInstallPreview)
                                    ?? (activeInstallDefinition != null ? activeInstallDefinition.mapObject : null)
                                    ?? activeInstallPreview;
        int quarterTurns = GetPreviewQuarterTurns(activeInstallPreview);
        if (previousAnchorCoordinate.HasValue)
        {
            AddFenceVariantRefreshCoordinates(
                coordinates,
                previousAnchorCoordinate.Value,
                true);
        }

        if (activeInstallPreview is UndergroundPipe undergroundPipe
            && undergroundPipe.TryGetPreviewCandidateCoordinates(
                out Vector2Int firstEndpoint,
                out Vector2Int secondEndpoint))
        {
            AddUndergroundPipeEndpointRefreshCoordinates(
                coordinates,
                firstEndpoint,
                secondEndpoint);
        }
        else if (TryGetPreviewAnchorCoordinate(activeInstallPreview, out Vector2Int currentAnchorCoordinate)
                 && !coordinates.Contains(currentAnchorCoordinate))
        {
            AddPipeConnectorVariantRefreshCoordinates(
                coordinates,
                currentAnchorCoordinate,
                footprintSource,
                quarterTurns,
                true);
        }

        RefreshPipeBlueprintTopology(coordinates);
        RefreshFluidTankBlueprintPipeVisuals();
    }

    private static void AddUndergroundPipeEndpointRefreshCoordinates(
        HashSet<Vector2Int> coordinates,
        Vector2Int firstEndpoint,
        Vector2Int secondEndpoint)
    {
        AddFenceVariantRefreshCoordinates(coordinates, firstEndpoint, true);
        if (secondEndpoint != firstEndpoint)
        {
            AddFenceVariantRefreshCoordinates(coordinates, secondEndpoint, true);
        }
    }

    private void RefreshFluidTankBlueprintPipeVisuals()
    {
        CleanupInstallPreviewReferences();
        for (int previewIndex = 0; previewIndex < installPreviewInstances.Count; previewIndex++)
        {
            MapObject preview = installPreviewInstances[previewIndex];
            if (!(preview is Fluidtank fluidTank)
                || !TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate))
            {
                continue;
            }

            fluidTankPreviewConnectionDirectionsScratch.Clear();
            int preferredFluidItemId = ResolveProposedStoredFluidItemId(
                fluidTank,
                preview);
            for (int directionIndex = 0; directionIndex < PipeCardinalDirections.Length; directionIndex++)
            {
                Vector2Int direction = PipeCardinalDirections[directionIndex];
                if (HasFluidTankBlueprintConnection(
                        preview,
                        anchorCoordinate,
                        direction,
                        preferredFluidItemId))
                {
                    AddPipeDirection(fluidTankPreviewConnectionDirectionsScratch, direction);
                }
            }

            fluidTank.ApplyBlueprintPipeConnections(fluidTankPreviewConnectionDirectionsScratch);
        }

        fluidTankPreviewConnectionDirectionsScratch.Clear();
    }

    private bool HasFluidTankBlueprintConnection(
        MapObject fluidTankPreview,
        Vector2Int tankCoordinate,
        Vector2Int directionFromTank,
        int preferredFluidItemId)
    {
        Vector2Int neighborCoordinate = tankCoordinate + directionFromTank;
        if (TryGetFluidTankPlacementSnapshotAtCoordinate(
                neighborCoordinate,
                fluidTankPreview,
                out _))
        {
            return true;
        }

        if (!TryResolveFluidTankBlueprintConnection(
                fluidTankPreview,
                tankCoordinate,
                directionFromTank,
                out int neighborFluidItemId))
        {
            return false;
        }

        return preferredFluidItemId < 0
               || neighborFluidItemId < 0
               || preferredFluidItemId == neighborFluidItemId;
    }

    private bool TryResolveFluidTankBlueprintConnection(
        MapObject fluidTankPreview,
        Vector2Int tankCoordinate,
        Vector2Int directionFromTank,
        out int neighborFluidItemId)
    {
        neighborFluidItemId = -1;
        Vector2Int neighborCoordinate = tankCoordinate + directionFromTank;
        if (TryGetPipePlacementAtCoordinate(
                neighborCoordinate,
                fluidTankPreview,
                out Pipe pipe,
                out Quaternion pipeRotation)
            && (HasEffectivePipeConnectionTowardsAt(
                    neighborCoordinate,
                    pipe,
                    pipeRotation,
                    -directionFromTank)
                || TryResolvePipeVariantForForcedConnection(
                    neighborCoordinate,
                    pipe,
                    pipeRotation,
                    -directionFromTank,
                    out _,
                    out _,
                    fluidTankPreview)))
        {
            TryGetAdjacentPipeBranchFluidItemId(
                tankCoordinate,
                neighborCoordinate,
                pipe,
                pipeRotation,
                fluidTankPreview,
                out neighborFluidItemId);
            return true;
        }

        return TryResolveFluidTankBlueprintPipeOutputConnection(
            tankCoordinate,
            neighborCoordinate,
            directionFromTank,
            fluidTankPreview,
            out neighborFluidItemId);
    }

    private bool TryResolveFluidTankBlueprintPipeOutputConnection(
        Vector2Int tankCoordinate,
        Vector2Int neighborCoordinate,
        Vector2Int requiredDirection,
        MapObject previewToIgnore,
        out int fluidItemId)
    {
        fluidItemId = -1;
        return TryResolveFluidTankBlueprintPipeOutputAtCoordinate(
                   tankCoordinate,
                   requiredDirection,
                   previewToIgnore,
                   out fluidItemId)
               || TryResolveFluidTankBlueprintPipeOutputAtCoordinate(
                   neighborCoordinate,
                   requiredDirection,
                   previewToIgnore,
                   out fluidItemId);
    }

    private bool TryResolveFluidTankBlueprintPipeOutputAtCoordinate(
        Vector2Int coordinate,
        Vector2Int requiredDirection,
        MapObject previewToIgnore,
        out int fluidItemId)
    {
        fluidItemId = -1;
        List<PipeAreaBlockCandidate> candidates = new List<PipeAreaBlockCandidate>(4);
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
            coordinate,
            previewToIgnore,
            candidates);

        bool hasConnection = false;
        HashSet<int> candidateFluidItemIds = new HashSet<int>();
        for (int candidateIndex = 0; candidateIndex < candidates.Count; candidateIndex++)
        {
            PipeAreaBlockCandidate candidate = candidates[candidateIndex];
            if (candidate.snapshot == null
                || !InputOutputModule.IsOutputBlockType(candidate.blockType)
                || !InputOutputModule.AllowsPipeAreaInteraction(candidate.blockType)
                || !TryGetInputOutputModule(
                    candidate.snapshot.mapObject,
                    out InputOutputModule inputOutputModule)
                || !TryGetRectGridPipeAreaConnectionDirection(
                    candidate.snapshot.mapObject,
                    inputOutputModule,
                    candidate.snapshot.anchorCoordinate,
                    candidate.snapshot.quarterTurns,
                    coordinate,
                    out Vector2Int connectionDirection)
                || connectionDirection != requiredDirection)
            {
                continue;
            }

            hasConnection = true;
            candidateFluidItemIds.Clear();
            if (ResolvePipeAreaCandidateFluidItemIds(
                    coordinate,
                    candidate,
                    candidateFluidItemIds) != PipeAreaFluidResolution.Resolved)
            {
                continue;
            }

            foreach (int candidateFluidItemId in candidateFluidItemIds)
            {
                if (InputOutputModule.IsFluidItemId(candidateFluidItemId)
                    && (fluidItemId < 0 || candidateFluidItemId < fluidItemId))
                {
                    fluidItemId = candidateFluidItemId;
                }
            }
        }

        return hasConnection;
    }

    private static bool IsPipeConnectorObject(MapObject mapObject)
    {
        if (mapObject is Pipe || mapObject is Fluidtank || mapObject is Bucket)
        {
            return true;
        }

        if (!(mapObject is InputOutputModule module))
        {
            return false;
        }

        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = module.RectGridPlacements;
        for (int placementIndex = 0;
             placements != null && placementIndex < placements.Count;
             placementIndex++)
        {
            if (InputOutputModule.AllowsPipeAreaInteraction(placements[placementIndex].blockType))
            {
                return true;
            }
        }

        return module.CanStoreFluid;
    }

    private static bool IsProtectedAnchorCoordinate(
        Vector2Int anchorCoordinate,
        IReadOnlyCollection<Vector2Int> protectedAnchorCoordinates)
    {
        if (protectedAnchorCoordinates == null)
        {
            return false;
        }

        foreach (Vector2Int protectedAnchorCoordinate in protectedAnchorCoordinates)
        {
            if (protectedAnchorCoordinate == anchorCoordinate)
            {
                return true;
            }
        }

        return false;
    }

    public void NormalizeLoadedFenceVariants(IReadOnlyList<Vector2Int> anchorCoordinates)
    {
        NormalizeFenceCornersAroundCoordinates(anchorCoordinates, true, null, null);
    }

    public void NormalizeLoadedLegacyPipeVariants(IReadOnlyList<Vector2Int> anchorCoordinates)
    {
        if (anchorCoordinates == null || anchorCoordinates.Count <= 0)
        {
            return;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return;
        }

        HashSet<Vector2Int> inspectedCoordinates = new HashSet<Vector2Int>();
        HashSet<Vector2Int> pipeAnchorsToNormalize = new HashSet<Vector2Int>();
        HashSet<Vector2Int> exactPipeAnchors = new HashSet<Vector2Int>();
        for (int anchorIndex = 0; anchorIndex < anchorCoordinates.Count; anchorIndex++)
        {
            CollectLoadedPipeSaveKindAtCoordinate(anchorCoordinates[anchorIndex]);
            for (int directionIndex = 0;
                 directionIndex < PipeCardinalDirections.Length;
                 directionIndex++)
            {
                CollectLoadedPipeSaveKindAtCoordinate(
                    anchorCoordinates[anchorIndex] + PipeCardinalDirections[directionIndex]);
            }
        }

        if (pipeAnchorsToNormalize.Count <= 0)
        {
            return;
        }

        NormalizePipeVariantsAroundCoordinates(
            new List<Vector2Int>(pipeAnchorsToNormalize),
            true,
            null,
            exactPipeAnchors);

        void CollectLoadedPipeSaveKindAtCoordinate(Vector2Int coordinate)
        {
            if (!inspectedCoordinates.Add(coordinate)
                || !terrain.TryGetLoadedBlock(coordinate, out Block block)
                || block == null
                || !(block.MapObject is Pipe pipe)
                || !pipe.TryGetPlacementRuntime(out Vector2Int pipeAnchorCoordinate, out _)
                || !terrain.TryGetInstallationStateAtCoordinate(
                    pipeAnchorCoordinate,
                    out BlockStateStore.InstallationSaveState savedState)
                || savedState == null)
            {
                return;
            }

            if (savedState.pipeConnectionMask >= 0)
            {
                if (CanPipePlacementFluidConnectionsMatch(
                        pipeAnchorCoordinate,
                        pipe,
                        pipe.transform.rotation,
                        null,
                        savedState.pipeConnectionMask))
                {
                    exactPipeAnchors.Add(pipeAnchorCoordinate);
                }
                else
                {
                    pipeAnchorsToNormalize.Add(pipeAnchorCoordinate);
                }
            }
            else
            {
                pipeAnchorsToNormalize.Add(pipeAnchorCoordinate);
            }
        }
    }

    private void NormalizeFenceCornersAroundCoordinates(
        IReadOnlyList<Vector2Int> coordinates,
        bool includeSelf = true,
        MapObject previewToIgnore = null,
        IReadOnlyCollection<Vector2Int> protectedAnchorCoordinates = null)
    {
        if (coordinates == null || coordinates.Count <= 0)
        {
            return;
        }

        HashSet<Vector2Int> candidateCoordinates = new HashSet<Vector2Int>();
        for (int i = 0; i < coordinates.Count; i++)
        {
            AddPipeConnectorVariantRefreshCoordinatesForWorldCoordinate(
                candidateCoordinates,
                coordinates[i],
                includeSelf,
                previewToIgnore);
        }

        if (candidateCoordinates.Count <= 0)
        {
            return;
        }

        List<Vector2Int> candidateList = new List<Vector2Int>(candidateCoordinates);
        int maxPassCount = Mathf.Max(1, candidateList.Count);
        for (int pass = 0; pass < maxPassCount; pass++)
        {
            bool anyChanged = false;
            for (int i = 0; i < candidateList.Count; i++)
            {
                if (TryNormalizeFenceCornerAtCoordinate(
                        candidateList[i],
                        previewToIgnore,
                        protectedAnchorCoordinates))
                {
                    anyChanged = true;
                }
            }

            if (!anyChanged)
            {
                break;
            }
        }
    }

    private bool TryNormalizeFenceCornerAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        IReadOnlyCollection<Vector2Int> protectedAnchorCoordinates)
    {
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null
            || !terrain.TryGetLoadedBlock(coordinate, out Block block)
            || block == null
            || !(block.MapObject is Wall installedFence)
            || installedFence == null
            || !installedFence.gameObject.activeInHierarchy
            || !installedFence.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out int currentQuarterTurns))
        {
            return false;
        }

        if (anchorCoordinate != coordinate)
        {
            return false;
        }

        if (protectedAnchorCoordinates != null)
        {
            foreach (Vector2Int protectedAnchorCoordinate in protectedAnchorCoordinates)
            {
                if (protectedAnchorCoordinate == anchorCoordinate)
                {
                    return false;
                }
            }
        }

        Wall fencePrototype = installedFence.StraightVariantPrefab != null
            ? installedFence.StraightVariantPrefab
            : installedFence;
        if (!TryResolveFencePlacementVariant(
                fencePrototype,
                anchorCoordinate,
                currentQuarterTurns,
                previewToIgnore,
                out MapObject desiredPrefab,
                out int desiredQuarterTurns)
            || !(desiredPrefab is Wall desiredFencePrefab))
        {
            return false;
        }

        Quaternion desiredRotation = GetInstalledObjectRotation(desiredFencePrefab, desiredQuarterTurns);
        bool sameVariant = installedFence.VariantKind == desiredFencePrefab.VariantKind;
        bool sameQuarterTurns = NormalizePlacementQuarterTurns(currentQuarterTurns) == NormalizePlacementQuarterTurns(desiredQuarterTurns);
        bool sameRotation = Mathf.Abs(Quaternion.Dot(installedFence.transform.rotation, desiredRotation)) >= 0.9999f;
        if (sameVariant && sameQuarterTurns && sameRotation)
        {
            return false;
        }

        Vector3 desiredPosition = GetInstalledObjectWorldPosition(anchorCoordinate, desiredFencePrefab, desiredQuarterTurns);
        RemoveInstalledFenceVariantPreview(installedFence);
        if (sameVariant)
        {
            installedFence.transform.SetPositionAndRotation(desiredPosition, desiredRotation);
            block.SetMapObject(installedFence);
            ConfigureInstalledObjectRuntime(
                installedFence,
                anchorCoordinate,
                desiredQuarterTurns,
                placementSequence: installedFence.RuntimePlacementSequence);
            RegisterInstalledObjectPersistence(installedFence);
            return true;
        }

        MapObject replacementObject = CreateInstalledObjectInstance(desiredFencePrefab, terrain.transform, terrain);
        if (!(replacementObject is Wall replacementFence))
        {
            if (replacementObject is InstallationObject replacementInstallation)
            {
                ReleaseInstalledObjectInstance(replacementInstallation, desiredFencePrefab, terrain);
            }

            return false;
        }

        replacementFence.transform.SetPositionAndRotation(desiredPosition, desiredRotation);
        replacementFence.ApplyItemFilterMask(
            installedFence.CaptureItemFilterMaskWords(),
            installedFence.IsItemFilterMaskInitialized);
        block.SetMapObject(replacementFence);
        ConfigureInstalledObjectRuntime(
            replacementFence,
            anchorCoordinate,
            desiredQuarterTurns,
            placementSequence: installedFence.RuntimePlacementSequence);
        RegisterInstalledObjectPersistence(replacementFence);

        TryGetInstallationDefinition(installedFence.ResolveItemId(), out ItemDefinition installedDefinition);
        ReleaseInstalledObjectInstance(
            installedFence,
            ResolveInstallationSourcePrefab(
                installedDefinition,
                GetFenceVariantKind(installedFence)),
            terrain);

        return true;
    }

    private void NormalizePipeVariantsAroundCoordinates(
        IReadOnlyList<Vector2Int> coordinates,
        bool includeSelf = true,
        MapObject previewToIgnore = null,
        IReadOnlyCollection<Vector2Int> protectedAnchorCoordinates = null)
    {
        if (coordinates == null || coordinates.Count <= 0)
        {
            return;
        }

        HashSet<Vector2Int> candidateCoordinates = new HashSet<Vector2Int>();
        for (int i = 0; i < coordinates.Count; i++)
        {
            AddPipeConnectorVariantRefreshCoordinatesForWorldCoordinate(
                candidateCoordinates,
                coordinates[i],
                includeSelf,
                previewToIgnore);
        }

        if (candidateCoordinates.Count <= 0)
        {
            return;
        }

        List<Vector2Int> candidateList = new List<Vector2Int>(candidateCoordinates);
        candidateList.Sort(ComparePipeVariantCoordinates);
        int maxPassCount = Mathf.Max(1, candidateList.Count);
        pipeVariantNormalizationStateHashesScratch.Clear();
        pipeVariantNormalizationStateHashesScratch.Add(
            ComputePipeVariantNormalizationStateHash(candidateList, false));
        for (int pass = 0; pass < maxPassCount; pass++)
        {
            bool anyChanged = false;
            for (int i = 0; i < candidateList.Count; i++)
            {
                if (TryNormalizePipeVariantAtCoordinate(
                        candidateList[i],
                        previewToIgnore,
                        protectedAnchorCoordinates))
                {
                    anyChanged = true;
                }
            }

            if (!anyChanged)
            {
                break;
            }

            ulong stateHash = ComputePipeVariantNormalizationStateHash(candidateList, false);
            if (!pipeVariantNormalizationStateHashesScratch.Add(stateHash))
            {
                break;
            }
        }

        pipeVariantNormalizationStateHashesScratch.Clear();
    }

    private bool TryNormalizePipeVariantAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        IReadOnlyCollection<Vector2Int> protectedAnchorCoordinates)
    {
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null
            || !terrain.TryGetLoadedBlock(coordinate, out Block block)
            || block == null
            || !(block.MapObject is Pipe installedPipe)
            || installedPipe == null
            || installedPipe is UndergroundPipe
            || !installedPipe.gameObject.activeInHierarchy
            || !installedPipe.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out int currentQuarterTurns))
        {
            return false;
        }

        if (anchorCoordinate != coordinate || IsProtectedAnchorCoordinate(anchorCoordinate, protectedAnchorCoordinates))
        {
            return false;
        }

        Pipe pipePrototype = installedPipe.StraightVariantPrefab != null
            ? installedPipe.StraightVariantPrefab
            : installedPipe;
        int baselineConnectionMask = installedPipe.GetConnectionMask(installedPipe.transform.rotation);
        if (!TryResolvePipePlacementVariantWithCompatibleAdjacency(
                pipePrototype,
                anchorCoordinate,
                currentQuarterTurns,
                previewToIgnore,
                baselineConnectionMask,
                out MapObject desiredPrefab,
                out int desiredQuarterTurns)
            || !(desiredPrefab is Pipe desiredPipePrefab))
        {
            return false;
        }

        Quaternion desiredRotation = GetInstalledObjectRotation(
            desiredPipePrefab,
            desiredQuarterTurns);
        return ApplyInstalledPipeVariantPlan(new InstalledPipeVariantPreviewPlan
        {
            installedPipe = installedPipe,
            sourcePrefab = desiredPipePrefab,
            quarterTurns = NormalizePlacementQuarterTurns(desiredQuarterTurns),
            position = GetInstalledObjectWorldPosition(
                anchorCoordinate,
                desiredPipePrefab,
                desiredQuarterTurns),
            rotation = desiredRotation
        });
    }

    private bool ApplyInstalledPipeVariantPlan(InstalledPipeVariantPreviewPlan plan)
    {
        if (plan.installedPipe == null
            || !(plan.sourcePrefab is Pipe desiredPipePrefab)
            || !plan.installedPipe.TryGetPlacementRuntime(
                out Vector2Int anchorCoordinate,
                out int currentQuarterTurns))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null
            || !terrain.TryGetLoadedBlock(anchorCoordinate, out Block block)
            || block == null
            || block.MapObject != plan.installedPipe)
        {
            return false;
        }

        Pipe installedPipe = plan.installedPipe;
        int desiredQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            desiredPipePrefab,
            plan.quarterTurns);
        bool sameVariant = installedPipe.VariantKind == desiredPipePrefab.VariantKind;
        bool sameQuarterTurns = NormalizePlacementQuarterTurns(currentQuarterTurns)
                                == NormalizePlacementQuarterTurns(desiredQuarterTurns);
        bool sameRotation = Mathf.Abs(Quaternion.Dot(
            installedPipe.transform.rotation,
            plan.rotation)) >= 0.9999f;
        bool samePosition = (installedPipe.transform.position - plan.position).sqrMagnitude
                            <= 0.0001f;
        if (sameVariant && sameQuarterTurns && sameRotation && samePosition)
        {
            return false;
        }

        RemoveInstalledPipeVariantPreview(installedPipe);
        if (sameVariant)
        {
            installedPipe.transform.SetPositionAndRotation(plan.position, plan.rotation);
            block.SetMapObject(installedPipe);
            ConfigureInstalledObjectRuntime(
                installedPipe,
                anchorCoordinate,
                desiredQuarterTurns,
                placementSequence: installedPipe.RuntimePlacementSequence);
            RegisterInstalledObjectPersistence(installedPipe);
            return true;
        }

        MapObject replacementObject = CreateInstalledObjectInstance(
            desiredPipePrefab,
            terrain.transform,
            terrain);
        if (!(replacementObject is Pipe replacementPipe))
        {
            if (replacementObject is InstallationObject replacementInstallation)
            {
                ReleaseInstalledObjectInstance(
                    replacementInstallation,
                    desiredPipePrefab,
                    terrain);
            }

            return false;
        }

        replacementPipe.transform.SetPositionAndRotation(plan.position, plan.rotation);
        replacementPipe.ApplyItemFilterMask(
            installedPipe.CaptureItemFilterMaskWords(),
            installedPipe.IsItemFilterMaskInitialized);
        block.SetMapObject(replacementPipe);
        ConfigureInstalledObjectRuntime(
            replacementPipe,
            anchorCoordinate,
            desiredQuarterTurns,
            placementSequence: installedPipe.RuntimePlacementSequence);
        RegisterInstalledObjectPersistence(replacementPipe);

        TryGetInstallationDefinition(
            installedPipe.ResolveItemId(),
            out ItemDefinition installedDefinition);
        ReleaseInstalledObjectInstance(
            installedPipe,
            ResolveInstallationSourcePrefab(
                installedDefinition,
                GetPipeVariantKind(installedPipe)),
            terrain);
        return true;
    }

    private void ApplyInstalledPipeBlueprintPlans(
        IReadOnlyList<InstalledPipeVariantPreviewPlan> plans)
    {
        // Removing the visual overlays restores their real owners. From this point
        // onward only the captured blueprint plans may change installed variants.
        RemoveInstalledPipeVariantPreviews(null);
        for (int planIndex = 0;
             plans != null && planIndex < plans.Count;
             planIndex++)
        {
            InstalledPipeVariantPreviewPlan plan = plans[planIndex];
            if (!PipeVariantResolutionPlanMatchesInstalledPipe(plan))
            {
                ApplyInstalledPipeVariantPlan(plan);
            }
        }
    }

    private bool CanApplyInstalledPipeBlueprintPlans(
        IReadOnlyList<InstalledPipeVariantPreviewPlan> plans)
    {
        if (plans == null || plans.Count <= 0)
        {
            return true;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        for (int planIndex = 0; planIndex < plans.Count; planIndex++)
        {
            InstalledPipeVariantPreviewPlan plan = plans[planIndex];
            if (plan.installedPipe == null
                || !(plan.sourcePrefab is Pipe)
                || !plan.installedPipe.TryGetPlacementRuntime(
                    out Vector2Int anchorCoordinate,
                    out _)
                || !terrain.TryGetLoadedBlock(anchorCoordinate, out Block block)
                || block == null
                || block.MapObject != plan.installedPipe)
            {
                return false;
            }
        }

        return true;
    }

    private bool TryGetEditableInstallationFromRaycast(
        Ray ray,
        float maxDistance,
        out InstallationObject installationObject,
        out Vector2Int anchorCoordinate)
    {
        installationObject = null;
        anchorCoordinate = Vector2Int.zero;

        int hitCount = Physics.RaycastNonAlloc(
            ray,
            pointerRaycastHits,
            Mathf.Max(0f, maxDistance),
            Physics.DefaultRaycastLayers,
            QueryTriggerInteraction.Ignore);
        if (hitCount <= 0)
        {
            return false;
        }

        InstallationObject bestInstallationObject = null;
        Vector2Int bestAnchorCoordinate = Vector2Int.zero;
        float bestDistance = float.PositiveInfinity;
        for (int i = 0; i < hitCount; i++)
        {
            RaycastHit hit = pointerRaycastHits[i];
            Collider hitCollider = hit.collider;
            if (hitCollider == null)
            {
                continue;
            }

            InstallationObject candidate = hitCollider.GetComponentInParent<InstallationObject>();
            if (candidate == null
                || !candidate.gameObject.activeInHierarchy
                || !candidate.TryGetPlacementRuntime(out Vector2Int candidateAnchorCoordinate, out _))
            {
                continue;
            }

            if (hit.distance >= bestDistance)
            {
                continue;
            }

            bestInstallationObject = candidate;
            bestAnchorCoordinate = candidateAnchorCoordinate;
            bestDistance = hit.distance;
        }

        if (bestInstallationObject == null)
        {
            return false;
        }

        installationObject = bestInstallationObject;
        anchorCoordinate = bestAnchorCoordinate;
        return true;
    }

    private bool TryGetConveyorPlacementOutputDirection(ConveyorBelt conveyorPrototype, int quarterTurns, out Vector2Int outputDirection)
    {
        outputDirection = Vector2Int.zero;
        if (conveyorPrototype == null)
        {
            return false;
        }

        return conveyorPrototype.TryGetOutputDirection(
            GetPlacementObjectRotation(conveyorPrototype, quarterTurns),
            out outputDirection);
    }

    private bool TryGetConveyorPlacementInputDirection(ConveyorBelt conveyorPrototype, int quarterTurns, out Vector2Int inputDirection)
    {
        inputDirection = Vector2Int.zero;
        if (conveyorPrototype == null)
        {
            return false;
        }

        return conveyorPrototype.TryGetInputDirection(
            GetPlacementObjectRotation(conveyorPrototype, quarterTurns),
            out inputDirection);
    }

    private bool TryGetConveyorPlacementQuarterTurnsForOutput(MapObject sourcePrefab, Vector2Int desiredOutputDirection, out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = 0;
        if (!(sourcePrefab is ConveyorBelt conveyorSource) || desiredOutputDirection == Vector2Int.zero)
        {
            return false;
        }

        int candidateCount = GetPlacementRotationCandidateCount(sourcePrefab);
        for (int candidateQuarterTurns = 0; candidateQuarterTurns < candidateCount; candidateQuarterTurns++)
        {
            if (!conveyorSource.TryGetOutputDirection(
                    GetPlacementObjectRotation(conveyorSource, candidateQuarterTurns),
                    out Vector2Int candidateOutputDirection))
            {
                continue;
            }

            if (candidateOutputDirection != desiredOutputDirection)
            {
                continue;
            }

            resolvedQuarterTurns = candidateQuarterTurns;
            return true;
        }

        return false;
    }

    private bool TryGetConveyorPlacementQuarterTurnsForInput(MapObject sourcePrefab, Vector2Int desiredInputDirection, out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = 0;
        if (!(sourcePrefab is ConveyorBelt conveyorSource) || desiredInputDirection == Vector2Int.zero)
        {
            return false;
        }

        int candidateCount = GetPlacementRotationCandidateCount(sourcePrefab);
        for (int candidateQuarterTurns = 0; candidateQuarterTurns < candidateCount; candidateQuarterTurns++)
        {
            if (!conveyorSource.TryGetInputDirection(
                    GetPlacementObjectRotation(conveyorSource, candidateQuarterTurns),
                    out Vector2Int candidateInputDirection))
            {
                continue;
            }

            if (candidateInputDirection != desiredInputDirection)
            {
                continue;
            }

            resolvedQuarterTurns = candidateQuarterTurns;
            return true;
        }

        return false;
    }

    private bool TryResolveConveyorEndpointAlignedQuarterTurns(
        Vector2Int anchorCoordinate,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        if (activeInstallDefinition == null || !(activeInstallDefinition.mapObject is ConveyorBelt conveyorPrototype))
        {
            return false;
        }

        ConveyorPreviewVariantMode previewVariantMode = previewToIgnore == activeInstallPreview
            ? installPreviewConveyorVariantMode
            : GetConveyorPreviewVariantMode(previewToIgnore);
        List<MapObject> candidateSources = new List<MapObject>(3);
        if (previewVariantMode == ConveyorPreviewVariantMode.Straight)
        {
            AddUniqueConveyorCandidateSource(candidateSources, conveyorPrototype.StraightVariantPrefab);
        }
        else
        {
            AddUniqueConveyorCandidateSource(candidateSources, conveyorPrototype.CornerVariantPrefab);
            AddUniqueConveyorCandidateSource(candidateSources, conveyorPrototype.ReverseCornerVariantPrefab);
            AddUniqueConveyorCandidateSource(candidateSources, conveyorPrototype.StraightVariantPrefab);
        }

        bool found = false;
        int bestScore = 0;
        int bestOffset = int.MaxValue;
        for (int i = 0; i < candidateSources.Count; i++)
        {
            if (!TryResolveConveyorEndpointAlignedQuarterTurnsForSource(
                    candidateSources[i],
                    anchorCoordinate,
                    previewToIgnore,
                    preferredQuarterTurns,
                    out int candidateQuarterTurns,
                    out int candidateScore))
            {
                continue;
            }

            int candidateOffset = GetQuarterTurnSearchOffset(preferredQuarterTurns, candidateQuarterTurns);
            if (found
                && (candidateScore < bestScore
                    || (candidateScore == bestScore && candidateOffset >= bestOffset)))
            {
                continue;
            }

            found = true;
            bestScore = candidateScore;
            bestOffset = candidateOffset;
            resolvedQuarterTurns = candidateQuarterTurns;
        }

        return found;
    }

    private bool TryResolveConveyorEndpointAlignedQuarterTurnsForSource(
        MapObject sourcePrefab,
        Vector2Int anchorCoordinate,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        out int resolvedQuarterTurns,
        out int resolvedScore)
    {
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        resolvedScore = 0;
        if (!(sourcePrefab is ConveyorBelt conveyorSource))
        {
            return false;
        }

        int normalizedPreferredQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            sourcePrefab,
            preferredQuarterTurns);
        int candidateCount = GetPlacementRotationCandidateCount(sourcePrefab);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                sourcePrefab,
                normalizedPreferredQuarterTurns + offset);
            Quaternion candidateRotation = GetPlacementObjectRotation(conveyorSource, candidateQuarterTurns);
            if (!conveyorSource.TryGetInputDirection(candidateRotation, out Vector2Int inputDirection)
                || !conveyorSource.TryGetOutputDirection(candidateRotation, out Vector2Int outputDirection))
            {
                continue;
            }

            int candidateScore = GetConveyorEndpointConnectionCandidateScore(
                anchorCoordinate,
                inputDirection,
                outputDirection,
                previewToIgnore);
            if (candidateScore <= 0)
            {
                continue;
            }

            if (resolvedScore > 0 && candidateScore <= resolvedScore)
            {
                continue;
            }

            resolvedQuarterTurns = candidateQuarterTurns;
            resolvedScore = candidateScore;
            if (candidateScore >= 2)
            {
                return true;
            }
        }

        return resolvedScore > 0;
    }

    private int GetConveyorEndpointConnectionScore(
        Vector2Int anchorCoordinate,
        Vector2Int inputDirection,
        Vector2Int outputDirection,
        MapObject previewToIgnore)
    {
        int score = 0;
        if (inputDirection != Vector2Int.zero
            && TryGetConveyorPlacementDirectionsAtCoordinate(
                anchorCoordinate + inputDirection,
                previewToIgnore,
                out ConveyorBelt inputNeighborConveyor,
                out _,
                out Vector2Int neighborOutputDirection)
            && (neighborOutputDirection == -inputDirection
                || IsStraightConveyorSideSeamConnection(
                    inputNeighborConveyor,
                    inputDirection,
                    neighborOutputDirection)))
        {
            score++;
        }

        if (outputDirection != Vector2Int.zero
            && TryGetConveyorPlacementDirectionsAtCoordinate(
                anchorCoordinate + outputDirection,
                previewToIgnore,
                out ConveyorBelt outputNeighborConveyor,
                out Vector2Int neighborInputDirection,
                out Vector2Int outputNeighborOutputDirection)
            && (neighborInputDirection == -outputDirection
                || IsStraightConveyorSideSeamConnection(
                    outputNeighborConveyor,
                    outputDirection,
                    outputNeighborOutputDirection)))
        {
            score++;
        }

        return score;
    }

    private int GetConveyorEndpointConnectionCandidateScore(
        Vector2Int anchorCoordinate,
        Vector2Int inputDirection,
        Vector2Int outputDirection,
        MapObject previewToIgnore)
    {
        Vector2Int neighborOutputDirection = Vector2Int.zero;
        ConveyorBelt inputNeighborConveyor = null;
        bool inputHasConveyor = inputDirection != Vector2Int.zero
                                && TryGetConveyorPlacementDirectionsAtCoordinate(
                                    anchorCoordinate + inputDirection,
                                    previewToIgnore,
                                    out inputNeighborConveyor,
                                    out _,
                                    out neighborOutputDirection);
        bool inputConnected = inputHasConveyor && neighborOutputDirection == -inputDirection;
        bool inputSeamConnected = inputHasConveyor
                                  && !inputConnected
                                  && IsStraightConveyorSideSeamConnection(
                                      inputNeighborConveyor,
                                      inputDirection,
                                      neighborOutputDirection);

        Vector2Int neighborInputDirection = Vector2Int.zero;
        Vector2Int outputNeighborOutputDirection = Vector2Int.zero;
        ConveyorBelt outputNeighborConveyor = null;
        bool outputHasConveyor = outputDirection != Vector2Int.zero
                                 && TryGetConveyorPlacementDirectionsAtCoordinate(
                                     anchorCoordinate + outputDirection,
                                     previewToIgnore,
                                     out outputNeighborConveyor,
                                     out neighborInputDirection,
                                     out outputNeighborOutputDirection);
        bool outputConnected = outputHasConveyor && neighborInputDirection == -outputDirection;
        bool outputSeamConnected = outputHasConveyor
                                   && !outputConnected
                                   && IsStraightConveyorSideSeamConnection(
                                       outputNeighborConveyor,
                                       outputDirection,
                                       outputNeighborOutputDirection);

        return GetConveyorEndpointConnectionCandidateScore(
            inputConnected,
            outputConnected,
            inputHasConveyor,
            outputHasConveyor,
            inputSeamConnected,
            outputSeamConnected);
    }

    private static int GetConveyorEndpointConnectionCandidateScore(
        bool inputConnected,
        bool outputConnected,
        bool inputHasConveyor,
        bool outputHasConveyor,
        bool inputSeamConnected = false,
        bool outputSeamConnected = false)
    {
        int score = 0;
        score += inputConnected ? 4 : inputSeamConnected ? 3 : inputHasConveyor ? 0 : 0;
        score += outputConnected ? 2 : outputSeamConnected ? 1 : outputHasConveyor ? 0 : 0;
        return score;
    }

    private static bool IsStraightConveyorSideSeamConnection(
        ConveyorBelt conveyorBelt,
        Vector2Int endpointDirection,
        Vector2Int neighborFlowDirection)
    {
        return conveyorBelt != null
               && !conveyorBelt.IsCornerVariant
               && ConveyorBelt.IsPerpendicular(endpointDirection, neighborFlowDirection);
    }

    private static void AddUniqueConveyorCandidateSource(List<MapObject> candidateSources, MapObject candidateSource)
    {
        if (candidateSources == null || candidateSource == null)
        {
            return;
        }

        for (int i = 0; i < candidateSources.Count; i++)
        {
            if (candidateSources[i] == candidateSource)
            {
                return;
            }
        }

        candidateSources.Add(candidateSource);
    }

    private static int GetQuarterTurnSearchOffset(int preferredQuarterTurns, int candidateQuarterTurns)
    {
        int normalizedPreferredQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        int normalizedCandidateQuarterTurns = NormalizePlacementQuarterTurns(candidateQuarterTurns);
        return (normalizedCandidateQuarterTurns - normalizedPreferredQuarterTurns + 4) % 4;
    }

    private bool TryGetConveyorPlacementDirectionsAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out ConveyorBelt conveyorBelt,
        out Vector2Int inputDirection,
        out Vector2Int outputDirection)
    {
        return TryGetConveyorPlacementDirectionsAndSequenceAtCoordinate(
            coordinate,
            previewToIgnore,
            out conveyorBelt,
            out inputDirection,
            out outputDirection,
            out _);
    }

    private bool TryGetConveyorPlacementDirectionsAndSequenceAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out ConveyorBelt conveyorBelt,
        out Vector2Int inputDirection,
        out Vector2Int outputDirection,
        out long placementSequence)
    {
        conveyorBelt = null;
        inputDirection = Vector2Int.zero;
        outputDirection = Vector2Int.zero;
        placementSequence = 0;

        if (TryGetInstallPreviewAtCoordinate(coordinate, out MapObject preview)
            && preview != null
            && preview != previewToIgnore
            && preview is ConveyorBelt previewConveyor)
        {
            conveyorBelt = previewConveyor;
            placementSequence = installPreviewPlacementSequencesByPreview.TryGetValue(preview, out long previewSequence)
                ? previewSequence
                : 0;
            return previewConveyor.TryGetInputDirection(previewConveyor.transform.rotation, out inputDirection)
                && previewConveyor.TryGetOutputDirection(previewConveyor.transform.rotation, out outputDirection);
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        if (terrain.TryGetLoadedBlock(coordinate, out Block block)
            && block != null
            && block.MapObject is ConveyorBelt liveConveyor
            && liveConveyor != null
            && liveConveyor.gameObject.activeInHierarchy)
        {
            conveyorBelt = liveConveyor;
            placementSequence = liveConveyor.RuntimePlacementSequence;
            return liveConveyor.TryGetInputDirection(liveConveyor.transform.rotation, out inputDirection)
                && liveConveyor.TryGetOutputDirection(liveConveyor.transform.rotation, out outputDirection);
        }

        if (!terrain.TryGetInstallationStateAtCoordinate(coordinate, out BlockStateStore.InstallationSaveState savedState)
            || savedState == null
            || !TryGetInstallationDefinition(savedState, out ItemDefinition savedDefinition)
            || !(savedDefinition.mapObject is ConveyorBelt))
        {
            return false;
        }

        MapObject savedSourcePrefab = null;
        if (!IsBelt2F(savedDefinition.mapObject)
            && savedDefinition.mapObject is ConveyorBelt savedPrototype
            && savedState.conveyorVariantKind >= 0)
        {
            savedSourcePrefab = ResolveConveyorVariantPrefab(savedPrototype, savedState.conveyorVariantKind);
        }

        if (savedSourcePrefab == null)
        {
            savedSourcePrefab = ResolveInstalledObjectSourcePrefab(
                savedDefinition,
                savedState.anchorCoordinate,
                savedState.quarterTurns,
                null,
                ConveyorPreviewVariantMode.Corner);
        }
        if (!(savedSourcePrefab is ConveyorBelt savedConveyor))
        {
            return false;
        }

        conveyorBelt = savedConveyor;
        placementSequence = savedState.placementSequence;
        Quaternion savedRotation = GetPlacementObjectRotation(savedConveyor, savedState.quarterTurns);
        return savedConveyor.TryGetInputDirection(savedRotation, out inputDirection)
            && savedConveyor.TryGetOutputDirection(savedRotation, out outputDirection);
    }

    private void RefreshFencePreviewVariants(
        IReadOnlyList<Vector2Int> changedCoordinates = null,
        MapObject previewToIgnore = null,
        bool preserveActivePreviewQuarterTurns = false)
    {
        if (activeInstallDefinition == null || !(activeInstallDefinition.mapObject is Wall))
        {
            return;
        }

        CleanupInstallPreviewReferences();
        if (installPreviewInstances.Count <= 0)
        {
            return;
        }

        HashSet<Vector2Int> affectedPreviewCoordinates = BuildFenceVariantRefreshCoordinates(changedCoordinates, true);
        int maxPassCount = Mathf.Max(1, installPreviewInstances.Count);
        for (int pass = 0; pass < maxPassCount; pass++)
        {
            bool anyChanged = false;
            List<MapObject> previews = new List<MapObject>(installPreviewInstances);
            for (int i = 0; i < previews.Count; i++)
            {
                MapObject preview = previews[i];
                if (!(preview is Wall)
                    || !TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate))
                {
                    continue;
                }

                if (affectedPreviewCoordinates != null && !affectedPreviewCoordinates.Contains(anchorCoordinate))
                {
                    continue;
                }

                if (RefreshSingleFencePreviewVariant(
                        preview,
                        anchorCoordinate,
                        previewToIgnore,
                        preserveActivePreviewQuarterTurns && preview == activeInstallPreview))
                {
                    anyChanged = true;
                }
            }

            if (!anyChanged)
            {
                break;
            }
        }
    }

    private static HashSet<Vector2Int> BuildFenceVariantRefreshCoordinates(
        IReadOnlyList<Vector2Int> changedCoordinates,
        bool includeSelf)
    {
        if (changedCoordinates == null || changedCoordinates.Count <= 0)
        {
            return null;
        }

        HashSet<Vector2Int> coordinates = new HashSet<Vector2Int>();
        for (int i = 0; i < changedCoordinates.Count; i++)
        {
            Vector2Int coordinate = changedCoordinates[i];
            if (includeSelf)
            {
                coordinates.Add(coordinate);
            }

            coordinates.Add(coordinate + Vector2Int.up);
            coordinates.Add(coordinate + Vector2Int.right);
            coordinates.Add(coordinate + Vector2Int.down);
            coordinates.Add(coordinate + Vector2Int.left);
        }

        return coordinates.Count > 0 ? coordinates : null;
    }

    private bool ResolvePipePreviewBlueprintAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore)
    {
        if (activeInstallDefinition == null || !(activeInstallDefinition.mapObject is Pipe))
        {
            return false;
        }

        if (!TryGetInstallPreviewAtCoordinate(coordinate, out MapObject preview)
            || preview == null
            || preview == previewToIgnore
            || !(preview is Pipe))
        {
            return false;
        }

        return RefreshSinglePipePreviewVariant(
            preview,
            coordinate,
            previewToIgnore);
    }

    private static bool ContainsCoordinate(IReadOnlyCollection<Vector2Int> coordinates, Vector2Int coordinate)
    {
        if (coordinates == null)
        {
            return false;
        }

        foreach (Vector2Int candidate in coordinates)
        {
            if (candidate == coordinate)
            {
                return true;
            }
        }

        return false;
    }

    private void RefreshInstalledFenceVariantPreviews(
        IReadOnlyList<Vector2Int> changedCoordinates = null,
        MapObject previewToIgnore = null)
    {
        CleanupInstalledFenceVariantPreviewReferences();
        if (IsEditingInstallation()
            || activeInstallDefinition == null
            || !(activeInstallDefinition.mapObject is Wall fencePrototype)
            || installPreviewInstances.Count <= 0)
        {
            RemoveInstalledFenceVariantPreviews(null);
            return;
        }

        HashSet<Vector2Int> affectedCoordinates = BuildFenceVariantRefreshCoordinates(changedCoordinates, true)
                                                 ?? BuildInstalledFenceVariantPreviewRefreshCoordinates();
        if (affectedCoordinates == null || affectedCoordinates.Count <= 0)
        {
            RemoveInstalledFenceVariantPreviews(null);
            return;
        }

        Dictionary<Wall, InstalledFenceVariantPreviewPlan> desiredPreviewsByFence =
            new Dictionary<Wall, InstalledFenceVariantPreviewPlan>();
        foreach (Vector2Int coordinate in affectedCoordinates)
        {
            if (TryResolveInstalledFenceVariantPreview(
                    coordinate,
                    fencePrototype,
                    previewToIgnore,
                    out InstalledFenceVariantPreviewPlan plan)
                && plan != null
                && plan.installedFence != null)
            {
                desiredPreviewsByFence[plan.installedFence] = plan;
            }
        }

        List<Wall> existingPreviewOwners = new List<Wall>(installedFenceVariantPreviews.Keys);
        for (int i = 0; i < existingPreviewOwners.Count; i++)
        {
            Wall installedFence = existingPreviewOwners[i];
            if (installedFence == null)
            {
                RemoveInstalledFenceVariantPreview(installedFence);
                continue;
            }

            if (!installedFence.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out _)
                || !affectedCoordinates.Contains(anchorCoordinate))
            {
                continue;
            }

            if (!desiredPreviewsByFence.TryGetValue(installedFence, out InstalledFenceVariantPreviewPlan plan))
            {
                RemoveInstalledFenceVariantPreview(installedFence);
                continue;
            }

            UpdateInstalledFenceVariantPreview(plan);
            desiredPreviewsByFence.Remove(installedFence);
        }

        foreach (InstalledFenceVariantPreviewPlan plan in desiredPreviewsByFence.Values)
        {
            UpdateInstalledFenceVariantPreview(plan);
        }
    }

    private HashSet<Vector2Int> BuildInstalledFenceVariantPreviewRefreshCoordinates()
    {
        HashSet<Vector2Int> coordinates = new HashSet<Vector2Int>();
        CleanupInstallPreviewReferences();
        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            MapObject preview = installPreviewInstances[i];
            if (!(preview is Wall)
                || !TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate))
            {
                continue;
            }

            AddFenceVariantRefreshCoordinates(coordinates, anchorCoordinate, true);
        }

        List<Wall> existingPreviewOwners = new List<Wall>(installedFenceVariantPreviews.Keys);
        for (int i = 0; i < existingPreviewOwners.Count; i++)
        {
            Wall installedFence = existingPreviewOwners[i];
            if (installedFence == null
                || !installedFence.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out _))
            {
                continue;
            }

            coordinates.Add(anchorCoordinate);
        }

        return coordinates.Count > 0 ? coordinates : null;
    }

    private static void AddFenceVariantRefreshCoordinates(HashSet<Vector2Int> coordinates, Vector2Int coordinate, bool includeSelf)
    {
        if (coordinates == null)
        {
            return;
        }

        if (includeSelf)
        {
            coordinates.Add(coordinate);
        }

        coordinates.Add(coordinate + Vector2Int.up);
        coordinates.Add(coordinate + Vector2Int.right);
        coordinates.Add(coordinate + Vector2Int.down);
        coordinates.Add(coordinate + Vector2Int.left);
    }

    private void AddPipeConnectorVariantRefreshCoordinatesForWorldCoordinate(
        HashSet<Vector2Int> coordinates,
        Vector2Int coordinate,
        bool includeSelf,
        MapObject previewToIgnore = null)
    {
        AddFenceVariantRefreshCoordinates(coordinates, coordinate, includeSelf);
        if (coordinates == null)
        {
            return;
        }

        if (TryGetPreviewPlacementSnapshot(coordinate, previewToIgnore, out PlacementSnapshot previewSnapshot)
            && previewSnapshot?.mapObject != null
            && IsPipeConnectorObject(previewSnapshot.mapObject))
        {
            AddPipeConnectorVariantRefreshCoordinates(
                coordinates,
                previewSnapshot.anchorCoordinate,
                previewSnapshot.mapObject,
                previewSnapshot.quarterTurns,
                true);
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain != null
            && terrain.TryGetLoadedBlock(coordinate, out Block block)
            && block != null
            && block.MapObject != null
            && IsPipeConnectorObject(block.MapObject)
            && block.MapObject is InstallationObject installationObject
            && installationObject.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out int quarterTurns))
        {
            AddPipeConnectorVariantRefreshCoordinates(
                coordinates,
                anchorCoordinate,
                block.MapObject,
                quarterTurns,
                true);
        }

        if (TryGetSavedPlacementSnapshot(coordinate, out PlacementSnapshot savedSnapshot)
            && savedSnapshot?.mapObject != null
            && IsPipeConnectorObject(savedSnapshot.mapObject))
        {
            AddPipeConnectorVariantRefreshCoordinates(
                coordinates,
                savedSnapshot.anchorCoordinate,
                savedSnapshot.mapObject,
                savedSnapshot.quarterTurns,
                true);
        }
    }

    private void AddPipeConnectorVariantRefreshCoordinates(
        HashSet<Vector2Int> coordinates,
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        bool includeSelf)
    {
        AddFenceVariantRefreshCoordinates(coordinates, anchorCoordinate, includeSelf);
        if (coordinates == null || footprintSource == null)
        {
            return;
        }

        List<Vector2Int> footprintCoordinates = GetFootprintCoordinates(
            anchorCoordinate,
            footprintSource,
            quarterTurns);
        for (int i = 0; i < footprintCoordinates.Count; i++)
        {
            AddFenceVariantRefreshCoordinates(coordinates, footprintCoordinates[i], true);
        }

        if (!TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return;
        }

        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (placements == null)
        {
            return;
        }

        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (!InputOutputModule.AllowsPipeAreaInteraction(placement.blockType)
                || !TryGetRectGridCoordinate(
                    anchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    placement,
                    out Vector2Int pipeAreaCoordinate))
            {
                continue;
            }

            AddFenceVariantRefreshCoordinates(coordinates, pipeAreaCoordinate, true);
        }
    }

    private bool TryResolveInstalledFenceVariantPreview(
        Vector2Int coordinate,
        Wall fencePrototype,
        MapObject previewToIgnore,
        out InstalledFenceVariantPreviewPlan plan)
    {
        plan = null;
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null
            || !terrain.TryGetLoadedBlock(coordinate, out Block block)
            || block == null
            || !(block.MapObject is Wall installedFence)
            || installedFence == null
            || !installedFence.gameObject.activeInHierarchy
            || !installedFence.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out int currentQuarterTurns)
            || anchorCoordinate != coordinate)
        {
            return false;
        }

        Wall sourcePrototype = installedFence.StraightVariantPrefab != null
            ? installedFence.StraightVariantPrefab
            : fencePrototype != null && fencePrototype.StraightVariantPrefab != null
                ? fencePrototype.StraightVariantPrefab
                : fencePrototype != null
                    ? fencePrototype
                    : installedFence;
        if (!TryResolveFencePlacementVariant(
                sourcePrototype,
                anchorCoordinate,
                currentQuarterTurns,
                previewToIgnore,
                out MapObject desiredPrefab,
                out int desiredQuarterTurns)
            || !(desiredPrefab is Wall desiredFencePrefab))
        {
            return false;
        }

        Quaternion desiredRotation = GetInstalledObjectRotation(desiredFencePrefab, desiredQuarterTurns);
        Vector3 desiredFinalPosition = GetInstalledObjectWorldPosition(anchorCoordinate, desiredFencePrefab, desiredQuarterTurns);
        bool sameVariant = installedFence.VariantKind == desiredFencePrefab.VariantKind;
        bool sameRotation = Mathf.Abs(Quaternion.Dot(installedFence.transform.rotation, desiredRotation)) >= 0.9999f;
        bool samePosition = (installedFence.transform.position - desiredFinalPosition).sqrMagnitude <= 0.0001f;
        if (sameVariant && sameRotation && samePosition)
        {
            return false;
        }

        plan = new InstalledFenceVariantPreviewPlan
        {
            installedFence = installedFence,
            sourcePrefab = desiredFencePrefab,
            quarterTurns = NormalizePlacementQuarterTurns(desiredQuarterTurns),
            position = GetInstalledObjectWorldPosition(anchorCoordinate, desiredFencePrefab, desiredQuarterTurns),
            rotation = desiredRotation
        };
        return true;
    }

    private void UpdateInstalledFenceVariantPreview(InstalledFenceVariantPreviewPlan plan)
    {
        if (plan == null
            || plan.installedFence == null
            || plan.sourcePrefab == null)
        {
            return;
        }

        Wall installedFence = plan.installedFence;
        installedFenceVariantPreviews.TryGetValue(installedFence, out MapObject preview);
        installedFenceVariantPreviewSourcePrefabs.TryGetValue(installedFence, out MapObject currentSourcePrefab);
        bool requiresReplacement = preview == null
                                   || currentSourcePrefab != plan.sourcePrefab
                                   || RequiresFencePreviewReplacement(preview, plan.sourcePrefab);
        if (requiresReplacement)
        {
            DestroyInstallPreviewObject(preview);
            preview = Instantiate(plan.sourcePrefab);
            if (preview == null)
            {
                RemoveInstalledFenceVariantPreview(installedFence);
                return;
            }

            preview.name = $"{plan.sourcePrefab.name}_InstalledBlueprint";
            ConfigureInstallPreview(preview);
            installedFenceVariantPreviews[installedFence] = preview;
            installedFenceVariantPreviewSourcePrefabs[installedFence] = plan.sourcePrefab;
        }

        HideInstalledObjectForVariantPreview(installedFence, installedFencePreviewRendererStates);
        preview.transform.SetPositionAndRotation(plan.position, plan.rotation);
        if (preview is InstallationObject previewInstallation)
        {
            previewInstallation.RefreshInstalledDirectionFromCurrentTransform();
        }
    }

    private void RemoveInstalledFenceVariantPreviews(IReadOnlyCollection<Vector2Int> allowedCoordinates)
    {
        List<Wall> installedFences = new List<Wall>(installedFenceVariantPreviews.Keys);
        for (int i = 0; i < installedFences.Count; i++)
        {
            Wall installedFence = installedFences[i];
            if (installedFence != null
                && allowedCoordinates != null
                && installedFence.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out _)
                && ContainsCoordinate(allowedCoordinates, anchorCoordinate))
            {
                continue;
            }

            RemoveInstalledFenceVariantPreview(installedFence);
        }
    }

    private void RemoveInstalledFenceVariantPreview(Wall installedFence)
    {
        if (ReferenceEquals(installedFence, null))
        {
            return;
        }

        installedFenceVariantPreviews.TryGetValue(installedFence, out MapObject preview);
        DestroyInstallPreviewObject(preview);
        installedFenceVariantPreviews.Remove(installedFence);
        installedFenceVariantPreviewSourcePrefabs.Remove(installedFence);
        RestoreInstalledObjectPreviewRenderers(installedFence, installedFencePreviewRendererStates);
    }

    private void CleanupInstalledFenceVariantPreviewReferences()
    {
        CopyWallKeys(installedFenceVariantPreviews, cleanupWallScratch);
        for (int i = 0; i < cleanupWallScratch.Count; i++)
        {
            Wall installedFence = cleanupWallScratch[i];
            installedFenceVariantPreviews.TryGetValue(installedFence, out MapObject preview);
            bool ownerMissing = installedFence == null;
            bool ownerInactive = !ownerMissing && !installedFence.gameObject.activeInHierarchy;
            if (ownerMissing || ownerInactive || preview == null)
            {
                RemoveInstalledFenceVariantPreview(installedFence);
            }
        }

        CopyWallKeys(installedFencePreviewRendererStates, cleanupWallScratch);
        for (int i = 0; i < cleanupWallScratch.Count; i++)
        {
            Wall installedFence = cleanupWallScratch[i];
            if (installedFence == null || !installedFenceVariantPreviews.ContainsKey(installedFence))
            {
                RestoreInstalledObjectPreviewRenderers(installedFence, installedFencePreviewRendererStates);
            }
        }

        cleanupWallScratch.Clear();
    }

    private void RefreshPipeBlueprintTopology(
        IReadOnlyCollection<Vector2Int> changedCoordinates,
        MapObject previewToIgnore = null)
    {
        CleanupInstalledPipeVariantPreviewReferences();
        if (activeInstallDefinition == null
            || !IsPipeConnectorObject(activeInstallDefinition.mapObject)
            || installPreviewInstances.Count <= 0)
        {
            RemoveInstalledPipeVariantPreviews(null);
            return;
        }

        if (changedCoordinates == null || changedCoordinates.Count <= 0)
        {
            RemoveInstalledPipeVariantPreviews(null);
            return;
        }

        HashSet<Vector2Int> candidateCoordinates = changedCoordinates as HashSet<Vector2Int>
            ?? new HashSet<Vector2Int>(changedCoordinates);
        bool wasResolvingInstalledPipeVariantPreviewPlans = isResolvingInstalledPipeVariantPreviewPlans;
        installedPipeVariantResolutionOverrides.Clear();
        pipeBlueprintCandidateCoordinatesScratch.Clear();
        pipeBlueprintCandidateCoordinatesScratch.AddRange(candidateCoordinates);
        pipeBlueprintCandidateCoordinatesScratch.Sort(ComparePipeVariantCoordinates);
        isResolvingInstalledPipeVariantPreviewPlans = true;
        try
        {
            // Blueprint pipes are a virtual installation. Resolve newly placed
            // previews and existing installed pipes in the same deterministic order
            // as post-install normalization, then repeat until neither side changes.
            // The live map is not mutated merely to draw a preview.
            int maxPassCount = Mathf.Max(1, candidateCoordinates.Count);
            pipeVariantNormalizationStateHashesScratch.Clear();
            pipeVariantNormalizationStateHashesScratch.Add(
                ComputePipeVariantNormalizationStateHash(
                    pipeBlueprintCandidateCoordinatesScratch,
                    true));
            for (int pass = 0; pass < maxPassCount; pass++)
            {
                bool anyChanged = false;
                for (int coordinateIndex = 0;
                     coordinateIndex < pipeBlueprintCandidateCoordinatesScratch.Count;
                     coordinateIndex++)
                {
                    Vector2Int coordinate = pipeBlueprintCandidateCoordinatesScratch[coordinateIndex];
                    if (ResolvePipePreviewBlueprintAtCoordinate(
                            coordinate,
                            previewToIgnore))
                    {
                        anyChanged = true;
                    }

                    if (TryResolveInstalledPipeVariantPreview(
                            coordinate,
                            previewToIgnore,
                            out InstalledPipeVariantPreviewPlan plan))
                    {
                        if (SetInstalledPipeVariantResolutionOverride(plan))
                        {
                            anyChanged = true;
                        }
                    }
                }

                if (!anyChanged)
                {
                    break;
                }

                ulong stateHash = ComputePipeVariantNormalizationStateHash(
                    pipeBlueprintCandidateCoordinatesScratch,
                    true);
                if (!pipeVariantNormalizationStateHashesScratch.Add(stateHash))
                {
                    break;
                }
            }
        }
        finally
        {
            pipeVariantNormalizationStateHashesScratch.Clear();
            isResolvingInstalledPipeVariantPreviewPlans = wasResolvingInstalledPipeVariantPreviewPlans;
        }

        CopyPipeKeys(installedPipeVariantPreviews, cleanupPipeScratch);
        for (int i = 0; i < cleanupPipeScratch.Count; i++)
        {
            Pipe installedPipe = cleanupPipeScratch[i];
            if (installedPipe == null)
            {
                RemoveInstalledPipeVariantPreview(installedPipe);
                continue;
            }

            if (installedPipe.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out _)
                && !candidateCoordinates.Contains(anchorCoordinate))
            {
                continue;
            }

            if (!installedPipeVariantResolutionOverrides.TryGetValue(
                    installedPipe,
                    out InstalledPipeVariantPreviewPlan plan))
            {
                RemoveInstalledPipeVariantPreview(installedPipe);
                continue;
            }

            if (PipeVariantResolutionPlanMatchesInstalledPipe(plan))
            {
                RemoveInstalledPipeVariantPreview(installedPipe);
            }
            else
            {
                UpdateInstalledPipeVariantPreview(plan);
            }
            installedPipeVariantResolutionOverrides.Remove(installedPipe);
        }

        cleanupPipeScratch.Clear();
        foreach (InstalledPipeVariantPreviewPlan plan in installedPipeVariantResolutionOverrides.Values)
        {
            if (!PipeVariantResolutionPlanMatchesInstalledPipe(plan))
            {
                UpdateInstalledPipeVariantPreview(plan);
            }
        }

        installedPipeVariantResolutionOverrides.Clear();
        pipeBlueprintCandidateCoordinatesScratch.Clear();
        RestorePipeRenderersWithoutRenderableVariantPreview();
    }

    private bool SetInstalledPipeVariantResolutionOverride(
        InstalledPipeVariantPreviewPlan plan)
    {
        if (plan.installedPipe == null || plan.sourcePrefab == null)
        {
            return false;
        }

        if (installedPipeVariantResolutionOverrides.TryGetValue(
                plan.installedPipe,
                out InstalledPipeVariantPreviewPlan currentPlan)
            && PipeVariantResolutionPlansEqual(currentPlan, plan))
        {
            return false;
        }

        installedPipeVariantResolutionOverrides[plan.installedPipe] = plan;
        return true;
    }

    private static bool PipeVariantResolutionPlansEqual(
        InstalledPipeVariantPreviewPlan firstPlan,
        InstalledPipeVariantPreviewPlan secondPlan)
    {
        return firstPlan.sourcePrefab == secondPlan.sourcePrefab
               && NormalizePlacementQuarterTurns(firstPlan.quarterTurns)
               == NormalizePlacementQuarterTurns(secondPlan.quarterTurns)
               && Mathf.Abs(Quaternion.Dot(firstPlan.rotation, secondPlan.rotation)) >= 0.9999f;
    }

    private static bool PipeVariantResolutionPlanMatchesInstalledPipe(
        InstalledPipeVariantPreviewPlan plan)
    {
        return plan.installedPipe != null
               && plan.sourcePrefab is Pipe plannedPipe
               && plan.installedPipe.VariantKind == plannedPipe.VariantKind
               && Mathf.Abs(Quaternion.Dot(
                   plan.installedPipe.transform.rotation,
                   plan.rotation)) >= 0.9999f
               && (plan.installedPipe.transform.position - plan.position).sqrMagnitude <= 0.0001f;
    }

    private static int ComparePipeVariantCoordinates(Vector2Int first, Vector2Int second)
    {
        int xComparison = first.x.CompareTo(second.x);
        return xComparison != 0 ? xComparison : first.y.CompareTo(second.y);
    }

    private ulong ComputePipeVariantNormalizationStateHash(
        IReadOnlyList<Vector2Int> coordinates,
        bool useBlueprintState)
    {
        const ulong offsetBasis = 1469598103934665603UL;
        ulong hash = offsetBasis;
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        for (int coordinateIndex = 0;
             coordinates != null && coordinateIndex < coordinates.Count;
             coordinateIndex++)
        {
            Vector2Int coordinate = coordinates[coordinateIndex];
            hash = AppendPipeVariantStateHash(hash, coordinate.x);
            hash = AppendPipeVariantStateHash(hash, coordinate.y);

            Pipe pipe = null;
            Quaternion rotation = Quaternion.identity;
            if (useBlueprintState
                && TryGetInstallPreviewAtCoordinate(coordinate, out MapObject preview)
                && preview is Pipe previewPipe)
            {
                pipe = previewPipe;
                rotation = preview.transform.rotation;
            }
            else if (terrain != null
                     && terrain.TryGetLoadedBlock(coordinate, out Block block)
                     && block != null
                     && block.MapObject is Pipe installedPipe
                     && installedPipe != null
                     && installedPipe.gameObject.activeInHierarchy)
            {
                pipe = installedPipe;
                rotation = installedPipe.transform.rotation;
                if (useBlueprintState
                    && installedPipeVariantResolutionOverrides.TryGetValue(
                        installedPipe,
                        out InstalledPipeVariantPreviewPlan virtualPlan)
                    && virtualPlan.sourcePrefab is Pipe virtualPipe)
                {
                    pipe = virtualPipe;
                    rotation = virtualPlan.rotation;
                }
            }

            if (pipe == null)
            {
                hash = AppendPipeVariantStateHash(hash, -1);
                continue;
            }

            hash = AppendPipeVariantStateHash(hash, GetPipeVariantKind(pipe));
            hash = AppendPipeVariantStateHash(hash, pipe.GetConnectionMask(rotation));
            hash = AppendPipeVariantStateHash(
                hash,
                TryGetManualPipeConnectionMask(
                    pipe,
                    coordinate,
                    out int selectedConnectionMask)
                    ? selectedConnectionMask
                    : -1);
        }

        return hash;
    }

    private static ulong AppendPipeVariantStateHash(ulong hash, int value)
    {
        const ulong prime = 1099511628211UL;
        unchecked
        {
            hash ^= (uint)value;
            return hash * prime;
        }
    }

    private HashSet<Vector2Int> BuildPipeVariantRefreshCoordinates(
        IReadOnlyList<Vector2Int> changedCoordinates,
        bool includeSelf,
        MapObject previewToIgnore)
    {
        if (changedCoordinates == null || changedCoordinates.Count <= 0)
        {
            return null;
        }

        HashSet<Vector2Int> coordinates = new HashSet<Vector2Int>();
        for (int i = 0; i < changedCoordinates.Count; i++)
        {
            AddPipeConnectorVariantRefreshCoordinatesForWorldCoordinate(
                coordinates,
                changedCoordinates[i],
                includeSelf,
                previewToIgnore);
        }

        return coordinates.Count > 0 ? coordinates : null;
    }

    private bool TryResolveInstalledPipeVariantPreview(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out InstalledPipeVariantPreviewPlan plan)
    {
        plan = default;
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null
            || !terrain.TryGetLoadedBlock(coordinate, out Block block)
            || block == null
            || !(block.MapObject is Pipe installedPipe)
            || installedPipe == null
            || installedPipe is UndergroundPipe
            || !installedPipe.gameObject.activeInHierarchy
            || !installedPipe.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out int currentQuarterTurns)
            || anchorCoordinate != coordinate)
        {
            return false;
        }

        Pipe currentPipe = installedPipe;
        Quaternion currentRotation = installedPipe.transform.rotation;
        if (isResolvingInstalledPipeVariantPreviewPlans
            && installedPipeVariantResolutionOverrides.TryGetValue(
                installedPipe,
                out InstalledPipeVariantPreviewPlan currentPlan)
            && currentPlan.sourcePrefab is Pipe currentPlanPipe)
        {
            currentPipe = currentPlanPipe;
            currentRotation = currentPlan.rotation;
            currentQuarterTurns = currentPlan.quarterTurns;
        }

        Pipe sourcePrototype = currentPipe.StraightVariantPrefab != null
            ? currentPipe.StraightVariantPrefab
            : currentPipe;
        int baselineConnectionMask = currentPipe.GetConnectionMask(currentRotation);
        if (!TryResolvePipePlacementVariantWithCompatibleAdjacency(
                sourcePrototype,
                anchorCoordinate,
                currentQuarterTurns,
                previewToIgnore,
                baselineConnectionMask,
                out MapObject desiredPrefab,
                out int desiredQuarterTurns)
            || !(desiredPrefab is Pipe desiredPipePrefab))
        {
            return false;
        }

        Quaternion desiredRotation = GetInstalledObjectRotation(desiredPipePrefab, desiredQuarterTurns);
        Vector3 desiredFinalPosition = GetInstalledObjectWorldPosition(anchorCoordinate, desiredPipePrefab, desiredQuarterTurns);
        plan = new InstalledPipeVariantPreviewPlan
        {
            installedPipe = installedPipe,
            sourcePrefab = desiredPipePrefab,
            quarterTurns = NormalizePlacementQuarterTurns(desiredQuarterTurns),
            position = desiredFinalPosition,
            rotation = desiredRotation
        };
        return true;
    }

    private void UpdateInstalledPipeVariantPreview(InstalledPipeVariantPreviewPlan plan)
    {
        if (plan.installedPipe == null
            || plan.sourcePrefab == null)
        {
            return;
        }

        Pipe installedPipe = plan.installedPipe;
        installedPipeVariantPreviews.TryGetValue(installedPipe, out MapObject preview);
        installedPipeVariantPreviewPlans.TryGetValue(
            installedPipe,
            out InstalledPipeVariantPreviewPlan currentPlan);
        MapObject currentSourcePrefab = currentPlan.sourcePrefab;
        bool requiresReplacement = preview == null
                                   || currentSourcePrefab != plan.sourcePrefab
                                   || RequiresPipePreviewReplacement(preview, plan.sourcePrefab);
        if (requiresReplacement)
        {
            MapObject previousPreview = preview;
            MapObject replacementPreview = Instantiate(plan.sourcePrefab);
            if (replacementPreview == null)
            {
                RemoveInstalledPipeVariantPreview(installedPipe);
                return;
            }

            replacementPreview.name = $"{plan.sourcePrefab.name}_InstalledBlueprint";
            ConfigureInstallPreview(replacementPreview);
            replacementPreview.transform.SetPositionAndRotation(plan.position, plan.rotation);
            if (replacementPreview is InstallationObject replacementInstallation)
            {
                replacementInstallation.RefreshInstalledDirectionFromCurrentTransform();
            }

            installedPipeVariantPreviews[installedPipe] = replacementPreview;
            installedPipeVariantPreviewPlans[installedPipe] = plan;
            HideInstalledPipeForVariantPreview(installedPipe, replacementPreview);
            DestroyInstallPreviewObject(previousPreview);
            return;
        }

        preview.transform.SetPositionAndRotation(plan.position, plan.rotation);
        if (preview is InstallationObject previewInstallation)
        {
            previewInstallation.RefreshInstalledDirectionFromCurrentTransform();
        }

        installedPipeVariantPreviewPlans[installedPipe] = plan;
        HideInstalledPipeForVariantPreview(installedPipe, preview);
    }

    private List<InstalledPipeVariantPreviewPlan> CaptureInstalledPipeVariantPreviewPlans()
    {
        List<InstalledPipeVariantPreviewPlan> plans =
            new List<InstalledPipeVariantPreviewPlan>(installedPipeVariantPreviewPlans.Count);
        foreach (KeyValuePair<Pipe, InstalledPipeVariantPreviewPlan> entry
                 in installedPipeVariantPreviewPlans)
        {
            Pipe installedPipe = entry.Key;
            if (installedPipe != null
                && installedPipeVariantPreviews.ContainsKey(installedPipe))
            {
                plans.Add(entry.Value);
            }
        }

        return plans;
    }

    private void RemoveInstalledPipeVariantPreviews(IReadOnlyCollection<Vector2Int> allowedCoordinates)
    {
        List<Pipe> installedPipes = new List<Pipe>(installedPipeVariantPreviews.Keys);
        for (int i = 0; i < installedPipes.Count; i++)
        {
            Pipe installedPipe = installedPipes[i];
            if (installedPipe != null
                && allowedCoordinates != null
                && installedPipe.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out _)
                && ContainsCoordinate(allowedCoordinates, anchorCoordinate))
            {
                continue;
            }

            RemoveInstalledPipeVariantPreview(installedPipe);
        }
    }

    private void RemoveInstalledPipeVariantPreview(Pipe installedPipe)
    {
        if (ReferenceEquals(installedPipe, null))
        {
            return;
        }

        installedPipeVariantPreviews.TryGetValue(installedPipe, out MapObject preview);
        installedPipeVariantPreviews.Remove(installedPipe);
        installedPipeVariantPreviewPlans.Remove(installedPipe);
        RestoreInstalledObjectPreviewRenderers(installedPipe, installedPipePreviewRendererStates);
        DestroyInstallPreviewObject(preview);
    }

    private void CleanupInstalledPipeVariantPreviewReferences()
    {
        CopyPipeKeys(installedPipeVariantPreviews, cleanupPipeScratch);
        for (int i = 0; i < cleanupPipeScratch.Count; i++)
        {
            Pipe installedPipe = cleanupPipeScratch[i];
            installedPipeVariantPreviews.TryGetValue(installedPipe, out MapObject preview);
            bool ownerMissing = installedPipe == null;
            bool ownerInactive = !ownerMissing && !installedPipe.gameObject.activeInHierarchy;
            bool ownerDoesNotUseVariants = !ownerMissing && installedPipe is UndergroundPipe;
            if (ownerMissing || ownerInactive || ownerDoesNotUseVariants || preview == null)
            {
                RemoveInstalledPipeVariantPreview(installedPipe);
            }
        }

        CopyPipeKeys(installedPipePreviewRendererStates, cleanupPipeScratch);
        for (int i = 0; i < cleanupPipeScratch.Count; i++)
        {
            Pipe installedPipe = cleanupPipeScratch[i];
            if (installedPipe == null || !installedPipeVariantPreviews.ContainsKey(installedPipe))
            {
                RestoreInstalledObjectPreviewRenderers(installedPipe, installedPipePreviewRendererStates);
            }
        }

        cleanupPipeScratch.Clear();
    }

    private void HideInstalledPipeForVariantPreview(Pipe installedPipe, MapObject preview)
    {
        if (HasRenderableVariantPreview(preview))
        {
            installedPipe.SetVariantPreviewFluidDisplaySuppressed(true);
            HideInstalledObjectForVariantPreview(installedPipe, installedPipePreviewRendererStates);
            return;
        }

        RestoreInstalledObjectPreviewRenderers(installedPipe, installedPipePreviewRendererStates);
    }

    private void RestorePipeRenderersWithoutRenderableVariantPreview()
    {
        CopyPipeKeys(installedPipePreviewRendererStates, cleanupPipeScratch);
        for (int i = 0; i < cleanupPipeScratch.Count; i++)
        {
            Pipe installedPipe = cleanupPipeScratch[i];
            bool hasRenderablePreview = installedPipe != null
                                        && installedPipeVariantPreviews.TryGetValue(installedPipe, out MapObject preview)
                                        && HasRenderableVariantPreview(preview);
            if (!hasRenderablePreview)
            {
                RestoreInstalledObjectPreviewRenderers(installedPipe, installedPipePreviewRendererStates);
            }
        }

        cleanupPipeScratch.Clear();
    }

    private static bool HasRenderableVariantPreview(MapObject preview)
    {
        if (preview == null || !preview.gameObject.activeInHierarchy)
        {
            return false;
        }

        Renderer[] renderers = preview.GetComponentsInChildren<Renderer>(true);
        for (int i = 0; i < renderers.Length; i++)
        {
            Renderer renderer = renderers[i];
            if (renderer != null && renderer.enabled && renderer.gameObject.activeInHierarchy)
            {
                return true;
            }
        }

        return false;
    }

    private static void CopyWallKeys<TValue>(Dictionary<Wall, TValue> dictionary, List<Wall> target)
    {
        target.Clear();
        if (dictionary == null || dictionary.Count <= 0)
        {
            return;
        }

        foreach (KeyValuePair<Wall, TValue> entry in dictionary)
        {
            target.Add(entry.Key);
        }
    }

    private static void CopyPipeKeys<TValue>(Dictionary<Pipe, TValue> dictionary, List<Pipe> target)
    {
        target.Clear();
        if (dictionary == null || dictionary.Count <= 0)
        {
            return;
        }

        foreach (KeyValuePair<Pipe, TValue> entry in dictionary)
        {
            target.Add(entry.Key);
        }
    }

    private static void HideInstalledObjectForVariantPreview<TInstallation>(
        TInstallation installedObject,
        Dictionary<TInstallation, List<RendererVisibilityState>> rendererStatesByObject)
        where TInstallation : MapObject
    {
        if (installedObject == null
            || rendererStatesByObject == null
            || rendererStatesByObject.ContainsKey(installedObject))
        {
            return;
        }

        List<RendererVisibilityState> rendererStates = CaptureAndHideRendererVisibility(installedObject);
        rendererStatesByObject[installedObject] = rendererStates;
    }

    private static List<RendererVisibilityState> CaptureAndHideRendererVisibility(MapObject installedObject)
    {
        if (installedObject == null)
        {
            return null;
        }

        Renderer[] renderers = installedObject.GetComponentsInChildren<Renderer>(true);
        List<RendererVisibilityState> rendererStates = new List<RendererVisibilityState>(renderers.Length);
        for (int i = 0; i < renderers.Length; i++)
        {
            Renderer renderer = renderers[i];
            if (renderer == null)
            {
                continue;
            }

            rendererStates.Add(new RendererVisibilityState
            {
                renderer = renderer,
                enabled = renderer.enabled
            });
            renderer.enabled = false;
        }

        return rendererStates;
    }

    private static void RestoreRendererVisibility(List<RendererVisibilityState> rendererStates)
    {
        if (rendererStates == null)
        {
            return;
        }

        for (int i = 0; i < rendererStates.Count; i++)
        {
            RendererVisibilityState rendererState = rendererStates[i];
            if (rendererState == null || rendererState.renderer == null)
            {
                continue;
            }

            rendererState.renderer.enabled = rendererState.enabled;
        }
    }

    private static void RestoreInstalledObjectPreviewRenderers<TInstallation>(
        TInstallation installedObject,
        Dictionary<TInstallation, List<RendererVisibilityState>> rendererStatesByObject)
        where TInstallation : MapObject
    {
        if (ReferenceEquals(installedObject, null)
            || rendererStatesByObject == null
            || !rendererStatesByObject.TryGetValue(installedObject, out List<RendererVisibilityState> rendererStates))
        {
            return;
        }

        RestoreRendererVisibility(rendererStates);
        rendererStatesByObject.Remove(installedObject);
        if (installedObject is Pipe pipe)
        {
            pipe.SetVariantPreviewFluidDisplaySuppressed(false);
        }
    }

    private void DestroyInstallPreviewObject(MapObject preview)
    {
        if (preview == null)
        {
            return;
        }

        UnregisterUtilityPolePreviewWire(preview);
        SetInstallPreviewSelectionVisual(preview, false);
        ReleaseBlueprintPreviewMaterials(preview);
        preview.gameObject.SetActive(false);
        if (Application.isPlaying)
        {
            Destroy(preview.gameObject);
        }
        else
        {
            DestroyImmediate(preview.gameObject);
        }
    }

    private static void ReleaseBlueprintPreviewMaterials(MapObject preview)
    {
        if (preview == null)
        {
            return;
        }

        blueprintPreviewMaterialReleaseScratch.Clear();
        Renderer[] renderers = preview.GetComponentsInChildren<Renderer>(true);
        for (int i = 0; i < renderers.Length; i++)
        {
            Renderer renderer = renderers[i];
            if (renderer == null)
            {
                continue;
            }

            Material[] materials = renderer.sharedMaterials;
            if (materials == null)
            {
                continue;
            }

            for (int materialIndex = 0; materialIndex < materials.Length; materialIndex++)
            {
                Material material = materials[materialIndex];
                if (!IsRuntimeBlueprintPreviewMaterial(material))
                {
                    continue;
                }

                materials[materialIndex] = null;
                blueprintPreviewMaterialReleaseScratch.Add(material);
            }

            renderer.sharedMaterials = materials;
        }

        foreach (Material material in blueprintPreviewMaterialReleaseScratch)
        {
            runtimeBlueprintPreviewMaterials.Remove(material);
            if (Application.isPlaying)
            {
                Destroy(material);
            }
            else
            {
                DestroyImmediate(material);
            }
        }

        blueprintPreviewMaterialReleaseScratch.Clear();
    }

    private static bool IsRuntimeBlueprintPreviewMaterial(Material material)
    {
        if (material == null)
        {
            return false;
        }

        if (runtimeBlueprintPreviewMaterials.Contains(material))
        {
            return true;
        }

        return (material.hideFlags & HideFlags.DontSave) != 0
               && material.name.EndsWith(BlueprintPreviewRuntimeMaterialSuffix);
    }

    private void RefreshActiveFencePreviewVariant(bool preserveActivePreviewQuarterTurns = false)
    {
        if (activeInstallDefinition == null || !(activeInstallDefinition.mapObject is Wall))
        {
            return;
        }

        if (activeInstallPreview == null || !TryGetPreviewAnchorCoordinate(activeInstallPreview, out Vector2Int anchorCoordinate))
        {
            return;
        }

        RefreshSingleFencePreviewVariant(
            activeInstallPreview,
            anchorCoordinate,
            null,
            preserveActivePreviewQuarterTurns);
    }

    private bool RefreshSingleFencePreviewVariant(
        MapObject preview,
        Vector2Int anchorCoordinate,
        MapObject previewToIgnore = null,
        bool preservePreviewQuarterTurns = false)
    {
        if (preview == null
            || activeInstallDefinition == null
            || !(activeInstallDefinition.mapObject is Wall fencePrototype))
        {
            return false;
        }

        int quarterTurns = GetPreviewQuarterTurns(preview);
        if (!TryResolveFencePlacementVariant(
                fencePrototype,
                anchorCoordinate,
                quarterTurns,
                preview,
                out MapObject desiredPrefab,
                out int resolvedQuarterTurns)
            || desiredPrefab == null)
        {
            return false;
        }

        bool shouldPreservePreviewQuarterTurns = preservePreviewQuarterTurns
            && IsFenceDoor(fencePrototype, preview)
            && !ShouldAutoAlignFenceDoorPreview(preview, anchorCoordinate);
        int normalizedResolvedQuarterTurns = shouldPreservePreviewQuarterTurns
            ? NormalizePlacementQuarterTurns(quarterTurns)
            : NormalizePlacementQuarterTurns(resolvedQuarterTurns);
        if (!RequiresFencePreviewReplacement(preview, desiredPrefab))
        {
            bool changed = false;
            if (NormalizePlacementQuarterTurns(quarterTurns) != normalizedResolvedQuarterTurns)
            {
                installPreviewQuarterTurnsByPreview[preview] = normalizedResolvedQuarterTurns;
                if (preview == activeInstallPreview)
                {
                    installPreviewQuarterTurns = normalizedResolvedQuarterTurns;
                }

                changed = true;
            }

            if (!installPreviewSourcePrefabsByPreview.TryGetValue(preview, out MapObject currentSourcePrefab)
                || currentSourcePrefab != desiredPrefab)
            {
                installPreviewSourcePrefabsByPreview[preview] = desiredPrefab;
                changed = true;
            }

            Quaternion desiredRotation = GetPlacementObjectRotation(desiredPrefab, normalizedResolvedQuarterTurns);
            if (Mathf.Abs(Quaternion.Dot(preview.transform.rotation, desiredRotation)) < 0.9999f)
            {
                preview.transform.rotation = desiredRotation;
                if (preview is InstallationObject installationPreview)
                {
                    installationPreview.RefreshInstalledDirectionFromCurrentTransform();
                }

                changed = true;
            }

            Vector3 desiredPosition = GetPlacementWorldPositionFromAnchorCoordinate(
                anchorCoordinate,
                desiredPrefab,
                normalizedResolvedQuarterTurns);
            if ((preview.transform.position - desiredPosition).sqrMagnitude > 0.0001f)
            {
                preview.transform.position = desiredPosition;
                changed = true;
            }

            if (changed)
            {
                RefreshInstallPreviewAreaMarkers(preview);
            }

            return changed;
        }

        MapObject replacementPreview = Instantiate(desiredPrefab);
        if (replacementPreview == null)
        {
            return false;
        }

        replacementPreview.name = $"{desiredPrefab.name}_Blueprint";
        ConfigureInstallPreview(replacementPreview);
        ReplaceInstallPreviewInstance(preview, replacementPreview, desiredPrefab, anchorCoordinate, normalizedResolvedQuarterTurns);
        return true;
    }

    private static bool RequiresFencePreviewReplacement(MapObject currentPreview, MapObject desiredPrefab)
    {
        if (!(currentPreview is Wall currentFence) || !(desiredPrefab is Wall desiredFence))
        {
            return false;
        }

        return currentFence.VariantKind != desiredFence.VariantKind;
    }

    private void MaterializeActivePipeManualConnectionSelection()
    {
        if (activeInstallDefinition == null
            || !(activeInstallDefinition.mapObject is Pipe)
            || activeInstallDefinition.mapObject is UndergroundPipe
            || !(activeInstallPreview is Pipe activePipePreview)
            || activePipePreview is UndergroundPipe
            || !TryGetPreviewAnchorCoordinate(
                activeInstallPreview,
                out Vector2Int anchorCoordinate)
            || !TryGetManualPipeConnectionMask(
                anchorCoordinate,
                activeInstallPreview,
                out _))
        {
            return;
        }

        // First materialize the selected direction on the active preview. The
        // rotation handler then resolves the complete blueprint topology so every
        // affected preview already shows the shape that commit will capture.
        RefreshSinglePipePreviewVariant(
            activeInstallPreview,
            anchorCoordinate,
            activeInstallPreview);
    }

    private bool RefreshSinglePipePreviewVariant(
        MapObject preview,
        Vector2Int anchorCoordinate,
        MapObject previewToIgnore = null)
    {
        if (preview == null
            || activeInstallDefinition == null
            || !(activeInstallDefinition.mapObject is Pipe pipePrototype))
        {
            return false;
        }

        if (preview is UndergroundPipe || pipePrototype is UndergroundPipe)
        {
            return false;
        }

        int quarterTurns = GetPreviewQuarterTurns(preview);
        MapObject ignoredPreview = previewToIgnore ?? preview;
        int baselineConnectionMask = preview is Pipe previewPipe
            ? previewPipe.GetConnectionMask(preview.transform.rotation)
            : 0;
        if (!TryResolvePipePlacementVariantWithCompatibleAdjacency(
                pipePrototype,
                anchorCoordinate,
                quarterTurns,
                ignoredPreview,
                baselineConnectionMask,
                out MapObject desiredPrefab,
                out int resolvedQuarterTurns)
            || desiredPrefab == null)
        {
            return false;
        }

        int normalizedResolvedQuarterTurns = NormalizePlacementQuarterTurns(resolvedQuarterTurns);
        if (!RequiresPipePreviewReplacement(preview, desiredPrefab))
        {
            bool changed = false;
            if (NormalizePlacementQuarterTurns(quarterTurns) != normalizedResolvedQuarterTurns)
            {
                installPreviewQuarterTurnsByPreview[preview] = normalizedResolvedQuarterTurns;
                if (preview == activeInstallPreview)
                {
                    installPreviewQuarterTurns = normalizedResolvedQuarterTurns;
                }

                changed = true;
            }

            if (!installPreviewSourcePrefabsByPreview.TryGetValue(preview, out MapObject currentSourcePrefab)
                || currentSourcePrefab != desiredPrefab)
            {
                installPreviewSourcePrefabsByPreview[preview] = desiredPrefab;
                changed = true;
            }

            Quaternion desiredRotation = GetPlacementObjectRotation(desiredPrefab, normalizedResolvedQuarterTurns);
            if (Mathf.Abs(Quaternion.Dot(preview.transform.rotation, desiredRotation)) < 0.9999f)
            {
                preview.transform.rotation = desiredRotation;
                if (preview is InstallationObject installationPreview)
                {
                    installationPreview.RefreshInstalledDirectionFromCurrentTransform();
                }

                changed = true;
            }

            Vector3 desiredPosition = GetPlacementWorldPositionFromAnchorCoordinate(
                anchorCoordinate,
                desiredPrefab,
                normalizedResolvedQuarterTurns);
            if ((preview.transform.position - desiredPosition).sqrMagnitude > 0.0001f)
            {
                preview.transform.position = desiredPosition;
                changed = true;
            }

            if (changed)
            {
                RefreshInstallPreviewAreaMarkers(preview);
            }

            return changed;
        }

        MapObject replacementPreview = Instantiate(desiredPrefab);
        if (replacementPreview == null)
        {
            return false;
        }

        replacementPreview.name = $"{desiredPrefab.name}_Blueprint";
        ConfigureInstallPreview(replacementPreview);
        ReplaceInstallPreviewInstance(preview, replacementPreview, desiredPrefab, anchorCoordinate, normalizedResolvedQuarterTurns);
        return true;
    }

    private static bool RequiresPipePreviewReplacement(MapObject currentPreview, MapObject desiredPrefab)
    {
        if (!(currentPreview is Pipe currentPipe) || !(desiredPrefab is Pipe desiredPipe))
        {
            return false;
        }

        return currentPipe.VariantKind != desiredPipe.VariantKind;
    }

    private void RefreshActiveConveyorPreviewVariant(MapObject previewToIgnore = null)
    {
        if (activeInstallDefinition == null
            || !(activeInstallDefinition.mapObject is ConveyorBelt)
            || IsBelt2F(activeInstallDefinition.mapObject))
        {
            return;
        }

        if (activeInstallPreview == null || !TryGetPreviewAnchorCoordinate(activeInstallPreview, out Vector2Int anchorCoordinate))
        {
            return;
        }

        RefreshSingleConveyorPreviewVariant(
            activeInstallPreview,
            anchorCoordinate,
            previewToIgnore);
    }

    private bool RefreshSingleConveyorPreviewVariant(
        MapObject preview,
        Vector2Int anchorCoordinate,
        MapObject previewToIgnore = null)
    {
        if (preview == null || activeInstallDefinition == null)
        {
            return false;
        }

        int quarterTurns = GetPreviewQuarterTurns(preview);
        MapObject manualSourcePrefab = ResolveInstallPreviewFootprintSource(preview);
        if (IsBelt2F(activeInstallDefinition.mapObject))
        {
            installPreviewSourcePrefabsByPreview[preview] = activeInstallDefinition.mapObject;
            return false;
        }

        if (activeInstallDefinition.mapObject is ConveyorBelt conveyorPrototype)
        {
            manualSourcePrefab = ResolveConveyorPreviewSourceForAnchor(
                conveyorPrototype,
                manualSourcePrefab,
                anchorCoordinate,
                quarterTurns,
                preview);
            if (TryResolveActiveConveyorCornerPromotion(
                    conveyorPrototype,
                    manualSourcePrefab,
                    anchorCoordinate,
                    quarterTurns,
                    preview,
                    out MapObject promotedConveyorPrefab,
                    out int promotedConveyorQuarterTurns))
            {
                manualSourcePrefab = promotedConveyorPrefab;
                quarterTurns = promotedConveyorQuarterTurns;
            }
        }

        return ApplyConveyorPreviewVariant(preview, manualSourcePrefab, anchorCoordinate, quarterTurns);
    }

    private bool ApplyConveyorPreviewVariant(
        MapObject preview,
        MapObject desiredPrefab,
        Vector2Int anchorCoordinate,
        int resolvedQuarterTurns)
    {
        if (preview == null || desiredPrefab == null)
        {
            return false;
        }

        int normalizedResolvedQuarterTurns = NormalizePlacementQuarterTurns(resolvedQuarterTurns);
        if (!RequiresConveyorPreviewReplacement(preview, desiredPrefab))
        {
            bool changed = false;
            int currentQuarterTurns = GetPreviewQuarterTurns(preview);
            if (NormalizePlacementQuarterTurns(currentQuarterTurns) != normalizedResolvedQuarterTurns)
            {
                changed = true;
            }

            installPreviewQuarterTurnsByPreview[preview] = normalizedResolvedQuarterTurns;
            if (!installPreviewSourcePrefabsByPreview.TryGetValue(preview, out MapObject currentSourcePrefab)
                || currentSourcePrefab != desiredPrefab)
            {
                changed = true;
            }

            installPreviewSourcePrefabsByPreview[preview] = desiredPrefab;
            if (preview == activeInstallPreview)
            {
                installPreviewQuarterTurns = normalizedResolvedQuarterTurns;
                installPreviewConveyorVariantMode = GetConveyorPreviewVariantMode(desiredPrefab);
            }

            installPreviewAnchorCoordinates[preview] = anchorCoordinate;
            Quaternion desiredRotation = wasActivePreviewRotation(preview);
            if (Mathf.Abs(Quaternion.Dot(preview.transform.rotation, desiredRotation)) < 0.9999f)
            {
                preview.transform.rotation = desiredRotation;
                if (preview is InstallationObject installationPreview)
                {
                    installationPreview.RefreshInstalledDirectionFromCurrentTransform();
                }

                changed = true;
            }

            Vector3 desiredPosition = GetPlacementWorldPositionFromAnchorCoordinate(
                anchorCoordinate,
                desiredPrefab,
                normalizedResolvedQuarterTurns);
            if ((preview.transform.position - desiredPosition).sqrMagnitude > 0.0001f)
            {
                preview.transform.position = desiredPosition;
                changed = true;
            }

            if (changed)
            {
                RefreshInstallPreviewAreaMarkers(preview);
            }

            return changed;
        }

        MapObject replacementPreview = Instantiate(desiredPrefab);
        if (replacementPreview == null)
        {
            return false;
        }

        replacementPreview.name = $"{desiredPrefab.name}_Blueprint";
        ConfigureInstallPreview(replacementPreview);
        ReplaceInstallPreviewInstance(
            preview,
            replacementPreview,
            desiredPrefab,
            anchorCoordinate,
            normalizedResolvedQuarterTurns);
        return true;
    }

    private static bool RequiresConveyorPreviewReplacement(MapObject currentPreview, MapObject desiredPrefab)
    {
        if (!(currentPreview is ConveyorBelt currentConveyor) || !(desiredPrefab is ConveyorBelt desiredConveyor))
        {
            return false;
        }

        return currentConveyor.IsCornerVariant != desiredConveyor.IsCornerVariant
               || currentConveyor.IsReverseCornerVariant != desiredConveyor.IsReverseCornerVariant;
    }

    private void ReplaceInstallPreviewInstance(MapObject currentPreview, MapObject replacementPreview, MapObject replacementSourcePrefab, Vector2Int anchorCoordinate, int quarterTurns)
    {
        if (currentPreview == null || replacementPreview == null)
        {
            return;
        }

        int previewIndex = installPreviewInstances.IndexOf(currentPreview);
        Vector3 currentPosition = currentPreview.transform.position;
        int resolvedQuarterTurns = quarterTurns;
        Quaternion replacementBaseRotation = replacementSourcePrefab != null
            ? replacementSourcePrefab.transform.rotation
            : replacementPreview.transform.rotation;
        bool wasActivePreview = activeInstallPreview == currentPreview;
        bool wasPointerOriginPreview = previewPointerOriginPreview == currentPreview;

        SetInstallPreviewSelectionVisual(currentPreview, false);

        if (previewIndex >= 0)
        {
            installPreviewInstances[previewIndex] = replacementPreview;
        }
        else
        {
            installPreviewInstances.Add(replacementPreview);
        }

        installPreviewQuarterTurnsByPreview.Remove(currentPreview);
        installPreviewQuarterTurnsByPreview[replacementPreview] = resolvedQuarterTurns;
        installPreviewBaseRotationsByPreview.Remove(currentPreview);
        installPreviewBaseRotationsByPreview[replacementPreview] = replacementBaseRotation;
        if (installPreviewPlacementSequencesByPreview.TryGetValue(currentPreview, out long previewPlacementSequence))
        {
            installPreviewPlacementSequencesByPreview.Remove(currentPreview);
            installPreviewPlacementSequencesByPreview[replacementPreview] = previewPlacementSequence;
        }
        if (installPreviewConveyorRotationSequenceIndexesByPreview.TryGetValue(currentPreview, out int conveyorSequenceIndex))
        {
            installPreviewConveyorRotationSequenceIndexesByPreview.Remove(currentPreview);
            installPreviewConveyorRotationSequenceIndexesByPreview[replacementPreview] = NormalizeConveyorRotationSequenceIndex(conveyorSequenceIndex);
        }
        if (installPreviewPipeConnectionMasksByPreview.TryGetValue(
                currentPreview,
                out int pipeConnectionMask))
        {
            installPreviewPipeConnectionMasksByPreview.Remove(currentPreview);
            installPreviewPipeConnectionMasksByPreview[replacementPreview] =
                pipeConnectionMask;
        }
        if (installPreviewPipeSelectedSetDirectionsByPreview.TryGetValue(
                currentPreview,
                out Vector2Int selectedPipeSetDirection))
        {
            installPreviewPipeSelectedSetDirectionsByPreview.Remove(currentPreview);
            installPreviewPipeSelectedSetDirectionsByPreview[replacementPreview] =
                selectedPipeSetDirection;
        }
        installPreviewSourcePrefabsByPreview.Remove(currentPreview);
        installPreviewSourcePrefabsByPreview[replacementPreview] = replacementSourcePrefab != null ? replacementSourcePrefab : replacementPreview;
        if (installPreviewRailReferenceWorldPositions.TryGetValue(currentPreview, out Vector3 railReferenceWorldPosition))
        {
            installPreviewRailReferenceWorldPositions.Remove(currentPreview);
            installPreviewRailReferenceWorldPositions[replacementPreview] = railReferenceWorldPosition;
        }
        straightFirstConveyorPreviews.Remove(currentPreview);
        installPreviewAnchorCoordinates.Remove(currentPreview);
        installPreviewAnchorCoordinates[replacementPreview] = anchorCoordinate;
        if (installPreviewItemReservationsByPreview.TryGetValue(currentPreview, out InstallPreviewItemReservation reservation))
        {
            installPreviewItemReservationsByPreview.Remove(currentPreview);
            installPreviewItemReservationsByPreview[replacementPreview] = reservation;
        }

        replacementPreview.transform.SetPositionAndRotation(
            currentPosition,
            GetPlacementObjectRotation(
                replacementBaseRotation,
                replacementSourcePrefab != null ? replacementSourcePrefab : replacementPreview,
                resolvedQuarterTurns));
        if (replacementPreview is InstallationObject replacementInstallation)
        {
            replacementInstallation.RefreshInstalledDirectionFromCurrentTransform();
        }

        if (wasActivePreview)
        {
            activeInstallPreview = replacementPreview;
            installPreviewQuarterTurns = resolvedQuarterTurns;
            installPreviewConveyorVariantMode = GetConveyorPreviewVariantMode(replacementPreview);
            NormalizeInstallPreviewNativeRendering(replacementPreview);
            ResetInstallPreviewVisualSyncState();
            RefreshInstallPreviewSelectionVisuals();
        }

        if (wasPointerOriginPreview)
        {
            previewPointerOriginPreview = replacementPreview;
        }

        DestroyInstallPreviewObject(currentPreview);
    }

    private bool TryGetOrderedInputItemAreaBindings(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        InputOutputModule inputOutputModule,
        out List<InputOutputModuleItemAreaBinding> bindings,
        bool directOnly = false)
    {
        bindings = new List<InputOutputModuleItemAreaBinding>();
        if (footprintSource == null
            || inputOutputModule == null)
        {
            return false;
        }

        List<RectGridPlacementCell> cells = new List<RectGridPlacementCell>();
        if (!TryBuildRectGridPlacementCells(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                null,
                cells))
        {
            return false;
        }

        List<RectGridPlacementCell> inputItemCells = new List<RectGridPlacementCell>();
        for (int i = 0; i < cells.Count; i++)
        {
            RectGridPlacementCell cell = cells[i];
            if (!InputOutputModule.IsInputItemBlockType(cell.blockType)
                || (directOnly && !InputOutputModule.AllowsDirectAreaInteraction(cell.blockType)))
            {
                continue;
            }

            inputItemCells.Add(cell);
        }

        if (inputItemCells.Count <= 0)
        {
            return false;
        }

        inputItemCells.Sort(CompareInputItemPlacementCells);

        if (inputOutputModule is ProductionMachine productionMachine
            && TryGetProductionMachineInputItemAreaBindings(productionMachine, inputItemCells, bindings))
        {
            return true;
        }

        IReadOnlyList<InputOutputModule.ItemIoEntry> inputList = inputOutputModule.InputList;
        int recipeCount = inputList != null ? inputList.Count : 0;
        if (recipeCount <= 0)
        {
            return false;
        }

        bool useSharedSingleInputArea = inputItemCells.Count == 1 && recipeCount > 1;
        int bindingCount = useSharedSingleInputArea
            ? recipeCount
            : Mathf.Min(inputItemCells.Count, recipeCount);

        for (int i = 0; i < bindingCount; i++)
        {
            ItemDefinition itemDefinition = inputList[i].itemDefinition;
            if (itemDefinition == null || itemDefinition.id < 0)
            {
                continue;
            }

            RectGridPlacementCell cell = inputItemCells[useSharedSingleInputArea ? 0 : i];
            bindings.Add(new InputOutputModuleItemAreaBinding(cell.coordinate, itemDefinition.id));
        }

        return bindings.Count > 0;
    }

    private static bool TryGetProductionMachineInputItemAreaBindings(
        ProductionMachine productionMachine,
        IReadOnlyList<RectGridPlacementCell> inputItemCells,
        List<InputOutputModuleItemAreaBinding> bindings)
    {
        if (productionMachine == null
            || inputItemCells == null
            || inputItemCells.Count <= 0
            || bindings == null)
        {
            return false;
        }

        List<int> ingredientItemIds = new List<int>();
        if (!productionMachine.TryCollectProductionIngredientItemIds(ingredientItemIds))
        {
            return false;
        }

        for (int cellIndex = 0; cellIndex < inputItemCells.Count; cellIndex++)
        {
            RectGridPlacementCell cell = inputItemCells[cellIndex];
            for (int itemIndex = 0; itemIndex < ingredientItemIds.Count; itemIndex++)
            {
                int ingredientItemId = ingredientItemIds[itemIndex];
                if (ingredientItemId < 0)
                {
                    continue;
                }

                bindings.Add(new InputOutputModuleItemAreaBinding(cell.coordinate, ingredientItemId));
            }
        }

        return bindings.Count > 0;
    }

    private static int CompareInputItemPlacementCells(
        RectGridPlacementCell left,
        RectGridPlacementCell right)
    {
        return CompareInputItemPlacements(left.placement, right.placement);
    }

    private static int CompareInputItemPlacements(
        InputOutputModule.RectGridBlockPlacement left,
        InputOutputModule.RectGridBlockPlacement right)
    {
        if (left.y != right.y)
        {
            return right.y.CompareTo(left.y);
        }

        return left.x.CompareTo(right.x);
    }

    private static void AddAreaMarkerRequests(List<AreaMarkerSpawnRequest> markerRequests, IReadOnlyList<Vector3> worldPositions, Sprite icon)
    {
        if (markerRequests == null || worldPositions == null || worldPositions.Count <= 0)
        {
            return;
        }

        for (int i = 0; i < worldPositions.Count; i++)
        {
            markerRequests.Add(new AreaMarkerSpawnRequest(worldPositions[i], icon));
        }
    }

    private static void AddDirectionalAreaMarkerRequests(
        List<AreaMarkerSpawnRequest> markerRequests,
        IReadOnlyList<Vector3> worldPositions,
        Sprite icon,
        IReadOnlyList<Vector3> referenceWorldPositions,
        bool pointFromReferenceToMarker)
    {
        if (markerRequests == null || worldPositions == null || worldPositions.Count <= 0)
        {
            return;
        }

        for (int i = 0; i < worldPositions.Count; i++)
        {
            Vector3 markerWorldPosition = worldPositions[i];
            Vector3 referenceWorldPosition = ResolveNearestAreaMarkerReferenceWorldPosition(
                markerWorldPosition,
                referenceWorldPositions);
            float iconRotationZ = pointFromReferenceToMarker
                ? GetArrowMarkerRotationZ(referenceWorldPosition, markerWorldPosition)
                : GetArrowMarkerRotationZ(markerWorldPosition, referenceWorldPosition);
            markerRequests.Add(new AreaMarkerSpawnRequest(markerWorldPosition, icon, iconRotationZ));
        }
    }

    private static Vector3 ResolveNearestAreaMarkerReferenceWorldPosition(
        Vector3 markerWorldPosition,
        IReadOnlyList<Vector3> referenceWorldPositions)
    {
        if (referenceWorldPositions == null || referenceWorldPositions.Count <= 0)
        {
            return markerWorldPosition;
        }

        const float DistanceTieTolerance = 0.0001f;
        const float AlignmentTolerance = 0.01f;
        Vector3 bestReference = referenceWorldPositions[0];
        float bestDistanceSqr = float.MaxValue;
        int bestAlignmentPenalty = int.MaxValue;

        for (int i = 0; i < referenceWorldPositions.Count; i++)
        {
            Vector3 referenceWorldPosition = referenceWorldPositions[i];
            float deltaX = referenceWorldPosition.x - markerWorldPosition.x;
            float deltaZ = referenceWorldPosition.z - markerWorldPosition.z;
            float distanceSqr = deltaX * deltaX + deltaZ * deltaZ;
            int alignmentPenalty = Mathf.Abs(deltaX) <= AlignmentTolerance
                                   || Mathf.Abs(deltaZ) <= AlignmentTolerance
                ? 0
                : 1;

            if (distanceSqr > bestDistanceSqr + DistanceTieTolerance)
            {
                continue;
            }

            if (distanceSqr >= bestDistanceSqr - DistanceTieTolerance
                && alignmentPenalty >= bestAlignmentPenalty)
            {
                continue;
            }

            bestDistanceSqr = distanceSqr;
            bestAlignmentPenalty = alignmentPenalty;
            bestReference = referenceWorldPosition;
        }

        return bestReference;
    }

    private static bool TryGetRobotArm(MapObject mapObject, out RobotArm robotArm)
    {
        robotArm = mapObject as RobotArm;
        if (robotArm != null)
        {
            return true;
        }

        if (mapObject == null)
        {
            return false;
        }

        robotArm = mapObject.GetComponent<RobotArm>();
        if (robotArm != null)
        {
            return true;
        }

        robotArm = mapObject.GetComponentInChildren<RobotArm>(true);
        return robotArm != null;
    }

    private static bool TryGetRobotArmFlowDirection(MapObject mapObject, out Vector2Int flowDirection)
    {
        flowDirection = Vector2Int.zero;
        if (mapObject == null)
        {
            return false;
        }

        return TryResolveCardinalGridDirection(mapObject.transform.rotation * Vector3.forward, out flowDirection);
    }

    private static Vector2Int GetRobotArmEdgeCoordinate(
        IReadOnlyList<Vector2Int> objectCoordinates,
        Vector2Int flowDirection,
        bool front)
    {
        if (objectCoordinates == null || objectCoordinates.Count <= 0 || flowDirection == Vector2Int.zero)
        {
            return Vector2Int.zero;
        }

        Vector2Int selectedCoordinate = objectCoordinates[0];
        int selectedProjection = GetGridProjection(selectedCoordinate, flowDirection);
        for (int i = 1; i < objectCoordinates.Count; i++)
        {
            Vector2Int coordinate = objectCoordinates[i];
            int projection = GetGridProjection(coordinate, flowDirection);
            if ((front && projection > selectedProjection)
                || (!front && projection < selectedProjection))
            {
                selectedCoordinate = coordinate;
                selectedProjection = projection;
            }
        }

        return selectedCoordinate;
    }

    private static int GetGridProjection(Vector2Int coordinate, Vector2Int direction)
    {
        return (coordinate.x * direction.x) + (coordinate.y * direction.y);
    }

    private static bool TryResolveCardinalGridDirection(Vector3 directionVector, out Vector2Int gridDirection)
    {
        gridDirection = Vector2Int.zero;
        directionVector.y = 0f;
        if (directionVector.sqrMagnitude <= 0.0001f)
        {
            return false;
        }

        directionVector.Normalize();
        gridDirection = Mathf.Abs(directionVector.x) >= Mathf.Abs(directionVector.z)
            ? new Vector2Int(directionVector.x >= 0f ? 1 : -1, 0)
            : new Vector2Int(0, directionVector.z >= 0f ? 1 : -1);
        return true;
    }

    private AreaMarkerPool ResolveAreaMarkerPool()
    {
        if (areaMarkerPool != null)
        {
            return areaMarkerPool;
        }

        areaMarkerPool = GetComponent<AreaMarkerPool>();
        if (areaMarkerPool == null)
        {
            areaMarkerPool = gameObject.AddComponent<AreaMarkerPool>();
        }

        return areaMarkerPool;
    }

    private Sprite ResolveArrowMarkerIcon()
    {
        return UIManager.Instance != null ? UIManager.Instance.ArrowImage : null;
    }

    private Sprite ResolvePipePassMarkerIcon(MapObject footprintSource)
    {
        if (TryResolvePipePassFluidIcon(footprintSource, out Sprite icon))
        {
            return icon;
        }

        return ResolveFallbackPipePassMarkerIcon();
    }

    private bool TryResolvePipePassFluidIcon(MapObject footprintSource, out Sprite icon)
    {
        icon = null;
        if (!TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        IReadOnlyList<InputOutputModule.ItemIoEntry> inputList = inputOutputModule.InputList;
        if (inputList == null || inputList.Count <= 0)
        {
            return false;
        }

        for (int i = 0; i < inputList.Count; i++)
        {
            ItemDefinition itemDefinition = inputList[i].itemDefinition;
            if (itemDefinition == null
                || itemDefinition.icon == null
                || !InputOutputModule.IsFluidItemDefinition(itemDefinition))
            {
                continue;
            }

            icon = itemDefinition.icon;
            return true;
        }

        return false;
    }

    private Sprite ResolveFallbackPipePassMarkerIcon()
    {
        if (pipePassMarkerIcon != null)
        {
            return pipePassMarkerIcon;
        }

#if UNITY_EDITOR
        pipePassMarkerIcon = UnityEditor.AssetDatabase.LoadAssetAtPath<Sprite>(PipePassMarkerIconAssetPath);
        if (pipePassMarkerIcon != null)
        {
            return pipePassMarkerIcon;
        }
#endif

        List<ItemDefinition> definitions = GameManager.Instance?.ItemManger?.ItemDefinitions;
        if (definitions == null || definitions.Count <= 0)
        {
            return null;
        }

        ItemDefinition fluidDefinition = FindItemDefinitionByName(definitions, "Fluid");
        if (fluidDefinition == null)
        {
            fluidDefinition = FindItemDefinitionByName(definitions, "Water");
        }

        pipePassMarkerIcon = fluidDefinition != null ? fluidDefinition.icon : null;
        return pipePassMarkerIcon;
    }

    private Sprite ResolveInputEnergyMarkerIcon(MapObject installedObject)
    {
        ItemDefinition installationDefinition = ResolveItemDefinition(installedObject);
        if (installationDefinition == null || installationDefinition.useEnergyType == ItemDefinition.EnergyType.None)
        {
            return null;
        }

        List<ItemDefinition> definitions = GameManager.Instance?.ItemManger?.ItemDefinitions;
        if (definitions == null || definitions.Count <= 0)
        {
            return null;
        }

        ItemDefinition fixedCoalDefinition = FindItemDefinitionByName(definitions, "Coar");
        if (fixedCoalDefinition == null)
        {
            fixedCoalDefinition = FindItemDefinitionByName(definitions, "Coal");
        }

        if (fixedCoalDefinition != null && fixedCoalDefinition.icon != null)
        {
            return fixedCoalDefinition.icon;
        }

        ItemDefinition bestDefinition = null;
        for (int i = 0; i < definitions.Count; i++)
        {
            ItemDefinition candidate = definitions[i];
            if (candidate == null
                || candidate.energyType != installationDefinition.useEnergyType
                || candidate.energyAmount <= 0)
            {
                continue;
            }

            if (bestDefinition == null || candidate.id < bestDefinition.id)
            {
                bestDefinition = candidate;
            }
        }

        return bestDefinition != null ? bestDefinition.icon : null;
    }

    private static ItemDefinition FindItemDefinitionByName(List<ItemDefinition> definitions, string itemName)
    {
        if (definitions == null || definitions.Count <= 0 || string.IsNullOrWhiteSpace(itemName))
        {
            return null;
        }

        for (int i = 0; i < definitions.Count; i++)
        {
            ItemDefinition candidate = definitions[i];
            if (candidate == null)
            {
                continue;
            }

            if (string.Equals(candidate.itemName, itemName, System.StringComparison.OrdinalIgnoreCase)
                || string.Equals(candidate.name, itemName, System.StringComparison.OrdinalIgnoreCase))
            {
                return candidate;
            }
        }

        return null;
    }

    private static float GetArrowMarkerRotationZ(Vector3 fromWorldPosition, Vector3 toWorldPosition)
    {
        Vector2 direction = new Vector2(
            toWorldPosition.x - fromWorldPosition.x,
            toWorldPosition.z - fromWorldPosition.z);
        if (direction.sqrMagnitude <= 0.0001f)
        {
            return 0f;
        }

        return -Mathf.Atan2(direction.x, direction.y) * Mathf.Rad2Deg;
    }

    private ItemDefinition ResolveItemDefinition(MapObject mapObject)
    {
        int itemId = mapObject != null ? mapObject.ResolveItemId() : -1;
        if (itemId < 0)
        {
            return activeInstallDefinition;
        }

        List<ItemDefinition> definitions = GameManager.Instance?.ItemManger?.ItemDefinitions;
        if (definitions != null)
        {
            for (int i = 0; i < definitions.Count; i++)
            {
                ItemDefinition definition = definitions[i];
                if (definition != null && definition.id == itemId)
                {
                    return definition;
                }
            }
        }

        return activeInstallDefinition != null && activeInstallDefinition.id == itemId
            ? activeInstallDefinition
            : null;
    }

    private bool TryGetInputOutputModule(MapObject footprintSource, out InputOutputModule inputOutputModule)
    {
        inputOutputModule = footprintSource as InputOutputModule;
        if (inputOutputModule == null && footprintSource != null)
        {
            inputOutputModule = footprintSource.GetComponent<InputOutputModule>();
        }

        if (inputOutputModule == null && footprintSource != null)
        {
            inputOutputModule = footprintSource.GetComponentInChildren<InputOutputModule>(true);
        }

        return inputOutputModule != null;
    }

    private bool TryGetMiningMachine(MapObject footprintSource, out MiningMachine miningMachine)
    {
        miningMachine = footprintSource as MiningMachine;
        if (miningMachine == null && footprintSource != null)
        {
            miningMachine = footprintSource.GetComponent<MiningMachine>();
        }

        if (miningMachine == null && footprintSource != null)
        {
            miningMachine = footprintSource.GetComponentInChildren<MiningMachine>(true);
        }

        return miningMachine != null;
    }

    private List<Vector3> GetRectGridBlockWorldPositions(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        InputOutputModule.RectGridBlockType blockType)
    {
        return GetRectGridBlockWorldPositions(
            anchorCoordinate,
            footprintSource,
            quarterTurns,
            new[] { blockType });
    }

    private List<Vector3> GetRectGridBlockWorldPositions(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        IReadOnlyList<InputOutputModule.RectGridBlockType> blockTypes)
    {
        List<Vector3> worldPositions = new List<Vector3>();
        if (!TryGetRectGridBlockCoordinates(anchorCoordinate, footprintSource, quarterTurns, blockTypes, out List<Vector2Int> coordinates))
        {
            return worldPositions;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        float fallbackY = terrain != null ? terrain.transform.position.y : 0f;

        for (int i = 0; i < coordinates.Count; i++)
        {
            worldPositions.Add(GetAreaMarkerWorldPosition(coordinates[i], terrain, fallbackY));
        }

        return worldPositions;
    }

    private void FillRectGridBlockWorldPositions(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        IReadOnlyList<InputOutputModule.RectGridBlockType> blockTypes,
        List<Vector3> worldPositions)
    {
        if (worldPositions == null)
        {
            return;
        }

        worldPositions.Clear();
        if (!TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return;
        }

        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (placements == null || placements.Count <= 0)
        {
            return;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        float fallbackY = terrain != null ? terrain.transform.position.y : 0f;
        int normalizedQuarterTurns = NormalizePlacementQuarterTurnsForObject(footprintSource, quarterTurns);
        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (placement.blockType == InputOutputModule.RectGridBlockType.None
                || placement.x < 0
                || placement.x >= rectGridWidth
                || placement.y < 0
                || placement.y >= rectGridHeight
                || (blockTypes != null && !RectGridBlockTypeListContains(blockTypes, placement.blockType)))
            {
                continue;
            }

            Vector2Int localOffset = new Vector2Int(
                placement.x - objectAnchorCell.x,
                placement.y - objectAnchorCell.y);
            Vector2Int rotatedOffset = RotateFootprintOffset(localOffset, normalizedQuarterTurns);
            worldPositions.Add(GetAreaMarkerWorldPosition(anchorCoordinate + rotatedOffset, terrain, fallbackY));
        }
    }

    private Vector3 GetAreaMarkerWorldPosition(Vector2Int coordinate)
    {
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        float fallbackY = terrain != null ? terrain.transform.position.y : 0f;
        return GetAreaMarkerWorldPosition(coordinate, terrain, fallbackY);
    }

    private static Vector3 GetAreaMarkerWorldPosition(
        Vector2Int coordinate,
        TerrainGenerator terrain,
        float fallbackY)
    {
        if (terrain != null && terrain.TryGetLoadedBlock(coordinate, out Block block) && block != null)
        {
            Vector3 markerPosition = block.transform.position;
            if (TryGetMiningResourceMarkerSurfaceY(block, out float markerSurfaceY))
            {
                markerPosition.y = Mathf.Max(markerPosition.y, markerSurfaceY);
            }

            return markerPosition;
        }

        return new Vector3(coordinate.x, fallbackY, coordinate.y);
    }

    private static bool TryGetMiningResourceMarkerSurfaceY(Block block, out float surfaceY)
    {
        surfaceY = 0f;
        Resource resource = block != null ? block.Resource : null;
        if (resource == null || resource.ResolvedHarvestMode != Resource.HarvestMode.Mining)
        {
            return false;
        }

        int resourceInstanceId = resource.GetInstanceID();
        if (ResourceMarkerSurfaceYCache.TryGetValue(resourceInstanceId, out surfaceY))
        {
            return true;
        }

        ResourceRendererScratch.Clear();
        resource.GetComponentsInChildren(true, ResourceRendererScratch);
        bool foundRenderer = false;
        Bounds bounds = default;
        for (int i = 0; i < ResourceRendererScratch.Count; i++)
        {
            Renderer rendererComponent = ResourceRendererScratch[i];
            if (rendererComponent == null)
            {
                continue;
            }

            if (!foundRenderer)
            {
                bounds = rendererComponent.bounds;
                foundRenderer = true;
                continue;
            }

            bounds.Encapsulate(rendererComponent.bounds);
        }

        ResourceRendererScratch.Clear();

        surfaceY = foundRenderer
            ? bounds.max.y
            : Mathf.Max(block.transform.position.y, resource.transform.position.y);
        ResourceMarkerSurfaceYCache[resourceInstanceId] = surfaceY;
        return true;
    }

    private bool TryBuildRectGridPlacementCells(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        IReadOnlyList<InputOutputModule.RectGridBlockType> blockTypes,
        List<RectGridPlacementCell> cells)
    {
        if (cells == null)
        {
            return false;
        }

        cells.Clear();
        if (!TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (placements == null || placements.Count <= 0)
        {
            return false;
        }

        int normalizedQuarterTurns = NormalizePlacementQuarterTurnsForObject(footprintSource, quarterTurns);
        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (placement.blockType == InputOutputModule.RectGridBlockType.None
                || placement.x < 0
                || placement.x >= rectGridWidth
                || placement.y < 0
                || placement.y >= rectGridHeight
                || (blockTypes != null && !RectGridBlockTypeListContains(blockTypes, placement.blockType)))
            {
                continue;
            }

            Vector2Int localOffset = new Vector2Int(
                placement.x - objectAnchorCell.x,
                placement.y - objectAnchorCell.y);
            Vector2Int rotatedOffset = RotateFootprintOffset(localOffset, normalizedQuarterTurns);
            cells.Add(new RectGridPlacementCell(
                placement,
                placement.blockType,
                localOffset,
                rotatedOffset,
                anchorCoordinate + rotatedOffset));
        }

        return cells.Count > 0;
    }

    private bool TryGetRectGridBlockCoordinates(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        InputOutputModule.RectGridBlockType blockType,
        out List<Vector2Int> coordinates)
    {
        return TryGetRectGridBlockCoordinates(
            anchorCoordinate,
            footprintSource,
            quarterTurns,
            new[] { blockType },
            out coordinates);
    }

    private bool TryGetRectGridBlockCoordinates(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        IReadOnlyList<InputOutputModule.RectGridBlockType> blockTypes,
        out List<Vector2Int> coordinates)
    {
        coordinates = new List<Vector2Int>();
        List<RectGridPlacementCell> cells = new List<RectGridPlacementCell>();
        if (!TryBuildRectGridPlacementCells(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                blockTypes,
                cells))
        {
            return false;
        }

        for (int i = 0; i < cells.Count; i++)
        {
            coordinates.Add(cells[i].coordinate);
        }

        return coordinates.Count > 0;
    }

    private bool TryGetRectGridBlockLocalOffsets(
        MapObject footprintSource,
        int quarterTurns,
        InputOutputModule.RectGridBlockType blockType,
        out List<Vector2Int> localOffsets)
    {
        return TryGetRectGridBlockLocalOffsets(
            footprintSource,
            quarterTurns,
            new[] { blockType },
