    }

    private bool TryGetRectGridBlockLocalOffsets(
        MapObject footprintSource,
        int quarterTurns,
        IReadOnlyList<InputOutputModule.RectGridBlockType> blockTypes,
        out List<Vector2Int> localOffsets)
    {
        localOffsets = new List<Vector2Int>();
        List<RectGridPlacementCell> cells = new List<RectGridPlacementCell>();
        if (!TryBuildRectGridPlacementCells(
                Vector2Int.zero,
                footprintSource,
                quarterTurns,
                blockTypes,
                cells))
        {
            return false;
        }

        for (int i = 0; i < cells.Count; i++)
        {
            localOffsets.Add(cells[i].rotatedOffset);
        }

        return localOffsets.Count > 0;
    }

    private static bool RectGridBlockTypeListContains(
        IReadOnlyList<InputOutputModule.RectGridBlockType> blockTypes,
        InputOutputModule.RectGridBlockType blockType)
    {
        if (blockTypes == null)
        {
            return false;
        }

        for (int i = 0; i < blockTypes.Count; i++)
        {
            if (blockTypes[i] == blockType)
            {
                return true;
            }
        }

        return false;
    }

    private void BeginInstallPreview(ItemDefinition definition)
    {
        ClearInstallPreview();
        InvalidateInstallPreviewMoveCache();

        activeInstallDefinition = definition;
        activeInstallPreview = null;
        activeInstallBaseRotation = definition.mapObject != null ? definition.mapObject.transform.rotation : Quaternion.identity;
        installPreviewQuarterTurns = IsFenceDoorDefinition(definition)
            ? GetPreferredFenceDoorStandaloneQuarterTurns(definition, null)
            : GetPreferredInstallPreviewQuarterTurns(definition, null);
        waitForPointerReleaseAfterPreviewSpawn = true;
        InvalidateInstallGrid();
        GameManager.Instance?.SetInstallationPlacementActive(true);
        RefreshInstallOrEditWorkableRangeVisualRequest();
    }

    private void BeginRailloadInstallPreview(ItemDefinition definition)
    {
        ClearInstallPreview();
        InvalidateInstallPreviewMoveCache();

        activeInstallDefinition = definition;
        activeInstallPreview = null;
        activeInstallBaseRotation = definition != null && definition.mapObject != null
            ? definition.mapObject.transform.rotation
            : Quaternion.identity;
        installPreviewQuarterTurns = 0;
        waitForPointerReleaseAfterPreviewSpawn = true;
        InvalidateInstallGrid();
        GameManager.Instance?.SetInstallationPlacementActive(true);
        ResolveRailloadInstallationController().Begin(this, definition);
        RefreshInstallOrEditWorkableRangeVisualRequest();
    }

    private RailloadInstallationController ResolveRailloadInstallationController()
    {
        if (railloadInstallationController != null)
        {
            return railloadInstallationController;
        }

        railloadInstallationController = GetComponent<RailloadInstallationController>();
        if (railloadInstallationController == null)
        {
            railloadInstallationController = gameObject.AddComponent<RailloadInstallationController>();
        }

        railloadInstallationController.Initialize(this);
        return railloadInstallationController;
    }

    private bool IsRailloadInstallationModeActive()
    {
        return railloadInstallationController != null && railloadInstallationController.IsActive;
    }

    private MapObject CreateInstallPreviewInstance(ItemDefinition definition)
    {
        if (definition == null || definition.mapObject == null)
        {
            return null;
        }

        MapObject sourcePrefab = definition.mapObject;
        if (definition.mapObject is ConveyorBelt conveyorPrototype)
        {
            sourcePrefab = conveyorPrototype.StraightVariantPrefab != null
                ? conveyorPrototype.StraightVariantPrefab
                : definition.mapObject;
        }
        else if (definition.mapObject is Wall fencePrototype)
        {
            sourcePrefab = fencePrototype.StraightVariantPrefab != null
                ? fencePrototype.StraightVariantPrefab
                : definition.mapObject;
        }
        else if (definition.mapObject is Pipe pipePrototype)
        {
            sourcePrefab = pipePrototype.StraightVariantPrefab != null
                ? pipePrototype.StraightVariantPrefab
                : definition.mapObject;
        }

        return CreateInstallPreviewInstance(sourcePrefab, definition.mapObject);
    }

    private MapObject CreateInstallPreviewInstance(MapObject sourcePrefab, MapObject nameSourcePrefab)
    {
        if (sourcePrefab == null)
        {
            return null;
        }

        MapObject preview = Instantiate(sourcePrefab);
        if (preview == null)
        {
            return null;
        }

        string previewName = nameSourcePrefab != null ? nameSourcePrefab.name : sourcePrefab.name;
        bool containsRobotArmPreview = preview.GetComponentInChildren<RobotArm>(true) != null;
        if (containsRobotArmPreview)
        {
            preview.gameObject.SetActive(false);
        }

        preview.name = $"{previewName}_Blueprint";
        ConfigureInstallPreview(preview);
        installPreviewSourcePrefabsByPreview[preview] = sourcePrefab;
        if (containsRobotArmPreview)
        {
            preview.gameObject.SetActive(true);
        }

        return preview;
    }

    private void ConfigureInstallPreview(MapObject preview)
    {
        if (preview == null)
        {
            return;
        }

        blueprintPreviewMaterialCache.Clear();
        doubleSidedBlueprintPreviewMaterialCache.Clear();
        ApplyConveyorVariantSharedInstallationSettings(preview);
        ApplyPipeVariantSharedMapObjectSettings(preview);
        bool containsRobotArmPreview = ConfigurePreviewOnlyRuntimeRendering(preview);
        NormalizeInstallPreviewNativeRendering(preview);

        MonoBehaviour[] behaviours = preview.GetComponentsInChildren<MonoBehaviour>(true);
        for (int i = 0; i < behaviours.Length; i++)
        {
            MonoBehaviour behaviour = behaviours[i];
            if (behaviour == null)
            {
                continue;
            }

            behaviour.enabled = false;
        }

        Collider[] colliders = preview.GetComponentsInChildren<Collider>(true);
        for (int i = 0; i < colliders.Length; i++)
        {
            if (colliders[i] != null)
            {
                colliders[i].enabled = false;
            }
        }

        Rigidbody[] rigidbodies = preview.GetComponentsInChildren<Rigidbody>(true);
        for (int i = 0; i < rigidbodies.Length; i++)
        {
            Rigidbody body = rigidbodies[i];
            if (body == null)
            {
                continue;
            }

            body.isKinematic = true;
            body.detectCollisions = false;
        }

        if (installPreviewPropertyBlock == null)
        {
            installPreviewPropertyBlock = new MaterialPropertyBlock();
        }

        Renderer[] renderers = preview.GetComponentsInChildren<Renderer>(true);
        for (int i = 0; i < renderers.Length; i++)
        {
            Renderer renderer = renderers[i];
            if (renderer == null)
            {
                continue;
            }

            renderer.shadowCastingMode = ShadowCastingMode.Off;
            renderer.receiveShadows = false;
            Color previewTint = ResolveInstallPreviewTint(preview);
            bool isRobotArmPreviewRenderer = containsRobotArmPreview && IsRobotArmPreviewRenderer(renderer);
            if (isRobotArmPreviewRenderer)
            {
                renderer.enabled = true;
            }

            ApplyBlueprintPreviewMaterial(renderer, previewTint, isRobotArmPreviewRenderer);

            Material sharedMaterial = renderer.sharedMaterial;
            if (sharedMaterial == null)
            {
                continue;
            }

            installPreviewPropertyBlock.Clear();
            renderer.GetPropertyBlock(installPreviewPropertyBlock);
            bool hasColorProperty = false;

            if (TryApplyBlueprintPreviewProperties(sharedMaterial, installPreviewPropertyBlock, previewTint))
            {
                hasColorProperty = true;
            }
            else if (sharedMaterial.HasProperty(BaseColorPropertyId))
            {
                installPreviewPropertyBlock.SetColor(BaseColorPropertyId, previewTint);
                hasColorProperty = true;
            }
            else if (sharedMaterial.HasProperty(ColorPropertyId))
            {
                installPreviewPropertyBlock.SetColor(ColorPropertyId, previewTint);
                hasColorProperty = true;
            }

            if (sharedMaterial.HasProperty(EmissionColorPropertyId))
            {
                installPreviewPropertyBlock.SetColor(EmissionColorPropertyId, previewTint * 0.35f);
                hasColorProperty = true;
            }

            if (hasColorProperty)
            {
                renderer.SetPropertyBlock(installPreviewPropertyBlock);
            }
        }

        if (containsRobotArmPreview)
        {
            ConfigurePreviewOnlyRuntimeRendering(preview);
        }

        blueprintPreviewMaterialCache.Clear();
        doubleSidedBlueprintPreviewMaterialCache.Clear();
        SetInstallPreviewSelectionVisual(preview, false);
    }

    private void ApplyBlueprintPreviewMaterial(Renderer renderer, Color previewTint, bool forceDoubleSided = false)
    {
        if (renderer == null
            || renderer.GetComponentInParent<WorkableObjectRangeVisual>() != null)
        {
            return;
        }

        Material[] sourceMaterials = renderer.sharedMaterials;
        if (sourceMaterials == null || sourceMaterials.Length == 0)
        {
            return;
        }

        Dictionary<Material, Material> materialCache = forceDoubleSided
            ? doubleSidedBlueprintPreviewMaterialCache
            : blueprintPreviewMaterialCache;
        for (int i = 0; i < sourceMaterials.Length; i++)
        {
            Material sourceMaterial = sourceMaterials[i];
            if (sourceMaterial == null)
            {
                continue;
            }

            if (!materialCache.TryGetValue(sourceMaterial, out Material previewMaterial))
            {
                previewMaterial = CreateBlueprintPreviewMaterial(sourceMaterial, previewTint, forceDoubleSided);
                materialCache[sourceMaterial] = previewMaterial;
            }

            sourceMaterials[i] = previewMaterial;
        }

        renderer.sharedMaterials = sourceMaterials;
    }

    private static Material CreateBlueprintPreviewMaterial(Material sourceMaterial, Color previewTint, bool forceDoubleSided = false)
    {
        if (sourceMaterial == null)
        {
            return null;
        }

        Material material = new Material(sourceMaterial)
        {
            name = $"{sourceMaterial.name}{BlueprintPreviewRuntimeMaterialSuffix}",
            hideFlags = HideFlags.DontSave
        };

        runtimeBlueprintPreviewMaterials.Add(material);
        ConfigureBlueprintPreviewMaterial(material, previewTint, forceDoubleSided);
        return material;
    }

    private static void ConfigureBlueprintPreviewMaterial(Material material, Color previewTint, bool forceDoubleSided = false)
    {
        if (material == null)
        {
            return;
        }

        SetBlueprintPreviewMaterialProperties(material, previewTint);
        material.SetOverrideTag("RenderType", "Transparent");
        material.renderQueue = (int)RenderQueue.Transparent;
        material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");

        if (material.HasProperty(SurfacePropertyId))
        {
            material.SetFloat(SurfacePropertyId, 1f);
        }

        if (material.HasProperty(SrcBlendPropertyId))
        {
            material.SetFloat(SrcBlendPropertyId, (float)BlendMode.SrcAlpha);
        }

        if (material.HasProperty(DstBlendPropertyId))
        {
            material.SetFloat(DstBlendPropertyId, (float)BlendMode.OneMinusSrcAlpha);
        }

        if (material.HasProperty(SrcBlendAlphaPropertyId))
        {
            material.SetFloat(SrcBlendAlphaPropertyId, (float)BlendMode.One);
        }

        if (material.HasProperty(DstBlendAlphaPropertyId))
        {
            material.SetFloat(DstBlendAlphaPropertyId, (float)BlendMode.OneMinusSrcAlpha);
        }

        if (material.HasProperty(ZWritePropertyId))
        {
            material.SetFloat(ZWritePropertyId, 1f);
        }

        if (forceDoubleSided && material.HasProperty(CullPropertyId))
        {
            material.SetFloat(CullPropertyId, (float)CullMode.Off);
        }
    }

    private static void SetBlueprintPreviewMaterialProperties(Material material, Color previewTint)
    {
        if (material == null)
        {
            return;
        }

        if (material.HasProperty(BlueprintPreviewPropertyId))
        {
            material.SetFloat(BlueprintPreviewPropertyId, 1f);
        }

        if (material.HasProperty(BlueprintTintPropertyId))
        {
            material.SetColor(BlueprintTintPropertyId, GetBlueprintPreviewTintColor(previewTint));
        }

        if (material.HasProperty(BlueprintBrightnessPropertyId))
        {
            material.SetFloat(BlueprintBrightnessPropertyId, BlueprintPreviewBrightness);
        }

        if (material.HasProperty(BlueprintMinBrightnessPropertyId))
        {
            material.SetFloat(BlueprintMinBrightnessPropertyId, BlueprintPreviewMinBrightness);
        }

        if (material.HasProperty(BlueprintContrastPropertyId))
        {
            material.SetFloat(BlueprintContrastPropertyId, BlueprintPreviewContrast);
        }

        if (material.HasProperty(BlueprintAlphaPropertyId))
        {
            material.SetFloat(BlueprintAlphaPropertyId, Mathf.Max(previewTint.a, BlueprintPreviewAlpha));
        }

        if (material.HasProperty(BlueprintRimColorPropertyId))
        {
            material.SetColor(BlueprintRimColorPropertyId, GetBlueprintPreviewRimColor(previewTint));
        }

        if (material.HasProperty(BlueprintRimStrengthPropertyId))
        {
            material.SetFloat(BlueprintRimStrengthPropertyId, BlueprintPreviewRimStrength);
        }

        if (material.HasProperty(BlueprintRimPowerPropertyId))
        {
            material.SetFloat(BlueprintRimPowerPropertyId, BlueprintPreviewRimPower);
        }
    }

    private static bool TryApplyBlueprintPreviewProperties(
        Material material,
        MaterialPropertyBlock propertyBlock,
        Color previewTint)
    {
        if (material == null || propertyBlock == null)
        {
            return false;
        }

        bool applied = false;
        if (material.HasProperty(BlueprintPreviewPropertyId))
        {
            propertyBlock.SetFloat(BlueprintPreviewPropertyId, 1f);
            applied = true;
        }

        if (material.HasProperty(BlueprintTintPropertyId))
        {
            propertyBlock.SetColor(BlueprintTintPropertyId, GetBlueprintPreviewTintColor(previewTint));
            applied = true;
        }

        if (material.HasProperty(BlueprintBrightnessPropertyId))
        {
            propertyBlock.SetFloat(BlueprintBrightnessPropertyId, BlueprintPreviewBrightness);
            applied = true;
        }

        if (material.HasProperty(BlueprintMinBrightnessPropertyId))
        {
            propertyBlock.SetFloat(BlueprintMinBrightnessPropertyId, BlueprintPreviewMinBrightness);
            applied = true;
        }

        if (material.HasProperty(BlueprintContrastPropertyId))
        {
            propertyBlock.SetFloat(BlueprintContrastPropertyId, BlueprintPreviewContrast);
            applied = true;
        }

        if (material.HasProperty(BlueprintAlphaPropertyId))
        {
            propertyBlock.SetFloat(BlueprintAlphaPropertyId, Mathf.Max(previewTint.a, BlueprintPreviewAlpha));
            applied = true;
        }

        if (material.HasProperty(BlueprintRimColorPropertyId))
        {
            propertyBlock.SetColor(BlueprintRimColorPropertyId, GetBlueprintPreviewRimColor(previewTint));
            applied = true;
        }

        if (material.HasProperty(BlueprintRimStrengthPropertyId))
        {
            propertyBlock.SetFloat(BlueprintRimStrengthPropertyId, BlueprintPreviewRimStrength);
            applied = true;
        }

        if (material.HasProperty(BlueprintRimPowerPropertyId))
        {
            propertyBlock.SetFloat(BlueprintRimPowerPropertyId, BlueprintPreviewRimPower);
            applied = true;
        }

        return applied;
    }

    private static Color GetBlueprintPreviewTintColor(Color previewTint)
    {
        return new Color(previewTint.r, previewTint.g, previewTint.b, 1f);
    }

    private static Color GetBlueprintPreviewRimColor(Color previewTint)
    {
        return new Color(0.03f, 0.12f, 0.52f, 1f);
    }

    private void TryMoveInstallPreview(Vector2 pointerPosition, bool preserveRotation = false)
    {
        if (activeInstallPreview == null)
        {
            return;
        }

        if (TryMoveActiveFreightCarLoadPreview(pointerPosition))
        {
            return;
        }

        Vector3? railReferenceWorldPosition = null;
        if (TryGetInstallPreviewRailReferenceWorldPosition(pointerPosition, out Vector3 worldPoint))
        {
            railReferenceWorldPosition = worldPoint;
        }

        if (TryGetPlacementPointerBlock(pointerPosition, out Block block))
        {
            MoveInstallPreviewToBlock(block, preserveRotation, railReferenceWorldPosition);
        }
    }

    private bool TryGetInstallPreviewRailReferenceWorldPosition(
        Vector2 pointerPosition,
        out Vector3 worldPosition)
    {
        worldPosition = Vector3.zero;
        Camera targetCamera = ResolveInstallPreviewCamera();
        return targetCamera != null
               && TryGetGroundPlanePoint(targetCamera.ScreenPointToRay(pointerPosition), out worldPosition);
    }

    private bool MoveInstallPreviewToBlock(
        Block block,
        bool preserveRotation = false,
        Vector3? railReferenceWorldPosition = null)
    {
        if (activeInstallPreview == null || block == null)
        {
            return false;
        }

        if (activeInstallPreview is UndergroundPipe committedUndergroundPipe
            && committedUndergroundPipe.IsPreviewPairCommitted
            && (activeInstallationEditSession == null
                || !activeInstallationEditSession.editsUndergroundPipeEndpoint))
        {
            return false;
        }

        if (activeInstallationEditSession != null
            && activeInstallationEditSession.editsUndergroundPipeEndpoint
            && activeInstallPreview is UndergroundPipe undergroundPipePreview)
        {
            return MoveUndergroundPipeEditPreviewToBlock(
                undergroundPipePreview,
                activeInstallationEditSession,
                block);
        }

        ClearFreightCarBoxPreviewTarget(activeInstallPreview);

        bool hasMoveFootprintSource =
            TryResolveInstallPreviewFootprintSourceForPlacement(activeInstallPreview, out MapObject moveFootprintSource);
        bool isTrainMovePreview = hasMoveFootprintSource && IsTrainSource(moveFootprintSource);
        if (!isTrainMovePreview
            && TryUseCachedInstallPreviewMove(block, preserveRotation, out bool cachedMoveResult))
        {
            return cachedMoveResult;
        }

        int preferredQuarterTurns = GetPreviewQuarterTurns(activeInstallPreview);
        bool allowWaterPumpAutoRotation = IsWaterPumpPreview(activeInstallPreview);
        bool allowOilDrillingMachineAutoRotation = IsOilDrillingMachineSource(moveFootprintSource);
        bool preserveRotationForTarget = preserveRotation
                                         && !allowWaterPumpAutoRotation
                                         && !allowOilDrillingMachineAutoRotation;
        bool useSimpleRectGridTarget =
            hasMoveFootprintSource
            && CanUseSimpleRectGridInstallGridCheck(moveFootprintSource);
        Block anchorBlock;
        int resolvedQuarterTurns;
        bool hasPlacementTarget = IsTrainSource(moveFootprintSource)
            ? TryResolveTrainInstallPreviewTarget(
                block,
                moveFootprintSource,
                preferredQuarterTurns,
                railReferenceWorldPosition,
                out anchorBlock,
                out resolvedQuarterTurns)
            : useSimpleRectGridTarget
            ? TryResolveSimpleRectGridInstallPreviewTargetFast(
                block,
                moveFootprintSource,
                activeInstallPreview,
                preferredQuarterTurns,
                preserveRotationForTarget,
                out anchorBlock,
                out resolvedQuarterTurns)
            : preserveRotationForTarget
                ? TryResolveFixedRotationInstallPreviewTarget(
                    block,
                    activeInstallPreview,
                    preferredQuarterTurns,
                    out anchorBlock,
                    out resolvedQuarterTurns)
                : TryResolvePlaceableInstallPreviewTarget(
                    block,
                    activeInstallPreview,
                    preferredQuarterTurns,
                    false,
                    out anchorBlock,
                    out resolvedQuarterTurns);
        if (!hasPlacementTarget)
        {
            CacheInstallPreviewMoveResult(block, false, preserveRotation);
            return false;
        }

        MapObject waterPumpRotationSource = ResolveInstallPreviewFootprintSource(activeInstallPreview)
                                            ?? (activeInstallDefinition != null ? activeInstallDefinition.mapObject : null)
                                            ?? activeInstallPreview;
        if ((!preserveRotation || allowWaterPumpAutoRotation)
            && TryResolveWaterPumpOutwardQuarterTurns(
                anchorBlock.Coordinate,
                waterPumpRotationSource,
                resolvedQuarterTurns,
                out int waterPumpQuarterTurns))
        {
            resolvedQuarterTurns = waterPumpQuarterTurns;
        }

        MapObject activePlacementSourceForMove = ResolveInstallPreviewPlacementSource(activeInstallPreview)
                                             ?? moveFootprintSource
                                             ?? waterPumpRotationSource;
        if (TryResolveTrainStationFacingQuarterTurns(
                anchorBlock.Coordinate,
                activePlacementSourceForMove,
                activeInstallPreview,
                resolvedQuarterTurns,
                out int trainStationQuarterTurns))
        {
            resolvedQuarterTurns = trainStationQuarterTurns;
        }

        if (!IsTrainSource(activePlacementSourceForMove)
            && TryGetPreviewAnchorCoordinate(activeInstallPreview, out Vector2Int currentAnchorCoordinate)
            && currentAnchorCoordinate == anchorBlock.Coordinate
            && GetPreviewQuarterTurns(activeInstallPreview) == resolvedQuarterTurns)
        {
            CacheInstallPreviewMoveResult(block, true, preserveRotation);
            return true;
        }

        SetInstallPreviewQuarterTurns(activeInstallPreview, resolvedQuarterTurns);

        Vector2Int previousAnchorCoordinate = Vector2Int.zero;
        bool hadPreviousAnchorCoordinate = TryGetPreviewAnchorCoordinate(activeInstallPreview, out previousAnchorCoordinate);

        if (hadPreviousAnchorCoordinate
            && previousAnchorCoordinate != anchorBlock.Coordinate)
        {
            installPreviewPipeConnectionMasksByPreview.Remove(activeInstallPreview);
            installPreviewPipeSelectedSetDirectionsByPreview.Remove(activeInstallPreview);
        }

        installPreviewAnchorCoordinates[activeInstallPreview] = anchorBlock.Coordinate;
        if (hadPreviousAnchorCoordinate && previousAnchorCoordinate != anchorBlock.Coordinate)
        {
            straightFirstConveyorPreviews.Remove(activeInstallPreview);
        }

        RefreshActiveConveyorPreviewVariant();
        RefreshActiveFencePreviewVariant(true);
        MapObject placementSource = ResolveInstallPreviewPlacementSource(activeInstallPreview);
        Vector3 targetPosition = ResolvePlacementWorldPosition(
            anchorBlock,
            placementSource,
            installPreviewQuarterTurns,
            railReferenceWorldPosition);
        Vector3? rotationRailReferenceWorldPosition = railReferenceWorldPosition;
        if (!rotationRailReferenceWorldPosition.HasValue && IsTrainSource(placementSource))
        {
            rotationRailReferenceWorldPosition = targetPosition;
        }

        SetInstallPreviewRailReferenceForPlacement(placementSource, rotationRailReferenceWorldPosition);
        Quaternion targetRotation = GetInstallPreviewRotation();

        activeInstallPreview.transform.position = targetPosition;
        activeInstallPreview.transform.rotation = targetRotation;
        if (activeInstallPreview is InstallationObject movedInstallationPreview)
        {
            movedInstallationPreview.RefreshInstalledDirectionFromCurrentTransform();
        }

        RefreshHandcartInstallPreviewConnectionPoses();
        RefreshPreviewRangeVisualsIfNeeded(activeInstallPreview);
        RefreshUtilityPolePreviewWires();
        RefreshInstallPreviewAreaMarkers(activeInstallPreview);
        RefreshFencePreviewVariantsAroundActivePreview(
            hadPreviousAnchorCoordinate ? previousAnchorCoordinate : (Vector2Int?)null,
            true);
        RefreshPipePreviewVariantsAroundActivePreview(
            hadPreviousAnchorCoordinate ? previousAnchorCoordinate : (Vector2Int?)null);
        RefreshTrainInstallPreviewTints();
        RememberBlueprintRotationForPreview(activeInstallDefinition, activeInstallPreview, installPreviewQuarterTurns);
        InvalidateInstallGridPreview();
        CacheInstallPreviewMoveResult(block, true, preserveRotation);
        return true;
    }

    private bool MoveUndergroundPipeEditPreviewToBlock(
        UndergroundPipe preview,
        InstallationEditSession editSession,
        Block movingBlock)
    {
        Vector2Int movingCoordinate = movingBlock.Coordinate;
        Vector2Int fixedCoordinate = editSession.fixedUndergroundEndpointCoordinate;
        bool hadPreviousCandidate = preview.TryGetPreviewCandidateCoordinates(
            out Vector2Int previousFirstCoordinate,
            out Vector2Int previousSecondCoordinate);
        bool isValid = TryValidateUndergroundPipePair(
            movingCoordinate,
            fixedCoordinate,
            preview,
            out Block validatedMovingBlock,
            out Block fixedBlock);
        ConfigureUndergroundPipePreviewCandidate(
            preview,
            movingCoordinate,
            fixedCoordinate,
            validatedMovingBlock ?? movingBlock,
            fixedBlock,
            isValid,
            isValid);

        installPreviewAnchorCoordinates[preview] = movingCoordinate;
        int quarterTurns = ResolveUndergroundPipeQuarterTurns(movingCoordinate, fixedCoordinate);
        SetInstallPreviewQuarterTurns(preview, quarterTurns);
        SetInstallPreviewSelectionVisual(preview, true);
        RefreshInstallPreviewAreaMarkers(preview);
        RefreshUndergroundPipeBlueprintTopology(
            preview,
            hadPreviousCandidate,
            previousFirstCoordinate,
            previousSecondCoordinate);
        InvalidateInstallGrid();
        return isValid;
    }

    private bool IsWaterPumpPreview(MapObject preview)
    {
        if (preview == null)
        {
            return false;
        }

        MapObject footprintSource = ResolveInstallPreviewFootprintSource(preview)
                                    ?? (activeInstallDefinition != null ? activeInstallDefinition.mapObject : null)
                                    ?? preview;
        return IsWaterPumpSource(footprintSource);
    }

    private static bool IsOilDrillingMachineSource(MapObject source)
    {
        return source is OilDrillingMachine;
    }

    private bool TryResolveOilDrillingMachineFacingQuarterTurns(
        Vector2Int anchorCoordinate,
        MapObject source,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        IReadOnlyList<InstallPreviewPlacementReservation> reservedFootprintReservations,
        out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(source, preferredQuarterTurns);
        if (!IsOilDrillingMachineSource(source))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        for (int offset = 0; offset < 4; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                source,
                preferredQuarterTurns + offset);
            if (!TryGetOilDrillingMachineTargetCoordinate(
                    terrain,
                    anchorCoordinate,
                    candidateQuarterTurns,
                    out Vector2Int oilTargetCoordinate)
                || !IsOilDrillingMachineTargetAvailable(
                    oilTargetCoordinate,
                    previewToIgnore,
                    reservedFootprintReservations))
            {
                continue;
            }

            resolvedQuarterTurns = candidateQuarterTurns;
            return true;
        }

        return false;
    }

    private bool OilDrillingMachinePlacementMatchesOil(
        Vector2Int anchorCoordinate,
        MapObject source,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (!IsOilDrillingMachineSource(source))
        {
            return true;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        int normalizedQuarterTurns = NormalizePlacementQuarterTurnsForObject(source, quarterTurns);
        return terrain != null
               && TryGetOilDrillingMachineTargetCoordinate(
                   terrain,
                   anchorCoordinate,
                   normalizedQuarterTurns,
                   out Vector2Int oilTargetCoordinate)
               && IsOilDrillingMachineTargetAvailable(oilTargetCoordinate, previewToIgnore, null);
    }

    private static bool TryGetOilDrillingMachineTargetCoordinate(
        TerrainGenerator terrain,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        out Vector2Int oilTargetCoordinate)
    {
        oilTargetCoordinate = ResolveOilDrillingMachineTargetCoordinate(anchorCoordinate, quarterTurns);
        if (terrain == null
            || !terrain.TryGetLoadedBlock(oilTargetCoordinate, out Block oilBlock)
            || oilBlock == null)
        {
            return false;
        }

        Resource oilResource = oilBlock.Resource;
        return oilResource != null
               && oilResource.PlacementCategory == ResourceDefinition.PlacementCategory.Oil;
    }

    private static Vector2Int ResolveOilDrillingMachineTargetCoordinate(
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        return OilDrillingMachine.ResolveOilTargetCoordinate(anchorCoordinate, quarterTurns);
    }

    private bool IsOilDrillingMachineTargetAvailable(
        Vector2Int oilTargetCoordinate,
        MapObject previewToIgnore,
        IReadOnlyList<InstallPreviewPlacementReservation> reservedFootprintReservations)
    {
        return !IsOilDrillingMachineTargetClaimedByInstalledObject(oilTargetCoordinate)
               && !IsOilDrillingMachineTargetClaimedByEarlierPreview(oilTargetCoordinate, previewToIgnore)
               && !IsOilDrillingMachineTargetReserved(oilTargetCoordinate, reservedFootprintReservations);
    }

    private bool IsOilDrillingMachineTargetClaimedByInstalledObject(Vector2Int oilTargetCoordinate)
    {
        oilDrillingMachineOccupantScratch.Clear();
        for (int directionIndex = 0; directionIndex < PipeCardinalDirections.Length; directionIndex++)
        {
            InstallationObject.CollectActiveInstallationsAtRuntimeGridCoordinate(
                oilTargetCoordinate + PipeCardinalDirections[directionIndex],
                oilDrillingMachineOccupantScratch);
        }

        bool targetClaimed = false;
        for (int i = 0; i < oilDrillingMachineOccupantScratch.Count; i++)
        {
            InstallationObject candidate = oilDrillingMachineOccupantScratch[i];
            if (!(candidate is OilDrillingMachine)
                || !candidate.TryGetPlacementRuntime(out Vector2Int candidateAnchorCoordinate, out int candidateQuarterTurns)
                || ResolveOilDrillingMachineTargetCoordinate(candidateAnchorCoordinate, candidateQuarterTurns)
                   != oilTargetCoordinate)
            {
                continue;
            }

            targetClaimed = true;
            break;
        }

        oilDrillingMachineOccupantScratch.Clear();
        return targetClaimed;
    }

    private bool IsOilDrillingMachineTargetClaimedByEarlierPreview(
        Vector2Int oilTargetCoordinate,
        MapObject previewToIgnore)
    {
        int ignoredPreviewIndex = previewToIgnore != null
            ? installPreviewInstances.IndexOf(previewToIgnore)
            : -1;
        int previewCount = ignoredPreviewIndex >= 0
            ? ignoredPreviewIndex
            : installPreviewInstances.Count;
        for (int i = 0; i < previewCount; i++)
        {
            MapObject preview = installPreviewInstances[i];
            if (preview == null
                || preview == previewToIgnore
                || !TryGetPreviewAnchorCoordinate(preview, out Vector2Int previewAnchorCoordinate))
            {
                continue;
            }

            MapObject previewSource = ResolveInstallPreviewPlacementSource(preview);
            if (!IsOilDrillingMachineSource(previewSource))
            {
                continue;
            }

            int previewQuarterTurns = GetPreviewQuarterTurns(preview);
            if (ResolveOilDrillingMachineTargetCoordinate(previewAnchorCoordinate, previewQuarterTurns)
                == oilTargetCoordinate)
            {
                return true;
            }
        }

        return false;
    }

    private static bool IsOilDrillingMachineTargetReserved(
        Vector2Int oilTargetCoordinate,
        IReadOnlyList<InstallPreviewPlacementReservation> reservedFootprintReservations)
    {
        if (reservedFootprintReservations == null)
        {
            return false;
        }

        for (int i = 0; i < reservedFootprintReservations.Count; i++)
        {
            InstallPreviewPlacementReservation reservation = reservedFootprintReservations[i];
            if (reservation != null
                && reservation.hasOilTargetCoordinate
                && reservation.oilTargetCoordinate == oilTargetCoordinate)
            {
                return true;
            }
        }

        return false;
    }

    private bool TryResolveTrainInstallPreviewTarget(
        Block block,
        MapObject footprintSource,
        int preferredQuarterTurns,
        Vector3? railReferenceWorldPosition,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = block;
        resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            footprintSource,
            preferredQuarterTurns);
        if (block == null || !IsTrainSource(footprintSource))
        {
            return false;
        }

        Vector3 referencePosition = railReferenceWorldPosition ?? block.transform.position;
        return TryResolveTrainRailPlacementPose(
            footprintSource,
            block.Coordinate,
            resolvedQuarterTurns,
            referencePosition,
            out Vector3 trainPosition,
            out Quaternion trainRotation)
            && CanPlaceTrainAtPose(footprintSource, trainPosition, trainRotation, activeInstallPreview);
    }

    private bool TryGetPointerBlock(out Block block)
    {
        block = null;
        return TryGetPrimaryPointerPosition(out Vector2 pointerPosition) && TryGetPointerBlock(pointerPosition, out block);
    }

    private bool TryGetPointerBlock(Vector2 pointerPosition, out Block block)
    {
        block = null;

        Camera targetCamera = ResolveInstallPreviewCamera();
        if (targetCamera == null)
        {
            return false;
        }

        Ray ray = targetCamera.ScreenPointToRay(pointerPosition);
        int hitCount = Physics.RaycastNonAlloc(
            ray,
            pointerRaycastHits,
            512f,
            Physics.DefaultRaycastLayers,
            QueryTriggerInteraction.Ignore);
        if (hitCount > 0)
        {
            Block nearestBlock = null;
            float nearestDistance = float.PositiveInfinity;
            for (int i = 0; i < hitCount; i++)
            {
                RaycastHit hit = pointerRaycastHits[i];
                Block hitBlock = hit.collider != null ? hit.collider.GetComponentInParent<Block>() : null;
                if (hitBlock != null && hit.distance < nearestDistance)
                {
                    nearestBlock = hitBlock;
                    nearestDistance = hit.distance;
                }
            }

            if (nearestBlock != null)
            {
                block = nearestBlock;
                return true;
            }
        }

        return TryGetBlockFromGroundPlane(ray, out block);
    }

    public bool TryGetPlacementPointerBlock(out Block block)
    {
        block = null;
        return TryGetPrimaryPointerPosition(out Vector2 pointerPosition)
               && TryGetPlacementPointerBlock(pointerPosition, out block);
    }

    public bool TryGetPlacementPointerBlock(Vector2 pointerPosition, out Block block)
    {
        block = null;
        Camera targetCamera = ResolveInstallPreviewCamera();
        if (targetCamera == null)
        {
            return false;
        }

        Ray ray = targetCamera.ScreenPointToRay(pointerPosition);
        return TryGetBlockFromGroundPlane(ray, out block)
               || TryGetPointerBlock(pointerPosition, out block);
    }

    private Camera ResolveInstallPreviewCamera()
    {
        if (installPreviewCamera != null)
        {
            return installPreviewCamera;
        }

        installPreviewCamera = Camera.main;
        if (installPreviewCamera != null)
        {
            return installPreviewCamera;
        }

        PlayerCamera playerCamera = FindObjectOfType<PlayerCamera>();
        if (playerCamera != null)
        {
            installPreviewCamera = playerCamera.GetComponent<Camera>();
        }

        if (installPreviewCamera == null)
        {
            installPreviewCamera = FindObjectOfType<Camera>();
        }

        return installPreviewCamera;
    }

    private TerrainGenerator ResolveInstallPreviewTerrain()
    {
        if (installPreviewTerrain == null)
        {
            installPreviewTerrain = TerrainGenerator.ResolveActive();
        }

        return installPreviewTerrain;
    }

    private void UpdateInstallGrid()
    {
        if (!Application.isPlaying)
        {
            ReleaseInstallGridResources();
            ResetInstallGridRefreshState();
            return;
        }

        bool showFullGrid = IsInstallGridModeActive();
        bool showConveyorDebugOnly = !showFullGrid
            && GameManager.Instance != null
            && GameManager.Instance.DebugConveyorInstallGridEnds;
        if (!showFullGrid && !showConveyorDebugOnly)
        {
            SetInstallGridVisible(false);
            ResetInstallGridRefreshState();
            return;
        }

        if (showFullGrid != installGridLastShowFullGrid
            || showConveyorDebugOnly != installGridLastShowConveyorDebugOnly)
        {
            installGridDirty = true;
            installGridPreviewDirty = true;
            ResetInstallGridMeshBuild(true);
            installGridLastShowFullGrid = showFullGrid;
            installGridLastShowConveyorDebugOnly = showConveyorDebugOnly;
        }

        EnsureInstallGridResources();
        bool wasVisible = installGridObject != null && installGridObject.activeSelf;
        SetInstallGridVisible(true);
        if (!wasVisible)
        {
            installGridDirty = true;
            installGridPreviewDirty = true;
            ResetInstallGridMeshBuild(true);
        }

        if (HaveInstallGridBoundsChanged())
        {
            installGridDirty = true;
            ResetInstallGridMeshBuild();
        }

        if (HaveInstallGridPreviewStateChanged())
        {
            installGridPreviewDirty = true;
        }

        if (installGridDirty)
        {
            installGridDirty = !RebuildInstallGridMesh();
        }

        if (installGridPreviewDirty)
        {
            RebuildInstallGridPreviewMesh();
            installGridPreviewDirty = false;
        }
    }

    private void ResetInstallGridRefreshState()
    {
        installGridDirty = true;
        installGridPreviewDirty = true;
        installGridBoundsInitialized = false;
        installGridLastShowFullGrid = false;
        installGridLastShowConveyorDebugOnly = false;
        installGridLastHadPreviewOverlay = false;
        installGridLastPreviewAnchorCoordinate = Vector2Int.zero;
        installGridLastPreviewQuarterTurns = 0;
        installGridLastPreview = null;
        ResetInstallGridMeshBuild(true);
    }

    private void ResetInstallGridMeshBuild(bool clearValidityCache = false)
    {
        installGridMeshBuildInitialized = false;
        installGridBlockedCoordinates.Clear();
        if (clearValidityCache)
        {
            installGridPlacementValidityCache.Clear();
            installGridRectAnchorValidityCache.Clear();
            installGridSimpleClearCellCache.Clear();
        }
    }

    private bool HaveInstallGridBoundsChanged()
    {
        if (!TryGetInstallGridEffectiveBounds(out Vector2Int minCoordinate, out Vector2Int maxCoordinate))
        {
            return installGridBoundsInitialized;
        }

        return !installGridBoundsInitialized
               || installGridMinCoordinate != minCoordinate
               || installGridMaxCoordinate != maxCoordinate;
    }

    private bool HaveInstallGridPreviewStateChanged()
    {
        Vector2Int anchorCoordinate = Vector2Int.zero;
        bool hasPreviewOverlay = IsInstallGridModeActive()
                                 && activeInstallPreview != null
                                 && TryGetPreviewAnchorCoordinate(activeInstallPreview, out anchorCoordinate);
        int quarterTurns = hasPreviewOverlay ? GetPreviewAreaQuarterTurns(activeInstallPreview) : 0;
        bool changed = installGridLastHadPreviewOverlay != hasPreviewOverlay
                       || installGridLastPreview != activeInstallPreview
                       || (hasPreviewOverlay && installGridLastPreviewAnchorCoordinate != anchorCoordinate)
                       || (hasPreviewOverlay && installGridLastPreviewQuarterTurns != quarterTurns);

        installGridLastHadPreviewOverlay = hasPreviewOverlay;
        installGridLastPreview = activeInstallPreview;
        installGridLastPreviewAnchorCoordinate = hasPreviewOverlay ? anchorCoordinate : Vector2Int.zero;
        installGridLastPreviewQuarterTurns = quarterTurns;
        return changed;
    }

    private bool TryGetInstallGridEffectiveBounds(out Vector2Int minCoordinate, out Vector2Int maxCoordinate)
    {
        minCoordinate = Vector2Int.zero;
        maxCoordinate = Vector2Int.zero;

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null || !terrain.TryGetLoadedBlockBounds(out Vector2Int loadedMin, out Vector2Int loadedMax))
        {
            return false;
        }

        minCoordinate = loadedMin;
        maxCoordinate = loadedMax;
        if (!TryGetInstallGridViewportBounds(terrain, out Vector2Int viewportMin, out Vector2Int viewportMax))
        {
            ClampInstallGridEffectiveBounds(
                loadedMin,
                loadedMax,
                ResolveInstallGridFocusCoordinate(minCoordinate, maxCoordinate, true),
                ref minCoordinate,
                ref maxCoordinate);
            return true;
        }

        minCoordinate = new Vector2Int(
            Mathf.Max(loadedMin.x, viewportMin.x),
            Mathf.Max(loadedMin.y, viewportMin.y));
        maxCoordinate = new Vector2Int(
            Mathf.Min(loadedMax.x, viewportMax.x),
            Mathf.Min(loadedMax.y, viewportMax.y));
        if (minCoordinate.x > maxCoordinate.x || minCoordinate.y > maxCoordinate.y)
        {
            return false;
        }

        ClampInstallGridEffectiveBounds(
            loadedMin,
            loadedMax,
            ResolveInstallGridFocusCoordinate(minCoordinate, maxCoordinate, false),
            ref minCoordinate,
            ref maxCoordinate);
        return true;
    }

    private void ClampInstallGridEffectiveBounds(
        Vector2Int loadedMin,
        Vector2Int loadedMax,
        Vector2Int focusCoordinate,
        ref Vector2Int minCoordinate,
        ref Vector2Int maxCoordinate)
    {
        if (minCoordinate.x > maxCoordinate.x || minCoordinate.y > maxCoordinate.y)
        {
            return;
        }

        ClampInstallGridAxis(
            minCoordinate.x,
            maxCoordinate.x,
            focusCoordinate.x,
            out int clampedMinX,
            out int clampedMaxX);
        ClampInstallGridAxis(
            minCoordinate.y,
            maxCoordinate.y,
            focusCoordinate.y,
            out int clampedMinY,
            out int clampedMaxY);

        minCoordinate = new Vector2Int(
            Mathf.Max(loadedMin.x, clampedMinX),
            Mathf.Max(loadedMin.y, clampedMinY));
        maxCoordinate = new Vector2Int(
            Mathf.Min(loadedMax.x, clampedMaxX),
            Mathf.Min(loadedMax.y, clampedMaxY));
    }

    private Vector2Int ResolveInstallGridFocusCoordinate(
        Vector2Int minCoordinate,
        Vector2Int maxCoordinate,
        bool allowPreviewFocus)
    {
        if (allowPreviewFocus
            && activeInstallPreview != null
            && TryGetPreviewAnchorCoordinate(activeInstallPreview, out Vector2Int anchorCoordinate))
        {
            return anchorCoordinate;
        }

        if (allowPreviewFocus && selectedEditableInstallation != null)
        {
            return selectedEditableAnchorCoordinate;
        }

        return new Vector2Int(
            (minCoordinate.x + maxCoordinate.x) / 2,
            (minCoordinate.y + maxCoordinate.y) / 2);
    }

    private static void ClampInstallGridAxis(
        int currentMin,
        int currentMax,
        int focus,
        out int clampedMin,
        out int clampedMax)
    {
        int size = currentMax - currentMin + 1;
        if (size <= InstallGridMaxVisibleCellsPerAxis)
        {
            clampedMin = currentMin;
            clampedMax = currentMax;
            return;
        }

        int clampedSize = Mathf.Min(size, InstallGridMaxVisibleCellsPerAxis);
        int clampedFocus = Mathf.Clamp(focus, currentMin, currentMax);
        clampedMin = clampedFocus - clampedSize / 2;
        clampedMax = clampedMin + clampedSize - 1;
        if (clampedMin < currentMin)
        {
            clampedMax += currentMin - clampedMin;
            clampedMin = currentMin;
        }

        if (clampedMax > currentMax)
        {
            clampedMin -= clampedMax - currentMax;
            clampedMax = currentMax;
        }
    }

    private bool TryGetInstallGridViewportBounds(
        TerrainGenerator terrain,
        out Vector2Int minCoordinate,
        out Vector2Int maxCoordinate)
    {
        minCoordinate = Vector2Int.zero;
        maxCoordinate = Vector2Int.zero;
        Camera targetCamera = ResolveInstallPreviewCamera();
        if (targetCamera == null || terrain == null)
        {
            return false;
        }

        Plane groundPlane = new Plane(Vector3.up, new Vector3(0f, terrain.transform.position.y, 0f));
        float minX = float.PositiveInfinity;
        float maxX = float.NegativeInfinity;
        float minZ = float.PositiveInfinity;
        float maxZ = float.NegativeInfinity;
        int hitCount = 0;

        for (int y = 0; y <= 1; y++)
        {
            for (int x = 0; x <= 1; x++)
            {
                Ray ray = targetCamera.ViewportPointToRay(new Vector3(x, y, 0f));
                if (!groundPlane.Raycast(ray, out float enter))
                {
                    continue;
                }

                Vector3 point = ray.GetPoint(enter);
                minX = Mathf.Min(minX, point.x);
                maxX = Mathf.Max(maxX, point.x);
                minZ = Mathf.Min(minZ, point.z);
                maxZ = Mathf.Max(maxZ, point.z);
                hitCount++;
            }
        }

        if (hitCount <= 0)
        {
            return false;
        }

        minCoordinate = new Vector2Int(
            Mathf.FloorToInt(minX - 1f) - InstallGridViewportPaddingCells,
            Mathf.FloorToInt(minZ - 1f) - InstallGridViewportPaddingCells);
        maxCoordinate = new Vector2Int(
            Mathf.CeilToInt(maxX + 1f) + InstallGridViewportPaddingCells,
            Mathf.CeilToInt(maxZ + 1f) + InstallGridViewportPaddingCells);
        return true;
    }

    private void EnsureInstallGridResources()
    {
        if (!Application.isPlaying)
        {
            return;
        }

        if (installGridObject == null)
        {
            installGridObject = new GameObject(InstallGridOverlayObjectName);
            installGridObject.hideFlags = HideFlags.HideAndDontSave;
            installGridObject.transform.SetPositionAndRotation(Vector3.zero, Quaternion.identity);
            installGridMeshFilter = installGridObject.AddComponent<MeshFilter>();
            installGridMeshRenderer = installGridObject.AddComponent<MeshRenderer>();
        }

        if (installGridPreviewObject == null)
        {
            installGridPreviewObject = new GameObject(InstallGridPreviewOverlayObjectName);
            installGridPreviewObject.hideFlags = HideFlags.HideAndDontSave;
            installGridPreviewObject.transform.SetParent(installGridObject.transform, false);
            installGridPreviewObject.transform.localPosition = Vector3.zero;
            installGridPreviewObject.transform.localRotation = Quaternion.identity;
            installGridPreviewMeshFilter = installGridPreviewObject.AddComponent<MeshFilter>();
            installGridPreviewMeshRenderer = installGridPreviewObject.AddComponent<MeshRenderer>();
        }
        else if (installGridObject != null && installGridPreviewObject.transform.parent != installGridObject.transform)
        {
            installGridPreviewObject.transform.SetParent(installGridObject.transform, false);
        }

        if (installGridMesh == null)
        {
            installGridMesh = new Mesh
            {
                name = "InstallationGridOverlayMesh",
                hideFlags = HideFlags.DontSave
            };
            installGridMesh.MarkDynamic();
        }

        if (installGridPreviewMesh == null)
        {
            installGridPreviewMesh = new Mesh
            {
                name = "InstallationGridPreviewOverlayMesh",
                hideFlags = HideFlags.DontSave
            };
            installGridPreviewMesh.MarkDynamic();
        }

        if (installGridMeshFilter != null && installGridMeshFilter.sharedMesh != installGridMesh)
        {
            installGridMeshFilter.sharedMesh = installGridMesh;
        }

        if (installGridPreviewMeshFilter != null && installGridPreviewMeshFilter.sharedMesh != installGridPreviewMesh)
        {
            installGridPreviewMeshFilter.sharedMesh = installGridPreviewMesh;
        }

        if (installGridMaterial == null)
        {
            Shader shader = Shader.Find(InstallGridOverlayShaderName);
            if (shader == null)
            {
                shader = Shader.Find("Sprites/Default");
            }
            if (shader == null)
            {
                shader = Shader.Find("Unlit/Color");
            }
            if (shader == null)
            {
                shader = Shader.Find("Universal Render Pipeline/Unlit");
            }

            if (shader != null)
            {
                installGridMaterial = new Material(shader)
                {
                    name = "InstallationGridOverlayMaterial",
                    hideFlags = HideFlags.DontSave
                };
            }
        }

        if (installGridMaterial != null)
        {
            ApplyGridMaterialColor(installGridMaterial);
        }

        if (installGridMeshRenderer != null)
        {
            installGridMeshRenderer.sharedMaterial = installGridMaterial;
            installGridMeshRenderer.sortingOrder = 5000;
            installGridMeshRenderer.shadowCastingMode = ShadowCastingMode.Off;
            installGridMeshRenderer.receiveShadows = false;
            installGridMeshRenderer.lightProbeUsage = LightProbeUsage.Off;
            installGridMeshRenderer.reflectionProbeUsage = ReflectionProbeUsage.Off;
        }

        if (installGridPreviewMeshRenderer != null)
        {
            installGridPreviewMeshRenderer.sharedMaterial = installGridMaterial;
            installGridPreviewMeshRenderer.sortingOrder = 5001;
            installGridPreviewMeshRenderer.shadowCastingMode = ShadowCastingMode.Off;
            installGridPreviewMeshRenderer.receiveShadows = false;
            installGridPreviewMeshRenderer.lightProbeUsage = LightProbeUsage.Off;
            installGridPreviewMeshRenderer.reflectionProbeUsage = ReflectionProbeUsage.Off;
        }
    }

    private bool RebuildInstallGridMesh()
    {
        EnsureInstallGridResources();

        if (installGridMesh == null)
        {
            return true;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null || !TryGetInstallGridEffectiveBounds(out Vector2Int minCoordinate, out Vector2Int maxCoordinate))
        {
            installGridMesh.Clear();
            installGridBoundsInitialized = false;
            ResetInstallGridMeshBuild();
            return true;
        }

        bool showFullGrid = IsInstallGridModeActive();
        bool showConveyorDebugOnly = !showFullGrid
            && GameManager.Instance != null
            && GameManager.Instance.DebugConveyorInstallGridEnds;

        if (!installGridMeshBuildInitialized
            || installGridMinCoordinate != minCoordinate
            || installGridMaxCoordinate != maxCoordinate)
        {
            installGridMinCoordinate = minCoordinate;
            installGridMaxCoordinate = maxCoordinate;
            installGridBoundsInitialized = true;
            installGridMeshBuildInitialized = true;
            installGridBlockedCoordinates.Clear();
            RestoreCachedInstallGridBlockedCoordinates(minCoordinate, maxCoordinate);
        }

        bool shouldValidateBlockedCells = showFullGrid
                                          && activeInstallDefinition != null
                                          && activeInstallDefinition.mapObject != null;
        if (shouldValidateBlockedCells)
        {
            ValidateInstallGridBlockedCells(terrain, minCoordinate, maxCoordinate);
        }

        float lineY = terrain.transform.position.y + installGridVerticalOffset;
        float fillY = lineY - 0.002f;
        float conveyorDebugArrowY = lineY + ConveyorDebugArrowWorldLift;
        float minX = minCoordinate.x - 0.5f;
        float maxX = maxCoordinate.x + 0.5f;
        float minZ = minCoordinate.y - 0.5f;
        float maxZ = maxCoordinate.y + 0.5f;

        List<Vector3> vertices = installGridVertices;
        List<int> triangles = installGridTriangles;
        List<Color> colors = installGridColors;
        vertices.Clear();
        triangles.Clear();
        colors.Clear();

        if (showFullGrid)
        {
            for (int i = 0; i < installGridBlockedCoordinates.Count; i++)
            {
                AddGridCellQuad(
                    vertices,
                    triangles,
                    colors,
                    installGridBlockedCoordinates[i],
                    fillY,
                    installGridBlockedFillColor);
            }
        }

        if (showConveyorDebugOnly)
        {
            AddInstalledConveyorDebugEnds(vertices, triangles, colors, minCoordinate, maxCoordinate, conveyorDebugArrowY);
        }

        if (showFullGrid)
        {
            for (int x = minCoordinate.x; x <= maxCoordinate.x + 1; x++)
            {
                float lineX = x - 0.5f;
                AddGridLineQuad(
                    vertices,
                    triangles,
                    colors,
                    new Vector3(lineX, lineY, minZ),
                    new Vector3(lineX, lineY, maxZ),
                    installGridColor);
            }

            for (int z = minCoordinate.y; z <= maxCoordinate.y + 1; z++)
            {
                float lineZ = z - 0.5f;
                AddGridLineQuad(
                    vertices,
                    triangles,
                    colors,
                    new Vector3(minX, lineY, lineZ),
                    new Vector3(maxX, lineY, lineZ),
                    installGridColor);
            }
        }

        installGridMesh.Clear();
        installGridMesh.SetVertices(vertices);
        installGridMesh.SetTriangles(triangles, 0, true);
        installGridMesh.SetColors(colors);
        installGridMesh.RecalculateBounds();
        return true;
    }

    private void ValidateInstallGridBlockedCells(
        TerrainGenerator terrain,
        Vector2Int minCoordinate,
        Vector2Int maxCoordinate)
    {
        MapObject activeGridSource = activeInstallDefinition != null
            ? activeInstallDefinition.mapObject
            : null;
        if (terrain == null || activeGridSource == null)
        {
            return;
        }

        bool useFastBoilerGridCheck = IsBoilerSource(activeGridSource);
        bool useFastSteamGeneratorGridCheck = IsSteamGeneratorSource(activeGridSource);
        CleanupInstallPreviewReferences();
        installGridValidationInProgress = true;
        installGridValidationUsesSimpleRectGridFastPath =
            CanUseSimpleRectGridInstallGridCheck(activeGridSource);
        installGridSimpleAllowedFilter = activeGridSource is InstallationObject activeGridInstallation
            ? ResolvePlacementMapFilter(activeGridSource, activeGridInstallation)
            : InstallationMapFilter.Ground;
        try
        {
            for (int z = minCoordinate.y; z <= maxCoordinate.y; z++)
            {
                for (int x = minCoordinate.x; x <= maxCoordinate.x; x++)
                {
                    Vector2Int coordinate = new Vector2Int(x, z);
                    if (installGridPlacementValidityCache.ContainsKey(coordinate))
                    {
                        continue;
                    }

                    bool canPlace = !terrain.TryGetLoadedBlock(coordinate, out Block block)
                                    || block == null
                                    || CanPlaceActiveDefinitionFromGridCoordinate(
                                        block,
                                        useFastBoilerGridCheck,
                                        useFastSteamGeneratorGridCheck);
                    installGridPlacementValidityCache[coordinate] = canPlace;
                    if (!canPlace)
                    {
                        installGridBlockedCoordinates.Add(coordinate);
                    }
                }
            }
        }
        finally
        {
            installGridSimpleAllowedFilter = InstallationMapFilter.None;
            installGridValidationUsesSimpleRectGridFastPath = false;
            installGridValidationInProgress = false;
        }
    }

    private void RestoreCachedInstallGridBlockedCoordinates(
        Vector2Int minCoordinate,
        Vector2Int maxCoordinate)
    {
        for (int z = minCoordinate.y; z <= maxCoordinate.y; z++)
        {
            for (int x = minCoordinate.x; x <= maxCoordinate.x; x++)
            {
                Vector2Int coordinate = new Vector2Int(x, z);
                if (installGridPlacementValidityCache.TryGetValue(coordinate, out bool canPlace)
                    && !canPlace)
                {
                    installGridBlockedCoordinates.Add(coordinate);
                }
            }
        }
    }

    private void RebuildInstallGridPreviewMesh()
    {
        EnsureInstallGridResources();

        if (installGridPreviewMesh == null)
        {
            return;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null || !IsInstallGridModeActive())
        {
            installGridPreviewMesh.Clear();
            return;
        }

        float lineY = terrain.transform.position.y + installGridVerticalOffset + 0.001f;
        float fillY = lineY - 0.002f;
        List<Vector3> vertices = installGridVertices;
        List<int> triangles = installGridTriangles;
        List<Color> colors = installGridColors;
        vertices.Clear();
        triangles.Clear();
        colors.Clear();

        AddInstallPreviewFootprintFill(vertices, triangles, colors, fillY);
        AddInstallPreviewFootprintOutline(vertices, triangles, colors, lineY + 0.001f);

        installGridPreviewMesh.Clear();
        if (vertices.Count <= 0)
        {
            return;
        }

        installGridPreviewMesh.SetVertices(vertices);
        installGridPreviewMesh.SetTriangles(triangles, 0, true);
        installGridPreviewMesh.SetColors(colors);
        installGridPreviewMesh.RecalculateBounds();
    }

    private bool CanPlaceActiveDefinitionFromGridCoordinate(
        Block block,
        bool useFastBoilerGridCheck = false,
        bool useFastSteamGeneratorGridCheck = false)
    {
        if (block == null || activeInstallDefinition == null || activeInstallDefinition.mapObject == null)
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null || terrain.HasDroppedFloorObjectsAt(block.Coordinate))
        {
            return false;
        }

        MapObject footprintSource = activeInstallDefinition.mapObject;
        if (useFastBoilerGridCheck)
        {
            return CanPlaceBoilerFromGridCoordinateFast(block, footprintSource);
        }

        if (useFastSteamGeneratorGridCheck)
        {
            return CanPlaceSteamGeneratorFromGridCoordinateFast(block, footprintSource);
        }

        if (!IsBelt2F(footprintSource))
        {
            if (footprintSource is Pipe pipePrototype)
            {
                return CanPlacePipeFromGridCoordinate(block, pipePrototype);
            }

            if (IsBoilerSource(footprintSource) && IsExactPumpOutputCoordinateForPlacement(block.Coordinate))
            {
                return true;
            }

            if (IsWaterPumpSource(footprintSource))
            {
                int preferredQuarterTurns = activeInstallPreview != null
                    ? GetPreviewQuarterTurns(activeInstallPreview)
                    : GetPreferredInstallPreviewQuarterTurns(activeInstallDefinition, null);
                return TryResolvePlaceableInstallPreviewTarget(
                    block,
                    activeInstallPreview,
                    preferredQuarterTurns,
                    false,
                    out _,
                    out _);
            }

            if (IsTrainStationSource(footprintSource))
            {
                int preferredQuarterTurns = activeInstallPreview != null
                    ? GetPreviewQuarterTurns(activeInstallPreview)
                    : GetPreferredInstallPreviewQuarterTurns(activeInstallDefinition, null);
                return TryResolvePlaceableInstallPreviewTarget(
                    block,
                    activeInstallPreview,
                    preferredQuarterTurns,
                    false,
                    out _,
                    out _);
            }

            if (HasMultiCellMapSize(footprintSource))
            {
                int preferredQuarterTurns = activeInstallPreview != null
                    ? GetPreviewQuarterTurns(activeInstallPreview)
                    : GetPreferredInstallPreviewQuarterTurns(activeInstallDefinition, null);
                if (CanUseSimpleRectGridInstallGridCheck(footprintSource))
                {
                    return CanPlaceSimpleRectGridFromGridCoordinateFast(
                        block,
                        footprintSource,
                        preferredQuarterTurns,
                        activeInstallPreview);
                }

                return TryResolvePlaceableInstallPreviewTarget(
                    block,
                    activeInstallPreview,
                    preferredQuarterTurns,
                    false,
                    out _,
                    out _);
            }

            return CanPlacePreviewOnTargetBlockType(block, footprintSource);
        }

        return CanPlaceBelt2FGridTargetBlock(block, footprintSource);
    }

    private bool CanUseSimpleRectGridInstallGridCheck(MapObject footprintSource)
    {
        if (footprintSource == null
            || IsBelt2F(footprintSource)
            || IsWaterPumpSource(footprintSource)
            || IsBoilerSource(footprintSource)
            || IsSteamGeneratorSource(footprintSource)
            || footprintSource is Pipe
            || footprintSource is Pump
            || footprintSource is Wall)
        {
            return false;
        }

        if (footprintSource is InstallationObject installationObject && installationObject.CanStoreFluid)
        {
            return false;
        }

        return TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
               && inputOutputModule.LayoutType == InputOutputModule.SlotLayoutType.RectGrid
               && inputOutputModule.RectGridPlacements != null
               && inputOutputModule.RectGridPlacements.Count > 0;
    }

    private bool CanPlaceSimpleRectGridFromGridCoordinateFast(
        Block clickedBlock,
        MapObject footprintSource,
        int preferredQuarterTurns,
        MapObject previewToIgnore)
    {
        if (clickedBlock == null
            || footprintSource == null
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        int baseQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (rectGridWidth == 1
            && rectGridHeight == 1
            && TryResolveTrainStationFacingQuarterTurns(
                clickedBlock.Coordinate,
                footprintSource,
                previewToIgnore,
                baseQuarterTurns,
                out int trainStationQuarterTurns))
        {
            baseQuarterTurns = trainStationQuarterTurns;
            candidateCount = 1;
        }

        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizeInstallPreviewQuarterTurns(
                previewToIgnore,
                baseQuarterTurns + offset);
            for (int i = 0; i < placements.Count; i++)
            {
                InputOutputModule.RectGridBlockPlacement placement = placements[i];
                if (placement.blockType == InputOutputModule.RectGridBlockType.None
                    || placement.x < 0
                    || placement.x >= rectGridWidth
                    || placement.y < 0
                    || placement.y >= rectGridHeight)
                {
                    continue;
                }

                Vector2Int localOffset = new Vector2Int(
                    placement.x - objectAnchorCell.x,
                    placement.y - objectAnchorCell.y);
                Vector2Int candidateAnchorCoordinate =
                    clickedBlock.Coordinate - RotateFootprintOffset(localOffset, candidateQuarterTurns);
                Vector3Int cacheKey = new Vector3Int(
                    candidateAnchorCoordinate.x,
                    candidateAnchorCoordinate.y,
                    candidateQuarterTurns);
                if (!installGridRectAnchorValidityCache.TryGetValue(cacheKey, out bool canPlaceAtAnchor))
                {
                    canPlaceAtAnchor = CanPlaceSimpleRectGridAtAnchorFast(
                        terrain,
                        candidateAnchorCoordinate,
                        footprintSource,
                        candidateQuarterTurns,
                        previewToIgnore,
                        placements,
                        rectGridWidth,
                        rectGridHeight,
                        objectAnchorCell);
                    installGridRectAnchorValidityCache[cacheKey] = canPlaceAtAnchor;
                }

                if (canPlaceAtAnchor)
                {
                    return true;
                }
            }
        }

        return false;
    }

    private bool TryResolveSimpleRectGridInstallPreviewTargetFast(
        Block clickedBlock,
        MapObject footprintSource,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        bool preserveRotation,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || footprintSource == null
            || !CanUseSimpleRectGridInstallGridCheck(footprintSource)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        int candidateCount = preserveRotation
            ? 1
            : GetPlacementRotationCandidateCount(footprintSource);
        int baseQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (rectGridWidth == 1
            && rectGridHeight == 1
            && TryResolveTrainStationFacingQuarterTurns(
                clickedBlock.Coordinate,
                footprintSource,
                previewToIgnore,
                baseQuarterTurns,
                out int trainStationQuarterTurns))
        {
            baseQuarterTurns = trainStationQuarterTurns;
            candidateCount = 1;
        }

        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizeInstallPreviewQuarterTurns(
                previewToIgnore,
                baseQuarterTurns + offset);
            for (int priorityPass = 0; priorityPass < 2; priorityPass++)
            {
                for (int i = 0; i < placements.Count; i++)
                {
                    InputOutputModule.RectGridBlockPlacement placement = placements[i];
                    if (!ShouldEvaluateSimpleRectGridTargetPlacement(
                            placement,
                            rectGridWidth,
                            rectGridHeight,
                            priorityPass))
                    {
                        continue;
                    }

                    Vector2Int localOffset = new Vector2Int(
                        placement.x - objectAnchorCell.x,
                        placement.y - objectAnchorCell.y);
                    Vector2Int candidateAnchorCoordinate =
                        clickedBlock.Coordinate - RotateFootprintOffset(localOffset, candidateQuarterTurns);
                    if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                        || candidateAnchorBlock == null
                        || !CanPlaceSimpleRectGridAtAnchorFast(
                            terrain,
                            candidateAnchorCoordinate,
                            footprintSource,
                            candidateQuarterTurns,
                            previewToIgnore,
                            placements,
                            rectGridWidth,
                            rectGridHeight,
                            objectAnchorCell))
                    {
                        continue;
                    }

                    anchorBlock = candidateAnchorBlock;
                    resolvedQuarterTurns = candidateQuarterTurns;
                    return true;
                }
            }
        }

        return false;
    }

    private static bool ShouldEvaluateSimpleRectGridTargetPlacement(
        InputOutputModule.RectGridBlockPlacement placement,
        int rectGridWidth,
        int rectGridHeight,
        int priorityPass)
    {
        if (placement.blockType == InputOutputModule.RectGridBlockType.None
            || placement.x < 0
            || placement.x >= rectGridWidth
            || placement.y < 0
            || placement.y >= rectGridHeight)
        {
            return false;
        }

        bool isObjectPlacement = placement.blockType == InputOutputModule.RectGridBlockType.Object;
        return priorityPass == 0 ? isObjectPlacement : !isObjectPlacement;
    }

    private bool CanPlaceSimpleRectGridAtAnchorFast(
        TerrainGenerator terrain,
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore,
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements,
        int rectGridWidth,
        int rectGridHeight,
        Vector2Int objectAnchorCell)
    {
        if (terrain == null || footprintSource == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        if (!OilDrillingMachinePlacementMatchesOil(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                previewToIgnore))
        {
            return false;
        }

        if (PlacementHasNormalInputOutputAreaPipeOverlap(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                previewToIgnore))
        {
            return false;
        }

        bool checkedAnyPlacement = false;
        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (placement.blockType == InputOutputModule.RectGridBlockType.None
                || placement.x < 0
                || placement.x >= rectGridWidth
                || placement.y < 0
                || placement.y >= rectGridHeight)
            {
                continue;
            }

            Vector2Int localOffset = new Vector2Int(
                placement.x - objectAnchorCell.x,
                placement.y - objectAnchorCell.y);
            Vector2Int coordinate = anchorCoordinate + RotateFootprintOffset(localOffset, quarterTurns);
            if (!terrain.TryGetLoadedBlock(coordinate, out Block footprintBlock)
                || footprintBlock == null
                || terrain.HasDroppedFloorObjectsAt(coordinate))
            {
                return false;
            }

            if (!IsInstallGridSimpleClearCell(
                    footprintBlock,
                    footprintSource,
                    previewToIgnore)
                && !CanPlacePreviewOnTargetBlockType(
                    footprintBlock,
                    footprintSource,
                    placement.blockType,
                    anchorCoordinate,
                    quarterTurns,
                    previewToIgnore))
            {
                return false;
            }

            if (TryGetInstallPreviewAtCoordinate(coordinate, out MapObject existingPreview)
                && existingPreview != null
                && existingPreview != previewToIgnore
                && !CanOverlapCompatibleInstallPreview(
                    coordinate,
                    footprintSource,
                    placement.blockType,
                    anchorCoordinate,
                    quarterTurns,
                    existingPreview))
            {
                return false;
            }

            checkedAnyPlacement = true;
        }

        return checkedAnyPlacement;
    }

    private bool IsInstallGridSimpleClearCell(
        Block block,
        MapObject footprintSource,
        MapObject previewToIgnore)
    {
        if (!installGridValidationInProgress
            || !installGridValidationUsesSimpleRectGridFastPath
            || block == null
            || footprintSource == null)
        {
            return false;
        }

        Vector2Int coordinate = block.Coordinate;
        if (installGridSimpleClearCellCache.TryGetValue(coordinate, out bool isClear))
        {
            return isClear;
        }

        MapObject occupyingObject = GetOccupyingObjectForPlacement(block, previewToIgnore);
        bool hasOtherPreview = TryGetInstallPreviewAtCoordinate(
                                   coordinate,
                                   out MapObject existingPreview)
                               && existingPreview != null
                               && existingPreview != previewToIgnore;
        isClear = occupyingObject == null
                  && block.Resource == null
                  && !hasOtherPreview
                  && CanPlaceOnTerrainBiome(block, installGridSimpleAllowedFilter)
                  && !CoordinateHasNormalInputOutputAreaBlockForPlacement(
                      coordinate,
                      previewToIgnore)
                  && !InputOutputModule.CoordinateIsRuntimeInputOutputAreaBlock(coordinate)
                  && !HasPipeAreaFluidStorageAtCoordinate(coordinate)
                  && !IsPumpOutputCoordinateForPlacement(coordinate);
        installGridSimpleClearCellCache[coordinate] = isClear;
        return isClear;
    }

    private bool CanPlaceBoilerFromGridCoordinateFast(Block block, MapObject footprintSource)
    {
        if (block == null || !TryResolveInstallationObject(footprintSource, out InstallationObject installationObject))
        {
            return false;
        }

        InstallationMapFilter allowedFilter = ResolvePlacementMapFilter(footprintSource, installationObject);
        if (!CanPlaceOnTerrainBiome(block, allowedFilter))
        {
            return false;
        }

        MapObject occupyingObject = GetOccupyingObjectForPlacement(block);

        return occupyingObject == null
               || occupyingObject is Pump
               || IsFluidStoragePlacementObject(occupyingObject)
               || IsInstallationObjectAllowedForPlacement(occupyingObject, allowedFilter);
    }

    private bool CanPlaceSteamGeneratorFromGridCoordinateFast(Block block, MapObject footprintSource)
    {
        if (block == null || !TryResolveInstallationObject(footprintSource, out InstallationObject installationObject))
        {
            return false;
        }

        InstallationMapFilter allowedFilter = ResolvePlacementMapFilter(footprintSource, installationObject);
        if (!CanPlaceOnTerrainBiome(block, allowedFilter))
        {
            return false;
        }

        MapObject occupyingObject = GetOccupyingObjectForPlacement(block);
        if (occupyingObject == null
            || occupyingObject is BoxObject
            || IsResourceAllowedForPlacement(block, occupyingObject, allowedFilter)
            || IsInstallationObjectAllowedForPlacement(occupyingObject, allowedFilter))
        {
            return true;
        }

        return occupyingObject is Pipe
               || IsBoilerSource(occupyingObject)
               || IsSteamGeneratorSource(occupyingObject);
    }

    private bool CanPlacePipeFromGridCoordinate(Block block, Pipe pipePrototype)
    {
        if (block == null || pipePrototype == null)
        {
            return false;
        }

        InstallationMapFilter allowedFilter = ResolvePlacementMapFilter(pipePrototype, pipePrototype);
        if (!CanPlaceOnTerrainBiome(block, allowedFilter))
        {
            return false;
        }

        if (CoordinateHasBoilerEnergyInputBlockForPlacement(block.Coordinate, null))
        {
            return false;
        }

        bool isInputOutputAreaBlock =
            InputOutputModuleEnergyAreaController.CoordinateIsEnergyArea(block.Coordinate)
            || InputOutputModuleItemAreaController.CoordinateIsItemArea(block.Coordinate)
            || InputOutputModuleOutputAreaController.CoordinateIsOutputArea(block.Coordinate)
            || InputOutputModule.CoordinateIsRuntimeInputOutputAreaBlock(block.Coordinate);
        bool isRuntimePipeAreaBlock = InputOutputModule.CoordinateAllowsRuntimePipeBlock(block.Coordinate);
        if (isInputOutputAreaBlock && !isRuntimePipeAreaBlock)
        {
            return false;
        }

        MapObject occupyingObject = GetOccupyingObjectForPlacement(block);

        if (IsResourceAllowedForPlacement(block, occupyingObject, allowedFilter))
        {
            return true;
        }

        if (IsRailloadAllowedForPlacement(block, occupyingObject, allowedFilter))
        {
            return true;
        }

        if (IsInstallationObjectAllowedForPlacement(occupyingObject, allowedFilter))
        {
            return true;
        }

        if (CanPlacePassthroughOnBelt2FBridgeCenter(
                block,
                pipePrototype,
                occupyingObject,
                0))
        {
            return true;
        }

        return occupyingObject == null;
    }

    private void AddInstallPreviewFootprintFill(List<Vector3> vertices, List<int> triangles, List<Color> colors, float fillY)
    {
        CleanupInstallPreviewReferences();

        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            MapObject preview = installPreviewInstances[i];
            if (preview == null
                || preview != activeInstallPreview
                || !TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate))
            {
                continue;
            }

            int quarterTurns = GetPreviewAreaQuarterTurns(preview);
            bool isBlockedPreview = false;
            if (ResolveInstallPreviewTerrain() != null
                && ResolveInstallPreviewTerrain().TryGetLoadedBlock(anchorCoordinate, out Block anchorBlock)
                && anchorBlock != null)
            {
                isBlockedPreview = !CanPlacePreviewOnBlock(anchorBlock, preview, quarterTurns);
            }

            Color previewFillColor = isBlockedPreview
                ? installGridBlockedFillColor
                : GetInstallPreviewFootprintFillColor(preview);
            List<Vector2Int> occupiedCoordinates = GetInstallPreviewAreaDisplayCoordinates(
                preview,
                anchorCoordinate,
                quarterTurns);
            for (int coordinateIndex = 0; coordinateIndex < occupiedCoordinates.Count; coordinateIndex++)
            {
                Vector2Int coordinate = occupiedCoordinates[coordinateIndex];
                AddGridCellQuad(
                    vertices,
                    triangles,
                    colors,
                    coordinate,
                    fillY,
                    previewFillColor);
            }
        }
    }

    private Color GetInstallPreviewFootprintFillColor(MapObject preview)
    {
        Color color = ResolveInstallPreviewTint(preview);
        color.a = Mathf.Min(color.a, InstallPreviewFootprintFillAlpha);
        return color;
    }

    private void AddInstallPreviewFootprintOutline(List<Vector3> vertices, List<int> triangles, List<Color> colors, float lineY)
    {
        CleanupInstallPreviewReferences();

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            MapObject preview = installPreviewInstances[i];
            if (preview == null
                || preview != activeInstallPreview
                || !TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate))
            {
                continue;
            }

            int quarterTurns = GetPreviewAreaQuarterTurns(preview);
            bool isBlockedPreview = false;
            if (terrain != null
                && terrain.TryGetLoadedBlock(anchorCoordinate, out Block anchorBlock)
                && anchorBlock != null)
            {
                isBlockedPreview = !CanPlacePreviewOnBlock(anchorBlock, preview, quarterTurns);
            }

            Color previewLineColor = isBlockedPreview ? installGridBlockedLineColor : installGridColor;
            List<Vector2Int> occupiedCoordinates = GetInstallPreviewAreaDisplayCoordinates(
                preview,
                anchorCoordinate,
                quarterTurns);
            for (int coordinateIndex = 0; coordinateIndex < occupiedCoordinates.Count; coordinateIndex++)
            {
                Vector2Int coordinate = occupiedCoordinates[coordinateIndex];
                AddGridCellOutline(
                    vertices,
                    triangles,
                    colors,
                    coordinate,
                    lineY,
                    previewLineColor);
            }
        }
    }

    private void AddGridCellOutline(List<Vector3> vertices, List<int> triangles, List<Color> colors, Vector2Int coordinate, float y, Color color)
    {
        AddGridEdgeLine(vertices, triangles, colors, coordinate, Vector2Int.up, y, color);
        AddGridEdgeLine(vertices, triangles, colors, coordinate, Vector2Int.right, y, color);
        AddGridEdgeLine(vertices, triangles, colors, coordinate, Vector2Int.down, y, color);
        AddGridEdgeLine(vertices, triangles, colors, coordinate, Vector2Int.left, y, color);
    }

    private void AddInstalledConveyorDebugEnds(List<Vector3> vertices, List<int> triangles, List<Color> colors, Vector2Int minCoordinate, Vector2Int maxCoordinate, float lineY)
    {
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return;
        }

        HashSet<Vector2Int> drawnAnchors = new HashSet<Vector2Int>();
        for (int z = minCoordinate.y; z <= maxCoordinate.y; z++)
        {
            for (int x = minCoordinate.x; x <= maxCoordinate.x; x++)
            {
                Vector2Int coordinate = new Vector2Int(x, z);
                if (!terrain.TryGetLoadedBlock(coordinate, out Block block)
                    || block == null
                    || !(block.MapObject is ConveyorBelt conveyor)
                    || conveyor == null
                    || !conveyor.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out _)
                    || !drawnAnchors.Add(anchorCoordinate))
                {
                    continue;
                }

                Quaternion rotation = conveyor.transform.rotation;
                if (!conveyor.TryGetOutputDirection(rotation, out Vector2Int outputDirection))
                {
                    continue;
                }

                if (!conveyor.TryGetInputDirection(rotation, out Vector2Int inputDirection))
                {
                    inputDirection = -outputDirection;
                }

                AddConveyorFlowArrow(vertices, triangles, colors, anchorCoordinate, inputDirection, outputDirection, lineY + 0.001f, installGridConveyorEndDebugColor);
            }
        }
    }

    private void AddConveyorFlowArrow(
        List<Vector3> vertices,
        List<int> triangles,
        List<Color> colors,
        Vector2Int anchorCoordinate,
        Vector2Int inputDirection,
        Vector2Int outputDirection,
        float y,
        Color color)
    {
        if (inputDirection == Vector2Int.zero || outputDirection == Vector2Int.zero)
        {
            return;
        }

        Vector3 center = new Vector3(anchorCoordinate.x, y, anchorCoordinate.y);
        Vector3 inputPoint = center + DirectionToWorld(inputDirection) * installGridConveyorArrowInset;
        Vector3 outputPoint = center + DirectionToWorld(outputDirection) * installGridConveyorArrowInset;

        if (inputDirection == -outputDirection)
        {
            AddGridLineQuad(vertices, triangles, colors, inputPoint, outputPoint, color);
            AddArrowHead(vertices, triangles, colors, Vector3.Lerp(inputPoint, outputPoint, 0.45f), (outputPoint - inputPoint).normalized, color);
            AddArrowHead(vertices, triangles, colors, Vector3.Lerp(inputPoint, outputPoint, 0.75f), (outputPoint - inputPoint).normalized, color);
            return;
        }

        AddGridLineQuad(vertices, triangles, colors, inputPoint, center, color);
        AddGridLineQuad(vertices, triangles, colors, center, outputPoint, color);
        AddArrowHead(vertices, triangles, colors, Vector3.Lerp(inputPoint, center, 0.68f), (center - inputPoint).normalized, color);
        AddArrowHead(vertices, triangles, colors, Vector3.Lerp(center, outputPoint, 0.68f), (outputPoint - center).normalized, color);
    }

    private void AddArrowHead(
        List<Vector3> vertices,
        List<int> triangles,
        List<Color> colors,
        Vector3 center,
        Vector3 direction,
        Color color)
    {
        if (direction.sqrMagnitude <= 0.0001f)
        {
            return;
        }

        Vector3 normalizedDirection = direction.normalized;
        Vector3 tip = center + normalizedDirection * (installGridConveyorArrowHeadLength * 0.5f);
        Vector3 baseCenter = center - normalizedDirection * (installGridConveyorArrowHeadLength * 0.5f);
        Vector3 perpendicular = Vector3.Cross(Vector3.up, normalizedDirection) * (installGridConveyorArrowHeadWidth * 0.5f);
        int startIndex = vertices.Count;

        vertices.Add(tip);
        vertices.Add(baseCenter + perpendicular);
        vertices.Add(baseCenter - perpendicular);

        colors.Add(color);
        colors.Add(color);
        colors.Add(color);

        triangles.Add(startIndex);
        triangles.Add(startIndex + 1);
        triangles.Add(startIndex + 2);
    }

    private static Vector3 DirectionToWorld(Vector2Int direction)
    {
        return new Vector3(direction.x, 0f, direction.y).normalized;
    }

    private Quaternion wasActivePreviewRotation(MapObject preview)
    {
        if (preview == null)
        {
            return Quaternion.identity;
        }

        if (preview == activeInstallPreview)
        {
            return GetInstallPreviewRotation();
        }

        int quarterTurns = GetPreviewQuarterTurns(preview);
        MapObject rotationSource = ResolveInstallPreviewRotationSource(preview);
        Quaternion previewBaseRotation = installPreviewBaseRotationsByPreview.TryGetValue(preview, out Quaternion storedBaseRotation)
            ? storedBaseRotation
            : (rotationSource != null ? rotationSource.transform.rotation : preview.transform.rotation);
        if (TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate))
        {
            Vector3 railReferencePosition = installPreviewRailReferenceWorldPositions.TryGetValue(
                preview,
                out Vector3 storedRailReferencePosition)
                ? storedRailReferencePosition
                : preview.transform.position;
            return ResolvePlacementObjectRotation(
                previewBaseRotation,
                rotationSource,
                anchorCoordinate,
                quarterTurns,
                railReferencePosition);
        }

        return GetPlacementObjectRotation(previewBaseRotation, rotationSource, quarterTurns);
    }

    private void AddGridEdgeLine(List<Vector3> vertices, List<int> triangles, List<Color> colors, Vector2Int coordinate, Vector2Int direction, float y, Color color)
    {
        if (direction == Vector2Int.zero)
        {
            return;
        }

        float minX = coordinate.x - 0.5f;
        float maxX = coordinate.x + 0.5f;
        float minZ = coordinate.y - 0.5f;
        float maxZ = coordinate.y + 0.5f;

        Vector3 start;
        Vector3 end;

        if (direction == Vector2Int.up)
        {
            start = new Vector3(minX, y, maxZ);
            end = new Vector3(maxX, y, maxZ);
        }
        else if (direction == Vector2Int.down)
        {
            start = new Vector3(minX, y, minZ);
            end = new Vector3(maxX, y, minZ);
        }
        else if (direction == Vector2Int.left)
        {
            start = new Vector3(minX, y, minZ);
            end = new Vector3(minX, y, maxZ);
        }
        else if (direction == Vector2Int.right)
        {
            start = new Vector3(maxX, y, minZ);
            end = new Vector3(maxX, y, maxZ);
        }
        else
        {
            return;
        }

        AddGridLineQuad(vertices, triangles, colors, start, end, color);
    }

    private void AddGridLineQuad(List<Vector3> vertices, List<int> triangles, List<Color> colors, Vector3 start, Vector3 end, Color color)
    {
        Vector3 direction = end - start;
        if (direction.sqrMagnitude <= 0.0001f)
        {
            return;
        }

        Vector3 perpendicular = Vector3.Cross(Vector3.up, direction.normalized) * (installGridLineWidth * 0.5f);
        int startIndex = vertices.Count;

        vertices.Add(start - perpendicular);
        vertices.Add(start + perpendicular);
        vertices.Add(end + perpendicular);
        vertices.Add(end - perpendicular);

        colors.Add(color);
        colors.Add(color);
        colors.Add(color);
        colors.Add(color);

        triangles.Add(startIndex);
        triangles.Add(startIndex + 1);
        triangles.Add(startIndex + 2);
        triangles.Add(startIndex);
        triangles.Add(startIndex + 2);
        triangles.Add(startIndex + 3);
    }

    private static void AddGridCellQuad(List<Vector3> vertices, List<int> triangles, List<Color> colors, Vector2Int coordinate, float y, Color color)
    {
        float minX = coordinate.x - 0.5f;
        float maxX = coordinate.x + 0.5f;
        float minZ = coordinate.y - 0.5f;
        float maxZ = coordinate.y + 0.5f;
        int startIndex = vertices.Count;

        vertices.Add(new Vector3(minX, y, minZ));
        vertices.Add(new Vector3(minX, y, maxZ));
        vertices.Add(new Vector3(maxX, y, maxZ));
        vertices.Add(new Vector3(maxX, y, minZ));

        colors.Add(color);
        colors.Add(color);
        colors.Add(color);
        colors.Add(color);

        triangles.Add(startIndex);
        triangles.Add(startIndex + 1);
        triangles.Add(startIndex + 2);
        triangles.Add(startIndex);
        triangles.Add(startIndex + 2);
        triangles.Add(startIndex + 3);
    }

    private void ApplyGridMaterialColor(Material material)
    {
        if (material == null)
        {
            return;
        }

        if (material.HasProperty(BaseColorPropertyId))
        {
            material.SetColor(BaseColorPropertyId, installGridColor);
        }

        if (material.HasProperty(ColorPropertyId))
        {
            material.SetColor(ColorPropertyId, installGridColor);
        }
    }

    private void SetInstallGridVisible(bool isVisible)
    {
        if (isVisible && !Application.isPlaying)
        {
            ReleaseInstallGridResources();
            return;
        }

        if (installGridObject == null)
        {
            if (!isVisible)
            {
                return;
            }

            EnsureInstallGridResources();
        }

        if (installGridObject != null && installGridObject.activeSelf != isVisible)
        {
            installGridObject.SetActive(isVisible);
        }

        if (installGridPreviewObject != null && installGridPreviewObject.activeSelf != isVisible)
        {
            installGridPreviewObject.SetActive(isVisible);
        }
    }

    private void ReleaseInstallGridResources()
    {
        // Destroy() is deferred while playing. Disable the renderers immediately so
        // a play-mode transition cannot leave the runtime-only grid visible in Edit Mode.
        if (installGridObject != null && installGridObject.activeSelf)
        {
            installGridObject.SetActive(false);
        }

        if (Application.isPlaying)
        {
            if (installGridObject != null)
            {
                Destroy(installGridObject);
            }

            if (installGridMesh != null)
            {
                Destroy(installGridMesh);
            }

            if (installGridPreviewMesh != null)
            {
                Destroy(installGridPreviewMesh);
            }

            if (installGridMaterial != null)
            {
                Destroy(installGridMaterial);
            }
        }
        else
        {
            if (installGridObject != null)
            {
                DestroyImmediate(installGridObject);
            }

            if (installGridMesh != null)
            {
                DestroyImmediate(installGridMesh);
            }

            if (installGridPreviewMesh != null)
            {
                DestroyImmediate(installGridPreviewMesh);
            }

            if (installGridMaterial != null)
            {
                DestroyImmediate(installGridMaterial);
            }
        }

        installGridObject = null;
        installGridMeshFilter = null;
        installGridMeshRenderer = null;
        installGridMesh = null;
        installGridPreviewObject = null;
        installGridPreviewMeshFilter = null;
        installGridPreviewMeshRenderer = null;
        installGridPreviewMesh = null;
        installGridMaterial = null;
    }

    private bool TryGetBlockFromGroundPlane(Ray ray, out Block block)
    {
        block = null;

        if (!TryGetGroundPlanePoint(ray, out Vector3 worldPoint))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        Vector2Int coordinate = new Vector2Int(
            Mathf.RoundToInt(worldPoint.x),
            Mathf.RoundToInt(worldPoint.z));

        return terrain.TryGetLoadedBlock(coordinate, out block) && block != null;
    }

    private bool TryGetGroundPlanePoint(Ray ray, out Vector3 worldPoint)
    {
        worldPoint = Vector3.zero;

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        Plane groundPlane = new Plane(Vector3.up, new Vector3(0f, terrain.transform.position.y, 0f));
        if (!groundPlane.Raycast(ray, out float enter))
        {
            return false;
        }

        worldPoint = ray.GetPoint(enter);
        return true;
    }

    private void UpdateInstallPreviewPointerInput()
    {
        if (Input.touchCount > 0)
        {
            Touch touch = Input.GetTouch(0);
            switch (touch.phase)
            {
                case TouchPhase.Began:
                    BeginPreviewPointerTracking(touch.position, IsPointerOverBlockingUi(touch.position));
                    break;
                case TouchPhase.Moved:
                case TouchPhase.Stationary:
                    EnsurePreviewPointerTracking(touch.position);
                    ContinuePreviewPointerTracking(touch.position);
                    break;
                case TouchPhase.Ended:
                    EndPreviewPointerTracking(touch.position, false);
                    break;
                case TouchPhase.Canceled:
                    EndPreviewPointerTracking(touch.position, true);
                    break;
            }

            return;
        }

        if (Input.GetMouseButtonDown(0))
        {
            BeginPreviewPointerTracking(Input.mousePosition, IsPointerOverBlockingUi(Input.mousePosition));
        }
        else if (Input.GetMouseButton(0))
        {
            EnsurePreviewPointerTracking(Input.mousePosition);
        }

        if (Input.GetMouseButton(0))
        {
            ContinuePreviewPointerTracking(Input.mousePosition);
        }

        if (Input.GetMouseButtonUp(0))
        {
            EndPreviewPointerTracking(Input.mousePosition, false);
        }
    }

    private void BeginPreviewPointerTracking(Vector2 pointerPosition, bool startedOverUi)
    {
        isPreviewPointerTracking = true;
        previewPointerDragged = false;
        previewPointerStartedOverUi = startedOverUi;
        previewPointerStartPosition = pointerPosition;
        previewPointerOriginPreview = null;

        if (startedOverUi)
        {
            return;
        }

        if (!TryGetPointerBlock(pointerPosition, out Block pointerBlock) || pointerBlock == null)
        {
            return;
        }

        if (!TryGetInstallPreviewAtBlock(pointerBlock, out MapObject originPreview) || originPreview == null)
        {
            return;
        }

        previewPointerOriginPreview = originPreview;
        if (originPreview != activeInstallPreview)
        {
            SelectInstallPreview(originPreview);
        }
    }

    private void EnsurePreviewPointerTracking(Vector2 pointerPosition)
    {
        if (isPreviewPointerTracking)
        {
            return;
        }

        BeginPreviewPointerTracking(pointerPosition, IsPointerOverBlockingUi(pointerPosition));
    }

    private void ContinuePreviewPointerTracking(Vector2 pointerPosition)
    {
        if (!isPreviewPointerTracking || previewPointerStartedOverUi)
        {
            return;
        }

        if (!previewPointerDragged)
        {
            float threshold = Mathf.Max(1f, installRotateTapThreshold);
            previewPointerDragged = Vector2.Distance(previewPointerStartPosition, pointerPosition) >= threshold;
        }

        if (previewPointerDragged && (IsEditingInstallation() || previewPointerOriginPreview != null))
        {
            TryHandleInstallPreviewDrag(pointerPosition);
        }
    }

    private void EndPreviewPointerTracking(Vector2 pointerPosition, bool wasCanceled)
    {
        if (!isPreviewPointerTracking)
        {
            return;
        }

        bool endedOverUi = !wasCanceled && IsPointerOverBlockingUi(pointerPosition);
        if (!wasCanceled && !previewPointerStartedOverUi && !endedOverUi)
        {
            if (IsEditingInstallation())
            {
                if (previewPointerDragged)
                {
                    TryMoveInstallPreview(pointerPosition, true);
                }
                else
                {
                    HandleInstallationEditClick(pointerPosition);
                }

                ResetPreviewPointerTracking();
                return;
            }

            if (previewPointerDragged)
            {
                if (previewPointerOriginPreview != null)
                {
                    TryHandleInstallPreviewDrag(pointerPosition);
                }
            }
            else
            {
                HandleInstallPreviewClick(pointerPosition);
            }
        }

        ResetPreviewPointerTracking();
    }

    private void TryHandleInstallPreviewDrag(Vector2 pointerPosition)
    {
        if (IsEditingInstallation())
        {
            TryMoveInstallPreview(pointerPosition, true);
            return;
        }

        if (previewPointerOriginPreview != null
            && previewPointerOriginPreview != activeInstallPreview)
        {
            SelectInstallPreview(previewPointerOriginPreview);
        }

        TryMoveInstallPreview(pointerPosition, true);
    }

    private void HandleInstallationEditClick(Vector2 pointerPosition)
    {
        if (!TryGetEditableInstallationAtPointer(pointerPosition, out InstallationObject installationObject, out Vector2Int anchorCoordinate)
            || installationObject == null)
        {
            return;
        }

        if (activeInstallationEditSession != null
            && installationObject == activeInstallationEditSession.originalInstallation)
        {
            return;
        }

        bool shouldSelectOnly = ShouldSelectOnlyInMapEdit(installationObject);
        if (!TryCommitActiveInstallationEditPreview())
        {
            CancelInstallationEdit();
        }

        if (shouldSelectOnly)
        {
            SelectEditableInstallation(installationObject, anchorCoordinate);
            return;
        }

        if (!BeginInstallationEdit(installationObject, anchorCoordinate))
        {
            SelectEditableInstallation(installationObject, anchorCoordinate);
        }
    }

    private bool TryCommitActiveInstallationEditPreview()
    {
        InstallationEditSession editSession = activeInstallationEditSession;
        if (editSession == null)
        {
            return false;
        }

        CleanupInstallPreviewReferences();
        if (activeInstallPreview == null || !TryGetPreviewAnchorCoordinate(activeInstallPreview, out Vector2Int anchorCoordinate))
        {
            return false;
        }

        if (editSession.editsUndergroundPipeEndpoint
            && activeInstallPreview is UndergroundPipe undergroundPipePreview
            && !TryResolveCommittedUndergroundPipeEditCoordinate(
                editSession,
                undergroundPipePreview,
                out anchorCoordinate))
        {
            InvalidateInstallGrid();
            return false;
        }

        Quaternion previewRotation = activeInstallPreview.transform.rotation;
        Vector3 previewPosition = activeInstallPreview.transform.position;
        int quarterTurns = GetPreviewQuarterTurns(activeInstallPreview);
        int conveyorVariantKind = GetInstallationVariantKind(activeInstallPreview);
        if (!CanRestoreEditedInstallationAt(
                editSession,
                anchorCoordinate,
                quarterTurns,
                conveyorVariantKind,
                activeInstallPreview))
        {
            InvalidateInstallGrid();
            return false;
        }

        activeInstallationEditSession = null;
        RestoreEditedInstallation(
            editSession,
            anchorCoordinate,
            quarterTurns,
            conveyorVariantKind,
            previewRotation,
            previewPosition);
        ClearInstallPreview();
        return true;
    }

    private void ResetPreviewPointerTracking()
    {
        isPreviewPointerTracking = false;
        previewPointerDragged = false;
        previewPointerStartedOverUi = false;
        previewPointerStartPosition = Vector2.zero;
        previewPointerOriginPreview = null;
    }

    private void RotateInstallPreviewClockwise()
    {
        if (activeInstallPreview == null)
        {
            return;
        }

        if (activeInstallPreview is UndergroundPipe)
        {
            return;
        }

        if (GetInstallPreviewUserRotationFilter(activeInstallPreview) == InstallationRotationFilter.Fixed)
        {
            return;
        }

        MapObject rotationSource = ResolveInstallPreviewPlacementSource(activeInstallPreview)
                                   ?? activeInstallPreview;
        if (IsOilDrillingMachineSource(rotationSource))
        {
            return;
        }

        InvalidateInstallPreviewMoveCache();
        if (SnapFreightCarBoxPreviewToTarget(activeInstallPreview))
        {
            return;
        }

        if (TryRotateActiveTrainStationPreviewToNextRail())
        {
            return;
        }

        bool rotatesGridAnchoredPipe = activeInstallPreview is Pipe
                                      && !(activeInstallPreview is UndergroundPipe);
        // Pipe variants can use different prefab pivots/visual offsets. Keeping the
        // old transform and deriving the anchor back from it can move the replacement
        // pipe into a neighbouring cell while surrounding tee previews still target
        // the original cell. Normal pipes always remain snapped to their grid anchor.
        bool preservePreviewTransformOnRotation = !rotatesGridAnchoredPipe
                                                  && ShouldPreserveInstallPreviewTransformOnRotation(
                                                      activeInstallPreview);
        Vector3 preservedPreviewPosition = activeInstallPreview.transform.position;
        int previousQuarterTurns = GetPreviewQuarterTurns(activeInstallPreview);
        Block anchorBlock = null;
        bool hasAnchorBlock = TryGetPreviewAnchorCoordinate(activeInstallPreview, out Vector2Int anchorCoordinate)
                            && ResolveInstallPreviewTerrain() != null
                            && ResolveInstallPreviewTerrain().TryGetLoadedBlock(anchorCoordinate, out anchorBlock);
        Vector2Int previousAnchorCoordinate = anchorCoordinate;
        bool shouldReanchorRotatedMultiCellPreview = false;

        if (IsActiveBelt2FPreview())
        {
            if (!TryRotateBelt2FPreviewAroundBridgeCenter(
                    hasAnchorBlock,
                    anchorCoordinate,
                    out anchorBlock,
                    out anchorCoordinate,
                    out int resolvedQuarterTurns))
            {
                return;
            }

            hasAnchorBlock = anchorBlock != null;
            installPreviewQuarterTurns = resolvedQuarterTurns;
        }
        else if (activeInstallDefinition != null && activeInstallDefinition.mapObject is ConveyorBelt conveyorBelt)
        {
            int logicalQuarterTurns = GetPreviewQuarterTurns(activeInstallPreview);

            bool useCornerVariant = installPreviewConveyorVariantMode == ConveyorPreviewVariantMode.Corner
                || (activeInstallPreview is ConveyorBelt previewConveyor && previewConveyor.IsCornerVariant);
            if (hasAnchorBlock)
            {
                if (!TryFindNextConveyorPreviewRotation(
                        conveyorBelt,
                        anchorCoordinate,
                        activeInstallPreview,
                        logicalQuarterTurns,
                        useCornerVariant,
                        out logicalQuarterTurns,
                        out ConveyorPreviewVariantMode resolvedVariantMode,
                        out MapObject resolvedVariantPrefab,
                        out int resolvedSequenceIndex))
                {
                    return;
                }

                installPreviewQuarterTurns = logicalQuarterTurns;
                installPreviewConveyorVariantMode = resolvedVariantMode;
                installPreviewConveyorRotationSequenceIndexesByPreview[activeInstallPreview] = resolvedSequenceIndex;
                if (resolvedVariantPrefab != null)
                {
                    installPreviewSourcePrefabsByPreview[activeInstallPreview] = resolvedVariantPrefab;
                }

                ApplyConveyorPreviewVariant(
                    activeInstallPreview,
                    resolvedVariantPrefab,
                    anchorCoordinate,
                    logicalQuarterTurns);
            }
            else
            {
                if (!TryFindNextConveyorPreviewRotation(
                        conveyorBelt,
                        null,
                        activeInstallPreview,
                        logicalQuarterTurns,
                        useCornerVariant,
                        out logicalQuarterTurns,
                        out ConveyorPreviewVariantMode resolvedVariantMode,
                        out MapObject resolvedVariantPrefab,
                        out int resolvedSequenceIndex))
                {
                    return;
                }

                installPreviewQuarterTurns = logicalQuarterTurns;
                installPreviewConveyorVariantMode = resolvedVariantMode;
                installPreviewConveyorRotationSequenceIndexesByPreview[activeInstallPreview] = resolvedSequenceIndex;
                if (resolvedVariantPrefab != null)
                {
                    installPreviewSourcePrefabsByPreview[activeInstallPreview] = resolvedVariantPrefab;
                }
            }
        }
        else if (TryRotateWaterPumpPreviewAtShore(
                     hasAnchorBlock,
                     anchorBlock,
                     anchorCoordinate,
                     out int waterPumpQuarterTurns))
        {
            installPreviewQuarterTurns = waterPumpQuarterTurns;
        }
        else if (TryRotateSteamGeneratorPreviewInPlaceOnStraightPipe(
                     hasAnchorBlock,
                     anchorCoordinate,
                     out _,
                     out anchorBlock,
                     out anchorCoordinate,
                     out int steamGeneratorQuarterTurns))
        {
            hasAnchorBlock = anchorBlock != null;
            installPreviewQuarterTurns = steamGeneratorQuarterTurns;
        }
        else
        {
            int nextQuarterTurns = GetNextInstallPreviewQuarterTurns(
                activeInstallPreview,
                installPreviewQuarterTurns);
            bool shouldRememberFenceDoorStandaloneQuarterTurns =
                ShouldRememberFenceDoorStandaloneQuarterTurns(
                    activeInstallPreview,
                    hasAnchorBlock,
                    anchorCoordinate);
            if (shouldRememberFenceDoorStandaloneQuarterTurns)
            {
                installPreviewFenceDoorStandaloneQuarterTurnsByPreview[activeInstallPreview] =
                    NormalizePlacementQuarterTurnsForObject(activeInstallPreview, nextQuarterTurns);
            }

            installPreviewQuarterTurns = NormalizeInstallPreviewQuarterTurns(
                activeInstallPreview,
                nextQuarterTurns);
            shouldReanchorRotatedMultiCellPreview = hasAnchorBlock
                                                   && !preservePreviewTransformOnRotation
                                                   && !IsTrainSource(ResolveInstallPreviewPlacementSource(activeInstallPreview));
        }

        if (shouldReanchorRotatedMultiCellPreview
            && hasAnchorBlock
            && ShouldKeepInstallPreviewAnchorOnRotation(activeInstallPreview, anchorCoordinate))
        {
            shouldReanchorRotatedMultiCellPreview = false;
        }

        if (shouldReanchorRotatedMultiCellPreview
            && hasAnchorBlock
            && TryResolveRotatedMultiCellInstallPreviewAnchor(
                activeInstallPreview,
                previousAnchorCoordinate,
                previousQuarterTurns,
                installPreviewQuarterTurns,
                out Block reanchoredBlock,
                out Vector2Int reanchoredCoordinate))
        {
            anchorBlock = reanchoredBlock;
            anchorCoordinate = reanchoredCoordinate;
        }

        if (hasAnchorBlock
            && BoilerPlacementRotationCandidateIsBlockedForActivePreview(
                anchorBlock,
                anchorCoordinate,
                installPreviewQuarterTurns)
            && !TryFindBoilerRotationSkippingPlacementConflicts(
                activeInstallPreview,
                previousAnchorCoordinate,
                previousQuarterTurns,
                installPreviewQuarterTurns,
                out anchorBlock,
                out anchorCoordinate,
                out installPreviewQuarterTurns))
        {
            installPreviewQuarterTurns = previousQuarterTurns;
            return;
        }

        installPreviewQuarterTurnsByPreview[activeInstallPreview] = installPreviewQuarterTurns;
        if (hasAnchorBlock)
        {
            installPreviewAnchorCoordinates[activeInstallPreview] = anchorCoordinate;
        }

        if (ShouldRememberFenceDoorStandaloneQuarterTurns(activeInstallPreview, hasAnchorBlock, anchorCoordinate))
        {
            installPreviewFenceDoorStandaloneQuarterTurnsByPreview[activeInstallPreview] =
                NormalizePlacementQuarterTurnsForObject(activeInstallPreview, installPreviewQuarterTurns);
        }

        if (hasAnchorBlock
            && activeInstallPreview is Pipe explicitlyRotatedPipe
            && !(explicitlyRotatedPipe is UndergroundPipe))
        {
            if (TryResolveExplicitPipeRotationConnectionPreference(
                    explicitlyRotatedPipe,
                    anchorCoordinate,
                    out int preferredConnectionMask))
            {
                installPreviewPipeConnectionMasksByPreview[activeInstallPreview] =
                    preferredConnectionMask;
            }
        }

        if (!(activeInstallDefinition != null && activeInstallDefinition.mapObject is ConveyorBelt))
        {
            RefreshActiveConveyorPreviewVariant();
        }
        RefreshActiveFencePreviewVariant(true);
        MaterializeActivePipeManualConnectionSelection();
        activeInstallPreview.transform.rotation = GetInstallPreviewRotation();
        if (activeInstallPreview is InstallationObject rotatedInstallationPreview)
        {
            rotatedInstallationPreview.RefreshInstalledDirectionFromCurrentTransform();
        }
        ConfigurePreviewOnlyRuntimeRendering(activeInstallPreview);

        if (preservePreviewTransformOnRotation)
        {
            MapObject placementSource = ResolveInstallPreviewPlacementSource(activeInstallPreview);
            activeInstallPreview.transform.position = ResolveInstallPreviewPositionAfterRotation(
                preservedPreviewPosition,
                placementSource,
                previousQuarterTurns,
                installPreviewQuarterTurns);
            if (TryResolveInstallPreviewAnchorCoordinateFromTransform(
                    activeInstallPreview,
                    placementSource,
                    installPreviewQuarterTurns,
                    out Vector2Int transformAnchorCoordinate))
            {
                anchorCoordinate = transformAnchorCoordinate;
                hasAnchorBlock = ResolveInstallPreviewTerrain() != null
                                 && ResolveInstallPreviewTerrain().TryGetLoadedBlock(anchorCoordinate, out anchorBlock)
                                 && anchorBlock != null;
                installPreviewAnchorCoordinates[activeInstallPreview] = anchorCoordinate;
            }
        }
        else if (hasAnchorBlock)
        {
            MapObject placementSource = ResolveInstallPreviewPlacementSource(activeInstallPreview);
            if (!IsTrainSource(placementSource))
            {
                activeInstallPreview.transform.position = ResolvePlacementWorldPosition(
                    anchorBlock,
                    placementSource,
                    installPreviewQuarterTurns,
                    activeInstallPreview.transform.position);
            }
        }

        RefreshHandcartInstallPreviewConnectionPoses();
        RefreshPreviewRangeVisualsIfNeeded(activeInstallPreview);
        RefreshUtilityPolePreviewWires();
        RefreshInstallPreviewAreaMarkers(activeInstallPreview);
        RememberBlueprintRotationForPreview(activeInstallDefinition, activeInstallPreview, installPreviewQuarterTurns);
        RefreshFencePreviewVariantsAroundActivePreview(
            hasAnchorBlock ? anchorCoordinate : (Vector2Int?)null,
            true);
        if (activeInstallDefinition != null
            && activeInstallDefinition.mapObject is Pipe)
        {
            // Rotation must present the same fully resolved topology that commit
            // captures. A local refresh can leave remote previews in their old
            // shape and make the captured snapshot incomplete.
            RefreshAllPipeBlueprintTopology();
            RefreshFluidTankBlueprintPipeVisuals();
        }
        else
        {
            RefreshPipePreviewVariantsAroundActivePreview(
                hasAnchorBlock ? anchorCoordinate : (Vector2Int?)null);
        }
        RefreshTrainInstallPreviewTints();
        NormalizeInstallPreviewNativeRendering(activeInstallPreview);
        ResetInstallPreviewVisualSyncState();
        SetInstallPreviewSelectionVisual(activeInstallPreview, true);
        InvalidateInstallGridPreview();
    }

    private bool TryResolveExplicitPipeRotationConnectionPreference(
        Pipe rotatedPipe,
        Vector2Int anchorCoordinate,
        out int connectionMask)
    {
        connectionMask = 0;
        if (rotatedPipe == null)
        {
            return false;
        }

        // Automatic blueprint topology may have drawn temporary variants over the
        // installed neighbours. Rotation must start from the authoritative installed
        // ports, otherwise those temporary bends feed back into the next candidate.
        RemoveInstalledPipeVariantPreviews(null);
        installedPipeVariantResolutionOverrides.Clear();

        int candidateCount = CollectExplicitPipeRotationSetCandidates(
            anchorCoordinate,
            activeInstallPreview,
            pipeRotationSetEndpointsScratch);
        if (candidateCount <= 0)
        {
            return false;
        }

        ResolveExplicitPipeRotationSetIds(
            anchorCoordinate,
            activeInstallPreview,
            candidateCount,
            pipeRotationSetEndpointsScratch,
            pipeRotationSetIdsScratch);

        int currentMask;
        if (!installPreviewPipeConnectionMasksByPreview.TryGetValue(
                activeInstallPreview,
                out currentMask)
            || !HasValidManualPipeConnectionMask(currentMask))
        {
            currentMask = rotatedPipe.GetConnectionMask(rotatedPipe.transform.rotation);
        }

        for (int setIndex = 0; setIndex < candidateCount; setIndex++)
        {
            pipeRotationCurrentSetIdsScratch[setIndex] = false;
        }

        int currentDirectionIndex = -1;
        bool hasCurrentSet = false;
        if (installPreviewPipeSelectedSetDirectionsByPreview.TryGetValue(
                activeInstallPreview,
                out Vector2Int selectedSetDirection))
        {
            int selectedSetCandidateIndex = FindExplicitPipeRotationCandidateIndex(
                selectedSetDirection,
                candidateCount,
                pipeRotationSetEndpointsScratch);
            if (selectedSetCandidateIndex >= 0)
            {
                hasCurrentSet = true;
                pipeRotationCurrentSetIdsScratch[
                    pipeRotationSetIdsScratch[selectedSetCandidateIndex]] = true;
                currentDirectionIndex = GetPipeCardinalDirectionIndex(
                    selectedSetDirection);
            }
            else
            {
                installPreviewPipeSelectedSetDirectionsByPreview.Remove(
                    activeInstallPreview);
            }
        }

        if (!hasCurrentSet)
        {
            ResolveInitialExplicitPipeRotationCurrentSets(
                rotatedPipe,
                anchorCoordinate,
                currentMask,
                activeInstallPreview,
                candidateCount,
                pipeRotationSetEndpointsScratch,
                pipeRotationSetIdsScratch,
                pipeRotationCurrentSetIdsScratch,
                out hasCurrentSet,
                out currentDirectionIndex);
        }

        if (currentDirectionIndex < 0)
        {
            for (int directionIndex = 0;
                 directionIndex < PipeCardinalDirections.Length;
                 directionIndex++)
            {
                if (PipeConnectionMaskContainsDirection(
                        currentMask,
                        PipeCardinalDirections[directionIndex]))
                {
                    currentDirectionIndex = directionIndex;
                }
            }
        }

        int selectedCandidateIndex = FindNextExplicitPipeRotationSetCandidate(
            candidateCount,
            currentDirectionIndex,
            hasCurrentSet,
            pipeRotationSetEndpointsScratch,
            pipeRotationSetIdsScratch,
            pipeRotationCurrentSetIdsScratch);
        if (selectedCandidateIndex < 0)
        {
            // A stale two-port manual mask can remain after separately resolved
            // branches become one fluid-compatible set. Rebuild that sole set so
            // the blueprint immediately materializes the required tee/cross.
            if (candidateCount < 2)
            {
                return false;
            }

            int soleSetId = pipeRotationSetIdsScratch[0];
            for (int candidateIndex = 1;
                 candidateIndex < candidateCount;
                 candidateIndex++)
            {
                if (pipeRotationSetIdsScratch[candidateIndex] != soleSetId)
                {
                    return false;
                }
            }

            selectedCandidateIndex = 0;
        }

        bool resolved = TryBuildExplicitPipeRotationConnectionMask(
            rotatedPipe,
            selectedCandidateIndex,
            candidateCount,
            pipeRotationSetEndpointsScratch,
            pipeRotationSetIdsScratch,
            out connectionMask);
        if (resolved)
        {
            installPreviewPipeSelectedSetDirectionsByPreview[activeInstallPreview] =
                pipeRotationSetEndpointsScratch[selectedCandidateIndex].direction;
        }
        return resolved;
    }

    private void ResolveInitialExplicitPipeRotationCurrentSets(
        Pipe rotatedPipe,
        Vector2Int anchorCoordinate,
        int currentMask,
        MapObject previewToIgnore,
        int candidateCount,
        PipeRotationSetEndpoint[] endpoints,
        int[] setIds,
        bool[] currentSetIds,
        out bool hasCurrentSet,
        out int currentDirectionIndex)
    {
        hasCurrentSet = false;
        currentDirectionIndex = -1;
        int currentFluidItemId = ResolveInitialExplicitPipeRotationFluidItemId(
            rotatedPipe,
            anchorCoordinate,
            previewToIgnore);

        for (int candidateIndex = 0;
             candidateIndex < candidateCount;
             candidateIndex++)
        {
            PipeRotationSetEndpoint endpoint = endpoints[candidateIndex];
            if (!PipeConnectionMaskContainsDirection(currentMask, endpoint.direction)
                || !endpoint.hasCurrentConnection
                || currentFluidItemId < 0
                || !endpoint.hasFluidIdentity
                || endpoint.fluidItemId != currentFluidItemId)
            {
                continue;
            }

            hasCurrentSet = true;
            currentSetIds[setIds[candidateIndex]] = true;
            currentDirectionIndex = GetPipeCardinalDirectionIndex(endpoint.direction);
        }

        if (hasCurrentSet)
        {
            return;
        }

        // Empty pipes have no fluid identity. Only a mutually connected endpoint is
        // current; a nearby straight pipe that could become a tee is merely a
        // selectable set and must not be skipped before it is actually selected.
        for (int candidateIndex = 0;
             candidateIndex < candidateCount;
             candidateIndex++)
        {
            PipeRotationSetEndpoint endpoint = endpoints[candidateIndex];
            if (!PipeConnectionMaskContainsDirection(currentMask, endpoint.direction)
                || !endpoint.hasCurrentConnection)
            {
                continue;
            }

            hasCurrentSet = true;
            currentSetIds[setIds[candidateIndex]] = true;
            currentDirectionIndex = GetPipeCardinalDirectionIndex(endpoint.direction);
        }
    }

    private int ResolveInitialExplicitPipeRotationFluidItemId(
        Pipe rotatedPipe,
        Vector2Int anchorCoordinate,
        MapObject previewToIgnore)
    {
        TryGetPipeVariantAnchorFluidItemId(
            anchorCoordinate,
            previewToIgnore,
            out int anchorFluidItemId);
        int preferredFluidItemId = ResolvePreferredPipeVariantFluidItemId(
            anchorCoordinate,
            anchorFluidItemId,
            previewToIgnore);
        if (preferredFluidItemId >= 0)
        {
            return preferredFluidItemId;
        }

        return rotatedPipe != null
               && rotatedPipe.TryGetObjectInfoFluidItemId(out int displayedFluidItemId)
            ? displayedFluidItemId
            : -1;
    }

    private void ResolveExplicitPipeRotationSetIds(
        Vector2Int anchorCoordinate,
        MapObject previewToIgnore,
        int candidateCount,
        PipeRotationSetEndpoint[] endpoints,
        int[] setIds)
    {
        for (int candidateIndex = 0; candidateIndex < candidateCount; candidateIndex++)
        {
            setIds[candidateIndex] = candidateIndex;
            for (int previousIndex = 0;
                 previousIndex < candidateIndex;
                 previousIndex++)
            {
                if (!ExplicitPipeRotationEndpointsShareSet(
                        anchorCoordinate,
                        previewToIgnore,
                        endpoints[candidateIndex],
                        endpoints[previousIndex]))
                {
                    continue;
                }

                int previousSetId = setIds[previousIndex];
                int mergedSetId = setIds[candidateIndex];
                for (int mergeIndex = 0;
                     mergeIndex <= candidateIndex;
                     mergeIndex++)
                {
                    if (setIds[mergeIndex] == mergedSetId)
                    {
                        setIds[mergeIndex] = previousSetId;
                    }
                }
                break;
            }
        }
    }

    private bool ExplicitPipeRotationEndpointsShareSet(
        Vector2Int activePipeCoordinate,
        MapObject previewToIgnore,
        PipeRotationSetEndpoint first,
        PipeRotationSetEndpoint second)
    {
        if (ExplicitPipeRotationFluidIdentitiesShareSet(
                first.hasFluidIdentity,
                first.fluidItemId,
                second.hasFluidIdentity,
                second.fluidItemId))
        {
            return true;
        }

        if (first.hasFluidIdentity && second.hasFluidIdentity)
        {
            return false;
        }

        if (first.hasConnectorRoot
            && second.hasConnectorRoot
            && first.connectorOwner == second.connectorOwner
            && first.connectorAnchorCoordinate == second.connectorAnchorCoordinate)
        {
            return true;
        }

        return first.hasPipeRoot
               && second.hasPipeRoot
               && ExplicitPipeRotationPipeRootsAreConnected(
                   first.pipeRootCoordinate,
                   second.pipeRootCoordinate,
                   activePipeCoordinate,
                   previewToIgnore);
    }

    private static bool ExplicitPipeRotationFluidIdentitiesShareSet(
        bool firstHasFluidIdentity,
        int firstFluidItemId,
        bool secondHasFluidIdentity,
        int secondFluidItemId)
    {
        return firstHasFluidIdentity == secondHasFluidIdentity
               && (!firstHasFluidIdentity
                   || firstFluidItemId == secondFluidItemId);
    }

    private static bool CanShareExplicitPipeRotationFluidSelection(
        bool selectedHasFluidIdentity,
        int selectedFluidItemId,
        bool candidateHasFluidIdentity,
        int candidateFluidItemId)
    {
        return selectedHasFluidIdentity
               && (!candidateHasFluidIdentity
                   || selectedFluidItemId == candidateFluidItemId);
    }

    private bool ExplicitPipeRotationPipeRootsAreConnected(
        Vector2Int firstRootCoordinate,
        Vector2Int secondRootCoordinate,
        Vector2Int activePipeCoordinate,
        MapObject previewToIgnore)
    {
        if (firstRootCoordinate == secondRootCoordinate)
        {
            return true;
        }

        pipeFluidCompatibilityQueue.Clear();
        pipeFluidCompatibilityVisited.Clear();
        pipeFluidCompatibilityQueue.Enqueue(firstRootCoordinate);
        pipeFluidCompatibilityVisited.Add(firstRootCoordinate);

        int searchedNodeCount = 0;
        while (pipeFluidCompatibilityQueue.Count > 0
               && searchedNodeCount < MaxPipeFluidCompatibilitySearchNodes)
        {
            Vector2Int pipeCoordinate = pipeFluidCompatibilityQueue.Dequeue();
            searchedNodeCount++;
            if (!TryGetAuthoritativePipePlacementForExplicitRotation(
                    pipeCoordinate,
                    previewToIgnore,
                    out Pipe pipe,
                    out Quaternion pipeRotation,
                    out bool isPreview)
                || pipe == null)
            {
                continue;
            }

            for (int directionIndex = 0;
                 directionIndex < PipeCardinalDirections.Length;
                 directionIndex++)
            {
                Vector2Int direction = PipeCardinalDirections[directionIndex];
                if (!AuthoritativePipeHasConnectionTowardsAt(
                        pipeCoordinate,
                        pipe,
                        pipeRotation,
                        isPreview,
                        direction))
                {
                    continue;
                }

                Vector2Int neighborCoordinate = pipeCoordinate + direction;
                if (neighborCoordinate == activePipeCoordinate
                    || !TryGetAuthoritativePipePlacementForExplicitRotation(
                        neighborCoordinate,
                        previewToIgnore,
                        out Pipe neighborPipe,
                        out Quaternion neighborRotation,
                        out bool neighborIsPreview)
                    || neighborPipe == null
                    || !AuthoritativePipeHasConnectionTowardsAt(
                        neighborCoordinate,
                        neighborPipe,
                        neighborRotation,
                        neighborIsPreview,
                        -direction))
                {
                    continue;
                }

                if (neighborCoordinate == secondRootCoordinate)
                {
                    pipeFluidCompatibilityQueue.Clear();
                    pipeFluidCompatibilityVisited.Clear();
                    return true;
                }

                if (pipeFluidCompatibilityVisited.Add(neighborCoordinate))
                {
                    pipeFluidCompatibilityQueue.Enqueue(neighborCoordinate);
                }
            }

            if (pipe.TryGetRemoteConnectionCoordinate(
                    pipeCoordinate,
                    out Vector2Int remoteCoordinate)
                && remoteCoordinate != activePipeCoordinate)
            {
                if (remoteCoordinate == secondRootCoordinate)
                {
                    pipeFluidCompatibilityQueue.Clear();
                    pipeFluidCompatibilityVisited.Clear();
                    return true;
                }

                if (pipeFluidCompatibilityVisited.Add(remoteCoordinate))
                {
                    pipeFluidCompatibilityQueue.Enqueue(remoteCoordinate);
                }
            }
        }

        pipeFluidCompatibilityQueue.Clear();
        pipeFluidCompatibilityVisited.Clear();
        return false;
    }

    private bool AuthoritativePipeHasConnectionTowardsAt(
        Vector2Int coordinate,
        Pipe pipe,
        Quaternion pipeRotation,
        bool isPreview,
        Vector2Int direction)
    {
        return isPreview
            ? HasEffectivePipeConnectionTowardsAt(
                coordinate,
                pipe,
                pipeRotation,
                direction)
            : pipe != null
              && pipe.HasConnectionTowardsAt(
                  coordinate,
                  pipeRotation,
                  direction);
    }

    private static int FindNextExplicitPipeRotationSetCandidate(
        int candidateCount,
        int currentDirectionIndex,
        bool hasCurrentSet,
        PipeRotationSetEndpoint[] endpoints,
        int[] setIds,
        bool[] currentSetIds)
    {
        int firstDirectionIndex = currentDirectionIndex >= 0
            ? currentDirectionIndex + 1
            : 0;
        for (int directionOffset = 0;
             directionOffset < PipeCardinalDirections.Length;
             directionOffset++)
        {
            int directionIndex =
                (firstDirectionIndex + directionOffset) % PipeCardinalDirections.Length;
            Vector2Int direction = PipeCardinalDirections[directionIndex];
            for (int candidateIndex = 0;
                 candidateIndex < candidateCount;
                 candidateIndex++)
            {
                if (endpoints[candidateIndex].direction != direction
                    || hasCurrentSet && currentSetIds[setIds[candidateIndex]])
                {
                    continue;
                }

                return candidateIndex;
            }
        }

        return -1;
    }

    private bool TryBuildExplicitPipeRotationConnectionMask(
        Pipe rotatedPipe,
        int selectedCandidateIndex,
        int candidateCount,
        PipeRotationSetEndpoint[] endpoints,
        int[] setIds,
        out int connectionMask)
    {
        connectionMask = 0;
        if (rotatedPipe == null
            || selectedCandidateIndex < 0
            || selectedCandidateIndex >= candidateCount)
        {
            return false;
        }

        Vector2Int selectedDirection = endpoints[selectedCandidateIndex].direction;
        int selectedDirectionIndex = GetPipeCardinalDirectionIndex(selectedDirection);
        if (selectedDirectionIndex < 0)
        {
            return false;
        }

        int selectedSetId = setIds[selectedCandidateIndex];
        int selectedSetConnectionMask = 0;
        int selectedSetEndpointCount = 0;
        bool selectedSetHasFluidIdentity = false;
        int selectedSetFluidItemId = -1;
        for (int candidateIndex = 0; candidateIndex < candidateCount; candidateIndex++)
        {
            if (setIds[candidateIndex] != selectedSetId)
            {
                continue;
            }

            selectedSetConnectionMask |= GetPipeConnectionDirectionBit(
                endpoints[candidateIndex].direction);
            selectedSetEndpointCount++;
            if (endpoints[candidateIndex].hasFluidIdentity)
            {
                selectedSetHasFluidIdentity = true;
                selectedSetFluidItemId = endpoints[candidateIndex].fluidItemId;
            }
        }

        // Empty branches can adopt the selected fluid and must not remain visually
        // detached. They join this selection without allowing one empty branch to
        // merge two different known-fluid sets during set-ID construction.
        if (selectedSetHasFluidIdentity)
        {
            for (int candidateIndex = 0; candidateIndex < candidateCount; candidateIndex++)
            {
                if (setIds[candidateIndex] == selectedSetId
                    || !CanShareExplicitPipeRotationFluidSelection(
                        true,
                        selectedSetFluidItemId,
                        endpoints[candidateIndex].hasFluidIdentity,
                        endpoints[candidateIndex].fluidItemId))
                {
                    continue;
                }

                selectedSetConnectionMask |= GetPipeConnectionDirectionBit(
                    endpoints[candidateIndex].direction);
                selectedSetEndpointCount++;
            }
        }
        else
        {
            int compatibleKnownFluidItemId = -1;
            bool hasConflictingKnownFluids = false;
            for (int candidateIndex = 0; candidateIndex < candidateCount; candidateIndex++)
            {
                if (!endpoints[candidateIndex].hasFluidIdentity)
                {
                    continue;
                }

                int candidateFluidItemId = endpoints[candidateIndex].fluidItemId;
                if (compatibleKnownFluidItemId < 0)
                {
                    compatibleKnownFluidItemId = candidateFluidItemId;
                }
                else if (compatibleKnownFluidItemId != candidateFluidItemId)
                {
                    hasConflictingKnownFluids = true;
                    break;
                }
            }

            if (!hasConflictingKnownFluids)
            {
                selectedSetConnectionMask = 0;
                selectedSetEndpointCount = 0;
                for (int candidateIndex = 0; candidateIndex < candidateCount; candidateIndex++)
                {
                    selectedSetConnectionMask |= GetPipeConnectionDirectionBit(
                        endpoints[candidateIndex].direction);
                    selectedSetEndpointCount++;
                }
            }
        }

        // One selected pipe set can surround the active cell from multiple sides.
        // All of those endpoints belong to the same fluid network and must be kept:
        // two endpoints form a straight/corner, three form a tee, and four a cross.
        if (selectedSetEndpointCount >= 2)
        {
            if (!CanResolveExplicitPipeRotationConnectionMask(
                    rotatedPipe,
                    selectedSetConnectionMask))
            {
                return false;
            }

            connectionMask = selectedSetConnectionMask;
            return true;
        }

        // A set with only one endpoint still needs a second open side so a physical
        // pipe can be represented. Prefer a straight continuation and never borrow
        // the second side from a different pipe set.
        for (int offsetIndex = 0;
             offsetIndex < ExplicitPipeRotationSecondDirectionOffsets.Length;
             offsetIndex++)
        {
            int secondDirectionIndex =
                (selectedDirectionIndex
                 + ExplicitPipeRotationSecondDirectionOffsets[offsetIndex]) %
                PipeCardinalDirections.Length;
            Vector2Int secondDirection = PipeCardinalDirections[secondDirectionIndex];
            if (FindExplicitPipeRotationCandidateIndex(
                    secondDirection,
                    candidateCount,
                    endpoints) >= 0)
            {
                continue;
            }

            int candidateMask = GetPipeConnectionDirectionBit(selectedDirection)
                                | GetPipeConnectionDirectionBit(secondDirection);
            if (!CanResolveExplicitPipeRotationConnectionMask(
                    rotatedPipe,
                    candidateMask))
            {
                continue;
            }

            connectionMask = candidateMask;
            return true;
        }

        return false;
    }

    private static int FindExplicitPipeRotationCandidateIndex(
        Vector2Int direction,
        int candidateCount,
        PipeRotationSetEndpoint[] endpoints)
    {
        for (int candidateIndex = 0;
             candidateIndex < candidateCount;
             candidateIndex++)
        {
            if (endpoints[candidateIndex].direction == direction)
            {
                return candidateIndex;
            }
        }

        return -1;
    }

    private bool CanResolveExplicitPipeRotationConnectionMask(
        Pipe rotatedPipe,
        int connectionMask)
    {
        if (!HasValidManualPipeConnectionMask(connectionMask))
        {
            return false;
        }

        Pipe pipePrototype = activeInstallDefinition != null
                             && activeInstallDefinition.mapObject is Pipe definitionPipe
            ? definitionPipe
            : rotatedPipe != null && rotatedPipe.StraightVariantPrefab != null
                ? rotatedPipe.StraightVariantPrefab
                : rotatedPipe;
        return pipePrototype != null
               && TryResolvePipePlacementFromConnectionMask(
                   pipePrototype,
                   null,
                   connectionMask,
                   GetPreviewQuarterTurns(activeInstallPreview),
                   out _,
                   out _);
    }

    private static int GetPipeCardinalDirectionIndex(Vector2Int direction)
    {
        for (int directionIndex = 0;
             directionIndex < PipeCardinalDirections.Length;
             directionIndex++)
        {
            if (PipeCardinalDirections[directionIndex] == direction)
            {
                return directionIndex;
            }
        }

        return -1;
    }

    private int CollectExplicitPipeRotationSetCandidates(
        Vector2Int anchorCoordinate,
        MapObject previewToIgnore,
        PipeRotationSetEndpoint[] endpoints)
    {
        if (endpoints == null)
        {
            return 0;
        }

        int candidateCount = 0;
        for (int directionIndex = 0;
             directionIndex < PipeCardinalDirections.Length;
             directionIndex++)
        {
            Vector2Int direction = PipeCardinalDirections[directionIndex];
            if (!TryResolveExplicitPipeRotationSetEndpoint(
                    anchorCoordinate,
                    direction,
                    previewToIgnore,
                    out PipeRotationSetEndpoint endpoint))
            {
                continue;
            }

            endpoints[candidateCount] = endpoint;
            candidateCount++;
        }

        return candidateCount;
    }

    private bool TryResolveExplicitPipeRotationSetEndpoint(
        Vector2Int anchorCoordinate,
        Vector2Int direction,
        MapObject previewToIgnore,
        out PipeRotationSetEndpoint endpoint)
    {
        endpoint = new PipeRotationSetEndpoint
        {
            direction = direction
        };
        Vector2Int neighborCoordinate = anchorCoordinate + direction;
        if (TryGetAuthoritativePipePlacementForExplicitRotation(
                neighborCoordinate,
                previewToIgnore,
                out Pipe neighborPipe,
                out Quaternion neighborRotation,
                out bool neighborIsPreview)
            && neighborPipe != null)
        {
            bool neighborCurrentlyConnects = AuthoritativePipeHasConnectionTowardsAt(
                neighborCoordinate,
                neighborPipe,
                neighborRotation,
                neighborIsPreview,
                -direction);
            if (neighborCurrentlyConnects
                || TryResolvePipeVariantForForcedConnection(
                    neighborCoordinate,
                    neighborPipe,
                    neighborRotation,
                    -direction,
                    out _,
                    out _,
                    previewToIgnore))
            {
                endpoint.hasPipeRoot = true;
                endpoint.pipeRootCoordinate = neighborCoordinate;
                endpoint.hasCurrentConnection = neighborCurrentlyConnects;
            }
        }

        if (TryResolveExplicitPipeRotationFixedConnectorRoot(
                anchorCoordinate,
                direction,
                previewToIgnore,
                out MapObject connectorOwner,
                out Vector2Int connectorAnchorCoordinate,
                out Vector2Int connectorCoordinate))
        {
            endpoint.hasConnectorRoot = true;
            endpoint.connectorOwner = connectorOwner;
            endpoint.connectorAnchorCoordinate = connectorAnchorCoordinate;
            endpoint.connectorCoordinate = connectorCoordinate;
            endpoint.hasCurrentConnection = true;
        }

        if (!endpoint.hasConnectorRoot
            && TryGetPumpConnectionDirectionForExplicitPipeRotation(
                anchorCoordinate,
                out Vector2Int pumpConnectionDirection)
            && pumpConnectionDirection == direction)
        {
            endpoint.hasConnectorRoot = true;
            endpoint.connectorAnchorCoordinate = neighborCoordinate;
            endpoint.connectorCoordinate = neighborCoordinate;
            endpoint.hasCurrentConnection = true;
            if (InputOutputModule.TryGetRuntimePipeSourceAtCoordinate(
                    neighborCoordinate,
                    out Pump runtimePump))
            {
                endpoint.connectorOwner = runtimePump;
                if (runtimePump != null
                    && runtimePump.TryGetPlacementRuntime(
                        out Vector2Int pumpAnchorCoordinate,
                        out _))
                {
                    endpoint.connectorAnchorCoordinate = pumpAnchorCoordinate;
                }
            }
        }

        if (endpoint.hasConnectorRoot
            && TryGetPipeEndpointFluidItemIdAtCoordinate(
                endpoint.connectorCoordinate,
                previewToIgnore,
                out int connectorFluidItemId))
        {
            endpoint.hasFluidIdentity = true;
            endpoint.fluidItemId = connectorFluidItemId;
        }
        else if (endpoint.hasPipeRoot
                 && TryGetAuthoritativePipePlacementForExplicitRotation(
                     endpoint.pipeRootCoordinate,
                     previewToIgnore,
                     out Pipe rootPipe,
                     out Quaternion rootRotation,
                     out _)
                 && TryGetAdjacentPipeBranchFluidItemId(
                     anchorCoordinate,
                     endpoint.pipeRootCoordinate,
                     rootPipe,
                     rootRotation,
                     previewToIgnore,
                     out int pipeFluidItemId))
        {
            endpoint.hasFluidIdentity = true;
            endpoint.fluidItemId = pipeFluidItemId;
        }

        return endpoint.hasPipeRoot || endpoint.hasConnectorRoot;
    }

    private bool TryResolveExplicitPipeRotationFixedConnectorRoot(
        Vector2Int anchorCoordinate,
        Vector2Int direction,
        MapObject previewToIgnore,
        out MapObject connectorOwner,
        out Vector2Int connectorAnchorCoordinate,
        out Vector2Int connectorCoordinate)
    {
        connectorOwner = null;
        connectorAnchorCoordinate = Vector2Int.zero;
        connectorCoordinate = Vector2Int.zero;

        pipeRotationConnectorDirectionsScratch.Clear();
        AppendFixedFluidPipeConnectionDirections(
            anchorCoordinate,
            previewToIgnore,
            pipeRotationConnectorDirectionsScratch);
        bool hasSameCoordinateConnector = PipeDirectionsContain(
            pipeRotationConnectorDirectionsScratch,
            direction);
        pipeRotationConnectorDirectionsScratch.Clear();
        if (hasSameCoordinateConnector)
        {
            if (TryFindExplicitPipeRotationConnectorOwner(
                    anchorCoordinate,
                    direction,
                    true,
                    previewToIgnore,
                    out connectorOwner,
                    out connectorAnchorCoordinate))
            {
                connectorCoordinate = anchorCoordinate;
                return true;
            }

            connectorAnchorCoordinate = anchorCoordinate;
            connectorCoordinate = anchorCoordinate;
            return true;
        }

        Vector2Int adjacentCoordinate = anchorCoordinate + direction;
        if (!TryGetFixedFluidConnectorCompatibilityAtCoordinate(
                adjacentCoordinate,
                -direction,
                out bool connectorCanConnect)
            || !connectorCanConnect)
        {
            return false;
        }

        if (TryFindExplicitPipeRotationConnectorOwner(
                adjacentCoordinate,
                -direction,
                false,
                previewToIgnore,
                out connectorOwner,
                out connectorAnchorCoordinate))
        {
            connectorCoordinate = adjacentCoordinate;
            return true;
        }

        connectorAnchorCoordinate = adjacentCoordinate;
        connectorCoordinate = adjacentCoordinate;
        return true;
    }

    private bool TryFindExplicitPipeRotationConnectorOwner(
        Vector2Int coordinate,
        Vector2Int connectionDirection,
        bool directionIsFromPipe,
        MapObject previewToIgnore,
        out MapObject connectorOwner,
        out Vector2Int connectorAnchorCoordinate)
    {
        connectorOwner = null;
        connectorAnchorCoordinate = Vector2Int.zero;
        pipeAreaBlockCandidateScratchA.Clear();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
            coordinate,
            previewToIgnore,
            pipeAreaBlockCandidateScratchA);
        for (int candidateIndex = 0;
             candidateIndex < pipeAreaBlockCandidateScratchA.Count;
             candidateIndex++)
        {
            PipeAreaBlockCandidate candidate =
                pipeAreaBlockCandidateScratchA[candidateIndex];
            bool connects;
            if (directionIsFromPipe)
            {
                pipeRotationConnectorDirectionsScratch.Clear();
                connects = TryGetPipeAreaCandidateConnectionDirections(
                               coordinate,
                               candidate,
                               pipeRotationConnectorDirectionsScratch)
                           && PipeDirectionsContain(
                               pipeRotationConnectorDirectionsScratch,
                               connectionDirection);
                pipeRotationConnectorDirectionsScratch.Clear();
            }
            else
            {
                connects = candidate.snapshot != null
                           && TryResolveFixedFluidConnectorCompatibility(
                               candidate.snapshot,
                               coordinate,
                               connectionDirection,
                               out bool connectorCanConnect)
                           && connectorCanConnect;
            }

            if (!connects || candidate.snapshot == null)
            {
                continue;
            }

            connectorOwner = candidate.snapshot.mapObject;
            connectorAnchorCoordinate = candidate.snapshot.anchorCoordinate;
            pipeAreaBlockCandidateScratchA.Clear();
            return true;
        }

        pipeAreaBlockCandidateScratchA.Clear();
        return false;
    }

    private bool TryGetPumpConnectionDirectionForExplicitPipeRotation(
        Vector2Int pipeCoordinate,
        out Vector2Int connectionDirection)
    {
        connectionDirection = Vector2Int.zero;
        if (TryGetExactPumpOutputDirectionForPlacement(
                pipeCoordinate,
                out Vector2Int sameCellOutputDirection)
            && sameCellOutputDirection != Vector2Int.zero)
        {
            connectionDirection = -sameCellOutputDirection;
            return true;
        }

        for (int directionIndex = 0;
             directionIndex < PipeCardinalDirections.Length;
             directionIndex++)
        {
            Vector2Int directionFromPipeToOutput =
                PipeCardinalDirections[directionIndex];
            Vector2Int outputCoordinate =
                pipeCoordinate + directionFromPipeToOutput;
            if (!TryGetExactPumpOutputDirectionForPlacement(
                    outputCoordinate,
                    out Vector2Int outputFlowDirection)
                || outputFlowDirection != -directionFromPipeToOutput)
            {
                continue;
            }

            connectionDirection = directionFromPipeToOutput;
            return true;
        }

        return false;
    }

    private bool TryGetAuthoritativePipePlacementForExplicitRotation(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out Pipe pipe,
        out Quaternion pipeRotation,
        out bool isPreview)
    {
        pipe = null;
        pipeRotation = Quaternion.identity;
        isPreview = false;

        if (TryGetInstallPreviewAtCoordinate(coordinate, out MapObject preview)
            && preview != null
            && preview != previewToIgnore)
        {
            MapObject previewSource = ResolveInstallPreviewFootprintSource(preview) ?? preview;
            pipe = preview as Pipe ?? previewSource as Pipe;
            if (pipe != null)
            {
                pipeRotation = preview.transform.rotation;
                isPreview = true;
                return true;
            }
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain != null
            && terrain.TryGetLoadedBlock(coordinate, out Block block)
            && block != null)
        {
            if (block.MapObject is Pipe installedPipe
                && installedPipe.gameObject.activeInHierarchy)
            {
                pipe = installedPipe;
                pipeRotation = installedPipe.transform.rotation;
                return true;
            }

            MapObject occupyingObject = GetOccupyingObjectForPlacement(block, previewToIgnore);
            if (occupyingObject is Pipe occupyingPipe
                && occupyingPipe.gameObject.activeInHierarchy)
            {
                pipe = occupyingPipe;
                pipeRotation = occupyingPipe.transform.rotation;
                return true;
            }
        }

        if (!TryGetSavedPipePlacementAtCoordinate(
                coordinate,
                out Pipe savedPipe,
                out Quaternion savedRotation))
        {
            return false;
        }

        pipe = savedPipe;
        pipeRotation = savedRotation;
        return true;
    }

    private bool TryRotateActiveTrainStationPreviewToNextRail()
    {
        if (activeInstallPreview == null
            || !TryGetPreviewAnchorCoordinate(activeInstallPreview, out Vector2Int anchorCoordinate))
        {
            return false;
        }

        MapObject placementSource = ResolveInstallPreviewPlacementSource(activeInstallPreview) ?? activeInstallPreview;
        if (!TryResolveNextTrainStationFacingQuarterTurns(
                anchorCoordinate,
                placementSource,
                activeInstallPreview,
                installPreviewQuarterTurns,
                out int trainStationQuarterTurns))
        {
            return false;
        }

        installPreviewQuarterTurns = trainStationQuarterTurns;
        installPreviewQuarterTurnsByPreview[activeInstallPreview] = trainStationQuarterTurns;
        activeInstallPreview.transform.rotation = GetInstallPreviewRotation();
        if (activeInstallPreview is InstallationObject installationPreview)
        {
            installationPreview.RefreshInstalledDirectionFromCurrentTransform();
        }

        RefreshPreviewRangeVisualsIfNeeded(activeInstallPreview);
        RefreshUtilityPolePreviewWires();
        RefreshInstallPreviewAreaMarkers(activeInstallPreview);
        RememberBlueprintRotationForPreview(activeInstallDefinition, activeInstallPreview, installPreviewQuarterTurns);
        InvalidateInstallGridPreview();
        return true;
    }

    private bool ShouldPreserveInstallPreviewTransformOnRotation(MapObject preview)
    {
        if (preview == null)
        {
            return false;
        }

        MapObject placementSource = ResolveInstallPreviewPlacementSource(preview);
        return !IsTrainSource(placementSource)
               && !IsBelt2F(placementSource)
               && !IsSteamGeneratorSource(placementSource);
    }

    private Vector3 ResolveInstallPreviewPositionAfterRotation(
        Vector3 previousPosition,
        MapObject placementSource,
        int previousQuarterTurns,
        int targetQuarterTurns)
    {
        Vector2 previousOffset = GetPlacementWorldPositionOffset(placementSource, previousQuarterTurns);
        Vector2 targetOffset = GetPlacementWorldPositionOffset(placementSource, targetQuarterTurns);
        previousPosition.x += targetOffset.x - previousOffset.x;
        previousPosition.z += targetOffset.y - previousOffset.y;
        return previousPosition;
    }

    private static bool RendererHasAnyMaterial(Renderer renderer)
    {
        if (renderer == null)
        {
            return false;
        }

        Material[] materials = renderer.sharedMaterials;
        if (materials == null)
        {
            return false;
        }

        for (int i = 0; i < materials.Length; i++)
        {
            if (materials[i] != null)
            {
                return true;
            }
        }

        return false;
    }

    private bool TryRotateWaterPumpPreviewAtShore(
        bool hasAnchorBlock,
        Block anchorBlock,
        Vector2Int anchorCoordinate,
        out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = GetPreviewQuarterTurns(activeInstallPreview);
        if (!hasAnchorBlock
            || anchorBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(activeInstallPreview, out MapObject footprintSource)
            || !IsWaterPumpSource(footprintSource))
        {
            return false;
        }

        int preferredQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            footprintSource,
            resolvedQuarterTurns + 1);
        if (TryResolveWaterPumpOutwardQuarterTurns(
                anchorCoordinate,
                footprintSource,
                preferredQuarterTurns,
                out int waterPumpQuarterTurns)
            && CanPlacePreviewOnBlock(anchorBlock, activeInstallPreview, waterPumpQuarterTurns))
        {
            resolvedQuarterTurns = waterPumpQuarterTurns;
        }

        return true;
    }

    private bool BoilerPlacementRotationCandidateIsBlockedForActivePreview(
        Block anchorBlock,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        return TryResolveInstallPreviewFootprintSourceForPlacement(
                   activeInstallPreview,
                   out MapObject footprintSource)
               && IsBoilerSource(footprintSource)
               && !CanUseBoilerPlacementRotationCandidate(
                   anchorBlock,
                   anchorCoordinate,
                   activeInstallPreview,
                   footprintSource,
                   quarterTurns);
    }

    private bool CanUseBoilerPlacementRotationCandidate(
        Block anchorBlock,
        Vector2Int anchorCoordinate,
        MapObject preview,
        MapObject footprintSource,
        int quarterTurns)
    {
        return anchorBlock != null
               && !PlacementHasBoilerPlacementRotationConflict(
                   anchorCoordinate,
                   footprintSource,
                   quarterTurns,
                   preview)
               && CanPlacePreviewOnBlock(anchorBlock, preview, quarterTurns);
    }

    private bool PlacementHasBoilerPlacementRotationConflict(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject preview)
    {
        return PlacementHasBoilerEnergyInputPipeConflict(
                   anchorCoordinate,
                   footprintSource,
                   quarterTurns,
                   preview)
               || PlacementHasBoilerPumpOutputDirectionMismatch(
                   anchorCoordinate,
                   footprintSource,
                   quarterTurns);
    }

    private bool TryFindBoilerRotationSkippingPlacementConflicts(
        MapObject preview,
        Vector2Int previousAnchorCoordinate,
        int previousQuarterTurns,
        int startQuarterTurns,
        out Block resolvedAnchorBlock,
        out Vector2Int resolvedAnchorCoordinate,
        out int resolvedQuarterTurns)
    {
        resolvedAnchorBlock = null;
        resolvedAnchorCoordinate = previousAnchorCoordinate;
        resolvedQuarterTurns = startQuarterTurns;

        if (!TryResolveInstallPreviewFootprintSourceForPlacement(preview, out MapObject footprintSource)
            || !IsBoilerSource(footprintSource))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        bool keepPumpOutputAnchor = IsExactPumpOutputCoordinateForPlacement(previousAnchorCoordinate);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizeInstallPreviewQuarterTurns(
                preview,
                startQuarterTurns + offset);
            Vector2Int candidateAnchorCoordinate = previousAnchorCoordinate;
            Block candidateAnchorBlock = null;

            if (!keepPumpOutputAnchor
                && TryResolveRotatedMultiCellInstallPreviewAnchor(
                    preview,
                    previousAnchorCoordinate,
                    previousQuarterTurns,
                    candidateQuarterTurns,
                    out Block reanchoredBlock,
                    out Vector2Int reanchoredCoordinate))
            {
                candidateAnchorBlock = reanchoredBlock;
                candidateAnchorCoordinate = reanchoredCoordinate;
            }
            else if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out candidateAnchorBlock)
                     || candidateAnchorBlock == null)
            {
                continue;
            }

            if (!CanUseBoilerPlacementRotationCandidate(
                    candidateAnchorBlock,
                    candidateAnchorCoordinate,
                    preview,
                    footprintSource,
                    candidateQuarterTurns))
            {
                continue;
            }

            resolvedAnchorBlock = candidateAnchorBlock;
            resolvedAnchorCoordinate = candidateAnchorCoordinate;
            resolvedQuarterTurns = candidateQuarterTurns;
            return true;
        }

        return false;
    }

    private bool ShouldKeepInstallPreviewAnchorOnRotation(MapObject preview, Vector2Int anchorCoordinate)
    {
        if (!TryResolveInstallPreviewFootprintSourceForPlacement(preview, out MapObject footprintSource))
        {
            return false;
        }

        // Vehicles and some rect-grid objects should rotate in place instead of
        // preserving footprint centroid by moving the anchor between grid cells.
        return IsTrainSource(footprintSource)
               || IsSteamGeneratorSource(footprintSource)
               || (IsBoilerSource(footprintSource)
                   && IsExactPumpOutputCoordinateForPlacement(anchorCoordinate));
    }

    private bool TryResolveRotatedMultiCellInstallPreviewAnchor(
        MapObject preview,
        Vector2Int currentAnchorCoordinate,
        int previousQuarterTurns,
        int targetQuarterTurns,
        out Block resolvedAnchorBlock,
        out Vector2Int resolvedAnchorCoordinate)
    {
        resolvedAnchorBlock = null;
        resolvedAnchorCoordinate = currentAnchorCoordinate;

        MapObject footprintSource = ResolveInstallPreviewPlacementSource(preview);
        if (footprintSource == null
            || !HasMultiCellPlacementFootprint(footprintSource)
            || IsBelt2F(footprintSource))
        {
            return false;
        }

        int normalizedPreviousQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            footprintSource,
            previousQuarterTurns);
        int normalizedTargetQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            footprintSource,
            targetQuarterTurns);
        if (normalizedPreviousQuarterTurns == normalizedTargetQuarterTurns)
        {
            return false;
        }

        if (RectGridObjectCoordinatesMatchAtSameAnchor(
                footprintSource,
                currentAnchorCoordinate,
                normalizedPreviousQuarterTurns,
                normalizedTargetQuarterTurns))
        {
            return false;
        }

        // Reanchor against the same visual cells used by world-position placement.
        List<Vector2Int> previousOffsets = GetPlacementVisualLocalOffsets(
            footprintSource,
            normalizedPreviousQuarterTurns);
        List<Vector2Int> targetOffsets = GetPlacementVisualLocalOffsets(
            footprintSource,
            normalizedTargetQuarterTurns);
        if (previousOffsets.Count <= 0 || targetOffsets.Count <= 0)
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        Vector2 previousAverageOffset = GetAverageLocalOffset(previousOffsets);
        Vector2 targetAverageOffset = GetAverageLocalOffset(targetOffsets);
        Vector2 desiredCenter = new Vector2(currentAnchorCoordinate.x, currentAnchorCoordinate.y) + previousAverageOffset;
        Vector2 idealAnchor = desiredCenter - targetAverageOffset;

        HashSet<Vector2Int> previousCoordinates = new HashSet<Vector2Int>();
        for (int i = 0; i < previousOffsets.Count; i++)
        {
            previousCoordinates.Add(currentAnchorCoordinate + previousOffsets[i]);
        }

        List<Vector2Int> candidates = new List<Vector2Int>();
        HashSet<Vector2Int> candidateSet = new HashSet<Vector2Int>();
        void AddCandidate(Vector2Int candidate)
        {
            if (candidateSet.Add(candidate))
            {
                candidates.Add(candidate);
            }
        }

        int roundedX = RoundGridCoordinate(idealAnchor.x);
        int roundedY = RoundGridCoordinate(idealAnchor.y);
        AddCandidate(new Vector2Int(roundedX, roundedY));

        int floorX = Mathf.FloorToInt(idealAnchor.x);
        int ceilX = Mathf.CeilToInt(idealAnchor.x);
        int floorY = Mathf.FloorToInt(idealAnchor.y);
        int ceilY = Mathf.CeilToInt(idealAnchor.y);
        AddCandidate(new Vector2Int(floorX, floorY));
        AddCandidate(new Vector2Int(ceilX, floorY));
        AddCandidate(new Vector2Int(floorX, ceilY));
        AddCandidate(new Vector2Int(ceilX, ceilY));
        AddCandidate(currentAnchorCoordinate);

        for (int previousIndex = 0; previousIndex < previousOffsets.Count; previousIndex++)
        {
            Vector2Int previousCoordinate = currentAnchorCoordinate + previousOffsets[previousIndex];
            for (int targetIndex = 0; targetIndex < targetOffsets.Count; targetIndex++)
            {
                AddCandidate(previousCoordinate - targetOffsets[targetIndex]);
            }
        }

        Vector2Int bestCoordinate = currentAnchorCoordinate;
        Block bestBlock = null;
        float bestCenterDistance = float.MaxValue;
        int bestOverlap = -1;
        for (int i = 0; i < candidates.Count; i++)
        {
            Vector2Int candidateCoordinate = candidates[i];
            if (!terrain.TryGetLoadedBlock(candidateCoordinate, out Block candidateBlock)
                || candidateBlock == null
                || !CanPlacePreviewOnBlock(candidateBlock, preview, normalizedTargetQuarterTurns))
            {
                continue;
            }

            Vector2 candidateCenter =
                new Vector2(candidateCoordinate.x, candidateCoordinate.y) + targetAverageOffset;
            float centerDistance = (candidateCenter - desiredCenter).sqrMagnitude;
            int overlap = CountRotatedFootprintOverlap(
                candidateCoordinate,
                targetOffsets,
                previousCoordinates);
            if (centerDistance > bestCenterDistance + 0.0001f
                || (Mathf.Abs(centerDistance - bestCenterDistance) <= 0.0001f
                    && overlap <= bestOverlap))
            {
                continue;
            }

            bestCenterDistance = centerDistance;
            bestOverlap = overlap;
            bestCoordinate = candidateCoordinate;
            bestBlock = candidateBlock;
        }

        if (bestBlock == null || bestCoordinate == currentAnchorCoordinate)
        {
            return false;
        }

        resolvedAnchorBlock = bestBlock;
        resolvedAnchorCoordinate = bestCoordinate;
        return true;
    }

    private bool RectGridObjectCoordinatesMatchAtSameAnchor(
        MapObject footprintSource,
        Vector2Int anchorCoordinate,
        int previousQuarterTurns,
        int targetQuarterTurns)
    {
        return TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
               && inputOutputModule.RectGridPlacements != null
               && TryGetRectGridFootprintSettings(
                   footprintSource,
                   out _,
                   out _,
                   out Vector2Int objectAnchorCell)
               && RectGridObjectCoordinatesMatch(
                   inputOutputModule.RectGridPlacements,
                   objectAnchorCell,
                   anchorCoordinate,
                   previousQuarterTurns,
                   anchorCoordinate,
                   targetQuarterTurns);
    }

    private static Vector2 GetAverageLocalOffset(IReadOnlyList<Vector2Int> offsets)
    {
        if (offsets == null || offsets.Count <= 0)
        {
            return Vector2.zero;
        }

        Vector2 averageOffset = Vector2.zero;
        for (int i = 0; i < offsets.Count; i++)
        {
            averageOffset += offsets[i];
        }

        return averageOffset / offsets.Count;
    }

    private static int CountRotatedFootprintOverlap(
        Vector2Int anchorCoordinate,
        IReadOnlyList<Vector2Int> localOffsets,
        ISet<Vector2Int> previousCoordinates)
    {
        if (localOffsets == null || previousCoordinates == null || previousCoordinates.Count <= 0)
        {
            return 0;
        }

        int overlap = 0;
        for (int i = 0; i < localOffsets.Count; i++)
        {
            if (previousCoordinates.Contains(anchorCoordinate + localOffsets[i]))
            {
                overlap++;
            }
        }

        return overlap;
    }

    private static int RoundGridCoordinate(float value)
    {
        return Mathf.FloorToInt(value + 0.5f);
    }

    private bool TryRotateSteamGeneratorPreviewInPlaceOnStraightPipe(
        bool hasAnchorBlock,
        Vector2Int anchorCoordinate,
        out bool handled,
        out Block resolvedAnchorBlock,
        out Vector2Int resolvedAnchorCoordinate,
        out int resolvedQuarterTurns)
    {
        handled = false;
        resolvedAnchorBlock = null;
        resolvedAnchorCoordinate = anchorCoordinate;
        resolvedQuarterTurns = GetPreviewQuarterTurns(activeInstallPreview);
        if (!hasAnchorBlock
            || activeInstallPreview == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(activeInstallPreview, out MapObject footprintSource)
            || !IsSteamGeneratorSource(footprintSource)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        if (!TryGetRectGridFootprintSettings(
                footprintSource,
                out _,
                out _,
                out Vector2Int objectAnchorCell))
        {
            return false;
        }

        int currentQuarterTurns = GetPreviewQuarterTurns(activeInstallPreview);
        int targetQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            footprintSource,
            currentQuarterTurns + 2);
        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (!InputOutputModule.AllowsPipeAreaInteraction(placement.blockType)
                || !TryGetRectGridCoordinate(
                    anchorCoordinate,
                    footprintSource,
                    currentQuarterTurns,
                    placement,
                    out Vector2Int pipeCoordinate)
                || !TryGetPipePlacementAtCoordinate(
                    pipeCoordinate,
                    out Pipe pipe,
                    out Quaternion pipeRotation)
                || !TryGetStraightPipeAxis(pipe, pipeRotation, out _))
            {
                continue;
            }

            handled = true;

            for (int targetPlacementIndex = 0; targetPlacementIndex < placements.Count; targetPlacementIndex++)
            {
                InputOutputModule.RectGridBlockPlacement targetPlacement = placements[targetPlacementIndex];
                if (!InputOutputModule.AllowsPipeAreaInteraction(targetPlacement.blockType))
                {
                    continue;
                }

                Vector2Int localOffset = new Vector2Int(
                    targetPlacement.x - objectAnchorCell.x,
                    targetPlacement.y - objectAnchorCell.y);
                Vector2Int candidateAnchorCoordinate =
                    pipeCoordinate - RotateFootprintOffset(localOffset, targetQuarterTurns);
                if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                    || candidateAnchorBlock == null
                    || !RectGridObjectCoordinatesMatch(
                        placements,
                        objectAnchorCell,
                        anchorCoordinate,
                        currentQuarterTurns,
                        candidateAnchorCoordinate,
                        targetQuarterTurns))
                {
                    continue;
                }

                resolvedAnchorBlock = candidateAnchorBlock;
                resolvedAnchorCoordinate = candidateAnchorCoordinate;
                resolvedQuarterTurns = targetQuarterTurns;
                return true;
            }
        }

        return false;
    }

    private static bool RectGridObjectCoordinatesMatch(
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements,
        Vector2Int objectAnchorCell,
        Vector2Int firstAnchorCoordinate,
        int firstQuarterTurns,
        Vector2Int secondAnchorCoordinate,
        int secondQuarterTurns)
    {
        if (placements == null || placements.Count <= 0)
        {
            return false;
        }

        int firstObjectCount = 0;
        int secondObjectCount = 0;
        for (int i = 0; i < placements.Count; i++)
        {
            if (placements[i].blockType == InputOutputModule.RectGridBlockType.Object)
            {
                firstObjectCount++;
                secondObjectCount++;
            }
        }

        if (firstObjectCount <= 0 || firstObjectCount != secondObjectCount)
        {
            return false;
        }

        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement firstPlacement = placements[i];
            if (firstPlacement.blockType != InputOutputModule.RectGridBlockType.Object)
            {
                continue;
            }

            Vector2Int firstOffset = new Vector2Int(
                firstPlacement.x - objectAnchorCell.x,
                firstPlacement.y - objectAnchorCell.y);
            Vector2Int firstCoordinate =
                firstAnchorCoordinate + RotateFootprintOffset(firstOffset, firstQuarterTurns);
            bool foundMatchingSecondCoordinate = false;
            for (int j = 0; j < placements.Count; j++)
            {
                InputOutputModule.RectGridBlockPlacement secondPlacement = placements[j];
                if (secondPlacement.blockType != InputOutputModule.RectGridBlockType.Object)
                {
                    continue;
                }

                Vector2Int secondOffset = new Vector2Int(
                    secondPlacement.x - objectAnchorCell.x,
                    secondPlacement.y - objectAnchorCell.y);
                Vector2Int secondCoordinate =
                    secondAnchorCoordinate + RotateFootprintOffset(secondOffset, secondQuarterTurns);
                if (secondCoordinate != firstCoordinate)
                {
                    continue;
                }

                foundMatchingSecondCoordinate = true;
                break;
            }

            if (!foundMatchingSecondCoordinate)
            {
                return false;
            }
        }

        return true;
    }

    private bool IsActiveBelt2FPreview()
    {
        if (activeInstallPreview == null)
        {
            return false;
        }

        MapObject footprintSource = ResolveInstallPreviewFootprintSource(activeInstallPreview)
                                    ?? (activeInstallDefinition != null ? activeInstallDefinition.mapObject : null)
                                    ?? activeInstallPreview;
        return IsBelt2F(footprintSource);
    }

    private bool TryRotateBelt2FPreviewAroundBridgeCenter(
        bool hasAnchorBlock,
        Vector2Int currentAnchorCoordinate,
        out Block rotatedAnchorBlock,
        out Vector2Int rotatedAnchorCoordinate,
        out int rotatedQuarterTurns)
    {
        rotatedAnchorBlock = null;
        rotatedAnchorCoordinate = currentAnchorCoordinate;
        rotatedQuarterTurns = GetNextInstallPreviewQuarterTurns(activeInstallPreview, installPreviewQuarterTurns);

        if (!hasAnchorBlock)
        {
            return true;
        }

        MapObject footprintSource = ResolveInstallPreviewFootprintSource(activeInstallPreview)
                                    ?? (activeInstallDefinition != null ? activeInstallDefinition.mapObject : null)
                                    ?? activeInstallPreview;
        if (!IsBelt2F(footprintSource))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        Vector2Int bridgeCenterCoordinate = GetBelt2FBridgeCenterCoordinate(
            currentAnchorCoordinate,
            footprintSource,
            GetPreviewQuarterTurns(activeInstallPreview));

        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        int startQuarterTurns = GetNextInstallPreviewQuarterTurns(activeInstallPreview, installPreviewQuarterTurns);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizeInstallPreviewQuarterTurns(
                activeInstallPreview,
                startQuarterTurns + offset);
            Vector2Int candidateAnchorCoordinate =
                bridgeCenterCoordinate - GetBelt2FBridgeCenterOffset(footprintSource, candidateQuarterTurns);
            if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                || candidateAnchorBlock == null
                || !CanPlacePreviewOnBlock(candidateAnchorBlock, activeInstallPreview, candidateQuarterTurns))
            {
                continue;
            }

            rotatedAnchorBlock = candidateAnchorBlock;
            rotatedAnchorCoordinate = candidateAnchorCoordinate;
            rotatedQuarterTurns = candidateQuarterTurns;
            return true;
        }

        rotatedAnchorBlock = null;
        rotatedAnchorCoordinate = currentAnchorCoordinate;
        rotatedQuarterTurns = GetPreviewQuarterTurns(activeInstallPreview);
        return false;
    }

    private bool TryFindNextConveyorPreviewRotation(
        ConveyorBelt conveyorPrototype,
        Vector2Int? anchorCoordinate,
        MapObject previewToIgnore,
        int currentStraightQuarterTurns,
        bool currentUsesCornerVariant,
        out int resolvedQuarterTurns,
        out ConveyorPreviewVariantMode resolvedVariantMode,
        out MapObject resolvedVariantPrefab,
        out int resolvedSequenceIndex)
    {
        int normalizedCurrentQuarterTurns = NormalizePlacementQuarterTurns(currentStraightQuarterTurns);
        resolvedQuarterTurns = normalizedCurrentQuarterTurns;
        resolvedVariantMode = currentUsesCornerVariant
            ? ConveyorPreviewVariantMode.Corner
            : ConveyorPreviewVariantMode.Straight;
        resolvedVariantPrefab = null;
        resolvedSequenceIndex = 0;

        if (conveyorPrototype == null)
        {
            return false;
        }

        int currentSequenceIndex = previewToIgnore != null
            && installPreviewConveyorRotationSequenceIndexesByPreview.TryGetValue(
                previewToIgnore,
                out int storedSequenceIndex)
                ? NormalizeConveyorRotationSequenceIndex(storedSequenceIndex)
                : GetConveyorRotationSequenceIndex(
                    conveyorPrototype,
                    previewToIgnore,
                    normalizedCurrentQuarterTurns,
                    currentUsesCornerVariant);

        for (int offset = 1; offset <= ConveyorRotationSequenceCount; offset++)
        {
            int candidateSequenceIndex = NormalizeConveyorRotationSequenceIndex(currentSequenceIndex + offset);
            if (!TryGetConveyorRotationSequenceCandidate(
                    conveyorPrototype,
                    candidateSequenceIndex,
                    out int candidateQuarterTurns,
                    out ConveyorPreviewVariantMode candidateVariantMode,
                    out MapObject candidateVariantPrefab)
                || candidateVariantPrefab == null)
            {
                continue;
            }

            if (candidateVariantMode == ConveyorPreviewVariantMode.Corner
                && anchorCoordinate.HasValue
                && !CanUseConveyorCornerRotationCandidate(
                    anchorCoordinate.Value,
                    candidateVariantPrefab,
                    candidateQuarterTurns,
                    previewToIgnore))
            {
                continue;
            }

            resolvedQuarterTurns = candidateQuarterTurns;
            resolvedVariantMode = candidateVariantMode;
            resolvedVariantPrefab = candidateVariantPrefab;
            resolvedSequenceIndex = candidateSequenceIndex;
            return true;
        }

        return false;
    }

    private int GetConveyorRotationSequenceIndex(
        ConveyorBelt conveyorPrototype,
        MapObject preview,
        int currentStraightQuarterTurns,
        bool currentUsesCornerVariant)
    {
        int normalizedCurrentQuarterTurns = NormalizePlacementQuarterTurns(currentStraightQuarterTurns);
        if (currentUsesCornerVariant
            && preview is ConveyorBelt previewConveyor
            && previewConveyor.IsCornerVariant)
        {
            int outputQuarterTurns = normalizedCurrentQuarterTurns;
            if (TryGetConveyorStraightQuarterTurnsFromPreview(preview, conveyorPrototype, out int resolvedOutputQuarterTurns))
            {
                outputQuarterTurns = NormalizePlacementQuarterTurns(resolvedOutputQuarterTurns);
            }

            int cornerSequenceBaseIndex = ((outputQuarterTurns + 3) % 4) * 3;
            return cornerSequenceBaseIndex + (previewConveyor.IsReverseCornerVariant ? 2 : 1);
        }

        return normalizedCurrentQuarterTurns * 3;
    }

    private static int NormalizeConveyorRotationSequenceIndex(int sequenceIndex)
    {
        return ((sequenceIndex % ConveyorRotationSequenceCount) + ConveyorRotationSequenceCount) % ConveyorRotationSequenceCount;
    }

    private bool TryGetConveyorRotationSequenceCandidate(
        ConveyorBelt conveyorPrototype,
        int candidateSequenceIndex,
        out int candidateQuarterTurns,
        out ConveyorPreviewVariantMode candidateVariantMode,
        out MapObject candidateVariantPrefab)
    {
        candidateQuarterTurns = 0;
        candidateVariantMode = ConveyorPreviewVariantMode.Straight;
        candidateVariantPrefab = null;
        if (conveyorPrototype == null)
        {
            return false;
        }

        int normalizedSequenceIndex = NormalizeConveyorRotationSequenceIndex(candidateSequenceIndex);
        int straightQuarterTurns = normalizedSequenceIndex / 3;
        int sequenceStep = normalizedSequenceIndex % 3;
        if (sequenceStep == 0)
        {
            candidateQuarterTurns = straightQuarterTurns;
            candidateVariantPrefab = ResolveConveyorVariantPrefab(conveyorPrototype, 0) ?? conveyorPrototype;
            return candidateVariantPrefab is ConveyorBelt straightConveyor && !straightConveyor.IsCornerVariant;
        }

        if (conveyorPrototype.CornerVariantPrefab == null
            && conveyorPrototype.ReverseCornerVariantPrefab == null)
        {
            return false;
        }

        candidateQuarterTurns = (straightQuarterTurns + 1) % 4;
        candidateVariantMode = ConveyorPreviewVariantMode.Corner;
        candidateVariantPrefab = ResolveConveyorVariantPrefab(conveyorPrototype, sequenceStep == 1 ? 1 : 2);
        return candidateVariantPrefab is ConveyorBelt resolvedCornerConveyor
            && resolvedCornerConveyor.IsCornerVariant
            && resolvedCornerConveyor.IsReverseCornerVariant == (sequenceStep == 2);
    }

    private bool CanUseConveyorCornerRotationCandidate(
        Vector2Int anchorCoordinate,
        MapObject candidateVariantPrefab,
        int candidateQuarterTurns,
        MapObject previewToIgnore)
    {
        if (!(candidateVariantPrefab is ConveyorBelt candidateConveyor)
            || !candidateConveyor.IsCornerVariant)
        {
            return false;
        }

        Quaternion candidateRotation = GetPlacementObjectRotation(candidateConveyor, candidateQuarterTurns);
        if (!candidateConveyor.TryGetInputDirection(candidateRotation, out Vector2Int inputDirection)
            || !candidateConveyor.TryGetOutputDirection(candidateRotation, out Vector2Int outputDirection))
        {
            return false;
        }

        bool hasConnectedEndpoint = false;
        Vector2Int[] sideDirections =
        {
            Vector2Int.up,
            Vector2Int.right,
            Vector2Int.down,
            Vector2Int.left
        };

        for (int i = 0; i < sideDirections.Length; i++)
        {
            Vector2Int sideDirection = sideDirections[i];
            if (!TryGetConveyorPlacementDirectionsAtCoordinate(
                    anchorCoordinate + sideDirection,
                    previewToIgnore,
                    out ConveyorBelt conveyorBelt,
                    out Vector2Int neighborInputDirection,
                    out Vector2Int neighborOutputDirection))
            {
                continue;
            }

            if (sideDirection == inputDirection)
            {
                if (neighborOutputDirection == -sideDirection
                    || IsStraightConveyorSideSeamConnection(
                        conveyorBelt,
                        sideDirection,
                        neighborOutputDirection))
                {
                    hasConnectedEndpoint = true;
                    continue;
                }

                return false;
            }

            if (sideDirection == outputDirection)
            {
                if (neighborInputDirection == -sideDirection
                    || IsStraightConveyorSideSeamConnection(
                        conveyorBelt,
                        sideDirection,
                        neighborOutputDirection))
                {
                    hasConnectedEndpoint = true;
                    continue;
                }

                return false;
            }
        }

        return hasConnectedEndpoint;
    }

    private bool TryResolveActiveConveyorCornerPromotion(
        ConveyorBelt conveyorPrototype,
        MapObject sourcePrefab,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore,
        out MapObject resolvedPrefab,
        out int resolvedQuarterTurns)
    {
        resolvedPrefab = sourcePrefab;
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(quarterTurns);
        if (conveyorPrototype == null
            || straightFirstConveyorPreviews.Contains(previewToIgnore)
            || IsBelt2F(conveyorPrototype)
            || !(sourcePrefab is ConveyorBelt sourceConveyor)
            || sourceConveyor.IsCornerVariant)
        {
            return false;
        }

        if (!TryResolveConveyorCornerPlacementPrefab(
                conveyorPrototype,
                anchorCoordinate,
                quarterTurns,
                previewToIgnore,
                out MapObject cornerPrefab,
                out int cornerQuarterTurns,
                false,
                false))
        {
            return false;
        }

        if (!(cornerPrefab is ConveyorBelt cornerConveyor)
            || !cornerConveyor.IsCornerVariant
            || !TryGetConveyorEndpointConnectionScoreForSource(
                cornerConveyor,
                anchorCoordinate,
                cornerQuarterTurns,
                previewToIgnore,
                out int cornerConnectionScore)
            || cornerConnectionScore <= 0)
        {
            return false;
        }

        int straightConnectionScore = GetConveyorEndpointConnectionScore(
            anchorCoordinate,
            sourceConveyor,
            quarterTurns,
            previewToIgnore);
        if (cornerConnectionScore < 2 || cornerConnectionScore <= straightConnectionScore)
        {
            return false;
        }

        resolvedPrefab = cornerPrefab;
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(cornerQuarterTurns);
        return true;
    }

    private bool TryGetConveyorEndpointConnectionScoreForSource(
        ConveyorBelt conveyorSource,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore,
        out int connectionScore)
    {
        connectionScore = 0;
        if (conveyorSource == null)
        {
            return false;
        }

        Quaternion sourceRotation = GetPlacementObjectRotation(conveyorSource, quarterTurns);
        if (!conveyorSource.TryGetInputDirection(sourceRotation, out Vector2Int inputDirection)
            || !conveyorSource.TryGetOutputDirection(sourceRotation, out Vector2Int outputDirection))
        {
            return false;
        }

        connectionScore = GetConveyorEndpointConnectionScore(
            anchorCoordinate,
            inputDirection,
            outputDirection,
            previewToIgnore);
        return true;
    }

    private int GetConveyorEndpointConnectionScore(
        Vector2Int anchorCoordinate,
        ConveyorBelt conveyorSource,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (conveyorSource == null)
        {
            return 0;
        }

        Quaternion sourceRotation = GetPlacementObjectRotation(conveyorSource, quarterTurns);
        if (!conveyorSource.TryGetInputDirection(sourceRotation, out Vector2Int inputDirection)
            || !conveyorSource.TryGetOutputDirection(sourceRotation, out Vector2Int outputDirection))
        {
            return 0;
        }

        return GetConveyorEndpointConnectionScore(
            anchorCoordinate,
            inputDirection,
            outputDirection,
            previewToIgnore);
    }

    private MapObject ResolveConveyorPreviewSourceForAnchor(
        ConveyorBelt conveyorPrototype,
        MapObject sourcePrefab,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (IsBelt2F(conveyorPrototype))
        {
            return sourcePrefab != null ? sourcePrefab : conveyorPrototype;
        }

        if (conveyorPrototype == null || !(sourcePrefab is ConveyorBelt sourceConveyor) || !sourceConveyor.IsCornerVariant)
        {
            return sourcePrefab;
        }

        if (CanUseConveyorCornerRotationCandidate(
                anchorCoordinate,
                sourcePrefab,
                quarterTurns,
                previewToIgnore))
        {
            return sourcePrefab;
        }

        return ResolveConveyorVariantPrefab(conveyorPrototype, 0) ?? conveyorPrototype;
    }

    private bool IsSameConveyorPreviewState(MapObject preview, MapObject candidatePrefab, int candidateQuarterTurns)
    {
        if (!(preview is ConveyorBelt previewConveyor)
            || !(candidatePrefab is ConveyorBelt candidateConveyor))
        {
            return false;
        }

        if (previewConveyor.IsCornerVariant != candidateConveyor.IsCornerVariant
            || previewConveyor.IsReverseCornerVariant != candidateConveyor.IsReverseCornerVariant)
        {
            return false;
        }

        Quaternion candidateRotation = GetPlacementObjectRotation(candidateConveyor, candidateQuarterTurns);
        return Mathf.Abs(Quaternion.Dot(preview.transform.rotation, candidateRotation)) >= 0.9999f;
    }

    private bool TryGetConveyorStraightQuarterTurnsFromPreview(MapObject preview, ConveyorBelt conveyorPrototype, out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = installPreviewQuarterTurns;
        if (!(preview is ConveyorBelt previewConveyor) || conveyorPrototype == null)
        {
            return false;
        }

        if (!previewConveyor.TryGetOutputDirection(preview.transform.rotation, out Vector2Int outputDirection))
        {
            return false;
        }

        ConveyorBelt straightPrefab = conveyorPrototype.StraightVariantPrefab != null
            ? conveyorPrototype.StraightVariantPrefab
            : conveyorPrototype;
        return TryGetConveyorPlacementQuarterTurnsForOutput(straightPrefab, outputDirection, out resolvedQuarterTurns);
    }

    private Quaternion GetInstallPreviewRotation()
    {
        if (activeInstallPreview != null)
        {
            MapObject rotationSource = ResolveInstallPreviewRotationSource(activeInstallPreview);
            Quaternion previewBaseRotation = installPreviewBaseRotationsByPreview.TryGetValue(activeInstallPreview, out Quaternion storedBaseRotation)
                ? storedBaseRotation
                : (rotationSource != null ? rotationSource.transform.rotation : activeInstallPreview.transform.rotation);
            if (TryGetPreviewAnchorCoordinate(activeInstallPreview, out Vector2Int anchorCoordinate))
            {
                Vector3 railReferencePosition = installPreviewRailReferenceWorldPositions.TryGetValue(
                    activeInstallPreview,
                    out Vector3 storedRailReferencePosition)
                    ? storedRailReferencePosition
                    : activeInstallPreview.transform.position;
                return ResolvePlacementObjectRotation(
                    previewBaseRotation,
                    rotationSource,
                    anchorCoordinate,
                    installPreviewQuarterTurns,
                    railReferencePosition);
            }

            return GetPlacementObjectRotation(previewBaseRotation, rotationSource, installPreviewQuarterTurns);
        }

        if (activeInstallDefinition != null && activeInstallDefinition.mapObject != null)
        {
            return GetPlacementObjectRotation(activeInstallBaseRotation, activeInstallDefinition.mapObject, installPreviewQuarterTurns);
        }

        return Quaternion.identity;
    }

    private void SetInstallPreviewRailReferenceForPlacement(
        MapObject placementSource,
        Vector3? railReferenceWorldPosition)
    {
        if (activeInstallPreview == null)
        {
            return;
        }

        if (IsTrainSource(placementSource) && railReferenceWorldPosition.HasValue)
        {
            installPreviewRailReferenceWorldPositions[activeInstallPreview] = railReferenceWorldPosition.Value;
            return;
        }

        installPreviewRailReferenceWorldPositions.Remove(activeInstallPreview);
    }

    private void HandleInstallPreviewClick(Vector2 pointerPosition)
    {
        if (IsUndergroundPipeInstallDefinition(activeInstallDefinition))
        {
            HandleUndergroundPipePreviewClick(pointerPosition);
            return;
        }

        if (IsFreightCarLoadInstallDefinition(activeInstallDefinition)
            && TryGetPointerFreightCar(pointerPosition, out _, out _))
        {
            if (TryResolveFreightCarBoxInstallTarget(
                    pointerPosition,
                    null,
                    out FreightCar freightCar,
                    out Transform boxPoint))
            {
                if (TryGetFreightCarBoxPreviewAtTarget(freightCar, boxPoint, out MapObject freightBoxPreview)
                    && freightBoxPreview != null)
                {
                    RemoveInstallPreview(freightBoxPreview);
                    return;
                }

                if (CanCreateAdditionalPreview())
                {
                    TryCreateAndPlaceFreightCarBoxPreview(freightCar, boxPoint);
                }
            }

            return;
        }

        if (!TryGetPointerBlock(pointerPosition, out Block clickedBlock) || clickedBlock == null)
        {
            return;
        }

        Vector3? railReferenceWorldPosition = TryGetInstallPreviewRailReferenceWorldPosition(
            pointerPosition,
            out Vector3 pointerWorldPosition)
            ? pointerWorldPosition
            : null;

        if (TryGetInstallPreviewAtBlock(clickedBlock, out MapObject clickedPreview) && clickedPreview != null)
        {
            if (IsPreviewObjectCell(clickedPreview, clickedBlock))
            {
                RemoveInstallPreview(clickedPreview);
                return;
            }

            if (CanCreateAdditionalPreview()
                && CoordinateHasInputOutputAreaForPlacement(clickedBlock.Coordinate, null)
                && TryCreateAndPlaceInstallPreview(clickedBlock, clickedPreview, railReferenceWorldPosition))
            {
                return;
            }

            SelectInstallPreview(clickedPreview);
            return;
        }

        if (CanCreateAdditionalPreview())
        {
            TryCreateAndPlaceInstallPreview(clickedBlock, null, railReferenceWorldPosition);
        }
    }

    private void SelectInstallPreview(MapObject preview)
    {
        SelectInstallPreview(preview, true, true);
    }

    private void SelectInstallPreview(MapObject preview, bool refreshDependentVisuals, bool invalidateGrid)
    {
        if (preview == null)
        {
            return;
        }

        InvalidateInstallPreviewMoveCache();
        activeInstallPreview = preview;
        installPreviewQuarterTurns = GetPreviewQuarterTurns(preview);
        installPreviewConveyorVariantMode = GetConveyorPreviewVariantMode(preview);
        if (!SnapFreightCarBoxPreviewToTarget(activeInstallPreview))
        {
            activeInstallPreview.transform.rotation = GetInstallPreviewRotation();
        }

        if (activeInstallPreview is InstallationObject selectedInstallationPreview)
        {
            selectedInstallationPreview.RefreshInstalledDirectionFromCurrentTransform();
        }
        ConfigurePreviewOnlyRuntimeRendering(activeInstallPreview);
        RefreshHandcartInstallPreviewConnectionPoses();

        if (refreshDependentVisuals)
        {
            RefreshInstallPreviewSelectionVisuals();
            RefreshInstallPreviewAreaMarkers(activeInstallPreview);
            RefreshInstallOrEditWorkableRangeVisualRequest();
        }

        if (invalidateGrid)
        {
            InvalidateInstallGrid();
        }
    }

    private int GetPreviewQuarterTurns(MapObject preview)
    {
        if (preview == null)
        {
            return 0;
        }

        if (installPreviewQuarterTurnsByPreview.TryGetValue(preview, out int storedQuarterTurns))
        {
            return NormalizePlacementQuarterTurnsForObject(
                ResolveInstallPreviewRotationSource(preview),
                storedQuarterTurns);
        }

        if (preview == activeInstallPreview)
        {
            return NormalizePlacementQuarterTurnsForObject(
                ResolveInstallPreviewRotationSource(preview),
                installPreviewQuarterTurns);
        }

        return 0;
    }

    private int GetPreviewAreaQuarterTurns(MapObject preview)
    {
        if (preview == null)
        {
            return 0;
        }

        MapObject placementSource = ResolveInstallPreviewPlacementSource(preview);
        if (installPreviewQuarterTurnsByPreview.TryGetValue(preview, out int storedQuarterTurns))
        {
            return NormalizePlacementQuarterTurnsForObject(
                placementSource,
                storedQuarterTurns);
        }

        if (preview == activeInstallPreview)
        {
            return NormalizePlacementQuarterTurnsForObject(placementSource, installPreviewQuarterTurns);
        }

        if (TryResolvePlacementQuarterTurnsFromRotation(
                placementSource,
                preview.transform.rotation,
                out int transformQuarterTurns))
        {
            return NormalizePlacementQuarterTurnsForObject(
                placementSource,
                transformQuarterTurns);
        }

        return 0;
    }

    private void SetInstallPreviewQuarterTurns(MapObject preview, int quarterTurns)
    {
        if (preview == null)
        {
            return;
        }

        int normalizedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            ResolveInstallPreviewRotationSource(preview),
            quarterTurns);
        installPreviewQuarterTurnsByPreview[preview] = normalizedQuarterTurns;
        if (preview == activeInstallPreview)
        {
            installPreviewQuarterTurns = normalizedQuarterTurns;
        }
    }

    private MapObject ResolveInstallPreviewRotationSource(MapObject preview)
    {
        if (preview != null
            && installPreviewSourcePrefabsByPreview.TryGetValue(preview, out MapObject sourcePrefab)
            && sourcePrefab != null)
        {
            return sourcePrefab;
        }

        return preview;
    }

    private static int NormalizePlacementQuarterTurns(int quarterTurns)
    {
        return ((quarterTurns % 4) + 4) % 4;
    }

    private static InstallationRotationFilter GetPlacementRotationFilter(MapObject sourcePrefab)
    {
        // Auto-selected corner/tee variants may need all four rotations even when
        // the item blueprint only exposes horizontal/vertical rotation to the player.
        return sourcePrefab is InstallationObject installationObject
            ? installationObject.RotationFilter
            : InstallationRotationFilter.All;
    }

    private static bool UsesTwoStatePlacementRotation(MapObject sourcePrefab)
    {
        return GetPlacementRotationFilter(sourcePrefab) == InstallationRotationFilter.HorizontalAndVertical;
    }

    private static int GetPlacementRotationCandidateCount(MapObject sourcePrefab)
    {
        return GetPlacementRotationFilter(sourcePrefab) switch
        {
            InstallationRotationFilter.Fixed => 1,
            InstallationRotationFilter.HorizontalAndVertical => 2,
            _ => 4
        };
    }

    private static int NormalizePlacementQuarterTurnsForObject(MapObject sourcePrefab, int quarterTurns)
    {
        int normalizedQuarterTurns = NormalizePlacementQuarterTurns(quarterTurns);
        return GetPlacementRotationFilter(sourcePrefab) switch
        {
            InstallationRotationFilter.Fixed => 0,
            InstallationRotationFilter.HorizontalAndVertical => normalizedQuarterTurns % 2,
            _ => normalizedQuarterTurns
        };
    }

    private static int ResolveTwoStateQuarterTurnsFromRotation(
        MapObject sourcePrefab,
        Quaternion worldRotation,
        int fallbackQuarterTurns)
    {
        int bestQuarterTurns = -1;
        float bestDot = -1f;
        Quaternion baseRotation = sourcePrefab != null
            ? sourcePrefab.transform.rotation
            : Quaternion.identity;

        for (int candidateQuarterTurns = 0; candidateQuarterTurns < 4; candidateQuarterTurns++)
        {
            Quaternion candidateRotation = baseRotation * Quaternion.Euler(0f, candidateQuarterTurns * 90f, 0f);
            float dot = Mathf.Abs(Quaternion.Dot(candidateRotation, worldRotation));
            if (dot > bestDot)
            {
                bestDot = dot;
                bestQuarterTurns = candidateQuarterTurns;
            }
        }

        if (bestQuarterTurns >= 0 && bestDot >= PlacementRotationNearestDotThreshold)
        {
            return bestQuarterTurns % 2;
        }

        return NormalizePlacementQuarterTurns(fallbackQuarterTurns) % 2;
    }

    private int GetNextInstallPreviewQuarterTurns(MapObject preview, int currentQuarterTurns)
    {
        switch (GetInstallPreviewUserRotationFilter(preview))
        {
            case InstallationRotationFilter.Fixed:
                return 0;
            case InstallationRotationFilter.HorizontalAndVertical:
                return NormalizeInstallPreviewQuarterTurns(preview, currentQuarterTurns) == 0 ? 1 : 0;
            default:
                return NormalizePlacementQuarterTurns(currentQuarterTurns + 1);
        }
    }

    private void HandleUndergroundPipePreviewClick(Vector2 pointerPosition)
    {
        if (!TryGetPointerBlock(pointerPosition, out Block clickedBlock) || clickedBlock == null)
        {
            return;
        }

        if (activeInstallPreview is UndergroundPipe pendingPreview
            && !pendingPreview.IsPreviewPairCommitted
            && TryGetPreviewAnchorCoordinate(pendingPreview, out Vector2Int firstCoordinate))
        {
            bool hadPreviousCandidate = pendingPreview.TryGetPreviewCandidateCoordinates(
                out Vector2Int previousFirstCoordinate,
                out Vector2Int previousSecondCoordinate);
            Vector2Int secondCoordinate = clickedBlock.Coordinate;
            bool isValid = TryValidateUndergroundPipePair(
                firstCoordinate,
                secondCoordinate,
                pendingPreview,
                out Block firstBlock,
                out Block secondBlock);
            ConfigureUndergroundPipePreviewCandidate(
                pendingPreview,
                firstCoordinate,
                secondCoordinate,
                firstBlock,
                secondBlock,
                isValid,
                isValid);
            if (isValid)
            {
                SetInstallPreviewQuarterTurns(
                    pendingPreview,
                    ResolveUndergroundPipeQuarterTurns(firstCoordinate, secondCoordinate));
                InvalidateInstallGrid();
            }

            RefreshUndergroundPipeBlueprintTopology(
                pendingPreview,
                hadPreviousCandidate,
                previousFirstCoordinate,
                previousSecondCoordinate);

            return;
        }

        if (TryGetInstallPreviewAtBlock(clickedBlock, out MapObject clickedPreview)
            && clickedPreview is UndergroundPipe)
        {
            RemoveInstallPreview(clickedPreview);
            return;
        }

        if (!CanCreateAdditionalPreview()
            || !TryCreateAndPlaceInstallPreview(clickedBlock, null))
        {
            return;
        }

        if (activeInstallPreview is UndergroundPipe createdPreview)
        {
            createdPreview.ClearPreviewPair();
            installPreviewAnchorCoordinates[createdPreview] = clickedBlock.Coordinate;
            createdPreview.transform.position = clickedBlock.transform.position;
            InvalidateInstallGrid();
        }
    }

    private void UpdateUndergroundPipeCandidatePreview()
    {
        if (activeInstallationEditSession != null
            && activeInstallationEditSession.editsUndergroundPipeEndpoint)
        {
            return;
        }

        if (!(activeInstallPreview is UndergroundPipe preview)
            || preview.IsPreviewPairCommitted
            || !TryGetPreviewAnchorCoordinate(preview, out Vector2Int firstCoordinate))
        {
            return;
        }

        Vector2 pointerPosition = Input.touchCount > 0
            ? Input.GetTouch(0).position
            : (Vector2)Input.mousePosition;
        if (IsPointerOverBlockingUi(pointerPosition)
            || !TryGetPointerBlock(pointerPosition, out Block pointerBlock)
            || pointerBlock == null)
        {
            return;
        }

        Vector2Int secondCoordinate = pointerBlock.Coordinate;
        bool hadPreviousCandidate = preview.TryGetPreviewCandidateCoordinates(
            out Vector2Int previousFirstCoordinate,
            out Vector2Int previousSecondCoordinate);
        bool previousCandidateWasValid = preview.HasValidPreviewCandidate;
        bool isValid = TryValidateUndergroundPipePair(
            firstCoordinate,
            secondCoordinate,
            preview,
            out Block firstBlock,
            out Block secondBlock);
        ConfigureUndergroundPipePreviewCandidate(
            preview,
            firstCoordinate,
            secondCoordinate,
            firstBlock,
            secondBlock,
            isValid,
            false);
        if (!hadPreviousCandidate
            || previousFirstCoordinate != firstCoordinate
            || previousSecondCoordinate != secondCoordinate
            || previousCandidateWasValid != isValid)
        {
            RefreshUndergroundPipeBlueprintTopology(
                preview,
                hadPreviousCandidate,
                previousFirstCoordinate,
                previousSecondCoordinate);
        }
    }

    private void RefreshUndergroundPipeBlueprintTopology(
        UndergroundPipe preview,
        bool hadPreviousCandidate,
        Vector2Int previousFirstCoordinate,
        Vector2Int previousSecondCoordinate)
    {
        undergroundPipeBlueprintRefreshCoordinatesScratch.Clear();
        if (hadPreviousCandidate)
        {
            AddUndergroundPipeEndpointRefreshCoordinates(
                undergroundPipeBlueprintRefreshCoordinatesScratch,
                previousFirstCoordinate,
                previousSecondCoordinate);
        }

        if (preview != null
            && preview.TryGetPreviewCandidateCoordinates(
                out Vector2Int firstCoordinate,
                out Vector2Int secondCoordinate))
        {
            AddUndergroundPipeEndpointRefreshCoordinates(
                undergroundPipeBlueprintRefreshCoordinatesScratch,
                firstCoordinate,
                secondCoordinate);
        }

        RefreshPipeBlueprintTopology(undergroundPipeBlueprintRefreshCoordinatesScratch);
        RefreshFluidTankBlueprintPipeVisuals();
        undergroundPipeBlueprintRefreshCoordinatesScratch.Clear();
    }

    private static void ConfigureUndergroundPipePreviewCandidate(
        UndergroundPipe preview,
        Vector2Int firstCoordinate,
        Vector2Int secondCoordinate,
        Block firstBlock,
        Block secondBlock,
        bool isValid,
        bool commitPair)
    {
        if (preview == null)
        {
            return;
        }

        float fallbackY = preview.transform.position.y;
        Vector3 firstWorldPosition = firstBlock != null
            ? firstBlock.transform.position
            : new Vector3(firstCoordinate.x, fallbackY, firstCoordinate.y);
        Vector3 secondWorldPosition = secondBlock != null
            ? secondBlock.transform.position
            : new Vector3(secondCoordinate.x, fallbackY, secondCoordinate.y);
        preview.ConfigurePreviewPair(
            firstCoordinate,
            secondCoordinate,
            firstWorldPosition,
            secondWorldPosition,
            isValid,
            commitPair);
    }

    private bool HasIncompleteUndergroundPipePreview()
    {
        CleanupInstallPreviewReferences();
        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            if (installPreviewInstances[i] is UndergroundPipe undergroundPipe
                && !undergroundPipe.IsPreviewPairCommitted)
            {
                return true;
            }
        }

        return false;
    }

    private static bool IsUndergroundPipeInstallDefinition(ItemDefinition definition)
    {
        return definition != null && definition.mapObject is UndergroundPipe;
    }

    private int NormalizeInstallPreviewQuarterTurns(MapObject preview, int quarterTurns)
    {
        int normalizedQuarterTurns = NormalizePlacementQuarterTurns(quarterTurns);
        return GetInstallPreviewUserRotationFilter(preview) switch
        {
            InstallationRotationFilter.Fixed => 0,
            InstallationRotationFilter.HorizontalAndVertical => normalizedQuarterTurns % 2,
            _ => normalizedQuarterTurns
        };
    }

    private InstallationRotationFilter GetInstallPreviewUserRotationFilter(MapObject preview)
    {
        // Player input follows the item/straight prefab; topology variants use their
        // own filter through GetPlacementRotationFilter when connections are resolved.
        if (activeInstallDefinition != null
            && activeInstallDefinition.mapObject is InstallationObject definitionInstallation)
        {
            return definitionInstallation.RotationFilter;
        }

        MapObject rotationSource = ResolveInstallPreviewRotationSource(preview);
        InstallationObject userRotationSource = rotationSource switch
        {
            Wall wall => wall.StraightVariantPrefab,
            Pipe pipe => pipe.StraightVariantPrefab,
            ConveyorBelt conveyorBelt => conveyorBelt.StraightVariantPrefab,
            InstallationObject installationObject => installationObject,
            _ => null
        };
        return userRotationSource != null
            ? userRotationSource.RotationFilter
            : InstallationRotationFilter.All;
    }

    private void RememberLastBlueprintRotation(ItemDefinition definition, int quarterTurns)
    {
        int normalizedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            definition != null ? definition.mapObject : null,
            quarterTurns);
        lastBlueprintQuarterTurns = normalizedQuarterTurns;
        hasLastBlueprintQuarterTurns = true;

        if (definition != null && definition.id >= 0)
        {
            lastBlueprintQuarterTurnsByItemId[definition.id] = normalizedQuarterTurns;
        }
    }

    private void RememberBlueprintRotationForPreview(ItemDefinition definition, MapObject preview, int quarterTurns)
    {
        int normalizedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            preview != null ? preview : definition != null ? definition.mapObject : null,
            quarterTurns);
        if (IsFenceDoorDefinition(definition))
        {
            if (preview is FenceDoor)
            {
                if (TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate)
                    && HasFenceNeighborConnections(anchorCoordinate, preview, true))
                {
                    return;
                }

                installPreviewFenceDoorStandaloneQuarterTurnsByPreview[preview] = normalizedQuarterTurns;
            }
        }

        RememberLastBlueprintRotation(definition, normalizedQuarterTurns);
    }

    private bool HasFenceNeighborConnections(
        Vector2Int anchorCoordinate,
        MapObject previewToIgnore,
        bool allowPotentialConnections)
    {
        List<Vector2Int> neighborDirections = GetFenceNeighborConnectionDirections(
            anchorCoordinate,
            previewToIgnore,
            allowPotentialConnections);
        return CountFenceNeighborDirections(neighborDirections) > 0;
    }

    private void RememberLastInstalledRotation(ItemDefinition definition, int quarterTurns)
    {
        int normalizedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            definition != null ? definition.mapObject : null,
            quarterTurns);
        lastInstalledQuarterTurns = normalizedQuarterTurns;
        hasLastInstalledQuarterTurns = true;

        if (definition != null && definition.id >= 0)
        {
            lastInstalledQuarterTurnsByItemId[definition.id] = normalizedQuarterTurns;
        }
    }

    private int GetPreferredInstallPreviewQuarterTurns(ItemDefinition definition, MapObject sourcePreview)
    {
        if (sourcePreview != null)
        {
            return GetPreviewQuarterTurns(sourcePreview);
        }

        if (TryGetRememberedBlueprintRotation(definition, out int blueprintQuarterTurns))
        {
            return blueprintQuarterTurns;
        }

        if (activeInstallPreview != null && installPreviewInstances.Contains(activeInstallPreview))
        {
            return GetPreviewQuarterTurns(activeInstallPreview);
        }

        return TryGetRememberedInstallRotation(definition, out int rememberedQuarterTurns)
            ? rememberedQuarterTurns
            : 0;
    }

    private int GetPreferredFenceDoorStandaloneQuarterTurns(ItemDefinition definition, MapObject sourcePreview)
    {
        if (sourcePreview != null)
        {
            return GetFenceDoorStandaloneQuarterTurns(sourcePreview, GetPreviewQuarterTurns(sourcePreview));
        }

        if (definition != null
            && definition.id >= 0
            && lastBlueprintQuarterTurnsByItemId.TryGetValue(definition.id, out int blueprintQuarterTurns))
        {
            return NormalizePlacementQuarterTurnsForObject(definition.mapObject, blueprintQuarterTurns);
        }

        if (definition != null
            && definition.id >= 0
            && lastInstalledQuarterTurnsByItemId.TryGetValue(definition.id, out int installedQuarterTurns))
        {
            return NormalizePlacementQuarterTurnsForObject(definition.mapObject, installedQuarterTurns);
        }

        return 0;
    }

    private static bool IsFenceDoorDefinition(ItemDefinition definition)
    {
        return definition != null && definition.mapObject is FenceDoor;
    }

    private bool HasRememberedInstallRotation(ItemDefinition definition)
    {
        return TryGetRememberedInstallRotation(definition, out _);
    }

    private bool HasRememberedBlueprintRotation(ItemDefinition definition)
    {
        return TryGetRememberedBlueprintRotation(definition, out _);
    }

    private bool TryGetRememberedBlueprintRotation(ItemDefinition definition, out int quarterTurns)
    {
        quarterTurns = 0;
        if (definition != null
            && definition.id >= 0
            && lastBlueprintQuarterTurnsByItemId.TryGetValue(definition.id, out int itemQuarterTurns))
        {
            quarterTurns = NormalizePlacementQuarterTurnsForObject(definition.mapObject, itemQuarterTurns);
            return true;
        }

        if (!hasLastBlueprintQuarterTurns)
        {
            return false;
        }

        quarterTurns = NormalizePlacementQuarterTurnsForObject(definition != null ? definition.mapObject : null, lastBlueprintQuarterTurns);
        return true;
    }

    private bool TryGetRememberedInstallRotation(ItemDefinition definition, out int quarterTurns)
    {
        quarterTurns = 0;
        if (definition != null
            && definition.id >= 0
            && lastInstalledQuarterTurnsByItemId.TryGetValue(definition.id, out int itemQuarterTurns))
        {
            quarterTurns = NormalizePlacementQuarterTurnsForObject(definition.mapObject, itemQuarterTurns);
            return true;
        }

        if (!hasLastInstalledQuarterTurns)
        {
            return false;
        }

        quarterTurns = NormalizePlacementQuarterTurnsForObject(definition != null ? definition.mapObject : null, lastInstalledQuarterTurns);
        return true;
    }

    private bool TryResolvePlacementQuarterTurnsFromRotation(MapObject sourcePrefab, Quaternion worldRotation, out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = 0;
        if (sourcePrefab == null)
        {
            return false;
        }

        if (UsesTwoStatePlacementRotation(sourcePrefab))
        {
            resolvedQuarterTurns = ResolveTwoStateQuarterTurnsFromRotation(
                sourcePrefab,
                worldRotation,
                resolvedQuarterTurns);
            return true;
        }

        int candidateCount = GetPlacementRotationCandidateCount(sourcePrefab);
        int bestQuarterTurns = -1;
        float bestDot = -1f;
        for (int candidateQuarterTurns = 0; candidateQuarterTurns < candidateCount; candidateQuarterTurns++)
        {
            Quaternion candidateRotation = GetPlacementObjectRotation(sourcePrefab, candidateQuarterTurns);
            float dot = Mathf.Abs(Quaternion.Dot(candidateRotation, worldRotation));
            if (dot >= PlacementRotationExactDotThreshold)
            {
                resolvedQuarterTurns = candidateQuarterTurns;
                return true;
            }

            if (dot > bestDot)
            {
                bestDot = dot;
                bestQuarterTurns = candidateQuarterTurns;
            }
        }

        if (bestQuarterTurns >= 0 && bestDot >= PlacementRotationNearestDotThreshold)
        {
            resolvedQuarterTurns = bestQuarterTurns;
            return true;
        }

        return false;
    }

    private bool CanCreateAdditionalPreview()
    {
        if (IsEditingInstallation())
        {
            return false;
        }

        int itemId = activeInstallDefinition != null ? activeInstallDefinition.id : -1;
        int availableItemCount = GetAvailableInstallItemCount(itemId);
        return GetInstallPreviewCount() < availableItemCount;
    }

    public int GetAvailableInstallItemCount(int itemId = -1)
    {
        if (IsEditingInstallation())
        {
            return 1;
        }

        if (itemId < 0 && activeInstallDefinition != null)
        {
            itemId = activeInstallDefinition.id;
        }

        return GetCurrentInstallItemCount() + GetReservedInstallPreviewItemCount(itemId);
    }

    private int GetCurrentInstallItemCount()
    {
        if (IsEditingInstallation())
        {
            return 1;
        }

        int itemId = activeInstallDefinition != null ? activeInstallDefinition.id : -1;
        PlayerBag handBag = GetPlayerHandBag();
        if (itemId < 0 && handBag != null)
        {
            itemId = handBag.GetSlotItemId(0);
        }

        if (itemId < 0)
        {
            return 0;
        }

        int totalCount = 0;
        if (handBag != null && handBag.GetSlotItemId(0) == itemId)
        {
            totalCount += handBag.GetSlotCount(0);
        }

        PlayerBag inventoryBag = GetPlayerInventoryBag();
        if (inventoryBag != null && inventoryBag != handBag)
        {
            totalCount += inventoryBag.GetTotalItemCount(itemId);
        }

        return totalCount;
    }

    public int RemoveInstallItemsFromPlayer(int itemId, int requestedCount)
    {
        if (itemId < 0 || requestedCount <= 0)
        {
            return 0;
        }

        int removedCount = 0;
        Player player = GameManager.Instance != null ? GameManager.Instance.Player : null;
        PlayerBag handBag = player != null ? player.GetHandBag() : GetPlayerHandBag();
        PlayerBag inventoryBag = player != null ? player.GetBag() : GetPlayerInventoryBag();
        if (inventoryBag != null && inventoryBag != handBag)
        {
            removedCount += inventoryBag.RemoveItems(itemId, requestedCount);
        }

        int remainingCount = requestedCount - removedCount;
        if (remainingCount > 0 && handBag != null)
        {
            removedCount += handBag.RemoveItems(itemId, remainingCount);
            handBag.RefreshExternalStackCounts();
        }

        player?.UpdateCarryState();
        return removedCount;
    }

    public int RefundInstallItemsToPlayer(int itemId, int requestedCount)
    {
        if (itemId < 0 || requestedCount <= 0)
        {
            return 0;
        }

        int refundedCount = 0;
        Player player = GameManager.Instance != null ? GameManager.Instance.Player : null;
        PlayerBag handBag = player != null ? player.GetHandBag() : GetPlayerHandBag();
        PlayerBag inventoryBag = player != null ? player.GetBag() : GetPlayerInventoryBag();
        for (int i = 0; i < requestedCount; i++)
        {
            if (inventoryBag != null
                && inventoryBag != handBag
                && inventoryBag.TryAddObject(itemId, out _))
            {
                refundedCount++;
                continue;
            }

            if (player != null && player.TryAddToHand(itemId, out _))
            {
                refundedCount++;
                continue;
            }

            if (handBag != null && handBag.TryAddObject(0, itemId, out _))
            {
                refundedCount++;
                continue;
            }

            if (inventoryBag != null && inventoryBag.TryAddObject(itemId, out _))
            {
                refundedCount++;
                continue;
            }

            break;
        }

        RefreshPlayerHandInstallItemState(player, handBag);
        return refundedCount;
    }

    private void RefreshPlayerHandInstallItemState(Player player = null, PlayerBag handBag = null)
    {
        if (player == null)
        {
            player = GameManager.Instance != null ? GameManager.Instance.Player : null;
        }

        if (handBag == null)
        {
            handBag = player != null ? player.GetHandBag() : GetPlayerHandBag();
        }

        if (handBag != null)
        {
            handBag.RefreshExternalStackCounts(false);
        }

        if (player != null)
        {
            player.UpdateCarryState();
        }
    }

    private int GetInstallPreviewCount()
    {
        CleanupInstallPreviewReferences();
        return installPreviewInstances.Count;
    }

    private void RegisterInstallPreview(MapObject preview, int quarterTurns)
    {
        if (preview == null)
        {
            return;
        }

        InvalidateInstallPreviewMoveCache();
        CleanupInstallPreviewReferences();
        if (!installPreviewInstances.Contains(preview))
        {
            installPreviewInstances.Add(preview);
        }

        MapObject rotationSource = ResolveInstallPreviewRotationSource(preview);
        int normalizedQuarterTurns = NormalizePlacementQuarterTurnsForObject(rotationSource, quarterTurns);
        installPreviewQuarterTurnsByPreview[preview] = normalizedQuarterTurns;
        if (preview is FenceDoor)
        {
            installPreviewFenceDoorStandaloneQuarterTurnsByPreview[preview] = normalizedQuarterTurns;
        }

        installPreviewBaseRotationsByPreview[preview] = rotationSource != null
            ? rotationSource.transform.rotation
            : preview.transform.rotation;
        if (!installPreviewPlacementSequencesByPreview.ContainsKey(preview))
        {
            installPreviewPlacementSequencesByPreview[preview] = InstallationObject.ClaimNextPlacementSequence();
        }
        installPreviewConveyorVariantMode = GetConveyorPreviewVariantMode(preview);
    }

    private void CleanupInstallPreviewReferences()
    {
        if (installGridValidationInProgress)
        {
            return;
        }

        for (int i = installPreviewInstances.Count - 1; i >= 0; i--)
        {
            if (installPreviewInstances[i] != null)
            {
                continue;
            }

            installPreviewInstances.RemoveAt(i);
        }

        RemoveMissingPreviewKeys(installPreviewQuarterTurnsByPreview);
        RemoveMissingPreviewKeys(installPreviewAnchorCoordinates);
        RemoveMissingPreviewKeys(installPreviewFenceDoorStandaloneQuarterTurnsByPreview);
        RemoveMissingPreviewKeys(installPreviewBaseRotationsByPreview);
        RemoveMissingPreviewKeys(installPreviewSourcePrefabsByPreview);
        RemoveMissingPreviewKeys(installPreviewRailReferenceWorldPositions);
        RemoveMissingPreviewKeys(installPreviewPlacementSequencesByPreview);
        RemoveMissingPreviewKeys(installPreviewConveyorRotationSequenceIndexesByPreview);
        RemoveMissingPreviewKeys(installPreviewPipeConnectionMasksByPreview);
        RemoveMissingPreviewKeys(installPreviewPipeSelectedSetDirectionsByPreview);
        RemoveMissingPreviewKeys(installPreviewFreightCarBoxTargets);
        RemoveMissingPreviewKeys(installPreviewFreightCarBoxPoints);
        RemoveMissingPreviewKeys(trainConnectionPreviewTints);
        RemoveMissingPreviewItemReservations();
        RemoveMissingStraightFirstConveyorPreviews();

        CleanupInstalledFenceVariantPreviewReferences();
    }

    private void RemoveMissingPreviewKeys<TValue>(Dictionary<MapObject, TValue> dictionary)
    {
        if (dictionary == null || dictionary.Count <= 0)
        {
            return;
        }

        cleanupMapObjectScratch.Clear();
        foreach (KeyValuePair<MapObject, TValue> entry in dictionary)
        {
            if (entry.Key == null)
            {
                cleanupMapObjectScratch.Add(entry.Key);
            }
        }

        for (int i = 0; i < cleanupMapObjectScratch.Count; i++)
        {
            dictionary.Remove(cleanupMapObjectScratch[i]);
        }

        cleanupMapObjectScratch.Clear();
    }

    private void RemoveMissingStraightFirstConveyorPreviews()
    {
        if (straightFirstConveyorPreviews.Count <= 0)
        {
            return;
        }

        cleanupMapObjectScratch.Clear();
        foreach (MapObject preview in straightFirstConveyorPreviews)
        {
            if (preview == null || !installPreviewInstances.Contains(preview))
            {
                cleanupMapObjectScratch.Add(preview);
            }
        }

        for (int i = 0; i < cleanupMapObjectScratch.Count; i++)
        {
            straightFirstConveyorPreviews.Remove(cleanupMapObjectScratch[i]);
        }

        cleanupMapObjectScratch.Clear();
    }

    private void RemoveMissingPreviewItemReservations()
    {
        if (installPreviewItemReservationsByPreview.Count <= 0)
        {
            return;
        }

        cleanupMapObjectScratch.Clear();
        foreach (KeyValuePair<MapObject, InstallPreviewItemReservation> entry in installPreviewItemReservationsByPreview)
        {
            if (entry.Key != null)
            {
                continue;
            }

            RefundInstallPreviewReservation(entry.Value);
            cleanupMapObjectScratch.Add(entry.Key);
        }

        for (int i = 0; i < cleanupMapObjectScratch.Count; i++)
        {
            installPreviewItemReservationsByPreview.Remove(cleanupMapObjectScratch[i]);
        }

        cleanupMapObjectScratch.Clear();
    }

    private bool TryCreateAndPlaceFreightCarBoxPreview(FreightCar freightCar, Transform boxPoint)
    {
        if (freightCar == null
            || boxPoint == null
            || activeInstallDefinition == null
            || !IsFreightCarLoadInstallDefinition(activeInstallDefinition)
            || !CanFreightCarAcceptLoadPreview(freightCar, activeInstallDefinition.mapObject)
            || !CanCreateAdditionalPreview()
            || !freightCar.IsBoxPointAvailable(boxPoint)
            || IsFreightCarBoxPointReservedByPreview(freightCar, boxPoint, null))
        {
            return false;
        }

        if (!TryReserveInstallPreviewItem(activeInstallDefinition, out InstallPreviewItemReservation reservation))
        {
            return false;
        }

        MapObject preview = CreateInstallPreviewInstance(activeInstallDefinition);
        if (preview == null)
        {
            RefundInstallPreviewReservation(reservation);
            return false;
        }

        installPreviewItemReservationsByPreview[preview] = reservation;
        RegisterInstallPreview(preview, 0);
        if (!ApplyFreightCarBoxPreviewPlacement(preview, freightCar, boxPoint))
        {
            RemoveInstallPreview(preview);
            return false;
        }

        SelectInstallPreview(preview);
        return true;
    }

    private bool TryMoveActiveFreightCarLoadPreview(Vector2 pointerPosition)
    {
        if (activeInstallPreview == null
            || !IsFreightCarLoadInstallDefinition(activeInstallDefinition))
        {
            return false;
        }

        if (!TryGetPointerFreightCar(pointerPosition, out _, out _))
        {
            return false;
        }

        if (TryResolveFreightCarBoxInstallTarget(
                pointerPosition,
                activeInstallPreview,
                out FreightCar freightCar,
                out Transform boxPoint))
        {
            return ApplyFreightCarBoxPreviewPlacement(activeInstallPreview, freightCar, boxPoint);
        }

        return true;
    }

    private bool ApplyFreightCarBoxPreviewPlacement(MapObject preview, FreightCar freightCar, Transform boxPoint)
    {
        if (preview == null
            || freightCar == null
            || boxPoint == null
            || !CanFreightCarAcceptLoadPreview(freightCar, preview)
            || !freightCar.IsBoxPointAvailable(boxPoint)
            || IsFreightCarBoxPointReservedByPreview(freightCar, boxPoint, preview))
        {
            return false;
        }

        installPreviewFreightCarBoxTargets[preview] = freightCar;
        installPreviewFreightCarBoxPoints[preview] = boxPoint;
        SetInstallPreviewQuarterTurns(preview, 0);

        Vector2Int anchorCoordinate = freightCar.TryGetPlacementRuntime(out Vector2Int carAnchorCoordinate, out _)
            ? carAnchorCoordinate
            : RoundWorldPositionToCoordinate(boxPoint.position);
        installPreviewAnchorCoordinates[preview] = anchorCoordinate;

        ApplyFreightCarLoadPreviewPresentation(preview, true);
        preview.transform.SetPositionAndRotation(
            GetFreightCarLoadPreviewWorldPosition(preview, boxPoint),
            boxPoint.rotation);
        if (preview is InstallationObject installationPreview)
        {
            installationPreview.RefreshInstalledDirectionFromCurrentTransform();
        }

        RememberBlueprintRotationForPreview(activeInstallDefinition, preview, 0);
        InvalidateInstallGridPreview();
        return true;
    }

    private bool SnapFreightCarBoxPreviewToTarget(MapObject preview)
    {
        if (preview == null
            || !installPreviewFreightCarBoxTargets.TryGetValue(preview, out FreightCar freightCar)
            || freightCar == null
            || !installPreviewFreightCarBoxPoints.TryGetValue(preview, out Transform boxPoint)
            || boxPoint == null)
        {
            return false;
        }

        Vector2Int anchorCoordinate = freightCar.TryGetPlacementRuntime(out Vector2Int carAnchorCoordinate, out _)
            ? carAnchorCoordinate
            : RoundWorldPositionToCoordinate(boxPoint.position);
        installPreviewAnchorCoordinates[preview] = anchorCoordinate;
        ApplyFreightCarLoadPreviewPresentation(preview, true);
        preview.transform.SetPositionAndRotation(
            GetFreightCarLoadPreviewWorldPosition(preview, boxPoint),
            boxPoint.rotation);
        return true;
    }

    private static Vector3 GetFreightCarLoadPreviewWorldPosition(
        MapObject preview,
        Transform boxPoint)
    {
        if (boxPoint == null)
        {
            return preview != null ? preview.transform.position : Vector3.zero;
        }

        if (TryResolveFreightCarLoadObject(preview, out InstallationObject loadObject)
            && loadObject is Fluidtank fluidTank)
        {
            return boxPoint.TransformPoint(fluidTank.FlatCarMountedLocalPosition);
        }

        return boxPoint.position;
    }

    private static void ApplyFreightCarLoadPreviewPresentation(MapObject preview, bool mounted)
    {
        if (TryResolveFreightCarLoadObject(preview, out InstallationObject loadObject)
            && loadObject is Fluidtank fluidTank)
        {
            fluidTank.SetFlatCarMountedPresentation(mounted);
        }
    }

    private bool TryResolveFreightCarBoxInstallTarget(
        Vector2 pointerPosition,
        MapObject previewToIgnore,
        out FreightCar freightCar,
        out Transform boxPoint)
    {
        freightCar = null;
        boxPoint = null;
        if (!IsFreightCarLoadInstallDefinition(activeInstallDefinition)
            || !TryGetPointerFreightCar(pointerPosition, out freightCar, out Vector3 referenceWorldPosition)
            || freightCar == null
            || !CanFreightCarAcceptLoadPreview(freightCar, activeInstallDefinition.mapObject))
        {
            return false;
        }

        FreightCar targetFreightCar = freightCar;
        return targetFreightCar.TryGetBestAvailableBoxPoint(
            referenceWorldPosition,
            point => !IsFreightCarBoxPointReservedByPreview(targetFreightCar, point, previewToIgnore),
            out boxPoint);
    }

    private bool TryGetPointerFreightCar(
        Vector2 pointerPosition,
        out FreightCar freightCar,
        out Vector3 hitWorldPosition)
    {
        freightCar = null;
        hitWorldPosition = Vector3.zero;

        Camera targetCamera = ResolveInstallPreviewCamera();
        if (targetCamera == null)
        {
            return false;
        }

        Ray ray = targetCamera.ScreenPointToRay(pointerPosition);
        int hitCount = Physics.RaycastNonAlloc(
            ray,
            pointerRaycastHits,
            512f,
            Physics.DefaultRaycastLayers,
            QueryTriggerInteraction.Ignore);
        if (hitCount <= 0)
        {
            return false;
        }

        float nearestDistance = float.PositiveInfinity;
        for (int i = 0; i < hitCount; i++)
        {
            RaycastHit hit = pointerRaycastHits[i];
            if (hit.collider == null)
            {
                continue;
            }

            MapObject hitMapObject = hit.collider.GetComponentInParent<MapObject>();
            if (hitMapObject != null && installPreviewInstances.Contains(hitMapObject))
            {
                continue;
            }

            FreightCar candidateFreightCar = hit.collider.GetComponentInParent<FreightCar>();
            if (candidateFreightCar == null
                || !candidateFreightCar.gameObject.activeInHierarchy
                || hit.distance >= nearestDistance)
            {
                continue;
            }

            nearestDistance = hit.distance;
            freightCar = candidateFreightCar;
            hitWorldPosition = hit.point;
        }

        return freightCar != null;
    }

    private bool TryGetFreightCarBoxPreviewAtTarget(
        FreightCar freightCar,
        Transform boxPoint,
        out MapObject preview)
    {
        preview = null;
        if (freightCar == null || boxPoint == null || installPreviewFreightCarBoxTargets.Count <= 0)
        {
            return false;
        }

        foreach (KeyValuePair<MapObject, FreightCar> entry in installPreviewFreightCarBoxTargets)
        {
            MapObject candidatePreview = entry.Key;
            if (candidatePreview == null
                || entry.Value != freightCar
                || !installPreviewFreightCarBoxPoints.TryGetValue(candidatePreview, out Transform candidatePoint)
                || candidatePoint != boxPoint)
            {
                continue;
            }

            preview = candidatePreview;
            return true;
        }

        return false;
    }

    private bool IsFreightCarBoxPointReservedByPreview(
        FreightCar freightCar,
        Transform boxPoint,
        MapObject previewToIgnore)
    {
        if (freightCar == null || boxPoint == null || installPreviewFreightCarBoxTargets.Count <= 0)
        {
            return false;
        }

        foreach (KeyValuePair<MapObject, FreightCar> entry in installPreviewFreightCarBoxTargets)
        {
            MapObject preview = entry.Key;
            if (preview == null
                || preview == previewToIgnore
                || entry.Value != freightCar
                || !installPreviewFreightCarBoxPoints.TryGetValue(preview, out Transform reservedPoint)
                || reservedPoint != boxPoint)
            {
                continue;
            }

            return true;
        }

        return false;
    }

    private void ClearFreightCarBoxPreviewTarget(MapObject preview)
    {
        if (preview == null)
        {
            return;
        }

        if (installPreviewFreightCarBoxTargets.ContainsKey(preview))
        {
            ApplyFreightCarLoadPreviewPresentation(preview, false);
        }

        installPreviewFreightCarBoxTargets.Remove(preview);
        installPreviewFreightCarBoxPoints.Remove(preview);
    }

    private static bool IsBoxObjectInstallDefinition(ItemDefinition definition)
    {
        return definition != null && TryResolveBoxObject(definition.mapObject, out _);
    }

    private static bool IsFreightCarLoadInstallDefinition(ItemDefinition definition)
    {
        return definition != null
               && TryResolveFreightCarLoadObject(definition.mapObject, out _);
    }

    private static bool TryResolveFreightCarLoadObject(
        MapObject mapObject,
        out InstallationObject loadObject)
    {
        loadObject = null;
        if (TryResolveBoxObject(mapObject, out BoxObject boxObject))
        {
            loadObject = boxObject;
            return true;
        }

        if (mapObject == null)
        {
            return false;
        }

        Fluidtank fluidTank = mapObject as Fluidtank;
        if (fluidTank == null)
        {
            mapObject.TryGetComponent(out fluidTank);
        }

        if (fluidTank == null)
        {
            fluidTank = mapObject.GetComponentInChildren<Fluidtank>(true);
        }

        loadObject = fluidTank;
        return loadObject != null;
    }

    private static bool CanFreightCarAcceptLoadPreview(FreightCar freightCar, MapObject loadPreview)
    {
        return freightCar != null
               && TryResolveFreightCarLoadObject(loadPreview, out InstallationObject loadObject)
               && freightCar.CanAttachLoadObject(loadObject);
    }

    private static bool TryResolveBoxObject(MapObject mapObject, out BoxObject boxObject)
    {
        boxObject = null;
        if (mapObject == null)
        {
            return false;
        }

        boxObject = mapObject as BoxObject;
        if (boxObject != null)
        {
            return true;
        }

        if (mapObject.TryGetComponent(out boxObject) && boxObject != null)
        {
            return true;
        }

        boxObject = mapObject.GetComponentInChildren<BoxObject>(true);
        return boxObject != null;
    }

    private bool TryCreateAndPlaceInstallPreview(
        Block block,
        MapObject sourcePreview,
        Vector3? railReferenceWorldPosition = null)
    {
        if (block == null || activeInstallDefinition == null || !CanCreateAdditionalPreview())
        {
            return false;
        }

        int quarterTurns = IsFenceDoorDefinition(activeInstallDefinition)
            ? GetPreferredFenceDoorStandaloneQuarterTurns(activeInstallDefinition, sourcePreview)
            : GetPreferredInstallPreviewQuarterTurns(activeInstallDefinition, sourcePreview);
        if (sourcePreview == null && activeInstallDefinition.mapObject is ConveyorBelt conveyorPrototype)
        {
            if (!HasRememberedBlueprintRotation(activeInstallDefinition)
                && !HasRememberedInstallRotation(activeInstallDefinition)
                && activeInstallPreview == null)
            {
                TryResolveInitialConveyorPreviewQuarterTurns(block.Coordinate, conveyorPrototype, out quarterTurns);
            }
        }

        Block anchorBlock;
        bool resolvedTarget;
        if (IsTrainSource(activeInstallDefinition.mapObject))
        {
            resolvedTarget = TryResolveTrainInstallPreviewTarget(
                block,
                activeInstallDefinition.mapObject,
                quarterTurns,
                railReferenceWorldPosition,
                out anchorBlock,
                out quarterTurns);
        }
        else
        {
            resolvedTarget = TryResolvePlaceableInstallPreviewTarget(
                block,
                sourcePreview,
                quarterTurns,
                sourcePreview != null,
                out anchorBlock,
                out quarterTurns);
        }

        if (!resolvedTarget)
        {
            return false;
        }

        if (!TryReserveInstallPreviewItem(activeInstallDefinition, out InstallPreviewItemReservation reservation))
        {
            return false;
        }

        MapObject preview = CreateInstallPreviewInstance(activeInstallDefinition);
        if (preview == null)
        {
            RefundInstallPreviewReservation(reservation);
            return false;
        }

        installPreviewItemReservationsByPreview[preview] = reservation;
        RegisterInstallPreview(preview, quarterTurns);
        if (sourcePreview == null
            && activeInstallDefinition.mapObject is ConveyorBelt
            && !IsBelt2F(activeInstallDefinition.mapObject))
        {
            straightFirstConveyorPreviews.Add(preview);
        }

        // 새 프리뷰의 풋프린트는 전용 오버레이에서 바로 그린다. 설치 가능 배경 그리드는
        // 아이템 종류와 방향이 바뀌지 않았으므로 전체 맵을 다시 검사할 필요가 없다.
        SelectInstallPreview(preview, true, false);
        if (sourcePreview != null)
        {
            installPreviewConveyorVariantMode = GetConveyorPreviewVariantMode(sourcePreview);
            if (sourcePreview is ConveyorBelt)
            {
                MapObject sourcePrefab = ResolveInstallPreviewFootprintSource(sourcePreview);
                if (sourcePrefab != null)
                {
                    installPreviewSourcePrefabsByPreview[preview] = sourcePrefab;
                }
            }

            RefreshActiveConveyorPreviewVariant();
        }

        if (sourcePreview != null)
        {
            bool placed = ApplyResolvedInstallPreviewPlacement(anchorBlock, quarterTurns);
            if (placed && sourcePreview is ConveyorBelt)
            {
                straightFirstConveyorPreviews.Remove(sourcePreview);
                if (TryGetPreviewAnchorCoordinate(sourcePreview, out Vector2Int sourceAnchorCoordinate))
                {
                    RefreshSingleConveyorPreviewVariant(
                        sourcePreview,
                        sourceAnchorCoordinate,
                        activeInstallPreview);
                    RefreshAllInstallPreviewConveyorEndpointVisuals();
                }
            }

            return placed;
        }

        Block initialPreviewBlock = IsBelt2F(activeInstallDefinition.mapObject) ? block : anchorBlock;
        if (MoveInstallPreviewToBlock(initialPreviewBlock, false, railReferenceWorldPosition))
        {
            return true;
        }

        RemoveInstallPreview(preview);
        return false;
    }

    private bool ApplyResolvedInstallPreviewPlacement(Block anchorBlock, int resolvedQuarterTurns)
    {
        if (activeInstallPreview == null || anchorBlock == null)
        {
            return false;
        }

        MapObject placementSource = ResolveInstallPreviewPlacementSource(activeInstallPreview) ?? activeInstallPreview;
        if (TryResolveTrainStationFacingQuarterTurns(
                anchorBlock.Coordinate,
                placementSource,
                activeInstallPreview,
                resolvedQuarterTurns,
                out int trainStationQuarterTurns))
        {
            resolvedQuarterTurns = trainStationQuarterTurns;
        }

        installPreviewQuarterTurns = NormalizePlacementQuarterTurnsForObject(placementSource, resolvedQuarterTurns);
        installPreviewQuarterTurnsByPreview[activeInstallPreview] = installPreviewQuarterTurns;
        installPreviewAnchorCoordinates[activeInstallPreview] = anchorBlock.Coordinate;

        RefreshActiveConveyorPreviewVariant();
        RefreshActiveFencePreviewVariant(true);

        Vector3 targetPosition = ResolvePlacementWorldPosition(
            anchorBlock,
            placementSource,
            installPreviewQuarterTurns);
        SetInstallPreviewRailReferenceForPlacement(
            placementSource,
            IsTrainSource(placementSource) ? targetPosition : (Vector3?)null);
        Quaternion targetRotation = GetInstallPreviewRotation();

        activeInstallPreview.transform.position = targetPosition;
        activeInstallPreview.transform.rotation = targetRotation;
        if (activeInstallPreview is InstallationObject movedInstallationPreview)
        {
            movedInstallationPreview.RefreshInstalledDirectionFromCurrentTransform();
        }

        RefreshHandcartInstallPreviewConnectionPoses();
        RefreshPreviewRangeVisualsIfNeeded(activeInstallPreview);
        RefreshUtilityPolePreviewWires();
        RefreshInstallPreviewAreaMarkers(activeInstallPreview);
        RefreshFencePreviewVariantsAroundActivePreview(null, true);
        RefreshPipePreviewVariantsAroundActivePreview(null);
        RefreshTrainInstallPreviewTints();
        RememberBlueprintRotationForPreview(activeInstallDefinition, activeInstallPreview, installPreviewQuarterTurns);
        InvalidateInstallGridPreview();
        return true;
    }

    private void RemoveInstallPreview(MapObject preview)
    {
        if (preview == null)
        {
            return;
        }

        InvalidateInstallPreviewMoveCache();
        ClearHandcartConnectionPreviewHandleOverrides();
        RefundInstallPreviewReservation(preview);

        Vector2Int removedFenceAnchorCoordinate = Vector2Int.zero;
        bool hadRemovedFenceAnchorCoordinate = preview is Wall
            && TryGetPreviewAnchorCoordinate(preview, out removedFenceAnchorCoordinate);
        Vector2Int removedPipeConnectorAnchorCoordinate = Vector2Int.zero;
        bool hadRemovedPipeConnectorAnchorCoordinate = IsPipeConnectorObject(preview)
            && TryGetPreviewAnchorCoordinate(preview, out removedPipeConnectorAnchorCoordinate);
        HashSet<Vector2Int> removedPipeConnectorRefreshCoordinates = null;
        if (hadRemovedPipeConnectorAnchorCoordinate)
        {
            removedPipeConnectorRefreshCoordinates = new HashSet<Vector2Int>();
            if (preview is UndergroundPipe undergroundPipe
                && undergroundPipe.TryGetPreviewCandidateCoordinates(
                    out Vector2Int firstEndpoint,
                    out Vector2Int secondEndpoint))
            {
                AddUndergroundPipeEndpointRefreshCoordinates(
                    removedPipeConnectorRefreshCoordinates,
                    firstEndpoint,
                    secondEndpoint);
            }
            else
            {
                MapObject footprintSource = ResolveInstallPreviewFootprintSource(preview) ?? preview;
                AddPipeConnectorVariantRefreshCoordinates(
                    removedPipeConnectorRefreshCoordinates,
                    removedPipeConnectorAnchorCoordinate,
                    footprintSource,
                    GetPreviewQuarterTurns(preview),
                    true);
            }
        }

        bool removedConveyorPreview = preview is ConveyorBelt;

        installPreviewInstances.Remove(preview);
        installPreviewQuarterTurnsByPreview.Remove(preview);
        installPreviewFenceDoorStandaloneQuarterTurnsByPreview.Remove(preview);
        installPreviewBaseRotationsByPreview.Remove(preview);
        installPreviewSourcePrefabsByPreview.Remove(preview);
        installPreviewRailReferenceWorldPositions.Remove(preview);
        installPreviewPlacementSequencesByPreview.Remove(preview);
        installPreviewConveyorRotationSequenceIndexesByPreview.Remove(preview);
        installPreviewPipeConnectionMasksByPreview.Remove(preview);
        installPreviewPipeSelectedSetDirectionsByPreview.Remove(preview);
        ClearFreightCarBoxPreviewTarget(preview);
        installPreviewAnchorCoordinates.Remove(preview);
        installPreviewItemReservationsByPreview.Remove(preview);
        straightFirstConveyorPreviews.Remove(preview);

        if (activeInstallPreview == preview)
        {
            activeInstallPreview = null;
            installPreviewQuarterTurns = 0;
        }

        DestroyInstallPreviewObject(preview);

        EnsureValidActiveInstallPreview();
        RefreshInstallOrEditWorkableRangeVisualRequest();
        RefreshActiveConveyorPreviewVariant();
        if (removedConveyorPreview)
        {
            RefreshAllInstallPreviewConveyorEndpointVisuals();
        }

        if (hadRemovedFenceAnchorCoordinate)
        {
            RefreshActiveFencePreviewVariant();
            RefreshFencePreviewVariants();
            RefreshInstalledFenceVariantPreviews();
        }
        else if (hadRemovedPipeConnectorAnchorCoordinate)
        {
            RefreshPipeBlueprintTopology(removedPipeConnectorRefreshCoordinates);
        }
        else
        {
            RefreshActiveFencePreviewVariant();
            RefreshInstalledFenceVariantPreviews();
        }

        InvalidateInstallGrid();
        RefreshTrainInstallPreviewTints();
    }

    private void RemovePlacedInstallPreviews(IReadOnlyList<MapObject> placedPreviews)
    {
        if (placedPreviews == null || placedPreviews.Count <= 0)
        {
            return;
        }

        InvalidateInstallPreviewMoveCache();
        ClearHandcartConnectionPreviewHandleOverrides();
        for (int i = 0; i < placedPreviews.Count; i++)
        {
            MapObject preview = placedPreviews[i];
            if (preview == null)
            {
                continue;
            }

            installPreviewInstances.Remove(preview);
            installPreviewQuarterTurnsByPreview.Remove(preview);
            installPreviewFenceDoorStandaloneQuarterTurnsByPreview.Remove(preview);
            installPreviewBaseRotationsByPreview.Remove(preview);
            installPreviewSourcePrefabsByPreview.Remove(preview);
            installPreviewRailReferenceWorldPositions.Remove(preview);
            installPreviewPlacementSequencesByPreview.Remove(preview);
            installPreviewConveyorRotationSequenceIndexesByPreview.Remove(preview);
            installPreviewPipeConnectionMasksByPreview.Remove(preview);
            installPreviewPipeSelectedSetDirectionsByPreview.Remove(preview);
            ClearFreightCarBoxPreviewTarget(preview);
            installPreviewAnchorCoordinates.Remove(preview);
            installPreviewItemReservationsByPreview.Remove(preview);
            straightFirstConveyorPreviews.Remove(preview);
            if (activeInstallPreview == preview)
            {
                activeInstallPreview = null;
                installPreviewQuarterTurns = 0;
            }

            DestroyInstallPreviewObject(preview);
        }

        EnsureValidActiveInstallPreview();
        RefreshInstallOrEditWorkableRangeVisualRequest();
        if (installPreviewInstances.Count <= 0)
        {
            ClearInstallPreview();
            return;
        }

        InvalidateInstallGrid();
        RefreshTrainInstallPreviewTints();
    }

    private void EnsureValidActiveInstallPreview()
    {
        if (activeInstallPreview != null)
        {
            return;
        }

        CleanupInstallPreviewReferences();
        if (installPreviewInstances.Count <= 0)
        {
            installPreviewQuarterTurns = 0;
            return;
        }

        SelectInstallPreview(installPreviewInstances[installPreviewInstances.Count - 1]);
    }

    private bool IsInstallationModeActive()
    {
        return GameManager.Instance != null
               && GameManager.Instance.InstallationPlacementActive
               && activeInstallDefinition != null;
    }

    private bool IsInstallGridModeActive()
    {
        return IsInstallationModeActive() || mapEditModeActive;
    }

    private void InvalidateInstallGrid()
    {
        ResetInstallGridMeshBuild(true);
        installGridDirty = true;
        installGridPreviewDirty = true;
    }

    private void InvalidateInstallGridPreview()
    {
        installGridPreviewDirty = true;
    }

    private void InvalidateInstallPreviewMoveCache()
    {
        cachedInstallPreviewMovePreview = null;
        cachedInstallPreviewMoveBlock = null;
        cachedInstallPreviewMoveQuarterTurns = 0;
        cachedInstallPreviewMovePreviewCount = 0;
        cachedInstallPreviewMovePreserveRotation = false;
        cachedInstallPreviewMoveResult = false;
    }

    private bool TryUseCachedInstallPreviewMove(Block block, bool preserveRotation, out bool result)
    {
        result = false;
        if (ShouldBypassInstallPreviewMoveCacheForRailAlignment())
        {
            return false;
        }

        if (activeInstallPreview == null
            || block == null
            || cachedInstallPreviewMovePreview != activeInstallPreview
            || cachedInstallPreviewMoveBlock != block
            || cachedInstallPreviewMoveQuarterTurns != installPreviewQuarterTurns
            || cachedInstallPreviewMovePreviewCount != installPreviewInstances.Count
            || cachedInstallPreviewMovePreserveRotation != preserveRotation)
        {
            return false;
        }

        result = cachedInstallPreviewMoveResult;
        return true;
    }

    private bool ShouldBypassInstallPreviewMoveCacheForRailAlignment()
    {
        MapObject rotationSource = activeInstallPreview != null
            ? ResolveInstallPreviewRotationSource(activeInstallPreview)
            : activeInstallDefinition != null
                ? activeInstallDefinition.mapObject
                : null;
        return IsTrainSource(rotationSource)
               || IsTrainStationSource(rotationSource);
    }

    private void CacheInstallPreviewMoveResult(Block block, bool result, bool preserveRotation)
    {
        if (activeInstallPreview == null || block == null)
        {
            InvalidateInstallPreviewMoveCache();
            return;
        }

        cachedInstallPreviewMovePreview = activeInstallPreview;
        cachedInstallPreviewMoveBlock = block;
        cachedInstallPreviewMoveQuarterTurns = installPreviewQuarterTurns;
        cachedInstallPreviewMovePreviewCount = installPreviewInstances.Count;
        cachedInstallPreviewMovePreserveRotation = preserveRotation;
        cachedInstallPreviewMoveResult = result;
    }

    private bool TryGetInstallPreviewAtBlock(Block block, out MapObject preview)
    {
        preview = null;
        if (block == null)
        {
            return false;
        }

        return TryGetInstallPreviewAtCoordinate(block.Coordinate, out preview);
    }

    private bool TryGetBlockForPreview(MapObject preview, out Block block)
    {
        block = null;
        if (preview == null)
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        if (!TryGetPreviewAnchorCoordinate(preview, out Vector2Int coordinate))
        {
            return false;
        }

        return terrain.TryGetLoadedBlock(coordinate, out block) && block != null;
    }

    private bool CanPlacePreviewOnBlock(
        Block block,
        MapObject previewToIgnore = null,
        int? quarterTurnsOverride = null,
        bool includeIgnoredPreviewAsConnector = false)
    {
        if (block == null)
        {
            return false;
        }

        if (previewToIgnore is UndergroundPipe undergroundPipePreview
            && undergroundPipePreview.IsPreviewPairCommitted)
        {
            return undergroundPipePreview.TryGetPairCoordinates(
                       out Vector2Int firstCoordinate,
                       out Vector2Int secondCoordinate)
                   && TryValidateUndergroundPipePair(
                       firstCoordinate,
                       secondCoordinate,
                       undergroundPipePreview,
                       out _,
                       out _);
        }

        int quarterTurns = quarterTurnsOverride ?? (previewToIgnore != null ? GetPreviewQuarterTurns(previewToIgnore) : installPreviewQuarterTurns);
        MapObject footprintSource = previewToIgnore != null
            ? previewToIgnore
            : (activeInstallDefinition != null ? activeInstallDefinition.mapObject : null);
        if (activeInstallDefinition != null && IsBelt2F(activeInstallDefinition.mapObject))
        {
            footprintSource = activeInstallDefinition.mapObject;
        }
        else if (activeInstallDefinition != null && activeInstallDefinition.mapObject is ConveyorBelt)
        {
            ConveyorPreviewVariantMode previewVariantMode = previewToIgnore == activeInstallPreview
                ? installPreviewConveyorVariantMode
                : GetConveyorPreviewVariantMode(previewToIgnore);
            footprintSource = ResolveInstalledObjectSourcePrefab(
                                  activeInstallDefinition,
                                  block.Coordinate,
                                  quarterTurns,
                                  previewToIgnore,
                                  previewVariantMode)
                              ?? footprintSource;
        }
        else if (activeInstallDefinition != null
                 && activeInstallDefinition.mapObject is Wall fencePrototype
                 && TryResolveFencePlacementVariant(
                     fencePrototype,
                     block.Coordinate,
                     quarterTurns,
                     previewToIgnore,
                     out MapObject fenceSourcePrefab,
                     out int fenceQuarterTurns))
        {
            footprintSource = fenceSourcePrefab ?? footprintSource;
            quarterTurns = fenceQuarterTurns;
        }
        else if (activeInstallDefinition != null
                 && activeInstallDefinition.mapObject is Pipe pipePrototype)
        {
            if (!TryResolvePipePlacementVariant(
                    pipePrototype,
                    block.Coordinate,
                    quarterTurns,
                    previewToIgnore,
                    out MapObject resolvedPipeSource,
                    out int resolvedPipeQuarterTurns)
                || !(resolvedPipeSource is Pipe))
            {
                return false;
            }

            footprintSource = resolvedPipeSource;
            quarterTurns = resolvedPipeQuarterTurns;
        }

        if (footprintSource == null)
        {
            return false;
        }

        if (TryResolveTrainStationFacingQuarterTurns(
                block.Coordinate,
                footprintSource,
                previewToIgnore,
                quarterTurns,
                out int trainStationQuarterTurns))
        {
            quarterTurns = trainStationQuarterTurns;
        }

        if (IsTrainSource(footprintSource))
        {
            Vector3 referencePosition = previewToIgnore != null
                ? previewToIgnore.transform.position
                : block.transform.position;
            if (previewToIgnore != null
                && installPreviewRailReferenceWorldPositions.TryGetValue(previewToIgnore, out Vector3 storedRailReferencePosition))
            {
                referencePosition = storedRailReferencePosition;
            }

            return TryResolveTrainRailPlacementPose(
                footprintSource,
                block.Coordinate,
                quarterTurns,
                referencePosition,
                out Vector3 trainPosition,
                out Quaternion trainRotation)
                && CanPlaceTrainAtPose(footprintSource, trainPosition, trainRotation, previewToIgnore);
        }

        if (!TryGetFootprintBlocks(
                block.Coordinate,
                footprintSource,
                quarterTurns,
                previewToIgnore,
                out _,
                false,
                includeIgnoredPreviewAsConnector))
        {
            return !IsBelt2F(footprintSource)
                   && CanPlaceStraightConveyorPreviewOnBlock(block, previewToIgnore, quarterTurns);
        }

        if (IsBoilerSource(footprintSource)
            && IsExactPumpOutputCoordinateForPlacement(block.Coordinate)
            && TryGetBoilerPumpOutputDirectionMatch(
                footprintSource,
                block.Coordinate,
                quarterTurns,
                out bool pumpOutputDirectionMatches))
        {
            return pumpOutputDirectionMatches;
        }

        if (!CanProposedFluidTankAndPumpConnectionsMatchExisting(
                block.Coordinate,
                footprintSource,
                quarterTurns,
                previewToIgnore)
            || !CanProposedFluidStoragePipeAreaConnectionsMatchExisting(
                block.Coordinate,
                footprintSource,
                quarterTurns,
                previewToIgnore,
                includeIgnoredPreviewAsConnector))
        {
            return false;
        }

        if (activeInstallDefinition == null || !(activeInstallDefinition.mapObject is ConveyorBelt conveyorPrototype))
        {
            return true;
        }

        ConveyorBelt cornerConveyor = footprintSource is ConveyorBelt footprintConveyor && footprintConveyor.IsCornerVariant
            ? footprintConveyor
            : null;

        if (cornerConveyor == null)
        {
            return conveyorPrototype != null;
        }

        return true;
    }

    private bool CanPlaceStraightConveyorPreviewOnBlock(Block block, MapObject previewToIgnore, int quarterTurns)
    {
        if (block == null
            || !CanUseStraightConveyorFallback(previewToIgnore)
            || !TryResolveStraightConveyorPlacementSource(out MapObject sourcePrefab))
        {
            return false;
        }

        return TryGetFootprintBlocks(
            block.Coordinate,
            sourcePrefab,
            NormalizePlacementQuarterTurns(quarterTurns),
            previewToIgnore,
            out _);
    }

    private bool CanUseStraightConveyorFallback(MapObject preview)
    {
        if (activeInstallDefinition == null
            || !(activeInstallDefinition.mapObject is ConveyorBelt)
            || IsBelt2F(activeInstallDefinition.mapObject))
        {
            return false;
        }

        if (preview == null)
        {
            return true;
        }

        if (preview == activeInstallPreview && installPreviewConveyorVariantMode == ConveyorPreviewVariantMode.Straight)
        {
            return true;
        }

        return preview is ConveyorBelt conveyorPreview && !conveyorPreview.IsCornerVariant;
    }

    private bool TryResolveStraightConveyorPlacementSource(out MapObject sourcePrefab)
    {
        sourcePrefab = null;
        if (activeInstallDefinition == null || !(activeInstallDefinition.mapObject is ConveyorBelt conveyorPrototype))
        {
            return false;
        }

        sourcePrefab = ResolveConveyorVariantPrefab(conveyorPrototype, 0) ?? conveyorPrototype;
        return sourcePrefab is ConveyorBelt straightConveyor && !straightConveyor.IsCornerVariant;
    }

    private bool TryFindPlaceableInstallPreviewQuarterTurns(
        Block block,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (block == null)
        {
            return false;
        }

        if (TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject trainStationFootprintSource)
            && TryResolveTrainStationFacingQuarterTurns(
                block.Coordinate,
                trainStationFootprintSource,
                previewToIgnore,
                resolvedQuarterTurns,
                out int trainStationQuarterTurns)
            && CanPlacePreviewOnBlock(block, previewToIgnore, trainStationQuarterTurns))
        {
            resolvedQuarterTurns = trainStationQuarterTurns;
            return true;
        }

        if (TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject waterPumpFootprintSource)
            && TryResolveWaterPumpOutwardQuarterTurns(
                block.Coordinate,
                waterPumpFootprintSource,
                resolvedQuarterTurns,
                out int waterPumpQuarterTurns)
            && CanPlacePreviewOnBlock(block, previewToIgnore, waterPumpQuarterTurns))
        {
            resolvedQuarterTurns = waterPumpQuarterTurns;
            return true;
        }

        if (IsConveyorInstallPreview(previewToIgnore)
            && TryResolveConveyorEndpointAlignedQuarterTurns(
                block.Coordinate,
                previewToIgnore,
                resolvedQuarterTurns,
                out int endpointAlignedQuarterTurns))
        {
            if (CanPlacePreviewOnBlock(block, previewToIgnore, endpointAlignedQuarterTurns)
                || CanPlaceStraightConveyorPreviewOnBlock(block, previewToIgnore, endpointAlignedQuarterTurns))
            {
                resolvedQuarterTurns = endpointAlignedQuarterTurns;
                return true;
            }
        }

        if (activeInstallDefinition != null
            && activeInstallDefinition.mapObject is Wall fencePrototype
            && TryResolveFencePlacementVariant(
                fencePrototype,
                block.Coordinate,
                resolvedQuarterTurns,
                previewToIgnore,
                out _,
                out int fenceResolvedQuarterTurns)
            && CanPlacePreviewOnBlock(block, previewToIgnore, fenceResolvedQuarterTurns))
        {
            resolvedQuarterTurns = fenceResolvedQuarterTurns;
            return true;
        }

        if (TryResolveSteamGeneratorPipeAlignedQuarterTurns(
                block,
                previewToIgnore,
                resolvedQuarterTurns,
                out int steamGeneratorPipeQuarterTurns))
        {
            resolvedQuarterTurns = steamGeneratorPipeQuarterTurns;
            return true;
        }

        if (CanUseBoilerEnergyInputRotationCandidate(block.Coordinate, previewToIgnore, resolvedQuarterTurns)
            && CanPlacePreviewOnBlock(block, previewToIgnore, resolvedQuarterTurns))
        {
            return true;
        }

        if (CanUseBoilerEnergyInputRotationCandidate(block.Coordinate, previewToIgnore, resolvedQuarterTurns)
            && CanPlaceDisconnectedFluidStoragePreviewOnBlock(
                block,
                previewToIgnore,
                resolvedQuarterTurns))
        {
            return true;
        }

        if (IsConveyorInstallPreview(previewToIgnore))
        {
            if (CanPlaceStraightConveyorPreviewOnBlock(block, previewToIgnore, resolvedQuarterTurns))
            {
                return true;
            }

            return false;
        }

        int candidateCount = GetPlacementRotationCandidateCount(
            ResolveInstallPreviewRotationSource(previewToIgnore));
        for (int offset = 1; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizeInstallPreviewQuarterTurns(
                previewToIgnore,
                resolvedQuarterTurns + offset);
            if (!CanUseBoilerEnergyInputRotationCandidate(block.Coordinate, previewToIgnore, candidateQuarterTurns)
                || (!CanPlacePreviewOnBlock(block, previewToIgnore, candidateQuarterTurns)
                && !CanPlaceDisconnectedFluidStoragePreviewOnBlock(
                    block,
                    previewToIgnore,
                    candidateQuarterTurns)))
            {
                continue;
            }

            resolvedQuarterTurns = candidateQuarterTurns;
            return true;
        }

        return false;
    }

    private bool CanPlaceDisconnectedFluidStoragePreviewOnBlock(
        Block block,
        MapObject previewToIgnore,
        int quarterTurns)
    {
        if (block == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !TryResolveInstallationObject(footprintSource, out InstallationObject installationObject)
            || installationObject is Pipe
            || installationObject is Pump
            || !installationObject.CanStoreFluid
            || PlacementHasExternalFluidConnector(
                block.Coordinate,
                footprintSource,
                quarterTurns,
                previewToIgnore))
        {
            return false;
        }

        return TryGetFootprintBlocks(
            block.Coordinate,
            footprintSource,
            quarterTurns,
            previewToIgnore,
            out _);
    }

    private bool PlacementHasExternalFluidConnector(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (footprintSource == null
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (placements == null || placements.Count <= 0)
        {
            return false;
        }

        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (!InputOutputModule.AllowsPipeAreaInteraction(placement.blockType)
                || !TryGetRectGridCoordinate(
                    anchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    placement,
                    out Vector2Int pipeAreaCoordinate))
            {
                continue;
            }

            if (CoordinateHasExternalFluidConnector(pipeAreaCoordinate, previewToIgnore))
            {
                return true;
            }

            for (int directionIndex = 0; directionIndex < PipeCardinalDirections.Length; directionIndex++)
            {
                if (CoordinateHasExternalFluidConnector(
                        pipeAreaCoordinate + PipeCardinalDirections[directionIndex],
                        previewToIgnore))
                {
                    return true;
                }
            }
        }

        return false;
    }

    private bool CoordinateHasExternalFluidConnector(Vector2Int coordinate, MapObject previewToIgnore)
    {
        if (TryGetPipePlacementAtCoordinate(coordinate, out _, out _))
        {
            return true;
        }

        pipeAreaBlockCandidateScratchA.Clear();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
            coordinate,
            previewToIgnore,
            pipeAreaBlockCandidateScratchA);
        bool hasConnector = false;
        for (int i = 0; i < pipeAreaBlockCandidateScratchA.Count; i++)
        {
            PipeAreaBlockCandidate candidate = pipeAreaBlockCandidateScratchA[i];
            if (IsIgnoredFluidConnectorSnapshot(candidate.snapshot, previewToIgnore))
            {
                continue;
            }

            hasConnector = true;
            break;
        }

        pipeAreaBlockCandidateScratchA.Clear();
        return hasConnector;
    }

    private bool IsIgnoredFluidConnectorSnapshot(PlacementSnapshot snapshot, MapObject previewToIgnore)
    {
        if (snapshot == null || snapshot.mapObject == null)
        {
            return true;
        }

        if (SnapshotBelongsToMapObject(snapshot, previewToIgnore))
        {
            return true;
        }

        InstallationObject originalInstallation = activeInstallationEditSession != null
            ? activeInstallationEditSession.originalInstallation
            : null;
        return SnapshotBelongsToMapObject(snapshot, originalInstallation);
    }

    private static bool SnapshotBelongsToMapObject(PlacementSnapshot snapshot, MapObject mapObject)
    {
        if (snapshot == null || snapshot.mapObject == null || mapObject == null)
        {
            return false;
        }

        if (snapshot.mapObject == mapObject)
        {
            return true;
        }

        Transform snapshotTransform = snapshot.mapObject.transform;
        Transform mapObjectTransform = mapObject.transform;
        if (snapshotTransform == null || mapObjectTransform == null)
        {
            return false;
        }

        return snapshotTransform == mapObjectTransform
               || snapshotTransform.IsChildOf(mapObjectTransform)
               || mapObjectTransform.IsChildOf(snapshotTransform);
    }

    private bool TryGetAdjacentBoilerInitialQuarterTurns(
        Vector2Int targetCoordinate,
        MapObject previewToIgnore,
        out int quarterTurns)
    {
        quarterTurns = 0;
        if (!TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsBoilerSource(footprintSource))
        {
            return false;
        }

        if (!TryGetNearbyBoilerPlacementQuarterTurns(
                targetCoordinate,
                previewToIgnore,
                out int nearbyBoilerQuarterTurns))
        {
            return false;
        }

        quarterTurns = NormalizePlacementQuarterTurnsForObject(
            footprintSource,
            nearbyBoilerQuarterTurns);
        return true;
    }

    private bool TryGetNearbyBoilerPlacementQuarterTurns(
        Vector2Int targetCoordinate,
        MapObject previewToIgnore,
        out int quarterTurns)
    {
        if (TryGetBoilerPipePassPlacementQuarterTurnsAtCoordinate(
                targetCoordinate,
                previewToIgnore,
                out quarterTurns)
            || TryGetBoilerObjectPlacementQuarterTurnsAtCoordinate(
                targetCoordinate,
                previewToIgnore,
                out quarterTurns))
        {
            return true;
        }

        for (int distance = 1; distance <= 2; distance++)
        {
            for (int i = 0; i < PipeCardinalDirections.Length; i++)
            {
                Vector2Int direction = PipeCardinalDirections[i];
                Vector2Int probeCoordinate = new Vector2Int(
                    targetCoordinate.x + direction.x * distance,
                    targetCoordinate.y + direction.y * distance);

                if (TryGetBoilerObjectPlacementQuarterTurnsAtCoordinate(
                        probeCoordinate,
                        previewToIgnore,
                        out quarterTurns)
                    || TryGetBoilerPipePassPlacementQuarterTurnsAtCoordinate(
                        probeCoordinate,
                        previewToIgnore,
                        out quarterTurns))
                {
                    return true;
                }
            }
        }

        quarterTurns = 0;
        return false;
    }

    private bool TryGetBoilerObjectPlacementQuarterTurnsAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out int quarterTurns)
    {
        quarterTurns = 0;
        if (!TryGetBoilerObjectPlacementSnapshotAtCoordinate(
                coordinate,
                previewToIgnore,
                out PlacementSnapshot snapshot))
        {
            return false;
        }

        quarterTurns = snapshot.quarterTurns;
        return true;
    }

    private bool TryGetBoilerObjectPlacementSnapshotAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out PlacementSnapshot snapshot)
    {
        if (TryGetPreviewPlacementSnapshot(coordinate, previewToIgnore, out snapshot)
            && IsBoilerObjectSnapshotAtCoordinate(snapshot, coordinate))
        {
            return true;
        }

        if (TryGetInstalledPlacementSnapshot(coordinate, out snapshot)
            && IsBoilerObjectSnapshotAtCoordinate(snapshot, coordinate))
        {
            return true;
        }

        if (TryGetRuntimeGridPlacementSnapshot(coordinate, out snapshot)
            && IsBoilerObjectSnapshotAtCoordinate(snapshot, coordinate))
        {
            return true;
        }

        if (TryGetRuntimeAreaPlacementSnapshot(coordinate, out snapshot)
            && IsBoilerObjectSnapshotAtCoordinate(snapshot, coordinate))
        {
            return true;
        }

        if (TryGetSavedPlacementSnapshot(coordinate, out snapshot)
            && IsBoilerObjectSnapshotAtCoordinate(snapshot, coordinate))
        {
            return true;
        }

        snapshot = null;
        return false;
    }

    private bool IsBoilerObjectSnapshotAtCoordinate(PlacementSnapshot snapshot, Vector2Int coordinate)
    {
        return snapshot != null
               && IsBoilerSource(snapshot.mapObject)
               && SnapshotHasRectGridObjectBlock(snapshot, coordinate);
    }

    private bool TryGetBoilerPipePassPlacementQuarterTurnsAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out int quarterTurns)
    {
        quarterTurns = 0;
        pipeAreaBlockCandidateScratchB.Clear();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
            coordinate,
            previewToIgnore,
            pipeAreaBlockCandidateScratchB);

        for (int i = 0; i < pipeAreaBlockCandidateScratchB.Count; i++)
        {
            PipeAreaBlockCandidate candidate = pipeAreaBlockCandidateScratchB[i];
            if (candidate.snapshot == null
                || !IsBoilerSource(candidate.snapshot.mapObject)
                || !IsPipePassBlockType(candidate.blockType))
            {
                continue;
            }

            quarterTurns = candidate.snapshot.quarterTurns;
            pipeAreaBlockCandidateScratchB.Clear();
            return true;
        }

        pipeAreaBlockCandidateScratchB.Clear();
        return false;
    }

    private bool TryResolveFixedRotationInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = clickedBlock;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource))
        {
            return false;
        }

        if (IsBelt2F(footprintSource))
        {
            TerrainGenerator terrain = ResolveInstallPreviewTerrain();
            Vector2Int bridgeCenterOffset = GetBelt2FBridgeCenterOffset(footprintSource, resolvedQuarterTurns);
            Vector2Int candidateAnchorCoordinate = clickedBlock.Coordinate - bridgeCenterOffset;
            if (terrain != null
                && terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                && candidateAnchorBlock != null
                && CanPlacePreviewOnBlock(candidateAnchorBlock, previewToIgnore, resolvedQuarterTurns))
            {
                anchorBlock = candidateAnchorBlock;
                return true;
            }

            return false;
        }

        if (TryResolveTrainStationFacingQuarterTurns(
                clickedBlock.Coordinate,
                footprintSource,
                previewToIgnore,
                resolvedQuarterTurns,
                out int trainStationQuarterTurns))
        {
            resolvedQuarterTurns = trainStationQuarterTurns;
        }

        if (TryResolveFixedRotationSteamGeneratorChainTarget(
                clickedBlock,
                previewToIgnore,
                resolvedQuarterTurns,
                out anchorBlock))
        {
            return true;
        }

        if (TryResolveBoilerPipeConnectionInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                resolvedQuarterTurns,
                false,
                false,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (CanPlacePreviewOnBlock(clickedBlock, previewToIgnore, resolvedQuarterTurns))
        {
            anchorBlock = clickedBlock;
            return true;
        }

        if (TryFindFixedRotationItemAreaOverlapInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                resolvedQuarterTurns,
                out anchorBlock))
        {
            return true;
        }

        return TryFindFixedRotationMultiCellInstallPreviewTarget(
            clickedBlock,
            previewToIgnore,
            resolvedQuarterTurns,
            out anchorBlock);
    }

    private bool TryResolveFixedRotationSteamGeneratorChainTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int quarterTurns,
        out Block anchorBlock)
    {
        anchorBlock = null;
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsSteamGeneratorSource(footprintSource)
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out _))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        int searchRadius = Mathf.Max(4, Mathf.Max(rectGridWidth, rectGridHeight) + 1);
        int bestScore = int.MaxValue;
        Block bestAnchorBlock = null;
        for (int z = -searchRadius; z <= searchRadius; z++)
        {
            for (int x = -searchRadius; x <= searchRadius; x++)
            {
                Vector2Int connectorCoordinate = clickedBlock.Coordinate + new Vector2Int(x, z);
                pipeAreaBlockCandidateScratchC.Clear();
                CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
                    connectorCoordinate,
                    previewToIgnore,
                    pipeAreaBlockCandidateScratchC);

                for (int candidateIndex = 0; candidateIndex < pipeAreaBlockCandidateScratchC.Count; candidateIndex++)
                {
                    PipeAreaBlockCandidate existingCandidate = pipeAreaBlockCandidateScratchC[candidateIndex];
                    if (!TryResolveFixedRotationSteamGeneratorChainCandidate(
                            clickedBlock.Coordinate,
                            connectorCoordinate,
                            existingCandidate,
                            footprintSource,
                            terrain,
                            previewToIgnore,
                            quarterTurns,
                            out Block candidateAnchorBlock))
                    {
                        continue;
                    }

                    int score = Mathf.Abs(connectorCoordinate.x - clickedBlock.Coordinate.x)
                        + Mathf.Abs(connectorCoordinate.y - clickedBlock.Coordinate.y);
                    if (bestAnchorBlock != null && score >= bestScore)
                    {
                        continue;
                    }

                    bestScore = score;
                    bestAnchorBlock = candidateAnchorBlock;
                }
            }
        }

        pipeAreaBlockCandidateScratchC.Clear();
        anchorBlock = bestAnchorBlock;
        return anchorBlock != null;
    }

    private bool TryResolveFixedRotationSteamGeneratorChainCandidate(
        Vector2Int clickedCoordinate,
        Vector2Int connectorCoordinate,
        PipeAreaBlockCandidate existingCandidate,
        MapObject footprintSource,
        TerrainGenerator terrain,
        MapObject previewToIgnore,
        int quarterTurns,
        out Block anchorBlock)
    {
        anchorBlock = null;
        if (existingCandidate.snapshot == null
            || !IsSteamGeneratorSource(existingCandidate.snapshot.mapObject)
            || !TryGetSteamGeneratorPipePassTailDirection(
                connectorCoordinate,
                existingCandidate,
                out Vector2Int existingTailDirection)
            || !TryGetSteamGeneratorBodyDirectionFromCenter(
                footprintSource,
                quarterTurns,
                out Vector2Int proposedTailDirection)
            || proposedTailDirection != existingTailDirection)
        {
            return false;
        }

        Vector2Int candidateAnchorCoordinate = connectorCoordinate;
        if (!SteamGeneratorChainPlacementContainsCoordinate(
                clickedCoordinate,
                candidateAnchorCoordinate,
                footprintSource,
                quarterTurns)
            || !terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
            || candidateAnchorBlock == null
            || !CanPlacePreviewOnBlock(
                candidateAnchorBlock,
                previewToIgnore,
                quarterTurns,
                true))
        {
            return false;
        }

        anchorBlock = candidateAnchorBlock;
        return true;
    }

    private bool TryFindFixedRotationItemAreaOverlapInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int quarterTurns,
        out Block anchorBlock)
    {
        anchorBlock = null;
        if (clickedBlock == null
            || !CoordinateHasInputOutputAreaForPlacement(clickedBlock.Coordinate, null)
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            bool canUsePlacementForAreaOverlap = IsRectGridAreaBlockType(placement.blockType)
                || CanUseObjectPlacementForFluidStorageAreaOverlap(
                    footprintSource,
                    placement.blockType,
                    clickedBlock.Coordinate);
            if (!canUsePlacementForAreaOverlap
                || placement.x < 0
                || placement.x >= rectGridWidth
                || placement.y < 0
                || placement.y >= rectGridHeight)
            {
                continue;
            }

            Vector2Int localOffset = new Vector2Int(
                placement.x - objectAnchorCell.x,
                placement.y - objectAnchorCell.y);
            Vector2Int candidateAnchorCoordinate =
                clickedBlock.Coordinate - RotateFootprintOffset(localOffset, quarterTurns);
            if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                || candidateAnchorBlock == null
                || PlacementHasBoilerEnergyInputPipeConflict(
                    candidateAnchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    previewToIgnore)
                || PlacementHasNormalInputOutputAreaPipeOverlap(
                    candidateAnchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    previewToIgnore)
                || !CanPlacePreviewOnBlock(candidateAnchorBlock, previewToIgnore, quarterTurns))
            {
                continue;
            }

            anchorBlock = candidateAnchorBlock;
            return true;
        }

        return false;
    }

    private bool TryFindFixedRotationMultiCellInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int quarterTurns,
        out Block anchorBlock)
    {
        anchorBlock = null;
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !HasMultiCellMapSize(footprintSource)
            || IsBelt2F(footprintSource))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        List<Vector2Int> localOffsets = GetFootprintLocalOffsets(footprintSource, quarterTurns);
        for (int i = 0; i < localOffsets.Count; i++)
        {
            Vector2Int localOffset = localOffsets[i];
            if (localOffset == Vector2Int.zero)
            {
                continue;
            }

            Vector2Int candidateAnchorCoordinate = clickedBlock.Coordinate - localOffset;
            if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                || candidateAnchorBlock == null
                || PlacementHasBoilerEnergyInputPipeConflict(
                    candidateAnchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    previewToIgnore)
                || PlacementHasNormalInputOutputAreaPipeOverlap(
                    candidateAnchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    previewToIgnore)
                || !CanPlacePreviewOnBlock(candidateAnchorBlock, previewToIgnore, quarterTurns))
            {
                continue;
            }

            anchorBlock = candidateAnchorBlock;
            return true;
        }

        return false;
    }

    private bool TryResolvePlaceableInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        bool includeIgnoredPreviewAsConnector,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = clickedBlock;
        resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null)
        {
            return false;
        }

        if (TryGetAdjacentBoilerInitialQuarterTurns(
                clickedBlock.Coordinate,
                previewToIgnore,
                out int adjacentBoilerQuarterTurns))
        {
            preferredQuarterTurns = adjacentBoilerQuarterTurns;
            resolvedQuarterTurns = adjacentBoilerQuarterTurns;
        }

        if (TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            && IsBelt2F(footprintSource))
        {
            return TryResolveBelt2FBridgeCenterInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                out anchorBlock,
                out resolvedQuarterTurns);
        }

        if (TryResolveBelt2FBridgeCenterInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (TryResolveSteamGeneratorOnBoilerOutputInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                includeIgnoredPreviewAsConnector,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (TryResolveSteamGeneratorOnPipePassInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                includeIgnoredPreviewAsConnector,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (TryResolveSteamGeneratorOnPipeInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                includeIgnoredPreviewAsConnector,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (TryResolveSteamGeneratorBesidePipeInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                includeIgnoredPreviewAsConnector,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (TryResolveSteamGeneratorChainInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                includeIgnoredPreviewAsConnector,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (TryResolveBoilerOnSteamGeneratorInputInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                includeIgnoredPreviewAsConnector,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (TryResolveBoilerOnPumpOutputInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (TryResolveBoilerPipeConnectionInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                includeIgnoredPreviewAsConnector,
                true,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (TryResolveBoilerOnBoilerPipePassInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                includeIgnoredPreviewAsConnector,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (includeIgnoredPreviewAsConnector
            && CoordinateHasInputOutputAreaForPlacement(clickedBlock.Coordinate, null))
        {
            if (TryFindPlaceableItemAreaOverlapInstallPreviewTarget(
                    clickedBlock,
                    null,
                    preferredQuarterTurns,
                    out anchorBlock,
                    out resolvedQuarterTurns))
            {
                return true;
            }

            // The clicked preview owns the ItemArea, but the object being placed is
            // the active definition. Simple installations such as floors have no
            // rect-grid area to align, so validate them directly against that area.
            if (TryFindPlaceableInstallPreviewQuarterTurns(
                    clickedBlock,
                    null,
                    preferredQuarterTurns,
                    out resolvedQuarterTurns))
            {
                anchorBlock = clickedBlock;
                return true;
            }

            return false;
        }

        bool isMultiCellPreview =
            TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject previewFootprintSource)
            && HasMultiCellMapSize(previewFootprintSource)
            && !IsBelt2F(previewFootprintSource);

        if (TryFindPlaceableInstallPreviewQuarterTurns(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                out resolvedQuarterTurns))
        {
            anchorBlock = clickedBlock;
            return true;
        }

        if (isMultiCellPreview)
        {
            if (TryFindPlaceableItemAreaOverlapInstallPreviewTarget(
                    clickedBlock,
                    previewToIgnore,
                    preferredQuarterTurns,
                    out anchorBlock,
                    out resolvedQuarterTurns))
            {
                return true;
            }

            if (TryFindPlaceableMultiCellInstallPreviewTarget(
                    clickedBlock,
                    previewToIgnore,
                    preferredQuarterTurns,
                    out anchorBlock,
                    out resolvedQuarterTurns))
            {
                return true;
            }
        }

        if (TryFindPlaceableItemAreaOverlapInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        return !isMultiCellPreview
               && TryFindPlaceableMultiCellInstallPreviewTarget(
                   clickedBlock,
                   previewToIgnore,
                   preferredQuarterTurns,
                   out anchorBlock,
                   out resolvedQuarterTurns);
    }

    private bool TryResolveBelt2FBridgeCenterInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsBelt2F(footprintSource))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizeInstallPreviewQuarterTurns(
                previewToIgnore,
                resolvedQuarterTurns + offset);
            Vector2Int bridgeCenterOffset = GetBelt2FBridgeCenterOffset(footprintSource, candidateQuarterTurns);
            Vector2Int candidateAnchorCoordinate = clickedBlock.Coordinate - bridgeCenterOffset;
            if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                || candidateAnchorBlock == null
                || !CanPlacePreviewOnBlock(candidateAnchorBlock, previewToIgnore, candidateQuarterTurns))
            {
                continue;
            }

            anchorBlock = candidateAnchorBlock;
            resolvedQuarterTurns = candidateQuarterTurns;
            return true;
        }

        return false;
    }

    private bool TryResolveSteamGeneratorChainInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        bool includeIgnoredPreviewAsConnector,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsSteamGeneratorSource(footprintSource)
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out _))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        MapObject connectorPreviewToIgnore = includeIgnoredPreviewAsConnector ? null : previewToIgnore;
        int searchRadius = Mathf.Max(4, Mathf.Max(rectGridWidth, rectGridHeight) + 1);
        bool foundCandidate = false;
        int bestScore = int.MaxValue;
        Block bestAnchorBlock = null;
        int bestQuarterTurns = resolvedQuarterTurns;
        for (int z = -searchRadius; z <= searchRadius; z++)
        {
            for (int x = -searchRadius; x <= searchRadius; x++)
            {
                Vector2Int connectorCoordinate = clickedBlock.Coordinate + new Vector2Int(x, z);
                pipeAreaBlockCandidateScratchC.Clear();
                CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
                    connectorCoordinate,
                    connectorPreviewToIgnore,
                    pipeAreaBlockCandidateScratchC);

                for (int candidateIndex = 0; candidateIndex < pipeAreaBlockCandidateScratchC.Count; candidateIndex++)
                {
                    PipeAreaBlockCandidate existingCandidate = pipeAreaBlockCandidateScratchC[candidateIndex];
                    if (!TryResolveSteamGeneratorStraightChainCandidate(
                            clickedBlock.Coordinate,
                            connectorCoordinate,
                            existingCandidate,
                            footprintSource,
                            terrain,
                            previewToIgnore,
                            out Block candidateAnchorBlock,
                            out int candidateQuarterTurns))
                    {
                        continue;
                    }

                    int score = Mathf.Abs(connectorCoordinate.x - clickedBlock.Coordinate.x)
                        + Mathf.Abs(connectorCoordinate.y - clickedBlock.Coordinate.y);
                    if (!foundCandidate || score < bestScore)
                    {
                        foundCandidate = true;
                        bestScore = score;
                        bestAnchorBlock = candidateAnchorBlock;
                        bestQuarterTurns = candidateQuarterTurns;
                    }
                }
            }
        }

        pipeAreaBlockCandidateScratchC.Clear();
        if (!foundCandidate)
        {
            return false;
        }

        anchorBlock = bestAnchorBlock;
        resolvedQuarterTurns = bestQuarterTurns;
        return anchorBlock != null;
    }

    private bool TryResolveSteamGeneratorStraightChainCandidate(
        Vector2Int clickedCoordinate,
        Vector2Int connectorCoordinate,
        PipeAreaBlockCandidate existingCandidate,
        MapObject footprintSource,
        TerrainGenerator terrain,
        MapObject previewToIgnore,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = 0;
        if (existingCandidate.snapshot == null
            || !IsSteamGeneratorSource(existingCandidate.snapshot.mapObject)
            || !IsPipePassBlockType(existingCandidate.blockType)
            || terrain == null)
        {
            return false;
        }

        resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            footprintSource,
            existingCandidate.snapshot.quarterTurns);

        if (!TryGetPipeAreaObjectDirection(
                connectorCoordinate,
                existingCandidate,
                out Vector2Int pipePassObjectDirection))
        {
            return false;
        }

        Vector2Int existingTailDirection = -pipePassObjectDirection;
        if (existingTailDirection == Vector2Int.zero
            || !TryGetSteamGeneratorBodyDirectionFromCenter(
                footprintSource,
                resolvedQuarterTurns,
                out Vector2Int proposedTailDirection)
            || proposedTailDirection != existingTailDirection)
        {
            return false;
        }

        Vector2Int candidateAnchorCoordinate = connectorCoordinate;
        if (!SteamGeneratorChainPlacementContainsCoordinate(
                clickedCoordinate,
                candidateAnchorCoordinate,
                footprintSource,
                resolvedQuarterTurns)
            || !terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
            || candidateAnchorBlock == null)
        {
            return false;
        }

        if (!CanPlacePreviewOnBlock(
                candidateAnchorBlock,
                previewToIgnore,
                resolvedQuarterTurns,
                true))
        {
            return false;
        }

        anchorBlock = candidateAnchorBlock;
        return true;
    }

    private bool SteamGeneratorChainPlacementContainsCoordinate(
        Vector2Int coordinate,
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns)
    {
        if (coordinate == anchorCoordinate)
        {
            return true;
        }

        List<Vector2Int> visualCoordinates = GetPlacementVisualCoordinates(
            anchorCoordinate,
            footprintSource,
            quarterTurns);
        for (int i = 0; i < visualCoordinates.Count; i++)
        {
            if (visualCoordinates[i] == coordinate)
            {
                return true;
            }
        }

        return TryGetRectGridFootprintBlockType(
            anchorCoordinate,
            footprintSource,
            quarterTurns,
            coordinate,
            out InputOutputModule.RectGridBlockType blockType)
            && blockType != InputOutputModule.RectGridBlockType.None;
    }

    private bool TryResolveSteamGeneratorOnBoilerOutputInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        bool includeIgnoredPreviewAsConnector,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        MapObject connectorPreviewToIgnore = includeIgnoredPreviewAsConnector ? null : previewToIgnore;
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsSteamGeneratorSource(footprintSource))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (placements == null || placements.Count <= 0)
        {
            return false;
        }

        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                footprintSource,
                preferredQuarterTurns + offset);

            for (int placementIndex = 0; placementIndex < placements.Count; placementIndex++)
            {
                InputOutputModule.RectGridBlockPlacement placement = placements[placementIndex];
                if (placement.blockType != InputOutputModule.RectGridBlockType.Object
                    || placement.x < 0
                    || placement.x >= rectGridWidth
                    || placement.y < 0
                    || placement.y >= rectGridHeight)
                {
                    continue;
                }

                Vector2Int localOffset = new Vector2Int(
                    placement.x - objectAnchorCell.x,
                    placement.y - objectAnchorCell.y);
                Vector2Int candidateAnchorCoordinate =
                    clickedBlock.Coordinate - RotateFootprintOffset(localOffset, candidateQuarterTurns);
                if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                    || candidateAnchorBlock == null
                    || !TryGetSteamGeneratorDirectBoilerOutputPlacement(
                        candidateAnchorCoordinate,
                        footprintSource,
                        candidateQuarterTurns,
                        connectorPreviewToIgnore,
                        out _,
                        out _)
                    || !CanPlacePreviewOnBlock(
                        candidateAnchorBlock,
                        previewToIgnore,
                        candidateQuarterTurns,
                        includeIgnoredPreviewAsConnector))
                {
                    continue;
                }

                anchorBlock = candidateAnchorBlock;
                resolvedQuarterTurns = candidateQuarterTurns;
                return true;
            }
        }

        return false;
    }

    private bool TryResolveSteamGeneratorOnPipePassInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        bool includeIgnoredPreviewAsConnector,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsSteamGeneratorSource(footprintSource)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        MapObject connectorPreviewToIgnore = includeIgnoredPreviewAsConnector ? null : previewToIgnore;
        List<PipeAreaBlockCandidate> pipePassCandidates =
            CollectPipePassCandidatesAtCoordinate(clickedBlock.Coordinate, connectorPreviewToIgnore);
        if (pipePassCandidates.Count <= 0)
        {
            return false;
        }

        if (!TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell))
        {
            return false;
        }

        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        for (int passIndex = 0; passIndex < pipePassCandidates.Count; passIndex++)
        {
            PipeAreaBlockCandidate pipePassCandidate = pipePassCandidates[passIndex];
            if (pipePassCandidate.snapshot != null
                && IsSteamGeneratorSource(pipePassCandidate.snapshot.mapObject))
            {
                continue;
            }

            if (!TryGetPipeAreaObjectDirection(
                    clickedBlock.Coordinate,
                    pipePassCandidate,
                    out Vector2Int pipePassObjectDirection))
            {
                continue;
            }

            Vector2Int requiredInputDirection = -pipePassObjectDirection;
            for (int offset = 0; offset < candidateCount; offset++)
            {
                int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                    footprintSource,
                    preferredQuarterTurns + offset);
                if (!TryGetSteamGeneratorBodyDirectionFromCenter(
                        footprintSource,
                        candidateQuarterTurns,
                        out Vector2Int adjacentBodyDirection)
                    || adjacentBodyDirection != requiredInputDirection)
                {
                    continue;
                }

                for (int placementIndex = 0; placementIndex < placements.Count; placementIndex++)
                {
                    InputOutputModule.RectGridBlockPlacement placement = placements[placementIndex];
                    if (!InputOutputModule.IsInputItemBlockType(placement.blockType)
                        || placement.x < 0
                        || placement.x >= rectGridWidth
                        || placement.y < 0
                        || placement.y >= rectGridHeight)
                    {
                        continue;
                    }

                    Vector2Int localOffset = new Vector2Int(
                        placement.x - objectAnchorCell.x,
                        placement.y - objectAnchorCell.y);
                    Vector2Int candidateAnchorCoordinate =
                        clickedBlock.Coordinate - RotateFootprintOffset(localOffset, candidateQuarterTurns);
                    if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                        || candidateAnchorBlock == null)
                    {
                        continue;
                    }

                    PlacementSnapshot proposedSnapshot = new PlacementSnapshot
                    {
                        mapObject = footprintSource,
                        rotation = GetPlacementObjectRotation(footprintSource, candidateQuarterTurns),
                        anchorCoordinate = candidateAnchorCoordinate,
                        quarterTurns = candidateQuarterTurns
                    };
                    PipeAreaBlockCandidate proposedInputCandidate =
                        new PipeAreaBlockCandidate(proposedSnapshot, placement.blockType);
                    if (!CanPipeAreaBlockCandidatesConnect(
                            clickedBlock.Coordinate,
                            pipePassCandidate,
                            clickedBlock.Coordinate,
                            proposedInputCandidate)
                        || !CanPlacePreviewOnBlock(
                            candidateAnchorBlock,
                            previewToIgnore,
                            candidateQuarterTurns,
                            includeIgnoredPreviewAsConnector))
                    {
                        continue;
                    }

                    anchorBlock = candidateAnchorBlock;
                    resolvedQuarterTurns = candidateQuarterTurns;
                    return true;
                }
            }
        }

        return false;
    }

    private bool TryResolveSteamGeneratorOnPipeInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        bool includeIgnoredPreviewAsConnector,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsSteamGeneratorSource(footprintSource)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell))
        {
            return false;
        }

        MapObject occupyingObject = GetOccupyingObjectForPlacement(clickedBlock);

        if (!TryGetPipePlacementAtBlock(clickedBlock, occupyingObject, out Pipe pipe, out Quaternion pipeRotation))
        {
            return false;
        }

        if (!TryGetStraightPipeAxis(pipe, pipeRotation, out Vector2Int pipeAxisDirection))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                footprintSource,
                preferredQuarterTurns + offset);
            if (!TryGetSteamGeneratorBodyDirectionFromCenter(
                    footprintSource,
                    candidateQuarterTurns,
                    out Vector2Int bodyDirection)
                || !DirectionsShareAxis(bodyDirection, pipeAxisDirection))
            {
                continue;
            }

            for (int placementIndex = 0; placementIndex < placements.Count; placementIndex++)
            {
                InputOutputModule.RectGridBlockPlacement placement = placements[placementIndex];
                if (!InputOutputModule.AllowsPipeAreaInteraction(placement.blockType)
                    || placement.x < 0
                    || placement.x >= rectGridWidth
                    || placement.y < 0
                    || placement.y >= rectGridHeight)
                {
                    continue;
                }

                Vector2Int localOffset = new Vector2Int(
                    placement.x - objectAnchorCell.x,
                    placement.y - objectAnchorCell.y);
                Vector2Int candidateAnchorCoordinate =
                    clickedBlock.Coordinate - RotateFootprintOffset(localOffset, candidateQuarterTurns);
                if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                    || candidateAnchorBlock == null
                    || !SteamGeneratorPipeAreaDirectionMatchesPipe(
                        footprintSource,
                        inputOutputModule,
                        candidateAnchorCoordinate,
                        candidateQuarterTurns,
                        clickedBlock.Coordinate,
                        pipeAxisDirection)
                    || !CanPlacePreviewOnBlock(
                        candidateAnchorBlock,
                        previewToIgnore,
                        candidateQuarterTurns,
                        includeIgnoredPreviewAsConnector))
                {
                    continue;
                }

                anchorBlock = candidateAnchorBlock;
                resolvedQuarterTurns = candidateQuarterTurns;
                return true;
            }
        }

        return false;
    }

    private bool TryResolveSteamGeneratorBesidePipeInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        bool includeIgnoredPreviewAsConnector,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsSteamGeneratorSource(footprintSource)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        const int maxSteamGeneratorCenterPipeProbeDistance = 2;
        for (int distance = 1; distance <= maxSteamGeneratorCenterPipeProbeDistance; distance++)
        {
            for (int directionIndex = 0; directionIndex < PipeCardinalDirections.Length; directionIndex++)
            {
                Vector2Int directionToPipe = PipeCardinalDirections[directionIndex];
                Vector2Int pipeCoordinate = clickedBlock.Coordinate
                    + new Vector2Int(directionToPipe.x * distance, directionToPipe.y * distance);
                if (!terrain.TryGetLoadedBlock(pipeCoordinate, out Block pipeBlock)
                    || pipeBlock == null)
                {
                    continue;
                }

                MapObject occupyingObject = GetOccupyingObjectForPlacement(pipeBlock);

                if (!TryGetPipePlacementAtBlock(pipeBlock, occupyingObject, out Pipe pipe, out Quaternion pipeRotation)
                    || !TryGetStraightPipeAxis(pipe, pipeRotation, out Vector2Int pipeAxisDirection)
                    || !DirectionsShareAxis(pipeAxisDirection, directionToPipe)
                    || !TryResolveSteamGeneratorCenterAtPipeCoordinate(
                        terrain,
                        footprintSource,
                        inputOutputModule,
                        placements,
                        rectGridWidth,
                        rectGridHeight,
                        objectAnchorCell,
                        clickedBlock,
                        pipeCoordinate,
                        pipeAxisDirection,
                        previewToIgnore,
                        preferredQuarterTurns,
                        includeIgnoredPreviewAsConnector,
                        out anchorBlock,
                        out resolvedQuarterTurns))
                {
                    continue;
                }

                return true;
            }
        }

        return false;
    }

    private bool TryResolveSteamGeneratorCenterAtPipeCoordinate(
        TerrainGenerator terrain,
        MapObject footprintSource,
        InputOutputModule inputOutputModule,
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements,
        int rectGridWidth,
        int rectGridHeight,
        Vector2Int objectAnchorCell,
        Block centerBlock,
        Vector2Int pipeCoordinate,
        Vector2Int pipeAxisDirection,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        bool includeIgnoredPreviewAsConnector,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (terrain == null
            || footprintSource == null
            || inputOutputModule == null
            || placements == null
            || placements.Count <= 0
            || centerBlock == null
            || pipeAxisDirection == Vector2Int.zero)
        {
            return false;
        }

        Vector2Int centerToPipe = pipeCoordinate - centerBlock.Coordinate;
        if (!TryGetCardinalDirectionAndDistance(
                centerToPipe,
                out Vector2Int directionToPipe,
                out int pipeDistance)
            || pipeDistance > 2
            || !DirectionsShareAxis(directionToPipe, pipeAxisDirection))
        {
            return false;
        }

        Vector2Int requiredBodyDirection = pipeDistance == 1
            ? -directionToPipe
            : directionToPipe;
        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                footprintSource,
                preferredQuarterTurns + offset);
            if (!TryGetSteamGeneratorBodyDirectionFromCenter(
                    footprintSource,
                    candidateQuarterTurns,
                    out Vector2Int bodyDirection)
                || bodyDirection != requiredBodyDirection)
            {
                continue;
            }

            for (int placementIndex = 0; placementIndex < placements.Count; placementIndex++)
            {
                InputOutputModule.RectGridBlockPlacement placement = placements[placementIndex];
                if (!InputOutputModule.AllowsPipeAreaInteraction(placement.blockType)
                    || placement.x < 0
                    || placement.x >= rectGridWidth
                    || placement.y < 0
                    || placement.y >= rectGridHeight)
                {
                    continue;
                }

                Vector2Int localOffset = new Vector2Int(
                    placement.x - objectAnchorCell.x,
                    placement.y - objectAnchorCell.y);
                Vector2Int candidatePipeCoordinate =
                    centerBlock.Coordinate + RotateFootprintOffset(localOffset, candidateQuarterTurns);
                if (candidatePipeCoordinate != pipeCoordinate
                    || !PlacementHasRectGridObjectCoordinate(
                        centerBlock.Coordinate,
                        footprintSource,
                        candidateQuarterTurns,
                        centerBlock.Coordinate)
                    || !CanPlacePreviewOnBlock(
                        centerBlock,
                        previewToIgnore,
                        candidateQuarterTurns,
                        includeIgnoredPreviewAsConnector))
                {
                    continue;
                }

                anchorBlock = centerBlock;
                resolvedQuarterTurns = candidateQuarterTurns;
                return true;
            }
        }

        return false;
    }

    private static bool TryGetCardinalDirectionAndDistance(
        Vector2Int offset,
        out Vector2Int direction,
        out int distance)
    {
        direction = Vector2Int.zero;
        distance = Mathf.Abs(offset.x) + Mathf.Abs(offset.y);
        if (distance <= 0 || (offset.x != 0 && offset.y != 0))
        {
            return false;
        }

        direction = offset.x != 0
            ? new Vector2Int(offset.x > 0 ? 1 : -1, 0)
            : new Vector2Int(0, offset.y > 0 ? 1 : -1);
        return true;
    }

    private bool PlacementHasRectGridObjectCoordinate(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        Vector2Int coordinate)
    {
        return TryGetRectGridFootprintBlockType(
                   anchorCoordinate,
                   footprintSource,
                   quarterTurns,
                   coordinate,
                   out InputOutputModule.RectGridBlockType blockType)
               && blockType == InputOutputModule.RectGridBlockType.Object;
    }

    private bool TryResolveBoilerOnSteamGeneratorInputInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        bool includeIgnoredPreviewAsConnector,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsBoilerSource(footprintSource)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out _))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        MapObject connectorPreviewToIgnore = includeIgnoredPreviewAsConnector ? null : previewToIgnore;
        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        if (terrain.TryGetLoadedBlock(clickedBlock.Coordinate, out Block clickedAnchorBlock)
            && clickedAnchorBlock != null)
        {
            for (int offset = 0; offset < candidateCount; offset++)
            {
                int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                    footprintSource,
                    preferredQuarterTurns + offset);
                if (!CanBoilerDirectSteamGeneratorInputConnection(
                        clickedBlock.Coordinate,
                        footprintSource,
                        candidateQuarterTurns,
                        connectorPreviewToIgnore)
                    || PlacementHasBoilerEnergyInputPipeConflict(
                        clickedBlock.Coordinate,
                        footprintSource,
                        candidateQuarterTurns,
                        connectorPreviewToIgnore)
                    || !CanPlacePreviewOnBlock(
                        clickedAnchorBlock,
                        previewToIgnore,
                        candidateQuarterTurns,
                        includeIgnoredPreviewAsConnector))
                {
                    continue;
                }

                anchorBlock = clickedAnchorBlock;
                resolvedQuarterTurns = candidateQuarterTurns;
                return true;
            }
        }

        int bestScore = int.MaxValue;
        Block bestAnchorBlock = null;
        int bestQuarterTurns = resolvedQuarterTurns;
        bool foundCandidate = false;
        int searchRadius = 2;
        for (int z = -searchRadius; z <= searchRadius; z++)
        {
            for (int x = -searchRadius; x <= searchRadius; x++)
            {
                Vector2Int connectorCoordinate = clickedBlock.Coordinate + new Vector2Int(x, z);
                pipeAreaBlockCandidateScratchC.Clear();
                CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
                    connectorCoordinate,
                    connectorPreviewToIgnore,
                    pipeAreaBlockCandidateScratchC);

                for (int existingIndex = 0; existingIndex < pipeAreaBlockCandidateScratchC.Count; existingIndex++)
                {
                    PipeAreaBlockCandidate existingInputCandidate = pipeAreaBlockCandidateScratchC[existingIndex];
                    if (existingInputCandidate.snapshot == null
                        || !IsSteamGeneratorSource(existingInputCandidate.snapshot.mapObject)
                        || !InputOutputModule.IsInputItemBlockType(existingInputCandidate.blockType)
                        || !TryGetSteamGeneratorBodyDirectionFromCenter(
                            existingInputCandidate.snapshot.mapObject,
                            existingInputCandidate.snapshot.quarterTurns,
                            out Vector2Int steamBodyDirection)
                        || steamBodyDirection == Vector2Int.zero
                        || connectorCoordinate != existingInputCandidate.snapshot.anchorCoordinate - steamBodyDirection)
                    {
                        continue;
                    }

                    for (int offset = 0; offset < candidateCount; offset++)
                    {
                        int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                            footprintSource,
                            preferredQuarterTurns + offset);

                        Vector2Int candidateAnchorCoordinate = connectorCoordinate;
                        if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                            || candidateAnchorBlock == null)
                        {
                            continue;
                        }

                        if (!CanBoilerDirectSteamGeneratorInputConnection(
                                candidateAnchorCoordinate,
                                footprintSource,
                                candidateQuarterTurns,
                                previewToIgnore)
                            || PlacementHasBoilerEnergyInputPipeConflict(
                                candidateAnchorCoordinate,
                                footprintSource,
                                candidateQuarterTurns,
                                previewToIgnore)
                            || !CanPlacePreviewOnBlock(
                                candidateAnchorBlock,
                                previewToIgnore,
                                candidateQuarterTurns,
                                includeIgnoredPreviewAsConnector))
                        {
                            continue;
                        }

                        int score = Mathf.Abs(x) + Mathf.Abs(z);
                        if (!foundCandidate || score < bestScore)
                        {
                            foundCandidate = true;
                            bestScore = score;
                            bestAnchorBlock = candidateAnchorBlock;
                            bestQuarterTurns = candidateQuarterTurns;
                        }
                    }
                }
            }
        }

        pipeAreaBlockCandidateScratchC.Clear();
        if (!foundCandidate)
        {
            return false;
        }

        anchorBlock = bestAnchorBlock;
        resolvedQuarterTurns = bestQuarterTurns;
        return anchorBlock != null;
    }

    private bool TryResolveBoilerOnPumpOutputInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsBoilerSource(footprintSource)
            || !TryGetExactPumpOutputDirectionForPlacement(
                clickedBlock.Coordinate,
                out Vector2Int pumpOutputDirection)
            || pumpOutputDirection == Vector2Int.zero
            || !TryGetRectGridFootprintSettings(footprintSource, out _, out _, out _))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        // CRITICAL: Pump -> Boiler is an adjacent fluid-direction connection, not a
        // PipeOutput/PipePass same-cell overlap. The Boiler Object/anchor is allowed on
        // the pump OutputArea so the two machines are visually flush. Do not "fix"
        // this by separating the machines; only the pump-side Boiler PipePass direction
        // is allowed to constrain rotation.
        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizeInstallPreviewQuarterTurns(
                previewToIgnore,
                preferredQuarterTurns + offset);
            if (!BoilerPumpSidePipePassMatchesOutputDirection(
                    footprintSource,
                    clickedBlock.Coordinate,
                    clickedBlock.Coordinate,
                    candidateQuarterTurns,
                    pumpOutputDirection)
                || !CanPlacePreviewOnBlock(
                    clickedBlock,
                    previewToIgnore,
                    candidateQuarterTurns))
            {
                continue;
            }

            anchorBlock = clickedBlock;
            resolvedQuarterTurns = candidateQuarterTurns;
            return true;
        }

        return false;
    }

