                }

                anchorBlock = candidateAnchorBlock;
                resolvedQuarterTurns = candidateQuarterTurns;
                return true;
            }
        }

        return false;
    }

    private bool TryResolveBoilerPipeConnectionInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        bool includeIgnoredPreviewAsConnector,
        bool allowRotationSearch,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsBoilerSource(footprintSource)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        MapObject connectorPreviewToIgnore = includeIgnoredPreviewAsConnector ? null : previewToIgnore;
        int candidateCount = allowRotationSearch ? GetPlacementRotationCandidateCount(footprintSource) : 1;
        bool foundCandidate = false;
        int bestScore = int.MaxValue;
        Block bestAnchorBlock = null;
        int bestQuarterTurns = resolvedQuarterTurns;
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                footprintSource,
                preferredQuarterTurns + (allowRotationSearch ? offset : 0));

            TryConsiderBoilerPipeConnectionAnchor(
                clickedBlock,
                footprintSource,
                candidateQuarterTurns,
                previewToIgnore,
                connectorPreviewToIgnore,
                includeIgnoredPreviewAsConnector,
                0,
                ref foundCandidate,
                ref bestScore,
                ref bestAnchorBlock,
                ref bestQuarterTurns);

            TryConsiderBoilerPipeFlushConnectionAnchors(
                clickedBlock,
                terrain,
                footprintSource,
                candidateQuarterTurns,
                previewToIgnore,
                connectorPreviewToIgnore,
                includeIgnoredPreviewAsConnector,
                ref foundCandidate,
                ref bestScore,
                ref bestAnchorBlock,
                ref bestQuarterTurns);

            for (int placementIndex = 0; placementIndex < placements.Count; placementIndex++)
            {
                InputOutputModule.RectGridBlockPlacement placement = placements[placementIndex];
                if (!IsPipePassBlockType(placement.blockType)
                    || placement.x < 0
                    || placement.x >= rectGridWidth
                    || placement.y < 0
                    || placement.y >= rectGridHeight)
                {
                    continue;
                }

                Vector2Int localOffset = new Vector2Int(
                    placement.x - objectAnchorCell.x,
                    placement.y - objectAnchorCell.y);
                Vector2Int candidateAnchorCoordinate =
                    clickedBlock.Coordinate - RotateFootprintOffset(localOffset, candidateQuarterTurns);
                if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                    || candidateAnchorBlock == null)
                {
                    continue;
                }

                TryConsiderBoilerPipeConnectionAnchor(
                    candidateAnchorBlock,
                    footprintSource,
                    candidateQuarterTurns,
                    previewToIgnore,
                    connectorPreviewToIgnore,
                    includeIgnoredPreviewAsConnector,
                    1 + Mathf.Abs(localOffset.x) + Mathf.Abs(localOffset.y),
                    ref foundCandidate,
                    ref bestScore,
                    ref bestAnchorBlock,
                    ref bestQuarterTurns);
            }
        }

        if (!foundCandidate)
        {
            return false;
        }

        anchorBlock = bestAnchorBlock;
        resolvedQuarterTurns = bestQuarterTurns;
        return anchorBlock != null;
    }

    private void TryConsiderBoilerPipeFlushConnectionAnchors(
        Block clickedBlock,
        TerrainGenerator terrain,
        MapObject footprintSource,
        int candidateQuarterTurns,
        MapObject previewToIgnore,
        MapObject connectorPreviewToIgnore,
        bool includeIgnoredPreviewAsConnector,
        ref bool foundCandidate,
        ref int bestScore,
        ref Block bestAnchorBlock,
        ref int bestQuarterTurns)
    {
        if (clickedBlock == null || terrain == null || !IsBoilerSource(footprintSource))
        {
            return;
        }

        for (int pipeSearchIndex = 0; pipeSearchIndex <= PipeCardinalDirections.Length; pipeSearchIndex++)
        {
            Vector2Int pipeCoordinate = pipeSearchIndex == 0
                ? clickedBlock.Coordinate
                : clickedBlock.Coordinate + PipeCardinalDirections[pipeSearchIndex - 1];
            if (!TryGetPipePlacementAtCoordinate(pipeCoordinate, connectorPreviewToIgnore, out _, out _))
            {
                continue;
            }

            for (int directionIndex = 0; directionIndex < PipeCardinalDirections.Length; directionIndex++)
            {
                Vector2Int directionFromPipeToBody = PipeCardinalDirections[directionIndex];
                Vector2Int candidateAnchorCoordinate = pipeCoordinate + directionFromPipeToBody;
                if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                    || candidateAnchorBlock == null
                    || !TryGetBoilerPipePassDirectionAtCoordinate(
                        footprintSource,
                        candidateAnchorCoordinate,
                        candidateQuarterTurns,
                        pipeCoordinate,
                        out Vector2Int pipePassDirection)
                    || pipePassDirection != directionFromPipeToBody)
                {
                    continue;
                }

                int score = 1
                    + Mathf.Abs(candidateAnchorCoordinate.x - clickedBlock.Coordinate.x)
                    + Mathf.Abs(candidateAnchorCoordinate.y - clickedBlock.Coordinate.y);
                TryConsiderBoilerPipeConnectionAnchor(
                    candidateAnchorBlock,
                    footprintSource,
                    candidateQuarterTurns,
                    previewToIgnore,
                    connectorPreviewToIgnore,
                    includeIgnoredPreviewAsConnector,
                    score,
                    ref foundCandidate,
                    ref bestScore,
                    ref bestAnchorBlock,
                    ref bestQuarterTurns);
            }
        }
    }

    private void TryConsiderBoilerPipeConnectionAnchor(
        Block candidateAnchorBlock,
        MapObject footprintSource,
        int candidateQuarterTurns,
        MapObject previewToIgnore,
        MapObject connectorPreviewToIgnore,
        bool includeIgnoredPreviewAsConnector,
        int score,
        ref bool foundCandidate,
        ref int bestScore,
        ref Block bestAnchorBlock,
        ref int bestQuarterTurns)
    {
        if (candidateAnchorBlock == null
            || !PlacementHasRectGridObjectCoordinate(
                candidateAnchorBlock.Coordinate,
                footprintSource,
                candidateQuarterTurns,
                candidateAnchorBlock.Coordinate)
            || PlacementHasBoilerEnergyInputPipeConflict(
                candidateAnchorBlock.Coordinate,
                footprintSource,
                candidateQuarterTurns,
                previewToIgnore)
            || !BoilerPlacementHasCompatiblePipePassPipeConnection(
                candidateAnchorBlock.Coordinate,
                footprintSource,
                candidateQuarterTurns,
                connectorPreviewToIgnore)
            || !CanPlacePreviewOnBlock(
                candidateAnchorBlock,
                previewToIgnore,
                candidateQuarterTurns,
                includeIgnoredPreviewAsConnector))
        {
            return;
        }

        if (foundCandidate && score >= bestScore)
        {
            return;
        }

        foundCandidate = true;
        bestScore = score;
        bestAnchorBlock = candidateAnchorBlock;
        bestQuarterTurns = candidateQuarterTurns;
    }

    private bool BoilerPlacementHasCompatiblePipePassPipeConnection(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (!IsBoilerSource(footprintSource)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (placements == null || placements.Count <= 0)
        {
            return false;
        }

        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate,
            quarterTurns = quarterTurns
        };

        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (!IsPipePassBlockType(placement.blockType)
                || !TryGetRectGridCoordinate(
                    anchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    placement,
                    out Vector2Int pipePassCoordinate))
            {
                continue;
            }

            PipeAreaBlockCandidate proposedCandidate =
                new PipeAreaBlockCandidate(proposedSnapshot, placement.blockType);
            if (BoilerPipePassCanConnectPipeAtCoordinate(
                pipePassCoordinate,
                proposedCandidate,
                previewToIgnore))
            {
                return true;
            }
        }

        return false;
    }

    private bool BoilerPipePassCanConnectPipeAtCoordinate(
        Vector2Int pipePassCoordinate,
        PipeAreaBlockCandidate proposedCandidate,
        MapObject previewToIgnore)
    {
        List<Vector2Int> requiredPipeDirections = new List<Vector2Int>(4);
        if (!TryGetPipePlacementAtCoordinate(
                pipePassCoordinate,
                previewToIgnore,
                out Pipe pipe,
                out Quaternion pipeRotation))
        {
            return false;
        }

        if (!TryGetProposedPipeAreaPipeConnectionDirections(
                pipePassCoordinate,
                proposedCandidate,
                pipePassCoordinate,
                requiredPipeDirections))
        {
            return false;
        }

        for (int directionIndex = 0; directionIndex < requiredPipeDirections.Count; directionIndex++)
        {
            Vector2Int requiredDirection = requiredPipeDirections[directionIndex];
            if (requiredDirection == Vector2Int.zero)
            {
                continue;
            }

            if (TryResolvePipeVariantForForcedConnection(
                    pipePassCoordinate,
                    pipe,
                    pipeRotation,
                    requiredDirection,
                    out Pipe resolvedPipe,
                    out Quaternion resolvedPipeRotation)
                && PipeAreaCandidateFluidMatchesPipeNetwork(
                    pipePassCoordinate,
                    resolvedPipe,
                    resolvedPipeRotation,
                    pipePassCoordinate,
                    proposedCandidate,
                    previewToIgnore))
            {
                return true;
            }
        }

        return false;
    }

    private List<PipeAreaBlockCandidate> CollectPipePassCandidatesAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore)
    {
        List<PipeAreaBlockCandidate> pipePassCandidates = new List<PipeAreaBlockCandidate>(2);
        pipeAreaBlockCandidateScratchA.Clear();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
            coordinate,
            previewToIgnore,
            pipeAreaBlockCandidateScratchA);

        for (int i = 0; i < pipeAreaBlockCandidateScratchA.Count; i++)
        {
            PipeAreaBlockCandidate candidate = pipeAreaBlockCandidateScratchA[i];
            if (IsPipePassBlockType(candidate.blockType))
            {
                pipePassCandidates.Add(candidate);
            }
        }

        pipeAreaBlockCandidateScratchA.Clear();
        return pipePassCandidates;
    }

    private bool HasBoilerPipePassAtCoordinate(Vector2Int coordinate, MapObject previewToIgnore)
    {
        List<PipeAreaBlockCandidate> pipePassCandidates = CollectPipePassCandidatesAtCoordinate(
            coordinate,
            previewToIgnore);
        for (int i = 0; i < pipePassCandidates.Count; i++)
        {
            PipeAreaBlockCandidate candidate = pipePassCandidates[i];
            if (candidate.snapshot != null && IsBoilerSource(candidate.snapshot.mapObject))
            {
                return true;
            }
        }

        return false;
    }

    private bool TryFindPlaceableItemAreaOverlapInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        if (clickedBlock == null
            || !CoordinateHasInputOutputAreaForPlacement(clickedBlock.Coordinate, null)
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !TryGetRectGridFootprintSettings(footprintSource, out int rectGridWidth, out int rectGridHeight, out Vector2Int objectAnchorCell)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        for (int offset = 0; offset < 4; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns + offset);
            for (int i = 0; i < placements.Count; i++)
            {
                InputOutputModule.RectGridBlockPlacement placement = placements[i];
                bool canUsePlacementForAreaOverlap = IsRectGridAreaBlockType(placement.blockType)
                    || CanUseObjectPlacementForFluidStorageAreaOverlap(
                        footprintSource,
                        placement.blockType,
                        clickedBlock.Coordinate);
                if (!canUsePlacementForAreaOverlap
                    || placement.x < 0
                    || placement.x >= rectGridWidth
                    || placement.y < 0
                    || placement.y >= rectGridHeight)
                {
                    continue;
                }

                Vector2Int localOffset = new Vector2Int(placement.x - objectAnchorCell.x, placement.y - objectAnchorCell.y);
                Vector2Int candidateAnchorCoordinate =
                    clickedBlock.Coordinate - RotateFootprintOffset(localOffset, candidateQuarterTurns);
                if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                    || candidateAnchorBlock == null
                    || PlacementHasBoilerEnergyInputPipeConflict(
                        candidateAnchorCoordinate,
                        footprintSource,
                        candidateQuarterTurns,
                        previewToIgnore)
                    || PlacementHasNormalInputOutputAreaPipeOverlap(
                        candidateAnchorCoordinate,
                        footprintSource,
                        candidateQuarterTurns,
                        previewToIgnore)
                    || !CanPlacePreviewOnBlock(candidateAnchorBlock, previewToIgnore, candidateQuarterTurns))
                {
                    continue;
                }

                anchorBlock = candidateAnchorBlock;
                resolvedQuarterTurns = candidateQuarterTurns;
                return true;
            }
        }

        return false;
    }

    private bool TryFindPlaceableMultiCellInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !HasMultiCellMapSize(footprintSource)
            || IsBelt2F(footprintSource))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizeInstallPreviewQuarterTurns(
                previewToIgnore,
                resolvedQuarterTurns + offset);
            List<Vector2Int> localOffsets = GetFootprintLocalOffsets(footprintSource, candidateQuarterTurns);
            if (localOffsets.Count <= 1)
            {
                continue;
            }

            for (int i = 0; i < localOffsets.Count; i++)
            {
                Vector2Int localOffset = localOffsets[i];
                if (localOffset == Vector2Int.zero)
                {
                    continue;
                }

                Vector2Int candidateAnchorCoordinate = clickedBlock.Coordinate - localOffset;
                if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                    || candidateAnchorBlock == null
                    || PlacementHasBoilerEnergyInputPipeConflict(
                        candidateAnchorCoordinate,
                        footprintSource,
                        candidateQuarterTurns,
                        previewToIgnore)
                    || PlacementHasNormalInputOutputAreaPipeOverlap(
                        candidateAnchorCoordinate,
                        footprintSource,
                        candidateQuarterTurns,
                        previewToIgnore)
                    || !CanPlacePreviewOnBlock(candidateAnchorBlock, previewToIgnore, candidateQuarterTurns))
                {
                    continue;
                }

                anchorBlock = candidateAnchorBlock;
                resolvedQuarterTurns = candidateQuarterTurns;
                return true;
            }
        }

        return false;
    }

    private bool TryResolveInstallPreviewFootprintSourceForPlacement(MapObject previewToIgnore, out MapObject footprintSource)
    {
        footprintSource = null;
        if (previewToIgnore != null)
        {
            footprintSource = ResolveInstallPreviewFootprintSource(previewToIgnore) ?? previewToIgnore;
            return footprintSource != null;
        }

        footprintSource = activeInstallDefinition != null ? activeInstallDefinition.mapObject : null;
        return footprintSource != null;
    }

    private bool PlacementHasNormalInputOutputAreaPipeOverlap(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (footprintSource == null
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (!IsNormalInputOutputAreaBlockType(placement.blockType)
                || placement.x < 0
                || placement.x >= rectGridWidth
                || placement.y < 0
                || placement.y >= rectGridHeight)
            {
                continue;
            }

            Vector2Int localOffset = new Vector2Int(
                placement.x - objectAnchorCell.x,
                placement.y - objectAnchorCell.y);
            Vector2Int coordinate = anchorCoordinate + RotateFootprintOffset(localOffset, quarterTurns);
            if (!terrain.TryGetLoadedBlock(coordinate, out Block block) || block == null)
            {
                continue;
            }

            if (IsInstallGridSimpleClearCell(block, footprintSource, previewToIgnore))
            {
                continue;
            }

            MapObject occupyingObject = GetOccupyingObjectForPlacement(block, previewToIgnore);

            if (TryGetPipePlacementAtBlock(block, occupyingObject, out _, out _))
            {
                return true;
            }

            if (TryGetInstallPreviewAtCoordinate(coordinate, out MapObject existingPreview)
                && existingPreview != null
                && existingPreview != previewToIgnore
                && IsPipePlacementSource(existingPreview))
            {
                return true;
            }
        }

        return false;
    }

    private bool PlacementHasBoilerEnergyInputPipeConflict(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (!IsBoilerSource(footprintSource)
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (placements == null || placements.Count <= 0)
        {
            return false;
        }

        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (!InputOutputModule.IsInputEnergyBlockType(placement.blockType)
                || placement.x < 0
                || placement.x >= rectGridWidth
                || placement.y < 0
                || placement.y >= rectGridHeight)
            {
                continue;
            }

            Vector2Int localOffset = new Vector2Int(
                placement.x - objectAnchorCell.x,
                placement.y - objectAnchorCell.y);
            Vector2Int energyCoordinate = anchorCoordinate + RotateFootprintOffset(localOffset, quarterTurns);
            if (TryGetPipePlacementAtCoordinate(energyCoordinate, previewToIgnore, out _, out _)
                || BoilerEnergyInputHasIncomingPipeConnection(energyCoordinate, previewToIgnore))
            {
                return true;
            }
        }

        return false;
    }

    private bool CanUseBoilerEnergyInputRotationCandidate(
        Vector2Int anchorCoordinate,
        MapObject previewToIgnore,
        int quarterTurns)
    {
        return !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
               || !IsBoilerSource(footprintSource)
               || !PlacementHasBoilerEnergyInputPipeConflict(
                   anchorCoordinate,
                   footprintSource,
                   quarterTurns,
                   previewToIgnore);
    }

    private bool BoilerEnergyInputHasIncomingPipeConnection(Vector2Int energyCoordinate, MapObject previewToIgnore)
    {
        for (int i = 0; i < PipeCardinalDirections.Length; i++)
        {
            Vector2Int directionToPipe = PipeCardinalDirections[i];
            Vector2Int pipeCoordinate = energyCoordinate + directionToPipe;
            Vector2Int directionToEnergyInput = -directionToPipe;
            if (TryGetPipePlacementAtCoordinate(
                    pipeCoordinate,
                    previewToIgnore,
                    out Pipe pipe,
                    out Quaternion pipeRotation)
                && HasEffectivePipeConnectionTowardsAt(
                    pipeCoordinate,
                    pipe,
                    pipeRotation,
                    directionToEnergyInput))
            {
                return true;
            }
        }

        return false;
    }

    private bool TryGetPipePlacementAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out Pipe pipe,
        out Quaternion pipeRotation)
    {
        pipe = null;
        pipeRotation = Quaternion.identity;

        if (TryGetInstallPreviewAtCoordinate(coordinate, out MapObject preview)
            && preview != null
            && preview != previewToIgnore)
        {
            MapObject previewSource = ResolveInstallPreviewFootprintSource(preview) ?? preview;
            pipe = preview as Pipe ?? previewSource as Pipe;
            if (pipe != null)
            {
                pipeRotation = preview.transform.rotation;
                return true;
            }
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain != null
            && terrain.TryGetLoadedBlock(coordinate, out Block block)
            && block != null
            && TryGetPipePlacementAtBlock(
                block,
                GetOccupyingObjectForPlacement(block, previewToIgnore),
                out pipe,
                out pipeRotation))
        {
            ApplyVirtualInstalledPipeResolution(ref pipe, ref pipeRotation);
            return true;
        }

        if (TryGetSavedPipePlacementAtCoordinate(
                coordinate,
                out Pipe savedPipe,
                out Quaternion savedRotation))
        {
            pipe = savedPipe;
            pipeRotation = savedRotation;
            return true;
        }

        return false;
    }

    private void ApplyVirtualInstalledPipeResolution(
        ref Pipe pipe,
        ref Quaternion pipeRotation)
    {
        if (!isResolvingInstalledPipeVariantPreviewPlans
            || pipe == null
            || !installedPipeVariantResolutionOverrides.TryGetValue(
                pipe,
                out InstalledPipeVariantPreviewPlan virtualPlan)
            || !(virtualPlan.sourcePrefab is Pipe virtualPipe))
        {
            return;
        }

        pipe = virtualPipe;
        pipeRotation = virtualPlan.rotation;
    }

    private bool IsPipePlacementSource(MapObject mapObject)
    {
        MapObject source = ResolveInstallPreviewFootprintSource(mapObject) ?? mapObject;
        return source is Pipe;
    }

    private bool CoordinateHasNormalInputOutputAreaBlockForPlacement(
        Vector2Int coordinate,
        MapObject previewToIgnore)
    {
        return CoordinateHasPlacementAreaBlock(
            coordinate,
            previewToIgnore,
            PlacementAreaBlockKind.Normal);
    }

    private bool CoordinateHasInputItemAreaBlockForPlacement(
        Vector2Int coordinate,
        MapObject previewToIgnore)
    {
        return CoordinateHasPlacementAreaBlock(
            coordinate,
            previewToIgnore,
            PlacementAreaBlockKind.InputItem);
    }

    private bool CoordinateHasBoilerEnergyInputBlockForPlacement(
        Vector2Int coordinate,
        MapObject previewToIgnore)
    {
        return CoordinateHasPlacementAreaBlock(
            coordinate,
            previewToIgnore,
            PlacementAreaBlockKind.BoilerEnergyInput);
    }

    private bool CoordinateHasPlacementAreaBlock(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        PlacementAreaBlockKind areaKind)
    {
        if (RegisteredCoordinateMatchesPlacementArea(coordinate, areaKind))
        {
            return true;
        }

        if (TryGetPreviewPlacementSnapshot(coordinate, previewToIgnore, out PlacementSnapshot previewSnapshot)
            && SnapshotMatchesPlacementArea(previewSnapshot, coordinate, areaKind))
        {
            return true;
        }

        if (TryGetInstalledPlacementSnapshot(coordinate, out PlacementSnapshot installedSnapshot)
            && SnapshotMatchesPlacementArea(installedSnapshot, coordinate, areaKind))
        {
            return true;
        }

        runtimeGridModuleScratch.Clear();
        if (InputOutputModule.CollectModulesAtRuntimeGridCoordinate(coordinate, runtimeGridModuleScratch))
        {
            for (int i = 0; i < runtimeGridModuleScratch.Count; i++)
            {
                if (TryGetRuntimeModulePlacementSnapshot(
                        runtimeGridModuleScratch[i],
                        out PlacementSnapshot runtimeGridSnapshot)
                    && SnapshotMatchesPlacementArea(runtimeGridSnapshot, coordinate, areaKind))
                {
                    runtimeGridModuleScratch.Clear();
                    return true;
                }
            }

            runtimeGridModuleScratch.Clear();
        }
        else if (TryGetRuntimeGridPlacementSnapshot(coordinate, out PlacementSnapshot runtimeGridSnapshot)
                 && SnapshotMatchesPlacementArea(runtimeGridSnapshot, coordinate, areaKind))
        {
            return true;
        }

        runtimeAreaModuleScratch.Clear();
        if (InputOutputModule.CollectModulesAtRuntimeAreaCoordinate(coordinate, runtimeAreaModuleScratch))
        {
            for (int i = 0; i < runtimeAreaModuleScratch.Count; i++)
            {
                if (TryGetRuntimeModulePlacementSnapshot(
                        runtimeAreaModuleScratch[i],
                        out PlacementSnapshot runtimeAreaSnapshot)
                    && SnapshotMatchesPlacementArea(runtimeAreaSnapshot, coordinate, areaKind))
                {
                    runtimeAreaModuleScratch.Clear();
                    return true;
                }
            }

            runtimeAreaModuleScratch.Clear();
        }
        else if (TryGetRuntimeAreaPlacementSnapshot(coordinate, out PlacementSnapshot runtimeAreaSnapshot)
                 && SnapshotMatchesPlacementArea(runtimeAreaSnapshot, coordinate, areaKind))
        {
            return true;
        }

        return TryGetSavedPlacementSnapshot(coordinate, out PlacementSnapshot savedSnapshot)
               && SnapshotMatchesPlacementArea(savedSnapshot, coordinate, areaKind);
    }

    private static bool RegisteredCoordinateMatchesPlacementArea(
        Vector2Int coordinate,
        PlacementAreaBlockKind areaKind)
    {
        return areaKind switch
        {
            PlacementAreaBlockKind.Normal =>
                InputOutputModuleEnergyAreaController.CoordinateIsEnergyArea(coordinate)
                || InputOutputModuleItemAreaController.CoordinateIsItemArea(coordinate)
                || InputOutputModuleOutputAreaController.CoordinateIsOutputArea(coordinate),
            PlacementAreaBlockKind.InputItem =>
                InputOutputModuleItemAreaController.CoordinateIsItemArea(coordinate)
                || InputOutputModule.CoordinateIsRuntimeInputItemBlock(coordinate),
            _ => false
        };
    }

    private bool SnapshotMatchesPlacementArea(
        PlacementSnapshot snapshot,
        Vector2Int coordinate,
        PlacementAreaBlockKind areaKind)
    {
        if (snapshot == null
            || snapshot.mapObject == null
            || (areaKind == PlacementAreaBlockKind.BoilerEnergyInput
                && !IsBoilerSource(snapshot.mapObject)))
        {
            return false;
        }

        MapObject footprintSource = ResolveInstallPreviewFootprintSource(snapshot.mapObject) ?? snapshot.mapObject;
        return TryGetRectGridFootprintBlockType(
                   snapshot.anchorCoordinate,
                   footprintSource,
                   snapshot.quarterTurns,
                   coordinate,
                   out InputOutputModule.RectGridBlockType blockType)
               && (areaKind switch
                   {
                       PlacementAreaBlockKind.Normal => IsNormalInputOutputAreaBlockType(blockType),
                       PlacementAreaBlockKind.InputItem => InputOutputModule.IsInputItemBlockType(blockType),
                       PlacementAreaBlockKind.BoilerEnergyInput => InputOutputModule.IsInputEnergyBlockType(blockType),
                       _ => false
                   });
    }

    private enum PlacementAreaBlockKind
    {
        Normal,
        InputItem,
        BoilerEnergyInput
    }

    private static bool IsNormalInputOutputAreaBlockType(InputOutputModule.RectGridBlockType blockType)
    {
        return InputOutputModule.AllowsDirectAreaInteraction(blockType)
               && !InputOutputModule.AllowsPipeAreaInteraction(blockType);
    }

    private bool CoordinateHasInputOutputAreaForPlacement(Vector2Int coordinate, MapObject previewToIgnore)
    {
        if (InputOutputModuleEnergyAreaController.CoordinateIsEnergyArea(coordinate)
            || InputOutputModuleItemAreaController.CoordinateIsItemArea(coordinate)
            || InputOutputModuleOutputAreaController.CoordinateIsOutputArea(coordinate)
            || InputOutputModule.CoordinateIsRuntimeInputOutputAreaBlock(coordinate)
            || HasPipeAreaFluidStorageAtCoordinate(coordinate)
            || IsPumpOutputCoordinateForPlacement(coordinate))
        {
            return true;
        }

        CleanupInstallPreviewReferences();
        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            MapObject preview = installPreviewInstances[i];
            if (preview == null
                || preview == previewToIgnore
                || !TryGetPreviewAnchorCoordinate(preview, out Vector2Int previewAnchorCoordinate))
            {
                continue;
            }

            MapObject previewFootprintSource = ResolveInstallPreviewFootprintSource(preview);
            if (IsRectGridAreaBlockType(GetRectGridBlockTypeAtCoordinate(
                    previewAnchorCoordinate,
                    previewFootprintSource,
                    GetPreviewAreaQuarterTurns(preview),
                    coordinate)))
            {
                return true;
            }
        }

        return false;
    }

    private bool CanUseObjectPlacementForFluidStorageAreaOverlap(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType blockType,
        Vector2Int coordinate)
    {
        return blockType == InputOutputModule.RectGridBlockType.Object
               && TryResolveInstallationObject(footprintSource, out InstallationObject installationObject)
               && installationObject.CanStoreFluid
               && !(installationObject is Pipe)
               && !(installationObject is Pump)
               && !IsSteamGeneratorSource(footprintSource)
               && !(IsBoilerSource(footprintSource) && IsPumpOutputCoordinateForPlacement(coordinate))
               && (IsPumpOutputCoordinateForPlacement(coordinate)
                   || HasPipeAreaFluidStorageAtCoordinate(coordinate));
    }

    private bool IsConveyorInstallPreview(MapObject previewToIgnore)
    {
        if (IsBelt2F(previewToIgnore)
            || (activeInstallDefinition != null && IsBelt2F(activeInstallDefinition.mapObject)))
        {
            return false;
        }

        if (previewToIgnore is ConveyorBelt)
        {
            return true;
        }

        return activeInstallDefinition != null && activeInstallDefinition.mapObject is ConveyorBelt;
    }

    private bool TryGetInstallPreviewAtCoordinate(Vector2Int coordinate, out MapObject preview)
    {
        preview = null;
        CleanupInstallPreviewReferences();
        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            MapObject candidate = installPreviewInstances[i];
            if (candidate == null)
            {
                continue;
            }

            if (InstallPreviewContainsCoordinateNoAlloc(candidate, coordinate))
            {
                preview = candidate;
                return true;
            }
        }

        return false;
    }

    private bool InstallPreviewContainsCoordinateNoAlloc(MapObject preview, Vector2Int coordinate)
    {
        if (preview == null || !TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate))
        {
            return false;
        }

        if (preview is UndergroundPipe undergroundPipe
            && undergroundPipe.TryGetPreviewCandidateCoordinates(
                out Vector2Int firstEndpoint,
                out Vector2Int secondEndpoint))
        {
            return coordinate == firstEndpoint || coordinate == secondEndpoint;
        }

        MapObject footprintSource = ResolveInstallPreviewFootprintSource(preview) ?? preview;
        int quarterTurns = GetPreviewAreaQuarterTurns(preview);
        if (TryGetRectGridFootprintSettings(
                footprintSource,
                out _,
                out _,
                out _))
        {
            return TryGetRectGridFootprintBlockType(
                       anchorCoordinate,
                       footprintSource,
                       quarterTurns,
                       coordinate,
                       out InputOutputModule.RectGridBlockType blockType)
                   && blockType != InputOutputModule.RectGridBlockType.None;
        }

        int sizeX = Mathf.Max(1, footprintSource != null ? footprintSource.Status.mapSizeX : 1);
        int sizeY = Mathf.Max(1, footprintSource != null ? footprintSource.Status.mapSizeY : 1);
        if (IsBelt2F(footprintSource))
        {
            Vector2Int belt2FSize = GetBelt2FFootprintSize(footprintSource);
            sizeX = belt2FSize.x;
            sizeY = belt2FSize.y;
        }

        Vector2Int centerCell = GetFootprintAnchorCell(footprintSource);
        for (int y = 0; y < sizeY; y++)
        {
            for (int x = 0; x < sizeX; x++)
            {
                Vector2Int localOffset = new Vector2Int(x - centerCell.x, y - centerCell.y);
                if (anchorCoordinate + RotateFootprintOffset(localOffset, quarterTurns) == coordinate)
                {
                    return true;
                }
            }
        }

        return false;
    }

    private bool TryGetPreviewAnchorCoordinate(MapObject preview, out Vector2Int anchorCoordinate)
    {
        anchorCoordinate = Vector2Int.zero;
        return preview != null && installPreviewAnchorCoordinates.TryGetValue(preview, out anchorCoordinate);
    }

    private MapObject ResolveInstallPreviewFootprintSource(MapObject preview)
    {
        if (preview != null
            && installPreviewSourcePrefabsByPreview.TryGetValue(preview, out MapObject sourcePrefab)
            && sourcePrefab != null)
        {
            return sourcePrefab;
        }

        return preview;
    }

    private MapObject ResolveInstallPreviewPlacementSource(MapObject preview)
    {
        return ResolveInstallPreviewFootprintSource(preview) ?? preview;
    }

    private bool CanOverlapCompatibleInstallPreview(
        Vector2Int coordinate,
        MapObject candidateFootprintSource,
        InputOutputModule.RectGridBlockType candidateBlockType,
        Vector2Int candidateAnchorCoordinate,
        int candidateQuarterTurns,
        MapObject existingPreview)
    {
        if (existingPreview == null
            || !TryGetPreviewAnchorCoordinate(existingPreview, out Vector2Int existingAnchorCoordinate))
        {
            return false;
        }

        MapObject existingFootprintSource = ResolveInstallPreviewFootprintSource(existingPreview);
        int existingQuarterTurns = GetPreviewQuarterTurns(existingPreview);
        return CanOverlapCompatiblePlacementItemAreas(
            coordinate,
            candidateFootprintSource,
            candidateBlockType,
            candidateAnchorCoordinate,
            candidateQuarterTurns,
            existingFootprintSource,
            GetRectGridBlockTypeAtCoordinate(
                existingAnchorCoordinate,
                existingFootprintSource,
                existingQuarterTurns,
                coordinate),
            existingAnchorCoordinate,
            existingQuarterTurns);
    }

    private List<Vector2Int> GetFootprintCoordinates(Vector2Int anchorCoordinate, MapObject footprintSource, int quarterTurns)
    {
        List<Vector2Int> offsets = GetFootprintLocalOffsets(footprintSource, quarterTurns);
        List<Vector2Int> coordinates = new List<Vector2Int>(offsets.Count);
        for (int i = 0; i < offsets.Count; i++)
        {
            coordinates.Add(anchorCoordinate + offsets[i]);
        }

        return coordinates;
    }

    private List<Vector2Int> GetPlacementValidationCoordinates(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns)
    {
        List<Vector2Int> rectGridCoordinates = GetRectGridPlacementCoordinates(
            anchorCoordinate,
            footprintSource,
            quarterTurns);
        return rectGridCoordinates.Count > 0
            ? rectGridCoordinates
            : GetFootprintCoordinates(anchorCoordinate, footprintSource, quarterTurns);
    }

    private List<Vector2Int> GetInstallPreviewAreaDisplayCoordinates(
        MapObject preview,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        if (preview is UndergroundPipe undergroundPipe
            && undergroundPipe.TryGetPreviewCandidateCoordinates(
                out Vector2Int firstEndpoint,
                out Vector2Int secondEndpoint))
        {
            return new List<Vector2Int>(2) { firstEndpoint, secondEndpoint };
        }

        MapObject footprintSource = ResolveInstallPreviewPlacementSource(preview);
        if (TryGetTransformBasedInstallPreviewAreaDisplayCoordinates(
                preview,
                footprintSource,
                quarterTurns,
                out List<Vector2Int> transformBasedCoordinates))
        {
            return transformBasedCoordinates;
        }

        List<Vector2Int> rectGridCoordinates = GetRectGridPlacementCoordinates(
            anchorCoordinate,
            footprintSource,
            quarterTurns);
        return rectGridCoordinates.Count > 0
            ? rectGridCoordinates
            : GetFootprintCoordinates(anchorCoordinate, footprintSource, quarterTurns);
    }

    private bool TryGetTransformBasedInstallPreviewAreaDisplayCoordinates(
        MapObject preview,
        MapObject footprintSource,
        int fallbackQuarterTurns,
        out List<Vector2Int> coordinates)
    {
        coordinates = null;
        if (preview == null || footprintSource == null)
        {
            return false;
        }

        int quarterTurns = fallbackQuarterTurns;

        if (!TryResolveInstallPreviewAnchorCoordinateFromTransform(
                preview,
                footprintSource,
                quarterTurns,
                out Vector2Int transformAnchorCoordinate))
        {
            return false;
        }

        List<Vector2Int> rectGridCoordinates = GetRectGridPlacementCoordinates(
            transformAnchorCoordinate,
            footprintSource,
            quarterTurns);
        if (rectGridCoordinates.Count > 0)
        {
            coordinates = rectGridCoordinates;
            return true;
        }

        List<Vector2Int> footprintCoordinates = GetFootprintCoordinates(
            transformAnchorCoordinate,
            footprintSource,
            quarterTurns);
        if (footprintCoordinates.Count <= 0)
        {
            return false;
        }

        coordinates = footprintCoordinates;
        return true;
    }

    private bool TryResolveInstallPreviewAnchorCoordinateFromTransform(
        MapObject preview,
        MapObject footprintSource,
        int quarterTurns,
        out Vector2Int anchorCoordinate)
    {
        anchorCoordinate = Vector2Int.zero;
        if (preview == null || footprintSource == null)
        {
            return false;
        }

        Vector2 averageObjectOffset = GetAverageLocalOffset(GetPlacementVisualLocalOffsets(footprintSource, quarterTurns));
        anchorCoordinate = new Vector2Int(
            RoundGridCoordinate(preview.transform.position.x - averageObjectOffset.x),
            RoundGridCoordinate(preview.transform.position.z - averageObjectOffset.y));
        return true;
    }

    private List<Vector2Int> GetRectGridPlacementCoordinates(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns)
    {
        List<Vector2Int> coordinates = new List<Vector2Int>();
        List<RectGridPlacementCell> cells = new List<RectGridPlacementCell>();
        if (!TryBuildRectGridPlacementCells(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                null,
                cells))
        {
            return coordinates;
        }

        HashSet<Vector2Int> occupiedCoordinates = new HashSet<Vector2Int>();
        for (int i = 0; i < cells.Count; i++)
        {
            Vector2Int coordinate = cells[i].coordinate;
            if (occupiedCoordinates.Add(coordinate))
            {
                coordinates.Add(coordinate);
            }
        }

        return coordinates;
    }

    private List<Vector2Int> GetFootprintLocalOffsets(MapObject footprintSource, int quarterTurns)
    {
        if (ShouldUseMapSizeFootprint(footprintSource))
        {
            return GetMapSizeFootprintLocalOffsets(footprintSource, quarterTurns);
        }

        List<RectGridPlacementCell> cells = new List<RectGridPlacementCell>();
        if (TryBuildRectGridPlacementCells(
                Vector2Int.zero,
                footprintSource,
                quarterTurns,
                null,
                cells))
        {
            List<Vector2Int> rectGridOffsets = new List<Vector2Int>(cells.Count);
            HashSet<Vector2Int> occupiedOffsets = new HashSet<Vector2Int>();

            for (int i = 0; i < cells.Count; i++)
            {
                Vector2Int rotatedOffset = cells[i].rotatedOffset;
                if (occupiedOffsets.Add(rotatedOffset))
                {
                    rectGridOffsets.Add(rotatedOffset);
                }
            }

            if (rectGridOffsets.Count > 0)
            {
                return rectGridOffsets;
            }
        }

        return GetMapSizeFootprintLocalOffsets(footprintSource, quarterTurns);
    }

    private static bool ShouldUseMapSizeFootprint(MapObject footprintSource)
    {
        return footprintSource is InstallationObject installationObject
               && installationObject.CanStoreFluid
               && !(installationObject is Pipe)
               && !(installationObject is Pump);
    }

    private List<Vector2Int> GetMapSizeFootprintLocalOffsets(MapObject footprintSource, int quarterTurns)
    {
        int sizeX = 1;
        int sizeY = 1;
        if (footprintSource != null)
        {
            sizeX = Mathf.Max(1, footprintSource.Status.mapSizeX);
            sizeY = Mathf.Max(1, footprintSource.Status.mapSizeY);
            if (IsBelt2F(footprintSource))
            {
                Vector2Int belt2FSize = GetBelt2FFootprintSize(footprintSource);
                sizeX = belt2FSize.x;
                sizeY = belt2FSize.y;
            }
        }

        Vector2Int centerCell = GetFootprintAnchorCell(footprintSource);
        List<Vector2Int> offsets = new List<Vector2Int>(sizeX * sizeY);
        for (int y = 0; y < sizeY; y++)
        {
            for (int x = 0; x < sizeX; x++)
            {
                offsets.Add(RotateFootprintOffset(new Vector2Int(x - centerCell.x, y - centerCell.y), quarterTurns));
            }
        }

        return offsets;
    }

    private static bool HasMultiCellMapSize(MapObject footprintSource)
    {
        return footprintSource != null
            && (Mathf.Max(1, footprintSource.Status.mapSizeX) > 1
                || Mathf.Max(1, footprintSource.Status.mapSizeY) > 1);
    }

    private bool HasMultiCellPlacementFootprint(MapObject footprintSource)
    {
        if (HasMultiCellMapSize(footprintSource))
        {
            return true;
        }

        List<RectGridPlacementCell> cells = new List<RectGridPlacementCell>();
        if (!TryBuildRectGridPlacementCells(
                Vector2Int.zero,
                footprintSource,
                0,
                null,
                cells))
        {
            return false;
        }

        HashSet<Vector2Int> coordinates = new HashSet<Vector2Int>();
        for (int i = 0; i < cells.Count; i++)
        {
            coordinates.Add(cells[i].coordinate);
            if (coordinates.Count > 1)
            {
                return true;
            }
        }

        return false;
    }

    private static Vector2Int GetFootprintAnchorCell(MapObject footprintSource)
    {
        if (footprintSource == null)
        {
            return Vector2Int.zero;
        }

        return IsBelt2F(footprintSource)
            ? GetBelt2FAnchorCell(footprintSource)
            : footprintSource.PlacementCenterCell;
    }

    private static Vector2Int GetBelt2FAnchorCell(MapObject footprintSource)
    {
        Vector2Int size = GetBelt2FFootprintSize(footprintSource);
        Vector2Int centerCell = footprintSource != null
            ? footprintSource.PlacementCenterCell
            : Vector2Int.zero;
        return new Vector2Int(
            Mathf.Clamp(centerCell.x, 0, size.x - 1),
            Mathf.Clamp(centerCell.y, 0, size.y - 1));
    }

    private static Vector2Int GetBelt2FBridgeCenterCell(MapObject footprintSource)
    {
        return GetBelt2FAnchorCell(footprintSource);
    }

    private static Vector2Int GetBelt2FFootprintSize(MapObject footprintSource)
    {
        int sizeX = Mathf.Max(1, footprintSource != null ? footprintSource.Status.mapSizeX : 1);
        int sizeY = Mathf.Max(1, footprintSource != null ? footprintSource.Status.mapSizeY : 1);
        if (sizeX == 1 && sizeY == 1)
        {
            sizeX = Belt2FDefaultFootprintWidth;
            sizeY = Belt2FDefaultFootprintLength;
        }

        return new Vector2Int(sizeX, sizeY);
    }

    private static Vector2Int GetBelt2FBridgeCenterOffset(MapObject footprintSource, int quarterTurns)
    {
        return RotateFootprintOffset(
            GetBelt2FBridgeCenterCell(footprintSource) - GetBelt2FAnchorCell(footprintSource),
            quarterTurns);
    }

    private static Vector2Int GetBelt2FBridgeCenterCoordinate(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns)
    {
        return anchorCoordinate + GetBelt2FBridgeCenterOffset(footprintSource, quarterTurns);
    }

    private bool TryGetRectGridFootprintSettings(
        MapObject footprintSource,
        out int rectGridWidth,
        out int rectGridHeight,
        out Vector2Int objectAnchorCell)
    {
        rectGridWidth = 0;
        rectGridHeight = 0;
        objectAnchorCell = Vector2Int.zero;

        if (footprintSource == null)
        {
            return false;
        }

        InputOutputModule inputOutputModule = footprintSource as InputOutputModule;
        if (inputOutputModule == null)
        {
            inputOutputModule = footprintSource.GetComponent<InputOutputModule>();
        }

        if (inputOutputModule == null)
        {
            inputOutputModule = footprintSource.GetComponentInChildren<InputOutputModule>(true);
        }

        if (inputOutputModule == null || inputOutputModule.LayoutType != InputOutputModule.SlotLayoutType.RectGrid)
        {
            return false;
        }

        rectGridWidth = Mathf.Max(1, inputOutputModule.RectGridWidth);
        rectGridHeight = Mathf.Max(1, inputOutputModule.RectGridHeight);
        return TryGetRectGridObjectAnchorCell(inputOutputModule, footprintSource, out objectAnchorCell);
    }

    private bool TryGetRectGridObjectAnchorCell(
        InputOutputModule inputOutputModule,
        MapObject footprintSource,
        out Vector2Int objectAnchorCell)
    {
        objectAnchorCell = Vector2Int.zero;
        return inputOutputModule != null
               && inputOutputModule.TryGetRectGridObjectAnchorCell(footprintSource, out objectAnchorCell);
    }

    private static Vector2Int RotateFootprintOffset(Vector2Int offset, int quarterTurns)
    {
        return InputOutputModule.RotateRectGridOffset(offset, quarterTurns);
    }

    public bool CanPlaceInstalledObjectAt(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore = null,
        bool ignoreOtherPreviews = false)
    {
        return TryGetFootprintBlocks(
            anchorCoordinate,
            footprintSource,
            quarterTurns,
            previewToIgnore,
            out _,
            ignoreOtherPreviews);
    }

    public bool CanCollectInstalledBucketToHand(Bucket bucket, Player player)
    {
        return TryResolveInstalledBucketCollection(
                   bucket,
                   out int itemId,
                   out _,
                   out _,
                   out _)
               && player != null
               && (player.CanAcceptHandObject(itemId) || player.CanClearHandIntoBag());
    }

    public bool TryCollectInstalledBucketToHand(Bucket bucket, Player player)
    {
        if (player == null
            || !TryResolveInstalledBucketCollection(
                bucket,
                out int itemId,
                out ItemDefinition definition,
                out TerrainGenerator terrain,
                out IReadOnlyList<Vector2Int> runtimeOccupiedCoordinates))
        {
            return false;
        }

        if (!player.CanAcceptHandObject(itemId)
            && !player.TryStoreHandItemsInBag())
        {
            return false;
        }

        if (!player.TryAddToHand(itemId, out _))
        {
            return false;
        }

        MapObject sourcePrefab = ResolveInstallationSourcePrefab(
            definition,
            GetInstallationVariantKind(bucket));
        List<Vector2Int> occupiedCoordinates = new List<Vector2Int>(runtimeOccupiedCoordinates);
        terrain.RemoveInstallationPersistence(bucket);
        for (int i = 0; i < occupiedCoordinates.Count; i++)
        {
            if (terrain.TryGetLoadedBlock(occupiedCoordinates[i], out Block block)
                && block != null
                && block.MapObject == bucket)
            {
                block.SetMapObject(null);
            }
        }

        ReleaseInstalledObjectInstance(bucket, sourcePrefab, terrain);
        RefreshInstalledConnectorVariantsAroundCoordinates(
            occupiedCoordinates,
            sourcePrefab,
            true,
            null);
        player.UpdateCarryState();
        return true;
    }

    private bool TryResolveInstalledBucketCollection(
        Bucket bucket,
        out int itemId,
        out ItemDefinition definition,
        out TerrainGenerator terrain,
        out IReadOnlyList<Vector2Int> occupiedCoordinates)
    {
        itemId = -1;
        definition = null;
        terrain = ResolveInstallPreviewTerrain();
        occupiedCoordinates = null;
        if (bucket == null
            || !bucket.gameObject.activeInHierarchy
            || terrain == null
            || !bucket.TryGetPlacementRuntime(out _, out _)
            || !TryGetInstallationDefinitionForEditableObject(bucket, out definition)
            || definition == null)
        {
            return false;
        }

        itemId = bucket.ResolveItemId();
        if (itemId < 0)
        {
            return false;
        }

        occupiedCoordinates = bucket.RuntimeOccupiedCoordinates;
        return occupiedCoordinates != null && occupiedCoordinates.Count > 0;
    }

    public bool TryUpgradeInstalledObject(
        InstallationObject currentObject,
        ItemDefinition targetDefinition,
        out InstallationObject upgradedObject)
    {
        upgradedObject = null;
        if (!TryResolveUpgradePlacement(
                currentObject,
                targetDefinition,
                out Vector2Int anchorCoordinate,
                out int quarterTurns,
                out MapObject targetSourcePrefab,
                out TerrainGenerator terrain)
            || !CanPlaceInstalledObjectAt(
                anchorCoordinate,
                targetSourcePrefab,
                quarterTurns,
                currentObject,
                true))
        {
            return false;
        }

        Transform installParent = terrain != null ? terrain.transform : transform;
        MapObject replacementMapObject = CreateInstalledObjectInstance(
            targetSourcePrefab,
            installParent,
            terrain);
        if (!(replacementMapObject is InstallationObject replacementInstallation))
        {
            if (replacementMapObject != null)
            {
                Destroy(replacementMapObject.gameObject);
            }

            return false;
        }

        InputOutputModule.PersistentState persistentState =
            currentObject is InputOutputModule currentInputOutputModule
                ? currentInputOutputModule.CapturePersistentState()
                : null;
        List<ulong> itemFilterMaskWords = currentObject.CaptureItemFilterMaskWords();
        bool itemFilterMaskInitialized = currentObject.IsItemFilterMaskInitialized;
        int storedFluidItemId = currentObject.StoredFluidItemId;
        float storedFluidLiters = currentObject.StoredFluidLiters;
        float storedFluidTemperatureCelsius = currentObject.GetStoredFluidTemperatureCelsius(
            storedFluidItemId);
        int storedInstallationItemId = currentObject is IPersistentInstallationItemStorage itemStorage
            ? itemStorage.PersistentStoredItemId
            : -1;
        List<int> storedInstallationItemIds = new List<int>();
        if (currentObject is IPersistentInstallationItemCollectionStorage collectionStorage)
        {
            collectionStorage.CapturePersistentStoredItemIds(storedInstallationItemIds);
        }
        long placementSequence = currentObject.RuntimePlacementSequence;
        List<Vector2Int> oldCoordinates = new List<Vector2Int>(currentObject.RuntimeOccupiedCoordinates);
        List<Vector2Int> newCoordinates = GetFootprintCoordinates(
            anchorCoordinate,
            targetSourcePrefab,
            quarterTurns);

        replacementInstallation.transform.SetPositionAndRotation(
            GetInstalledObjectWorldPosition(anchorCoordinate, targetSourcePrefab, quarterTurns),
            GetInstalledObjectRotation(targetSourcePrefab, quarterTurns));

        TryGetInstallationDefinitionForEditableObject(currentObject, out ItemDefinition currentDefinition);
        terrain?.RemoveInstallationPersistence(currentObject);
        for (int i = 0; i < oldCoordinates.Count; i++)
        {
            if (terrain != null
                && terrain.TryGetLoadedBlock(oldCoordinates[i], out Block block)
                && block != null
                && block.MapObject == currentObject)
            {
                block.SetMapObject(null);
            }
        }

        ReleaseInstalledObjectInstance(
            currentObject,
            ResolveInstallationSourcePrefab(
                currentDefinition,
                GetInstallationVariantKind(currentObject)),
            terrain);

        for (int i = 0; i < newCoordinates.Count; i++)
        {
            if (terrain != null
                && terrain.TryGetLoadedBlock(newCoordinates[i], out Block block)
                && block != null
                && ShouldBindInstalledObjectToBlock(
                    block,
                    anchorCoordinate,
                    targetSourcePrefab,
                    quarterTurns))
            {
                block.SetMapObject(replacementInstallation);
            }
        }

        ConfigureInstalledObjectRuntime(
            replacementInstallation,
            anchorCoordinate,
            quarterTurns,
            persistentState,
            placementSequence,
            newCoordinates);
        replacementInstallation.ApplyItemFilterMask(
            itemFilterMaskWords,
            itemFilterMaskInitialized);
        replacementInstallation.SetStoredFluid(
            storedFluidItemId,
            storedFluidLiters,
            storedFluidTemperatureCelsius);
        if (replacementInstallation is IPersistentInstallationItemStorage replacementItemStorage)
        {
            replacementItemStorage.ApplyPersistentStoredItemId(storedInstallationItemId);
        }
        if (replacementInstallation is IPersistentInstallationItemCollectionStorage replacementCollectionStorage)
        {
            replacementCollectionStorage.ApplyPersistentStoredItemIds(storedInstallationItemIds);
        }
        RegisterInstalledObjectPersistence(replacementInstallation);

        for (int i = 0; i < newCoordinates.Count; i++)
        {
            if (!oldCoordinates.Contains(newCoordinates[i]))
            {
                oldCoordinates.Add(newCoordinates[i]);
            }
        }

        RefreshInstalledConnectorVariantsAroundCoordinates(
            oldCoordinates,
            replacementInstallation,
            true,
            null);
        upgradedObject = replacementInstallation;
        return true;
    }

    private bool TryResolveUpgradePlacement(
        InstallationObject currentObject,
        ItemDefinition targetDefinition,
        out Vector2Int anchorCoordinate,
        out int quarterTurns,
        out MapObject targetSourcePrefab,
        out TerrainGenerator terrain)
    {
        anchorCoordinate = default;
        quarterTurns = 0;
        targetSourcePrefab = null;
        terrain = ResolveInstallPreviewTerrain();
        if (currentObject == null
            || !currentObject.gameObject.activeInHierarchy
            || targetDefinition == null
            || !targetDefinition.upgradeable
            || !(targetDefinition.mapObject is InstallationObject)
            || terrain == null
            || !currentObject.TryGetPlacementRuntime(out anchorCoordinate, out int currentQuarterTurns))
        {
            return false;
        }

        quarterTurns = NormalizePlacementQuarterTurnsForObject(
            targetDefinition.mapObject,
            currentQuarterTurns);
        targetSourcePrefab = ResolveInstalledObjectSourcePrefab(
            targetDefinition,
            anchorCoordinate,
            quarterTurns,
            currentObject);
        return targetSourcePrefab is InstallationObject;
    }

    private bool TryGetFootprintBlocks(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore,
        out List<Block> footprintBlocks,
        bool ignoreOtherPreviews = false,
        bool includeIgnoredPreviewAsConnector = false)
    {
        footprintBlocks = new List<Block>();

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        if (!OilDrillingMachinePlacementMatchesOil(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                previewToIgnore))
        {
            return false;
        }

        if (PlacementHasNormalInputOutputAreaPipeOverlap(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                previewToIgnore))
        {
            return false;
        }

        List<Vector2Int> occupiedCoordinates = GetPlacementValidationCoordinates(
            anchorCoordinate,
            footprintSource,
            quarterTurns);
        for (int i = 0; i < occupiedCoordinates.Count; i++)
        {
            Vector2Int coordinate = occupiedCoordinates[i];
            if (!terrain.TryGetLoadedBlock(coordinate, out Block footprintBlock) || footprintBlock == null)
            {
                return false;
            }

            if (terrain.HasDroppedFloorObjectsAt(coordinate))
            {
                return false;
            }

            TryGetRectGridFootprintBlockType(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                coordinate,
                out InputOutputModule.RectGridBlockType rectGridBlockType);
            if (!CanPlacePreviewOnTargetBlockType(
                    footprintBlock,
                    footprintSource,
                    rectGridBlockType,
                    anchorCoordinate,
                    quarterTurns,
                    previewToIgnore,
                    includeIgnoredPreviewAsConnector))
            {
                return false;
            }

            if (!ignoreOtherPreviews
                && TryGetInstallPreviewAtCoordinate(coordinate, out MapObject existingPreview)
                && existingPreview != null
                && existingPreview != previewToIgnore)
            {
                if (IsBelt2F(footprintSource)
                    || !CanOverlapCompatibleInstallPreview(
                        coordinate,
                        footprintSource,
                        rectGridBlockType,
                        anchorCoordinate,
                        quarterTurns,
                        existingPreview))
                {
                    return false;
                }
            }

            footprintBlocks.Add(footprintBlock);
        }

        return footprintBlocks.Count > 0;
    }

    private bool TryGetRectGridFootprintBlockType(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        Vector2Int coordinate,
        out InputOutputModule.RectGridBlockType blockType)
    {
        blockType = InputOutputModule.RectGridBlockType.None;
        return TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
               && inputOutputModule.TryGetRectGridBlockTypeAtCoordinate(
                   footprintSource,
                   anchorCoordinate,
                   NormalizePlacementQuarterTurnsForObject(footprintSource, quarterTurns),
                   coordinate,
                   out blockType);
    }

    private InputOutputModule.RectGridBlockType GetRectGridBlockTypeAtCoordinate(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        Vector2Int coordinate)
    {
        return TryGetRectGridFootprintBlockType(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                coordinate,
                out InputOutputModule.RectGridBlockType blockType)
            ? blockType
            : InputOutputModule.RectGridBlockType.None;
    }

    private bool ShouldBindInstalledObjectToBlock(
        Block block,
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns)
    {
        if (block == null)
        {
            return false;
        }

        if (IsTrainSource(footprintSource))
        {
            return false;
        }

        if (!TryGetRectGridFootprintSettings(footprintSource, out _, out _, out _)
            || !TryGetInputOutputModule(footprintSource, out _))
        {
            return !ShouldSkipBelt2FBridgeCenterBinding(block, anchorCoordinate, footprintSource, quarterTurns);
        }

        return TryGetRectGridFootprintBlockType(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                block.Coordinate,
                out InputOutputModule.RectGridBlockType blockType)
            && blockType == InputOutputModule.RectGridBlockType.Object;
    }

    private bool CanPlacePreviewOnTargetBlockType(
        Block block,
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType = InputOutputModule.RectGridBlockType.None,
        Vector2Int? anchorCoordinate = null,
        int quarterTurns = 0,
        MapObject previewToIgnore = null,
        bool includeIgnoredPreviewAsConnector = false)
    {
        if (block == null)
        {
            return false;
        }

        MapObject occupyingObject = GetOccupyingObjectForPlacement(block, previewToIgnore);

        if (!TryResolveInstallationObject(footprintSource, out InstallationObject installationObject))
        {
            return CanPlaceOnTerrainBiome(block, InstallationMapFilter.Ground) && occupyingObject == null;
        }

        InstallationMapFilter allowedFilter = ResolvePlacementMapFilter(footprintSource, installationObject);
        InstallationMapFilter rectGridTerrainFilter =
            ResolveRectGridTerrainFilter(footprintSource, rectGridBlockType, allowedFilter);
        if (footprintSource is Pipe && IsFixedRectGridObjectBlockCoordinate(block.Coordinate))
        {
            return false;
        }

        bool isRectGridAreaBlock = IsRectGridAreaBlockType(rectGridBlockType);
        bool isInputOutputEnergyAreaBlock = InputOutputModuleEnergyAreaController.CoordinateIsEnergyArea(block.Coordinate)
            || InputOutputModule.CoordinateIsRuntimeInputEnergyBlock(block.Coordinate);
        bool isInputOutputItemAreaBlock = CoordinateHasInputItemAreaBlockForPlacement(
            block.Coordinate,
            previewToIgnore);
        bool isPumpRuntimeOutputAreaBlock = IsPumpOutputCoordinateForPlacement(block.Coordinate);
        bool isInputOutputOutputAreaBlock = InputOutputModuleOutputAreaController.CoordinateIsOutputArea(block.Coordinate)
            || (InputOutputModule.CoordinateIsRuntimeOutputBlock(block.Coordinate)
                && !isPumpRuntimeOutputAreaBlock);
        bool isRuntimePipeAreaBlock = InputOutputModule.CoordinateAllowsRuntimePipeBlock(block.Coordinate);
        bool isFluidStoragePipeNodeBlock = HasPipeAreaFluidStorageAtCoordinate(block.Coordinate);
        bool hasNormalInputOutputAreaBlock = CoordinateHasNormalInputOutputAreaBlockForPlacement(
            block.Coordinate,
            previewToIgnore);
        bool isExistingNormalInputOutputAreaBlock = hasNormalInputOutputAreaBlock
            && !isRuntimePipeAreaBlock
            && !isPumpRuntimeOutputAreaBlock
            && !isFluidStoragePipeNodeBlock;
        bool isInputOutputAreaBlock = isInputOutputEnergyAreaBlock
            || isInputOutputItemAreaBlock
            || isInputOutputOutputAreaBlock
            || isExistingNormalInputOutputAreaBlock
            || isPumpRuntimeOutputAreaBlock;
        // ItemArea represents every non-pipe item interaction cell: item input, fuel input, and output.
        bool allowsItemArea = isExistingNormalInputOutputAreaBlock
            && (allowedFilter & InstallationMapFilter.ItemArea) != 0;
        bool canPlacePipeOnFixedConnectorArea = footprintSource is Pipe
            && CanPlacePipeOnFixedFluidConnectorArea(
                block,
                occupyingObject,
                footprintSource,
                quarterTurns);
        bool isCandidateNormalInputOutputAreaBlock = IsNormalInputOutputAreaBlockType(rectGridBlockType);
        if (footprintSource is Pipe
            && (isExistingNormalInputOutputAreaBlock
                || hasNormalInputOutputAreaBlock))
        {
            return false;
        }

        if ((isCandidateNormalInputOutputAreaBlock || isExistingNormalInputOutputAreaBlock)
            && TryGetPipePlacementAtBlock(block, occupyingObject, out _, out _))
        {
            return false;
        }

        if (rectGridBlockType != InputOutputModule.RectGridBlockType.None
            && !allowsItemArea
            && !CanPlaceOnTerrainBiome(block, rectGridTerrainFilter))
        {
            return false;
        }

        MapObject boilerPipePassPreviewToIgnore = includeIgnoredPreviewAsConnector ? null : previewToIgnore;
        if (CanPlaceBoilerConnectorOnPumpBody(
                footprintSource,
                rectGridBlockType,
                block,
                occupyingObject,
                anchorCoordinate,
                quarterTurns))
        {
            return true;
        }

        if (CanPlaceBoilerConnectorOnBoilerBody(
                footprintSource,
                rectGridBlockType,
                block,
                occupyingObject,
                anchorCoordinate,
                quarterTurns,
                boilerPipePassPreviewToIgnore))
        {
            return true;
        }

        if (CanPlaceBoilerObjectOnPumpOutputArea(
                footprintSource,
                rectGridBlockType,
                block,
                occupyingObject,
                isPumpRuntimeOutputAreaBlock,
                anchorCoordinate,
                quarterTurns))
        {
            return true;
        }

        if (CanPlaceBoilerObjectOnBoilerPipePassArea(
                footprintSource,
                rectGridBlockType,
                block,
                occupyingObject,
                allowedFilter,
                anchorCoordinate,
                quarterTurns,
                boilerPipePassPreviewToIgnore))
        {
            return true;
        }

        if (CanPlaceSteamGeneratorCenterOnBoilerPipeOutput(
                footprintSource,
                rectGridBlockType,
                block,
                occupyingObject,
                allowedFilter,
                anchorCoordinate,
                quarterTurns,
                previewToIgnore))
        {
            return true;
        }

        if (CanPlaceBoilerCenterOnSteamGeneratorPipeInput(
                footprintSource,
                rectGridBlockType,
                block,
                occupyingObject,
                allowedFilter,
                anchorCoordinate,
                quarterTurns,
                previewToIgnore))
        {
            return true;
        }

        if (CanPlaceBoilerOutputOnSteamGeneratorBodyForDirectInput(
                footprintSource,
                rectGridBlockType,
                block,
                occupyingObject,
                allowedFilter,
                anchorCoordinate,
                quarterTurns,
                previewToIgnore))
        {
            return true;
        }

        if (CanPlaceSteamGeneratorStraightChainBlock(
                footprintSource,
                rectGridBlockType,
                block,
                anchorCoordinate,
                quarterTurns,
                previewToIgnore,
                includeIgnoredPreviewAsConnector))
        {
            return true;
        }

        bool needsCompatibleRectGridOverlapCheck =
            (IsSteamGeneratorSource(footprintSource) || IsBoilerSource(footprintSource))
            && (occupyingObject != null
                || isInputOutputAreaBlock
                || isRuntimePipeAreaBlock
                || isFluidStoragePipeNodeBlock);
        if (needsCompatibleRectGridOverlapCheck
            && CanPlaceCompatibleRectGridOverlap(
                footprintSource,
                rectGridBlockType,
                block,
                anchorCoordinate,
                quarterTurns,
                previewToIgnore))
        {
            return true;
        }

        bool canPlaceFluidStorageObjectOnPipeNode = CanPlaceFluidStorageObjectOnPipeNode(
            footprintSource,
            rectGridBlockType,
            block,
            occupyingObject,
            anchorCoordinate,
            quarterTurns,
            isPumpRuntimeOutputAreaBlock,
            isFluidStoragePipeNodeBlock,
            previewToIgnore);
        if (!isRectGridAreaBlock
            && !canPlaceFluidStorageObjectOnPipeNode
            && !canPlacePipeOnFixedConnectorArea
            && !allowsItemArea
            && !CanPlaceOnTerrainBiome(block, allowedFilter))
        {
            return false;
        }

        if (IsWaterPumpSource(footprintSource)
            && !IsWaterPumpCardinalShoreCoordinate(anchorCoordinate ?? block.Coordinate))
        {
            return false;
        }

        if (IsTrainStationSource(footprintSource)
            && !TryResolveTrainStationSelectedRailCoordinate(
                anchorCoordinate ?? block.Coordinate,
                footprintSource,
                quarterTurns,
                previewToIgnore,
                out _))
        {
            return false;
        }

        if (canPlaceFluidStorageObjectOnPipeNode)
        {
            return true;
        }

        if (canPlacePipeOnFixedConnectorArea)
        {
            return true;
        }

        if (footprintSource is Pipe pipeOnRuntimeArea
            && isRuntimePipeAreaBlock
            && occupyingObject == null)
        {
            return CanResolvedPipePlacementMatchFixedFluidConnectors(
                block.Coordinate,
                pipeOnRuntimeArea,
                quarterTurns);
        }

        if (footprintSource is Pipe pipeFootprint
            && !CanResolvedPipePlacementMatchFixedFluidConnectors(
                block.Coordinate,
                pipeFootprint,
                quarterTurns))
        {
            return false;
        }

        if (IsResourceAllowedForPlacement(block, occupyingObject, allowedFilter))
        {
            return true;
        }

        if (IsRailloadAllowedForPlacement(block, occupyingObject, allowedFilter))
        {
            return true;
        }

        if (IsInstallationObjectAllowedForPlacement(occupyingObject, allowedFilter))
        {
            return true;
        }

        if (CanPlacePassthroughOnBelt2FBridgeCenter(
                block,
                footprintSource,
                occupyingObject,
                quarterTurns))
        {
            return true;
        }

        if (!isRectGridAreaBlock
            && IsPipeAllowedForPlacement(
                block,
                occupyingObject,
                footprintSource,
                anchorCoordinate,
                quarterTurns,
                allowedFilter))
        {
            return true;
        }

        if (IsBelt2F(footprintSource))
        {
            return CanPlaceBelt2FBlock(
                block,
                footprintSource,
                occupyingObject,
                anchorCoordinate,
                quarterTurns,
                isInputOutputAreaBlock,
                allowedFilter);
        }

        if (isRectGridAreaBlock)
        {
            if (CanPlaceBoilerOnPumpOutputArea(
                    footprintSource,
                    rectGridBlockType,
                    block,
                    occupyingObject,
                    isPumpRuntimeOutputAreaBlock,
                    allowedFilter,
                    anchorCoordinate,
                    quarterTurns))
            {
                return true;
            }

            if (CanPlaceBoilerAreaBesidePumpOutput(
                    footprintSource,
                    rectGridBlockType,
                    block,
                    occupyingObject,
                    anchorCoordinate,
                    quarterTurns))
            {
                return true;
            }

            if (CanPlaceFluidStorageAreaOnPipeNode(
                    installationObject,
                    rectGridBlockType,
                    block,
                    occupyingObject,
                    anchorCoordinate,
                    quarterTurns,
                    isPumpRuntimeOutputAreaBlock,
                    isFluidStoragePipeNodeBlock,
                    allowedFilter,
                    previewToIgnore))
            {
                return true;
            }

            if (CanPlaceSteamGeneratorInputOnBoilerBodyForDirectOutput(
                    footprintSource,
                    rectGridBlockType,
                    block,
                    occupyingObject,
                    rectGridTerrainFilter,
                    anchorCoordinate,
                    quarterTurns,
                    previewToIgnore))
            {
                return true;
            }

            return CanPlaceRectGridAreaBlock(
                block,
                occupyingObject,
                footprintSource,
                rectGridBlockType,
                anchorCoordinate ?? block.Coordinate,
                quarterTurns,
                isInputOutputEnergyAreaBlock,
                isInputOutputItemAreaBlock,
                isInputOutputOutputAreaBlock,
                rectGridTerrainFilter);
        }

        if (isInputOutputAreaBlock)
        {
            if ((isRuntimePipeAreaBlock || isPumpRuntimeOutputAreaBlock || isFluidStoragePipeNodeBlock)
                && CanPlaceFluidStorageOnRuntimePipeArea(
                    installationObject,
                    block,
                    occupyingObject,
                    isPumpRuntimeOutputAreaBlock,
                    isRuntimePipeAreaBlock,
                    isRectGridAreaBlock,
                    isFluidStoragePipeNodeBlock,
                    allowedFilter))
            {
                return true;
            }

            if (isRuntimePipeAreaBlock
                && CanPlacePipeOnFixedFluidConnectorArea(
                    block,
                    occupyingObject,
                    footprintSource,
                    quarterTurns))
            {
                return true;
            }

            if (CanPlaceBoilerOnPumpOutputArea(
                    footprintSource,
                    rectGridBlockType,
                    block,
                    occupyingObject,
                    isPumpRuntimeOutputAreaBlock,
                    allowedFilter,
                    anchorCoordinate,
                    quarterTurns))
            {
                return true;
            }

            return CanPlaceInstallationOnInputOutputAreaBlock(
                installationObject,
                block,
                occupyingObject,
                isInputOutputAreaBlock,
                isExistingNormalInputOutputAreaBlock,
                isInputOutputItemAreaBlock,
                allowedFilter);
        }

        if (occupyingObject != null)
        {
            return false;
        }

        return block.Type switch
        {
            Block.BlockType.Ground => true,
            _ => false
        };
    }

    private bool CanPlaceFluidStorageOnRuntimePipeArea(
        InstallationObject installationObject,
        Block block,
        MapObject occupyingObject,
        bool isPumpRuntimeOutputAreaBlock,
        bool isRuntimePipeAreaBlock,
        bool isRectGridAreaBlock,
        bool isFluidStoragePipeNodeBlock,
        InstallationMapFilter allowedFilter)
    {
        if (installationObject is Boiler && isPumpRuntimeOutputAreaBlock && !isRectGridAreaBlock)
        {
            return false;
        }

        if (installationObject is Boiler && isRuntimePipeAreaBlock && !isRectGridAreaBlock)
        {
            return false;
        }

        return installationObject != null
               && installationObject.CanStoreFluid
               && !(installationObject is Pipe)
               && !(installationObject is Pump)
               && block != null
               && CanPlaceOnTerrainBiome(block, allowedFilter)
               && (occupyingObject == null
                   || (isPumpRuntimeOutputAreaBlock && occupyingObject is Pump));
    }

    private bool CanPlaceFluidStorageObjectOnPipeNode(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        bool isPumpRuntimeOutputAreaBlock,
        bool isFluidStoragePipeNodeBlock,
        MapObject previewToIgnore)
    {
        if (IsBoilerSource(footprintSource)
            && isPumpRuntimeOutputAreaBlock
            && rectGridBlockType == InputOutputModule.RectGridBlockType.Object)
        {
            return anchorCoordinate.HasValue
                   && IsExactPumpOutputCoordinateForPlacement(block.Coordinate)
                   && TryGetExactPumpOutputDirectionForPlacement(
                       block.Coordinate,
                       out Vector2Int pumpOutputDirection)
                   && BoilerPumpSidePipePassMatchesOutputDirection(
                       footprintSource,
                       anchorCoordinate.Value,
                       block.Coordinate,
                       quarterTurns,
                       pumpOutputDirection);
        }

        if (IsBoilerSource(footprintSource)
            && block != null
            && isFluidStoragePipeNodeBlock
            && TryGetSteamGeneratorPipePassTailDirectionAtCoordinate(
                block.Coordinate,
                previewToIgnore,
                out _,
                out _))
        {
            return false;
        }

        return TryResolveInstallationObject(footprintSource, out InstallationObject installationObject)
               && installationObject.CanStoreFluid
               && !(installationObject is Pipe)
               && !(installationObject is Pump)
               && !IsSteamGeneratorSource(footprintSource)
               && rectGridBlockType == InputOutputModule.RectGridBlockType.Object
               && block != null
                && block.Type == Block.BlockType.Ground
                && (occupyingObject == null
                    || (isPumpRuntimeOutputAreaBlock && occupyingObject is Pump))
                && (isPumpRuntimeOutputAreaBlock || isFluidStoragePipeNodeBlock);
    }

    private bool CanPlaceSteamGeneratorCenterOnBoilerPipeOutput(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        InstallationMapFilter allowedFilter,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        return rectGridBlockType == InputOutputModule.RectGridBlockType.Object
               && block != null
               && anchorCoordinate.HasValue
               && block.Coordinate == anchorCoordinate.Value
               && (occupyingObject == null || IsBoilerSource(occupyingObject))
               && CanPlaceOnTerrainBiome(block, allowedFilter)
               && TryGetSteamGeneratorDirectBoilerOutputPlacement(
                   anchorCoordinate.Value,
                   footprintSource,
                   quarterTurns,
                   previewToIgnore,
                   out _,
                   out _);
    }

    private bool CanPlaceSteamGeneratorInputOnBoilerBodyForDirectOutput(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        InstallationMapFilter allowedFilter,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (!InputOutputModule.IsInputItemBlockType(rectGridBlockType)
            || block == null
            || !anchorCoordinate.HasValue
            || !IsBoilerSource(occupyingObject)
            || !CanPlaceOnTerrainBiome(block, allowedFilter)
            || !TryGetSteamGeneratorDirectBoilerOutputPlacement(
                anchorCoordinate.Value,
                footprintSource,
                quarterTurns,
                previewToIgnore,
                out _,
                out Vector2Int steamInputCoordinate)
            || block.Coordinate != steamInputCoordinate)
        {
            return false;
        }

        return true;
    }

    private bool CanPlaceBoilerCenterOnSteamGeneratorPipeInput(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        InstallationMapFilter allowedFilter,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (!IsBoilerSource(footprintSource)
            || rectGridBlockType != InputOutputModule.RectGridBlockType.Object
            || block == null
            || !anchorCoordinate.HasValue
            || block.Coordinate != anchorCoordinate.Value
            || (occupyingObject != null && !IsSteamGeneratorSource(occupyingObject))
            || !CanPlaceOnTerrainBiome(block, allowedFilter))
        {
            return false;
        }

        return CanBoilerDirectSteamGeneratorInputConnection(
            anchorCoordinate.Value,
            footprintSource,
            quarterTurns,
            previewToIgnore);
    }

    private bool CanPlaceBoilerOutputOnSteamGeneratorBodyForDirectInput(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        InstallationMapFilter allowedFilter,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        // Boiler -> SteamGenerator is a flush direct connection: the Boiler Object/body
        // sits on the SteamGenerator PipeInputArea, and the Boiler PipeOutput reaches
        // over the SteamGenerator body cell. Do not fall back to same-cell PipeOutput/
        // PipeInput overlap because that separates the machines by one tile.
        return IsBoilerSource(footprintSource)
               && InputOutputModule.IsOutputBlockType(rectGridBlockType)
               && block != null
               && anchorCoordinate.HasValue
               && (occupyingObject == null || IsSteamGeneratorSource(occupyingObject))
               && CanPlaceOnTerrainBiome(block, allowedFilter)
               && TryGetBoilerDirectSteamGeneratorInputPlacement(
                   anchorCoordinate.Value,
                   footprintSource,
                   quarterTurns,
                   previewToIgnore,
                   out Vector2Int boilerOutputCoordinate,
                   out _)
               && block.Coordinate == boilerOutputCoordinate;
    }

    private bool CanPlaceSteamGeneratorStraightChainBlock(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore,
        bool includeIgnoredPreviewAsConnector)
    {
        MapObject connectorPreviewToIgnore = includeIgnoredPreviewAsConnector ? null : previewToIgnore;
        if (!IsSteamGeneratorSource(footprintSource)
            || block == null
            || block.Type != Block.BlockType.Ground
            || !anchorCoordinate.HasValue
            || !TryGetSteamGeneratorPipePassTailDirectionAtCoordinate(
                anchorCoordinate.Value,
                connectorPreviewToIgnore,
                out Vector2Int existingTailDirection,
                out PipeAreaBlockCandidate existingPipePassCandidate)
            || !TryGetSteamGeneratorBodyDirectionFromCenter(
                footprintSource,
                quarterTurns,
                out Vector2Int proposedTailDirection)
            || proposedTailDirection != existingTailDirection)
        {
            return false;
        }

        if (rectGridBlockType == InputOutputModule.RectGridBlockType.Object
            && block.Coordinate == anchorCoordinate.Value)
        {
            return true;
        }

        if (!InputOutputModule.IsInputItemBlockType(rectGridBlockType)
            || block.Coordinate != anchorCoordinate.Value - proposedTailDirection)
        {
            return false;
        }

        return existingPipePassCandidate.snapshot != null
               && TryGetRectGridFootprintBlockType(
                   existingPipePassCandidate.snapshot.anchorCoordinate,
                   existingPipePassCandidate.snapshot.mapObject,
                   existingPipePassCandidate.snapshot.quarterTurns,
                   block.Coordinate,
                   out InputOutputModule.RectGridBlockType existingBlockType)
               && existingBlockType == InputOutputModule.RectGridBlockType.Object;
    }

    private bool CanPlaceFluidStorageAreaOnPipeNode(
        InstallationObject installationObject,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        bool isPumpRuntimeOutputAreaBlock,
        bool isFluidStoragePipeNodeBlock,
        InstallationMapFilter allowedFilter,
        MapObject previewToIgnore)
    {
        if (installationObject is Boiler
            && block != null
            && isFluidStoragePipeNodeBlock
            && TryGetSteamGeneratorPipePassTailDirectionAtCoordinate(
                block.Coordinate,
                previewToIgnore,
                out _,
                out _))
        {
            return false;
        }

        if (installationObject is Boiler
            && isPumpRuntimeOutputAreaBlock
            && rectGridBlockType == InputOutputModule.RectGridBlockType.PipeInput
            && !BoilerPipePassMatchesPumpOutput(
                installationObject,
                block != null ? block.Coordinate : Vector2Int.zero,
                anchorCoordinate,
                quarterTurns))
        {
            return false;
        }

        if (isFluidStoragePipeNodeBlock
            && InputOutputModule.AllowsPipeAreaInteraction(rectGridBlockType)
            && !CanProposedPipeAreaBlockConnectExisting(
                block != null ? block.Coordinate : Vector2Int.zero,
                installationObject,
                rectGridBlockType,
                anchorCoordinate,
                quarterTurns))
        {
            return false;
        }

        return installationObject != null
               && installationObject.CanStoreFluid
               && !(installationObject is Pipe)
               && !(installationObject is Pump)
               && IsRectGridAreaBlockType(rectGridBlockType)
               && block != null
               && CanPlaceOnTerrainBiome(block, allowedFilter)
               && (occupyingObject == null
                   || (isPumpRuntimeOutputAreaBlock && occupyingObject is Pump)
                   || (isFluidStoragePipeNodeBlock && IsFluidStoragePlacementObject(occupyingObject)))
               && (isPumpRuntimeOutputAreaBlock || isFluidStoragePipeNodeBlock);
    }

    private bool CanProposedPipeAreaBlockConnectExisting(
        Vector2Int coordinate,
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Vector2Int? anchorCoordinate,
        int quarterTurns)
    {
        if (footprintSource == null
            || !anchorCoordinate.HasValue
            || !InputOutputModule.AllowsPipeAreaInteraction(rectGridBlockType))
        {
            return false;
        }

        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate.Value,
            quarterTurns = quarterTurns
        };
        PipeAreaBlockCandidate proposedCandidate =
            new PipeAreaBlockCandidate(proposedSnapshot, rectGridBlockType);

        pipeAreaBlockCandidateScratchA.Clear();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(coordinate, null, pipeAreaBlockCandidateScratchA);
        bool foundExistingCandidate = false;
        bool canConnect = false;
        for (int i = 0; i < pipeAreaBlockCandidateScratchA.Count; i++)
        {
            PipeAreaBlockCandidate existingCandidate = pipeAreaBlockCandidateScratchA[i];
            if (existingCandidate.snapshot == null
                || existingCandidate.snapshot.mapObject == footprintSource)
            {
                continue;
            }

            foundExistingCandidate = true;
            if (CanPipeAreaBlockCandidatesConnect(
                    coordinate,
                    proposedCandidate,
                    coordinate,
                    existingCandidate))
            {
                canConnect = true;
                break;
            }
        }

        pipeAreaBlockCandidateScratchA.Clear();
        if (foundExistingCandidate && canConnect)
        {
            return true;
        }

        if (IsBoilerSource(footprintSource) && IsPipePassBlockType(rectGridBlockType))
        {
            for (int directionIndex = 0; directionIndex < PipeCardinalDirections.Length; directionIndex++)
            {
                Vector2Int existingPipePassCoordinate = coordinate + PipeCardinalDirections[directionIndex];
                if (BoilerPipePassConnectsExistingBoilerPipePassAtCoordinate(
                        coordinate,
                        proposedCandidate,
                        existingPipePassCoordinate,
                        null))
                {
                    return true;
                }
            }
        }

        return false;
    }

    private bool CanProposedFluidStoragePipeAreaConnectionsMatchExisting(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore,
        bool includeIgnoredPreviewAsConnector = false)
    {
        if (!TryResolveInstallationObject(footprintSource, out InstallationObject installationObject)
            || installationObject is Pipe
            || (!(installationObject is Pump) && !installationObject.CanStoreFluid)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return true;
        }

        MapObject connectorPreviewToIgnore = includeIgnoredPreviewAsConnector ? null : previewToIgnore;
        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate,
            quarterTurns = quarterTurns
        };

        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (placements == null || placements.Count <= 0)
        {
            return true;
        }

        if (TryGetSteamGeneratorDirectBoilerOutputPlacement(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                connectorPreviewToIgnore,
                out _,
                out _))
        {
            return true;
        }

        if (CanSteamGeneratorDirectSteamGeneratorPipePassConnection(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                connectorPreviewToIgnore))
        {
            return true;
        }

        if (CanBoilerDirectSteamGeneratorInputConnection(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                connectorPreviewToIgnore))
        {
            return true;
        }

        if (CanBoilerObjectOnBoilerPipePassConnection(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                connectorPreviewToIgnore))
        {
            return true;
        }

        if (CanBoilerPipePassConnectExistingBoilerPipePass(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                connectorPreviewToIgnore))
        {
            return true;
        }

        if (IsSteamGeneratorSource(footprintSource)
            && !SteamGeneratorPlacementPipeOverlapsMatch(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                false))
        {
            return false;
        }

        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (!InputOutputModule.AllowsPipeAreaInteraction(placement.blockType)
                || !TryGetRectGridCoordinate(
                    anchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    placement,
                    out Vector2Int pipeAreaCoordinate))
            {
                continue;
            }

            PipeAreaBlockCandidate proposedCandidate =
                new PipeAreaBlockCandidate(proposedSnapshot, placement.blockType);
            if (!PipeAreaConnectionAtCoordinateIsCompatible(
                    pipeAreaCoordinate,
                    proposedCandidate,
                    pipeAreaCoordinate,
                    connectorPreviewToIgnore))
            {
                return false;
            }

            for (int directionIndex = 0; directionIndex < PipeCardinalDirections.Length; directionIndex++)
            {
                Vector2Int connectorCoordinate = pipeAreaCoordinate + PipeCardinalDirections[directionIndex];
                if (!PipeAreaConnectionAtCoordinateIsCompatible(
                        pipeAreaCoordinate,
                        proposedCandidate,
                        connectorCoordinate,
                        connectorPreviewToIgnore))
                {
                    return false;
                }
            }
        }

        return true;
    }

    private bool CanProposedFluidTankAndPumpConnectionsMatchExisting(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (!TryResolveInstallationObject(footprintSource, out InstallationObject installationObject))
        {
            return true;
        }

        if (installationObject is Fluidtank)
        {
            // A tank may sit beside a different-fluid tank or pipe network. The
            // incompatible side is closed by the shared tank connection resolver
            // instead of making the whole footprint invalid.
            return true;
        }

        if (installationObject is not Pump proposedPump)
        {
            return true;
        }

        HashSet<int> compatibleFluidItemIds = new HashSet<int>();
        bool hasFluidConstraint = false;
        HashSet<int> proposedPumpFluidItemIds = new HashSet<int>();
        if (!TryGetCandidateOutputItemIds(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                proposedPumpFluidItemIds)
            || !RemoveNonFluidItemIds(proposedPumpFluidItemIds)
            || !TryMergeFluidCompatibilityConstraint(
                compatibleFluidItemIds,
                ref hasFluidConstraint,
                proposedPumpFluidItemIds))
        {
            return false;
        }

        return TryMergeTanksConnectedToProposedPump(
            anchorCoordinate,
            footprintSource,
            quarterTurns,
            proposedPump,
            previewToIgnore,
            compatibleFluidItemIds,
            ref hasFluidConstraint);
    }

    private int ResolveProposedStoredFluidItemId(
        InstallationObject footprintInstallation,
        MapObject previewToIgnore)
    {
        if (TryResolveInstallationObject(
                previewToIgnore,
                out InstallationObject previewInstallation)
            && previewInstallation.StoredFluidItemId >= 0)
        {
            return previewInstallation.StoredFluidItemId;
        }

        return footprintInstallation != null
            ? footprintInstallation.StoredFluidItemId
            : -1;
    }

    private static bool FluidConstraintSetsOverlap(
        HashSet<int> firstFluidItemIds,
        HashSet<int> secondFluidItemIds)
    {
        if (firstFluidItemIds == null
            || secondFluidItemIds == null
            || firstFluidItemIds.Count <= 0
            || secondFluidItemIds.Count <= 0)
        {
            return false;
        }

        HashSet<int> smallerSet = firstFluidItemIds.Count <= secondFluidItemIds.Count
            ? firstFluidItemIds
            : secondFluidItemIds;
        HashSet<int> largerSet = ReferenceEquals(smallerSet, firstFluidItemIds)
            ? secondFluidItemIds
            : firstFluidItemIds;
        foreach (int fluidItemId in smallerSet)
        {
            if (largerSet.Contains(fluidItemId))
            {
                return true;
            }
        }

        return false;
    }

    private bool TryMergeTanksConnectedToProposedPump(
        Vector2Int pumpAnchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        Pump proposedPump,
        MapObject previewToIgnore,
        HashSet<int> compatibleFluidItemIds,
        ref bool hasFluidConstraint)
    {
        if (proposedPump == null
            || !proposedPump.TryGetPipeConnectionDirection(
                GetPlacementObjectRotation(footprintSource, quarterTurns),
                out Vector2Int outputDirection)
            || outputDirection == Vector2Int.zero
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements =
            inputOutputModule.RectGridPlacements;
        if (placements == null)
        {
            return false;
        }

        for (int placementIndex = 0; placementIndex < placements.Count; placementIndex++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[placementIndex];
            if (!InputOutputModule.IsOutputBlockType(placement.blockType)
                || !TryGetRectGridCoordinate(
                    pumpAnchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    placement,
                    out Vector2Int outputCoordinate))
            {
                continue;
            }

            if (!TryMergeFluidTankAtCoordinate(
                    outputCoordinate,
                    previewToIgnore,
                    compatibleFluidItemIds,
                    ref hasFluidConstraint)
                || !TryMergeFluidTankAtCoordinate(
                    outputCoordinate + outputDirection,
                    previewToIgnore,
                    compatibleFluidItemIds,
                    ref hasFluidConstraint))
            {
                return false;
            }
        }

        return true;
    }

    private bool TryMergeFluidTankAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        HashSet<int> compatibleFluidItemIds,
        ref bool hasFluidConstraint)
    {
        return !TryGetFluidTankPlacementSnapshotAtCoordinate(
                   coordinate,
                   previewToIgnore,
                   out PlacementSnapshot tankSnapshot)
               || TryMergeSingleFluidCompatibilityConstraint(
                   ResolveSnapshotStoredFluidItemId(tankSnapshot),
                   compatibleFluidItemIds,
                   ref hasFluidConstraint);
    }

    private bool TryGetFluidTankPlacementSnapshotAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out PlacementSnapshot snapshot)
    {
        if (TryGetPreviewPlacementSnapshot(coordinate, previewToIgnore, out snapshot)
            && SnapshotIsActiveFluidTank(snapshot, previewToIgnore))
        {
            return true;
        }

        if (TryGetInstalledPlacementSnapshot(coordinate, out snapshot)
            && SnapshotIsActiveFluidTank(snapshot, previewToIgnore))
        {
            return true;
        }

        if (TryGetSavedPlacementSnapshot(coordinate, out snapshot)
            && SnapshotIsActiveFluidTank(snapshot, previewToIgnore))
        {
            return true;
        }

        snapshot = null;
        return false;
    }

    private bool SnapshotIsActiveFluidTank(
        PlacementSnapshot snapshot,
        MapObject previewToIgnore)
    {
        return snapshot?.mapObject is Fluidtank
               && !IsIgnoredFluidConnectorSnapshot(snapshot, previewToIgnore);
    }

    private static int ResolveSnapshotStoredFluidItemId(PlacementSnapshot snapshot)
    {
        if (snapshot == null)
        {
            return -1;
        }

        if (snapshot.storedFluidItemId >= 0)
        {
            return snapshot.storedFluidItemId;
        }

        return snapshot.mapObject is InstallationObject installationObject
            ? installationObject.StoredFluidItemId
            : -1;
    }

    private static bool TryMergeSingleFluidCompatibilityConstraint(
        int fluidItemId,
        HashSet<int> compatibleFluidItemIds,
        ref bool hasFluidConstraint)
    {
        if (fluidItemId < 0 || !InputOutputModule.IsFluidItemId(fluidItemId))
        {
            return true;
        }

        if (compatibleFluidItemIds == null)
        {
            return false;
        }

        if (hasFluidConstraint && !compatibleFluidItemIds.Contains(fluidItemId))
        {
            return false;
        }

        compatibleFluidItemIds.Clear();
        compatibleFluidItemIds.Add(fluidItemId);
        hasFluidConstraint = true;
        return true;
    }

    private static bool RemoveNonFluidItemIds(HashSet<int> itemIds)
    {
        if (itemIds == null || itemIds.Count <= 0)
        {
            return false;
        }

        itemIds.RemoveWhere(itemId => !InputOutputModule.IsFluidItemId(itemId));
        return itemIds.Count > 0;
    }

    private bool TryGetSteamGeneratorDirectBoilerOutputPlacement(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore,
        out Vector2Int boilerOutputDirection,
        out Vector2Int steamInputCoordinate)
    {
        boilerOutputDirection = Vector2Int.zero;
        steamInputCoordinate = Vector2Int.zero;
        if (!TryResolveSteamGenerator(footprintSource, out SteamGenerator steamGenerator))
        {
            return false;
        }

        if (TryGetBoilerPipeOutputDirectionAtCoordinate(
                anchorCoordinate,
                previewToIgnore,
                out Vector2Int directBoilerOutputDirection)
            && steamGenerator.TryGetBodyDirectionFromCenter(
                footprintSource,
                quarterTurns,
                out Vector2Int adjacentBodyDirection)
            && adjacentBodyDirection == directBoilerOutputDirection)
        {
            Vector2Int directSteamInputCoordinate = anchorCoordinate - directBoilerOutputDirection;
            if (SteamGeneratorInputItemsMatchBoilerOutput(
                    anchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    directSteamInputCoordinate,
                    previewToIgnore))
            {
                boilerOutputDirection = directBoilerOutputDirection;
                steamInputCoordinate = directSteamInputCoordinate;
                return true;
            }
        }

        if (!steamGenerator.TryGetInputCoordinateAndDirection(
                footprintSource,
                anchorCoordinate,
                quarterTurns,
                out Vector2Int candidateInputCoordinate,
                out Vector2Int inputDirection)
            || !TryGetBoilerPipeOutputDirectionAtCoordinate(
                candidateInputCoordinate,
                previewToIgnore,
                out Vector2Int candidateBoilerOutputDirection)
            || candidateBoilerOutputDirection != inputDirection
            || !SteamGeneratorInputItemsMatchBoilerOutput(
                candidateInputCoordinate,
                footprintSource,
                quarterTurns,
                candidateInputCoordinate,
                previewToIgnore))
        {
            return false;
        }

        boilerOutputDirection = candidateBoilerOutputDirection;
        steamInputCoordinate = candidateInputCoordinate;
        return true;
    }

    private bool SteamGeneratorInputItemsMatchBoilerOutput(
        Vector2Int boilerOutputCoordinate,
        MapObject steamGeneratorSource,
        int steamGeneratorQuarterTurns,
        Vector2Int steamInputCoordinate,
        MapObject previewToIgnore)
    {
        HashSet<int> outputItemIds = new HashSet<int>();
        if (!TryGetBoilerOutputItemIdsAtCoordinate(
                boilerOutputCoordinate,
                previewToIgnore,
                outputItemIds))
        {
            return false;
        }

        HashSet<int> inputItemIds = new HashSet<int>();
        return TryGetCandidateInputItemIdsAtCoordinate(
                boilerOutputCoordinate,
                steamGeneratorSource,
                steamGeneratorQuarterTurns,
                steamInputCoordinate,
                inputItemIds)
            && HasSharedItemId(outputItemIds, inputItemIds);
    }

    private bool CanSteamGeneratorDirectSteamGeneratorPipePassConnection(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (!TryResolveSteamGenerator(footprintSource, out SteamGenerator steamGenerator)
            || !TryGetSteamGeneratorPipePassTailDirectionAtCoordinate(
                anchorCoordinate,
                previewToIgnore,
                out Vector2Int existingTailDirection,
                out PipeAreaBlockCandidate pipePassCandidate)
            || !steamGenerator.TryGetBodyDirectionFromCenter(
                footprintSource,
                quarterTurns,
                out Vector2Int proposedTailDirection)
            || proposedTailDirection != existingTailDirection)
        {
            return false;
        }

        Vector2Int proposedInputCoordinate = anchorCoordinate - proposedTailDirection;
        HashSet<int> pipePassItemIds = new HashSet<int>();
        HashSet<int> proposedInputItemIds = new HashSet<int>();
        bool hasPipePassItems = TryGetCandidatePipePassItemIds(pipePassCandidate, pipePassItemIds);
        bool hasInputItems = TryGetCandidateInputItemIdsAtCoordinate(
            anchorCoordinate,
            footprintSource,
            quarterTurns,
            proposedInputCoordinate,
            proposedInputItemIds);
        return !hasPipePassItems || !hasInputItems || HasSharedItemId(pipePassItemIds, proposedInputItemIds);
    }

    private bool CanBoilerDirectSteamGeneratorInputConnection(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        return TryGetBoilerDirectSteamGeneratorInputPlacement(
            anchorCoordinate,
            footprintSource,
            quarterTurns,
            previewToIgnore,
            out _,
            out _);
    }

    private bool TryGetBoilerDirectSteamGeneratorInputPlacement(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore,
        out Vector2Int boilerOutputCoordinate,
        out Vector2Int steamInputCoordinate)
    {
        boilerOutputCoordinate = Vector2Int.zero;
        steamInputCoordinate = Vector2Int.zero;
        if (!TryResolveBoiler(footprintSource, out Boiler boiler)
            || !boiler.TryGetOutputCoordinateAndDirection(
                footprintSource,
                anchorCoordinate,
                quarterTurns,
                out Vector2Int proposedOutputCoordinate,
                out Vector2Int boilerOutputFlowDirection))
        {
            return false;
        }

        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate,
            quarterTurns = quarterTurns
        };

        pipeAreaBlockCandidateScratchA.Clear();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
            anchorCoordinate,
            previewToIgnore,
            pipeAreaBlockCandidateScratchA);

        for (int existingIndex = 0; existingIndex < pipeAreaBlockCandidateScratchA.Count; existingIndex++)
        {
            PipeAreaBlockCandidate existingInputCandidate = pipeAreaBlockCandidateScratchA[existingIndex];
            if (existingInputCandidate.snapshot == null
                || !TryResolveSteamGenerator(existingInputCandidate.snapshot.mapObject, out SteamGenerator steamGenerator)
                || !InputOutputModule.IsInputItemBlockType(existingInputCandidate.blockType)
                || !steamGenerator.TryGetBodyDirectionFromCenter(
                    existingInputCandidate.snapshot.mapObject,
                    existingInputCandidate.snapshot.quarterTurns,
                    out Vector2Int steamBodyDirection)
                || steamBodyDirection == Vector2Int.zero
                || anchorCoordinate != existingInputCandidate.snapshot.anchorCoordinate - steamBodyDirection)
            {
                continue;
            }

            Vector2Int requiredOutputCoordinate = existingInputCandidate.snapshot.anchorCoordinate;
            if (proposedOutputCoordinate != requiredOutputCoordinate
                || boilerOutputFlowDirection != steamBodyDirection)
            {
                continue;
            }

            if (BoilerOutputItemsMatchSteamGeneratorInput(
                    anchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    anchorCoordinate,
                    existingInputCandidate))
            {
                boilerOutputCoordinate = proposedOutputCoordinate;
                steamInputCoordinate = anchorCoordinate;
                pipeAreaBlockCandidateScratchA.Clear();
                return true;
            }
        }

        pipeAreaBlockCandidateScratchA.Clear();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
            proposedOutputCoordinate,
            previewToIgnore,
            pipeAreaBlockCandidateScratchA);

        for (int existingIndex = 0; existingIndex < pipeAreaBlockCandidateScratchA.Count; existingIndex++)
        {
            PipeAreaBlockCandidate existingInputCandidate = pipeAreaBlockCandidateScratchA[existingIndex];
            if (existingInputCandidate.snapshot == null
                || !TryResolveSteamGenerator(existingInputCandidate.snapshot.mapObject, out SteamGenerator steamGenerator)
                || !InputOutputModule.IsInputItemBlockType(existingInputCandidate.blockType)
                || !steamGenerator.TryGetInputDirectionAtCoordinate(
                    existingInputCandidate.snapshot.mapObject,
                    existingInputCandidate.snapshot.anchorCoordinate,
                    existingInputCandidate.snapshot.quarterTurns,
                    proposedOutputCoordinate,
                    out Vector2Int steamInputDirection)
                || steamInputDirection != boilerOutputFlowDirection)
            {
                continue;
            }

            if (BoilerOutputItemsMatchSteamGeneratorInput(
                    anchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    proposedOutputCoordinate,
                    existingInputCandidate))
            {
                boilerOutputCoordinate = proposedOutputCoordinate;
                steamInputCoordinate = proposedOutputCoordinate;
                pipeAreaBlockCandidateScratchA.Clear();
                return true;
            }
        }

        pipeAreaBlockCandidateScratchA.Clear();
        return false;
    }

    private bool CanBoilerObjectOnBoilerPipePassConnection(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (!IsBoilerSource(footprintSource)
            || !TryGetRectGridBlockCoordinates(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                InputOutputModule.RectGridBlockType.Object,
                out List<Vector2Int> objectCoordinates))
        {
            return false;
        }

        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate,
            quarterTurns = quarterTurns
        };

        for (int i = 0; i < objectCoordinates.Count; i++)
        {
            if (BoilerObjectMatchesExistingBoilerPipePassDirection(
                    objectCoordinates[i],
                    proposedSnapshot,
                    previewToIgnore))
            {
                return true;
            }
        }

        return false;
    }

    private bool CanBoilerPipePassConnectExistingBoilerPipePass(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (!IsBoilerSource(footprintSource)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (placements == null || placements.Count <= 0)
        {
            return false;
        }

        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate,
            quarterTurns = quarterTurns
        };

        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (!IsPipePassBlockType(placement.blockType)
                || !TryGetRectGridCoordinate(
                    anchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    placement,
                    out Vector2Int proposedPipePassCoordinate))
            {
                continue;
            }

            PipeAreaBlockCandidate proposedCandidate =
                new PipeAreaBlockCandidate(proposedSnapshot, placement.blockType);
            if (BoilerPipePassConnectsExistingBoilerPipePassAtOrAdjacentCoordinate(
                    proposedPipePassCoordinate,
                    proposedCandidate,
                    previewToIgnore))
            {
                return true;
            }
        }

        return false;
    }

    private bool BoilerPipePassConnectsExistingBoilerPipePassAtOrAdjacentCoordinate(
        Vector2Int proposedPipePassCoordinate,
        PipeAreaBlockCandidate proposedCandidate,
        MapObject previewToIgnore)
    {
        if (BoilerPipePassConnectsExistingBoilerPipePassAtCoordinate(
                proposedPipePassCoordinate,
                proposedCandidate,
                proposedPipePassCoordinate,
                previewToIgnore))
        {
            return true;
        }

        for (int directionIndex = 0; directionIndex < PipeCardinalDirections.Length; directionIndex++)
        {
            Vector2Int existingPipePassCoordinate =
                proposedPipePassCoordinate + PipeCardinalDirections[directionIndex];
            if (BoilerPipePassConnectsExistingBoilerPipePassAtCoordinate(
                    proposedPipePassCoordinate,
                    proposedCandidate,
                    existingPipePassCoordinate,
                    previewToIgnore))
            {
                return true;
            }
        }

        return false;
    }

    private bool BoilerPipePassConnectsExistingBoilerPipePassAtCoordinate(
        Vector2Int proposedPipePassCoordinate,
        PipeAreaBlockCandidate proposedCandidate,
        Vector2Int existingPipePassCoordinate,
        MapObject previewToIgnore)
    {
        if (proposedCandidate.snapshot == null || !IsPipePassBlockType(proposedCandidate.blockType))
        {
            return false;
        }

        List<PipeAreaBlockCandidate> existingPipePassCandidates =
            CollectPipePassCandidatesAtCoordinate(existingPipePassCoordinate, previewToIgnore);
        for (int i = 0; i < existingPipePassCandidates.Count; i++)
        {
            PipeAreaBlockCandidate existingCandidate = existingPipePassCandidates[i];
            if (existingCandidate.snapshot == null
                || !IsBoilerSource(existingCandidate.snapshot.mapObject))
            {
                continue;
            }

            if (CanPipeAreaBlockCandidatesConnect(
                    proposedPipePassCoordinate,
                    proposedCandidate,
                    existingPipePassCoordinate,
                    existingCandidate))
            {
                return true;
            }
        }

        return false;
    }

    private bool BoilerObjectMatchesExistingBoilerPipePassDirection(
        Vector2Int objectCoordinate,
        PlacementSnapshot proposedSnapshot,
        MapObject previewToIgnore)
    {
        return BoilerObjectMatchesExistingBoilerPipePassDirection(
            objectCoordinate,
            proposedSnapshot,
            previewToIgnore,
            null);
    }

    private bool BoilerObjectMatchesExistingBoilerPipePassDirection(
        Vector2Int objectCoordinate,
        PlacementSnapshot proposedSnapshot,
        MapObject previewToIgnore,
        Vector2Int? requiredProposedPipePassCoordinate)
    {
        if (proposedSnapshot == null || !IsBoilerSource(proposedSnapshot.mapObject))
        {
            return false;
        }

        List<PipeAreaBlockCandidate> pipePassCandidates = CollectPipePassCandidatesAtCoordinate(
            objectCoordinate,
            previewToIgnore);
        for (int i = 0; i < pipePassCandidates.Count; i++)
        {
            PipeAreaBlockCandidate existingCandidate = pipePassCandidates[i];
            if (existingCandidate.snapshot == null
                || !IsBoilerSource(existingCandidate.snapshot.mapObject)
                || !TryGetPipeAreaObjectDirection(
                    objectCoordinate,
                    existingCandidate,
                    out Vector2Int existingPipePassDirection))
            {
                continue;
            }

            Vector2Int proposedPipePassCoordinate = objectCoordinate + existingPipePassDirection;
            if (requiredProposedPipePassCoordinate.HasValue
                && proposedPipePassCoordinate != requiredProposedPipePassCoordinate.Value)
            {
                continue;
            }

            if (!TryGetBoilerPipePassDirectionAtCoordinate(
                    proposedSnapshot.mapObject,
                    proposedSnapshot.anchorCoordinate,
                    proposedSnapshot.quarterTurns,
                    proposedPipePassCoordinate,
                    out Vector2Int proposedPipePassDirection)
                || proposedPipePassDirection != -existingPipePassDirection)
            {
                continue;
            }

            PipeAreaBlockCandidate proposedCandidate = new PipeAreaBlockCandidate(
                proposedSnapshot,
                InputOutputModule.RectGridBlockType.PipeInput);
            if (PipePassItemsMatchPipePass(existingCandidate, proposedCandidate))
            {
                return true;
            }
        }

        return false;
    }

    private bool BoilerOutputItemsMatchSteamGeneratorInput(
        Vector2Int boilerAnchorCoordinate,
        MapObject boilerSource,
        int boilerQuarterTurns,
        Vector2Int steamInputCoordinate,
        PipeAreaBlockCandidate steamInputCandidate)
    {
        HashSet<int> outputItemIds = new HashSet<int>();
        HashSet<int> inputItemIds = new HashSet<int>();
        return TryGetCandidateOutputItemIds(
                boilerAnchorCoordinate,
                boilerSource,
                boilerQuarterTurns,
                outputItemIds)
            && steamInputCandidate.snapshot != null
            && TryGetCandidateInputItemIdsAtCoordinate(
                steamInputCandidate.snapshot.anchorCoordinate,
                steamInputCandidate.snapshot.mapObject,
                steamInputCandidate.snapshot.quarterTurns,
                steamInputCoordinate,
                inputItemIds)
            && HasSharedItemId(outputItemIds, inputItemIds);
    }

    private bool TryGetBoilerOutputItemIdsAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        ISet<int> outputItemIds)
    {
        if (outputItemIds == null)
        {
            return false;
        }

        pipeAreaBlockCandidateScratchA.Clear();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
            coordinate,
            previewToIgnore,
            pipeAreaBlockCandidateScratchA);

        for (int i = 0; i < pipeAreaBlockCandidateScratchA.Count; i++)
        {
            PipeAreaBlockCandidate candidate = pipeAreaBlockCandidateScratchA[i];
            if (candidate.snapshot == null
                || !IsBoilerSource(candidate.snapshot.mapObject)
                || !InputOutputModule.IsOutputBlockType(candidate.blockType))
            {
                continue;
            }

            bool foundOutput = TryGetCandidateOutputItemIds(
                candidate.snapshot.anchorCoordinate,
                candidate.snapshot.mapObject,
                candidate.snapshot.quarterTurns,
                outputItemIds);
            pipeAreaBlockCandidateScratchA.Clear();
            return foundOutput;
        }

        pipeAreaBlockCandidateScratchA.Clear();
        return false;
    }

    private bool PipeAreaConnectionAtCoordinateIsCompatible(
        Vector2Int proposedCoordinate,
        PipeAreaBlockCandidate proposedCandidate,
        Vector2Int connectorCoordinate,
        MapObject previewToIgnore)
    {
        bool hasConnector = false;
        bool hasCompatibleConnector = false;
        List<Vector2Int> pipeConnectionDirections = new List<Vector2Int>(4);
        if (TryGetPipePlacementAtCoordinate(
                connectorCoordinate,
                previewToIgnore,
                out Pipe connectorPipe,
                out Quaternion connectorPipeRotation)
            && TryGetProposedPipeAreaPipeConnectionDirections(
                proposedCoordinate,
                proposedCandidate,
                connectorCoordinate,
                pipeConnectionDirections))
        {
            hasConnector = true;
            for (int i = 0; i < pipeConnectionDirections.Count; i++)
            {
                Vector2Int pipeConnectionDirection = pipeConnectionDirections[i];
                if (pipeConnectionDirection == Vector2Int.zero)
                {
                    continue;
                }

                if (TryResolvePipeVariantForForcedConnection(
                        connectorCoordinate,
                        connectorPipe,
                        connectorPipeRotation,
                        pipeConnectionDirection,
                        out Pipe resolvedPipe,
                        out Quaternion resolvedPipeRotation)
                    && PipeAreaCandidateFluidMatchesPipeNetwork(
                        connectorCoordinate,
                        resolvedPipe,
                        resolvedPipeRotation,
                        proposedCoordinate,
                        proposedCandidate,
                        previewToIgnore))
                {
                    hasCompatibleConnector = true;
                    break;
                }
            }

            if (!hasCompatibleConnector
                && TryResolvePipeVariantAvoidingConnections(
                    connectorCoordinate,
                    connectorPipe,
                    connectorPipeRotation,
                    pipeConnectionDirections,
                    previewToIgnore,
                    out _,
                    out _))
            {
                // The fixed connector remains in place, but the ordinary pipe turns
                // away. Adjacency is therefore valid without creating a fluid link.
                hasCompatibleConnector = true;
            }
        }

        pipeAreaBlockCandidateScratchA.Clear();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
            connectorCoordinate,
            previewToIgnore,
            pipeAreaBlockCandidateScratchA);

        for (int i = 0; i < pipeAreaBlockCandidateScratchA.Count; i++)
        {
            PipeAreaBlockCandidate connectorCandidate = pipeAreaBlockCandidateScratchA[i];
            if (connectorCandidate.snapshot == null
                || connectorCandidate.snapshot.mapObject == proposedCandidate.snapshot.mapObject)
            {
                continue;
            }

            if (!PipeAreaBlockCandidatesWouldConnect(
                    proposedCoordinate,
                    proposedCandidate,
                    connectorCoordinate,
                    connectorCandidate))
            {
                continue;
            }

            hasConnector = true;
            if (CanPipeAreaBlockCandidatesConnect(
                    proposedCoordinate,
                    proposedCandidate,
                    connectorCoordinate,
                    connectorCandidate))
            {
                hasCompatibleConnector = true;
                break;
            }
        }

        pipeAreaBlockCandidateScratchA.Clear();
        return !hasConnector || hasCompatibleConnector;
    }

    private bool TryGetProposedPipeAreaPipeConnectionDirections(
        Vector2Int proposedCoordinate,
        PipeAreaBlockCandidate proposedCandidate,
        Vector2Int pipeCoordinate,
        List<Vector2Int> pipeConnectionDirections)
    {
        if (pipeConnectionDirections == null || proposedCandidate.snapshot == null)
        {
            return false;
        }

        int beforeCount = pipeConnectionDirections.Count;
        if (pipeCoordinate == proposedCoordinate)
        {
            TryGetPipeAreaCandidateConnectionDirections(
                proposedCoordinate,
                proposedCandidate,
                pipeConnectionDirections);
            return pipeConnectionDirections.Count > beforeCount;
        }

        Vector2Int directionFromAreaToPipe = pipeCoordinate - proposedCoordinate;
        if (!IsCardinalPipeDirection(directionFromAreaToPipe)
            || !TryResolveFixedFluidConnectorCompatibility(
                proposedCandidate.snapshot,
                proposedCoordinate,
                directionFromAreaToPipe,
                out bool connectorCanConnect)
            || !connectorCanConnect)
        {
            return false;
        }

        AddPipeDirection(pipeConnectionDirections, -directionFromAreaToPipe);
        return pipeConnectionDirections.Count > beforeCount;
    }

    private static bool IsFluidStoragePlacementObject(MapObject mapObject)
    {
        return mapObject is InstallationObject installationObject
               && installationObject.CanStoreFluid
               && !(installationObject is Pipe)
               && !(installationObject is Pump);
    }

    private bool CanPlacePipeNearFixedFluidConnectors(
        Vector2Int pipeCoordinate,
        Pipe pipePrefab,
        int quarterTurns)
    {
        if (pipePrefab == null)
        {
            return true;
        }

        Quaternion pipeRotation = GetPlacementObjectRotation(pipePrefab, quarterTurns);
        for (int i = 0; i < PipeCardinalDirections.Length; i++)
        {
            Vector2Int directionToConnector = PipeCardinalDirections[i];
            Vector2Int connectorCoordinate = pipeCoordinate + directionToConnector;
            Vector2Int directionToPipe = -directionToConnector;

            if (!TryGetFixedFluidConnectorCompatibilityAtCoordinate(
                    connectorCoordinate,
                    directionToPipe,
                    out bool connectorCanConnect))
            {
                continue;
            }

            if (connectorCanConnect
                && !CanPipeAreaBlocksConnect(pipeCoordinate, connectorCoordinate))
            {
                return false;
            }

            if (connectorCanConnect
                && !pipePrefab.HasConnectionTowards(pipeRotation, directionToConnector))
            {
                return false;
            }
        }

        return CanPipePlacementFluidConnectionsMatch(
            pipeCoordinate,
            pipePrefab,
            pipeRotation,
            null);
    }

    private bool CanResolvedPipePlacementMatchFixedFluidConnectors(
        Vector2Int pipeCoordinate,
        Pipe pipePrefab,
        int quarterTurns)
    {
        if (pipePrefab == null)
        {
            return true;
        }

        // An explicitly rotated blueprint has already selected exactly one adjacent
        // pipe set. Other fixed endpoints are deliberately disconnected, so the
        // generic rule that forces every compatible fixed connector must not reject
        // that valid manual topology.
        if (TryGetManualPipeConnectionMask(
                pipeCoordinate,
                null,
                out int manualConnectionMask)
            && HasValidManualPipeConnectionMask(manualConnectionMask))
        {
            return true;
        }

        if (TryGetFixedFluidPipeConnectionDirectionsAtCoordinate(pipeCoordinate, null, out _))
        {
            return CanPlacePipeOnFixedFluidConnectorCoordinate(
                pipeCoordinate,
                pipePrefab,
                quarterTurns);
        }

        return CanPlacePipeNearFixedFluidConnectors(
            pipeCoordinate,
            pipePrefab,
            quarterTurns);
    }

    private bool CanPlacePipeOnFixedFluidConnectorCoordinate(
        Vector2Int pipeCoordinate,
        Pipe pipePrefab,
        int quarterTurns)
    {
        if (pipePrefab == null)
        {
            return true;
        }

        if (!TryGetFixedFluidPipeConnectionDirectionsAtCoordinate(
                pipeCoordinate,
                null,
                out List<Vector2Int> pipeConnectionDirections))
        {
            return CanPipePlacementFluidConnectionsMatch(
                pipeCoordinate,
                pipePrefab,
                quarterTurns,
                null);
        }

        Quaternion pipeRotation = GetPlacementObjectRotation(pipePrefab, quarterTurns);
        return PipeHasConnectionTowardsAnyDirection(pipePrefab, pipeRotation, pipeConnectionDirections)
               && CanPipePlacementFluidConnectionsMatch(
                   pipeCoordinate,
                   pipePrefab,
                   pipeRotation,
                   null);
    }

    private bool CanPlacePipeOnFixedFluidConnectorArea(
        Block block,
        MapObject occupyingObject,
        MapObject footprintSource,
        int quarterTurns)
    {
        if (block == null
            || block.Type != Block.BlockType.Ground
            || !(footprintSource is Pipe pipePrefab))
        {
            return false;
        }

        if (IsFixedRectGridObjectBlockCoordinate(block.Coordinate))
        {
            return false;
        }

        if (occupyingObject != null && !IsPipePlacementAreaCoordinate(block.Coordinate))
        {
            return false;
        }

        if (TryGetFixedFluidPipeConnectionDirectionsAtCoordinate(
                block.Coordinate,
                null,
                out List<Vector2Int> pipeConnectionDirections))
        {
            Quaternion pipeRotation = GetPlacementObjectRotation(pipePrefab, quarterTurns);
            return PipeHasConnectionTowardsAnyDirection(pipePrefab, pipeRotation, pipeConnectionDirections)
                   && CanPipePlacementFluidConnectionsMatch(
                       block.Coordinate,
                       pipePrefab,
                       pipeRotation,
                       null);
        }

        return HasCompatibleFixedFluidConnectorAdjacentToPipe(
                   block.Coordinate,
                   pipePrefab,
                   quarterTurns)
               && CanPipePlacementFluidConnectionsMatch(
                   block.Coordinate,
                   pipePrefab,
                   quarterTurns,
                   null);
    }

    private bool IsFixedRectGridObjectBlockCoordinate(Vector2Int coordinate)
    {
        if (InputOutputModule.CoordinateIsRuntimeRectGridBlockType(
                coordinate,
                InputOutputModule.RectGridBlockType.Object))
        {
            return true;
        }

        if (TryGetPreviewPlacementSnapshot(coordinate, null, out PlacementSnapshot previewSnapshot)
            && SnapshotHasRectGridObjectBlock(previewSnapshot, coordinate))
        {
            return true;
        }

        if (TryGetInstalledPlacementSnapshot(coordinate, out PlacementSnapshot installedSnapshot)
            && SnapshotHasRectGridObjectBlock(installedSnapshot, coordinate))
        {
            return true;
        }

        if (TryGetSavedPlacementSnapshot(coordinate, out PlacementSnapshot savedSnapshot)
            && SnapshotHasRectGridObjectBlock(savedSnapshot, coordinate))
        {
            return true;
        }

        return false;
    }

    private bool SnapshotHasRectGridObjectBlock(PlacementSnapshot snapshot, Vector2Int coordinate)
    {
        if (snapshot == null || snapshot.mapObject == null)
        {
            return false;
        }

        MapObject footprintSource = ResolveInstallPreviewFootprintSource(snapshot.mapObject) ?? snapshot.mapObject;
        return TryGetRectGridFootprintBlockType(
                   snapshot.anchorCoordinate,
                   footprintSource,
                   snapshot.quarterTurns,
                   coordinate,
                   out InputOutputModule.RectGridBlockType blockType)
               && blockType == InputOutputModule.RectGridBlockType.Object;
    }

    private bool IsPipePlacementAreaCoordinate(Vector2Int coordinate)
    {
        if (InputOutputModule.CoordinateAllowsRuntimePipeBlock(coordinate)
            || IsPumpOutputCoordinateForPlacement(coordinate)
            || HasPipeAreaFluidStorageAtCoordinate(coordinate))
        {
            return true;
        }

        pipeAreaBlockCandidateScratchC.Clear();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
            coordinate,
            null,
            pipeAreaBlockCandidateScratchC);
        bool hasPipeArea = pipeAreaBlockCandidateScratchC.Count > 0;
        pipeAreaBlockCandidateScratchC.Clear();
        return hasPipeArea;
    }

    private bool HasCompatibleFixedFluidConnectorAdjacentToPipe(
        Vector2Int pipeCoordinate,
        Pipe pipePrefab,
        int quarterTurns)
    {
        if (pipePrefab == null)
        {
            return false;
        }

        Quaternion pipeRotation = GetPlacementObjectRotation(pipePrefab, quarterTurns);
        for (int i = 0; i < PipeCardinalDirections.Length; i++)
        {
            Vector2Int directionToConnector = PipeCardinalDirections[i];
            Vector2Int connectorCoordinate = pipeCoordinate + directionToConnector;
            Vector2Int directionToPipe = -directionToConnector;

            if (TryGetFixedFluidConnectorCompatibilityAtCoordinate(
                    connectorCoordinate,
                    directionToPipe,
                    out bool connectorCanConnect)
                && connectorCanConnect
                && CanPipeAreaBlocksConnect(pipeCoordinate, connectorCoordinate)
                && pipePrefab.HasConnectionTowards(pipeRotation, directionToConnector))
            {
                return true;
            }
        }

        return false;
    }

    private bool TryGetFixedFluidPipeConnectionDirectionsAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out List<Vector2Int> pipeConnectionDirections)
    {
        pipeConnectionDirections = new List<Vector2Int>(4);
        AppendFixedFluidPipeConnectionDirections(coordinate, previewToIgnore, pipeConnectionDirections);
        return pipeConnectionDirections.Count > 0;
    }

    private static bool PipeHasConnectionTowardsAnyDirection(
        Pipe pipePrefab,
        Quaternion pipeRotation,
        IReadOnlyList<Vector2Int> directions)
    {
        if (pipePrefab == null || directions == null || directions.Count <= 0)
        {
            return true;
        }

        for (int i = 0; i < directions.Count; i++)
        {
            Vector2Int direction = directions[i];
            if (direction == Vector2Int.zero)
            {
                continue;
            }

            if (pipePrefab.HasConnectionTowards(pipeRotation, direction))
            {
                return true;
            }
        }

        return false;
    }

    private bool TryGetBoilerFixedFluidConnectorCompatibilityAtCoordinate(
        Vector2Int connectorCoordinate,
        Vector2Int directionToPipe,
        out bool connectorCanConnect)
    {
        connectorCanConnect = false;
        if (directionToPipe == Vector2Int.zero)
        {
            return false;
        }

        if (TryGetPreviewPlacementSnapshot(connectorCoordinate, null, out PlacementSnapshot previewSnapshot)
            && TryResolveBoilerFixedFluidConnectorCompatibility(
                previewSnapshot,
                connectorCoordinate,
                directionToPipe,
                out connectorCanConnect))
        {
            return true;
        }

        if (TryGetInstalledPlacementSnapshot(connectorCoordinate, out PlacementSnapshot installedSnapshot)
            && TryResolveBoilerFixedFluidConnectorCompatibility(
                installedSnapshot,
                connectorCoordinate,
                directionToPipe,
                out connectorCanConnect))
        {
            return true;
        }

        if (TryGetRuntimeGridPlacementSnapshot(connectorCoordinate, out PlacementSnapshot runtimeGridSnapshot)
            && TryResolveBoilerFixedFluidConnectorCompatibility(
                runtimeGridSnapshot,
                connectorCoordinate,
                directionToPipe,
                out connectorCanConnect))
        {
            return true;
        }

        if (TryGetRuntimeAreaPlacementSnapshot(connectorCoordinate, out PlacementSnapshot runtimeAreaSnapshot)
            && TryResolveBoilerFixedFluidConnectorCompatibility(
                runtimeAreaSnapshot,
                connectorCoordinate,
                directionToPipe,
                out connectorCanConnect))
        {
            return true;
        }

        return TryGetSavedPlacementSnapshot(connectorCoordinate, out PlacementSnapshot savedSnapshot)
               && TryResolveBoilerFixedFluidConnectorCompatibility(
                   savedSnapshot,
                   connectorCoordinate,
                   directionToPipe,
                   out connectorCanConnect);
    }

    private bool TryResolveBoilerFixedFluidConnectorCompatibility(
        PlacementSnapshot connectorSnapshot,
        Vector2Int connectorCoordinate,
        Vector2Int directionToPipe,
        out bool connectorCanConnect)
    {
        connectorCanConnect = false;
        if (!(connectorSnapshot?.mapObject is Boiler))
        {
            return false;
        }

        if (TryResolveFixedFluidConnectorCompatibility(
            connectorSnapshot,
            connectorCoordinate,
            directionToPipe,
            out connectorCanConnect))
        {
            return true;
        }

        if (!SnapshotHasRectGridObjectBlock(connectorSnapshot, connectorCoordinate))
        {
            return false;
        }

        connectorCanConnect = BoilerHasPipePassFacingDirection(
            connectorSnapshot.mapObject,
            connectorSnapshot.anchorCoordinate,
            connectorSnapshot.quarterTurns,
            -directionToPipe);
        return connectorCanConnect;
    }

    private bool TryGetFixedFluidConnectorCompatibilityAtCoordinate(
        Vector2Int connectorCoordinate,
        Vector2Int directionToPipe,
        out bool connectorCanConnect)
    {
        connectorCanConnect = false;
        if (directionToPipe == Vector2Int.zero)
        {
            return false;
        }

        if (TryGetPreviewPlacementSnapshot(connectorCoordinate, null, out PlacementSnapshot previewSnapshot)
            && TryResolveFixedFluidConnectorCompatibility(
                previewSnapshot,
                connectorCoordinate,
                directionToPipe,
                out connectorCanConnect))
        {
            return true;
        }

        if (TryGetInstalledPlacementSnapshot(connectorCoordinate, out PlacementSnapshot installedSnapshot)
            && TryResolveFixedFluidConnectorCompatibility(
                installedSnapshot,
                connectorCoordinate,
                directionToPipe,
                out connectorCanConnect))
        {
            return true;
        }

        if (TryGetRuntimeGridPlacementSnapshot(connectorCoordinate, out PlacementSnapshot runtimeGridSnapshot)
            && TryResolveFixedFluidConnectorCompatibility(
                runtimeGridSnapshot,
                connectorCoordinate,
                directionToPipe,
                out connectorCanConnect))
        {
            return true;
        }

        if (TryGetRuntimeAreaPlacementSnapshot(connectorCoordinate, out PlacementSnapshot runtimeAreaSnapshot)
            && TryResolveFixedFluidConnectorCompatibility(
                runtimeAreaSnapshot,
                connectorCoordinate,
                directionToPipe,
                out connectorCanConnect))
        {
            return true;
        }

        return TryGetSavedPlacementSnapshot(connectorCoordinate, out PlacementSnapshot savedSnapshot)
               && TryResolveFixedFluidConnectorCompatibility(
                   savedSnapshot,
                   connectorCoordinate,
                   directionToPipe,
                   out connectorCanConnect);
    }

    private bool TryResolveFixedFluidConnectorCompatibility(
        PlacementSnapshot connectorSnapshot,
        Vector2Int connectorCoordinate,
        Vector2Int directionToPipe,
        out bool connectorCanConnect)
    {
        connectorCanConnect = false;
        if (connectorSnapshot == null)
        {
            return false;
        }

        return TryResolveFixedFluidConnectorCompatibility(
            connectorSnapshot.mapObject,
            connectorSnapshot.rotation,
            connectorSnapshot.anchorCoordinate,
            connectorSnapshot.quarterTurns,
            connectorCoordinate,
            directionToPipe,
            out connectorCanConnect);
    }

    private bool TryResolveFixedFluidConnectorCompatibility(
        MapObject connector,
        Quaternion connectorRotation,
        Vector2Int connectorAnchorCoordinate,
        int connectorQuarterTurns,
        Vector2Int connectorCoordinate,
        Vector2Int directionToPipe,
        out bool connectorCanConnect)
    {
        connectorCanConnect = false;
        if (connector == null || directionToPipe == Vector2Int.zero)
        {
            return false;
        }

        if (connector is Pump pump)
        {
            return TryResolvePumpFixedFluidConnectorCompatibility(
                pump,
                connectorRotation,
                connectorAnchorCoordinate,
                connectorQuarterTurns,
                connectorCoordinate,
                directionToPipe,
                out connectorCanConnect);
        }

        if (connector is Boiler boiler)
        {
            connectorCanConnect = CanBoilerConnectorBlockConnectPipeTowards(
                boiler,
                connectorAnchorCoordinate,
                connectorQuarterTurns,
                connectorCoordinate,
                directionToPipe);
            return connectorCanConnect;
        }

        if (TryGetInputOutputModule(connector, out InputOutputModule inputOutputModule))
        {
            if (!TryGetRectGridFootprintBlockType(
                    connectorAnchorCoordinate,
                    connector,
                    connectorQuarterTurns,
                    connectorCoordinate,
                    out InputOutputModule.RectGridBlockType blockType)
                || !InputOutputModule.AllowsPipeAreaInteraction(blockType)
                || !TryGetRectGridPipeAreaConnectionDirection(
                    connector,
                    inputOutputModule,
                    connectorAnchorCoordinate,
                    connectorQuarterTurns,
                    connectorCoordinate,
                    out Vector2Int connectionDirection))
            {
                return false;
            }

            connectorCanConnect = directionToPipe == connectionDirection;
            return true;
        }

        if (connector is InstallationObject fluidStorage
            && !(connector is Pipe)
            && !(connector is InputOutputModule)
            && fluidStorage.CanStoreFluid)
        {
            connectorCanConnect = IsCardinalPipeDirection(directionToPipe);
            return connectorCanConnect;
        }

        return false;
    }

    private bool TryResolvePumpFixedFluidConnectorCompatibility(
        Pump pump,
        Quaternion pumpRotation,
        Vector2Int pumpAnchorCoordinate,
        int pumpQuarterTurns,
        Vector2Int connectorCoordinate,
        Vector2Int directionToPipe,
        out bool connectorCanConnect)
    {
        connectorCanConnect = false;
        if (pump == null || directionToPipe == Vector2Int.zero)
        {
            return false;
        }

        if (TryGetRectGridFootprintBlockType(
                pumpAnchorCoordinate,
                pump,
                pumpQuarterTurns,
                connectorCoordinate,
                out InputOutputModule.RectGridBlockType blockType))
        {
            if (blockType != InputOutputModule.RectGridBlockType.PipeOutputItem)
            {
                return false;
            }

            connectorCanConnect = pump.TryGetPipeConnectionDirection(
                pumpRotation,
                out Vector2Int pumpOutputDirection)
                && directionToPipe == pumpOutputDirection;
            return connectorCanConnect;
        }

        connectorCanConnect = pump.HasPipeConnectionTowards(pumpRotation, directionToPipe);
        return connectorCanConnect;
    }

    private bool CanBoilerConnectorBlockConnectPipeTowards(
        Boiler boiler,
        Vector2Int boilerAnchorCoordinate,
        int boilerQuarterTurns,
        Vector2Int connectorCoordinate,
        Vector2Int directionToPipe)
    {
        // Boiler PipePass is the actual pipe tile. Allowing an adjacent pipe here
        // creates the recurring invalid layout: Pipe - empty PipePass tile - Boiler body.
        // Same-cell pipe overlap is handled by CanBoilerPipePassOverlapPipe.
        return false;
    }

    private bool TryAppendBoilerPipeAxisDirectionsAtCoordinate(
        Boiler boiler,
        Vector2Int boilerAnchorCoordinate,
        int boilerQuarterTurns,
        Vector2Int coordinate,
        List<Vector2Int> directions)
    {
        if (boiler == null || directions == null)
        {
            return false;
        }

        if (!TryGetRectGridFootprintBlockType(
                boilerAnchorCoordinate,
                boiler,
                boilerQuarterTurns,
                coordinate,
                out InputOutputModule.RectGridBlockType blockType)
            || blockType == InputOutputModule.RectGridBlockType.None)
        {
            return false;
        }

        if (blockType == InputOutputModule.RectGridBlockType.Object)
        {
            return false;
        }

        if (TryGetBoilerPipePassDirectionAtCoordinate(
                boiler,
                boilerAnchorCoordinate,
                boilerQuarterTurns,
                coordinate,
                out Vector2Int pipePassDirection))
        {
            // A pipe placed directly on a boiler PipePass cell connects to the boiler body only.
            // The opposite side must be counted only when an actual neighboring pipe exists;
            // otherwise a single side branch is incorrectly promoted from corner to tee.
            AddPipeDirection(directions, pipePassDirection);
            return true;
        }

        return false;
    }

    private bool CanBoilerPipePassOverlapPipe(
        Block block,
        MapObject occupyingObject,
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        if (block == null
            || !IsPipePassBlockType(rectGridBlockType)
            || !TryGetPipePlacementAtBlock(block, occupyingObject, out Pipe pipe, out Quaternion pipeRotation)
            || !TryGetBoilerPipePassDirectionAtCoordinate(
                footprintSource,
                anchorCoordinate,
                quarterTurns,
                block.Coordinate,
                out Vector2Int pipePassDirection))
        {
            return false;
        }

        if (!TryResolvePipeVariantForForcedConnection(
                block.Coordinate,
                pipe,
                pipeRotation,
                pipePassDirection,
                out Pipe resolvedPipe,
                out Quaternion resolvedPipeRotation))
        {
            return false;
        }

        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate,
            quarterTurns = quarterTurns
        };
        return PipeAreaCandidateFluidMatchesPipeNetwork(
            block.Coordinate,
            resolvedPipe,
            resolvedPipeRotation,
            block.Coordinate,
            new PipeAreaBlockCandidate(proposedSnapshot, rectGridBlockType),
            null);
    }

    private bool CanBoilerPipeOutputOverlapPipe(
        Block block,
        MapObject occupyingObject,
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        if (block == null
            || !IsBoilerSource(footprintSource)
            || !InputOutputModule.IsOutputBlockType(rectGridBlockType)
            || !TryGetPipePlacementAtBlock(block, occupyingObject, out Pipe pipe, out Quaternion pipeRotation)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
            || !TryGetRectGridPipeAreaConnectionDirection(
                footprintSource,
                inputOutputModule,
                anchorCoordinate,
                quarterTurns,
                block.Coordinate,
                out Vector2Int outputObjectDirection))
        {
            return false;
        }

        if (!TryResolvePipeVariantForForcedConnection(
                block.Coordinate,
                pipe,
                pipeRotation,
                outputObjectDirection,
                out Pipe resolvedPipe,
                out Quaternion resolvedPipeRotation))
        {
            return false;
        }

        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate,
            quarterTurns = quarterTurns
        };
        return PipeAreaCandidateFluidMatchesPipeNetwork(
            block.Coordinate,
            resolvedPipe,
            resolvedPipeRotation,
            block.Coordinate,
            new PipeAreaBlockCandidate(proposedSnapshot, rectGridBlockType),
            null);
    }

    private bool TryGetBoilerPipePassDirectionAtCoordinate(
        MapObject boilerSource,
        Vector2Int boilerAnchorCoordinate,
        int boilerQuarterTurns,
        Vector2Int coordinate,
        out Vector2Int pipePassDirection)
    {
        pipePassDirection = Vector2Int.zero;
        return TryResolveBoiler(boilerSource, out Boiler boiler)
               && boiler.TryGetPipePassDirectionAtCoordinate(
                   boilerSource,
                   boilerAnchorCoordinate,
                   boilerQuarterTurns,
                   coordinate,
                   out pipePassDirection)
               && pipePassDirection != Vector2Int.zero;
    }

    private static bool IsCardinalPipeDirection(Vector2Int direction)
    {
        return PipeDirectionsContain(PipeCardinalDirections, direction);
    }

    private void PrepareBelt2FBridgeCenterForPassthroughPlacement(Block block, MapObject passthroughSource)
    {
        if (!IsBelt2FPassthroughPlacementSource(passthroughSource)
            || block == null
            || !(block.MapObject is ConvayorBelt2F belt2F)
            || !belt2F.IsBridgeCenterCoordinate(block.Coordinate)
            || !belt2F.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out int quarterTurns))
        {
            return;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        terrain?.RemoveInstallationPersistence(belt2F);

        List<Vector2Int> blockingCoordinates = GetFootprintCoordinates(anchorCoordinate, belt2F, quarterTurns);
        blockingCoordinates.Remove(block.Coordinate);
        belt2F.ConfigurePlacementRuntime(
            anchorCoordinate,
            quarterTurns,
            blockingCoordinates,
            belt2F.RuntimePlacementSequence);

        ConvayorBelt2F.MarkCoverageDirty();
        belt2F.RefreshCoveredConveyorTopology();
        terrain?.RegisterLiveInstallationObject(belt2F);
    }

    private bool CanPlacePassthroughOnBelt2FBridgeCenter(
        Block block,
        MapObject footprintSource,
        MapObject occupyingObject,
        int quarterTurns)
    {
        if (!IsBelt2FPassthroughPlacementSource(footprintSource)
            || block == null
            || block.Type != Block.BlockType.Ground
            || !(occupyingObject is ConvayorBelt2F belt2F)
            || !belt2F.IsBridgeCenterCoordinate(block.Coordinate))
        {
            return false;
        }

        if (footprintSource is Pipe pipeFootprint)
        {
            return CanResolvedPipePlacementMatchFixedFluidConnectors(
                block.Coordinate,
                pipeFootprint,
                quarterTurns);
        }

        return true;
    }

    private static bool IsBelt2FPassthroughPlacementSource(MapObject mapObject)
    {
        return mapObject is Pipe || IsBaseConveyorBelt(mapObject);
    }

    private bool CanPlaceBelt2FBlock(
        Block block,
        MapObject footprintSource,
        MapObject occupyingObject,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        bool isInputOutputAreaBlock,
        InstallationMapFilter allowedFilter)
    {
        if (block == null
            || !anchorCoordinate.HasValue
            || block.Type != Block.BlockType.Ground
            || !CanPlaceOnTerrainBiome(block, allowedFilter))
        {
            return false;
        }

        bool isBridgeCenter = block.Coordinate == GetBelt2FBridgeCenterCoordinate(
            anchorCoordinate.Value,
            footprintSource,
            quarterTurns);
        if (IsResourceAllowedForPlacement(block, occupyingObject, allowedFilter))
        {
            return true;
        }

        if (isBridgeCenter)
        {
            if (isInputOutputAreaBlock)
            {
                return false;
            }

            if (occupyingObject == null || IsBaseConveyorBelt(occupyingObject))
            {
                return true;
            }

            return TryGetPipePlacementAtBlock(block, occupyingObject, out Pipe pipe, out Quaternion pipeRotation)
                   && IsBelt2FCrossingPipeDirectionAllowed(footprintSource, quarterTurns, pipe, pipeRotation);
        }

        return occupyingObject == null && !isInputOutputAreaBlock;
    }

    private bool CanPlaceBelt2FGridTargetBlock(Block block, MapObject footprintSource)
    {
        if (block == null || block.Type != Block.BlockType.Ground)
        {
            return false;
        }

        MapObject occupyingObject = GetOccupyingObjectForPlacement(block);

        InstallationMapFilter allowedFilter = TryResolveInstallationObject(footprintSource, out InstallationObject installationObject)
            ? ResolvePlacementMapFilter(footprintSource, installationObject)
            : InstallationMapFilter.Ground;
        if (!CanPlaceOnTerrainBiome(block, allowedFilter))
        {
            return false;
        }

        if (TryResolveInstallationObject(footprintSource, out installationObject)
            && IsResourceAllowedForPlacement(
                block,
                occupyingObject,
                allowedFilter))
        {
            return true;
        }

        if (IsRailloadAllowedForPlacement(block, occupyingObject, allowedFilter))
        {
            return true;
        }

        if (IsPipeAllowedForAnyBelt2FPlacementRotation(
                block,
                occupyingObject,
                footprintSource,
                allowedFilter))
        {
            return true;
        }

        bool isInputOutputAreaBlock =
            InputOutputModuleEnergyAreaController.CoordinateIsEnergyArea(block.Coordinate)
            || InputOutputModuleItemAreaController.CoordinateIsItemArea(block.Coordinate)
            || InputOutputModuleOutputAreaController.CoordinateIsOutputArea(block.Coordinate)
            || InputOutputModule.CoordinateIsRuntimeInputOutputAreaBlock(block.Coordinate);
        if (isInputOutputAreaBlock)
        {
            return false;
        }

        return occupyingObject == null
               || IsBaseConveyorBelt(occupyingObject)
               || (TryGetPipePlacementAtBlock(block, occupyingObject, out Pipe pipe, out Quaternion pipeRotation)
                   && IsBelt2FCrossingPipeDirectionAllowed(footprintSource, 0, pipe, pipeRotation));
    }

    private bool ShouldSkipBelt2FBridgeCenterBinding(
        Block block,
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns)
    {
        if (block == null
            || !IsBelt2F(footprintSource)
            || block.Coordinate != GetBelt2FBridgeCenterCoordinate(anchorCoordinate, footprintSource, quarterTurns))
        {
            return false;
        }

        return IsBelt2FBridgeCenterBlockedByPassthroughObject(block);
    }

    private bool ShouldSkipBelt2FBridgeCenterBinding(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        out Vector2Int bridgeCenterCoordinate)
    {
        bridgeCenterCoordinate = Vector2Int.zero;
        if (!IsBelt2F(footprintSource))
        {
            return false;
        }

        bridgeCenterCoordinate = GetBelt2FBridgeCenterCoordinate(anchorCoordinate, footprintSource, quarterTurns);
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        return terrain != null
               && terrain.TryGetLoadedBlock(bridgeCenterCoordinate, out Block bridgeCenterBlock)
               && bridgeCenterBlock != null
               && IsBelt2FBridgeCenterBlockedByPassthroughObject(bridgeCenterBlock);
    }

    private bool IsBelt2FBridgeCenterBlockedByPassthroughObject(Block block)
    {
        if (block == null)
        {
            return false;
        }

        MapObject occupyingObject = GetOccupyingObjectForPlacement(block);
        return IsBaseConveyorBelt(occupyingObject) || occupyingObject is Pipe;
    }

    private static bool IsBaseConveyorBelt(MapObject mapObject)
    {
        return mapObject is ConveyorBelt && !IsBelt2F(mapObject);
    }

    private static bool IsBelt2F(MapObject mapObject)
    {
        return mapObject is ConvayorBelt2F;
    }

    private bool CanPlaceOnTerrainBiome(Block block, InstallationMapFilter allowedFilter)
    {
        if (block == null || block.Type != Block.BlockType.Ground)
        {
            return false;
        }

        if (IsWaterBiomeBlock(block))
        {
            return (allowedFilter & InstallationMapFilter.Water) != 0;
        }

        if (IsWaterOutlineBiomeBlock(block))
        {
            return (allowedFilter & InstallationMapFilter.WaterOutline) != 0;
        }

        return (allowedFilter & InstallationMapFilter.Ground) != 0;
    }

    private bool IsWaterBiomeBlock(Block block)
    {
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        return terrain != null
               && block != null
               && terrain.IsWaterBiomeAt(block.Coordinate);
    }

    private bool IsWaterOutlineBiomeBlock(Block block)
    {
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null || block == null || terrain.IsWaterBiomeAt(block.Coordinate))
        {
            return false;
        }

        Vector2Int coordinate = block.Coordinate;
        for (int y = -1; y <= 1; y++)
        {
            for (int x = -1; x <= 1; x++)
            {
                if (x == 0 && y == 0)
                {
                    continue;
                }

                if (terrain.IsWaterBiomeAt(coordinate + new Vector2Int(x, y)))
                {
                    return true;
                }
            }
        }

        return false;
    }

    private bool IsWaterPumpCardinalShoreCoordinate(Vector2Int coordinate)
    {
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        return terrain != null
               && !terrain.IsWaterBiomeAt(coordinate)
               && HasCardinalWaterNeighbor(coordinate, terrain);
    }

    private bool TryResolveWaterPumpOutwardQuarterTurns(
        Vector2Int coordinate,
        MapObject sourcePrefab,
        int fallbackQuarterTurns,
        out int quarterTurns)
    {
        quarterTurns = NormalizePlacementQuarterTurnsForObject(sourcePrefab, fallbackQuarterTurns);
        if (!IsWaterPumpSource(sourcePrefab))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null || terrain.IsWaterBiomeAt(coordinate))
        {
            return false;
        }

        List<int> candidateQuarterTurns = GetWaterPumpOutwardQuarterTurnCandidates(coordinate, terrain);
        for (int i = candidateQuarterTurns.Count - 1; i >= 0; i--)
        {
            int candidate = candidateQuarterTurns[i];
            if (NormalizePlacementQuarterTurnsForObject(sourcePrefab, candidate) != candidate)
            {
                candidateQuarterTurns.RemoveAt(i);
            }
        }

        if (candidateQuarterTurns.Count <= 0)
        {
            return false;
        }

        quarterTurns = ResolvePreferredWaterPumpOutwardQuarterTurns(
            candidateQuarterTurns,
            quarterTurns);
        return true;
    }

    private static List<int> GetWaterPumpOutwardQuarterTurnCandidates(
        Vector2Int coordinate,
        TerrainGenerator terrain)
    {
        List<int> candidates = new List<int>();
        if (terrain == null)
        {
            return candidates;
        }

        AppendWaterPumpCardinalOutwardQuarterTurnCandidates(coordinate, terrain, candidates);
        return candidates;
    }

    private static bool HasCardinalWaterNeighbor(Vector2Int coordinate, TerrainGenerator terrain)
    {
        if (terrain == null)
        {
            return false;
        }

        for (int i = 0; i < WaterPumpCardinalProbeDirections.Length; i++)
        {
            Vector2Int waterDirection = WaterPumpCardinalProbeDirections[i];
            if (terrain.IsWaterBiomeAt(coordinate + waterDirection))
            {
                return true;
            }
        }

        return false;
    }

    private static void AppendWaterPumpCardinalOutwardQuarterTurnCandidates(
        Vector2Int coordinate,
        TerrainGenerator terrain,
        List<int> candidates)
    {
        if (terrain == null || candidates == null)
        {
            return;
        }

        for (int i = 0; i < WaterPumpCardinalProbeDirections.Length; i++)
        {
            Vector2Int waterDirection = WaterPumpCardinalProbeDirections[i];
            if (!terrain.IsWaterBiomeAt(coordinate + waterDirection))
            {
                continue;
            }

            AddWaterPumpQuarterTurnCandidate(candidates, -waterDirection);
        }
    }

    private static void AddWaterPumpQuarterTurnCandidate(List<int> candidates, Vector2Int outwardDirection)
    {
        if (candidates == null || !TryGetQuarterTurnsForCardinalDirection(outwardDirection, out int quarterTurns))
        {
            return;
        }

        if (!candidates.Contains(quarterTurns))
        {
            candidates.Add(quarterTurns);
        }
    }

    private static int ResolvePreferredWaterPumpOutwardQuarterTurns(
        IReadOnlyList<int> candidates,
        int preferredQuarterTurns)
    {
        int normalizedPreferred = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        int bestQuarterTurns = normalizedPreferred;
        int bestClockwiseDelta = 4;
        for (int i = 0; i < candidates.Count; i++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurns(candidates[i]);
            int clockwiseDelta = NormalizePlacementQuarterTurns(candidateQuarterTurns - normalizedPreferred);
            if (clockwiseDelta >= bestClockwiseDelta)
            {
                continue;
            }

            bestClockwiseDelta = clockwiseDelta;
            bestQuarterTurns = candidateQuarterTurns;
        }

        return bestQuarterTurns;
    }

    private static bool IsWaterPumpSource(MapObject sourcePrefab)
    {
        if (sourcePrefab == null)
        {
            return false;
        }

        return sourcePrefab is Pump
               || sourcePrefab.GetComponent<Pump>() != null
               || sourcePrefab.GetComponentInChildren<Pump>(true) != null;
    }

    private static bool TryGetQuarterTurnsForCardinalDirection(
        Vector2Int direction,
        out int quarterTurns)
    {
        quarterTurns = 0;
        if (direction == Vector2Int.zero)
        {
            return false;
        }

        if (direction == Vector2Int.up)
        {
            quarterTurns = 0;
            return true;
        }

        if (direction == Vector2Int.right)
        {
            quarterTurns = 1;
            return true;
        }

        if (direction == Vector2Int.down)
        {
            quarterTurns = 2;
            return true;
        }

        if (direction == Vector2Int.left)
        {
            quarterTurns = 3;
            return true;
        }

        return false;
    }

    public static InstallationMapFilter ResolvePlacementMapFilter(
        MapObject footprintSource,
        InstallationObject installationObject)
    {
        if (footprintSource is ConveyorBelt conveyorBelt && conveyorBelt.IsCornerVariant)
        {
            ConveyorBelt straightPrefab = conveyorBelt.StraightVariantPrefab;
            if (straightPrefab != null)
            {
                return straightPrefab.MapFilter;
            }
        }

        if (footprintSource is Wall wall && wall.StraightVariantPrefab != null && wall.StraightVariantPrefab != wall)
        {
            return wall.StraightVariantPrefab.MapFilter;
        }

        if (footprintSource is Pipe pipe && pipe.StraightVariantPrefab != null && pipe.StraightVariantPrefab != pipe)
        {
            return pipe.StraightVariantPrefab.MapFilter;
        }

        return installationObject != null
            ? installationObject.MapFilter
            : InstallationMapFilter.Ground;
    }

    private static InstallationMapFilter ResolveRectGridTerrainFilter(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        InstallationMapFilter fallbackFilter)
    {
        if (!IsWaterPumpSource(footprintSource))
        {
            return fallbackFilter;
        }

        if (IsWaterPumpPipeInputBlockType(rectGridBlockType))
        {
            return InstallationMapFilter.Water;
        }

        if (rectGridBlockType == InputOutputModule.RectGridBlockType.PipeOutputItem)
        {
            return InstallationMapFilter.Ground | InstallationMapFilter.WaterOutline;
        }

        return fallbackFilter;
    }

    private static bool IsWaterPumpPipeInputBlockType(InputOutputModule.RectGridBlockType blockType)
    {
        return blockType == InputOutputModule.RectGridBlockType.PipeInput
               || blockType == InputOutputModule.RectGridBlockType.PipeInputItem
               || blockType == InputOutputModule.RectGridBlockType.PipeInputEnergy;
    }

    private bool CanPlaceRectGridAreaBlock(
        Block block,
        MapObject occupyingObject,
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        bool hasExistingInputOutputEnergyAreaBlock,
        bool hasExistingInputOutputItemAreaBlock,
        bool hasExistingInputOutputOutputAreaBlock,
        InstallationMapFilter allowedFilter)
    {
        if (!CanPlaceOnTerrainBiome(block, allowedFilter))
        {
            return false;
        }

        bool hasExistingInputOutputAreaBlock =
            hasExistingInputOutputEnergyAreaBlock
            || hasExistingInputOutputItemAreaBlock
            || hasExistingInputOutputOutputAreaBlock;
        if (hasExistingInputOutputAreaBlock
            && !CanOverlapCompatibleItemArea(
                block.Coordinate,
                footprintSource,
                rectGridBlockType,
                anchorCoordinate,
                quarterTurns,
                hasExistingInputOutputEnergyAreaBlock,
                hasExistingInputOutputItemAreaBlock,
                hasExistingInputOutputOutputAreaBlock))
        {
            return false;
        }

        if (occupyingObject == null || occupyingObject is BoxObject)
        {
            return true;
        }

        if (occupyingObject is Pipe
            && InputOutputModule.AllowsPipeAreaInteraction(rectGridBlockType))
        {
            if (IsSteamGeneratorSource(footprintSource))
            {
                return SteamGeneratorPipeAreaOverlapsPipeDirection(
                    block,
                    footprintSource,
                    occupyingObject,
                    anchorCoordinate,
                    quarterTurns);
            }

            return !IsBoilerSource(footprintSource)
                   || CanBoilerPipePassOverlapPipe(
                       block,
                       occupyingObject,
                       footprintSource,
                       rectGridBlockType,
                       anchorCoordinate,
                       quarterTurns)
                   || CanBoilerPipeOutputOverlapPipe(
                       block,
                       occupyingObject,
                       footprintSource,
                       rectGridBlockType,
                       anchorCoordinate,
                       quarterTurns);
        }

        return occupyingObject is Resource resource
            && IsResourceAllowedByMapFilter(resource, allowedFilter);
    }

    private bool CanPlaceCompatibleRectGridOverlap(
        MapObject candidateFootprintSource,
        InputOutputModule.RectGridBlockType candidateBlockType,
        Block block,
        Vector2Int? candidateAnchorCoordinate,
        int candidateQuarterTurns,
        MapObject previewToIgnore)
    {
        if (candidateFootprintSource == null
            || candidateBlockType == InputOutputModule.RectGridBlockType.None
            || block == null
            || !candidateAnchorCoordinate.HasValue)
        {
            return false;
        }

        bool foundExistingRectGridBlock = false;
        bool foundCompatibleOverlap = false;
        bool hasIncompatibleOverlap = false;

        EvaluateCompatibleRectGridOverlap(
            block.Coordinate,
            candidateFootprintSource,
            candidateBlockType,
            candidateAnchorCoordinate.Value,
            candidateQuarterTurns,
            previewToIgnore,
            ref foundExistingRectGridBlock,
            ref foundCompatibleOverlap,
            ref hasIncompatibleOverlap);

        return foundExistingRectGridBlock && foundCompatibleOverlap && !hasIncompatibleOverlap;
    }

    private void EvaluateCompatibleRectGridOverlap(
        Vector2Int coordinate,
        MapObject candidateFootprintSource,
        InputOutputModule.RectGridBlockType candidateBlockType,
        Vector2Int candidateAnchorCoordinate,
        int candidateQuarterTurns,
        MapObject previewToIgnore,
        ref bool foundExistingRectGridBlock,
        ref bool foundCompatibleOverlap,
        ref bool hasIncompatibleOverlap)
    {
        if (TryGetPreviewPlacementSnapshot(coordinate, previewToIgnore, out PlacementSnapshot previewSnapshot))
        {
            EvaluateCompatibleRectGridOverlap(
                coordinate,
                candidateFootprintSource,
                candidateBlockType,
                candidateAnchorCoordinate,
                candidateQuarterTurns,
                previewSnapshot,
                ref foundExistingRectGridBlock,
                ref foundCompatibleOverlap,
                ref hasIncompatibleOverlap);
            if (hasIncompatibleOverlap)
            {
                return;
            }
        }

        if (TryGetInstalledPlacementSnapshot(coordinate, out PlacementSnapshot installedSnapshot))
        {
            EvaluateCompatibleRectGridOverlap(
                coordinate,
                candidateFootprintSource,
                candidateBlockType,
                candidateAnchorCoordinate,
                candidateQuarterTurns,
                installedSnapshot,
                ref foundExistingRectGridBlock,
                ref foundCompatibleOverlap,
                ref hasIncompatibleOverlap);
            if (hasIncompatibleOverlap)
            {
                return;
            }
        }

        runtimeGridModuleScratch.Clear();
        if (InputOutputModule.CollectModulesAtRuntimeGridCoordinate(coordinate, runtimeGridModuleScratch))
        {
            for (int i = 0; i < runtimeGridModuleScratch.Count; i++)
            {
                if (TryGetRuntimeModulePlacementSnapshot(
                        runtimeGridModuleScratch[i],
                        out PlacementSnapshot runtimeGridSnapshot))
                {
                    EvaluateCompatibleRectGridOverlap(
                        coordinate,
                        candidateFootprintSource,
                        candidateBlockType,
                        candidateAnchorCoordinate,
                        candidateQuarterTurns,
                        runtimeGridSnapshot,
                        ref foundExistingRectGridBlock,
                        ref foundCompatibleOverlap,
                        ref hasIncompatibleOverlap);
                    if (hasIncompatibleOverlap)
                    {
                        break;
                    }
                }
            }

            runtimeGridModuleScratch.Clear();
            if (hasIncompatibleOverlap)
            {
                return;
            }
        }
        else if (TryGetRuntimeGridPlacementSnapshot(coordinate, out PlacementSnapshot runtimeGridSnapshot))
        {
            EvaluateCompatibleRectGridOverlap(
                coordinate,
                candidateFootprintSource,
                candidateBlockType,
                candidateAnchorCoordinate,
                candidateQuarterTurns,
                runtimeGridSnapshot,
                ref foundExistingRectGridBlock,
                ref foundCompatibleOverlap,
                ref hasIncompatibleOverlap);
            if (hasIncompatibleOverlap)
            {
                return;
            }
        }

        runtimeAreaModuleScratch.Clear();
        if (InputOutputModule.CollectModulesAtRuntimeAreaCoordinate(coordinate, runtimeAreaModuleScratch))
        {
            for (int i = 0; i < runtimeAreaModuleScratch.Count; i++)
            {
                if (TryGetRuntimeModulePlacementSnapshot(
                        runtimeAreaModuleScratch[i],
                        out PlacementSnapshot runtimeAreaSnapshot))
                {
                    EvaluateCompatibleRectGridOverlap(
                        coordinate,
                        candidateFootprintSource,
                        candidateBlockType,
                        candidateAnchorCoordinate,
                        candidateQuarterTurns,
                        runtimeAreaSnapshot,
                        ref foundExistingRectGridBlock,
                        ref foundCompatibleOverlap,
                        ref hasIncompatibleOverlap);
                    if (hasIncompatibleOverlap)
                    {
                        break;
                    }
                }
            }

            runtimeAreaModuleScratch.Clear();
            if (hasIncompatibleOverlap)
            {
                return;
            }
        }
        else if (TryGetRuntimeAreaPlacementSnapshot(coordinate, out PlacementSnapshot runtimeAreaSnapshot))
        {
            EvaluateCompatibleRectGridOverlap(
                coordinate,
                candidateFootprintSource,
                candidateBlockType,
                candidateAnchorCoordinate,
                candidateQuarterTurns,
                runtimeAreaSnapshot,
                ref foundExistingRectGridBlock,
                ref foundCompatibleOverlap,
                ref hasIncompatibleOverlap);
            if (hasIncompatibleOverlap)
            {
                return;
            }
        }

        if (TryGetSavedPlacementSnapshot(coordinate, out PlacementSnapshot savedSnapshot))
        {
            EvaluateCompatibleRectGridOverlap(
                coordinate,
                candidateFootprintSource,
                candidateBlockType,
                candidateAnchorCoordinate,
                candidateQuarterTurns,
                savedSnapshot,
                ref foundExistingRectGridBlock,
                ref foundCompatibleOverlap,
                ref hasIncompatibleOverlap);
        }
    }

    private void EvaluateCompatibleRectGridOverlap(
        Vector2Int coordinate,
        MapObject candidateFootprintSource,
        InputOutputModule.RectGridBlockType candidateBlockType,
        Vector2Int candidateAnchorCoordinate,
        int candidateQuarterTurns,
        PlacementSnapshot existingSnapshot,
        ref bool foundExistingRectGridBlock,
        ref bool foundCompatibleOverlap,
        ref bool hasIncompatibleOverlap)
    {
        if (existingSnapshot == null
            || existingSnapshot.mapObject == null
            || !TryGetRectGridFootprintBlockType(
                existingSnapshot.anchorCoordinate,
                existingSnapshot.mapObject,
                existingSnapshot.quarterTurns,
                coordinate,
                out InputOutputModule.RectGridBlockType existingBlockType)
            || existingBlockType == InputOutputModule.RectGridBlockType.None)
        {
            return;
        }

        foundExistingRectGridBlock = true;
        if (CanOverlapCompatiblePlacementItemAreas(
                coordinate,
                candidateFootprintSource,
                candidateBlockType,
                candidateAnchorCoordinate,
                candidateQuarterTurns,
                existingSnapshot.mapObject,
                existingBlockType,
                existingSnapshot.anchorCoordinate,
                existingSnapshot.quarterTurns))
        {
            foundCompatibleOverlap = true;
        }
        else
        {
            hasIncompatibleOverlap = true;
        }
    }

    private bool CanOverlapCompatibleItemArea(
        Vector2Int coordinate,
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        bool hasExistingInputOutputEnergyAreaBlock,
        bool hasExistingInputOutputItemAreaBlock,
        bool hasExistingInputOutputOutputAreaBlock)
    {
        if (IsBoilerSource(footprintSource)
            && IsExactPumpOutputCoordinateForPlacement(coordinate)
            && IsBoilerPumpInputBlockType(rectGridBlockType))
        {
            return BoilerPipePassMatchesPumpOutput(
                footprintSource,
                coordinate,
                anchorCoordinate,
                quarterTurns);
        }

        if (InputOutputModule.IsInputItemBlockType(rectGridBlockType))
        {
            return hasExistingInputOutputOutputAreaBlock
                && CandidateInputItemsMatchExistingOutput(
                    coordinate,
                    footprintSource,
                    anchorCoordinate,
                    quarterTurns);
        }

        if (InputOutputModule.IsInputEnergyBlockType(rectGridBlockType))
        {
            return hasExistingInputOutputOutputAreaBlock
                && CandidateInputEnergyMatchesExistingOutput(coordinate, footprintSource);
        }

        if (InputOutputModule.IsOutputBlockType(rectGridBlockType))
        {
            return CandidateOutputMatchesExistingInputAreas(
                coordinate,
                footprintSource,
                anchorCoordinate,
                quarterTurns,
                hasExistingInputOutputItemAreaBlock,
                hasExistingInputOutputEnergyAreaBlock);
        }

        return false;
    }

    private bool CandidateInputItemsMatchExistingOutput(
        Vector2Int coordinate,
        MapObject footprintSource,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        HashSet<int> candidateInputItemIds = new HashSet<int>();
        HashSet<int> existingOutputItemIds = new HashSet<int>();
        return TryGetCandidateInputItemIdsAtCoordinate(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                coordinate,
                candidateInputItemIds)
            && TryGetExistingOutputItemIdsAtCoordinate(coordinate, existingOutputItemIds)
            && HasSharedItemId(candidateInputItemIds, existingOutputItemIds);
    }

    private bool CandidateInputEnergyMatchesExistingOutput(Vector2Int coordinate, MapObject footprintSource)
    {
        HashSet<ItemDefinition.EnergyType> candidateInputEnergyTypes = new HashSet<ItemDefinition.EnergyType>();
        HashSet<int> existingOutputItemIds = new HashSet<int>();
        return TryGetCandidateInputEnergyTypes(footprintSource, candidateInputEnergyTypes)
            && TryGetExistingOutputItemIdsAtCoordinate(coordinate, existingOutputItemIds)
            && HasOutputItemWithEnergyType(existingOutputItemIds, candidateInputEnergyTypes);
    }

    private bool CandidateOutputMatchesExistingInputAreas(
        Vector2Int coordinate,
        MapObject footprintSource,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        bool hasExistingInputOutputItemAreaBlock,
        bool hasExistingInputOutputEnergyAreaBlock)
    {
        if (!hasExistingInputOutputItemAreaBlock && !hasExistingInputOutputEnergyAreaBlock)
        {
            return false;
        }

        HashSet<int> candidateOutputItemIds = new HashSet<int>();
        if (!TryGetCandidateOutputItemIds(anchorCoordinate, footprintSource, quarterTurns, candidateOutputItemIds))
        {
            return false;
        }

        return (hasExistingInputOutputItemAreaBlock
                && ExistingInputItemsMatchOutput(coordinate, candidateOutputItemIds))
            || (hasExistingInputOutputEnergyAreaBlock
                && ExistingInputEnergyMatchesOutput(coordinate, candidateOutputItemIds));
    }

    private static bool ExistingInputItemsMatchOutput(Vector2Int coordinate, ISet<int> outputItemIds)
    {
        HashSet<int> existingInputItemIds = new HashSet<int>();
        return TryGetExistingInputItemIdsAtCoordinate(coordinate, existingInputItemIds)
            && HasSharedItemId(outputItemIds, existingInputItemIds);
    }

    private static bool ExistingInputEnergyMatchesOutput(Vector2Int coordinate, ISet<int> outputItemIds)
    {
        HashSet<ItemDefinition.EnergyType> existingInputEnergyTypes = new HashSet<ItemDefinition.EnergyType>();
        return TryGetExistingInputEnergyTypesAtCoordinate(coordinate, existingInputEnergyTypes)
            && HasOutputItemWithEnergyType(outputItemIds, existingInputEnergyTypes);
    }

    private bool CanOverlapCompatiblePlacementItemAreas(
        Vector2Int coordinate,
        MapObject candidateFootprintSource,
        InputOutputModule.RectGridBlockType candidateBlockType,
        Vector2Int candidateAnchorCoordinate,
        int candidateQuarterTurns,
        MapObject existingFootprintSource,
        InputOutputModule.RectGridBlockType existingBlockType,
        Vector2Int existingAnchorCoordinate,
        int existingQuarterTurns)
    {
        if (SimpleInstallationAllowsItemAreaOverlap(
                candidateFootprintSource,
                candidateBlockType,
                existingBlockType)
            || SimpleInstallationAllowsItemAreaOverlap(
                existingFootprintSource,
                existingBlockType,
                candidateBlockType))
        {
            return true;
        }

        PlacementSnapshot candidateSnapshot = new PlacementSnapshot
        {
            mapObject = candidateFootprintSource,
            rotation = GetPlacementObjectRotation(candidateFootprintSource, candidateQuarterTurns),
            anchorCoordinate = candidateAnchorCoordinate,
            quarterTurns = candidateQuarterTurns
        };
        PlacementSnapshot existingSnapshot = new PlacementSnapshot
        {
            mapObject = existingFootprintSource,
            rotation = GetPlacementObjectRotation(existingFootprintSource, existingQuarterTurns),
            anchorCoordinate = existingAnchorCoordinate,
            quarterTurns = existingQuarterTurns
        };

        if (BoilerObjectPipePassOverlapCanConnect(
                coordinate,
                candidateSnapshot,
                candidateBlockType,
                existingSnapshot,
                existingBlockType))
        {
            return true;
        }

        if (SteamGeneratorObjectPipePassOverlapCanConnect(
                coordinate,
                candidateSnapshot,
                candidateBlockType,
                existingSnapshot,
                existingBlockType))
        {
            return true;
        }

        if (SteamGeneratorInputObjectOverlapCanConnect(
                coordinate,
                candidateSnapshot,
                candidateBlockType,
                existingSnapshot,
                existingBlockType))
        {
            return true;
        }

        if (InputOutputModule.AllowsPipeAreaInteraction(candidateBlockType)
            && InputOutputModule.AllowsPipeAreaInteraction(existingBlockType))
        {
            return CanPipeAreaBlockCandidatesConnect(
                coordinate,
                new PipeAreaBlockCandidate(candidateSnapshot, candidateBlockType),
                coordinate,
                new PipeAreaBlockCandidate(existingSnapshot, existingBlockType));
        }

        if (IsPipePassBlockType(candidateBlockType) && IsPipePassBlockType(existingBlockType))
        {
            return true;
        }

        if (InputOutputModule.IsOutputBlockType(candidateBlockType))
        {
            HashSet<int> candidateOutputItemIds = new HashSet<int>();
            if (!TryGetCandidateOutputItemIds(
                    candidateAnchorCoordinate,
                    candidateFootprintSource,
                    candidateQuarterTurns,
                    candidateOutputItemIds))
            {
                return false;
            }

            return PlacementInputAreaMatchesOutput(
                coordinate,
                existingFootprintSource,
                existingBlockType,
                existingAnchorCoordinate,
                existingQuarterTurns,
                candidateOutputItemIds);
        }

        if (!InputOutputModule.IsOutputBlockType(existingBlockType))
        {
            return false;
        }

        HashSet<int> existingOutputItemIds = new HashSet<int>();
        if (!TryGetCandidateOutputItemIds(
                existingAnchorCoordinate,
                existingFootprintSource,
                existingQuarterTurns,
                existingOutputItemIds))
        {
            return false;
        }

        return PlacementInputAreaMatchesOutput(
            coordinate,
            candidateFootprintSource,
            candidateBlockType,
            candidateAnchorCoordinate,
            candidateQuarterTurns,
            existingOutputItemIds);
    }

    private static bool SimpleInstallationAllowsItemAreaOverlap(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType footprintBlockType,
        InputOutputModule.RectGridBlockType otherBlockType)
    {
        if (footprintBlockType != InputOutputModule.RectGridBlockType.None
            || !IsNormalInputOutputAreaBlockType(otherBlockType)
            || !TryResolveInstallationObject(footprintSource, out InstallationObject installationObject))
        {
            return false;
        }

        InstallationMapFilter mapFilter = ResolvePlacementMapFilter(
            footprintSource,
            installationObject);
        return (mapFilter & InstallationMapFilter.ItemArea) != 0;
    }

    private bool BoilerObjectPipePassOverlapCanConnect(
        Vector2Int coordinate,
        PlacementSnapshot candidateSnapshot,
        InputOutputModule.RectGridBlockType candidateBlockType,
        PlacementSnapshot existingSnapshot,
        InputOutputModule.RectGridBlockType existingBlockType)
    {
        if (candidateSnapshot == null
            || existingSnapshot == null
            || !IsBoilerSource(candidateSnapshot.mapObject)
            || !IsBoilerSource(existingSnapshot.mapObject))
        {
            return false;
        }

        if (candidateBlockType == InputOutputModule.RectGridBlockType.Object
            && IsPipePassBlockType(existingBlockType))
        {
            return BoilerObjectMatchesPipePassDirection(
                coordinate,
                candidateSnapshot,
                new PipeAreaBlockCandidate(existingSnapshot, existingBlockType));
        }

        if (existingBlockType == InputOutputModule.RectGridBlockType.Object
            && IsPipePassBlockType(candidateBlockType))
        {
            return BoilerObjectMatchesPipePassDirection(
                coordinate,
                existingSnapshot,
                new PipeAreaBlockCandidate(candidateSnapshot, candidateBlockType));
        }

        return false;
    }

    private bool BoilerObjectMatchesPipePassDirection(
        Vector2Int objectCoordinate,
        PlacementSnapshot objectSnapshot,
        PipeAreaBlockCandidate pipePassCandidate)
    {
        if (objectSnapshot == null
            || !IsBoilerSource(objectSnapshot.mapObject)
            || pipePassCandidate.snapshot == null
            || !IsBoilerSource(pipePassCandidate.snapshot.mapObject)
            || !IsPipePassBlockType(pipePassCandidate.blockType)
            || !TryGetPipeAreaObjectDirection(
                objectCoordinate,
                pipePassCandidate,
                out Vector2Int pipePassDirection))
        {
            return false;
        }

        Vector2Int objectPipePassCoordinate = objectCoordinate + pipePassDirection;
        if (!TryGetBoilerPipePassDirectionAtCoordinate(
                objectSnapshot.mapObject,
                objectSnapshot.anchorCoordinate,
                objectSnapshot.quarterTurns,
                objectPipePassCoordinate,
                out Vector2Int objectPipePassDirection)
            || objectPipePassDirection != -pipePassDirection)
        {
            return false;
        }

        return PipePassItemsMatchPipePass(
            pipePassCandidate,
            new PipeAreaBlockCandidate(objectSnapshot, InputOutputModule.RectGridBlockType.PipeInput));
    }

    private bool SteamGeneratorObjectPipePassOverlapCanConnect(
        Vector2Int coordinate,
        PlacementSnapshot candidateSnapshot,
        InputOutputModule.RectGridBlockType candidateBlockType,
        PlacementSnapshot existingSnapshot,
        InputOutputModule.RectGridBlockType existingBlockType)
    {
        if (candidateSnapshot == null
            || existingSnapshot == null
            || !IsSteamGeneratorSource(candidateSnapshot.mapObject)
            || !IsSteamGeneratorSource(existingSnapshot.mapObject))
        {
            return false;
        }

        if (candidateBlockType == InputOutputModule.RectGridBlockType.Object
            && IsPipePassBlockType(existingBlockType))
        {
            return SteamGeneratorObjectMatchesPipePassDirection(
                coordinate,
                candidateSnapshot,
                new PipeAreaBlockCandidate(existingSnapshot, existingBlockType));
        }

        if (existingBlockType == InputOutputModule.RectGridBlockType.Object
            && IsPipePassBlockType(candidateBlockType))
        {
            return SteamGeneratorObjectMatchesPipePassDirection(
                coordinate,
                existingSnapshot,
                new PipeAreaBlockCandidate(candidateSnapshot, candidateBlockType));
        }

        return false;
    }

    private bool SteamGeneratorInputObjectOverlapCanConnect(
        Vector2Int coordinate,
        PlacementSnapshot candidateSnapshot,
        InputOutputModule.RectGridBlockType candidateBlockType,
        PlacementSnapshot existingSnapshot,
        InputOutputModule.RectGridBlockType existingBlockType)
    {
        if (candidateSnapshot == null
            || existingSnapshot == null
            || !IsSteamGeneratorSource(candidateSnapshot.mapObject)
            || !IsSteamGeneratorSource(existingSnapshot.mapObject))
        {
            return false;
        }

        if (InputOutputModule.IsInputItemBlockType(candidateBlockType)
            && existingBlockType == InputOutputModule.RectGridBlockType.Object)
        {
            return SteamGeneratorInputMatchesExistingTailObject(
                coordinate,
                candidateSnapshot,
                candidateBlockType,
                existingSnapshot);
        }

        if (InputOutputModule.IsInputItemBlockType(existingBlockType)
            && candidateBlockType == InputOutputModule.RectGridBlockType.Object)
        {
            return SteamGeneratorInputMatchesExistingTailObject(
                coordinate,
                existingSnapshot,
                existingBlockType,
                candidateSnapshot);
        }

        return false;
    }

    private bool SteamGeneratorInputMatchesExistingTailObject(
        Vector2Int inputCoordinate,
        PlacementSnapshot inputSnapshot,
        InputOutputModule.RectGridBlockType inputBlockType,
        PlacementSnapshot existingSnapshot)
    {
        if (inputSnapshot == null
            || existingSnapshot == null
            || !IsSteamGeneratorSource(inputSnapshot.mapObject)
            || !IsSteamGeneratorSource(existingSnapshot.mapObject)
            || !InputOutputModule.IsInputItemBlockType(inputBlockType)
            || !SnapshotHasRectGridObjectBlock(existingSnapshot, inputCoordinate)
            || !TryGetSteamGeneratorBodyDirectionFromCenter(
                inputSnapshot.mapObject,
                inputSnapshot.quarterTurns,
                out Vector2Int proposedTailDirection))
        {
            return false;
        }

        Vector2Int pipePassCoordinate = inputSnapshot.anchorCoordinate;
        if (inputCoordinate != pipePassCoordinate - proposedTailDirection
            || !TryGetRectGridFootprintBlockType(
                existingSnapshot.anchorCoordinate,
                existingSnapshot.mapObject,
                existingSnapshot.quarterTurns,
                pipePassCoordinate,
                out InputOutputModule.RectGridBlockType existingPipePassBlockType)
            || !IsPipePassBlockType(existingPipePassBlockType))
        {
            return false;
        }

        PipeAreaBlockCandidate existingPipePassCandidate =
            new PipeAreaBlockCandidate(existingSnapshot, existingPipePassBlockType);
        if (!TryGetSteamGeneratorPipePassTailDirection(
                pipePassCoordinate,
                existingPipePassCandidate,
                out Vector2Int existingTailDirection)
            || existingTailDirection != proposedTailDirection)
        {
            return false;
        }

        return PipePassItemsMatchInput(
            existingPipePassCandidate,
            new PipeAreaBlockCandidate(inputSnapshot, inputBlockType),
            inputCoordinate);
    }

    private bool SteamGeneratorObjectMatchesPipePassDirection(
        Vector2Int objectCoordinate,
        PlacementSnapshot objectSnapshot,
        PipeAreaBlockCandidate pipePassCandidate)
    {
        if (objectSnapshot == null
            || !IsSteamGeneratorSource(objectSnapshot.mapObject)
            || objectCoordinate != objectSnapshot.anchorCoordinate
            || pipePassCandidate.snapshot == null
            || !IsSteamGeneratorSource(pipePassCandidate.snapshot.mapObject)
            || !TryGetSteamGeneratorPipePassTailDirection(
                objectCoordinate,
                pipePassCandidate,
                out Vector2Int existingTailDirection)
            || !TryGetSteamGeneratorBodyDirectionFromCenter(
                objectSnapshot.mapObject,
                objectSnapshot.quarterTurns,
                out Vector2Int proposedTailDirection)
            || proposedTailDirection != existingTailDirection)
        {
            return false;
        }

        Vector2Int proposedInputCoordinate = objectCoordinate - proposedTailDirection;
        if (!SnapshotHasRectGridObjectBlock(pipePassCandidate.snapshot, proposedInputCoordinate)
            || !TryGetRectGridFootprintBlockType(
                objectSnapshot.anchorCoordinate,
                objectSnapshot.mapObject,
                objectSnapshot.quarterTurns,
                proposedInputCoordinate,
                out InputOutputModule.RectGridBlockType proposedInputBlockType)
            || !InputOutputModule.IsInputItemBlockType(proposedInputBlockType))
        {
            return false;
        }

        return PipePassItemsMatchInput(
            pipePassCandidate,
            new PipeAreaBlockCandidate(objectSnapshot, proposedInputBlockType),
            proposedInputCoordinate);
    }

    private bool PlacementInputAreaMatchesOutput(
        Vector2Int coordinate,
        MapObject inputFootprintSource,
        InputOutputModule.RectGridBlockType inputBlockType,
        Vector2Int inputAnchorCoordinate,
        int inputQuarterTurns,
        ISet<int> outputItemIds)
    {
        if (InputOutputModule.IsInputItemBlockType(inputBlockType))
        {
            HashSet<int> inputItemIds = new HashSet<int>();
            return TryGetCandidateInputItemIdsAtCoordinate(
                    inputAnchorCoordinate,
                    inputFootprintSource,
                    inputQuarterTurns,
                    coordinate,
                    inputItemIds)
                && HasSharedItemId(outputItemIds, inputItemIds);
        }

        if (InputOutputModule.IsInputEnergyBlockType(inputBlockType))
        {
            HashSet<ItemDefinition.EnergyType> inputEnergyTypes = new HashSet<ItemDefinition.EnergyType>();
            return TryGetCandidateInputEnergyTypes(inputFootprintSource, inputEnergyTypes)
                && HasOutputItemWithEnergyType(outputItemIds, inputEnergyTypes);
        }

        return false;
    }

    private bool CanPlaceBoilerOnPumpOutputArea(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        bool isPumpRuntimeOutputAreaBlock,
        InstallationMapFilter allowedFilter,
        Vector2Int? anchorCoordinate,
        int quarterTurns)
    {
        return IsBoilerSource(footprintSource)
               && IsBoilerPumpInputBlockType(rectGridBlockType)
               && block != null
               && CanPlaceOnTerrainBiome(block, allowedFilter)
               && (occupyingObject == null || occupyingObject is Pump)
               && isPumpRuntimeOutputAreaBlock
               && IsExactPumpOutputCoordinateForPlacement(block.Coordinate)
               && BoilerPipePassMatchesPumpOutput(
                   footprintSource,
                   block.Coordinate,
                   anchorCoordinate,
                   quarterTurns);
    }

    private bool CanPlaceBoilerObjectOnPumpOutputArea(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        bool isPumpRuntimeOutputAreaBlock,
        Vector2Int? anchorCoordinate,
        int quarterTurns)
    {
        // CRITICAL: Boiler may sit directly on the pump OutputArea. Do not require
        // Pump PipeOutput and Boiler PipePass to overlap the same cell; this is an
        // adjacent fluid-direction connection. Do not move the Boiler one cell away.
        // The only hard rule here is that the pump-side Boiler PipePass faces the
        // pump output flow direction.
        return IsBoilerSource(footprintSource)
               && rectGridBlockType == InputOutputModule.RectGridBlockType.Object
               && block != null
               && block.Type == Block.BlockType.Ground
               && (occupyingObject == null || occupyingObject is Pump)
               && isPumpRuntimeOutputAreaBlock
               && IsExactPumpOutputCoordinateForPlacement(block.Coordinate)
               && anchorCoordinate.HasValue
               && TryGetExactPumpOutputDirectionForPlacement(
                   block.Coordinate,
                   out Vector2Int pumpOutputDirection)
               && BoilerPumpSidePipePassMatchesOutputDirection(
                   footprintSource,
                   anchorCoordinate.Value,
                   block.Coordinate,
                   quarterTurns,
                   pumpOutputDirection);
    }

    private bool CanPlaceBoilerObjectOnBoilerPipePassArea(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        InstallationMapFilter allowedFilter,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (!IsBoilerSource(footprintSource)
            || rectGridBlockType != InputOutputModule.RectGridBlockType.Object
            || block == null
            || block.Type != Block.BlockType.Ground
            || occupyingObject != null
            || !CanPlaceOnTerrainBiome(block, allowedFilter))
        {
            return false;
        }

        if (!anchorCoordinate.HasValue)
        {
            return HasBoilerPipePassAtCoordinate(block.Coordinate, previewToIgnore);
        }

        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate.Value,
            quarterTurns = quarterTurns
        };
        return BoilerObjectMatchesExistingBoilerPipePassDirection(
            block.Coordinate,
            proposedSnapshot,
            previewToIgnore);
    }

    private bool CanPlaceBoilerConnectorOnPumpBody(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        Vector2Int? anchorCoordinate,
        int quarterTurns)
    {
        if (!IsBoilerSource(footprintSource)
            || rectGridBlockType != InputOutputModule.RectGridBlockType.PipeInput
            || block == null
            || !(occupyingObject is Pump)
            || !anchorCoordinate.HasValue
            || !TryGetExactPumpOutputDirectionForPlacement(
                anchorCoordinate.Value,
                out Vector2Int pumpOutputDirection))
        {
            return false;
        }

        // When Boiler Object is anchored on Pump OutputArea, its PipeInput marker can
        // geometrically fall over the pump body. Treat that marker as a virtual port,
        // not a placement blocker, as long as the boiler's pipe direction faces the pump flow.
        return BoilerPumpSidePipePassMatchesOutputDirection(
            footprintSource,
            anchorCoordinate.Value,
            anchorCoordinate.Value,
            quarterTurns,
            pumpOutputDirection);
    }

    private bool CanPlaceBoilerConnectorOnBoilerBody(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (!IsBoilerSource(footprintSource)
            || rectGridBlockType != InputOutputModule.RectGridBlockType.PipeInput
            || block == null
            || !anchorCoordinate.HasValue
            || !IsBoilerSource(occupyingObject)
            || !TryGetRectGridBlockCoordinates(
                anchorCoordinate.Value,
                footprintSource,
                quarterTurns,
                InputOutputModule.RectGridBlockType.Object,
                out List<Vector2Int> objectCoordinates))
        {
            return false;
        }

        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate.Value,
            quarterTurns = quarterTurns
        };

        // CRITICAL: Boiler -> Boiler is the same flush-adjacent rule as Pump -> Boiler.
        // The new Boiler Object may sit on the existing Boiler PipePass cell, while the
        // new Boiler PipePass marker may fall over the existing Boiler body. Do not
        // separate the machines by one tile; only allow this when the two PipePass
        // directions face each other.
        for (int i = 0; i < objectCoordinates.Count; i++)
        {
            if (BoilerObjectMatchesExistingBoilerPipePassDirection(
                    objectCoordinates[i],
                    proposedSnapshot,
                    previewToIgnore,
                    block.Coordinate))
            {
                return true;
            }
        }

        return false;
    }

    private bool CanPlaceBoilerAreaBesidePumpOutput(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        Vector2Int? anchorCoordinate,
        int quarterTurns)
    {
        // Same rule as above: pump body cells are not boiler connection cells.
        return false;
    }

    private static bool IsBoilerSource(MapObject footprintSource)
    {
        return footprintSource is Boiler
               || (footprintSource != null
                   && (footprintSource.GetComponent<Boiler>() != null
                       || footprintSource.GetComponentInChildren<Boiler>(true) != null));
    }

    private static bool IsSteamGeneratorSource(MapObject footprintSource)
    {
        return footprintSource is SteamGenerator
               || (footprintSource != null
                   && (footprintSource.GetComponent<SteamGenerator>() != null
                       || footprintSource.GetComponentInChildren<SteamGenerator>(true) != null));
    }

    private static bool TryResolveBoiler(MapObject footprintSource, out Boiler boiler)
    {
        boiler = footprintSource as Boiler;
        if (boiler != null)
        {
            return true;
        }

        if (footprintSource == null)
        {
            return false;
        }

        boiler = footprintSource.GetComponent<Boiler>();
        if (boiler != null)
        {
            return true;
        }

        boiler = footprintSource.GetComponentInChildren<Boiler>(true);
        return boiler != null;
    }

    private static bool TryResolveSteamGenerator(MapObject footprintSource, out SteamGenerator steamGenerator)
    {
        steamGenerator = footprintSource as SteamGenerator;
        if (steamGenerator != null)
        {
            return true;
        }

        if (footprintSource == null)
        {
            return false;
        }

        steamGenerator = footprintSource.GetComponent<SteamGenerator>();
        if (steamGenerator != null)
        {
            return true;
        }

        steamGenerator = footprintSource.GetComponentInChildren<SteamGenerator>(true);
        return steamGenerator != null;
    }

    private static bool TryGetSteamGeneratorBodyDirectionFromCenter(
        MapObject footprintSource,
        int quarterTurns,
        out Vector2Int direction)
    {
        direction = Vector2Int.zero;
        return TryResolveSteamGenerator(footprintSource, out SteamGenerator steamGenerator)
               && steamGenerator.TryGetBodyDirectionFromCenter(footprintSource, quarterTurns, out direction);
    }

    private bool TryResolveSteamGeneratorPipeAlignedQuarterTurns(
        Block anchorBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (anchorBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsSteamGeneratorSource(footprintSource))
        {
            return false;
        }

        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                footprintSource,
                preferredQuarterTurns + offset);
            if (!SteamGeneratorPlacementHasMatchingPipeOverlap(
                    anchorBlock.Coordinate,
                    footprintSource,
                    candidateQuarterTurns)
                || !CanPlacePreviewOnBlock(anchorBlock, previewToIgnore, candidateQuarterTurns))
            {
                continue;
            }

            resolvedQuarterTurns = candidateQuarterTurns;
            return true;
        }

        return false;
    }

    private bool SteamGeneratorPlacementHasMatchingPipeOverlap(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns)
    {
        return SteamGeneratorPlacementPipeOverlapsMatch(
            anchorCoordinate,
            footprintSource,
            quarterTurns,
            true);
    }

    private bool SteamGeneratorPlacementPipeOverlapsMatch(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        bool requirePipeOverlap)
    {
        if (!IsSteamGeneratorSource(footprintSource)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return !requirePipeOverlap;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return !requirePipeOverlap;
        }

        bool foundPipeOverlap = false;
        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (!InputOutputModule.AllowsPipeAreaInteraction(placement.blockType)
                || !TryGetRectGridCoordinate(
                    anchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    placement,
                    out Vector2Int pipeAreaCoordinate)
                || !terrain.TryGetLoadedBlock(pipeAreaCoordinate, out Block pipeAreaBlock)
                || pipeAreaBlock == null)
            {
                continue;
            }

            if (!TryGetRectGridPipeAreaConnectionDirection(
                    footprintSource,
                    inputOutputModule,
                    anchorCoordinate,
                    quarterTurns,
                    pipeAreaCoordinate,
                    out Vector2Int pipeAreaDirection))
            {
                continue;
            }

            if (!SteamGeneratorPipeAreaPipeConnectionsMatch(
                    pipeAreaCoordinate,
                    pipeAreaDirection,
                    out bool hasPipeConnection))
            {
                return false;
            }

            foundPipeOverlap |= hasPipeConnection;
        }

        return requirePipeOverlap ? foundPipeOverlap : true;
    }

    private bool SteamGeneratorPipeAreaOverlapsPipeDirection(
        Block block,
        MapObject footprintSource,
        MapObject occupyingObject,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        return block != null
               && IsSteamGeneratorSource(footprintSource)
               && TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
               && TryGetRectGridFootprintBlockType(
                   anchorCoordinate,
                   footprintSource,
                   quarterTurns,
                   block.Coordinate,
                   out InputOutputModule.RectGridBlockType blockType)
               && TryGetRectGridPipeAreaConnectionDirection(
                   footprintSource,
                   inputOutputModule,
                   anchorCoordinate,
                   quarterTurns,
                   block.Coordinate,
                   out Vector2Int pipeAreaDirection)
               && SteamGeneratorPipeAreaPipeConnectionsMatch(
                   block.Coordinate,
                   pipeAreaDirection,
                   out bool hasPipeConnection)
               && hasPipeConnection
               && SteamGeneratorPipeAreaFluidMatchesPipeNetwork(
                   block.Coordinate,
                   footprintSource,
                   blockType,
                   anchorCoordinate,
                   quarterTurns);
    }

    private bool SteamGeneratorPipeAreaFluidMatchesPipeNetwork(
        Vector2Int pipeAreaCoordinate,
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType blockType,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate,
            quarterTurns = quarterTurns
        };
        PipeAreaBlockCandidate proposedCandidate = new PipeAreaBlockCandidate(proposedSnapshot, blockType);

        if (!TryGetPipePlacementAtCoordinate(
                pipeAreaCoordinate,
                out Pipe pipe,
                out Quaternion pipeRotation))
        {
            for (int i = 0; i < PipeCardinalDirections.Length; i++)
            {
                Vector2Int directionToPipe = PipeCardinalDirections[i];
                Vector2Int pipeCoordinate = pipeAreaCoordinate + directionToPipe;
                Vector2Int directionFromPipeToArea = -directionToPipe;
                if (!TryGetPipePlacementAtCoordinate(
                        pipeCoordinate,
                        out Pipe adjacentPipe,
                        out Quaternion adjacentPipeRotation)
                    || !TryResolvePipeVariantForForcedConnection(
                        pipeCoordinate,
                        adjacentPipe,
                        adjacentPipeRotation,
                        directionFromPipeToArea,
                        out Pipe resolvedAdjacentPipe,
                        out Quaternion resolvedAdjacentPipeRotation))
                {
                    continue;
                }

                if (!PipeAreaCandidateFluidMatchesPipeNetwork(
                        pipeCoordinate,
                        resolvedAdjacentPipe,
                        resolvedAdjacentPipeRotation,
                        pipeAreaCoordinate,
                        proposedCandidate,
                        null))
                {
                    return false;
                }
            }

            return true;
        }

        Pipe pipeForFluidMatch = pipe;
        Quaternion pipeRotationForFluidMatch = pipeRotation;
        List<Vector2Int> requiredDirections = new List<Vector2Int>(4);
        if (TryGetPipeAreaCandidateConnectionDirections(
                pipeAreaCoordinate,
                proposedCandidate,
                requiredDirections)
            && requiredDirections.Count > 0)
        {
            bool resolvedPipeForArea = false;
            for (int i = 0; i < requiredDirections.Count; i++)
            {
                Vector2Int requiredDirection = requiredDirections[i];
                if (requiredDirection == Vector2Int.zero)
                {
                    continue;
                }

                if (TryResolvePipeVariantForForcedConnection(
                        pipeAreaCoordinate,
                        pipe,
                        pipeRotation,
                        requiredDirection,
                        out Pipe resolvedPipe,
                        out Quaternion resolvedPipeRotation))
                {
                    pipeForFluidMatch = resolvedPipe;
                    pipeRotationForFluidMatch = resolvedPipeRotation;
                    resolvedPipeForArea = true;
                    break;
                }
            }

            if (!resolvedPipeForArea)
            {
                return false;
            }
        }

        return PipeAreaCandidateFluidMatchesPipeNetwork(
            pipeAreaCoordinate,
            pipeForFluidMatch,
            pipeRotationForFluidMatch,
            pipeAreaCoordinate,
            proposedCandidate,
            null);
    }

    private bool SteamGeneratorPipeAreaPipeConnectionsMatch(
        Vector2Int pipeAreaCoordinate,
        Vector2Int pipeAreaDirection,
        out bool hasPipeConnection)
    {
        hasPipeConnection = false;
        if (pipeAreaDirection == Vector2Int.zero)
        {
            return true;
        }

        if (TryGetPipePlacementAtCoordinate(
                pipeAreaCoordinate,
                out Pipe overlappingPipe,
                out Quaternion overlappingPipeRotation))
        {
            hasPipeConnection = true;
            if (!TryResolvePipeVariantForForcedConnection(
                    pipeAreaCoordinate,
                    overlappingPipe,
                    overlappingPipeRotation,
                    pipeAreaDirection,
                    out _,
                    out _))
            {
                return false;
            }
        }

        for (int i = 0; i < PipeCardinalDirections.Length; i++)
        {
            Vector2Int directionToPipe = PipeCardinalDirections[i];
            Vector2Int pipeCoordinate = pipeAreaCoordinate + directionToPipe;
            if (!TryGetPipePlacementAtCoordinate(
                    pipeCoordinate,
                    out Pipe pipe,
                    out Quaternion pipeRotation))
            {
                continue;
            }

            Vector2Int directionFromPipeToArea = -directionToPipe;
            if (!TryResolvePipeVariantForForcedConnection(
                    pipeCoordinate,
                    pipe,
                    pipeRotation,
                    directionFromPipeToArea,
                    out _,
                    out _))
            {
                continue;
            }

            if (directionFromPipeToArea != pipeAreaDirection)
            {
                return false;
            }

            hasPipeConnection = true;
        }

        return true;
    }

    private bool TryGetPipePlacementAtCoordinate(
        Vector2Int coordinate,
        out Pipe pipe,
        out Quaternion pipeRotation)
    {
        pipe = null;
        pipeRotation = Quaternion.identity;

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        Block block = null;
        if (terrain != null)
        {
            terrain.TryGetLoadedBlock(coordinate, out block);
        }

        MapObject occupyingObject = null;
        if (block != null)
        {
            occupyingObject = GetBlockingMapObject(block);
        }

        if (TryGetPipePlacementAtBlock(block, occupyingObject, out pipe, out pipeRotation))
        {
            ApplyVirtualInstalledPipeResolution(ref pipe, ref pipeRotation);
            return true;
        }

        if (TryGetSavedPipePlacementAtCoordinate(
                coordinate,
                out Pipe savedPipe,
                out Quaternion savedRotation))
        {
            pipe = savedPipe;
            pipeRotation = savedRotation;
            return true;
        }

        return false;
    }

    private bool SteamGeneratorPipeAreaDirectionMatchesPipe(
        MapObject footprintSource,
        InputOutputModule inputOutputModule,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        Vector2Int pipeAreaCoordinate,
        Vector2Int pipeAxisDirection)
    {
        return TryGetRectGridPipeAreaConnectionDirection(
                   footprintSource,
                   inputOutputModule,
                   anchorCoordinate,
                   quarterTurns,
                   pipeAreaCoordinate,
                   out Vector2Int pipeAreaDirection)
               && DirectionsShareAxis(pipeAxisDirection, pipeAreaDirection);
    }

    private static bool TryGetStraightPipeAxis(Pipe pipe, Quaternion pipeRotation, out Vector2Int axisDirection)
    {
        axisDirection = Vector2Int.zero;
        if (pipe == null
            || pipe.IsCornerVariant
            || pipe.IsTeeVariant
            || pipe.IsCrossVariant)
        {
            return false;
        }

        for (int i = 0; i < PipeCardinalDirections.Length; i++)
        {
            Vector2Int direction = PipeCardinalDirections[i];
            if (!pipe.HasConnectionTowards(pipeRotation, direction)
                || !pipe.HasConnectionTowards(pipeRotation, -direction))
            {
                continue;
            }

            axisDirection = NormalizeCardinalAxis(direction);
            return axisDirection != Vector2Int.zero;
        }

        return false;
    }

    private static bool DirectionsShareAxis(Vector2Int firstDirection, Vector2Int secondDirection)
    {
        return firstDirection != Vector2Int.zero
               && secondDirection != Vector2Int.zero
               && NormalizeCardinalAxis(firstDirection) == NormalizeCardinalAxis(secondDirection);
    }

    private static Vector2Int NormalizeCardinalAxis(Vector2Int direction)
    {
        if (direction.x != 0)
        {
            return Vector2Int.right;
        }

        if (direction.y != 0)
        {
            return Vector2Int.up;
        }

        return Vector2Int.zero;
    }

    private static bool IsBoilerPumpInputBlockType(InputOutputModule.RectGridBlockType blockType)
    {
        return blockType == InputOutputModule.RectGridBlockType.PipeInput;
    }

    private bool BoilerPipePassMatchesPumpOutput(
        MapObject boilerSource,
        Vector2Int coordinate,
        Vector2Int? boilerAnchorCoordinate,
        int boilerQuarterTurns)
    {
        // Same-cell PipePass/PipeOutput overlap is still valid, but it is not required
        // for pump-to-boiler attachment. Direct flush placement is handled by the
        // Boiler Object-on-OutputArea path above.
        if (boilerSource == null
            || !boilerAnchorCoordinate.HasValue
            || !TryGetExactPumpOutputDirectionForPlacement(coordinate, out Vector2Int pumpOutputDirection)
            || !BoilerPipePassAtCoordinateMatchesDirection(
                boilerSource,
                boilerAnchorCoordinate.Value,
                boilerQuarterTurns,
                coordinate,
                pumpOutputDirection))
        {
            return false;
        }

        return true;
    }

    private bool PlacementHasBoilerPumpOutputDirectionMismatch(
        Vector2Int boilerAnchorCoordinate,
        MapObject boilerSource,
        int boilerQuarterTurns)
    {
        return TryGetExactPumpOutputDirectionForPlacement(
                   boilerAnchorCoordinate,
                   out Vector2Int pumpOutputDirection)
               && !BoilerPumpSidePipePassMatchesOutputDirection(
                   boilerSource,
                   boilerAnchorCoordinate,
                   boilerAnchorCoordinate,
                   boilerQuarterTurns,
                   pumpOutputDirection);
    }

    private bool BoilerPumpSidePipePassMatchesOutputDirection(
        MapObject boilerSource,
        Vector2Int boilerAnchorCoordinate,
        Vector2Int pumpOutputCoordinate,
        int boilerQuarterTurns,
        Vector2Int pumpOutputDirection)
    {
        if (pumpOutputDirection == Vector2Int.zero)
        {
            return false;
        }

        Vector2Int pumpSidePipePassCoordinate = pumpOutputCoordinate - pumpOutputDirection;
        return BoilerPipePassAtCoordinateMatchesDirection(
            boilerSource,
            boilerAnchorCoordinate,
            boilerQuarterTurns,
            pumpSidePipePassCoordinate,
            pumpOutputDirection);
    }

    private bool BoilerPipePassAtCoordinateMatchesDirection(
        MapObject boilerSource,
        Vector2Int boilerAnchorCoordinate,
        int boilerQuarterTurns,
        Vector2Int pipePassCoordinate,
        Vector2Int targetDirection)
    {
        return TryResolveBoiler(boilerSource, out Boiler boiler)
               && boiler.PipePassAtCoordinateMatchesDirection(
                   boilerSource,
                   boilerAnchorCoordinate,
                   boilerQuarterTurns,
                   pipePassCoordinate,
                   targetDirection);
    }

    private bool BoilerHasPipePassFacingDirection(
        MapObject boilerSource,
        Vector2Int boilerAnchorCoordinate,
        int boilerQuarterTurns,
        Vector2Int targetDirection)
    {
        return TryResolveBoiler(boilerSource, out Boiler boiler)
               && boiler.HasPipePassFacingDirection(
                   boilerSource,
                   boilerAnchorCoordinate,
                   boilerQuarterTurns,
                   targetDirection);
    }

    private bool TryGetBoilerPumpOutputDirectionMatch(
        MapObject boilerSource,
        Vector2Int boilerAnchorCoordinate,
        int boilerQuarterTurns,
        out bool matches)
    {
        matches = false;
        if (!IsBoilerSource(boilerSource)
            || !TryGetInputOutputModule(boilerSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        if (TryGetExactPumpOutputDirectionForPlacement(
                boilerAnchorCoordinate,
                out Vector2Int directPumpOutputDirection))
        {
            matches = BoilerPumpSidePipePassMatchesOutputDirection(
                boilerSource,
                boilerAnchorCoordinate,
                boilerAnchorCoordinate,
                boilerQuarterTurns,
                directPumpOutputDirection);
            return true;
        }

        bool foundPumpOutput = false;
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (placement.blockType != InputOutputModule.RectGridBlockType.PipeInput
                || !TryGetRectGridCoordinate(
                    boilerAnchorCoordinate,
                    boilerSource,
                    boilerQuarterTurns,
                    placement,
                    out Vector2Int pipePassCoordinate)
                || !TryGetPumpOutputDirectionForBoilerPipePass(
                    pipePassCoordinate,
                    out Vector2Int pumpOutputDirection))
            {
                continue;
            }

            if (!TryGetRectGridPipeAreaConnectionDirection(
                    boilerSource,
                    inputOutputModule,
                    boilerAnchorCoordinate,
                    boilerQuarterTurns,
                    pipePassCoordinate,
                    out Vector2Int pipePassDirection))
            {
                continue;
            }

            foundPumpOutput = true;
            if (pipePassDirection == pumpOutputDirection)
            {
                matches = true;
                return true;
            }
        }

        return foundPumpOutput;
    }

    private bool TryGetPumpOutputDirectionForBoilerPipePass(Vector2Int pipePassCoordinate, out Vector2Int direction)
    {
        direction = Vector2Int.zero;
        if (TryGetExactPumpOutputDirectionForPlacement(pipePassCoordinate, out direction))
        {
            return direction != Vector2Int.zero;
        }

        // Pump/boiler fluid connectors may be adjacent. Do not require PipeOutput and
        // PipePass to occupy the same cell; only the flow direction has to line up.
        for (int i = 0; i < PipeCardinalDirections.Length; i++)
        {
            Vector2Int directionFromPumpOutput = PipeCardinalDirections[i];
            Vector2Int pumpOutputCoordinate = pipePassCoordinate - directionFromPumpOutput;
            if (!TryGetExactPumpOutputDirectionForPlacement(
                    pumpOutputCoordinate,
                    out Vector2Int pumpOutputDirection)
                || pumpOutputDirection != directionFromPumpOutput)
            {
                continue;
            }

            direction = pumpOutputDirection;
            return true;
        }

        return false;
    }

    private bool TryGetRectGridCoordinate(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        InputOutputModule.RectGridBlockPlacement placement,
        out Vector2Int coordinate)
    {
        coordinate = Vector2Int.zero;
        return TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
               && inputOutputModule.TryGetRectGridPlacementCoordinate(
                   footprintSource,
                   anchorCoordinate,
                   NormalizePlacementQuarterTurnsForObject(footprintSource, quarterTurns),
                   placement,
                   out coordinate);
    }

    private static bool IsPumpRuntimeOutputCoordinate(Vector2Int coordinate)
    {
        if (InputOutputModule.TryGetRuntimePipeSourceAtCoordinate(coordinate, out _))
        {
            return true;
        }

        return InputOutputModule.TryGetModuleAtRuntimeRectGridBlockType(
                   coordinate,
                   InputOutputModule.RectGridBlockType.PipeOutputItem,
                   out InputOutputModule pipeOutputModule)
               && pipeOutputModule is Pump;
    }

    private bool IsExactPumpOutputCoordinateForPlacement(Vector2Int coordinate)
    {
        return IsPumpRuntimeOutputCoordinate(coordinate)
               || IsPumpRectGridOutputCoordinateForPlacement(coordinate);
    }

    private bool IsPumpOutputCoordinateForPlacement(Vector2Int coordinate)
    {
        return IsPumpRuntimeOutputCoordinate(coordinate)
               || IsPumpRectGridOutputCoordinateForPlacement(coordinate)
               || IsAdjacentPumpOutputCoordinate(coordinate);
    }

    private bool TryGetExactPumpOutputDirectionForPlacement(Vector2Int coordinate, out Vector2Int direction)
    {
        direction = Vector2Int.zero;
        if (InputOutputModule.TryGetRuntimePipeSourceAtCoordinate(coordinate, out Pump runtimePump)
            && runtimePump != null
            && runtimePump.TryGetPipeConnectionDirection(runtimePump.transform.rotation, out direction))
        {
            return true;
        }

        return TryGetPumpRectGridOutputDirectionForPlacement(coordinate, out direction);
    }

    private bool IsPumpRectGridOutputCoordinateForPlacement(Vector2Int coordinate)
    {
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        for (int x = -2; x <= 2; x++)
        {
            for (int y = -2; y <= 2; y++)
            {
                Vector2Int pumpCoordinate = coordinate + new Vector2Int(x, y);
                if (!terrain.TryGetLoadedBlock(pumpCoordinate, out Block pumpBlock)
                    || pumpBlock == null)
                {
                    continue;
                }

                MapObject pumpObject = GetBlockingMapObject(pumpBlock);
                bool hasSavedPumpPlacement = false;
                Vector2Int savedPumpAnchorCoordinate = Vector2Int.zero;
                int savedPumpQuarterTurns = 0;
                if (pumpObject == null
                    && TryGetSavedInstallationPlacementAtCoordinate(
                        pumpCoordinate,
                        out pumpObject,
                        out _,
                        out BlockStateStore.InstallationSaveState savedPumpState)
                    && savedPumpState != null)
                {
                    hasSavedPumpPlacement = true;
                    savedPumpAnchorCoordinate = savedPumpState.anchorCoordinate;
                    savedPumpQuarterTurns = savedPumpState.quarterTurns;
                }

                if (pumpObject == null)
                {
                    continue;
                }

                Vector2Int pumpAnchorCoordinate;
                int pumpQuarterTurns;
                if (hasSavedPumpPlacement)
                {
                    pumpAnchorCoordinate = savedPumpAnchorCoordinate;
                    pumpQuarterTurns = savedPumpQuarterTurns;
                }
                else if (!TryGetPumpPlacementRuntime(
                             pumpObject,
                             out pumpAnchorCoordinate,
                             out pumpQuarterTurns))
                {
                    continue;
                }

                if (TryGetRectGridFootprintBlockType(
                        pumpAnchorCoordinate,
                        pumpObject,
                        pumpQuarterTurns,
                        coordinate,
                        out InputOutputModule.RectGridBlockType blockType)
                    && blockType == InputOutputModule.RectGridBlockType.PipeOutputItem)
                {
                    return true;
                }
            }
        }

        return false;
    }

    private bool TryGetPumpRectGridOutputDirectionForPlacement(Vector2Int coordinate, out Vector2Int direction)
    {
        direction = Vector2Int.zero;
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        for (int x = -2; x <= 2; x++)
        {
            for (int y = -2; y <= 2; y++)
            {
                Vector2Int pumpCoordinate = coordinate + new Vector2Int(x, y);
                if (!terrain.TryGetLoadedBlock(pumpCoordinate, out Block pumpBlock)
                    || pumpBlock == null)
                {
                    continue;
                }

                MapObject pumpObject = GetBlockingMapObject(pumpBlock);
                Quaternion pumpRotation = pumpObject != null ? pumpObject.transform.rotation : Quaternion.identity;
                bool hasSavedPumpPlacement = false;
                Vector2Int savedPumpAnchorCoordinate = Vector2Int.zero;
                int savedPumpQuarterTurns = 0;
                if (pumpObject == null
                    && TryGetSavedInstallationPlacementAtCoordinate(
                        pumpCoordinate,
                        out pumpObject,
                        out pumpRotation,
                        out BlockStateStore.InstallationSaveState savedPumpState)
                    && savedPumpState != null)
                {
                    hasSavedPumpPlacement = true;
                    savedPumpAnchorCoordinate = savedPumpState.anchorCoordinate;
                    savedPumpQuarterTurns = savedPumpState.quarterTurns;
                }

                if (!(pumpObject is Pump pump))
                {
                    continue;
                }

                Vector2Int pumpAnchorCoordinate;
                int pumpQuarterTurns;
                if (hasSavedPumpPlacement)
                {
                    pumpAnchorCoordinate = savedPumpAnchorCoordinate;
                    pumpQuarterTurns = savedPumpQuarterTurns;
                }
                else if (!TryGetPumpPlacementRuntime(
                             pumpObject,
                             out pumpAnchorCoordinate,
                             out pumpQuarterTurns))
                {
                    continue;
                }

                if (TryGetRectGridFootprintBlockType(
                        pumpAnchorCoordinate,
                        pumpObject,
                        pumpQuarterTurns,
                        coordinate,
                        out InputOutputModule.RectGridBlockType blockType)
                    && blockType == InputOutputModule.RectGridBlockType.PipeOutputItem
                    && pump.TryGetPipeConnectionDirection(pumpRotation, out direction))
                {
                    return true;
                }
            }
        }

        return false;
    }

    private bool TryGetPumpPlacementRuntime(
        MapObject pumpObject,
        out Vector2Int anchorCoordinate,
        out int quarterTurns)
    {
        anchorCoordinate = Vector2Int.zero;
        quarterTurns = 0;
        if (!(pumpObject is Pump pump))
        {
            return false;
        }

        if (pump.TryGetPlacementRuntime(out anchorCoordinate, out quarterTurns))
        {
            return true;
        }

        return false;
    }

    private bool IsAdjacentPumpOutputCoordinate(Vector2Int coordinate)
    {
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        for (int i = 0; i < PipeCardinalDirections.Length; i++)
        {
            Vector2Int directionFromPump = PipeCardinalDirections[i];
            Vector2Int pumpCoordinate = coordinate - directionFromPump;
            if (!terrain.TryGetLoadedBlock(pumpCoordinate, out Block pumpBlock)
                || pumpBlock == null)
            {
                continue;
            }

            MapObject pumpObject = GetBlockingMapObject(pumpBlock);
            Quaternion pumpRotation = pumpObject != null ? pumpObject.transform.rotation : Quaternion.identity;
            if (pumpObject == null
                && !TryGetSavedInstallationPlacementAtCoordinate(
                    pumpCoordinate,
                    out pumpObject,
                    out pumpRotation,
                    out _))
            {
                pumpObject = null;
            }

            if (pumpObject is Pump pump
                && pump.TryGetPipeConnectionDirection(
                    pumpRotation,
                    out Vector2Int pumpOutputDirection)
                && pumpOutputDirection == directionFromPump)
            {
                return true;
            }
        }

        return false;
    }

    private bool TryGetCandidateInputItemIdsAtCoordinate(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        Vector2Int coordinate,
        ISet<int> inputItemIds)
    {
        if (inputItemIds == null
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
            || !TryGetOrderedInputItemAreaBindings(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                inputOutputModule,
                out List<InputOutputModuleItemAreaBinding> bindings))
        {
            return false;
        }

        bool foundAny = false;
        for (int i = 0; i < bindings.Count; i++)
        {
            InputOutputModuleItemAreaBinding binding = bindings[i];
            if (binding.Coordinate != coordinate || binding.ItemId < 0)
            {
                continue;
            }

            inputItemIds.Add(binding.ItemId);
            foundAny = true;
        }

        return foundAny;
    }

    private bool TryGetCandidateOutputItemIds(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        ISet<int> outputItemIds)
    {
        if (outputItemIds == null || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        bool foundAny = inputOutputModule.TryAppendConfiguredOutputItemIds(outputItemIds);

        if (TryGetMiningMachine(footprintSource, out MiningMachine miningMachine))
        {
            List<Vector2Int> miningCoordinates = GetInstalledObjectBlockingCoordinates(
                anchorCoordinate,
                footprintSource,
                quarterTurns);
            foundAny |= miningMachine.TryAppendPlacementOutputItemIds(
                ResolveInstallPreviewTerrain(),
                miningCoordinates,
                outputItemIds);
        }

        return foundAny;
    }

    private bool TryGetCandidateInputEnergyTypes(
        MapObject footprintSource,
        ISet<ItemDefinition.EnergyType> energyTypes)
    {
        if (energyTypes == null)
        {
            return false;
        }

        ItemDefinition installationDefinition = ResolveItemDefinition(footprintSource);
        if (installationDefinition == null
            || installationDefinition.useEnergyType == ItemDefinition.EnergyType.None)
        {
            return false;
        }

        energyTypes.Add(installationDefinition.useEnergyType);
        return true;
    }

    private static bool TryGetExistingOutputItemIdsAtCoordinate(Vector2Int coordinate, ISet<int> outputItemIds)
    {
        if (IsPumpRuntimeOutputCoordinate(coordinate))
        {
            return false;
        }

        return InputOutputModule.TryGetOutputItemIdsAtRuntimeGridCoordinate(coordinate, outputItemIds);
    }

    private static bool TryGetExistingInputItemIdsAtCoordinate(Vector2Int coordinate, ISet<int> inputItemIds)
    {
        if (inputItemIds == null)
        {
            return false;
        }

        bool foundAny = InputOutputModuleItemAreaController.TryGetAcceptedItemIds(coordinate, inputItemIds);
        foundAny |= InputOutputModule.TryGetInputItemIdsAtRuntimeGridCoordinate(coordinate, inputItemIds);
        return foundAny;
    }

    private static bool TryGetExistingInputEnergyTypesAtCoordinate(
        Vector2Int coordinate,
        ISet<ItemDefinition.EnergyType> energyTypes)
    {
        if (energyTypes == null)
        {
            return false;
        }

        bool foundAny = InputOutputModuleEnergyAreaController.TryGetAcceptedEnergyTypes(coordinate, energyTypes);
        foundAny |= InputOutputModule.TryGetInputEnergyTypesAtRuntimeGridCoordinate(coordinate, energyTypes);
        return foundAny;
    }

    private static bool HasSharedItemId(ISet<int> leftItemIds, ISet<int> rightItemIds)
    {
        if (leftItemIds == null || rightItemIds == null || leftItemIds.Count <= 0 || rightItemIds.Count <= 0)
        {
            return false;
        }

        foreach (int itemId in leftItemIds)
        {
            if (itemId >= 0 && rightItemIds.Contains(itemId))
            {
                return true;
            }
        }

        return false;
    }

    private static bool HasOutputItemWithEnergyType(
        ISet<int> outputItemIds,
        ISet<ItemDefinition.EnergyType> acceptedEnergyTypes)
    {
        if (outputItemIds == null
            || acceptedEnergyTypes == null
            || outputItemIds.Count <= 0
            || acceptedEnergyTypes.Count <= 0)
        {
            return false;
        }

        foreach (int outputItemId in outputItemIds)
        {
            ItemDefinition outputDefinition = ResolveItemDefinition(outputItemId);
            if (outputDefinition == null
                || outputDefinition.energyType == ItemDefinition.EnergyType.None
                || outputDefinition.energyAmount <= 0)
            {
                continue;
            }

            if (acceptedEnergyTypes.Contains(outputDefinition.energyType))
            {
                return true;
            }
        }

        return false;
    }

    private static ItemDefinition ResolveItemDefinition(int itemId)
    {
        if (itemId < 0 || GameManager.Instance == null || GameManager.Instance.ItemManger == null)
        {
            return null;
        }

        List<ItemDefinition> definitions = GameManager.Instance.ItemManger.ItemDefinitions;
        if (definitions == null)
        {
            return null;
        }

        for (int i = 0; i < definitions.Count; i++)
        {
            ItemDefinition definition = definitions[i];
            if (definition != null && definition.id == itemId)
            {
                return definition;
            }
        }

        return null;
    }

    private static bool CanPlaceInstallationOnInputOutputAreaBlock(
        InstallationObject installationObject,
        Block block,
        MapObject occupyingObject,
        bool isInputOutputAreaBlock,
        bool isNormalInputOutputAreaBlock,
        bool isInputOutputItemAreaBlock,
        InstallationMapFilter allowedFilter)
    {
        if (installationObject == null || block == null || block.Type != Block.BlockType.Ground)
        {
            return false;
        }

        if (isInputOutputAreaBlock
            && occupyingObject is Resource occupyingResource
            && IsResourceAllowedByMapFilter(occupyingResource, allowedFilter))
        {
            return true;
        }

        bool allowsItemArea = isNormalInputOutputAreaBlock
            && (allowedFilter & InstallationMapFilter.ItemArea) != 0;
        if (allowsItemArea
            && (occupyingObject == null
                || occupyingObject is InputOutputModule
                || occupyingObject is Resource))
        {
            return true;
        }

        if (!(installationObject is BoxObject))
        {
            return false;
        }

        if (occupyingObject == null || occupyingObject is InputOutputModule)
        {
            return true;
        }

        return isInputOutputItemAreaBlock
            && occupyingObject is Resource resource
            && IsResourceAllowedByMapFilter(resource, InstallationMapFilter.Ore);
    }

    public static bool IsResourceAllowedByMapFilter(Resource resource, InstallationMapFilter allowedFilter)
    {
        if (resource == null || !resource.CanHarvest)
        {
            return false;
        }

        InstallationMapFilter resourceFilter;
        switch (resource.ResolvedHarvestMode)
        {
            case Resource.HarvestMode.Logging:
            case Resource.HarvestMode.Cut:
                resourceFilter = InstallationMapFilter.Tree;
                break;
            default:
                resourceFilter = resource.PlacementCategory == ResourceDefinition.PlacementCategory.Oil
                    ? InstallationMapFilter.Oil
                    : InstallationMapFilter.Ore;
                break;
        }

        return (allowedFilter & resourceFilter) != 0;
    }

    private static bool IsResourceAllowedForPlacement(
        Block block,
        MapObject occupyingObject,
        InstallationMapFilter allowedFilter)
    {
        Resource resource = occupyingObject as Resource;
        if (resource == null && occupyingObject == null && block != null)
        {
            resource = block.Resource;
        }

        return IsResourceAllowedByMapFilter(resource, allowedFilter);
    }

    private bool IsRailloadAllowedForPlacement(
        Block block,
        MapObject occupyingObject,
        InstallationMapFilter allowedFilter)
    {
        if ((allowedFilter & InstallationMapFilter.Railload) == 0)
        {
            return false;
        }

        if (occupyingObject is Railload)
        {
            return true;
        }

        if (block != null && block.MapObject is Railload)
        {
            return true;
        }

        return block != null
               && TryGetSavedInstallationPlacementAtCoordinate(
                   block.Coordinate,
                   out MapObject savedSourcePrefab,
                   out _,
                   out _)
               && savedSourcePrefab is Railload;
    }

    private static bool IsInstallationObjectAllowedForPlacement(
        MapObject occupyingObject,
        InstallationMapFilter allowedFilter)
    {
        if (!(occupyingObject is InstallationObject occupyingInstallation))
        {
            return false;
        }

        InstallationMapFilter requiredFilter = occupyingInstallation is Floor
            ? InstallationMapFilter.Floor
            : InstallationMapFilter.OtherInstallObject;
        return (allowedFilter & requiredFilter) != 0;
    }

    private bool TryResolveTrainStationFacingQuarterTurns(
        Vector2Int coordinate,
        MapObject sourcePrefab,
        MapObject previewToIgnore,
        int fallbackQuarterTurns,
        out int quarterTurns)
    {
        quarterTurns = NormalizePlacementQuarterTurnsForObject(sourcePrefab, fallbackQuarterTurns);
        if (!IsTrainStationSource(sourcePrefab))
        {
            return false;
        }

        int normalizedFallbackQuarterTurns = quarterTurns;
        int candidateCount = GetPlacementRotationCandidateCount(sourcePrefab);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                sourcePrefab,
                normalizedFallbackQuarterTurns + offset);
            if (!TryResolveTrainStationSelectedRailCoordinate(
                    coordinate,
                    sourcePrefab,
                    candidateQuarterTurns,
                    previewToIgnore,
                    out _))
            {
                continue;
            }

            quarterTurns = candidateQuarterTurns;
            return true;
        }

        return false;
    }

    private bool TryResolveNextTrainStationFacingQuarterTurns(
        Vector2Int coordinate,
        MapObject sourcePrefab,
        MapObject previewToIgnore,
        int currentQuarterTurns,
        out int quarterTurns)
    {
        quarterTurns = NormalizePlacementQuarterTurnsForObject(sourcePrefab, currentQuarterTurns);
        if (!IsTrainStationSource(sourcePrefab))
        {
            return false;
        }

        int normalizedCurrentQuarterTurns = NormalizePlacementQuarterTurnsForObject(sourcePrefab, currentQuarterTurns);
        int candidateCount = GetPlacementRotationCandidateCount(sourcePrefab);
        for (int offset = 1; offset <= candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                sourcePrefab,
                normalizedCurrentQuarterTurns + offset);
            if (!TryResolveTrainStationSelectedRailCoordinate(
                    coordinate,
                    sourcePrefab,
                    candidateQuarterTurns,
                    previewToIgnore,
                    out _))
            {
                continue;
            }

            quarterTurns = candidateQuarterTurns;
            return true;
        }

        return false;
    }

    private bool HasRailloadForTrainStationAtCoordinate(Vector2Int coordinate, MapObject previewToIgnore)
    {
        if (TryGetPreviewPlacementSnapshot(coordinate, previewToIgnore, out PlacementSnapshot previewSnapshot)
            && IsRailloadSource(ResolveInstallPreviewFootprintSource(previewSnapshot.mapObject) ?? previewSnapshot.mapObject))
        {
            return true;
        }

        if (CoordinateHasRuntimeRailload(coordinate))
        {
            return true;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain != null
            && terrain.TryGetLoadedBlock(coordinate, out Block block)
            && block != null
            && IsRailloadAllowedForPlacement(
                block,
                GetOccupyingObjectForPlacement(block, previewToIgnore),
                InstallationMapFilter.Railload))
        {
            return true;
        }

        return TryGetSavedPlacementSnapshot(coordinate, out PlacementSnapshot savedSnapshot)
               && IsRailloadSource(savedSnapshot.mapObject);
    }

    private bool CoordinateHasRuntimeRailload(Vector2Int coordinate)
    {
        trainPlacementRailSearchScratch.Clear();
        InstallationObject.CollectActiveInstallationsAtRuntimeGridCoordinate(
            coordinate,
            trainPlacementRailSearchScratch);

        bool hasRail = false;
        for (int i = 0; i < trainPlacementRailSearchScratch.Count; i++)
        {
            if (trainPlacementRailSearchScratch[i] is Railload)
            {
                hasRail = true;
                break;
            }
        }

        trainPlacementRailSearchScratch.Clear();
        return hasRail;
    }

    private bool IsPipeAllowedForPlacement(
        Block block,
        MapObject occupyingObject,
        MapObject footprintSource,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        InstallationMapFilter allowedFilter)
    {
        if ((allowedFilter & InstallationMapFilter.Pipe) == 0
            || !TryGetPipePlacementAtBlock(block, occupyingObject, out Pipe pipe, out Quaternion pipeRotation))
        {
            return false;
        }

        if (!IsBelt2F(footprintSource))
        {
            return true;
        }

        return anchorCoordinate.HasValue
               && block != null
               && block.Coordinate == GetBelt2FBridgeCenterCoordinate(
                   anchorCoordinate.Value,
                   footprintSource,
                   quarterTurns)
               && IsBelt2FCrossingPipeDirectionAllowed(footprintSource, quarterTurns, pipe, pipeRotation);
    }

    private bool IsPipeAllowedForPlacement(
        Block block,
        MapObject occupyingObject,
        MapObject footprintSource,
        Vector2Int anchorCoordinate,
        InstallationMapFilter allowedFilter)
    {
        return IsPipeAllowedForPlacement(
            block,
            occupyingObject,
            footprintSource,
            anchorCoordinate,
            0,
            allowedFilter);
    }

    private bool IsPipeAllowedForAnyBelt2FPlacementRotation(
        Block block,
        MapObject occupyingObject,
        MapObject footprintSource,
        InstallationMapFilter allowedFilter)
    {
        if (!IsBelt2F(footprintSource) || block == null)
        {
            return IsPipeAllowedForPlacement(
                block,
                occupyingObject,
                footprintSource,
                block != null ? block.Coordinate : Vector2Int.zero,
                0,
                allowedFilter);
        }

        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        for (int i = 0; i < candidateCount; i++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(footprintSource, i);
            if (IsPipeAllowedForPlacement(
                    block,
                    occupyingObject,
                    footprintSource,
                    block.Coordinate,
                    candidateQuarterTurns,
                    allowedFilter))
            {
                return true;
            }
        }

        return false;
    }

    private bool TryGetPipePlacementAtBlock(
        Block block,
        MapObject occupyingObject,
        out Pipe pipe,
        out Quaternion pipeRotation)
    {
        pipe = null;
        pipeRotation = Quaternion.identity;

        if (block != null && block.MapObject is Pipe activePipe)
        {
            if (TryGetInstalledPipeVariantPreview(
                    activePipe,
                    out Pipe previewPipe,
                    out Quaternion previewRotation))
            {
                pipe = previewPipe;
                pipeRotation = previewRotation;
                return true;
            }

            pipe = activePipe;
            pipeRotation = activePipe.transform.rotation;
            return true;
        }

        if (block != null
            && TryGetSavedPipePlacementAtCoordinate(
                block.Coordinate,
                out Pipe savedPipe,
                out Quaternion savedRotation))
        {
            pipe = savedPipe;
            pipeRotation = savedRotation;
            return true;
        }

        if (occupyingObject is Pipe occupyingPipe)
        {
            if (TryGetInstalledPipeVariantPreview(
                    occupyingPipe,
                    out Pipe previewPipe,
                    out Quaternion previewRotation))
            {
                pipe = previewPipe;
                pipeRotation = previewRotation;
                return true;
            }

            pipe = occupyingPipe;
            pipeRotation = occupyingPipe.transform.rotation;
            return true;
        }

        return false;
    }

    private bool IsBelt2FCrossingPipeDirectionAllowed(
        MapObject footprintSource,
        int quarterTurns,
        Pipe pipe,
        Quaternion pipeRotation)
    {
        if (!(footprintSource is ConveyorBelt belt2F)
            || pipe == null)
        {
            return false;
        }

        Quaternion beltRotation = GetPlacementObjectRotation(footprintSource, quarterTurns);
        if (!belt2F.TryGetOutputDirection(beltRotation, out Vector2Int beltDirection)
            || beltDirection == Vector2Int.zero)
        {
            return false;
        }

        if (pipe.HasConnectionTowards(pipeRotation, beltDirection)
            || pipe.HasConnectionTowards(pipeRotation, -beltDirection))
        {
            return false;
        }

        Vector2Int crossingDirection = ConveyorBelt.RotateDirectionClockwise(beltDirection);
        return pipe.HasConnectionTowards(pipeRotation, crossingDirection)
               || pipe.HasConnectionTowards(pipeRotation, -crossingDirection);
    }

    private static bool IsRectGridAreaBlockType(InputOutputModule.RectGridBlockType blockType)
    {
        return InputOutputModule.IsInputOutputAreaBlockType(blockType);
    }

    private MapObject GetOccupyingObjectForPlacement(Block block, MapObject previewToIgnore = null)
    {
        if (block == null)
        {
            return null;
        }

        MapObject occupyingObject = GetBlockingMapObject(block);
        if (occupyingObject == previewToIgnore)
        {
            occupyingObject = null;
        }

        // A Floor can remain bound to the block while another installation owns the same
        // runtime coordinate (for example, an object placed over the floor through an area cell).
        // Prefer that non-floor installation so the Floor filter alone cannot treat the cell as empty.
        if (occupyingObject is Floor
            && TryGetRuntimeNonFloorInstallationOccupant(
                block.Coordinate,
                previewToIgnore,
                out InstallationObject runtimeOccupyingInstallation))
        {
            occupyingObject = runtimeOccupyingInstallation;
        }

        if (occupyingObject == null
            && TryGetSavedInstallationPlacementAtCoordinate(
                block.Coordinate,
                out MapObject savedOccupyingObject,
                out _,
                out BlockStateStore.InstallationSaveState savedState)
            && savedOccupyingObject != previewToIgnore
            && !SavedPlacementBelongsToIgnoredPreview(savedState, previewToIgnore))
        {
            occupyingObject = savedOccupyingObject;
        }

        return occupyingObject;
    }

    private static bool SavedPlacementBelongsToIgnoredPreview(
        BlockStateStore.InstallationSaveState savedState,
        MapObject previewToIgnore)
    {
        if (savedState == null
            || !(previewToIgnore is InstallationObject ignoredInstallation)
            || !ignoredInstallation.TryGetPlacementRuntime(
                out Vector2Int ignoredAnchorCoordinate,
                out _)
            || savedState.anchorCoordinate != ignoredAnchorCoordinate)
        {
            return false;
        }

        long ignoredPlacementSequence = ignoredInstallation.RuntimePlacementSequence;
        if (savedState.placementSequence > 0 && ignoredPlacementSequence > 0)
        {
            return savedState.placementSequence == ignoredPlacementSequence;
        }

        return savedState.itemId == ignoredInstallation.ResolveItemId();
    }

    private bool TryGetRuntimeNonFloorInstallationOccupant(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out InstallationObject occupyingInstallation)
    {
        occupyingInstallation = null;
        placementInstallationOccupantScratch.Clear();
        InstallationObject.CollectActiveInstallationsAtRuntimeGridCoordinate(
            coordinate,
            placementInstallationOccupantScratch);

        long occupyingPlacementSequence = long.MinValue;
        for (int i = 0; i < placementInstallationOccupantScratch.Count; i++)
        {
            InstallationObject candidate = placementInstallationOccupantScratch[i];
            if (candidate == null
                || candidate == previewToIgnore
                || candidate is Floor
                || installPreviewAnchorCoordinates.ContainsKey(candidate))
            {
                continue;
            }

            long placementSequence = candidate.RuntimePlacementSequence;
            if (occupyingInstallation == null || placementSequence > occupyingPlacementSequence)
            {
                occupyingInstallation = candidate;
                occupyingPlacementSequence = placementSequence;
            }
        }

        placementInstallationOccupantScratch.Clear();
        return occupyingInstallation != null;
    }

    private MapObject GetBlockingMapObject(Block block)
    {
        if (block == null)
        {
            return null;
        }

        MapObject occupyingObject = block.MapObject;
        if (occupyingObject == null)
        {
            return null;
        }

        if (!occupyingObject.gameObject.activeInHierarchy)
        {
            block.SetMapObject(null);
            return null;
        }

        if (occupyingObject is Resource resource && !resource.CanHarvest)
        {
            block.SetMapObject(null);
            return null;
        }

        return occupyingObject;
    }

    private Vector3 GetPreviewWorldPosition(Block anchorBlock, MapObject footprintSource, int quarterTurns)
    {
        Vector3 position = anchorBlock.transform.position;
        Vector2 positionOffset = GetPlacementWorldPositionOffset(footprintSource, quarterTurns);
        position.x += positionOffset.x;
        position.z += positionOffset.y;
        return position;
    }

    private Vector3 ResolvePlacementWorldPosition(
        Block anchorBlock,
        MapObject footprintSource,
        int quarterTurns,
        Vector3? railReferenceWorldPosition = null)
    {
        if (anchorBlock == null)
        {
            return Vector3.zero;
        }

        Vector3 position = GetPreviewWorldPosition(anchorBlock, footprintSource, quarterTurns);
        return ResolveRailAlignedPlacementWorldPosition(
            footprintSource,
            anchorBlock.Coordinate,
            quarterTurns,
            position,
            railReferenceWorldPosition);
    }

    private Vector3 ResolvePlacementWorldPosition(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        Vector3? railReferenceWorldPosition = null)
    {
        Vector3 position = GetPlacementWorldPositionFromAnchorCoordinate(
            anchorCoordinate,
            footprintSource,
            quarterTurns);
        return ResolveRailAlignedPlacementWorldPosition(
            footprintSource,
            anchorCoordinate,
            quarterTurns,
            position,
            railReferenceWorldPosition);
    }

    private Vector3 ResolveRailAlignedPlacementWorldPosition(
        MapObject sourcePrefab,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        Vector3 fallbackPosition,
        Vector3? railReferenceWorldPosition)
    {
        Vector3 referencePosition = railReferenceWorldPosition ?? fallbackPosition;
        if (TryResolveTrainRailPlacementPose(
                sourcePrefab,
                anchorCoordinate,
                quarterTurns,
                referencePosition,
                out Vector3 trainPosition,
                out _))
        {
            return trainPosition;
        }

        if (!IsTrainSource(sourcePrefab)
            || !TryFindNearestRailPathAtCoordinate(
                anchorCoordinate,
                new Vector2(referencePosition.x, referencePosition.z),
                out _,
                out Vector2 railPoint,
                out _,
                out float railSqrDistance)
            || railSqrDistance > ResolveRailAlignedPlacementMaxSqrDistance())
        {
            return fallbackPosition;
        }

        Vector2 positionOffset = GetPlacementWorldPositionOffset(sourcePrefab, quarterTurns);
        fallbackPosition.x = railPoint.x + positionOffset.x;
        fallbackPosition.z = railPoint.y + positionOffset.y;
        return fallbackPosition;
    }

    private bool TryResolveTrainRailPlacementPose(
        MapObject sourcePrefab,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        Vector3 referencePosition,
        out Vector3 position,
        out Quaternion rotation)
    {
        return TryResolveTrainRailPlacementPose(
            sourcePrefab,
            anchorCoordinate,
            quarterTurns,
            referencePosition,
            out position,
            out rotation,
            out _);
    }

    private bool TryResolveTrainRailPlacementPose(
        MapObject sourcePrefab,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        Vector3 referencePosition,
        out Vector3 position,
        out Quaternion rotation,
        out TrainPlacementRailSample railSample)
    {
        position = referencePosition;
        rotation = sourcePrefab != null ? sourcePrefab.transform.rotation : Quaternion.identity;
        railSample = default;
        railSample.SqrDistance = float.MaxValue;
        Train train = ResolveTrainSource(sourcePrefab);
        if (train == null)
        {
            return false;
        }

        Quaternion baseRotation = sourcePrefab != null
            ? sourcePrefab.transform.rotation
            : Quaternion.identity;
        Vector2 referencePoint = new Vector2(referencePosition.x, referencePosition.z);
        int searchCells = Mathf.CeilToInt(Mathf.Max(1f, TrainPlacementRailSearchRadius));
        if (!TryFindNearestTrainPlacementRailSampleAroundCoordinate(
                anchorCoordinate,
                referencePoint,
                searchCells,
                out railSample))
        {
            return false;
        }

        float maxRailDistance = RailAlignedPlacementMaxDistance;
        if (railSample.SqrDistance > maxRailDistance * maxRailDistance)
        {
            return false;
        }

        Vector3 railForward = FlattenHorizontalDirection(new Vector3(railSample.Tangent.x, 0f, railSample.Tangent.y));
        if (railForward.sqrMagnitude <= 0.0001f)
        {
            return false;
        }

        Quaternion preferredRotation = GetPlacementObjectRotation(baseRotation, sourcePrefab, quarterTurns);
        Vector3 preferredForward = FlattenHorizontalDirection(preferredRotation * Vector3.forward);
        if (preferredForward.sqrMagnitude > 0.0001f
            && Vector3.Dot(railForward, preferredForward) < 0f)
        {
            railForward = -railForward;
        }

        Vector2 positionOffset = GetPlacementWorldPositionOffset(sourcePrefab, quarterTurns);
        position.x = railSample.Point.x + positionOffset.x;
        position.z = railSample.Point.y + positionOffset.y;
        rotation = AlignBaseRotationForwardToDirection(baseRotation, railForward);
        return true;
    }

    private Vector3 GetPlacementWorldPositionFromAnchorCoordinate(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns)
    {
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        float baseHeight = terrain != null ? terrain.transform.position.y : 0f;
        Vector3 position = new Vector3(anchorCoordinate.x, baseHeight, anchorCoordinate.y);
        if (terrain != null && terrain.TryGetLoadedBlock(anchorCoordinate, out Block anchorBlock) && anchorBlock != null)
        {
            position = anchorBlock.transform.position;
        }

        Vector2 positionOffset = GetPlacementWorldPositionOffset(footprintSource, quarterTurns);
        position.x += positionOffset.x;
        position.z += positionOffset.y;
        return position;
    }

    private Vector2 GetPlacementWorldPositionOffset(MapObject footprintSource, int quarterTurns)
    {
        if (ShouldUseAnchorCellWorldPosition(footprintSource))
        {
            return Vector2.zero;
        }

        List<Vector2Int> offsets = GetPlacementVisualLocalOffsets(footprintSource, quarterTurns);
        if (offsets.Count <= 0)
        {
            return Vector2.zero;
        }

        Vector2 averageOffset = Vector2.zero;
        for (int i = 0; i < offsets.Count; i++)
        {
            averageOffset += offsets[i];
        }

        return averageOffset / offsets.Count;
    }

    private static bool ShouldUseAnchorCellWorldPosition(MapObject footprintSource)
    {
        // SteamGenerator placement uses one RectGrid Object cell as the user-visible
        // Center. Using the average of its two body cells puts the preview on the grid
        // line between them after rotation.
        return IsSteamGeneratorSource(footprintSource);
    }

    private List<Vector2Int> GetPlacementVisualLocalOffsets(MapObject footprintSource, int quarterTurns)
    {
        if (ShouldUseMapSizeFootprint(footprintSource))
        {
            return GetMapSizeFootprintLocalOffsets(footprintSource, quarterTurns);
        }

        if (TryGetRectGridObjectLocalOffsets(footprintSource, quarterTurns, out List<Vector2Int> objectOffsets)
            && objectOffsets.Count > 0)
        {
            return objectOffsets;
        }

        return GetFootprintLocalOffsets(footprintSource, quarterTurns);
    }

    private bool TryGetRectGridObjectLocalOffsets(MapObject footprintSource, int quarterTurns, out List<Vector2Int> objectOffsets)
    {
        objectOffsets = null;
        return TryGetRectGridBlockLocalOffsets(
            footprintSource,
            quarterTurns,
            InputOutputModule.RectGridBlockType.Object,
            out objectOffsets);
    }

    private bool IsPreviewObjectCell(MapObject preview, Block block)
    {
        if (preview == null || block == null || !TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate))
        {
            return false;
        }

        if (preview is UndergroundPipe undergroundPipe
            && undergroundPipe.TryGetPreviewCandidateCoordinates(
                out Vector2Int firstEndpoint,
                out Vector2Int secondEndpoint))
        {
            return block.Coordinate == firstEndpoint || block.Coordinate == secondEndpoint;
        }

        List<Vector2Int> visualCoordinates = GetPlacementVisualCoordinates(
            anchorCoordinate,
            ResolveInstallPreviewPlacementSource(preview),
            GetPreviewAreaQuarterTurns(preview));
        for (int i = 0; i < visualCoordinates.Count; i++)
        {
            if (visualCoordinates[i] == block.Coordinate)
            {
                return true;
            }
        }

        return false;
    }

    private List<Vector2Int> GetPlacementVisualCoordinates(Vector2Int anchorCoordinate, MapObject footprintSource, int quarterTurns)
    {
        List<Vector2Int> offsets = GetPlacementVisualLocalOffsets(footprintSource, quarterTurns);
        List<Vector2Int> coordinates = new List<Vector2Int>(offsets.Count);
        for (int i = 0; i < offsets.Count; i++)
        {
            coordinates.Add(anchorCoordinate + offsets[i]);
        }

        return coordinates;
    }

    private void RegisterInstalledObjectPersistence(MapObject installedObject)
    {
        if (!(installedObject is InstallationObject installationObject))
        {
            return;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        terrain?.RegisterLiveInstallationObject(installationObject);
    }

    private MapObject CreateInstalledObjectInstance(MapObject sourcePrefab, Transform parent, TerrainGenerator terrain)
    {
        if (sourcePrefab == null)
        {
            return null;
        }

        InstallationObject pooledObject = terrain != null
            ? terrain.CreateInstallationObject(sourcePrefab, parent)
            : null;
        return pooledObject != null ? pooledObject : Instantiate(sourcePrefab, parent);
    }

    private void ReleaseInstalledObjectInstance(InstallationObject installationObject, MapObject sourcePrefab, TerrainGenerator terrain)
    {
        if (installationObject == null)
        {
            return;
        }

        if (installationObject is Wall installedFence)
        {
            RemoveInstalledFenceVariantPreview(installedFence);
        }

        if (installationObject is Pipe installedPipe)
        {
            RemoveInstalledPipeVariantPreview(installedPipe);
        }

        if (terrain != null)
        {
            terrain.ReleaseInstallationObject(installationObject, sourcePrefab);
            return;
        }

        if (Application.isPlaying)
        {
            Destroy(installationObject.gameObject);
        }
        else
        {
            DestroyImmediate(installationObject.gameObject);
        }
    }

    private static MapObject ResolveInstallationSourcePrefab(ItemDefinition definition, int conveyorVariantKind)
    {
        MapObject sourcePrefab = definition != null ? definition.mapObject : null;
        if (sourcePrefab is Wall fencePrototype && conveyorVariantKind >= 0)
        {
            sourcePrefab = ResolveFenceVariantPrefab(fencePrototype, conveyorVariantKind)
                ?? sourcePrefab;
        }
        else if (sourcePrefab is Pipe pipePrototype && conveyorVariantKind >= 0)
        {
            sourcePrefab = ResolvePipeVariantPrefab(pipePrototype, conveyorVariantKind)
                ?? sourcePrefab;
        }
        else if (!IsBelt2F(sourcePrefab) && sourcePrefab is ConveyorBelt conveyorPrototype && conveyorVariantKind >= 0)
        {
            sourcePrefab = ResolveConveyorVariantPrefab(conveyorPrototype, conveyorVariantKind)
                ?? sourcePrefab;
        }

        return sourcePrefab;
    }

    private void PlayInstallPlacementAnimation(MapObject installedObject, PortableObject sourcePortableObject, int itemId, float delay)
    {
        if (installedObject == null)
        {
            return;
        }

        Transform installedTransform = installedObject.transform;
        Vector3 originalScale = installedTransform.localScale;
        SetConveyorBeltVirtualRendering(installedObject, false);
        installedTransform.DOKill();
        installedTransform.localScale = Vector3.zero;
        List<RendererVisibilityState> rendererStates = CaptureAndHideRendererVisibility(installedObject);

        if (sourcePortableObject == null || itemId < 0)
        {
            RevealInstalledObjectAfterPlacement(installedObject, installedTransform, originalScale, rendererStates, delay);
            return;
        }

        PortableObject movingPortableObject = Instantiate(
            sourcePortableObject,
            sourcePortableObject.transform.position,
            sourcePortableObject.transform.rotation);
        if (movingPortableObject == null)
        {
            RevealInstalledObjectAfterPlacement(installedObject, installedTransform, originalScale, rendererStates, delay);
            return;
        }

        movingPortableObject.name = $"{sourcePortableObject.name}_InstallMove";
        movingPortableObject.transform.SetParent(null, true);
        movingPortableObject.transform.position = sourcePortableObject.transform.position;
        movingPortableObject.transform.localScale = sourcePortableObject.transform.lossyScale;
        if (!movingPortableObject.gameObject.activeSelf)
        {
            movingPortableObject.gameObject.SetActive(true);
        }

        if (!movingPortableObject.SetItem(itemId))
        {
            Destroy(movingPortableObject.gameObject);
            RevealInstalledObjectAfterPlacement(installedObject, installedTransform, originalScale, rendererStates, delay);
            return;
        }

        Vector3 startPosition = sourcePortableObject.transform.position;
        Vector3 targetPosition = installedTransform != null ? installedTransform.position : movingPortableObject.transform.position;
        movingPortableObject.MoveTo(
            () => installedTransform != null ? installedTransform.position : targetPosition,
            Mathf.Max(0f, delay),
            () => sourcePortableObject != null ? sourcePortableObject.transform.position : startPosition,
            () =>
            {
                if (movingPortableObject != null)
                {
                    Destroy(movingPortableObject.gameObject);
                }

                if (installedObject != null && installedTransform != null)
                {
                    RevealInstalledObjectAfterPlacement(installedObject, installedTransform, originalScale, rendererStates, 0f);
                }
            },
            false);
    }

    private void RevealInstalledObjectAfterPlacement(
        MapObject installedObject,
        Transform installedTransform,
        Vector3 originalScale,
        List<RendererVisibilityState> rendererStates,
        float delay)
    {
        if (installedObject == null || installedTransform == null)
        {
            return;
        }

        RestoreRendererVisibility(rendererStates);

        bool restoredVirtualRendering = false;
        TweenCallback restoreVirtualRendering = () =>
        {
            if (restoredVirtualRendering || installedObject == null)
            {
                return;
            }

            restoredVirtualRendering = true;
            SetConveyorBeltVirtualRendering(installedObject, true);
            if (installedObject is UtilityPole)
            {
                UtilityPole.RefreshPoleTopologyNow();
            }
        };

        Tween revealTween = installedTransform
            .DOScale(originalScale, installPlacementScaleDuration)
            .SetDelay(Mathf.Max(0f, delay))
            .SetEase(installPlacementScaleEase)
            .SetLink(installedObject.gameObject);
        revealTween.OnComplete(restoreVirtualRendering);
        revealTween.OnKill(restoreVirtualRendering);
    }

    private static void SetConveyorBeltVirtualRendering(MapObject installedObject, bool isEnabled)
    {
        if (installedObject is ConveyorBelt conveyorBelt)
        {
            conveyorBelt.SetVirtualRuntimeRenderingEnabled(isEnabled);
        }
    }

    private void PlayInstallationEditCompleteAnimation(MapObject restoredObject, InstallationEditSession editSession)
    {
        if (restoredObject == null)
        {
            return;
        }

        int itemId = editSession?.definition != null
            ? editSession.definition.id
            : restoredObject.ResolveItemId();
        PortableObject sourcePortableObject = null;
        List<PortableObject> handPortableSources = GetPlayerHandPortableSources(itemId, 1);
        if (handPortableSources.Count > 0)
        {
            sourcePortableObject = handPortableSources[0];
        }

        PlayInstallPlacementAnimation(restoredObject, sourcePortableObject, itemId, 0f);
    }

    private bool TryGetPrimaryPointerPosition(out Vector2 pointerPosition)
    {
        pointerPosition = Vector2.zero;

        if (Input.touchCount > 0)
        {
            pointerPosition = Input.GetTouch(0).position;
            return true;
        }

        pointerPosition = Input.mousePosition;
        return true;
    }

    private bool IsPrimaryPointerHeld()
    {
        if (Input.touchCount > 0)
        {
            Touch touch = Input.GetTouch(0);
            return touch.phase != TouchPhase.Ended && touch.phase != TouchPhase.Canceled;
        }

        return Input.GetMouseButton(0);
    }

    public bool IsPlacementPointerOverBlockingUi(Vector2 pointerPosition)
    {
        return IsPointerOverBlockingUi(pointerPosition);
    }

    private bool IsPointerOverBlockingUi(Vector2 pointerPosition)
    {
        EventSystem currentEventSystem = EventSystem.current;
        if (currentEventSystem == null)
        {
            return false;
        }

        if (pointerRaycastEventData == null || pointerRaycastEventSystem != currentEventSystem)
        {
            pointerRaycastEventSystem = currentEventSystem;
            pointerRaycastEventData = new PointerEventData(currentEventSystem);
        }

        pointerRaycastEventData.Reset();
        pointerRaycastEventData.position = pointerPosition;
        pointerRaycastResults.Clear();
        currentEventSystem.RaycastAll(pointerRaycastEventData, pointerRaycastResults);
        for (int i = 0; i < pointerRaycastResults.Count; i++)
        {
            GameObject hitObject = pointerRaycastResults[i].gameObject;
            if (IsBlockingButtonObject(hitObject))
            {
                return true;
            }
        }

        return false;
    }

    private static bool IsBlockingButtonObject(GameObject targetObject)
    {
        if (targetObject == null)
        {
            return false;
        }

        return targetObject.GetComponentInParent<Button>() != null;
    }

    private void ClearInstallPreview()
    {
        InvalidateInstallPreviewMoveCache();
        ClearHandcartConnectionPreviewHandleOverrides();
        railloadInstallationController?.Cancel();
        RefundAllInstallPreviewReservations();
        ClearInstalledTrainConnectionTints();
        trainConnectionPreviewTints.Clear();
        RemoveInstalledFenceVariantPreviews(null);
        RemoveInstalledPipeVariantPreviews(null);
        UtilityPole.ClearBlueprintPreviews();
        activeInstallDefinition = null;
        activeInstallBaseRotation = Quaternion.identity;
        waitForPointerReleaseAfterPreviewSpawn = false;
        installPreviewQuarterTurns = 0;
        installPreviewConveyorVariantMode = ConveyorPreviewVariantMode.Straight;
        ResetPreviewPointerTracking();
        ResetInstallPreviewVisualSyncState();
        GameManager.Instance?.SetInstallationPlacementActive(false);
        RefreshPlayerHandInstallItemState();
        if (IsInstallGridModeActive())
        {
            InvalidateInstallGrid();
            SetInstallGridVisible(true);
        }
        else
        {
            SetInstallGridVisible(false);
            ResetInstallGridRefreshState();
        }

        CleanupInstallPreviewReferences();
        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            MapObject preview = installPreviewInstances[i];
            if (preview == null)
            {
                continue;
            }

            DestroyInstallPreviewObject(preview);
        }

        installPreviewInstances.Clear();
        installPreviewQuarterTurnsByPreview.Clear();
        installPreviewFenceDoorStandaloneQuarterTurnsByPreview.Clear();
        installPreviewBaseRotationsByPreview.Clear();
        installPreviewAnchorCoordinates.Clear();
        installPreviewSourcePrefabsByPreview.Clear();
        installPreviewRailReferenceWorldPositions.Clear();
        installPreviewPlacementSequencesByPreview.Clear();
        installPreviewConveyorRotationSequenceIndexesByPreview.Clear();
        installPreviewPipeConnectionMasksByPreview.Clear();
        installPreviewPipeSelectedSetDirectionsByPreview.Clear();
        installPreviewFreightCarBoxTargets.Clear();
        installPreviewFreightCarBoxPoints.Clear();
        installPreviewItemReservationsByPreview.Clear();
        straightFirstConveyorPreviews.Clear();
        activeInstallPreview = null;
        RefreshInstallOrEditWorkableRangeVisualRequest();
    }

    private void SetInstallButtonVisible(bool isVisible)
    {
        if (installButton == null)
        {
            return;
        }

        if (installButton.gameObject.activeSelf != isVisible)
        {
            installButton.gameObject.SetActive(isVisible);
        }

        installButton.interactable = isVisible;
    }
}
